window.BOOK={"key":"dalil","app":"mutoon","lsk":"mutoon_dalil_v1","title":"دليل الطالب","unitWord":"فقرة","sub":"الفقه الحنبلي: دليل الطالب لنيل المطالب · مرعي بن يوسف الكرمي (ت ١٠٣٣هـ) · ١٥٤ بابًا","source":"دليل الطالب لنيل المطالب: ت. أبي قتيبة نظر محمد الفاريابي (دار طيبة ١٤٢٥هـ) = https://shamela.ws/book/11196، مقابلًا بطبعة المكتب الإسلامي (١٣٨٩هـ) = https://ketabonline.com/ar/books/10785 وبالمتن في «نيل المآرب» ت. الأشقر (مكتبة الفلاح ١٤٠٣هـ) = https://shamela.ws/book/96876 · قوبل بـ: قوبلت النسخ الثلاث كلمةً كلمةً بسكربت، وأُخذ في كل خلاف ما اتفق عليه اثنان منها، والشكل الجزئي من متن «نيل المآرب» — انظر dalil-sources.md","note":"لفظ تحقيق الفاريابي مقابَلًا كلمةً كلمةً بسكربت على طبعة المكتب الإسلامي وعلى المتن داخل «نيل المآرب» (ت. الأشقر)، ويؤخذ في كل خلاف ما اتفق عليه اثنان منها، وكل ذلك في تقرير المصادر. ولا توجد للمتن نسخة رقمية مشكولة، فالشكل الجزئي (نحو ثلث الكلمات) منقول من «نيل المآرب»، والباقي يحتاج إلى تشكيل. ولا توجد نسخة رقمية مشكولة كاملة، فأكمل الذكاء الاصطناعي الحركات (نحو ٦٠٪)، وصُحّحت ألفاظ بشهادة الطبعات (في تقرير المصادر). فإذا شككت بحركة فراجع شيخك.","chapters":[{"id":"da1","title":"مُقَدِّمَةُ الْمُصَنِّفِ","units":[{"id":"da1_1","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ١","segs":[["matn","الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ مَالِكِ يَوْمِ الدِّينِ."]]},{"id":"da1_2","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٢","segs":[["matn","وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ الْمُبَيِّنُ لِأَحْكَامِ شَرَائِعِ الدِّينِ الْفَائِزُ بِمُنْتَهَى الْإِرَادَاتِ مِنْ رَبِّهِ فَمَنْ تَمَسَّكَ بِشَرِيعَتِهِ فَهُوَ مِنَ الْفَائِزِينَ صَلَّى اللَّهُ وَسَلَّمَ عَلَيْهِ وَعَلَى جَمِيعِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ وَعَلَى آلِ كُلٍّ وَصَحْبِهِ أَجْمَعِينَ."]]},{"id":"da1_3","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٣","segs":[["matn","وَبَعْدُ: فَهَذَا مُخْتَصَرٌ فِي الْفِقْهِ عَلَى الْمَذْهَبِ الْأَحْمَدِ مَذْهَبِ الْإِمَامِ أَحْمَدَ بَالَغْتُ فِي إِيضَاحِهِ رَجَاءَ الْغُفْرَانِ وَبَيَّنْتُ فِيهِ الْأَحْكَامَ أَحْسَنَ بَيَانٍ لَمْ أَذْكُرْ فِيهِ إِلَّا مَا جَزَمَ بِصِحَّتِهِ أَهْلُ التَّصْحِيحِ"]]},{"id":"da1_4","label":"مُقَدِّمَةُ الْمُصَنِّفِ · ٤","segs":[["matn","وَالْعِرْفَانِ وَعَلَيْهِ الْفَتْوَى فِيمَا بَيْنَ أَهْلِ التَّرْجِيحِ وَالْإِتْقَانِ وَسَمَّيْتُهُ بِدَلِيلِ الطَّالِبِ لِنَيْلِ الْمَطَالِبِ وَاللَّهَ أَسْأَلُ أَنْ يَنْفَعَ بِهِ مَنِ اشْتَغَلَ بِهِ مِنَ الْمُسْلِمِينَ وَأَنْ يَرْحَمَنِي وَالْمُسْلِمِينَ إِنَّهُ أَرْحَمُ الرَّاحِمِينَ."]]}],"group":"مُقَدِّمَةُ الْمُصَنِّفِ"},{"id":"da2","title":"كِتَابُ الطَّهَارَةِ","units":[{"id":"da2_1","label":"كِتَابُ الطَّهَارَةِ · ١","segs":[["matn","وَهِيَ: رَفْعُ الْحَدَثِ وَزَوَالُ الْخَبَثِ. وَأَقْسَامُ الْمَاءِ ثَلَاثَةٌ: أَحَدُهَا: طَهُورٌ وَهُوَ الْبَاقِي عَلَى خِلْقَتِهِ يَرْفَعُ الْحَدَثَ وَيُزِيلُ الْخَبَثَ."]]},{"id":"da2_2","label":"كِتَابُ الطَّهَارَةِ · ٢","segs":[["matn","وَهُوَ أَرْبَعَةُ أَنْوَاعٍ: مَاءٌ يَحْرُمُ اسْتِعْمَالُهُ وَلَا يَرْفَعُ الْحَدَثَ وَيُزِيلُ الْخَبَثَ وَهُوَ مَا لَيْسَ مُبَاحًا."]]},{"id":"da2_3","label":"كِتَابُ الطَّهَارَةِ · ٣","segs":[["matn","وَمَاءٌ يَرْفَعُ حَدَثَ الْأُنْثَى لَا الرَّجُلِ الْبَالِغِ وَالْخُنْثَى وَهُوَ مَا خَلَتْ بِهِ الْمَرْأَةُ الْمُكَلَّفَةُ لِطَهَارَةٍ كَامِلَةٍ عَنْ حَدَثٍ."]]},{"id":"da2_4","label":"كِتَابُ الطَّهَارَةِ · ٤","segs":[["matn","وَمَاءٌ يُكْرَهُ اسْتِعْمَالُهُ مَعَ عَدَمِ الِاحْتِيَاجِ إِلَيْهِ وَهُوَ مَاءُ بِئْرٍ بِمَقْبَرَةٍ وَمَاءٌ اشْتَدَّ حَرُّهُ أَوْ بَرْدُهُ أَوْ سُخِّنَ بِنَجَاسَةٍ أَوْ سُخِّنَ بِمَغْصُوبٍ أَوِ اسْتُعْمِلَ فِي طَهَارَةٍ لَمْ تَجِبْ أَوْ"]]},{"id":"da2_5","label":"كِتَابُ الطَّهَارَةِ · ٥","segs":[["matn","فِي غُسْلِ كَافِرٍ أَوْ تَغَيَّرَ بِمِلْحٍ مَائِيٍّ أَوْ بِمَا لَا يُمَازِجُهُ كَتَغَيُّرِهِ بِالْعُودِ الْقَمَارِيِّ وَقِطَعِ الْكَافُورِ وَالدُّهْنِ وَلَا يُكْرَهُ مَاءُ زَمْزَمَ إِلَّا فِي إِزَالَةِ الْخَبَثِ."]]},{"id":"da2_6","label":"كِتَابُ الطَّهَارَةِ · ٦","segs":[["matn","وَمَاءٌ لَا يُكْرَهُ اسْتِعْمَالُهُ كَمَاءِ الْبَحْرِ وَالْآبَارِ وَالْعُيُونِ وَالْأَنْهَارِ وَالْحَمَّامِ وَلَا يُكْرَهُ الْمُسَخَّنُ بِالشَّمْسِ وَالْمُتَغَيِّرُ بِطُولِ الْمُكْثِ أَوْ بِالرِّيحِ مِنْ نَحْوِ مَيْتَةٍ أَوْ بِمَا يَشُقُّ صَوْنُ الْمَاءِ عَنْهُ كَطُحْلُبٍ وَوَرَقِ شَجَرٍ مَا لَمْ يُوضَعَا."]]},{"id":"da2_7","label":"كِتَابُ الطَّهَارَةِ · ٧","segs":[["matn","الثَّانِي: طَاهِرٌ يَجُوزُ اسْتِعْمَالُهُ فِي غَيْرِ رَفْعِ الْحَدَثِ وَزَوَالِ الْخَبَثِ وَهُوَ مَا تَغَيَّرَ كَثِيرٌ مِنْ لَوْنِهِ أَوْ طَعْمِهِ أَوْ رِيحِهِ بِشَيْءٍ طَاهِرٍ فَإِنْ زَالَ تَغَيُّرُهُ بِنَفْسِهِ عَادَ إِلَى طَهُورِيَّتِهِ."]]},{"id":"da2_8","label":"كِتَابُ الطَّهَارَةِ · ٨","segs":[["matn","وَمِنَ الطَّاهِرِ: مَا كَانَ قَلِيلًا وَاسْتُعْمِلَ فِي رَفْعِ حَدَثٍ أَوِ انْغَمَسَتْ فِيهِ كُلُّ يَدِ الْمُسْلِمِ الْمُكَلَّفِ النَّائِمِ لَيْلًا نَوْمًا يَنْقُضُ الْوُضُوءَ قَبْلَ غَسْلِهَا ثَلَاثًا بِنِيَّةٍ وَتَسْمِيَةٍ وَذَلِكَ وَاجِبٌ."]]},{"id":"da2_9","label":"كِتَابُ الطَّهَارَةِ · ٩","segs":[["matn","الثَّالِثُ: نَجِسٌ يَحْرُمُ اسْتِعْمَالُهُ إِلَّا لِضَرُورَةٍ وَلَا يَرْفَعُ الْحَدَثَ وَلَا يُزِيلُ الْخَبَثَ وَهُوَ مَا وَقَعَتْ فِيهِ نَجَاسَةٌ وَهُوَ قَلِيلٌ أَوْ كَانَ كَثِيرًا وَتَغَيَّرَ بِهَا أَحَدُ أَوْصَافِهِ."]]},{"id":"da2_10","label":"كِتَابُ الطَّهَارَةِ · ١٠","segs":[["matn","فَإِنْ زَالَ تَغَيُّرُهُ بِنَفْسِهِ أَوْ بِإِضَافَةِ طَهُورٍ إِلَيْهِ أَوْ بِنَزْحٍ مِنْهُ وَيَبْقَى بَعْدَهُ كَثِيرٌ طَهُرَ وَالْكَثِيرُ قُلَّتَانِ تَقْرِيبًا وَالْيَسِيرُ مَا دُونَهُمَا وَهُمَا خَمْسُمِائَةِ رِطْلٍ بِالْعِرَاقِيِّ وَثَمَانُونَ رِطْلًا وَسُبُعَانِ وَنِصْفُ سُبُعِ رِطْلٍ بِالْقُدْسِيِّ وَمِسَاحَتُهُمَا ذِرَاعٌ وَرُبُعٌ طُولًا وَعَرْضًا وَعُمْقًا."]]},{"id":"da2_11","label":"كِتَابُ الطَّهَارَةِ · ١١","segs":[["matn","فَإِذَا كَانَ الْمَاءُ الطَّهُورُ كَثِيرًا وَلَمْ يَتَغَيَّرْ بِالنَّجَاسَةِ فَهُوَ طَهُورٌ وَلَوْ مَعَ بَقَائِهَا فِيهِ وَإِنْ شَكَّ فِي كَثْرَتِهِ فَهُوَ نَجِسٌ."]]},{"id":"da2_12","label":"كِتَابُ الطَّهَارَةِ · ١٢","segs":[["matn","وَإِنِ اشْتَبَهَ مَا تَجُوزُ بِهِ الطَّهَارَةُ بِمَا لَا تَجُوزُ بِهِ الطَّهَارَةُ لَمْ يَتَحَرَّ وَيَتَيَمَّمُ بِلَا إِرَاقَةٍ. وَيَلْزَمُ مَنْ عَلِمَ بِنَجَاسَةِ شَيْءٍ إِعْلَامُ مَنْ أَرَادَ أَنْ يَسْتَعْمِلَهُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da3","title":"بَابُ الْآنِيَةِ","units":[{"id":"da3_1","label":"بَابُ الْآنِيَةِ · ١","segs":[["matn","يُبَاحُ اتِّخَاذُ كُلِّ إِنَاءٍ طَاهِرٍ وَاسْتِعْمَالُهُ وَلَوْ ثَمِينًا إِلَّا آنِيَةَ الذَّهَبِ وَالْفِضَّةِ وَالْمُمَوَّهِ بِهِمَا. وَتَصِحُّ الطَّهَارَةُ بِهِمَا وَبِالْإِنَاءِ الْمَغْصُوبِ. وَيُبَاحُ إِنَاءٌ ضُبِّبَ بِضَبَّةٍ يَسِيرَةٍ مِنَ الْفِضَّةِ لِغَيْرِ زِينَةٍ."]]},{"id":"da3_2","label":"بَابُ الْآنِيَةِ · ٢","segs":[["matn","وَآنِيَةُ الْكُفَّارِ وَثِيَابُهُمْ طَاهِرَةٌ. وَلَا يَنْجُسُ شَيْءٌ بِالشَّكِّ مَا لَمْ تُعْلَمْ نَجَاسَتُهُ. وَعَظْمُ الْمَيْتَةِ وَقَرْنُهَا وَظُفُرُهَا وَحَافِرُهَا وَعَصَبُهَا وَجِلْدُهَا نَجِسٌ وَلَا يَطْهُرُ بِالدِّبَاغِ."]]},{"id":"da3_3","label":"بَابُ الْآنِيَةِ · ٣","segs":[["matn","وَالشَّعْرُ وَالصُّوفُ وَالرِّيشُ طَاهِرٌ إِذَا كَانَ مِنْ مَيْتَةٍ طَاهِرَةٍ فِي الْحَيَاةِ وَلَوْ كَانَتْ غَيْرَ مَأْكُولَةٍ كَالْهِرِّ وَالْفَأْرِ. وَيُسَنُّ تَغْطِيَةُ الْآنِيَةِ وَإِيكَاءُ الْأَسْقِيَةِ"]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da4","title":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي","units":[{"id":"da4_1","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ١","segs":[["matn","الِاسْتِنْجَاءُ هُوَ إِزَالَةُ مَا خَرَجَ مِنَ السَّبِيلَيْنِ بِمَاءٍ طَهُورٍ أَوْ حَجَرٍ طَاهِرٍ مُبَاحٍ مُنَقٍّ."]]},{"id":"da4_2","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٢","segs":[["matn","فَالْإِنْقَاءُ بِالْحَجَرِ وَنَحْوِهِ أَنْ يَبْقَى أَثَرٌ لَا يُزِيلُهُ إِلَّا الْمَاءُ وَلَا يُجْزِئُ أَقَلُّ مِنْ ثَلَاثِ مَسَحَاتٍ تَعُمُّ كُلُّ مَسْحَةٍ الْمَحَلَّ. وَالْإِنْقَاءُ بِالْمَاءِ عَوْدُ خُشُونَةِ الْمَحَلِّ كَمَا كَانَ وَظَنُّهُ كَافٍ."]]},{"id":"da4_3","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٣","segs":[["matn","وَيُسَنُّ الِاسْتِنْجَاءُ بِالْحَجَرِ ثُمَّ بِالْمَاءِ فَإِنْ عَكَسَ كُرِهَ وَيُجْزِئُ أَحَدُهُمَا وَالْمَاءُ أَفْضَلُ. وَيُكْرَهُ اسْتِقْبَالُ الْقِبْلَةِ وَاسْتِدْبَارُهَا فِي الِاسْتِنْجَاءِ."]]},{"id":"da4_4","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٤","segs":[["matn","وَيَحْرُمُ بِرَوْثٍ وَعَظْمٍ وَطَعَامٍ وَلَوْ لِبَهِيمَةٍ فَإِنْ فَعَلَ لَمْ يُجْزِئْهُ بَعْدَ ذَلِكَ إِلَّا الْمَاءُ كَمَا لَوْ تَعَدَّى الْخَارِجُ مَوْضِعَ الْعَادَةِ."]]},{"id":"da4_5","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٥","segs":[["matn","وَيَجِبُ الِاسْتِنْجَاءُ لِكُلِّ خَارِجٍ إِلَّا الطَّاهِرَ وَالنَّجِسَ الَّذِي لَمْ يُلَوِّثِ الْمَحَلَّ."]]},{"id":"da4_6","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٦","segs":[["matn","فَصْلٌ: يُسَنُّ لِدَاخِلِ الْخَلَاءِ تَقْدِيمُ الْيُسْرَى وَقَوْلُ: بِسْمِ اللَّهِ أَعُوذُ بِاللَّهِ مِنَ الْخُبُثِ وَالْخَبَائِثِ."]]},{"id":"da4_7","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٧","segs":[["matn","وَإِذَا خَرَجَ قَدَّمَ الْيُمْنَى وَقَالَ: غُفْرَانَكَ الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى وَعَافَانِي وَيُكْرَهُ فِي حَالِ التَّخَلِّي اسْتِقْبَالُ الشَّمْسِ وَالْقَمَرِ وَمَهَبِّ الرِّيحِ وَالْكَلَامُ وَالْبَوْلُ فِي إِنَاءٍ وَشَقٍّ وَنَارٍ وَرَمَادٍ وَلَا يُكْرَهُ الْبَوْلُ."]]},{"id":"da4_8","label":"بَابُ الِاسْتِنْجَاءِ وَآدَابِ التَّخَلِّي · ٨","segs":[["matn","قَائِمًا وَيَحْرُمُ اسْتِقْبَالُ الْقِبْلَةِ وَاسْتِدْبَارُهَا فِي الصَّحْرَاءِ بِلَا حَائِلٍ وَيَكْفِي إِرْخَاءُ ذَيْلِهِ. وَأَنْ يَبُولَ أَوْ يَتَغَوَّطَ بِطَرِيقٍ مَسْلُوكٍ وَظِلٍّ نَافِعٍ وَتَحْتَ شَجَرَةٍ عَلَيْهَا ثَمَرٌ يُقْصَدُ وَبَيْنَ قُبُورِ الْمُسْلِمِينَ. وَأَنْ يَلْبَثَ فَوْقَ قَدْرِ حَاجَتِهِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da5","title":"بَابُ السِّوَاكِ","units":[{"id":"da5_1","label":"بَابُ السِّوَاكِ · ١","segs":[["matn","يُسَنُّ بِعُودٍ رَطْبٍ لَا يَتَفَتَّتُ. وَهُوَ مَسْنُونٌ مُطْلَقًا إِلَّا بَعْدَ الزَّوَالِ لِلصَّائِمِ فَيُكْرَهُ وَيُسَنُّ لَهُ قَبْلَهُ بِعُودٍ يَابِسٍ وَيُبَاحُ بِرَطْبٍ. وَلَمْ يُصِبِ السُّنَّةَ مَنِ اسْتَاكَ بِغَيْرِ عُودٍ."]]},{"id":"da5_2","label":"بَابُ السِّوَاكِ · ٢","segs":[["matn","وَيَتَأَكَّدُ عِنْدَ وُضُوءٍ وَصَلَاةٍ وَقِرَاءَةٍ وَانْتِبَاهٍ مِنْ نَوْمٍ وَتَغَيُّرِ رَائِحَةِ فَمٍ وَكَذَا عِنْدَ دُخُولِ مَسْجِدٍ وَمَنْزِلٍ وَإِطَالَةِ سُكُوتٍ وَصُفْرَةِ أَسْنَانٍ. وَلَا بَأْسَ أَنْ يَتَسَوَّكَ بِالْعُودِ الْوَاحِدِ اثْنَانِ فَصَاعِدًا."]]},{"id":"da5_3","label":"بَابُ السِّوَاكِ · ٣","segs":[["matn","فَصْلٌ: يُسَنُّ حَلْقُ الْعَانَةِ وَنَتْفُ الْإِبْطِ وَتَقْلِيمُ الْأَظْفَارِ وَالنَّظَرُ فِي الْمِرْآةِ وَالتَّطَيُّبُ بِالطِّيبِ وَالِاكْتِحَالُ كُلَّ لَيْلَةٍ فِي كُلِّ عَيْنٍ ثَلَاثًا وَحَفُّ الشَّارِبِ"]]},{"id":"da5_4","label":"بَابُ السِّوَاكِ · ٤","segs":[["matn","وَإِعْفَاءُ اللِّحْيَةِ وَحَرُمَ حَلْقُهَا وَلَا بَأْسَ بِأَخْذِ مَا زَادَ عَلَى الْقَبْضَةِ مِنْهَا وَالْخِتَانُ وَاجِبٌ عَلَى الذَّكَرِ وَالْأُنْثَى عِنْدَ الْبُلُوغِ وَقَبْلَهُ أَفْضَلُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da6","title":"بَابُ الْوُضُوءِ","units":[{"id":"da6_1","label":"بَابُ الْوُضُوءِ · ١","segs":[["matn","تَجِبُ فِيهِ التَّسْمِيَةُ وَتَسْقُطُ سَهْوًا وَإِنْ ذَكَرَهَا فِي أَثْنَائِهِ ابْتَدَأَ."]]},{"id":"da6_2","label":"بَابُ الْوُضُوءِ · ٢","segs":[["matn","وَفُرُوضُهُ سِتَّةٌ: غَسْلُ الْوَجْهِ وَمِنْهُ الْمَضْمَضَةُ وَالِاسْتِنْشَاقُ وَغَسْلُ الْيَدَيْنِ مَعَ الْمِرْفَقَيْنِ وَمَسْحُ الرَّأْسِ كُلِّهِ وَمِنْهُ الْأُذُنَانِ وَغَسْلُ الرِّجْلَيْنِ مَعَ الْكَعْبَيْنِ وَالتَّرْتِيبُ وَالْمُوَالَاةُ."]]},{"id":"da6_3","label":"بَابُ الْوُضُوءِ · ٣","segs":[["matn","وَشُرُوطُهُ ثَمَانِيَةٌ: انْقِطَاعُ مَا يُوجِبُهُ وَالنِّيَّةُ وَالْإِسْلَامُ وَالْعَقْلُ وَالتَّمْيِيزُ وَالْمَاءُ الطَّهُورُ الْمُبَاحُ وَإِزَالَةُ مَا يَمْنَعُ وُصُولَهُ وَالِاسْتِنْجَاءُ أَوِ الِاسْتِجْمَارُ."]]},{"id":"da6_4","label":"بَابُ الْوُضُوءِ · ٤","segs":[["matn","فَصْلٌ: فَالنِّيَّةُ هُنَا قَصْدُ رَفْعِ الْحَدَثِ أَوْ قَصْدُ مَا تَجِبُ لَهُ الطَّهَارَةُ كَصَلَاةٍ وَطَوَافٍ وَمَسِّ مُصْحَفٍ."]]},{"id":"da6_5","label":"بَابُ الْوُضُوءِ · ٥","segs":[["matn","أَوْ قَصْدُ مَا تُسَنُّ لَهُ كَقِرَاءَةٍ وَذِكْرٍ وَأَذَانٍ وَنَوْمٍ وَرَفْعِ شَكٍّ وَغَضَبٍ وَكَلَامٍ مُحَرَّمٍ وَجُلُوسٍ بِمَسْجِدٍ وَتَدْرِيسِ عِلْمٍ وَأَكْلٍ. فَمَتَى نَوَى شَيْئًا مِنْ ذَلِكَ ارْتَفَعَ حَدَثُهُ."]]},{"id":"da6_6","label":"بَابُ الْوُضُوءِ · ٦","segs":[["matn","وَلَا يَضُرُّ سَبْقُ لِسَانِهِ بِغَيْرِ مَا نَوَى وَلَا شَكُّهُ فِي النِّيَّةِ أَوْ فِي فَرْضٍ بَعْدَ فَرَاغِ كُلِّ عِبَادَةٍ. وَإِنْ شَكَّ فِيهَا فِي الْأَثْنَاءِ اسْتَأْنَفَ."]]},{"id":"da6_7","label":"بَابُ الْوُضُوءِ · ٧","segs":[["matn","فَصْلٌ فِي صِفَةِ الْوُضُوءِ: وَهِيَ أَنْ يَنْوِيَ ثُمَّ يُسَمِّيَ وَيَغْسِلَ كَفَّيْهِ ثُمَّ يَتَمَضْمَضَ وَيَسْتَنْشِقَ ثُمَّ يَغْسِلَ وَجْهَهُ مِنْ مَنَابِتِ شَعْرِ الرَّأْسِ الْمُعْتَادِ وَلَا يُجْزِئُ غَسْلُ ظَاهِرِ شَعْرِ اللِّحْيَةِ إِلَّا أَنْ لَا يَصِفَ الْبَشَرَةَ ثُمَّ يَغْسِلَ يَدَيْهِ مَعَ مِرْفَقَيْهِ وَلَا يَضُرُّ"]]},{"id":"da6_8","label":"بَابُ الْوُضُوءِ · ٨","segs":[["matn","وَسَخٌ يَسِيرٌ تَحْتَ ظُفُرٍ وَنَحْوِهِ ثُمَّ يَمْسَحَ جَمِيعَ ظَاهِرِ رَأْسِهِ مِنْ حَدِّ الْوَجْهِ إِلَى مَا يُسَمَّى قَفًا وَالْبَيَاضُ فَوْقَ الْأُذُنَيْنِ مِنْهُ وَيُدْخِلَ سَبَّابَتَيْهِ فِي صِمَاخَيْ أُذُنَيْهِ وَيَمْسَحَ بِإِبْهَامَيْهِ ظَاهِرَهُمَا ثُمَّ يَغْسِلَ رِجْلَيْهِ مَعَ كَعْبَيْهِ وَهُمَا الْعَظْمَانِ النَّاتِئَانِ."]]},{"id":"da6_9","label":"بَابُ الْوُضُوءِ · ٩","segs":[["matn","فَصْلٌ: وَسُنَنُهُ ثَمَانِيَةَ عَشَرَ: اسْتِقْبَالُ الْقِبْلَةِ وَالسِّوَاكُ وَغَسْلُ الْكَفَّيْنِ ثَلَاثًا وَالْبَدَاءَةُ قَبْلَ غَسْلِ الْوَجْهِ بِالْمَضْمَضَةِ وَالِاسْتِنْشَاقِ وَالْمُبَالَغَةُ فِيهِمَا لِغَيْرِ الصَّائِمِ وَالْمُبَالَغَةُ فِي سَائِرِ الْأَعْضَاءِ مُطْلَقًا وَالزِّيَادَةُ فِي مَاءِ الْوَجْهِ وَتَخْلِيلُ اللِّحْيَةِ الْكَثِيفَةِ"]]},{"id":"da6_10","label":"بَابُ الْوُضُوءِ · ١٠","segs":[["matn","وَتَخْلِيلُ الْأَصَابِعِ وَأَخْذُ مَاءٍ جَدِيدٍ لِلْأُذُنَيْنِ وَتَقْدِيمُ الْيُمْنَى عَلَى الْيُسْرَى وَمُجَاوَزَةُ مَحَلِّ الْفَرْضِ وَالْغَسْلَةُ الثَّانِيَةُ وَالثَّالِثَةُ وَاسْتِصْحَابُ ذِكْرِ النِّيَّةِ إِلَى آخِرِ الْوُضُوءِ وَالْإِتْيَانُ بِهَا عِنْدَ غَسْلِ الْكَفَّيْنِ وَالنُّطْقُ بِهَا سِرًّا."]]},{"id":"da6_11","label":"بَابُ الْوُضُوءِ · ١١","segs":[["matn","وَقَوْلُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ مَعَ رَفْعِ بَصَرِهِ إِلَى السَّمَاءِ: بَعْدَ فَرَاغِهِ. وَأَنْ يَتَوَلَّى وُضُوءَهُ بِنَفْسِهِ مِنْ غَيْرِ مُعَاوَنَةٍ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da7","title":"بَابُ مَسْحِ الْخُفَّيْنِ","units":[{"id":"da7_1","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ١","segs":[["matn","يَجُوزُ بِشُرُوطٍ سَبْعَةٍ لُبْسُهُمَا بَعْدَ كَمَالِ الطَّهَارَةِ بِالْمَاءِ وَسَتْرُهُمَا لِمَحَلِّ الْفَرْضِ وَلَوْ بِرَبْطِهِمَا وَإِمْكَانُ الْمَشْيِ بِهِمَا عُرْفًا وَثُبُوتُهُمَا بِنَفْسِهِمَا وَإِبَاحَتُهُمَا وَطَهَارَةُ عَيْنِهِمَا وَعَدَمُ وَصْفِهِمَا الْبَشَرَةَ."]]},{"id":"da7_2","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٢","segs":[["matn","فَيَمْسَحُ الْمُقِيمُ وَالْعَاصِي بِسَفَرِهِ مِنَ الْحَدَثِ بَعْدَ اللُّبْسِ يَوْمًا وَلَيْلَةً وَالْمُسَافِرُ ثَلَاثَةَ أَيَّامٍ بِلَيَالِيهِنَّ."]]},{"id":"da7_3","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٣","segs":[["matn","فَلَوْ مَسَحَ فِي السَّفَرِ ثُمَّ أَقَامَ أَوْ فِي الْحَضَرِ ثُمَّ سَافَرَ أَوْ شَكَّ فِي ابْتِدَاءِ الْمَسْحِ لَمْ يَزِدْ عَلَى مَسْحِ الْمُقِيمِ."]]},{"id":"da7_4","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٤","segs":[["matn","وَيَجِبُ مَسْحُ أَكْثَرِ أَعْلَى الْخُفِّ وَلَا يُجْزِئُ مَسْحُ أَسْفَلِهِ وَعَقِبِهِ وَلَا يُسَنُّ. وَمَتَى حَصَلَ مَا يُوجِبُ الْغُسْلَ أَوْ ظَهَرَ بَعْضُ مَحَلِّ الْفَرْضِ أَوِ انْقَضَتِ الْمُدَّةُ بَطَلَ الْوُضُوءُ."]]},{"id":"da7_5","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٥","segs":[["matn","فَصْلٌ: وَصَاحِبُ الْجَبِيرَةِ إِنْ وَضَعَهَا عَلَى طَهَارَةٍ وَلَمْ تَتَجَاوَزْ مَحَلَّ الْحَاجَةِ غَسَلَ الصَّحِيحَ وَمَسَحَ عَلَيْهَا بِالْمَاءِ وَأَجْزَأَ وَإِلَّا وَجَبَ مَعَ الْغَسْلِ أَنْ يَتَيَمَّمَ لَهَا."]]},{"id":"da7_6","label":"بَابُ مَسْحِ الْخُفَّيْنِ · ٦","segs":[["matn","وَلَا مَسْحَ مَا لَمْ تُوضَعْ عَلَى طَهَارَةٍ وَتَتَجَاوَزِ الْمَحَلَّ فَيَغْسِلُ وَيَمْسَحُ وَيَتَيَمَّمُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da8","title":"بَابُ نَوَاقِضِ الْوُضُوءِ","units":[{"id":"da8_1","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ١","segs":[["matn","وَهِيَ ثَمَانِيَةٌ: أَحَدُهَا: الْخَارِجُ مِنَ السَّبِيلَيْنِ قَلِيلًا كَانَ أَوْ كَثِيرًا طَاهِرًا أَوْ نَجِسًا."]]},{"id":"da8_2","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٢","segs":[["matn","الثَّانِي: خُرُوجُ النَّجَاسَةِ مِنْ بَقِيَّةِ الْبَدَنِ فَإِنْ كَانَ بَوْلًا أَوْ غَائِطًا نَقَضَ مُطْلَقًا وَإِنْ كَانَ غَيْرَهُمَا كَالدَّمِ وَالْقَيْءِ نَقَضَ إِنْ فَحُشَ فِي نَفْسِ كُلِّ أَحَدٍ بِحَسَبِهِ."]]},{"id":"da8_3","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٣","segs":[["matn","الثَّالِثُ: زَوَالُ الْعَقْلِ أَوْ تَغْطِيَتُهُ بِإِغْمَاءٍ أَوْ نَوْمٍ مَا لَمْ يَكُنِ النَّوْمُ يَسِيرًا عُرْفًا مِنْ جَالِسٍ وَقَائِمٍ."]]},{"id":"da8_4","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٤","segs":[["matn","الرَّابِعُ: مَسُّهُ بِيَدِهِ لَا ظُفُرِهِ فَرْجَ الْآدَمِيِّ الْمُتَّصِلَ بِلَا حَائِلٍ أَوْ حَلْقَةَ دُبُرِهِ لَا مَسُّ الْخُصْيَتَيْنِ وَلَا مَسُّ مَحَلِّ الْفَرْجِ الْبَائِنِ."]]},{"id":"da8_5","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٥","segs":[["matn","الْخَامِسُ: لَمْسُ بَشَرَةِ الذَّكَرِ الْأُنْثَى أَوِ الْأُنْثَى الذَّكَرَ لِشَهْوَةٍ مِنْ غَيْرِ حَائِلٍ وَلَوْ كَانَ الْمَلْمُوسُ مَيْتًا أَوْ عَجُوزًا أَوْ مَحْرَمًا لَا لَمْسُ مَنْ دُونَ سَبْعٍ وَلَا لَمْسُ سِنٍّ وَظُفُرٍ وَشَعْرٍ وَلَا اللَّمْسُ بِذَلِكَ."]]},{"id":"da8_6","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٦","segs":[["matn","وَلَا يَنْتَقِضُ وُضُوءُ الْمَمْسُوسِ فَرْجُهُ وَالْمَلْمُوسِ بَدَنُهُ وَلَوْ وَجَدَ شَهْوَةً. السَّادِسُ: غَسْلُ الْمَيِّتِ أَوْ بَعْضِهِ وَالْغَاسِلُ هُوَ مَنْ يُقَلِّبُ الْمَيِّتَ وَيُبَاشِرُهُ لَا مَنْ يَصُبُّ الْمَاءَ."]]},{"id":"da8_7","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٧","segs":[["matn","السَّابِعُ: أَكْلُ لَحْمِ الْإِبِلِ وَلَوْ نِيئًا فَلَا نَقْضَ بِبَقِيَّةِ أَجْزَائِهَا كَكَبِدٍ وَقَلْبٍ وَطِحَالٍ وَكَرِشٍ وَشَحْمٍ وَكُلْيَةٍ وَلِسَانٍ وَرَأْسٍ وَسَنَامٍ وَكَوَارِعَ وَمُصْرَانٍ وَمَرَقِ لَحْمٍ وَلَا يَحْنَثُ بِذَلِكَ مَنْ حَلَفَ لَا يَأْكُلُ لَحْمًا."]]},{"id":"da8_8","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٨","segs":[["matn","الثَّامِنُ: الرِّدَّةُ وَكُلُّ مَا أَوْجَبَ الْغُسْلَ أَوْجَبَ الْوُضُوءَ غَيْرَ الْمَوْتِ."]]},{"id":"da8_9","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ٩","segs":[["matn","فَصْلٌ: مَنْ تَيَقَّنَ الطَّهَارَةَ وَشَكَّ فِي الْحَدَثِ أَوْ تَيَقَّنَ الْحَدَثَ وَشَكَّ فِي الطَّهَارَةِ عَمِلَ بِمَا تَيَقَّنَ. وَيَحْرُمُ عَلَى الْمُحْدِثِ الصَّلَاةُ وَالطَّوَافُ وَمَسُّ الْمُصْحَفِ بِبَشَرَتِهِ بِلَا حَائِلٍ."]]},{"id":"da8_10","label":"بَابُ نَوَاقِضِ الْوُضُوءِ · ١٠","segs":[["matn","وَيَزِيدُ مَنْ عَلَيْهِ غُسْلٌ: بِقِرَاءَةِ الْقُرْآنِ وَاللُّبْثِ فِي الْمَسْجِدِ بِلَا وُضُوءٍ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da9","title":"بَابُ مَا يُوجِبُ الْغُسْلَ","units":[{"id":"da9_1","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ١","segs":[["matn","وَهُوَ سَبْعَةٌ: أَحَدُهَا: انْتِقَالُ الْمَنِيِّ فَلَوْ أَحَسَّ بِانْتِقَالِهِ فَحَبَسَهُ فَلَمْ يَخْرُجْ وَجَبَ الْغُسْلُ فَلَوِ اغْتَسَلَ لَهُ ثُمَّ خَرَجَ بِلَا لَذَّةٍ لَمْ يُعِدِ الْغُسْلَ."]]},{"id":"da9_2","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٢","segs":[["matn","الثَّانِي: خُرُوجُهُ مِنْ مَخْرَجِهِ وَلَوْ دَمًا وَيُشْتَرَطُ أَنْ يَكُونَ بِلَذَّةٍ مَا لَمْ يَكُنْ نَائِمًا وَنَحْوَهُ."]]},{"id":"da9_3","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٣","segs":[["matn","الثَّالِثُ: تَغْيِيبُ الْحَشَفَةِ كُلِّهَا أَوْ قَدْرِهَا بِلَا حَائِلٍ فِي فَرْجٍ وَلَوْ دُبُرًا لِمَيِّتٍ أَوْ بَهِيمَةٍ أَوْ طَيْرٍ وَلَكِنْ لَا يَجِبُ الْغُسْلُ إِلَّا عَلَى ابْنِ عَشْرٍ وَبِنْتِ تِسْعٍ."]]},{"id":"da9_4","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٤","segs":[["matn","الرَّابِعُ: إِسْلَامُ الْكَافِرِ وَلَوْ مُرْتَدًّا. الْخَامِسُ: خُرُوجُ دَمِ الْحَيْضِ. السَّادِسُ: خُرُوجُ دَمِ النِّفَاسِ. السَّابِعُ: الْمَوْتُ تَعَبُّدًا."]]},{"id":"da9_5","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٥","segs":[["matn","فَصْلٌ: وَشُرُوطُ الْغُسْلِ سَبْعَةٌ: انْقِطَاعُ مَا يُوجِبُهُ، وَالنِّيَّةُ، وَالْإِسْلَامُ، وَالْعَقْلُ، وَالتَّمْيِيزُ، وَالْمَاءُ الطَّهُورُ الْمُبَاحُ، وَإِزَالَةُ مَا يَمْنَعُ وُصُولَهُ. وَوَاجِبُهُ: التَّسْمِيَةُ وَتَسْقُطُ سَهْوًا."]]},{"id":"da9_6","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٦","segs":[["matn","وَفَرْضُهُ: أَنْ يَعُمَّ بِالْمَاءِ جَمِيعَ بَدَنِهِ وَدَاخِلَ فَمِهِ وَأَنْفِهِ حَتَّى مَا يَظْهَرُ مِنْ فَرْجِ الْمَرْأَةِ عِنْدَ الْقُعُودِ لِحَاجَتِهَا وَحَتَّى بَاطِنَ شَعْرِهَا. وَيَجِبُ نَقْضُهُ فِي الْحَيْضِ وَالنِّفَاسِ لَا الْجَنَابَةِ."]]},{"id":"da9_7","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٧","segs":[["matn","وَيَكْفِي الظَّنُّ فِي الْإِسْبَاغِ. وَسُنَنُهُ: الْوُضُوءُ قَبْلَهُ وَإِزَالَةُ مَا لَوَّثَهُ مِنْ أَذًى وَإِفْرَاغُهُ الْمَاءَ عَلَى رَأْسِهِ ثَلَاثًا وَعَلَى بَقِيَّةِ جَسَدِهِ ثَلَاثًا وَالتَّيَامُنُ وَالْمُوَالَاةُ وَإِمْرَارُ الْيَدِ عَلَى الْجَسَدِ وَإِعَادَةُ غَسْلِ رِجْلَيْهِ بِمَكَانٍ آخَرَ."]]},{"id":"da9_8","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٨","segs":[["matn","وَمَنْ نَوَى غُسْلًا مَسْنُونًا أَوْ وَاجِبًا أَجْزَأَ عَنِ الْآخَرِ. وَإِنْ نَوَى رَفْعَ الْحَدَثَيْنِ أَوِ الْحَدَثَ وَأَطْلَقَ أَوْ أَمْرًا لَا يُبَاحُ إِلَّا بِوُضُوءٍ وَغُسْلٍ أَجْزَأَ عَنْهُمَا."]]},{"id":"da9_9","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ٩","segs":[["matn","وَيُسَنُّ الْوُضُوءُ بِمُدٍّ وَهُوَ رِطْلٌ وَثُلُثٌ بِالْعِرَاقِيِّ وَأُوقِيَّتَانِ وَأَرْبَعَةُ أَسْبَاعٍ بِالْقُدْسِيِّ وَالِاغْتِسَالُ بِصَاعٍ وَهُوَ خَمْسَةُ أَرْطَالٍ وَثُلُثٌ بِالْعِرَاقِيِّ وَعَشْرُ أَوَاقٍ وَسُبُعَانِ بِالْقُدْسِيِّ. وَيُكْرَهُ: الْإِسْرَافُ لَا الْإِسْبَاغُ بِدُونِ مَا ذُكِرَ."]]},{"id":"da9_10","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ١٠","segs":[["matn","وَيُبَاحُ الْغُسْلُ فِي الْمَسْجِدِ مَا لَمْ يُؤْذِ بِهِ وَفِي الْحَمَّامِ إِنْ أَمِنَ الْوُقُوعَ فِي الْمُحَرَّمِ فَإِنْ خِيفَ كُرِهَ وَإِنْ عُلِمَ حَرُمَ."]]},{"id":"da9_11","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ١١","segs":[["matn","فَصْلٌ فِي الْأَغْسَالِ الْمُسْتَحَبَّةِ: وَهِيَ سِتَّةَ عَشَرَ: آكَدُهَا لِصَلَاةِ جُمُعَةٍ فِي يَوْمِهَا لِذَكَرٍ حَضَرَهَا ثُمَّ لِغَسْلِ مَيِّتٍ ثُمَّ لِعِيدٍ فِي يَوْمِهِ وَلِكُسُوفٍ وَاسْتِسْقَاءٍ وَجُنُونٍ وَإِغْمَاءٍ وَلِاسْتِحَاضَةٍ لِكُلِّ صَلَاةٍ وَلِإِحْرَامٍ وَلِدُخُولِ مَكَّةَ وَحَرَمِهَا وَلِوُقُوفٍ بِعَرَفَةَ وَطَوَافِ زِيَارَةٍ وَطَوَافِ وَدَاعٍ وَمَبِيتٍ بِمُزْدَلِفَةَ وَرَمْيِ جِمَارٍ."]]},{"id":"da9_12","label":"بَابُ مَا يُوجِبُ الْغُسْلَ · ١٢","segs":[["matn","وَيَتَيَمَّمُ لِلْكُلِّ لِحَاجَةٍ وَلِمَا يُسَنُّ لَهُ الْوُضُوءُ إِنْ تَعَذَّرَ"]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da10","title":"بَابُ التَّيَمُّمِ","units":[{"id":"da10_1","label":"بَابُ التَّيَمُّمِ · ١","segs":[["matn","يَصِحُّ بِشُرُوطٍ ثَمَانِيَةٍ: النِّيَّةُ، وَالْإِسْلَامُ، وَالْعَقْلُ، وَالتَّمْيِيزُ، وَالِاسْتِنْجَاءُ أَوِ الِاسْتِجْمَارُ. السَّادِسُ: دُخُولُ وَقْتِ الصَّلَاةِ فَلَا يَصِحُّ التَّيَمُّمُ لِصَلَاةٍ قَبْلَ وَقْتِهَا وَلَا لِنَافِلَةٍ وَقْتَ نَهْيٍ."]]},{"id":"da10_2","label":"بَابُ التَّيَمُّمِ · ٢","segs":[["matn","السَّابِعُ: تَعَذُّرُ اسْتِعْمَالِ الْمَاءِ إِمَّا لِعَدَمِهِ أَوْ لِخَوْفِهِ بِاسْتِعْمَالِهِ الضَّرَرَ. وَيَجِبُ بَذْلُهُ لِعَطْشَانَ مِنْ آدَمِيٍّ أَوْ بَهِيمَةٍ مُحْتَرَمَيْنِ. وَمَنْ وَجَدَ مَاءً لَا يَكْفِي لِطَهَارَتِهِ اسْتَعْمَلَهُ فِيمَا يَكْفِي وُجُوبًا ثُمَّ تَيَمَّمَ."]]},{"id":"da10_3","label":"بَابُ التَّيَمُّمِ · ٣","segs":[["matn","وَإِنْ وَصَلَ الْمُسَافِرُ إِلَى الْمَاءِ وَقَدْ ضَاقَ الْوَقْتُ أَوْ عَلِمَ أَنَّ النَّوْبَةَ لَا تَصِلُ إِلَيْهِ إِلَّا بَعْدَ خُرُوجِهِ عَدَلَ إِلَى التَّيَمُّمِ وَغَيْرُهُ لَا وَلَوْ فَاتَهُ الْوَقْتُ."]]},{"id":"da10_4","label":"بَابُ التَّيَمُّمِ · ٤","segs":[["matn","وَمَنْ فِي الْوَقْتِ أَرَاقَ الْمَاءَ أَوْ مَرَّ بِهِ وَأَمْكَنَهُ الْوُضُوءُ وَيَعْلَمُ أَنَّهُ لَا يَجِدُ غَيْرَهُ حَرُمَ ثُمَّ إِنْ تَيَمَّمَ وَصَلَّى لَمْ يُعِدْ."]]},{"id":"da10_5","label":"بَابُ التَّيَمُّمِ · ٥","segs":[["matn","وَإِنْ وَجَدَ مُحْدِثٌ بِبَدَنِهِ وَثَوْبِهِ نَجَاسَةٌ مَاءً لَا يَكْفِي وَجَبَ غَسْلُ ثَوْبِهِ ثُمَّ إِنْ فَضَلَ شَيْءٌ غَسَلَ بَدَنَهُ ثُمَّ إِنْ فَضَلَ شَيْءٌ تَطَهَّرَ بِهِ، وَإِلَّا تَيَمَّمَ."]]},{"id":"da10_6","label":"بَابُ التَّيَمُّمِ · ٦","segs":[["matn","وَيَصِحُّ التَّيَمُّمُ لِكُلِّ حَدَثٍ وَلِلنَّجَاسَةِ عَلَى الْبَدَنِ بَعْدَ تَخْفِيفِهَا مَا أَمْكَنَ فَإِنْ تَيَمَّمَ لَهَا قَبْلَ تَخْفِيفِهَا لَمْ يَصِحَّ."]]},{"id":"da10_7","label":"بَابُ التَّيَمُّمِ · ٧","segs":[["matn","الثَّامِنُ: أَنْ يَكُونَ بِتُرَابٍ طَهُورٍ مُبَاحٍ غَيْرِ مُحْتَرِقٍ لَهُ غُبَارٌ يَعْلَقُ بِالْيَدِ فَإِنْ لَمْ يَجِدْ ذَلِكَ صَلَّى الْفَرْضَ فَقَطْ عَلَى حَسَبِ حَالِهِ وَلَا يَزِيدُ فِي صَلَاتِهِ عَلَى مَا يُجْزِئُ وَلَا إِعَادَةَ."]]},{"id":"da10_8","label":"بَابُ التَّيَمُّمِ · ٨","segs":[["matn","فَصْلٌ: وَاجِبُ التَّيَمُّمِ: التَّسْمِيَةُ، وَتَسْقُطُ سَهْوًا وَفُرُوضُهُ خَمْسَةٌ: مَسْحُ الْوَجْهِ، وَمَسْحُ الْيَدَيْنِ إِلَى الْكُوعَيْنِ."]]},{"id":"da10_9","label":"بَابُ التَّيَمُّمِ · ٩","segs":[["matn","الثَّالِثُ: التَّرْتِيبُ فِي الطَّهَارَةِ الصُّغْرَى فَيَلْزَمُ مَنْ جُرْحُهُ بِبَعْضِ أَعْضَاءِ وُضُوئِهِ إِذَا تَوَضَّأَ أَنْ يَتَيَمَّمَ لَهُ عِنْدَ غَسْلِهِ لَوْ كَانَ صَحِيحًا."]]},{"id":"da10_10","label":"بَابُ التَّيَمُّمِ · ١٠","segs":[["matn","الرَّابِعُ: الْمُوَالَاةُ فَيَلْزَمُهُ أَنْ يُعِيدَ غَسْلَ الصَّحِيحِ عِنْدَ كُلِّ تَيَمُّمٍ. الْخَامِسُ: تَعْيِينُ النِّيَّةِ لِمَا يَتَيَمَّمُ لَهُ مِنْ حَدَثٍ أَوْ نَجَاسَةٍ فَلَا تَكْفِي نِيَّةُ أَحَدِهِمَا عَنِ الْآخَرِ وَإِنْ نَوَاهُمَا أَجْزَأَ."]]},{"id":"da10_11","label":"بَابُ التَّيَمُّمِ · ١١","segs":[["matn","وَمُبْطِلَاتُهُ خَمْسَةٌ: مَا أَبْطَلَ الْوُضُوءَ وَوُجُودُ الْمَاءِ وَخُرُوجُ الْوَقْتِ وَزَوَالُ الْمُبِيحِ لَهُ وَخَلْعُ مَا مَسَحَ عَلَيْهِ. وَإِنْ وَجَدَ الْمَاءَ وَهُوَ فِي الصَّلَاةِ بَطَلَتْ وَإِنِ انْقَضَتْ لَمْ تَجِبِ الْإِعَادَةُ."]]},{"id":"da10_12","label":"بَابُ التَّيَمُّمِ · ١٢","segs":[["matn","وَصِفَتُهُ أَنْ يَنْوِيَ ثُمَّ يُسَمِّيَ وَيَضْرِبَ التُّرَابَ بِيَدَيْهِ مُفَرَّجَتَيِ الْأَصَابِعِ ضَرْبَةً وَاحِدَةً وَالْأَحْوَطُ اثْنَتَانِ بَعْدَ نَزْعِ خَاتَمٍ وَنَحْوِهِ فَيَمْسَحُ وَجْهَهُ بِبَاطِنِ أَصَابِعِهِ وَكَفَّيْهِ بِرَاحَتَيْهِ."]]},{"id":"da10_13","label":"بَابُ التَّيَمُّمِ · ١٣","segs":[["matn","وَيُسَنُّ لِمَنْ يَرْجُو وُجُودَ الْمَاءِ تَأْخِيرُ التَّيَمُّمِ إِلَى آخِرِ الْوَقْتِ الْمُخْتَارِ وَلَهُ أَنْ يُصَلِّيَ بِتَيَمُّمٍ وَاحِدٍ مَا شَاءَ مِنَ الْفَرْضِ وَالنَّفْلِ لَكِنْ لَوْ تَيَمَّمَ لِلنَّفْلِ لَمْ يَسْتَبِحِ الْفَرْضَ"]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da11","title":"بَابُ إِزَالَةِ النَّجَاسَةِ","units":[{"id":"da11_1","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ١","segs":[["matn","يُشْتَرَطُ لِكُلِّ مُتَنَجِّسٍ سَبْعُ غَسَلَاتٍ وَأَنْ تَكُونَ إِحْدَاهَا بِتُرَابٍ طَاهِرٍ طَهُورٍ أَوْ صَابُونٍ وَنَحْوِهِ فِي مُتَنَجَّسٍ بِكَلْبٍ أَوْ خِنْزِيرٍ وَيَضُرُّ بَقَاءُ طَعْمِ النَّجَاسَةِ لَا لَوْنِهَا أَوْ رِيحِهَا أَوْ هُمَا عَجْزًا."]]},{"id":"da11_2","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٢","segs":[["matn","وَيُجْزِئُ فِي بَوْلِ غُلَامٍ لَمْ يَأْكُلْ طَعَامًا لِشَهْوَةٍ نَضْحُهُ وَهُوَ غَمْرُهُ بِالْمَاءِ."]]},{"id":"da11_3","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٣","segs":[["matn","وَيُجْزِئُ فِي تَطْهِيرِ صَخْرٍ وَأَحْوَاضٍ وَأَرْضٍ تَنَجَّسَتْ بِمَائِعٍ وَلَوْ مِنْ كَلْبٍ أَوْ خِنْزِيرٍ مُكَاثَرَتُهَا بِالْمَاءِ بِحَيْثُ يَذْهَبُ لَوْنُ النَّجَاسَةِ وَرِيحُهَا. وَلَا تَطْهُرُ الْأَرْضُ بِالشَّمْسِ وَالرِّيحِ وَالْجَفَافِ وَلَا النَّجَاسَةُ بِالنَّارِ."]]},{"id":"da11_4","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٤","segs":[["matn","وَتَطْهُرُ الْخَمْرَةُ بِإِنَائِهَا إِنِ انْقَلَبَتْ خَلًّا بِنَفْسِهَا وَإِذَا خَفِيَ مَوْضِعُ النَّجَاسَةِ غُسِلَ حَتَّى يُتَيَقَّنَ غَسْلُهَا."]]},{"id":"da11_5","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٥","segs":[["matn","فَصْلٌ: الْمُسْكِرُ الْمَائِعُ وَكَذَا الْحَشِيشَةُ وَمَا لَا يُؤْكَلُ مِنَ الطَّيْرِ وَالْبَهَائِمِ مِمَّا فَوْقَ الْهِرِّ خِلْقَةً نَجِسٌ. وَمَا دُونَهَا فِي الْخِلْقَةِ كَالْحَيَّةِ وَالْفَارِ وَالْمُسْكِرِ غَيْرِ الْمَائِعِ فَطَاهِرٌ."]]},{"id":"da11_6","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٦","segs":[["matn","وَكُلُّ مَيْتَةٍ نَجِسَةٌ غَيْرَ مَيْتَةِ الْآدَمِيِّ وَالسَّمَكِ وَالْجَرَادِ وَمَا لَا نَفْسَ لَهُ سَائِلَةٌ كَالْعَقْرَبِ وَالْخُنْفُسَاءِ وَالْبَقِّ وَالْقَمْلِ وَالْبَرَاغِيثِ."]]},{"id":"da11_7","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٧","segs":[["matn","وَمَا أُكِلَ لَحْمُهُ وَلَمْ يَكُنْ أَكْثَرُ عَلَفِهِ النَّجَاسَةَ فَبَوْلُهُ وَرَوْثُهُ وَقَيْئُهُ وَمَذْيُهُ وَمَنِيُّهُ وَلَبَنُهُ طَاهِرٌ. وَمَا لَا يُؤْكَلُ فَنَجِسٌ إِلَّا مَنِيَّ الْآدَمِيِّ وَلَبَنَهُ فَطَاهِرٌ."]]},{"id":"da11_8","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٨","segs":[["matn","وَالْقَيْحُ وَالدَّمُ وَالصَّدِيدُ نَجِسٌ لَكِنْ يُعْفَى فِي الصَّلَاةِ عَنْ يَسِيرٍ مِنْهُ لَمْ يَنْقُضْ إِذَا كَانَ مِنْ حَيَوَانٍ طَاهِرٍ فِي الْحَيَاةِ وَلَوْ مِنْ دَمِ حَائِضٍ. وَيُضَمُّ يَسِيرٌ مُتَفَرِّقٌ بِثَوْبٍ لَا أَكْثَرَ."]]},{"id":"da11_9","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ٩","segs":[["matn","وَطِينُ شَارِعٍ ظُنَّتْ نَجَاسَتُهُ وَعَرَقٌ وَرِيقٌ مِنْ طَاهِرٍ، طَاهِرٌ. وَلَوْ أَكَلَ هِرٌّ وَنَحْوُهُ مِنَ الْحَيَوَانَاتِ الطَّاهِرَاتِ كَالنِّمْسِ، وَالْفَأْرَةِ، وَالْقُنْفُذِ أَوْ طِفْلٌ نَجَاسَةً ثُمَّ شَرِبَ مِنْ مَائِعٍ لَمْ يَضُرَّ."]]},{"id":"da11_10","label":"بَابُ إِزَالَةِ النَّجَاسَةِ · ١٠","segs":[["matn","وَلَا يُكْرَهُ سُؤْرُ حَيَوَانٍ طَاهِرٍ وَهُوَ فَضْلَةُ طَعَامِهِ وَشَرَابِهِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da12","title":"بَابُ الْحَيْضِ","units":[{"id":"da12_1","label":"بَابُ الْحَيْضِ · ١","segs":[["matn","لَا حَيْضَ قَبْلَ تَمَامِ تِسْعِ سِنِينَ وَلَا بَعْدَ خَمْسِينَ سَنَةً وَلَا مَعَ حَمْلٍ وَأَقَلُّ الْحَيْضِ يَوْمٌ وَلَيْلَةٌ وَأَكْثَرُهُ خَمْسَةَ عَشَرَ يَوْمًا وَغَالِبُهُ سِتٌّ أَوْ سَبْعٌ."]]},{"id":"da12_2","label":"بَابُ الْحَيْضِ · ٢","segs":[["matn","وَأَقَلُّ الطُّهْرِ بَيْنَ الْحَيْضَتَيْنِ ثَلَاثَةَ عَشَرَ يَوْمًا وَغَالِبُهُ بَقِيَّةُ الشَّهْرِ وَلَا حَدَّ لِأَكْثَرِهِ."]]},{"id":"da12_3","label":"بَابُ الْحَيْضِ · ٣","segs":[["matn","وَيَحْرُمُ بِالْحَيْضِ أَشْيَاءُ: مِنْهَا الْوَطْءُ فِي الْفَرْجِ وَالطَّلَاقُ وَالصَّلَاةُ وَالصَّوْمُ وَالطَّوَافُ وَقِرَاءَةُ الْقُرْآنِ وَمَسُّ الْمُصْحَفِ وَاللُّبْثُ فِي الْمَسْجِدِ وَكَذَا الْمُرُورُ فِيهِ إِنْ خَافَتْ تَلْوِيثَهُ."]]},{"id":"da12_4","label":"بَابُ الْحَيْضِ · ٤","segs":[["matn","وَيُوجِبُ الْحَيْضُ الْغُسْلَ وَالْبُلُوغَ وَالْكَفَّارَةَ بِالْوَطْءِ فِيهِ وَلَوْ مُكْرَهًا أَوْ نَاسِيًا أَوْ جَاهِلًا لِلْحَيْضِ وَالتَّحْرِيمَ وَهِيَ دِينَارٌ أَوْ نِصْفُهُ عَلَى التَّخْيِيرِ وَكَذَا هِيَ إِنْ طَاوَعَتْ."]]},{"id":"da12_5","label":"بَابُ الْحَيْضِ · ٥","segs":[["matn","وَلَا يُبَاحُ بَعْدَ انْقِطَاعِهِ وَقَبْلَ غُسْلِهَا أَوْ تَيَمُّمِهَا غَيْرُ الصَّوْمِ وَالطَّلَاقِ وَاللُّبْثِ بِوُضُوءٍ فِي الْمَسْجِدِ. وَانْقِطَاعُ الدَّمِ: بِأَنْ لَا تَتَغَيَّرَ قُطْنَةٌ احْتَشَتْ بِهَا فِي زَمَنِ الْحَيْضِ طُهْرٌ. وَتَقْضِي الْحَائِضُ وَالنُّفَسَاءُ الصَّوْمَ لَا الصَّلَاةَ."]]},{"id":"da12_6","label":"بَابُ الْحَيْضِ · ٦","segs":[["matn","فَصْلٌ: وَمَنْ جَاوَزَ دَمُهَا خَمْسَةَ عَشَرَ يَوْمًا فَهِيَ مُسْتَحَاضَةٌ تَجْلِسُ مِنْ كُلِّ شَهْرٍ سِتًّا أَوْ سَبْعًا حَيْثُ لَا تَمْيِيزَ ثُمَّ تَغْتَسِلُ وَتَصُومُ وَتُصَلِّي بَعْدَ غَسْلِ الْمَحَلِّ وَتَعْصِيبِهِ وَتَتَوَضَّأُ فِي وَقْتِ كُلِّ صَلَاةٍ وَتَنْوِي بِوُضُوئِهَا الِاسْتِبَاحَةَ."]]},{"id":"da12_7","label":"بَابُ الْحَيْضِ · ٧","segs":[["matn","وَكَذَا يَفْعَلُ كُلُّ مَنْ حَدَثُهُ دَائِمٌ. وَيَحْرُمُ وَطْءُ الْمُسْتَحَاضَةِ وَلَا كَفَّارَةَ. وَالنِّفَاسُ: لَا حَدَّ لِأَقَلِّهِ وَأَكْثَرُهُ أَرْبَعُونَ يَوْمًا وَيَثْبُتُ حُكْمُهُ بِوَضْعِ مَا يَتَبَيَّنُ فِيهِ خَلْقُ إِنْسَانٍ."]]},{"id":"da12_8","label":"بَابُ الْحَيْضِ · ٨","segs":[["matn","فَإِنْ تَخَلَّلَ الْأَرْبَعِينَ نَقَاءٌ فَهُوَ طُهْرٌ لَكِنْ يُكْرَهُ وَطْؤُهَا فِيهِ. وَمَنْ وَضَعَتْ وَلَدَيْنِ فَأَكْثَرَ فَأَوَّلُ مُدَّةِ النِّفَاسِ مِنَ الْأَوَّلِ فَلَوْ كَانَ بَيْنَهُمَا أَرْبَعُونَ يَوْمًا فَلَا نِفَاسَ لِلثَّانِي."]]},{"id":"da12_9","label":"بَابُ الْحَيْضِ · ٩","segs":[["matn","وَفِي وَطْءِ النُّفَسَاءِ مَا فِي وَطْءِ الْحَائِضِ. وَيَجُوزُ لِلرَّجُلِ شُرْبُ دَوَاءٍ مُبَاحٍ يَمْنَعُ الْجِمَاعَ وَلِلْأُنْثَى شُرْبُهُ لِحُصُولِ الْحَيْضِ وَلِقَطْعِهِ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da13","title":"بَابُ الْأَذَانِ وَالْإِقَامَةِ","units":[{"id":"da13_1","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ١","segs":[["matn","وَهُمَا فَرْضُ كِفَايَةٍ فِي الْحَضَرِ عَلَى الرِّجَالِ الْأَحْرَارِ وَيُسَنَّانِ لِلْمُنْفَرِدِ وَفِي السَّفَرِ وَيُكْرَهَانِ لِلنِّسَاءِ وَلَوْ بِلَا رَفْعِ صَوْتٍ. وَلَا يَصِحَّانِ إِلَّا مُرَتَّبَيْنِ مُتَوَالِيَيْنِ عُرْفًا وَأَنْ يَكُونَا مِنْ وَاحِدٍ بِنِيَّةٍ مِنْهُ."]]},{"id":"da13_2","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٢","segs":[["matn","وَشُرِطَ كَوْنُهُ مُسْلِمًا ذَكَرًا عَاقِلًا مُمَيِّزًا نَاطِقًا عَدْلًا وَلَوْ ظَاهِرًا وَلَا يَصِحَّانِ قَبْلَ الْوَقْتِ إِلَّا أَذَانَ الْفَجْرِ فَيَصِحُّ بَعْدَ نِصْفِ اللَّيْلِ. وَرَفْعُ الصَّوْتِ رُكْنٌ مَا لَمْ يُؤَذِّنْ لِحَاضِرٍ."]]},{"id":"da13_3","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٣","segs":[["matn","وَسُنَّ كَوْنُهُ صَيِّتًا أَمِينًا عَالِمًا بِالْوَقْتِ مُتَطَهِّرًا قَائِمًا فِيهِمَا لَكِنْ لَا يُكْرَهُ أَذَانُ الْمُحْدِثِ بَلْ إِقَامَتُهُ."]]},{"id":"da13_4","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٤","segs":[["matn","وَيُسَنُّ الْأَذَانُ أَوَّلَ الْوَقْتِ وَالتَّرَسُّلُ فِيهِ وَأَنْ يَكُونَ عَلَى عُلْوٍ رَافِعًا وَجْهَهُ جَاعِلًا سَبَّابَتَيْهِ فِي أُذُنَيْهِ مُسْتَقْبِلَ الْقِبْلَةِ يَلْتَفِتُ يَمِينًا لِحَيَّ عَلَى الصَّلَاةِ"]]},{"id":"da13_5","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٥","segs":[["matn","وَشِمَالًا لِحَيَّ عَلَى الْفَلَاحِ وَلَا يُزِيلُ قَدَمَيْهِ مَا لَمْ يَكُنْ بِمَنَارَةٍ وَأَنْ يَقُولَ بَعْدَ حَيْعَلَةِ أَذَانِ الْفَجْرِ: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ مَرَّتَيْنِ وَيُسَمَّى التَّثْوِيبَ."]]},{"id":"da13_6","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٦","segs":[["matn","وَيُسَنُّ أَنْ يَتَوَلَّى الْأَذَانَ وَالْإِقَامَةَ وَاحِدٌ مَا لَمْ يَشُقَّ. وَمَنْ جَمَعَ أَوْ قَضَى فَوَائِتَ أَذَّنَ لِلْأُولَى وَأَقَامَ لِلْكُلِّ."]]},{"id":"da13_7","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٧","segs":[["matn","وَسُنَّ لِمَنْ يَسْمَعُ الْمُؤَذِّنَ أَوِ الْمُقِيمَ أَنْ يَقُولَ مِثْلَهُ إِلَّا فِي الْحَيْعَلَةِ فَيَقُولُ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ وَفِي التَّثْوِيبِ: صَدَقْتَ وَبَرِرْتَ وَفِي لَفْظِ الْإِقَامَةِ:"]]},{"id":"da13_8","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٨","segs":[["matn","أَقَامَهَا اللَّهُ وَأَدَامَهَا ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا فَرَغَ وَيَقُولُ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ ثُمَّ يَدْعُو هُنَا وَعِنْدَ الْإِقَامَةِ."]]},{"id":"da13_9","label":"بَابُ الْأَذَانِ وَالْإِقَامَةِ · ٩","segs":[["matn","وَيَحْرُمُ بَعْدَ الْأَذَانِ الْخُرُوجُ مِنَ الْمَسْجِدِ بِلَا عُذْرٍ أَوْ نِيَّةِ رُجُوعٍ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da14","title":"بَابُ شُرُوطِ الصَّلَاةِ","units":[{"id":"da14_1","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١","segs":[["matn","وَهِيَ تِسْعَةٌ: الْإِسْلَامُ وَالْعَقْلُ وَالتَّمْيِيزُ وَكَذَا الطَّهَارَةُ مَعَ الْقُدْرَةِ، الْخَامِسُ: دُخُولُ الْوَقْتِ. فَوَقْتُ الظُّهْرِ مِنَ الزَّوَالِ إِلَى أَنْ يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ سِوَى ظِلِّ الزَّوَالِ."]]},{"id":"da14_2","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٢","segs":[["matn","ثُمَّ يَلِيهِ الْوَقْتُ الْمُخْتَارُ لِلْعَصْرِ حَتَّى يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ سِوَى ظِلِّ الزَّوَالِ ثُمَّ هُوَ وَقْتُ ضَرُورَةٍ إِلَى الْغُرُوبِ. ثُمَّ يَلِيهِ وَقْتُ الْمَغْرِبِ حَتَّى يَغِيبَ الشَّفَقُ الْأَحْمَرُ."]]},{"id":"da14_3","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٣","segs":[["matn","ثُمَّ يَلِيهِ الْوَقْتُ الْمُخْتَارُ لِلْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ ثُمَّ هُوَ وَقْتُ ضَرُورَةٍ إِلَى طُلُوعِ الْفَجْرِ ثُمَّ يَلِيهِ وَقْتُ الْفَجْرِ إِلَى شُرُوقِ الشَّمْسِ. وَيُدْرَكُ الْوَقْتُ بِتَكْبِيرَةِ الْإِحْرَامِ."]]},{"id":"da14_4","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٤","segs":[["matn","وَيَحْرُمُ تَأْخِيرُ الصَّلَاةِ عَنْ وَقْتِ الْجَوَازِ. وَيَجُوزُ تَأْخِيرُ فِعْلِهَا فِي الْوَقْتِ مَعَ الْعَزْمِ عَلَيْهِ. وَالصَّلَاةُ أَوَّلَ الْوَقْتِ أَفْضَلُ وَتَحْصُلُ الْفَضِيلَةُ بِالتَّأَهُّبِ أَوَّلَ الْوَقْتِ."]]},{"id":"da14_5","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٥","segs":[["matn","وَيَجِبُ قَضَاءُ الصَّلَاةِ الْفَائِتَةِ مُرَتَّبَةً فَوْرًا وَلَا يَصِحُّ النَّفْلُ الْمُطْلَقُ إِذَنْ وَيَسْقُطُ التَّرْتِيبُ بِالنِّسْيَانِ وَبِضِيقِ الْوَقْتِ وَلَوْ لِلِاخْتِيَارِ. السَّادِسُ: سَتْرُ الْعَوْرَةِ مَعَ الْقُدْرَةِ بِشَيْءٍ لَا يَصِفُ الْبَشَرَةَ."]]},{"id":"da14_6","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٦","segs":[["matn","فَعَوْرَةُ الذَّكَرِ الْبَالِغِ عَشْرًا وَالْحُرَّةِ الْمُمَيِّزَةِ وَالْأَمَةِ وَلَوْ مُبَعَّضَةً مَا بَيْنَ السُّرَّةِ وَالرُّكْبَةِ وَعَوْرَةُ ابْنِ سَبْعٍ إِلَى عَشْرٍ الْفَرْجَانِ وَالْحُرَّةُ الْبَالِغَةُ كُلُّهَا عَوْرَةٌ فِي الصَّلَاةِ إِلَّا وَجْهَهَا."]]},{"id":"da14_7","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٧","segs":[["matn","وَشُرِطَ فِي فَرْضِ الرَّجُلِ الْبَالِغِ سَتْرُ أَحَدِ عَاتِقَيْهِ بِشَيْءٍ مِنَ اللِّبَاسِ. وَمَنْ صَلَّى فِي مَغْصُوبٍ أَوْ حَرِيرٍ عَالِمًا ذَاكِرًا لَمْ تَصِحَّ."]]},{"id":"da14_8","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٨","segs":[["matn","وَيُصَلِّي عُرْيَانًا مَعَ غَصْبٍ وَفِي حَرِيرٍ لِعَدَمٍ وَلَا يُعِيدُ وَفِي نَجِسٍ لِعَدَمٍ وَيُعِيدُ. وَيَحْرُمُ عَلَى الذُّكُورِ لَا الْإِنَاثِ لُبْسُ مَنْسُوجٍ وَمُمَوَّهٍ بِذَهَبٍ أَوْ فِضَّةٍ وَلُبْسُ مَا كُلُّهُ أَوْ غَالِبُهُ حَرِيرٌ."]]},{"id":"da14_9","label":"بَابُ شُرُوطِ الصَّلَاةِ · ٩","segs":[["matn","وَيُبَاحُ مَا سُدِّيَ بِالْحَرِيرِ وَأُلْحِمَ بِغَيْرِهِ أَوْ كَانَ الْحَرِيرُ وَغَيْرُهُ فِي الظُّهُورِ سِيَّانِ."]]},{"id":"da14_10","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٠","segs":[["matn","السَّابِعُ: اجْتِنَابُ النَّجَاسَةِ لِبَدَنِهِ وَثَوْبِهِ وَبُقْعَتِهِ مَعَ الْقُدْرَةِ فَإِنْ حُبِسَ بِبُقْعَةٍ نَجِسَةٍ وَصَلَّى صَحَّتْ لَكِنْ يُومِئُ بِالنَّجَاسَةِ الرَّطْبَةِ غَايَةَ مَا يُمْكِنُهُ وَيَجْلِسُ عَلَى قَدَمَيْهِ."]]},{"id":"da14_11","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١١","segs":[["matn","وَإِنْ مَسَّ ثَوْبُهُ ثَوْبًا نَجِسًا أَوْ حَائِطًا لَمْ يَسْتَنِدْ إِلَيْهِ أَوْ صَلَّى عَلَى طَاهِرٍ طَرَفُهُ مُتَنَجِّسٌ أَوْ سَقَطَتْ عَلَيْهِ النَّجَاسَةُ فَزَالَتْ أَوْ أَزَالَهَا سَرِيعًا: صَحَّتْ."]]},{"id":"da14_12","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٢","segs":[["matn","وَتَبْطُلُ إِنْ عَجَزَ عَنْ إِزَالَتِهَا فِي الْحَالِ أَوْ نَسِيَهَا ثُمَّ عَلِمَ. وَلَا تَصِحُّ الصَّلَاةُ فِي الْأَرْضِ الْمَغْصُوبَةِ وَكَذَا الْمَقْبَرَةِ وَالْمَجْزَرَةِ وَالْمَزْبَلَةِ وَالْحُشِّ وَأَعْطَانِ الْإِبِلِ وَقَارِعَةِ الطَّرِيقِ وَالْحَمَّامِ وَأَسْطِحَةُ هَذِهِ مِثْلُهَا."]]},{"id":"da14_13","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٣","segs":[["matn","وَلَا يَصِحُّ الْفَرْضُ فِي الْكَعْبَةِ وَالْحِجْرُ مِنْهَا وَلَا عَلَى ظَهْرِهَا إِلَّا إِذَا لَمْ يَبْقَ وَرَاءَهُ شَيْءٌ. وَيَصِحُّ النَّذْرُ فِيهَا وَعَلَيْهَا وَكَذَا النَّفْلُ بَلْ يُسَنُّ فِيهَا. الثَّامِنُ: اسْتِقْبَالُ الْقِبْلَةِ مَعَ الْقُدْرَةِ."]]},{"id":"da14_14","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٤","segs":[["matn","فَإِنْ لَمْ يَجِدْ مَنْ يُخْبِرُهُ عَنْهَا بِيَقِينٍ صَلَّى بِالِاجْتِهَادِ فَإِنْ أَخْطَأَ فَلَا إِعَادَةَ."]]},{"id":"da14_15","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٥","segs":[["matn","التَّاسِعُ: النِّيَّةُ وَلَا تَسْقُطُ بِحَالٍ وَمَحَلُّهَا الْقَلْبُ وَحَقِيقَتُهَا الْعَزْمُ عَلَى فِعْلِ الشَّيْءِ وَشَرْطُهَا: الْإِسْلَامُ وَالْعَقْلُ وَالتَّمْيِيزُ وَزَمَنُهَا أَوَّلُ الْعِبَادَةِ أَوْ قَبْلَهَا بِيَسِيرٍ وَالْأَفْضَلُ قَرْنُهَا بِالتَّكْبِيرِ."]]},{"id":"da14_16","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٦","segs":[["matn","وَشُرِطَ مَعَ نِيَّةِ الصَّلَاةِ تَعْيِينُ مَا يُصَلِّيهِ مِنْ ظُهْرٍ أَوْ عَصْرٍ أَوْ وِتْرٍ أَوْ رَاتِبَةٍ وَإِلَّا أَجْزَأَتْهُ نِيَّةُ الصَّلَاةِ وَلَا يُشْتَرَطُ تَعْيِينُ كَوْنِ الصَّلَاةِ حَاضِرَةً أَوْ قَضَاءً أَوْ فَرْضًا وَتُشْتَرَطُ نِيَّةُ الْإِمَامَةِ لِلْإِمَامِ وَالِائْتِمَامِ لِلْمَأْمُومِ."]]},{"id":"da14_17","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٧","segs":[["matn","وَتَصِحُّ نِيَّةُ الْمُفَارَقَةِ لِكُلٍّ مِنْهُمَا لِعُذْرٍ يُبِيحُ تَرْكَ الْجَمَاعَةِ وَيَقْرَأُ مَأْمُومٌ فَارَقَ فِي قِيَامٍ أَوْ يُكْمِلُ وَبَعْدَ الْفَاتِحَةِ لَهُ الرُّكُوعُ فِي الْحَالِ."]]},{"id":"da14_18","label":"بَابُ شُرُوطِ الصَّلَاةِ · ١٨","segs":[["matn","وَمَنْ أَحْرَمَ بِفَرْضٍ ثُمَّ قَلَبَهُ نَفْلًا صَحَّ إِنِ اتَّسَعَ الْوَقْتُ وَإِلَّا لَمْ يَصِحَّ وَبَطَلَ فَرْضُهُ."]]}],"group":"كِتَابُ الطَّهَارَةِ"},{"id":"da15","title":"كِتَابُ الصَّلَاةِ","units":[{"id":"da15_1","label":"كِتَابُ الصَّلَاةِ · ١","segs":[["matn","تَجِبُ عَلَى كُلِّ مُسْلِمٍ مُكَلَّفٍ غَيْرَ الْحَائِضِ وَالنُّفَسَاءِ. وَتَصِحُّ مِنَ الْمُمَيِّزِ وَهُوَ مَنْ بَلَغَ سَبْعًا وَالثَّوَابُ لَهُ. وَيَلْزَمُ وَلِيَّهُ أَمْرُهُ بِهَا لِسَبْعٍ وَضَرْبُهُ عَلَى تَرْكِهَا لِعَشْرٍ."]]},{"id":"da15_2","label":"كِتَابُ الصَّلَاةِ · ٢","segs":[["matn","وَمَنْ تَرَكَهَا جُحُودًا فَقَدِ ارْتَدَّ وَجَرَتْ عَلَيْهِ أَحْكَامُ الْمُرْتَدِّينَ. وَأَرْكَانُ الصَّلَاةِ أَرْبَعَةَ عَشَرَ وَلَا تَسْقُطُ عَمْدًا وَلَا سَهْوًا وَلَا جَهْلًا."]]},{"id":"da15_3","label":"كِتَابُ الصَّلَاةِ · ٣","segs":[["matn","أَحَدُهَا: الْقِيَامُ فِي الْفَرْضِ عَلَى الْقَادِرِ مُنْتَصِبًا فَإِنْ وَقَفَ مُنْحَنِيًا أَوْ مَائِلًا بِحَيْثُ لَا يُسَمَّى قَائِمًا لِغَيْرِ عُذْرٍ لَمْ تَصِحَّ وَلَا يَضُرُّ خَفْضُ رَأْسِهِ وَكُرِهَ قِيَامُهُ عَلَى رِجْلٍ وَاحِدَةٍ لِغَيْرِ عُذْرٍ."]]},{"id":"da15_4","label":"كِتَابُ الصَّلَاةِ · ٤","segs":[["matn","الثَّانِي: تَكْبِيرَةُ الْإِحْرَامِ وَهِيَ اللَّهُ أَكْبَرُ لَا يُجْزِئُهُ غَيْرُهَا يَقُولُهَا قَائِمًا فَإِنِ ابْتَدَأَهَا أَوْ أَتَمَّهَا غَيْرَ قَائِمٍ صَحَّتْ نَفْلًا وَتَنْعَقِدُ إِنْ مَدَّ اللَّامَ لَا إِنْ مَدَّ هَمْزَةَ اللَّهِ أَوْ هَمْزَةَ أَكْبَرَ أَوْ قَالَ أَكْبَارُ أَوِ الْأَكْبَرُ."]]},{"id":"da15_5","label":"كِتَابُ الصَّلَاةِ · ٥","segs":[["matn","وَجَهْرُهُ بِهَا وَبِكُلِّ رُكْنٍ وَوَاجِبٍ بِقَدْرِ مَا يُسْمِعُ نَفْسَهُ فَرْضٌ."]]},{"id":"da15_6","label":"كِتَابُ الصَّلَاةِ · ٦","segs":[["matn","الثَّالِثُ: قِرَاءَةُ الْفَاتِحَةِ مُرَتَّبَةً وَفِيهَا إِحْدَى عَشْرَةَ تَشْدِيدَةً فَإِنْ تَرَكَ وَاحِدَةً أَوْ حَرْفًا وَلَمْ يَأْتِ بِمَا تَرَكَ لَمْ تَصِحَّ فَإِنْ لَمْ يَعْرِفْ إِلَّا آيَةً كَرَّرَهَا بِقَدْرِهَا وَمَنِ امْتَنَعَتْ قِرَاءَتُهُ قَائِمًا صَلَّى قَاعِدًا وَقَرَأَ."]]},{"id":"da15_7","label":"كِتَابُ الصَّلَاةِ · ٧","segs":[["matn","الرَّابِعُ: الرُّكُوعُ وَأَقَلُّهُ أَنْ يَنْحَنِيَ بِحَيْثُ يُمْكِنُهُ مَسُّ رُكْبَتَيْهِ بِكَفَّيْهِ وَأَكْمَلُهُ أَنْ يَمُدَّ ظَهْرَهُ مُسْتَوِيًا وَيَجْعَلَ رَأْسَهُ حِيَالَهُ."]]},{"id":"da15_8","label":"كِتَابُ الصَّلَاةِ · ٨","segs":[["matn","الْخَامِسُ: الرَّفْعُ مِنْهُ وَلَا يَقْصِدُ غَيْرَهُ فَلَوْ رَفَعَ فَزَعًا مِنْ شَيْءٍ لَمْ يَكْفِ. السَّادِسُ: الِاعْتِدَالُ قَائِمًا وَلَا تَبْطُلُ إِنْ طَالَ."]]},{"id":"da15_9","label":"كِتَابُ الصَّلَاةِ · ٩","segs":[["matn","السَّابِعُ: السُّجُودُ وَأَكْمَلُهُ تَمْكِينُ جَبْهَتِهِ وَأَنْفِهِ وَكَفَّيْهِ وَرُكْبَتَيْهِ وَأَطْرَافِ أَصَابِعِ قَدَمَيْهِ مِنْ مَحَلِّ سُجُودِهِ وَأَقَلُّهُ وَضْعُ جُزْءٍ مِنْ كُلِّ عُضْوٍ وَيُعْتَبَرُ الْمَقَرُّ لِأَعْضَاءِ السُّجُودِ فَلَوْ"]]},{"id":"da15_10","label":"كِتَابُ الصَّلَاةِ · ١٠","segs":[["matn","وَضَعَ جَبْهَتَهُ عَلَى نَحْوِ قُطْنٍ مَنْفُوشٍ وَلَمْ يَنْكَبِسْ لَمْ تَصِحَّ وَيَصِحُّ سُجُودُهُ عَلَى كُمِّهِ وَذَيْلِهِ وَيُكْرَهُ بِلَا عُذْرٍ وَمَنْ عَجَزَ بِالْجَبْهَةِ لَمْ يَلْزَمْهُ بِغَيْرِهَا وَيُومِئُ مَا يُمْكِنُهُ."]]},{"id":"da15_11","label":"كِتَابُ الصَّلَاةِ · ١١","segs":[["matn","الثَّامِنُ: الرَّفْعُ مِنَ السُّجُودِ. التَّاسِعُ: الْجُلُوسُ بَيْنَ السَّجْدَتَيْنِ وَكَيْفَ جَلَسَ كَفَى وَالسُّنَّةُ أَنْ يَجْلِسَ مُفْتَرِشًا عَلَى رِجْلِهِ الْيُسْرَى وَيَنْصِبَ الْيُمْنَى وَيُوَجِّهَهَا إِلَى الْقِبْلَةِ."]]},{"id":"da15_12","label":"كِتَابُ الصَّلَاةِ · ١٢","segs":[["matn","الْعَاشِرُ: الطُّمَأْنِينَةُ وَهِيَ السُّكُونُ وَإِنْ قَلَّ فِي كُلِّ رُكْنٍ فِعْلِيٍّ."]]},{"id":"da15_13","label":"كِتَابُ الصَّلَاةِ · ١٣","segs":[["matn","الْحَادِي عَشَرَ: التَّشَهُّدُ الْأَخِيرُ وَهُوَ: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ بَعْدَ الْإِتْيَانِ بِمَا يُجْزِئُ مِنَ التَّشَهُّدِ الْأَوَّلِ وَالْمُجْزِئُ مِنْهُ التَّحِيَّاتُ لِلَّهِ سَلَامٌ عَلَيْكَ أَيُّهَا النَّبِيُّ"]]},{"id":"da15_14","label":"كِتَابُ الصَّلَاةِ · ١٤","segs":[["matn","وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ سَلَامٌ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَالْكَامِلُ مَشْهُورٌ."]]},{"id":"da15_15","label":"كِتَابُ الصَّلَاةِ · ١٥","segs":[["matn","الثَّانِي عَشَرَ: الْجُلُوسُ لَهُ وَلِلتَّسْلِيمَتَيْنِ فَلَوْ تَشَهَّدَ غَيْرَ جَالِسٍ أَوْ سَلَّمَ الْأُولَى جَالِسًا وَالثَّانِيَةَ غَيْرَ جَالِسٍ لَمْ تَصِحَّ."]]},{"id":"da15_16","label":"كِتَابُ الصَّلَاةِ · ١٦","segs":[["matn","الثَّالِثَ عَشَرَ: التَّسْلِيمَتَانِ وَهُوَ أَنْ يَقُولَ مَرَّتَيْنِ: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَالْأَوْلَى أَنْ لَا يَزِيدَ: وَبَرَكَاتُهُ. وَيَكْفِي فِي النَّفْلِ تَسْلِيمَةٌ وَاحِدَةٌ وَكَذَا فِي الْجِنَازَةِ."]]},{"id":"da15_17","label":"كِتَابُ الصَّلَاةِ · ١٧","segs":[["matn","الرَّابِعَ عَشَرَ: تَرْتِيبُ الْأَرْكَانِ كَمَا ذَكَرْنَا فَلَوْ سَجَدَ مَثَلًا قَبْلَ رُكُوعِهِ عَمْدًا بَطَلَتْ وَسَهْوًا لَزِمَهُ الرُّجُوعُ لِيَرْكَعَ ثُمَّ يَسْجُدَ."]]},{"id":"da15_18","label":"كِتَابُ الصَّلَاةِ · ١٨","segs":[["matn","فَصْلٌ: وَوَاجِبَاتُهَا ثَمَانِيَةٌ: تَبْطُلُ الصَّلَاةُ بِتَرْكِهَا عَمْدًا وَتَسْقُطُ سَهْوًا وَجَهْلًا: التَّكْبِيرُ لِغَيْرِ الْإِحْرَامِ لَكِنْ تَكْبِيرَةُ الْمَسْبُوقِ الَّتِي بَعْدَ تَكْبِيرَةِ الْإِحْرَامِ سُنَّةٌ وَقَوْلُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ لِلْإِمَامِ وَالْمُنْفَرِدِ لَا لِلْمَأْمُومِ وَقَوْلُ رَبَّنَا وَلَكَ الْحَمْدُ لِلْكُلِّ وَقَوْلُ:"]]},{"id":"da15_19","label":"كِتَابُ الصَّلَاةِ · ١٩","segs":[["matn","سُبْحَانَ رَبِّيَ الْعَظِيمِ مَرَّةً فِي الرُّكُوعِ وَسُبْحَانَ رَبِّيَ الْأَعْلَى مَرَّةً فِي السُّجُودِ وَرَبِّ اغْفِرْ لِي بَيْنَ السَّجْدَتَيْنِ وَالتَّشَهُّدُ الْأَوَّلُ عَلَى غَيْرِ مَنْ قَامَ إِمَامُهُ سَهْوًا وَالْجُلُوسُ لَهُ."]]},{"id":"da15_20","label":"كِتَابُ الصَّلَاةِ · ٢٠","segs":[["matn","وَسُنَنُهَا: أَقْوَالٌ وَأَفْعَالٌ وَلَا تَبْطُلُ بِتَرْكِ شَيْءٍ مِنْهَا وَلَوْ عَمْدًا وَيُبَاحُ السُّجُودُ لِسَهْوِهِ."]]},{"id":"da15_21","label":"كِتَابُ الصَّلَاةِ · ٢١","segs":[["matn","فَسُنَنُ الْأَقْوَالِ إِحْدَى عَشْرَةَ: قَوْلُهُ بَعْدَ تَكْبِيرَةِ الْإِحْرَامِ سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ وَالتَّعَوُّذُ وَالْبَسْمَلَةُ وَقَوْلُ:"]]},{"id":"da15_22","label":"كِتَابُ الصَّلَاةِ · ٢٢","segs":[["matn","آمِينَ وَقِرَاءَةُ السُّورَةِ بَعْدَ الْفَاتِحَةِ وَالْجَهْرُ بِالْقِرَاءَةِ لِلْإِمَامِ وَيُكْرَهُ لِلْمَأْمُومِ وَيُخَيَّرُ الْمُنْفَرِدُ وَقَوْلُ غَيْرِ الْمَأْمُومِ بَعْدَ التَّحْمِيدِ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ"]]},{"id":"da15_23","label":"كِتَابُ الصَّلَاةِ · ٢٣","segs":[["matn","وَمَا زَادَ عَلَى الْمَرَّةِ فِي تَسْبِيحِ الرُّكُوعِ وَالسُّجُودِ وَرَبِّ اغْفِرْ لِي وَالصَّلَاةُ فِي التَّشَهُّدِ الْأَخِيرِ عَلَى آلِهِ عَلَيْهِ السَّلَامُ وَالْبَرَكَةُ عَلَيْهِ وَعَلَيْهِمْ وَالدُّعَاءُ بَعْدَهُ."]]},{"id":"da15_24","label":"كِتَابُ الصَّلَاةِ · ٢٤","segs":[["matn","وَسُنَنُ الْأَفْعَالِ وَتُسَمَّى الْهَيْئَاتِ رَفْعُ الْيَدَيْنِ مَعَ تَكْبِيرَةِ الْإِحْرَامِ وَعِنْدَ الرُّكُوعِ وَعِنْدَ الرَّفْعِ مِنْهُ وَحَطُّهُمَا عَقِبَ ذَلِكَ وَوَضْعُ الْيَمِينِ عَلَى الشِّمَالِ"]]},{"id":"da15_25","label":"كِتَابُ الصَّلَاةِ · ٢٥","segs":[["matn","وَجَعْلُهُمَا تَحْتَ سُرَّتِهِ وَنَظَرُهُ إِلَى مَوْضِعِ سُجُودِهِ وَتَفْرِقَتُهُ بَيْنَ قَدَمَيْهِ قَائِمًا وَقَبْضُ رُكْبَتَيْهِ بِيَدَيْهِ مُفَرَّجَتَيِ الْأَصَابِعِ فِي رُكُوعِهِ وَمَدُّ ظَهْرِهِ فِيهِ وَجَعْلُهُ رَأْسَهُ حِيَالَهُ."]]},{"id":"da15_26","label":"كِتَابُ الصَّلَاةِ · ٢٦","segs":[["matn","وَالْبُدَاءَةُ فِي سُجُودِهِ بِوَضْعِ رُكْبَتَيْهِ ثُمَّ يَدَيْهِ ثُمَّ جَبْهَتِهِ وَأَنْفِهِ وَتَمْكِينُ أَعْضَاءِ السُّجُودِ مِنَ الْأَرْضِ وَمُبَاشَرَتُهَا لِمَحَلِّ السُّجُودِ سِوَى الرُّكْبَتَيْنِ فَيُكْرَهُ وَمُجَافَاةُ عَضُدَيْهِ عَنْ جَنْبَيْهِ وَبَطْنِهِ عَنْ فَخِذَيْهِ وَفَخِذَيْهِ عَنْ سَاقَيْهِ"]]},{"id":"da15_27","label":"كِتَابُ الصَّلَاةِ · ٢٧","segs":[["matn","وَتَفْرِيقُهُ بَيْنَ رُكْبَتَيْهِ وَإِقَامَةُ قَدَمَيْهِ وَجَعْلُ بُطُونِ أَصَابِعِهِمَا عَلَى الْأَرْضِ مُفَرَّقَةً وَوَضْعُ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ مَبْسُوطَةً مَضْمُومَةَ الْأَصَابِعِ وَرَفْعُ يَدَيْهِ أَوَّلًا فِي قِيَامِهِ إِلَى الرَّكْعَةِ وَقِيَامُهُ عَلَى صُدُورِ قَدَمَيْهِ"]]},{"id":"da15_28","label":"كِتَابُ الصَّلَاةِ · ٢٨","segs":[["matn","وَاعْتِمَادُهُ عَلَى رُكْبَتَيْهِ بِيَدَيْهِ وَالِافْتِرَاشُ فِي الْجُلُوسِ بَيْنَ السَّجْدَتَيْنِ وَفِي التَّشَهُّدِ الْأَوَّلِ وَالتَّوَرُّكُ فِي الثَّانِي وَوَضْعُ الْيَدَيْنِ عَلَى الْفَخِذَيْنِ مَبْسُوطَتَيْنِ مَضْمُومَتَيِ الْأَصَابِعِ بَيْنَ السَّجْدَتَيْنِ وَكَذَا فِي التَّشَهُّدِ إِلَّا أَنَّهُ يَقْبِضُ مِنَ الْيُمْنَى الْخِنْصَرَ"]]},{"id":"da15_29","label":"كِتَابُ الصَّلَاةِ · ٢٩","segs":[["matn","وَالْبِنْصَرَ وَيُحَلِّقُ إِبْهَامَهَا مَعَ الْوُسْطَى وَيُشِيرُ بِسَبَّابَتِهَا عِنْدَ ذِكْرِ اللَّهِ وَالْتِفَاتُهُ يَمِينًا وَشِمَالًا فِي تَسْلِيمِهِ وَنِيَّتُهُ بِهِ الْخُرُوجَ مِنَ الصَّلَاةِ وَتَفْضِيلُ الشِّمَالِ عَلَى الْيَمِينِ فِي الِالْتِفَاتِ."]]},{"id":"da15_30","label":"كِتَابُ الصَّلَاةِ · ٣٠","segs":[["matn","فَصْلٌ فِيمَا يُكْرَهُ فِي الصَّلَاةِ: يُكْرَهُ لِلْمُصَلِّي اقْتِصَارُهُ عَلَى الْفَاتِحَةِ وَتَكْرَارُهَا وَالْتِفَاتُهُ بِلَا حَاجَةٍ وَتَغْمِيضُ عَيْنَيْهِ وَحَمْلُ مُشْغِلٍ لَهُ وَافْتِرَاشُ ذِرَاعَيْهِ سَاجِدًا وَالْعَبَثُ وَالتَّخَصُّرُ"]]},{"id":"da15_31","label":"كِتَابُ الصَّلَاةِ · ٣١","segs":[["matn","وَالتَّمَطِّي وَفَتْحُ فَمِهِ وَوَضْعُهُ فِيهِ شَيْئًا وَاسْتِقْبَالُ صُورَةٍ وَوَجْهِ آدَمِيٍّ وَمُتَحَدِّثٍ وَنَائِمٍ وَنَارٍ وَمَا يُلْهِيهِ وَمَسُّ الْحَصَى وَتَسْوِيَةُ التُّرَابِ بِلَا عُذْرٍ"]]},{"id":"da15_32","label":"كِتَابُ الصَّلَاةِ · ٣٢","segs":[["matn","وَتَرَوُّحٌ بِمِرْوَحَةٍ وَفَرْقَعَةُ أَصَابِعِهِ وَتَشْبِيكُهَا وَمَسُّ لِحْيَتِهِ وَكَفُّ ثَوْبِهِ وَمَتَى كَثُرَ ذَلِكَ عُرْفًا بَطَلَتْ وَأَنْ يَخُصَّ جَبْهَتَهُ بِمَا يَسْجُدُ عَلَيْهِ وَأَنْ يَمْسَحَ فِيهَا أَثَرَ سُجُودِهِ وَأَنْ يَسْتَنِدَ بِلَا حَاجَةٍ فَإِنِ اسْتَنَدَ بِحَيْثُ يَقَعُ لَوْ أُزِيلَ مَا اسْتَنَدَ إِلَيْهِ بَطَلَتْ."]]},{"id":"da15_33","label":"كِتَابُ الصَّلَاةِ · ٣٣","segs":[["matn","وَحَمْدُهُ إِذَا عَطَسَ أَوْ وَجَدَ مَا يَسُرُّهُ وَاسْتِرْجَاعُهُ إِذَا وَجَدَ مَا يَغُمُّهُ."]]},{"id":"da15_34","label":"كِتَابُ الصَّلَاةِ · ٣٤","segs":[["matn","فَصْلٌ فِيمَا يُبْطِلُ الصَّلَاةَ: يُبْطِلُهَا مَا أَبْطَلَ الطَّهَارَةَ وَكَشْفُ الْعَوْرَةِ عَمْدًا لَا إِنْ كَشَفَهَا نَحْوُ رِيحٍ فَسَتَرَهَا فِي الْحَالِ أَوْ لَا وَكَانَ الْمَكْشُوفُ لَا يَفْحُشُ"]]},{"id":"da15_35","label":"كِتَابُ الصَّلَاةِ · ٣٥","segs":[["matn","فِي النَّظَرِ وَاسْتِدْبَارُ الْقِبْلَةِ حَيْثُ شُرِطَ اسْتِقْبَالُهَا وَاتِّصَالُ النَّجَاسَةِ بِهِ إِنْ لَمْ يُزِلْهَا فِي الْحَالِ وَالْعَمَلُ الْكَثِيرُ عَادَةً مِنْ غَيْرِ جِنْسِهَا لِغَيْرِ ضَرُورَةٍ"]]},{"id":"da15_36","label":"كِتَابُ الصَّلَاةِ · ٣٦","segs":[["matn","وَالِاسْتِنَادُ قَوِيًّا لِغَيْرِ عُذْرٍ وَرُجُوعُهُ عَالِمًا ذَاكِرًا لِلتَّشَهُّدِ بَعْدَ الشُّرُوعِ فِي الْقِرَاءَةِ وَتَعَمُّدُ زِيَادَةِ رُكْنٍ فِعْلِيٍّ وَتَعَمُّدُ تَقْدِيمِ بَعْضِ الْأَرْكَانِ عَلَى بَعْضٍ"]]},{"id":"da15_37","label":"كِتَابُ الصَّلَاةِ · ٣٧","segs":[["matn","وَتَعَمُّدُ السَّلَامِ قَبْلَ إِتْمَامِهَا وَتَعَمُّدُ إِحَالَةِ الْمَعْنَى فِي الْقِرَاءَةِ وَبِوُجُودِ سُتْرَةٍ بَعِيدَةٍ وَهُوَ عُرْيَانٌ وَبِفَسْخِ النِّيَّةِ وَبِالتَّرَدُّدِ فِي الْفَسْخِ وَبِالْعَزْمِ عَلَيْهِ وَبِشَكِّهِ:"]]},{"id":"da15_38","label":"كِتَابُ الصَّلَاةِ · ٣٨","segs":[["matn","هَلْ نَوَى فَعَمِلَ مَعَ الشَّكِّ عَمَلًا وَبِالدُّعَاءِ بِمَلَاذِّ الدُّنْيَا وَبِالْإِتْيَانِ بِكَافِ الْخِطَابِ لِغَيْرِ اللَّهِ وَرَسُولِهِ أَحْمَدَ وَبِالْقَهْقَهَةِ وَبِالْكَلَامِ وَلَوْ سَهْوًا وَبِتَقَدُّمِ الْمَأْمُومِ عَلَى إِمَامِهِ وَبِبُطْلَانِ صَلَاةِ إِمَامِهِ"]]},{"id":"da15_39","label":"كِتَابُ الصَّلَاةِ · ٣٩","segs":[["matn","وَبِسَلَامِهِ عَمْدًا قَبْلَ إِمَامِهِ أَوْ سَهْوًا وَلَمْ يُعِدْهُ بَعْدَهُ وَبِالْأَكْلِ وَبِالشُّرْبِ سِوَى الْيَسِيرِ عُرْفًا لِنَاسٍ وَجَاهِلٍ وَلَا تَبْطُلُ إِنْ بَلَعَ مَا بَيْنَ أَسْنَانِهِ بِلَا مَضْغٍ."]]},{"id":"da15_40","label":"كِتَابُ الصَّلَاةِ · ٤٠","segs":[["matn","وَكَالْكَلَامِ إِنْ تَنَحْنَحَ بِلَا حَاجَةٍ أَوِ انْتَحَبَ لَا خَشْيَةً، أَوْ نَفَخَ فَبَانَ حَرْفَانِ، لَا إِنْ نَامَ فَتَكَلَّمَ أَوْ سَبَقَ عَلَى لِسَانِهِ حَالَ قِرَاءَتِهِ أَوْ غَلَبَهُ سُعَالٌ أَوْ عُطَاسٌ أَوْ تَثَاؤُبٌ أَوْ بُكَاءٌ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da16","title":"بَابُ سُجُودِ السَّهْوِ","units":[{"id":"da16_1","label":"بَابُ سُجُودِ السَّهْوِ · ١","segs":[["matn","يُسَنُّ: إِذَا أَتَى بِقَوْلٍ مَشْرُوعٍ فِي غَيْرِ مَحَلِّهِ سَهْوًا وَيُبَاحُ إِذَا تَرَكَ مَسْنُونًا وَيَجِبُ إِذَا زَادَ رُكُوعًا أَوْ سُجُودًا أَوْ قِيَامًا أَوْ قُعُودًا"]]},{"id":"da16_2","label":"بَابُ سُجُودِ السَّهْوِ · ٢","segs":[["matn","وَلَوْ قَدْرَ جَلْسَةِ الِاسْتِرَاحَةِ أَوْ سَلَّمَ قَبْلَ إِتْمَامِهَا أَوْ لَحَنَ لَحْنًا يُحِيلُ الْمَعْنَى أَوْ تَرَكَ وَاجِبًا أَوْ شَكَّ فِي زِيَادَةٍ وَقْتَ فِعْلِهَا."]]},{"id":"da16_3","label":"بَابُ سُجُودِ السَّهْوِ · ٣","segs":[["matn","وَتَبْطُلُ الصَّلَاةُ: بِتَعَمُّدِ تَرْكِ سُجُودِ السَّهْوِ الْوَاجِبِ لَا إِنْ تَرَكَ مَا وَجَبَ بِسَلَامِهِ قَبْلَ إِتْمَامِهَا."]]},{"id":"da16_4","label":"بَابُ سُجُودِ السَّهْوِ · ٤","segs":[["matn","وَإِنْ شَاءَ سَجَدَ سَجْدَتَيِ السَّهْوِ قَبْلَ السَّلَامِ أَوْ بَعْدَهُ لَكِنْ إِنْ سَجَدَهُمَا بَعْدَهُ تَشَهَّدَ وُجُوبًا وَسَلَّمَ. وَإِنْ نَسِيَ السُّجُودَ حَتَّى طَالَ الْفَصْلُ عُرْفًا أَوْ أَحْدَثَ أَوْ خَرَجَ مِنَ الْمَسْجِدِ سَقَطَ."]]},{"id":"da16_5","label":"بَابُ سُجُودِ السَّهْوِ · ٥","segs":[["matn","وَلَا سُجُودَ عَلَى مَأْمُومٍ دَخَلَ أَوَّلَ الصَّلَاةِ إِذَا سَهَا فِي صَلَاتِهِ. وَإِنْ سَهَا إِمَامُهُ لَزِمَهُ مُتَابَعَتُهُ فِي سُجُودِ السَّهْوِ فَإِنْ لَمْ يَسْجُدْ إِمَامُهُ وَجَبَ عَلَيْهِ هُوَ."]]},{"id":"da16_6","label":"بَابُ سُجُودِ السَّهْوِ · ٦","segs":[["matn","وَمَنْ قَامَ لِرَكْعَةٍ زَائِدَةٍ جَلَسَ مَتَى ذَكَرَ. وَإِنْ نَهَضَ عَنْ تَرْكِ التَّشَهُّدِ الْأَوَّلِ نَاسِيًا لَزِمَهُ الرُّجُوعُ لِيَتَشَهَّدَ وَكُرِهَ إِنِ اسْتَتَمَّ قَائِمًا وَيَلْزَمُ:"]]},{"id":"da16_7","label":"بَابُ سُجُودِ السَّهْوِ · ٧","segs":[["matn","الْمَأْمُومَ مُتَابَعَتُهُ وَلَا يَرْجِعُ إِنْ شَرَعَ فِي الْقِرَاءَةِ وَمَنْ شَكَّ فِي رُكْنٍ أَوْ عَدَدِ رَكَعَاتٍ وَهُوَ فِي الصَّلَاةِ بَنَى عَلَى الْيَقِينِ وَهُوَ الْأَقَلُّ وَيَسْجُدُ لِلسَّهْوِ وَبَعْدَ فَرَاغِهَا لَا أَثَرَ لِلشَّكِّ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da17","title":"بَابُ صَلَاةِ التَّطَوُّعِ","units":[{"id":"da17_1","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١","segs":[["matn","وَهِيَ: أَفْضَلُ تَطَوُّعِ الْبَدَنِ بَعْدَ الْجِهَادِ وَالْعِلْمِ. وَأَفْضَلُهَا مَا سُنَّ جَمَاعَةً."]]},{"id":"da17_2","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٢","segs":[["matn","وَآكَدُهَا: الْكُسُوفُ فَالِاسْتِسْقَاءُ فَالتَّرَاوِيحُ فَالْوِتْرُ وَأَقَلُّهُ رَكْعَةٌ وَأَكْثَرُهُ إِحْدَى عَشْرَةَ وَأَدْنَى الْكَمَالِ ثَلَاثٌ بِسَلَامَيْنِ وَيَجُوزُ بِوَاحِدٍ سَرْدًا وَوَقْتُهُ مَا بَيْنَ صَلَاةِ الْعِشَاءِ وَطُلُوعِ الْفَجْرِ."]]},{"id":"da17_3","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٣","segs":[["matn","وَيَقْنُتُ فِيهِ بَعْدَ الرُّكُوعِ نَدْبًا فَلَوْ كَبَّرَ وَرَفَعَ يَدَيْهِ ثُمَّ قَنَتَ قَبْلَ الرُّكُوعِ جَازَ وَلَا بَأْسَ أَنْ يَدْعُوَ فِي قُنُوتِهِ بِمَا شَاءَ وَمِمَّا وَرَدَ:"]]},{"id":"da17_4","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٤","segs":[["matn","اللَّهُمَّ اهْدِنَا فِيمَنْ هَدَيْتَ وَعَافِنَا فِيمَنْ عَافَيْتَ وَتَوَلَّنَا فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لَنَا فِيمَا أَعْطَيْتَ وَقِنَا شَرَّ مَا قَضَيْتَ إِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبَارَكْتَ رَبَّنَا"]]},{"id":"da17_5","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٥","segs":[["matn","وَتَعَالَيْتَ اللَّهُمَّ إِنَّا نَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَبِعَفْوِكَ مِنْ عُقُوبَتِكَ وَبِكَ مِنْكَ لَا نُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيُؤَمِّنُ الْمَأْمُومُ ثُمَّ يَمْسَحُ وَجْهَهُ بِيَدَيْهِ هُنَا وَخَارِجَ الصَّلَاةِ."]]},{"id":"da17_6","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٦","segs":[["matn","وَكُرِهَ الْقُنُوتُ فِي غَيْرِ الْوِتْرِ. وَأَفْضَلُ الرَّوَاتِبِ: سُنَّةُ الْفَجْرِ ثُمَّ الْمَغْرِبِ ثُمَّ سَوَاءٌ. وَالرَّوَاتِبُ الْمُؤَكَّدَةُ عَشْرٌ: رَكْعَتَانِ قَبْلَ الظُّهْرِ وَرَكْعَتَانِ بَعْدَهَا وَرَكْعَتَانِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَانِ بَعْدَ الْعِشَاءِ وَرَكْعَتَانِ قَبْلَ الْفَجْرِ."]]},{"id":"da17_7","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٧","segs":[["matn","وَيُسَنُّ قَضَاءُ الرَّوَاتِبِ وَالْوِتْرِ إِلَّا مَا فَاتَ مَعَ فَرْضِهِ وَكَثُرَ فَالْأَوْلَى تَرْكُهُ وَفِعْلُ الْكُلِّ بِبَيْتٍ أَفْضَلُ. وَيُسَنُّ الْفَصْلُ بَيْنَ الْفَرْضِ وَسُنَّتِهِ بِقِيَامٍ أَوْ كَلَامٍ."]]},{"id":"da17_8","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٨","segs":[["matn","وَالتَّرَاوِيحُ عِشْرُونَ رَكْعَةً بِرَمَضَانَ وَوَقْتُهَا مَا بَيْنَ الْعِشَاءِ وَالْوِتْرِ."]]},{"id":"da17_9","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٩","segs":[["matn","فَصْلٌ: وَصَلَاةُ اللَّيْلِ أَفْضَلُ مِنْ صَلَاةِ النَّهَارِ وَالنِّصْفُ الْأَخِيرُ أَفْضَلُ مِنَ الْأَوَّلِ وَالتَّهَجُّدُ مَا كَانَ بَعْدَ النَّوْمِ. وَيُسَنُّ قِيَامُ اللَّيْلِ وَافْتِتَاحُهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ وَنِيَّتُهُ عِنْدَ النَّوْمِ. وَيَصِحُّ التَّطَوُّعُ بِرَكْعَةٍ."]]},{"id":"da17_10","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٠","segs":[["matn","وَأَجْرُ الْقَاعِدِ غَيْرِ الْمَعْذُورِ نِصْفُ أَجْرِ الْقَائِمِ. وَكَثْرَةُ الرُّكُوعِ وَالسُّجُودِ أَفْضَلُ مِنْ طُولِ الْقِيَامِ."]]},{"id":"da17_11","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١١","segs":[["matn","وَتُسَنُّ صَلَاةُ الضُّحَى غِبًّا وَأَقَلُّهَا رَكْعَتَانِ وَأَكْثَرُهَا ثَمَانٍ وَوَقْتُهَا مِنْ خُرُوجِ وَقْتِ النَّهْيِ إِلَى قُبَيْلِ الزَّوَالِ وَأَفْضَلُهُ إِذَا اشْتَدَّ الْحَرُّ."]]},{"id":"da17_12","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٢","segs":[["matn","وَتُسَنُّ تَحِيَّةُ الْمَسْجِدِ وَسُنَّةُ الْوُضُوءِ وَإِحْيَاءُ مَا بَيْنَ الْعِشَاءَيْنِ وَهُوَ مِنْ قِيَامِ اللَّيْلِ."]]},{"id":"da17_13","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٣","segs":[["matn","فَصْلٌ: وَيُسَنُّ سُجُودُ التِّلَاوَةِ مَعَ قِصَرِ الْفَصْلِ لِلْقَارِئِ وَالْمُسْتَمِعِ. وَهُوَ كَالنَّافِلَةِ فِيمَا يُعْتَبَرُ لَهَا."]]},{"id":"da17_14","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٤","segs":[["matn","يُكَبِّرُ إِذَا سَجَدَ بِلَا تَكْبِيرَةِ إِحْرَامٍ وَإِذَا رَفَعَ وَيَجْلِسُ وَيُسَلِّمُ بِلَا تَشَهُّدٍ وَإِنْ سَجَدَ الْمَأْمُومُ لِقِرَاءَةِ نَفْسِهِ أَوْ لِقِرَاءَةِ غَيْرِ إِمَامِهِ عَمْدًا بَطَلَتْ صَلَاتُهُ."]]},{"id":"da17_15","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٥","segs":[["matn","وَيَلْزَمُ الْمَأْمُومَ مُتَابَعَةُ إِمَامِهِ فِي صَلَاةِ الْجَهْرِ فَلَوْ تَرَكَ مُتَابَعَتَهُ عَمْدًا بَطَلَتْ."]]},{"id":"da17_16","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٦","segs":[["matn","وَيُعْتَبَرُ كَوْنُ الْقَارِئِ يَصْلُحُ إِمَامًا لِلْمُسْتَمِعِ فَلَا يَسْجُدُ إِنْ لَمْ يَسْجُدْ وَلَا قُدَّامَهُ وَلَا عَنْ يَسَارِهِ مَعَ خُلُوِّ يَمِينِهِ وَلَا يَسْجُدُ رَجُلٌ لِتِلَاوَةِ امْرَأَةٍ وَخُنْثَى وَيَسْجُدُ لِتِلَاوَةِ أُمِّيٍّ وَزَمِنٍ وَمُمَيِّزٍ."]]},{"id":"da17_17","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٧","segs":[["matn","وَيُسَنُّ سُجُودُ الشُّكْرِ عِنْدَ تَجَدُّدِ النِّعَمِ وَانْدِفَاعِ النِّقَمِ. وَإِنْ سَجَدَ لَهُ عَالِمًا ذَاكِرًا فِي صَلَاةٍ بَطَلَتْ. وَصِفَتُهُ وَأَحْكَامُهُ كَسُجُودِ التِّلَاوَةِ."]]},{"id":"da17_18","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٨","segs":[["matn","فَصْلٌ فِي أَوْقَاتِ النَّهْيِ: وَهِيَ مِنْ طُلُوعِ الْفَجْرِ إِلَى ارْتِفَاعِ الشَّمْسِ قَيْدَ رُمْحٍ وَمِنْ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ وَعِنْدَ قِيَامِهَا حَتَّى تَزُولَ."]]},{"id":"da17_19","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ١٩","segs":[["matn","فَتَحْرُمُ صَلَاةُ التَّطَوُّعِ فِي هَذِهِ الْأَوْقَاتِ وَلَا تَنْعَقِدُ وَلَوْ جَاهِلًا لِلْوَقْتِ وَالتَّحْرِيمِ سِوَى سُنَّةِ الْفَجْرِ قَبْلَهَا وَرَكْعَتَيِ الطَّوَافِ وَسُنَّةِ الظُّهْرِ إِذَا جَمَعَ وَإِعَادَةِ جَمَاعَةٍ أُقِيمَتْ وَهُوَ فِي الْمَسْجِدِ."]]},{"id":"da17_20","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٢٠","segs":[["matn","وَيَجُوزُ فِيهَا قَضَاءُ الْفَرَائِضِ وَفِعْلُ الْمَنْذُورَةِ وَلَوْ نَذَرَهَا فِيهَا. وَالِاعْتِبَارُ فِي التَّحْرِيمِ بَعْدَ الْعَصْرِ بِفَرَاغِ صَلَاةِ نَفْسِهِ لَا بِشُرُوعِهِ فِيهَا فَلَوْ أَحْرَمَ بِهَا ثُمَّ قَلَبَهَا نَفْلًا لَمْ يُمْنَعْ مِنَ التَّطَوُّعِ."]]},{"id":"da17_21","label":"بَابُ صَلَاةِ التَّطَوُّعِ · ٢١","segs":[["matn","وَتُبَاحُ قِرَاءَةُ الْقُرْآنِ فِي الطَّرِيقِ وَمَعَ حَدَثٍ أَصْغَرَ وَنَجَاسَةِ ثَوْبٍ وَبَدَنٍ وَفَمٍ. وَحِفْظُ الْقُرْآنِ فَرْضُ كِفَايَةٍ. وَيَتَعَيَّنُ حِفْظُ مَا يَجِبُ فِي الصَّلَاةِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da18","title":"بَابُ صَلَاةِ الْجَمَاعَةِ","units":[{"id":"da18_1","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١","segs":[["matn","تَجِبُ: عَلَى الرِّجَالِ الْأَحْرَارِ الْقَادِرِينَ حَضَرًا وَسَفَرًا. وَأَقَلُّهَا: إِمَامٌ وَمَأْمُومٌ وَلَوْ أُنْثَى. وَلَا تَنْعَقِدُ بِالْمُمَيِّزِ فِي الْفَرْضِ. وَتُسَنُّ الْجَمَاعَةُ بِالْمَسْجِدِ وَلِلنِّسَاءِ مُنْفَرِدَاتٍ عَنِ الرِّجَالِ."]]},{"id":"da18_2","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٢","segs":[["matn","وَحَرُمَ أَنْ يَؤُمَّ بِمَسْجِدٍ لَهُ إِمَامٌ رَاتِبٌ فَلَا تَصِحُّ إِلَّا مَعَ إِذْنِهِ إِنْ كَرِهَ ذَلِكَ مَا لَمْ يَضِقِ الْوَقْتُ."]]},{"id":"da18_3","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٣","segs":[["matn","وَمَنْ كَبَّرَ قَبْلَ تَسْلِيمَةِ الْإِمَامِ الْأُولَى أَدْرَكَ الْجَمَاعَةَ وَمَنْ أَدْرَكَ الرُّكُوعَ غَيْرَ شَاكٍّ أَدْرَكَ الرَّكْعَةَ وَاطْمَأَنَّ ثُمَّ تَابَعَ. وَيُسَنُّ دُخُولُ الْمَأْمُومِ مَعَ إِمَامِهِ كَيْفَ أَدْرَكَهُ."]]},{"id":"da18_4","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٤","segs":[["matn","وَإِنْ قَامَ الْمَسْبُوقُ قَبْلَ تَسْلِيمَةِ إِمَامِهِ الثَّانِيَةِ وَلَمْ يَرْجِعِ انْقَلَبَتْ نَفْلًا وَإِذَا أُقِيمَتِ الصَّلَاةُ الَّتِي يُرِيدُ أَنْ يُصَلِّيَ مَعَ إِمَامِهَا لَمْ تَنْعَقِدْ نَافِلَتُهُ وَإِنْ أُقِيمَتْ وَهُوَ فِيهَا أَتَمَّهَا خَفِيفَةً."]]},{"id":"da18_5","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٥","segs":[["matn","وَمَنْ صَلَّى ثُمَّ أُقِيمَتِ الْجَمَاعَةُ سُنَّ أَنْ يُعِيدَ وَالْأُولَى فَرْضُهُ. وَيَتَحَمَّلُ الْإِمَامُ عَنِ الْمَأْمُومِ الْقِرَاءَةَ وَسُجُودَ السَّهْوِ وَسُجُودَ التِّلَاوَةِ وَالسُّتْرَةَ وَدُعَاءَ الْقُنُوتِ وَالتَّشَهُّدَ الْأَوَّلَ إِذَا سُبِقَ بِرَكْعَةٍ فِي رُبَاعِيَّةٍ."]]},{"id":"da18_6","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٦","segs":[["matn","وَسُنَّ لِلْمَأْمُومِ أَنْ يَسْتَفْتِحَ وَيَتَعَوَّذَ فِي الْجَهْرِيَّةِ وَيَقْرَأَ الْفَاتِحَةَ وَسُورَةً حَيْثُ شُرِعَتْ فِي سَكَتَاتِ إِمَامِهِ وَهِيَ قَبْلَ الْفَاتِحَةِ وَبَعْدَهَا وَبَعْدَ فَرَاغِ الْقِرَاءَةِ. وَيَقْرَأُ فِيمَا لَا يَجْهَرُ فِيهِ الْإِمَامُ مَتَى شَاءَ."]]},{"id":"da18_7","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٧","segs":[["matn","فَصْلٌ: وَمَنْ أَحْرَمَ مَعَ إِمَامِهِ أَوْ قَبْلَ إِتْمَامِهِ لِتَكْبِيرَةِ الْإِحْرَامِ لَمْ تَنْعَقِدْ صَلَاتُهُ وَالْأَوْلَى لِلْمَأْمُومِ أَنْ يَشْرَعَ فِي أَفْعَالِ الصَّلَاةِ بَعْدَ إِمَامِهِ فَإِنْ وَافَقَهُ فِيهَا أَوْ فِي السَّلَامِ كُرِهَ وَإِنْ سَبَقَهُ حَرُمَ."]]},{"id":"da18_8","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٨","segs":[["matn","فَمَنْ رَكَعَ أَوْ سَجَدَ أَوْ رَفَعَ قَبْلَ إِمَامِهِ عَمْدًا لَزِمَهُ أَنْ يَرْجِعَ لِيَأْتِيَ بِهِ مَعَ إِمَامِهِ فَإِنْ أَبَى عَالِمًا عَمْدًا بَطَلَتْ صَلَاتُهُ لَا صَلَاةُ نَاسٍ وَجَاهِلٍ."]]},{"id":"da18_9","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٩","segs":[["matn","وَيُسَنُّ لِلْإِمَامِ التَّخْفِيفُ مَعَ الْإِتْمَامِ مَا لَمْ يُؤْثِرِ الْمَأْمُومُ التَّطْوِيلَ وَانْتِظَارُ دَاخِلٍ إِنْ لَمْ يَشُقَّ عَلَى الْمَأْمُومِ. وَمَنِ اسْتَأْذَنَتْهُ امْرَأَتُهُ أَوْ أَمَتُهُ إِلَى الْمَسْجِدِ كُرِهَ مَنْعُهَا وَبَيْتُهَا خَيْرٌ لَهَا."]]},{"id":"da18_10","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٠","segs":[["matn","فَصْلٌ فِي الْإِمَامَةِ: الْأَوْلَى بِهَا الْأَجْوَدُ قِرَاءَةً الْأَفْقَهُ وَيُقَدَّمُ قَارِئٌ لَا يَعْلَمُ فِقْهَ صَلَاتِهِ عَلَى فَقِيهٍ أُمِّيٍّ ثُمَّ الْأَسَنُّ ثُمَّ الْأَشْرَفُ ثُمَّ الْأَتْقَى وَالْأَوْرَعُ ثُمَّ يُقْرَعُ."]]},{"id":"da18_11","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١١","segs":[["matn","وَصَاحِبُ الْبَيْتِ وَإِمَامُ الْمَسْجِدِ وَلَوْ عَبْدًا أَحَقُّ. وَالْحُرُّ أَوْلَى مِنَ الْعَبْدِ. وَالْحَاضِرُ وَالْبَصِيرُ وَالْمُتَوَضِّئُ أَوْلَى مِنْ ضِدِّهِمْ. وَتُكْرَهُ إِمَامَةُ غَيْرِ الْأَوْلَى بِلَا إِذْنِهِ."]]},{"id":"da18_12","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٢","segs":[["matn","وَلَا تَصِحُّ إِمَامَةُ الْفَاسِقِ إِلَّا فِي جُمُعَةٍ وَعِيدٍ تَعَذَّرَا خَلْفَ غَيْرِهِ وَتَصِحُّ إِمَامَةُ الْأَعْمَى وَالْأَصَمِّ وَالْأَقْلَفِ وَكَثِيرِ لَحْنٍ لَمْ يُحِلِ الْمَعْنَى وَالتَّمْتَامِ الَّذِي يُكَرِّرُ التَّاءَ مَعَ الْكَرَاهَةِ."]]},{"id":"da18_13","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٣","segs":[["matn","وَلَا تَصِحُّ إِمَامَةُ الْعَاجِزِ عَنْ شَرْطٍ أَوْ رُكْنٍ إِلَّا بِمِثْلِهِ إِلَّا الْإِمَامَ الرَّاتِبَ بِمَسْجِدٍ الْمَرْجُوَّ زَوَالُ عِلَّتِهِ فَيُصَلِّي جَالِسًا وَيَجْلِسُونَ خَلْفَهُ وَتَصِحُّ قِيَامًا."]]},{"id":"da18_14","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٤","segs":[["matn","وَإِنْ تَرَكَ الْإِمَامُ رُكْنًا أَوْ شَرْطًا مُخْتَلَفًا فِيهِ مُقَلِّدًا صَحَّتْ وَمَنْ صَلَّى خَلْفَهُ مُعْتَقِدًا بُطْلَانَ صَلَاتِهِ أَعَادَ وَلَا إِنْكَارَ فِي مَسَائِلِ الِاجْتِهَادِ."]]},{"id":"da18_15","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٥","segs":[["matn","وَلَا تَصِحُّ إِمَامَةُ الْمَرْأَةِ بِالرِّجَالِ وَلَا إِمَامَةُ الْمُمَيِّزِ بِالْبَالِغِ فِي الْفَرْضِ. وَتَصِحُّ إِمَامَتُهُ فِي النَّفْلِ وَفِي الْفَرْضِ بِمِثْلِهِ."]]},{"id":"da18_16","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٦","segs":[["matn","وَلَا تَصِحُّ إِمَامَةُ مُحْدِثٍ وَلَا نَجِسٍ يَعْلَمُ ذَلِكَ فَإِنْ جَهِلَ هُوَ وَالْمَأْمُومُ حَتَّى انْقَضَتْ صَحَّتْ صَلَاةُ الْمَأْمُومِ وَحْدَهُ."]]},{"id":"da18_17","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٧","segs":[["matn","وَلَا تَصِحُّ إِمَامَةُ الْأُمِّيِّ: وَهُوَ مَنْ لَا يُحْسِنُ الْفَاتِحَةَ إِلَّا بِمِثْلِهِ وَيَصِحُّ النَّفْلُ خَلْفَ الْفَرْضِ وَلَا عَكْسَ. وَتَصِحُّ الْمَقْضِيَّةُ خَلْفَ الْحَاضِرَةِ وَعَكْسُهُ. حَيْثُ تَسَاوَتَا فِي الِاسْمِ."]]},{"id":"da18_18","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٨","segs":[["matn","فَصْلٌ: يَصِحُّ وُقُوفُ الْإِمَامِ وَسْطَ الْمَأْمُومِينَ وَالسُّنَّةُ وُقُوفُهُ مُتَقَدِّمًا عَلَيْهِمْ. وَيَقِفُ الرَّجُلُ الْوَاحِدُ عَنْ يَمِينِهِ مُحَاذِيًا لَهُ وَلَا تَصِحُّ خَلْفَهُ وَلَا عَنْ يَسَارِهِ مَعَ خُلُوِّ يَمِينِهِ. وَتَقِفُ الْمَرْأَةُ خَلْفَهُ."]]},{"id":"da18_19","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ١٩","segs":[["matn","وَإِنْ صَلَّى الرَّجُلُ رَكْعَةً خَلْفَ الصَّفِّ مُنْفَرِدًا فَصَلَاتُهُ بَاطِلَةٌ. وَإِنْ أَمْكَنَ الْمَأْمُومَ الِاقْتِدَاءُ بِإِمَامِهِ وَلَوْ كَانَ بَيْنَهُمَا فَوْقَ ثَلَاثِ مِائَةِ ذِرَاعٍ صَحَّ إِنْ رَأَى الْإِمَامَ أَوْ رَأَى مَنْ وَرَاءَهُ"]]},{"id":"da18_20","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٢٠","segs":[["matn","وَإِنْ كَانَ الْإِمَامُ وَالْمَأْمُومُ فِي الْمَسْجِدِ لَمْ تُشْتَرَطِ الرُّؤْيَةُ وَكَفَى سَمَاعُ التَّكْبِيرِ وَإِنْ كَانَ بَيْنَهُمَا نَهْرٌ تَجْرِي فِيهِ السُّفُنُ أَوْ طَرِيقٌ لَمْ تَصِحَّ. وَكُرِهَ عُلُوُّ الْإِمَامِ عَنِ الْمَأْمُومِ لَا عَكْسُهُ."]]},{"id":"da18_21","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٢١","segs":[["matn","وَكُرِهَ لِمَنْ أَكَلَ بَصَلًا أَوْ فُجْلًا وَنَحْوَهُ حُضُورُ الْمَسْجِدِ."]]},{"id":"da18_22","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٢٢","segs":[["matn","فَصْلٌ: يُعْذَرُ بِتَرْكِ الْجُمُعَةِ وَالْجَمَاعَةِ الْمَرِيضُ وَالْخَائِفُ حُدُوثَ الْمَرَضِ وَالْمُدَافِعُ أَحَدَ الْأَخْبَثَيْنِ وَمَنْ لَهُ ضَائِعٌ يَرْجُوهُ أَوْ يَخَافُ ضَيَاعَ مَالِهِ أَوْ فَوَاتَهُ أَوْ ضَرَرًا"]]},{"id":"da18_23","label":"بَابُ صَلَاةِ الْجَمَاعَةِ · ٢٣","segs":[["matn","فِيهِ أَوْ يَخَافُ عَلَى مَالٍ اسْتُؤْجِرَ لِحِفْظِهِ كَنِطَارَةِ بُسْتَانٍ أَوْ أَذىً بِمَطَرٍ وَوَحَلٍ وَثَلْجٍ وَجَلِيدٍ وَرِيحٍ بَارِدَةٍ بِلَيْلَةٍ مُظْلِمَةٍ أَوْ تَطْوِيلَ إِمَامٍ"]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da19","title":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ","units":[{"id":"da19_1","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١","segs":[["matn","يَلْزَمُ الْمَرِيضَ أَنْ يُصَلِّيَ الْمَكْتُوبَةَ قَائِمًا وَلَوْ مُسْتَنِدًا فَإِنْ لَمْ يَسْتَطِعْ فَقَاعِدًا فَإِنْ لَمْ يَسْتَطِعْ فَعَلَى جَنْبِهِ وَالْأَيْمَنُ أَفْضَلُ وَيُومِئُ بِالرُّكُوعِ"]]},{"id":"da19_2","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٢","segs":[["matn","وَالسُّجُودِ وَيَجْعَلُهُ أَخْفَضَ فَإِنْ عَجَزَ أَوْمَأَ بِطَرْفِهِ وَاسْتَحْضَرَ الْفِعْلَ بِقَلْبِهِ وَكَذَا الْقَوْلَ إِنْ عَجَزَ عَنْهُ بِلِسَانِهِ وَلَا تَسْقُطُ مَا دَامَ عَقْلُهُ ثَابِتًا."]]},{"id":"da19_3","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٣","segs":[["matn","وَمَنْ قَدِرَ عَلَى الْقِيَامِ أَوِ الْقُعُودِ فِي أَثْنَائِهَا انْتَقَلَ إِلَيْهِ. وَمَنْ قَدِرَ أَنْ يَقُومَ مُنْفَرِدًا وَيَجْلِسَ فِي الْجَمَاعَةِ خُيِّرَ."]]},{"id":"da19_4","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٤","segs":[["matn","وَتَصِحُّ عَلَى الرَّاحِلَةِ لِمَنْ يَتَأَذَّى بِنَحْوِ مَطَرٍ وَوَحْلٍ أَوْ يَخَافُ عَلَى نَفْسِهِ مِنْ نُزُولِهِ وَعَلَيْهِ الِاسْتِقْبَالُ وَمَا يَقْدِرُ عَلَيْهِ. وَيُومِئُ مَنْ: بِالْمَاءِ وَالطِّينِ."]]},{"id":"da19_5","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٥","segs":[["matn","فَصْلٌ فِي صَلَاةِ الْمُسَافِرِ: قَصْرُ الصَّلَاةِ الرُّبَاعِيَّةِ أَفْضَلُ لِمَنْ نَوَى سَفَرًا مُبَاحًا لِمَحَلٍّ مُعَيَّنٍ يَبْلُغُ سِتَّةَ عَشَرَ فَرْسَخًا وَهِيَ يَوْمَانِ قَاصِدَانِ فِي زَمَنٍ مُعْتَدِلٍ بِسَيْرِ الْأَثْقَالِ وَدَبِيبِ الْأَقْدَامِ إِذَا فَارَقَ بُيُوتَ قَرْيَتِهِ الْعَامِرَةِ."]]},{"id":"da19_6","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٦","segs":[["matn","وَلَا يُعِيدُ مَنْ قَصَرَ ثُمَّ رَجَعَ قَبْلَ اسْتِكْمَالِهِ الْمَسَافَةَ."]]},{"id":"da19_7","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٧","segs":[["matn","وَيَلْزَمُهُ إِتْمَامُ الصَّلَاةِ إِنْ دَخَلَ وَقْتُهَا وَهُوَ فِي الْحَضَرِ أَوْ صَلَّى خَلْفَ مَنْ يُتِمُّ أَوْ لَمْ يَنْوِ الْقَصْرَ عِنْدَ الْإِحْرَامِ أَوْ نَوَى إِقَامَةً مُطْلَقَةً أَوْ أَكْثَرَ مِنْ أَرْبَعَةِ أَيَّامٍ أَوْ أَقَامَ لِحَاجَةٍ"]]},{"id":"da19_8","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٨","segs":[["matn","وَظَنَّ أَنْ لَا تَنْقَضِيَ إِلَّا بَعْدَ الْأَرْبَعَةِ أَوْ أَخَّرَ الصَّلَاةَ بِلَا عُذْرٍ حَتَّى ضَاقَ وَقْتُهَا عَنْهَا."]]},{"id":"da19_9","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٩","segs":[["matn","وَيَقْصُرُ إِنْ أَقَامَ لِحَاجَةٍ بِلَا نِيَّةِ الْإِقَامَةِ فَوْقَ أَرْبَعَةِ أَيَّامٍ وَلَا يَدْرِي مَتَى تَنْقَضِي أَوْ حُبِسَ ظُلْمًا أَوْ بِمَطَرٍ وَلَوْ أَقَامَ سِنِينَ."]]},{"id":"da19_10","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٠","segs":[["matn","فَصْلٌ فِي الْجَمْعِ: يُبَاحُ بِسَفَرِ الْقَصْرِ الْجَمْعُ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَالْعِشَاءَيْنِ بِوَقْتِ إِحْدَاهُمَا."]]},{"id":"da19_11","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١١","segs":[["matn","وَيُبَاحُ لِمُقِيمٍ مَرِيضٍ يَلْحَقُهُ بِتَرْكِهِ مَشَقَّةٌ وَلِمُرْضِعٍ لِمَشَقَّةِ كَثْرَةِ النَّجَاسَةِ وَلِعَاجِزٍ عَنِ الطَّهَارَةِ لِكُلِّ صَلَاةٍ وَلِعُذْرٍ أَوْ شُغْلٍ يُبِيحُ تَرْكَ الْجُمُعَةِ وَالْجَمَاعَةِ."]]},{"id":"da19_12","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٢","segs":[["matn","وَيَخْتَصُّ بِجَوَازِ جَمْعِ الْعِشَاءَيْنِ وَلَوْ صَلَّى بِبَيْتِهِ ثَلْجٌ وَجَلِيدٌ وَوَحَلٌ وَرِيحٌ شَدِيدَةٌ بَارِدَةٌ وَمَطَرٌ يُبِلُّ الثِّيَابَ وَتُوجَدُ مَعَهُ مَشَقَّةٌ. وَالْأَفْضَلُ فِعْلُ الْأَرْفَقِ مِنْ تَقْدِيمِ الْجَمْعِ أَوْ تَأْخِيرِهِ."]]},{"id":"da19_13","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٣","segs":[["matn","فَإِنْ جَمَعَ تَقْدِيمًا اشْتُرِطَ لِصِحَّةِ الْجَمْعِ نِيَّتُهُ عِنْدَ إِحْرَامِ الْأُولَى وَأَنْ لَا يُفَرِّقَ بَيْنَهُمَا بِنَحْوِ نَافِلَةٍ بَلْ بِقَدْرِ إِقَامَةٍ وَوُضُوءٍ خَفِيفٍ وَأَنْ يُوجَدَ الْعُذْرُ عِنْدَ افْتِتَاحِهِمَا وَأَنْ يَسْتَمِرَّ إِلَى فَرَاغِ الثَّانِيَةِ."]]},{"id":"da19_14","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٤","segs":[["matn","وَإِنْ جَمَعَ تَأْخِيرًا اشْتُرِطَ: نِيَّةُ الْجَمْعِ بِوَقْتِ الْأُولَى قَبْلَ أَنْ يَضِيقَ. وَقْتُ الثَّانِيَةِ عَنْهَا وَبَقَاءُ الْعُذْرِ إِلَى دُخُولِ وَقْتِ الثَّانِيَةِ لَا غَيْرُ."]]},{"id":"da19_15","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٥","segs":[["matn","وَلَا يُشْتَرَطُ لِلصِّحَّةِ اتِّحَادُ الْإِمَامِ وَالْمَأْمُومِ فَلَوْ صَلَّاهُمَا خَلْفَ إِمَامَيْنِ أَوْ بِمَأْمُومِ الْأُولَى وَبِآخَرَ الثَّانِيَةَ أَوْ خَلْفَ مَنْ لَمْ يَجْمَعْ أَوْ إِحْدَاهُمَا مُنْفَرِدًا وَالْأُخْرَى جَمَاعَةً أَوْ صَلَّى بِمَنْ لَمْ يَجْمَعْ صَحَّ."]]},{"id":"da19_16","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٦","segs":[["matn","فَصْلٌ فِي صَلَاةِ الْخَوْفِ: تَصِحُّ صَلَاةُ الْخَوْفِ إِنْ كَانَ الْقِتَالُ مُبَاحًا حَضَرًا وَسَفَرًا. وَلَا تَأْثِيرَ لِلْخَوْفِ فِي تَغْيِيرِ عَدَدِ رَكَعَاتِ الصَّلَاةِ بَلْ فِي صِفَتِهَا وَبَعْضِ شُرُوطِهَا."]]},{"id":"da19_17","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٧","segs":[["matn","وَإِذَا اشْتَدَّ الْخَوْفُ صَلَّوْا رِجَالًا وَرُكْبَانًا لِلْقِبْلَةِ وَغَيْرِهَا وَلَا يَلْزَمُ افْتِتَاحُهَا إِلَيْهَا يُومِئُونَ طَاقَتَهُمْ."]]},{"id":"da19_18","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٨","segs":[["matn","وَكَذَا فِي حَالَةِ الْهَرَبِ مِنْ عَدُوٍّ أَوْ سَيْلٍ أَوْ سَبُعٍ أَوْ نَارٍ أَوْ غَرِيمٍ ظَالِمٍ أَوْ خَوْفِ فَوْتِ وَقْتِ الْوُقُوفِ بِعَرَفَةَ أَوْ خَافَ عَلَى نَفْسِهِ أَوْ أَهْلِهِ أَوْ مَالِهِ أَوْ ذَبٍّ عَنْ ذَلِكَ وَعَنْ نَفْسِ غَيْرِهِ."]]},{"id":"da19_19","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ١٩","segs":[["matn","وَإِنْ خَافَ عَدُوًّا إِنْ تَخَلَّفَ عَنْ رُفْقَتِهِ فَصَلَّى صَلَاةَ خَائِفٍ ثُمَّ بَانَ أَمْنُ الطَّرِيقِ لَمْ يُعِدْ. وَمَنْ خَافَ أَوْ أَمِنَ فِي صَلَاتِهِ انْتَقَلَ وَبَنَى. وَلِمُصَلٍّ كَرٌّ وَفَرٌّ لِمَصْلَحَةٍ."]]},{"id":"da19_20","label":"بَابُ صَلَاةِ أَهْلِ الْأَعْذَارِ · ٢٠","segs":[["matn","وَلَا تَبْطُلُ بِطُولِهِ. وَجَازَ لِحَاجَةٍ حَمْلُ نَجِسٍ وَلَا يُعِيدُ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da20","title":"بَابُ صَلَاةِ الْجُمْعَةِ","units":[{"id":"da20_1","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ١","segs":[["matn","تَجِبُ عَلَى كُلِّ ذَكَرٍ مُسْلِمٍ مُكَلَّفٍ حُرٍّ لَا عُذْرَ لَهُ. وَكَذَا عَلَى مُسَافِرٍ لَا يُبَاحُ لَهُ الْقَصْرُ. وَعَلَى مُقِيمٍ خَارِجَ الْبَلَدِ إِذَا كَانَ بَيْنَهُمَا وَبَيْنَ الْجُمُعَةِ وَقْتَ فِعْلِهَا فَرْسَخٌ فَأَقَلُّ."]]},{"id":"da20_2","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٢","segs":[["matn","وَلَا تَجِبُ عَلَى مَنْ يُبَاحُ لَهُ الْقَصْرُ وَلَا عَلَى عَبْدٍ وَمُبَعَّضٍ وَامْرَأَةٍ وَمَنْ حَضَرَهَا مِنْهُمْ أَجْزَأَتْهُ وَلَا يُحْسَبُ هُوَ وَلَا مَنْ لَيْسَ مِنْ أَهْلِ الْبَلَدِ مِنَ الْأَرْبَعِينَ وَلَا تَصِحُّ إِمَامَتُهُمْ فِيهَا."]]},{"id":"da20_3","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٣","segs":[["matn","وَشُرِطَ لِصِحَّةِ الْجُمُعَةِ أَرْبَعَةُ شُرُوطٍ: أَحَدُهَا: الْوَقْتُ وَهُوَ مِنْ أَوَّلِ وَقْتِ الْعِيدِ إِلَى آخِرِ وَقْتِ الظُّهْرِ وَتَجِبُ بِالزَّوَالِ وَبَعْدَهُ أَفْضَلُ."]]},{"id":"da20_4","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٤","segs":[["matn","الثَّانِي: أَنْ تَكُونَ بِقَرْيَةٍ وَلَوْ مِنْ قَصَبٍ يَسْتَوْطِنُهَا أَرْبَعُونَ اسْتِيطَانَ إِقَامَةٍ لَا يَظْعَنُونَ صَيْفًا وَلَا شِتَاءً وَتَصِحُّ فِيمَا قَارَبَ الْبُنْيَانَ مِنَ الصَّحْرَاءِ."]]},{"id":"da20_5","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٥","segs":[["matn","الثَّالِثُ: حُضُورُ أَرْبَعِينَ فَإِنْ نَقَصُوا قَبْلَ إِتْمَامِهَا اسْتَأْنَفُوا ظُهْرًا. الرَّابِعُ: تَقَدُّمُ خُطْبَتَيْنِ. مِنْ شَرْطِ صِحَّتِهِمَا خَمْسَةُ أَشْيَاءَ: الْوَقْتُ وَالنِّيَّةُ وَوُقُوعُهُمَا حَضَرًا وَحُضُورُ الْأَرْبَعِينَ وَأَنْ يَكُونَا مِمَّنْ تَصِحُّ إِمَامَتُهُ فِيهَا."]]},{"id":"da20_6","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٦","segs":[["matn","وَأَرْكَانُهُمَا سِتَّةٌ: حَمْدُ اللَّهِ وَالصَّلَاةُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقِرَاءَةُ آيَةٍ مِنْ كِتَابِ اللَّهِ وَالْوَصِيَّةُ بِتَقْوَى اللَّهِ وَمُوَالَاتُهُمَا مَعَ الصَّلَاةِ وَالْجَهْرُ بِحَيْثُ يَسْمَعُ الْعَدَدُ الْمُعْتَبَرُ حَيْثُ لَا مَانِعَ."]]},{"id":"da20_7","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٧","segs":[["matn","وَسُنَنُهُمَا: الطَّهَارَةُ وَسَتْرُ الْعَوْرَةِ وَإِزَالَةُ النَّجَاسَةِ وَالدُّعَاءُ لِلْمُسْلِمِينَ وَأَنْ يَتَوَلَّاهُمَا مَعَ الصَّلَاةِ وَاحِدٌ وَرَفْعُ الصَّوْتِ بِهِمَا حَسَبَ الطَّاقَةِ وَأَنْ يَخْطُبَ قَائِمًا عَلَى مُرْتَفِعٍ مُعْتَمِدًا عَلَى سَيْفٍ أَوْ عَصًا وَأَنْ يَجْلِسَ بَيْنَهُمَا قَلِيلًا."]]},{"id":"da20_8","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٨","segs":[["matn","فَإِنْ أَبَى أَوْ خَطَبَ جَالِسًا فَصَلَ بَيْنَهُمَا بِسَكْتَةٍ. وَسُنَّ قِصَرُهُمَا وَالثَّانِيَةُ أَقْصَرُ. وَلَا بَأْسَ أَنْ يَخْطُبَ مِنْ صَحِيفَةٍ"]]},{"id":"da20_9","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ٩","segs":[["matn","فَصْلٌ: يَحْرُمُ الْكَلَامُ وَالْإِمَامُ يَخْطُبُ وَهُوَ مِنْهُ بِحَيْثُ يَسْمَعُهُ وَيُبَاحُ إِذَا سَكَتَ بَيْنَهُمَا أَوْ شَرَعَ فِي دُعَاءٍ."]]},{"id":"da20_10","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ١٠","segs":[["matn","وَتَحْرُمُ إِقَامَةُ الْجُمُعَةِ وَإِقَامَةُ الْعِيدِ فِي أَكْثَرَ مِنْ مَوْضِعٍ مِنَ الْبَلَدِ إِلَّا لِحَاجَةٍ كَضِيقٍ وَبُعْدٍ وَخَوْفِ فِتْنَةٍ فَإِنْ تَعَدَّدَتْ لِغَيْرِ ذَلِكَ فَالسَّابِقَةُ بِالْإِحْرَامِ هِيَ الصَّحِيحَةُ."]]},{"id":"da20_11","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ١١","segs":[["matn","وَمَنْ أَحْرَمَ بِالْجُمُعَةِ فِي وَقْتِهَا وَأَدْرَكَ مَعَ الْإِمَامِ رَكْعَةً أَتَمَّ جُمُعَةً وَإِنْ أَدْرَكَ أَقَلَّ نَوَى ظُهْرًا."]]},{"id":"da20_12","label":"بَابُ صَلَاةِ الْجُمْعَةِ · ١٢","segs":[["matn","وَأَقَلُّ السُّنَّةِ بَعْدَهَا رَكْعَتَانِ وَأَكْثَرُهَا سِتٌّ وَسُنَّ قِرَاءَةُ سُورَةِ الْكَهْفِ فِي يَوْمِهَا وَأَنْ يَقْرَأَ فِي فَجْرِهَا: ﴿الم﴾ السَّجْدَةَ وَفِي الثَّانِيَةِ ﴿هَلْ أَتَى﴾ وَتُكْرَهُ مُدَاوَمَتُهُ عَلَيْهِمَا."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da21","title":"بَابُ صَلَاةِ الْعِيدَيْنِ","units":[{"id":"da21_1","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ١","segs":[["matn","وَهِيَ فَرْضُ كِفَايَةٍ. وَشُرُوطُهَا: كَالْجُمُعَةِ مَا عَدَا الْخُطْبَتَيْنِ. وَتُسَنُّ: بِالصَّحْرَاءِ. وَيُكْرَهُ: النَّفْلُ قَبْلَهَا وَبَعْدَهَا قَبْلَ مُفَارَقَةِ الْمُصَلَّى. وَوَقْتُهَا: كَصَلَاةِ الضُّحَى."]]},{"id":"da21_2","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٢","segs":[["matn","فَإِنْ لَمْ يُعْلَمْ بِالْعِيدِ إِلَّا بَعْدَ الزَّوَالِ صَلَّوْا مِنَ الْغَدِ قَضَاءً. وَسُنَّ تَبْكِيرُ الْمَأْمُومِ وَتَأَخُّرُ الْإِمَامِ إِلَى وَقْتِ الصَّلَاةِ. وَإِذَا مَضَى فِي طَرِيقٍ يَرْجِعُ فِي أُخْرَى وَكَذَا الْجُمُعَةُ."]]},{"id":"da21_3","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٣","segs":[["matn","وَصَلَاةُ الْعِيدِ رَكْعَتَانِ يُكَبِّرُ فِي الْأُولَى بَعْدَ تَكْبِيرَةِ الْإِحْرَامِ وَقَبْلَ التَّعَوُّذِ سِتًّا وَفِي الثَّانِيَةِ قَبْلَ الْقِرَاءَةِ خَمْسًا يَرْفَعُ يَدَيْهِ مَعَ كُلِّ تَكْبِيرَةٍ وَيَقُولُ بَيْنَهُمَا:"]]},{"id":"da21_4","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٤","segs":[["matn","اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا وَصَلَّى اللَّهُ عَلَى مُحَمَّدٍ النَّبِيِّ وَآلِهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا ثُمَّ يَسْتَعِيذُ ثُمَّ يَقْرَأُ جَهْرًا الْفَاتِحَةَ ثُمَّ سَبِّحِ فِي الْأُولَى وَالْغَاشِيَةِ فِي الثَّانِيَةِ."]]},{"id":"da21_5","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٥","segs":[["matn","فَإِذَا سَلَّمَ خَطَبَ خُطْبَتَيْنِ وَأَحْكَامُهُمَا كَخُطْبَتَيِ الْجُمُعَةِ لَكِنْ يُسَنُّ أَنْ يَسْتَفْتِحَ الْأُولَى بِتِسْعِ. تَكْبِيرَاتٍ وَالثَّانِيَةَ بِسَبْعٍ. وَإِنْ صَلَّى الْعِيدَ كَالنَّافِلَةِ صَحَّ لِأَنَّ التَّكْبِيرَاتِ الزَّوَائِدَ وَالذِّكْرَ بَيْنَهُمَا وَالْخُطْبَتَيْنِ سُنَّةٌ. وَسُنَّ لِمَنْ فَاتَتْهُ قَضَاؤُهَا وَلَوْ بَعْدَ الزَّوَالِ."]]},{"id":"da21_6","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٦","segs":[["matn","فَصْلٌ: يُسَنُّ التَّكْبِيرُ الْمُطْلَقُ وَالْجَهْرُ بِهِ فِي لَيْلَتَيِ الْعِيدَيْنِ إِلَى فَرَاغِ الْخُطْبَةِ وَفِي كُلِّ عَشْرِ ذِي الْحِجَّةِ."]]},{"id":"da21_7","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٧","segs":[["matn","وَالتَّكْبِيرُ الْمُقَيَّدُ فِي الْأَضْحَى عَقِبَ كُلِّ فَرِيضَةٍ صَلَّاهَا فِي جَمَاعَةٍ مِنْ صَلَاةِ فَجْرِ يَوْمِ عَرَفَةَ إِلَى عَصْرِ آخِرِ أَيَّامِ التَّشْرِيقِ إِلَّا الْمُحْرِمَ فَيُكَبِّرُ مِنْ صَلَاةِ ظُهْرِ يَوْمِ النَّحْرِ وَيُكَبِّرُ الْإِمَامُ مُسْتَقْبِلَ النَّاسِ."]]},{"id":"da21_8","label":"بَابُ صَلَاةِ الْعِيدَيْنِ · ٨","segs":[["matn","وَصِفَتُهُ شَفْعًا: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ وَلِلَّهِ الْحَمْدُ. وَلَا بَأْسَ بِقَوْلِهِ لِغَيْرِهِ: تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكَ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da22","title":"بَابُ صَلَاةِ الْكُسُوفِ","units":[{"id":"da22_1","label":"بَابُ صَلَاةِ الْكُسُوفِ · ١","segs":[["matn","وَهِيَ سُنَّةٌ مِنْ غَيْرِ خُطْبَةٍ وَوَقْتُهَا مِنَ ابْتِدَاءِ الْكُسُوفِ إِلَى ذَهَابِهِ وَلَا تُقْضَى إِنْ فَاتَتْ."]]},{"id":"da22_2","label":"بَابُ صَلَاةِ الْكُسُوفِ · ٢","segs":[["matn","وَهِيَ رَكْعَتَانِ يَقْرَأُ فِي الْأُولَى جَهْرًا الْفَاتِحَةَ وَسُورَةً طَوِيلَةً ثُمَّ يَرْكَعُ طَوِيلًا ثُمَّ يَرْفَعُ فَيُسَمِّعُ وَيُحَمِّدُ وَلَا يَسْجُدُ بَلْ يَقْرَأُ الْفَاتِحَةَ وَسُورَةً طَوِيلَةً ثُمَّ يَرْكَعُ ثُمَّ يَرْفَعُ ثُمَّ يَسْجُدُ سَجْدَتَيْنِ طَوِيلَتَيْنِ ثُمَّ يُصَلِّي الثَّانِيَةَ كَالْأُولَى ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ."]]},{"id":"da22_3","label":"بَابُ صَلَاةِ الْكُسُوفِ · ٣","segs":[["matn","وَإِنْ أَتَى فِي كُلِّ رَكْعَةٍ بِثَلَاثَةِ رُكُوعَاتٍ أَوْ أَرْبَعٍ أَوْ خَمْسٍ فَلَا بَأْسَ. وَمَا بَعْدَ الْأَوَّلِ سُنَّةٌ لَا تُدْرَكُ بِهِ الرَّكْعَةُ. وَيَصِحُّ أَنْ يُصَلِّيَهَا كَالنَّافِلَةِ."]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da23","title":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ","units":[{"id":"da23_1","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ١","segs":[["matn","وَهِيَ سُنَّةٌ وَوَقْتُهَا وَصِفَتُهَا وَأَحْكَامُهَا كَصَلَاةِ الْعِيدِ. وَإِذَا أَرَادَ الْإِمَامُ الْخُرُوجَ لَهَا وَعَظَ النَّاسَ وَأَمَرَهُمْ بِالتَّوْبَةِ وَالْخُرُوجِ مِنَ الْمَظَالِمِ وَيَتَنَظَّفُ لَهَا وَلَا يَتَطَيَّبُ وَيَخْرُجُ مُتَوَاضِعًا مُتَخَشِّعًا مُتَذَلِّلًا مُتَضَرِّعًا وَمَعَهُ أَهْلُ الدِّينِ وَالصَّلَاحِ وَالشُّيُوخُ وَيُبَاحُ خُرُوجُ الْأَطْفَالِ وَالْعَجَائِزِ وَالْبَهَائِمِ وَالتَّوَسُّلُ بِالصَّالِحِينَ."]]},{"id":"da23_2","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٢","segs":[["matn","فَيُصَلِّي ثُمَّ يَخْطُبُ خُطْبَةً وَاحِدَةً يَفْتَتِحُهَا بِالتَّكْبِيرِ كَخُطْبَةِ الْعِيدِ وَيُكْثِرُ فِيهَا الِاسْتِغْفَارَ وَقِرَاءَةَ آيَاتٍ فِيهَا الْأَمْرُ بِهِ وَيَرْفَعُ يَدَيْهِ وَظُهُورُهُمَا نَحْوَ السَّمَاءِ فَيَدْعُو بِدُعَاءِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيُؤَمِّنُ الْمَأْمُومُ."]]},{"id":"da23_3","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٣","segs":[["matn","ثُمَّ يَسْتَقْبِلُ الْقِبْلَةَ فِي أَثْنَاءِ الْخُطْبَةِ فَيَقُولُ سِرًّا: اللَّهُمَّ إِنَّكَ أَمَرْتَنَا بِدُعَائِكَ وَوَعَدْتَنَا إِجَابَتَكَ وَقَدْ دَعَوْنَاكَ كَمَا أَمَرْتَنَا فَاسْتَجِبْ لَنَا كَمَا وَعَدْتَنَا ثُمَّ يُحَوِّلُ رِدَاءَهُ فَيَجْعَلُ الْأَيْمَنَ عَلَى الْأَيْسَرِ وَالْأَيْسَرَ عَلَى الْأَيْمَنِ وَكَذَا النَّاسُ وَيَتْرُكُونَهُ حَتَّى يَنْزِعُوهُ مَعَ ثِيَابِهِمْ."]]},{"id":"da23_4","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٤","segs":[["matn","فَإِنْ سُقُوا وَإِلَّا عَادُوا ثَانِيًا وَثَالِثًا. وَيُسَنُّ الْوُقُوفُ فِي أَوَّلِ الْمَطَرِ وَالْوُضُوءُ وَالِاغْتِسَالُ مِنْهُ وَإِخْرَاجُ رَحْلِهِ وَثِيَابِهِ لِيُصِيبَهَا."]]},{"id":"da23_5","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٥","segs":[["matn","وَإِنْ كَثُرَ الْمَطَرُ حَتَّى خِيفَ مِنْهُ سُنَّ قَوْلُ اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا اللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ وَبُطُونِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ، ﴿رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ﴾ الْآيَةَ."]]},{"id":"da23_6","label":"بَابُ صَلَاةِ الِاسْتِسْقَاءِ · ٦","segs":[["matn","وَسُنَّ قَوْلُ: مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ وَيَحْرُمُ: مُطِرْنَا بِنَوْءِ كَذَا وَيُبَاحُ: فِي نَوْءِ كَذَا"]]}],"group":"كِتَابُ الصَّلَاةِ"},{"id":"da24","title":"كِتَابُ الْجَنَائِزِ","units":[{"id":"da24_1","label":"كِتَابُ الْجَنَائِزِ · ١","segs":[["matn","يُسَنُّ: الِاسْتِعْدَادُ لِلْمَوْتِ وَالْإِكْثَارُ مِنْ ذِكْرِهِ. وَيُكْرَهُ الْأَنِينُ وَتَمَنِّي الْمَوْتِ إِلَّا لِخَوْفِ فِتْنَةٍ."]]},{"id":"da24_2","label":"كِتَابُ الْجَنَائِزِ · ٢","segs":[["matn","وَتُسَنُّ عِيَادَةُ الْمَرِيضِ الْمُسْلِمِ وَتَلْقِينُهُ عِنْدَ مَوْتِهِ لَا إِلَهَ إِلَّا اللَّهُ مَرَّةً وَلَمْ يَزِدْ إِلَّا أَنْ يَتَكَلَّمَ وَقِرَاءَةُ الْفَاتِحَةِ وَيس وَتَوْجِيهُهُ إِلَى الْقِبْلَةِ عَلَى جَنْبِهِ الْأَيْمَنِ مَعَ سَعَةِ الْمَكَانِ، وَإِلَّا فَعَلَى ظَهْرِهِ."]]},{"id":"da24_3","label":"كِتَابُ الْجَنَائِزِ · ٣","segs":[["matn","فَإِذَا مَاتَ، سُنَّ: تَغْمِيضُ عَيْنَيْهِ، وَقَوْلُ: بِسْمِ اللَّهِ وَعَلَى وَفَاةِ رَسُولِ اللَّهِ وَلَا بَأْسَ: بِتَقْبِيلِهِ وَالنَّظَرِ إِلَيْهِ وَلَوْ بَعْدَ تَكْفِينِهِ."]]},{"id":"da24_4","label":"كِتَابُ الْجَنَائِزِ · ٤","segs":[["matn","فَصْلٌ: وَغَسْلُ الْمَيِّتِ فَرْضُ كِفَايَةٍ. وَشُرِطَ فِي الْمَاءِ: الطَّهُورِيَّةُ وَالْإِبَاحَةُ وَفِي الْغَاسِلِ: الْإِسْلَامُ وَالْعَقْلُ وَالتَّمْيِيزُ. وَالْأَفْضَلُ: ثِقَةٌ عَارِفٌ بِأَحْكَامِ الْغَسْلِ. وَالْأَوْلَى بِهِ وَصِيُّهُ الْعَدْلُ."]]},{"id":"da24_5","label":"كِتَابُ الْجَنَائِزِ · ٥","segs":[["matn","وَإِذَا شَرَعَ فِي غَسْلِهِ سَتَرَ عَوْرَتَهُ وُجُوبًا ثُمَّ يُلَفُّ عَلَى يَدِهِ خِرْقَةٌ فَيُنَجِّيهِ بِهَا وَيَجِبُ غَسْلُ مَا بِهِ مِنْ نَجَاسَةٍ وَيَحْرُمُ مَسُّ عَوْرَةِ مَنْ بَلَغَ سَبْعَ سِنِينَ وَسُنَّ أَنْ لَا يَمَسَّ سَائِرَ بَدَنِهِ إِلَّا بِخِرْقَةٍ."]]},{"id":"da24_6","label":"كِتَابُ الْجَنَائِزِ · ٦","segs":[["matn","وَلِلرَّجُلِ: أَنْ يَغْسِلَ زَوْجَتَهُ وَأَمَتَهُ وَبِنْتًا دُونَ سَبْعٍ. وَلِلْمَرْأَةِ غَسْلُ زَوْجِهَا وَسَيِّدِهَا وَابْنِ دُونِ سَبْعٍ."]]},{"id":"da24_7","label":"كِتَابُ الْجَنَائِزِ · ٧","segs":[["matn","وَحُكْمُ غَسْلِ الْمَيِّتِ فِيمَا يَجِبُ وَيُسَنُّ كَغَسْلِ الْجَنَابَةِ لَكِنْ لَا يُدْخِلُ الْمَاءَ فِي فَمِهِ وَأَنْفِهِ بَلْ يَأْخُذُ خِرْقَةً مَبْلُولَةً فَيَمْسَحُ بِهَا أَسْنَانَهُ وَمِنْخَرَيْهِ."]]},{"id":"da24_8","label":"كِتَابُ الْجَنَائِزِ · ٨","segs":[["matn","وَيُكْرَهُ الِاقْتِصَارُ فِي غَسْلِهِ عَلَى مَرَّةٍ إِنْ لَمْ يَخْرُجْ مِنْهُ شَيْءٌ فَإِنْ خَرَجَ وَجَبَ إِعَادَةُ الْغَسْلِ إِلَى سَبْعٍ فَإِنْ خَرَجَ بَعْدَهَا حُشِيَ بِقُطْنٍ فَإِنْ لَمْ يَسْتَمْسِكْ فَبِطِينٍ حُرٍّ ثُمَّ يُغْسَلُ الْمَحَلُّ وَيُوَضَّأُ وُجُوبًا وَلَا غَسْلَ."]]},{"id":"da24_9","label":"كِتَابُ الْجَنَائِزِ · ٩","segs":[["matn","وَإِنْ خَرَجَ بَعْدَ تَكْفِينِهِ لَمْ يُعِدِ الْوُضُوءَ وَلَا الْغَسْلَ. وَشَهِيدُ الْمَعْرَكَةِ وَالْمَقْتُولُ ظُلْمًا لَا يُغَسَّلُ وَلَا يُكَفَّنُ وَلَا يُصَلَّى عَلَيْهِ وَيَجِبُ بَقَاءُ دَمِهِ عَلَيْهِ وَدَفْنُهُ فِي ثِيَابِهِ."]]},{"id":"da24_10","label":"كِتَابُ الْجَنَائِزِ · ١٠","segs":[["matn","وَإِنْ حُمِلَ فَأَكَلَ أَوْ شَرِبَ أَوْ نَامَ أَوْ بَالَ أَوْ تَكَلَّمَ أَوْ عَطَسَ أَوْ طَالَ بَقَاؤُهُ عُرْفًا أَوْ قُتِلَ وَعَلَيْهِ مَا يُوجِبُ الْغُسْلَ مِنْ نَحْوِ جَنَابَةٍ فَهُوَ كَغَيْرِهِ."]]},{"id":"da24_11","label":"كِتَابُ الْجَنَائِزِ · ١١","segs":[["matn","وَسِقْطٌ لِأَرْبَعَةِ أَشْهُرٍ كَالْمَوْلُودِ حَيًّا. وَلَا يُغَسِّلُ مُسْلِمٌ كَافِرًا وَلَوْ ذِمِّيًّا وَلَا يُصَلِّي عَلَيْهِ وَلَا يَتَّبِعُ جِنَازَتَهُ بَلْ يُوَارَى لِعَدَمِ مَنْ يُوَارِيهِ."]]},{"id":"da24_12","label":"كِتَابُ الْجَنَائِزِ · ١٢","segs":[["matn","فَصْلٌ: وَتَكْفِينُهُ فَرْضُ كِفَايَةٍ. وَالْوَاجِبُ: سَتْرُ جَمِيعِهِ سِوَى رَأْسِ الْمُحْرِمِ وَوَجْهِ الْمُحْرِمَةِ بِثَوْبٍ لَا يَصِفُ الْبَشَرَةَ وَيَجِبُ أَنْ يَكُونَ مِنْ مَلْبُوسِ مِثْلِهِ مَا لَمْ يُوصِ بِدُونِهِ."]]},{"id":"da24_13","label":"كِتَابُ الْجَنَائِزِ · ١٣","segs":[["matn","وَالسُّنَّةُ: تَكْفِينُ الرَّجُلِ فِي: ثَلَاثِ لَفَائِفَ بِيضٍ مِنْ قُطْنٍ تُبْسَطُ عَلَى بَعْضِهَا وَيُوضَعُ عَلَيْهَا مُسْتَلْقِيًا ثُمَّ يُرَدُّ طَرَفُ الْعُلْيَا مِنَ الْجَانِبِ الْأَيْسَرِ عَلَى شِقِّهِ الْأَيْمَنِ"]]},{"id":"da24_14","label":"كِتَابُ الْجَنَائِزِ · ١٤","segs":[["matn","ثُمَّ طَرَفُهَا الْأَيْمَنُ عَلَى الْأَيْسَرِ ثُمَّ الثَّانِيَةُ ثُمَّ الثَّالِثَةُ كَذَلِكَ وَالْأُنْثَى فِي خَمْسَةِ أَثْوَابٍ بِيضٍ مِنْ قُطْنٍ:"]]},{"id":"da24_15","label":"كِتَابُ الْجَنَائِزِ · ١٥","segs":[["matn","إِزَارٍ وَخِمَارٍ وَقَمِيصٍ وَلِفَافَتَيْنِ وَالصَّبِيُّ فِي ثَوْبٍ، وَيُبَاحُ فِي ثَلَاثَةٍ وَالصَّغِيرَةُ فِي قَمِيصٍ وَلِفَافَتَيْنِ. وَيُكْرَهُ: التَّكْفِينُ بِشَعَرٍ وَصُوفٍ وَمُزَعْفَرٍ وَمُعَصْفَرٍ وَمَنْقُوشٍ. وَيَحْرُمُ: بِجِلْدٍ وَحَرِيرٍ وَمُذَهَّبٍ."]]},{"id":"da24_16","label":"كِتَابُ الْجَنَائِزِ · ١٦","segs":[["matn","فَصْلٌ: وَالصَّلَاةُ عَلَيْهِ فَرْضُ كِفَايَةٍ. وَتَسْقُطُ بِمُكَلَّفٍ وَلَوْ أُنْثَى."]]},{"id":"da24_17","label":"كِتَابُ الْجَنَائِزِ · ١٧","segs":[["matn","وَشُرُوطُهَا ثَمَانِيَةٌ: النِّيَّةُ وَالتَّكْلِيفُ وَاسْتِقْبَالُ الْقِبْلَةِ وَسَتْرُ الْعَوْرَةِ وَاجْتِنَابُ النَّجَاسَةِ وَحُضُورُ الْمَيِّتِ إِنْ كَانَ بِالْبَلَدِ وَإِسْلَامُ الْمُصَلِّي وَالْمُصَلَّى عَلَيْهِ وَطَهَارَتُهُمَا وَلَوْ بِتُرَابٍ لِعُذْرٍ."]]},{"id":"da24_18","label":"كِتَابُ الْجَنَائِزِ · ١٨","segs":[["matn","وَأَرْكَانُهَا سَبْعَةٌ: الْقِيَامُ فِي فَرْضِهَا وَالتَّكْبِيرَاتُ الْأَرْبَعُ وَقِرَاءَةُ الْفَاتِحَةِ وَالصَّلَاةُ عَلَى مُحَمَّدٍ وَالدُّعَاءُ لِلْمَيِّتِ وَالسَّلَامُ وَالتَّرْتِيبُ لَكِنْ لَا يَتَعَيَّنُ كَوْنُ الدُّعَاءِ فِي الثَّالِثَةِ بَلْ يَجُوزُ بَعْدَ الرَّابِعَةِ."]]},{"id":"da24_19","label":"كِتَابُ الْجَنَائِزِ · ١٩","segs":[["matn","وَصِفَتُهَا: أَنْ يَنْوِيَ ثُمَّ يُكَبِّرَ وَيَقْرَأَ الْفَاتِحَةَ ثُمَّ يُكَبِّرَ وَيُصَلِّيَ عَلَى مُحَمَّدٍ كَفِي التَّشَهُّدِ ثُمَّ يُكَبِّرَ وَيَدْعُوَ لِلْمَيِّتِ بِنَحْوِ:"]]},{"id":"da24_20","label":"كِتَابُ الْجَنَائِزِ · ٢٠","segs":[["matn","اللَّهُمَّ ارْحَمْهُ ثُمَّ يُكَبِّرُ وَيَقِفُ بَعْدَهَا قَلِيلًا وَيُسَلِّمُ وَتُجْزِئُ: وَاحِدَةٌ وَلَوْ لَمْ يَقُلْ وَرَحْمَةُ اللَّهِ وَيَجُوزُ: أَنْ يُصَلِّيَ عَلَى الْمَيِّتِ مِنْ دَفْنِهِ إِلَى شَهْرٍ وَشَيْءٍ وَيَحْرُمُ: بَعْدَ ذَلِكَ."]]},{"id":"da24_21","label":"كِتَابُ الْجَنَائِزِ · ٢١","segs":[["matn","فَصْلٌ: وَحَمْلُهُ وَدَفْنُهُ: فَرْضُ كِفَايَةٍ لَكِنْ يَسْقُطُ الْحَمْلُ وَالدَّفْنُ وَالتَّكْفِينُ بِالْكَافِرِ. وَيُكْرَهُ: أَخْذُ الْأُجْرَةِ عَلَى ذَلِكَ وَعَلَى الْغَسْلِ. وَسُنَّ: كَوْنُ الْمَاشِي أَمَامَ الْجِنَازَةِ وَالرَّاكِبِ خَلْفَهَا. وَالْقُرْبُ مِنْهَا أَفْضَلُ."]]},{"id":"da24_22","label":"كِتَابُ الْجَنَائِزِ · ٢٢","segs":[["matn","وَيُكْرَهُ: الْقِيَامُ لَهَا وَرَفْعُ الصَّوْتِ مَعَهَا وَلَوْ بِالذِّكْرِ وَالْقُرْآنِ. وَسُنَّ: أَنْ يُعَمَّقَ الْقَبْرُ وَيُوَسِّعَ بِلَا حَدٍّ وَيَكْفِي مَا يَمْنَعُ السِّبَاعَ وَالرَّائِحَةَ."]]},{"id":"da24_23","label":"كِتَابُ الْجَنَائِزِ · ٢٣","segs":[["matn","وَكُرِهَ: إِدْخَالُ الْقَبْرِ خَشَبًا وَمَا مَسَّتْهُ نَارٌ وَوَضْعُ فِرَاشٍ تَحْتَهُ وَجَعْلُ مِخَدَّةٍ تَحْتَ رَأْسِهِ."]]},{"id":"da24_24","label":"كِتَابُ الْجَنَائِزِ · ٢٤","segs":[["matn","وَسُنَّ: قَوْلُ مُدْخِلِهِ الْقَبْرَ: بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ وَيَجِبُ: أَنْ يَسْتَقْبِلَ بِهِ الْقِبْلَةَ وَيُسَنُّ عَلَى جَنْبِهِ الْأَيْمَنِ. وَيَحْرُمُ: دَفْنُ غَيْرِهِ عَلَيْهِ أَوْ مَعَهُ إِلَّا لِضَرُورَةٍ."]]},{"id":"da24_25","label":"كِتَابُ الْجَنَائِزِ · ٢٥","segs":[["matn","وَسُنَّ: حَثْوُ التُّرَابِ عَلَيْهِ ثَلَاثًا ثُمَّ يُهَالُ. وَاسْتَحَبَّ الْأَكْثَرُ تَلْقِينَهُ وَسُنَّ: رَشُّ الْقَبْرِ بِالْمَاءِ، وَرَفْعُهُ قَدْرَ شِبْرٍ."]]},{"id":"da24_26","label":"كِتَابُ الْجَنَائِزِ · ٢٦","segs":[["matn","وَيُكْرَهُ: تَزْوِيقُهُ وَتَجْصِيصُهُ وَتَبْخِيرُهُ وَتَقْبِيلُهُ وَالطَّوَافُ بِهِ وَالِاتِّكَاءُ إِلَيْهِ وَالْمَبِيتُ وَالضَّحِكُ عِنْدَهُ وَالْحَدِيثُ فِي أَمْرِ الدُّنْيَا وَالْكِتَابَةُ عَلَيْهِ وَالْجُلُوسُ وَالْبِنَاءُ وَالْمَشْيُ بِالنَّعْلِ إِلَّا لِخَوْفِ شَوْكٍ وَنَحْوِهِ."]]},{"id":"da24_27","label":"كِتَابُ الْجَنَائِزِ · ٢٧","segs":[["matn","وَيَحْرُمُ: إِسْرَاجُ الْمَقَابِرِ وَالدَّفْنُ بِالْمَسَاجِدِ وَفِي مِلْكِ الْغَيْرِ وَيُنْبَشُ. وَالدَّفْنُ بِالصَّحْرَاءِ أَفْضَلُ."]]},{"id":"da24_28","label":"كِتَابُ الْجَنَائِزِ · ٢٨","segs":[["matn","وَإِنْ مَاتَتِ الْحَامِلُ حَرُمَ شَقُّ بَطْنِهَا وَأَخْرَجَ النِّسَاءُ مَنْ تُرْجَى حَيَاتُهُ فَإِنْ تَعَذَّرَ لَمْ تُدْفَنْ حَتَّى يَمُوتَ وَإِنْ خَرَجَ بَعْضُهُ حَيًّا شُقَّ لِلْبَاقِي."]]},{"id":"da24_29","label":"كِتَابُ الْجَنَائِزِ · ٢٩","segs":[["matn","فَصْلٌ: تُسَنُّ: تَعْزِيَةُ الْمُسْلِمِ إِلَى ثَلَاثَةِ أَيَّامٍ فَيُقَالُ لَهُ: أَعْظَمَ اللَّهُ أَجْرَكَ وَأَحْسَنَ عَزَاءَكَ وَغَفَرَ لِمَيِّتِكَ وَيَقُولُ هُوَ: اسْتَجَابَ اللَّهُ دُعَاءَكَ وَرَحِمَنَا وَإِيَّاكَ وَلَا بَأْسَ: بِالْبُكَاءِ عَلَى الْمَيِّتِ."]]},{"id":"da24_30","label":"كِتَابُ الْجَنَائِزِ · ٣٠","segs":[["matn","وَيَحْرُمُ: النَّدْبُ وَهُوَ: الْبُكَاءُ مَعَ تَعْدَادِ مَحَاسِنِ الْمَيِّتِ وَالنِّيَاحَةُ وَهِيَ: رَفْعُ الصَّوْتِ بِذَلِكَ بِرَنَّةٍ وَيَحْرُمُ شَقُّ الثَّوْبِ وَلَطْمُ الْخَدِّ وَالصُّرَاخُ وَنَتْفُ الشَّعْرِ وَنَشْرُهُ وَحَلْقُهُ."]]},{"id":"da24_31","label":"كِتَابُ الْجَنَائِزِ · ٣١","segs":[["matn","وَتُسَنُّ: زِيَارَةُ الْقُبُورِ لِلرِّجَالِ وَتُكْرَهُ لِلنِّسَاءِ وَإِنِ اجْتَازَتِ الْمَرْأَةُ بِقَبْرٍ فِي طَرِيقِهَا فَسَلَّمَتْ عَلَيْهِ وَدَعَتْ لَهُ فَحَسَنٌ. وَسُنَّ: لِمَنْ زَارَ الْقُبُورَ أَوْ مَرَّ بِهَا أَنْ يَقُولَ:"]]},{"id":"da24_32","label":"كِتَابُ الْجَنَائِزِ · ٣٢","segs":[["matn","السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنْكُمْ وَالْمُسْتَأْخِرِينَ نَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُمْ وَلَا تَفْتِنَّا بَعْدَهُمْ وَاغْفِرْ لَنَا وَلَهُمْ وَابْتِدَاءُ السَّلَامِ عَلَى الْحَيِّ سُنَّةٌ وَرَدُّهُ فَرْضُ كِفَايَةٍ."]]},{"id":"da24_33","label":"كِتَابُ الْجَنَائِزِ · ٣٣","segs":[["matn","وَتَشْمِيتُ الْعَاطِسِ إِذَا حَمِدَ فَرْضُ كِفَايَةٍ. وَرَدُّهُ: فَرْضُ عَيْنٍ. وَيَعْرِفُ الْمَيِّتُ زَائِرَهُ يَوْمَ الْجُمُعَةِ قَبْلَ طُلُوعِ الشَّمْسِ. وَيَتَأَذَّى بِالْمُنْكَرِ عِنْدَهُ وَيَنْتَفِعُ بِالْخَيْرِ."]]}],"group":"كِتَابُ الْجَنَائِزِ"},{"id":"da25","title":"كِتَابُ الزَّكَاةِ","units":[{"id":"da25_1","label":"كِتَابُ الزَّكَاةِ · ١","segs":[["matn","شَرْطُ وُجُوبِهَا خَمْسَةُ أَشْيَاءَ. أَحَدُهَا: الْإِسْلَامُ فَلَا تَجِبُ عَلَى الْكَافِرِ وَلَوْ مُرْتَدًّا. الثَّانِي: الْحُرِّيَّةُ فَلَا تَجِبُ عَلَى الرَّقِيقِ وَلَوْ مُكَاتَبًا لَكِنْ تَجِبُ عَلَى الْمُبَعَّضِ بِقَدْرِ مِلْكِهِ."]]},{"id":"da25_2","label":"كِتَابُ الزَّكَاةِ · ٢","segs":[["matn","الثَّالِثُ: مِلْكُ النِّصَابِ تَقْرِيبًا فِي الْأَثْمَانِ وَتَحْدِيدًا فِي غَيْرِهَا. الرَّابِعُ: الْمِلْكُ التَّامُّ فَلَا زَكَاةَ عَلَى السَّيِّدِ فِي دَيْنِ الْكِتَابَةِ وَلَا فِي حِصَّةِ الْمُضَارِبِ قَبْلَ الْقِسْمَةِ."]]},{"id":"da25_3","label":"كِتَابُ الزَّكَاةِ · ٣","segs":[["matn","الْخَامِسُ: تَمَامُ الْحَوْلِ وَلَا يَضُرُّ لَوْ نَقَصَ نِصْفَ يَوْمٍ. وَتَجِبُ فِي مَالِ الصَّغِيرِ وَالْمَجْنُونِ."]]},{"id":"da25_4","label":"كِتَابُ الزَّكَاةِ · ٤","segs":[["matn","وَهِيَ فِي خَمْسَةِ أَشْيَاءَ: فِي سَائِمَةِ بَهِيمَةِ الْأَنْعَامِ وَفِي الْخَارِجِ مِنَ الْأَرْضِ وَفِي الْعَسَلِ وَفِي الْأَثْمَانِ وَفِي عُرُوضِ التِّجَارَةِ. وَيَمْنَعُ: وُجُوبَهَا دَيْنٌ يُنْقِصُ النِّصَابَ. وَمَنْ مَاتَ وَعَلَيْهِ زَكَاةٌ أُخِذَتْ مِنْ تَرِكَتِهِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da26","title":"بَابُ زَكَاةِ السَّائِمَةِ","units":[{"id":"da26_1","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١","segs":[["matn","تَجِبُ فِيهَا بِثَلَاثَةِ شُرُوطٍ: أَحَدُهَا: أَنْ تُتَّخَذَ لِلدَّرِّ وَالنَّسْلِ وَالتَّسْمِينِ لَا لِلْعَمَلِ. الثَّانِي: أَنْ تَسُومَ أَيْ: تَرْعَى الْمُبَاحَ أَكْثَرَ الْحَوْلِ. الثَّالِثُ: أَنْ تَبْلُغَ نِصَابًا."]]},{"id":"da26_2","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٢","segs":[["matn","فَأَقَلُّ نِصَابِ الْإِبِلِ خَمْسٌ وَفِيهَا شَاةٌ ثُمَّ فِي كُلِّ خَمْسٍ شَاةٌ إِلَى خَمْسٍ وَعِشْرِينَ فَتَجِبُ بِنْتُ مَخَاضٍ وَهِيَ مَا تَمَّ لَهَا سَنَةٌ وَفِي سِتٍّ وَثَلَاثِينَ بِنْتُ لَبُونٍ لَهَا سَنَتَانِ"]]},{"id":"da26_3","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٣","segs":[["matn","وَفِي سِتٍّ وَأَرْبَعِينَ حِقَّةٌ لَهَا ثَلَاثُ سِنِينَ وَفِي إِحْدَى وَسِتِّينَ جَذَعَةٌ لَهَا أَرْبَعُ سِنِينَ وَفِي سِتٍّ وَسَبْعِينَ بِنْتَا لَبُونٍ وَفِي إِحْدَى وَتِسْعِينَ حِقَّتَانِ وَفِي مِائَةٍ وَإِحْدَى وَعِشْرِينَ:"]]},{"id":"da26_4","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٤","segs":[["matn","ثَلَاثُ بَنَاتِ لَبُونٍ إِلَى مِائَةٍ وَثَلَاثِينَ فَيَسْتَقِرُّ فِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ وَفِي كُلِّ خَمْسِينَ: حِقَّةٌ."]]},{"id":"da26_5","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٥","segs":[["matn","فَصْلٌ: وَأَقَلُّ نِصَابِ الْبَقَرِ أَهْلِيَّةً كَانَتْ أَوْ وَحْشِيَّةً ثَلَاثُونَ وَفِيهَا تَبِيعٌ وَهُوَ مَا لَهُ سَنَةٌ وَفِي أَرْبَعِينَ مُسِنَّةٌ لَهَا سَنَتَانِ وَفِي سِتِّينَ تَبِيعَانِ ثُمَّ فِي كُلِّ ثَلَاثِينَ تَبِيعٌ وَفِي كُلِّ أَرْبَعِينَ مُسِنَّةٌ."]]},{"id":"da26_6","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٦","segs":[["matn","وَأَقَلُّ نِصَابِ الْغَنَمِ أَهْلِيَّةً كَانَتْ أَوْ وَحْشِيَّةً أَرْبَعُونَ وَفِيهَا شَاةٌ: لَهَا سَنَةٌ أَوْ جَذَعَةُ ضَأْنٍ: لَهَا سِتَّةُ أَشْهُرٍ وَفِي مِائَةٍ وَإِحْدَى وَعِشْرِينَ: شَاتَانِ وَفِي مِائَتَيْنِ وَوَاحِدَةٍ ثَلَاثُ شِيَاهٍ وَفِي أَرْبَعِمِائَةٍ أَرْبَعُ شِيَاهٍ ثُمَّ فِي كُلِّ مِائَةٍ شَاةٌ"]]},{"id":"da26_7","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٧","segs":[["matn","فَصْلٌ: وَإِذَا اخْتَلَطَ اثْنَانِ فَأَكْثَرُ مِنْ أَهْلِ الزَّكَاةِ فِي نِصَابِ مَاشِيَةٍ لَهُمْ جَمِيعَ الْحَوْلِ وَاشْتَرَكَا فِي الْمَبِيتِ وَالْمَسْرَحِ وَالْمَحْلَبِ وَالْفَحْلِ، وَالْمَرْعَى زُكِّيَا كَالْوَاحِدِ."]]},{"id":"da26_8","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٨","segs":[["matn","وَلَا تُشْتَرَطُ: نِيَّةُ الْخِلْطَةِ وَلَا اتِّحَادُ الْمَشْرَبِ وَالرَّاعِي وَلَا اتِّحَادُ الْفَحْلِ إِنِ اخْتَلَفَ النَّوْعُ: كَالْبَقَرِ وَالْجَامُوسِ وَالضَّأْنِ وَالْمَعْزِ."]]},{"id":"da26_9","label":"بَابُ زَكَاةِ السَّائِمَةِ · ٩","segs":[["matn","وَقَدْ تُفِيدُ الْخِلْطَةُ تَغْلِيظًا كَاثْنَيْنِ اخْتَلَطَا بِأَرْبَعِينَ شَاةً لِكُلِّ وَاحِدٍ عِشْرُونَ فَيَلْزَمُهُمَا شَاةٌ وَتَخْفِيفًا كَثَلَاثَةٍ اخْتَلَطُوا بِمِائَةٍ وَعِشْرِينَ شَاةً لِكُلِّ وَاحِدٍ أَرْبَعُونَ فَيَلْزَمُهُمْ شَاةٌ."]]},{"id":"da26_10","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١٠","segs":[["matn","وَلَا أَثَرَ لِتَفْرِقَةِ الْمَالِ مَا لَمْ يَكُنْ سَائِمَةً."]]},{"id":"da26_11","label":"بَابُ زَكَاةِ السَّائِمَةِ · ١١","segs":[["matn","فَإِنْ كَانَتْ سَائِمَةً بِمَحَلَّيْنِ بَيْنَهُمَا مَسَافَةُ قَصْرٍ فَلِكُلٍّ حُكْمُ نَفْسِهِ فَإِذَا كَانَ لَهُ شِيَاهٌ بِمَحَالَّ مُتَبَاعِدَةٍ فِي كُلِّ مَحَلٍّ أَرْبَعُونَ فَعَلَيْهِ شِيَاهٌ بِعَدَدِ الْمَحَالِّ وَلَا شَيْءَ عَلَيْهِ إِنْ لَمْ يَجْتَمِعْ فِي كُلِّ مَحَلٍّ أَرْبَعُونَ مَا لَمْ يَكُنْ خِلْطَةً."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da27","title":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ","units":[{"id":"da27_1","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ١","segs":[["matn","تَجِبُ: فِي كُلِّ مَكِيلٍ مُدَّخَرٍ مِنَ الْحَبِّ كَالْقَمْحِ وَالشَّعِيرِ وَالذُّرَةِ وَالْأَرُزِّ وَالْحِمِّصِ وَالْعَدَسِ وَالْبَاقِلَّا وَالْكِرْسَنَةِ وَالسِّمْسِمِ وَالدُّخْنِ وَالْكَرَاوْيَا وَالْكُزْبَرَةِ وَبِزْرِ الْقُطْنِ وَالْكَتَّانِ وَالْبَطِّيخِ وَنَحْوِهِ وَمِنَ الثَّمَرِ: كَالتَّمْرِ وَالزَّبِيبِ وَاللَّوْزِ وَالْفُسْتُقِ وَالْبُنْدُقِ وَالسُّمَّاقِ."]]},{"id":"da27_2","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٢","segs":[["matn","وَلَا زَكَاةَ فِي عُنَّابٍ وَزَيْتُونٍ وَجَوْزٍ وَتِينٍ وَمِشْمِشٍ وَتُوتٍ وَنَبْقٍ وَزَعْرُورٍ وَرُمَّانٍ."]]},{"id":"da27_3","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٣","segs":[["matn","وَإِنَّمَا تَجِبُ فِيمَا تَجِبُ بِشَرْطَيْنِ: الْأَوَّلُ: أَنْ يَبْلُغَ نِصَابًا وَقَدْرُهُ بَعْدَ تَصْفِيَةِ الْحَبِّ وَجَفَافِ الثَّمَرِ خَمْسَةُ أَوْسُقٍ وَهِيَ: ثَلَاثُمِائَةِ صَاعٍ وَبِالْأَرَادِبِّ: سِتَّةُ وَرُبُعُ وَبِالرِّطْلِ الْعِرَاقِيِّ: أَلْفٌ وَسِتُّمِائَةِ وَبِالْقُدْسِيِّ مِائَتَانِ وَسَبْعَةٌ وَخَمْسُونَ وَسُبْعُ رِطْلٍ."]]},{"id":"da27_4","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٤","segs":[["matn","الثَّانِي: أَنْ يَكُونَ مَالِكًا لِلنِّصَابِ وَقْتَ وُجُوبِهَا فَوَقْتُ الْوُجُوبِ فِي الْحَبِّ إِذَا اشْتَدَّ وَفِي الثَّمَرَةِ إِذَا بَدَا صَلَاحُهَا."]]},{"id":"da27_5","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٥","segs":[["matn","فَصْلٌ: وَيَجِبُ فِيمَا يُسْقَى بِلَا كُلْفَةٍ الْعُشْرُ وَفِيمَا يُسْقَى بِكُلْفَةٍ نِصْفُ الْعُشْرِ. وَيَجِبُ إِخْرَاجُ زَكَاةِ الْحَبِّ مُصَفًّى وَالثَّمَرِ: يَابِسًا فَلَوْ خَالَفَ وَأَخْرَجَ رُطَبًا لَمْ يُجْزِهِ وَوَقَعَ نَفْلًا."]]},{"id":"da27_6","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٦","segs":[["matn","وَسُنَّ: لِلْإِمَامِ بَعْثُ خَارِصٍ لِثَمَرَةِ النَّخْلِ وَالْكَرْمِ إِذَا بَدَا صَلَاحُهَا وَيَكْفِي وَاحِدٌ وَشُرِطَ كَوْنُهُ مُسْلِمًا أَمِينًا خَبِيرًا وَأُجْرَتُهُ عَلَى رَبِّ الثَّمَرَةِ."]]},{"id":"da27_7","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٧","segs":[["matn","وَيَجِبُ عَلَيْهِ: بَعْثُ السُّعَاةِ قُرْبَ الْوُجُوبِ لِقَبْضِ زَكَاةِ الْمَالِ الظَّاهِرِ وَيَجْتَمِعُ الْعُشْرُ وَالْخَرَاجُ فِي الْأَرْضِ الْخَرَاجِيَّةِ وَهِيَ مَا فُتِحَتْ عَنْوَةً وَلَمْ تُقْسَمْ بَيْنَ الْغَانِمِينَ كَمِصْرَ وَالشَّامِ وَالْعِرَاقِ."]]},{"id":"da27_8","label":"بَابُ زَكَاةِ الْخَارِجِ مِنَ الْأَرْضِ · ٨","segs":[["matn","وَتَضْمِينُ أَمْوَالِ الْعُشْرِ وَالْأَرْضِ الْخَرَاجِيَّةِ بَاطِلٌ. وَفِي الْعَسَلِ الْعُشْرُ وَنِصَابُهُ مِائَةٌ وَسِتُّونَ رِطْلًا عِرَاقِيَّةً. وَفِي الرِّكَازِ: وَهُوَ الْكَنْزُ وَلَوْ قَلِيلًا الْخُمُسُ وَلَا يَمْنَعُ مِنْ وُجُوبِهِ الدَّيْنُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da28","title":"بَابُ زَكَاةِ الْأَثْمَانِ","units":[{"id":"da28_1","label":"بَابُ زَكَاةِ الْأَثْمَانِ · ١","segs":[["matn","وَهِيَ: الذَّهَبُ وَالْفِضَّةُ. وَفِيهَا: رُبُعُ الْعُشْرِ إِذَا بَلَغَتْ نِصَابًا فَنِصَابُ الذَّهَبِ بِالْمَثَاقِيلِ:"]]},{"id":"da28_2","label":"بَابُ زَكَاةِ الْأَثْمَانِ · ٢","segs":[["matn","عِشْرُونَ مِثْقَالًا وَبِالدَّنَانِيرِ خَمْسَةٌ وَعِشْرُونَ وَسُبُعَا دِينَارٍ وَتُسْعُ دِينَارٍ وَنِصَابُ الْفِضَّةِ مِائَتَا دِرْهَمٍ وَالدِّرْهَمُ اثْنَتَا عَشْرَةَ حَبَّةَ خَرُّوبٍ وَالْمِثْقَالُ دِرْهَمٌ وَثَلَاثَةُ أَسْبَاعِ دِرْهَمٍ وَيُضَمُّ الذَّهَبُ إِلَى الْفِضَّةِ فِي تَكْمِيلِ النِّصَابِ وَيُخْرِجُ مِنْ أَيِّهِمَا شَاءَ."]]},{"id":"da28_3","label":"بَابُ زَكَاةِ الْأَثْمَانِ · ٣","segs":[["matn","وَلَا زَكَاةَ فِي حُلِيٍّ مُبَاحٍ مُعَدٍّ لِاسْتِعْمَالٍ أَوْ إِعَارَةٍ. وَتَجِبُ: فِي الْحُلِيِّ الْمُحَرَّمِ وَكَذَا فِي الْمُبَاحِ الْمُعَدِّ لِلْكِرَاءِ أَوِ النَّفَقَةِ إِذَا بَلَغَ نِصَابًا وَزْنًا وَيُخْرِجُ عَنْ قِيمَتِهِ إِنْ زَادَتْ."]]},{"id":"da28_4","label":"بَابُ زَكَاةِ الْأَثْمَانِ · ٤","segs":[["matn","فَصْلٌ: وَتَحْرُمُ: تَحْلِيَةُ الْمَسْجِدِ بِذَهَبٍ. أَوْ فِضَّةٍ وَيُبَاحُ لِلذَّكَرِ مِنَ الْفِضَّةِ الْخَاتَمُ وَلَوْ زَادَ عَلَى مِثْقَالٍ وَجَعْلُهُ بِخِنْصَرِ يَسَارٍ أَفْضَلُ وَتُبَاحُ قَبِيعَةُ السَّيْفِ فَقَطْ وَلَوْ مِنْ ذَهَبٍ، وَحِلْيَةُ الْمِنْطَقَةِ وَالْجَوْشَنِ وَالْخُوذَةِ لَا الرِّكَابِ وَاللِّجَامِ وَالدَّوَاةِ."]]},{"id":"da28_5","label":"بَابُ زَكَاةِ الْأَثْمَانِ · ٥","segs":[["matn","وَيُبَاحُ لِلنِّسَاءِ: مَا جَرَتْ عَادَتُهُنَّ بِلُبْسِهِ وَلَوْ زَادَ عَلَى أَلْفِ مِثْقَالٍ. وَلِلرَّجُلِ، وَالْمَرْأَةِ: التَّحَلِّي بِالْجَوْهَرِ، وَالْيَاقُوتِ وَالزَّبَرْجَدِ. وَكُرِهَ: تَخَتُّمُهُمَا بِالْحَدِيدِ وَالرَّصَاصِ وَالنُّحَاسِ. وَيُسْتَحَبُّ: بِالْعَقِيقِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da29","title":"بَابُ زَكَاةِ الْعُرُوضِ","units":[{"id":"da29_1","label":"بَابُ زَكَاةِ الْعُرُوضِ · ١","segs":[["matn","وَهِيَ: مَا يُعَدُّ لِلْبَيْعِ وَالشِّرَاءِ لِأَجْلِ الرِّبْحِ فَتُقَوَّمُ إِذَا حَالَ الْحَوْلُ عَلَيْهَا وَأَوَّلُهُ مِنْ حِينِ بُلُوغِ الْقِيمَةِ نِصَابًا بِالْأَحَظِّ لِلْمَسَاكِينِ مِنْ ذَهَبٍ أَوْ فِضَّةٍ فَإِنْ بَلَغَتِ الْقِيمَةُ نِصَابًا وَجَبَ رُبُعُ الْعُشْرِ وَإِلَّا فَلَا، وَكَذَا أَمْوَالُ الصَّيَارِفِ."]]},{"id":"da29_2","label":"بَابُ زَكَاةِ الْعُرُوضِ · ٢","segs":[["matn","وَلَا عِبْرَةَ بِقِيمَةِ آنِيَةِ الذَّهَبِ وَالْفِضَّةِ بَلْ بِوَزْنِهَا وَلَا بِمَا فِيهِ صِنَاعَةٌ مُحَرَّمَةٌ فَيُقَوَّمُ عَارِيًا عَنْهَا وَمَنْ عِنْدَهُ عَرْضٌ لِلتِّجَارَةِ أَوْ وَرِثَهُ فَنَوَاهُ لِلْقُنْيَةِ ثُمَّ نَوَاهُ لِلتِّجَارَةِ لَمْ يَصِرْ عَرْضًا بِمُجَرَّدِ النِّيَّةِ غَيْرَ حُلِيِّ اللُّبْسِ."]]},{"id":"da29_3","label":"بَابُ زَكَاةِ الْعُرُوضِ · ٣","segs":[["matn","وَمَا اسْتُخْرِجَ مِنَ الْمَعَادِنِ فَفِيهِ بِمُجَرَّدِ إِحْرَازِهِ رُبُعُ الْعُشْرِ إِنْ بَلَغَتِ الْقِيمَةُ نِصَابًا بَعْدَ السَّبْكِ وَالتَّصْفِيَةِ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da30","title":"بَابُ زَكَاةِ الْفِطْرِ","units":[{"id":"da30_1","label":"بَابُ زَكَاةِ الْفِطْرِ · ١","segs":[["matn","تَجِبُ: بِأَوَّلِ لَيْلَةِ الْعِيدِ فَمَنْ مَاتَ أَوْ أَعْسَرَ قَبْلَ الْغُرُوبِ فَلَا زَكَاةَ عَلَيْهِ وَبَعْدَهُ تَسْتَقِرُّ فِي ذِمَّتِهِ."]]},{"id":"da30_2","label":"بَابُ زَكَاةِ الْفِطْرِ · ٢","segs":[["matn","وَهِيَ وَاجِبَةٌ عَلَى كُلِّ مُسْلِمٍ يَجِدُ مَا يَفْضُلُ عَنْ قُوتِهِ وَقُوتِ عِيَالِهِ يَوْمَ الْعِيدِ وَلَيْلَتَهُ بَعْدَ مَا يَحْتَاجُهُ مِنْ مَسْكَنٍ وَخَادِمٍ وَدَابَّةٍ وَثِيَابِ بِذْلَةٍ وَكُتُبِ عِلْمٍ."]]},{"id":"da30_3","label":"بَابُ زَكَاةِ الْفِطْرِ · ٣","segs":[["matn","وَتَلْزَمُهُ: عَنْ نَفْسِهِ وَعَنْ مَنْ يَمُونُهُ مِنَ الْمُسْلِمِينَ. فَإِنْ لَمْ يَجِدْ لِجَمِيعِهِمْ بَدَأَ بِنَفْسِهِ فَزَوْجَتِهِ فَرَقِيقِهِ فَأُمِّهِ فَأَبِيهِ فَوَلَدِهِ فَأَقْرَبَ فِي الْمِيرَاثِ."]]},{"id":"da30_4","label":"بَابُ زَكَاةِ الْفِطْرِ · ٤","segs":[["matn","وَتَجِبُ عَلَى مَنْ تَبَرَّعَ بِمُؤْنَةِ شَخْصٍ شَهْرَ رَمَضَانَ لَا عَلَى مَنِ اسْتَأْجَرَ أَجِيرًا بِطَعَامِهِ وَتُسَنُّ عَنِ الْجَنِينِ."]]},{"id":"da30_5","label":"بَابُ زَكَاةِ الْفِطْرِ · ٥","segs":[["matn","فَصْلٌ: وَالْأَفْضَلُ: إِخْرَاجُهَا يَوْمَ الْعِيدِ قَبْلَ الصَّلَاةِ وَتُكْرَهُ بَعْدَهَا وَيَحْرُمُ: تَأْخِيرُهَا. عَنْ يَوْمِ الْعِيدِ مَعَ الْقُدْرَةِ وَيَقْضِيهَا وَتُجْزِئُ قَبْلَ الْعِيدِ بِيَوْمَيْنِ."]]},{"id":"da30_6","label":"بَابُ زَكَاةِ الْفِطْرِ · ٦","segs":[["matn","وَالْوَاجِبُ: عَنْ كُلِّ شَخْصٍ صَاعُ تَمْرٍ أَوْ زَبِيبٍ أَوْ بُرٍّ أَوْ شَعِيرٍ أَوْ أَقِطٍ. وَيُجْزِئُ: دَقِيقُ الْبُرِّ وَالشَّعِيرِ إِذَا كَانَ وَزْنَ الْحَبِّ."]]},{"id":"da30_7","label":"بَابُ زَكَاةِ الْفِطْرِ · ٧","segs":[["matn","وَيُخْرِجُ مَعَ عَدَمِ ذَلِكَ مَا يَقُومُ مَقَامَهُ مِنْ حَبٍّ يُقْتَاتُ كَذُرَةٍ وَدُخْنٍ وَبَاقِلًا. وَيَجُوزُ: أَنْ تُعْطِيَ الْجَمَاعَةُ فِطْرَتَهُمْ لِوَاحِدٍ وَأَنْ يُعْطِيَ الْوَاحِدُ فُطْرَتَهُ لِجَمَاعَةٍ."]]},{"id":"da30_8","label":"بَابُ زَكَاةِ الْفِطْرِ · ٨","segs":[["matn","وَلَا يُجْزِئُ: إِخْرَاجُ الْقِيمَةِ فِي الزَّكَاةِ مُطْلَقًا. وَيَحْرُمُ: عَلَى الشَّخْصِ شِرَاءُ زَكَاتِهِ وَصَدَقَتِهِ وَلَوِ اشْتَرَاهَا مِنْ غَيْرِ مَنْ أَخَذَهَا مِنْهُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da31","title":"بَابُ إِخْرَاجِ الزَّكَاةِ","units":[{"id":"da31_1","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ١","segs":[["matn","يَجِبُ إِخْرَاجُهَا فَوْرًا كَالنَّذْرِ وَالْكَفَّارَةِ وَلَهُ تَأْخِيرُهَا لِزَمَنِ الْحَاجَةِ وَلِقَرِيبٍ وَجَارٍ وَلِتَعَذُّرِ إِخْرَاجِهَا مِنَ النِّصَابِ وَلَوْ قَدِرَ أَنْ يُخْرِجَهَا مِنْ غَيْرِهِ. وَمَنْ جَحَدَ وُجُوبَهَا عَالِمًا كَفَرَ وَلَوْ أَخْرَجَهَا."]]},{"id":"da31_2","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٢","segs":[["matn","وَمَنْ مَنَعَهَا بُخْلًا أَوْ تَهَاوُنًا أُخِذَتْ مِنْهُ وَعُزِّرَ. وَمَنِ ادَّعَى إِخْرَاجَهَا أَوْ بَقَاءَ الْحَوْلِ أَوْ نَقْصَ النِّصَابِ أَوْ زَوَالَ الْمِلْكِ صُدِّقَ بِلَا يَمِينٍ. وَيَلْزَمُ أَنْ يُخْرِجَ عَنِ الصَّغِيرِ وَالْمَجْنُونِ وَلِيُّهُمَا."]]},{"id":"da31_3","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٣","segs":[["matn","وَيُسَنُّ: إِظْهَارُهَا وَأَنْ يُفَرِّقَهَا رَبُّهَا بِنَفْسِهِ وَيَقُولَ عِنْدَ دَفْعِهَا: اللَّهُمَّ اجْعَلْهَا مَغْنَمًا وَلَا تَجْعَلْهَا مَغْرَمًا وَيَقُولُ الْآخِذُ: آجَرَكَ اللَّهُ فِيمَا أَعْطَيْتَ وَبَارَكَ لَكَ فِيمَا أَبْقَيْتَ وَجَعَلَهُ لَكَ طَهُورًا."]]},{"id":"da31_4","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٤","segs":[["matn","فَصْلٌ: وَيُشْتَرَطُ لِإِخْرَاجِهَا نِيَّةٌ مِنْ مُكَلَّفٍ وَلَهُ تَقْدِيمُهَا بِيَسِيرٍ وَالْأَفْضَلُ قَرْنُهَا بِالدَّفْعِ فَيَنْوِي الزَّكَاةَ أَوِ الصَّدَقَةَ الْوَاجِبَةَ وَلَا يُجْزِئُ إِنْ نَوَى صَدَقَةً مُطْلَقَةً وَلَوْ تَصَدَّقَ بِجَمِيعِ مَالِهِ وَلَا تَجِبُ نِيَّةُ الْفَرْضِيَّةِ وَلَا تَعْيِينُ الْمَالِ الْمُزَكَّى عَنْهُ."]]},{"id":"da31_5","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٥","segs":[["matn","وَإِنْ وَكَّلَ فِي إِخْرَاجِهَا مُسْلِمًا أَجْزَأَتْ نِيَّةُ الْمُوَكِّلِ مَعَ قُرْبِ الْإِخْرَاجِ وَإِلَّا نَوَى الْوَكِيلُ أَيْضًا. وَالْأَفْضَلُ: جَعْلُ زَكَاةِ كُلِّ مَالٍ فِي فُقَرَاءِ بَلَدِهِ وَيَحْرُمُ نَقْلُهَا إِلَى مَسَافَةِ قَصْرٍ وَتُجْزِئُ."]]},{"id":"da31_6","label":"بَابُ إِخْرَاجِ الزَّكَاةِ · ٦","segs":[["matn","وَيَصِحُّ: تَعْجِيلُ الزَّكَاةِ لِحَوْلَيْنِ فَقَطْ إِذَا كَمَلَ النِّصَابُ لَا مِنْهُ لِحَوْلَيْنِ فَإِنْ تَلِفَ النِّصَابُ أَوْ نَقَصَ وَقَعَ نَفْلًا."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da32","title":"بَابُ أَهْلِ الزَّكَاةِ","units":[{"id":"da32_1","label":"بَابُ أَهْلِ الزَّكَاةِ · ١","segs":[["matn","وَهُمْ ثَمَانِيَةٌ: الْأَوَّلُ: الْفَقِيرُ وَهُوَ مَنْ لَمْ يَجِدْ نِصْفَ كِفَايَتِهِ. الثَّانِي: الْمِسْكِينُ: وَهُوَ مَنْ يَجِدُ نِصْفَهَا أَوْ أَكْثَرَهَا. الثَّالِثُ: الْعَامِلُ عَلَيْهَا: كَجَابٍ وَحَافِظٍ وَكَاتِبٍ وَقَاسِمٍ."]]},{"id":"da32_2","label":"بَابُ أَهْلِ الزَّكَاةِ · ٢","segs":[["matn","الرَّابِعُ: الْمُؤَلَّفُ: وَهُوَ السَّيِّدُ الْمُطَاعُ فِي عَشِيرَتِهِ مِمَّنْ يُرْجَى إِسْلَامُهُ أَوْ يُخْشَى شَرُّهُ أَوْ يُرْجَى بِعَطِيَّتِهِ قُوَّةُ إِيمَانِهِ أَوْ جِبَايَتُهَا مِمَّنْ لَا يُعْطِيهَا. الْخَامِسُ: الْمُكَاتَبُ."]]},{"id":"da32_3","label":"بَابُ أَهْلِ الزَّكَاةِ · ٣","segs":[["matn","السَّادِسُ: الْغَارِمُ: وَهُوَ مَنْ تَدَيَّنَ لِلْإِصْلَاحِ بَيْنَ النَّاسِ أَوْ تَدَيَّنَ لِنَفْسِهِ وَأَعْسَرَ. السَّابِعُ: الْغَازِي فِي سَبِيلِ اللَّهِ. الثَّامِنُ: ابْنُ السَّبِيلِ: وَهُوَ الْغَرِيبُ الْمُنْقَطِعُ بِغَيْرِ بَلَدِهِ."]]},{"id":"da32_4","label":"بَابُ أَهْلِ الزَّكَاةِ · ٤","segs":[["matn","فَيُعْطَى الْجَمِيعُ مِنَ الزَّكَاةِ بِقَدْرِ الْحَاجَةِ إِلَّا الْعَامِلَ فَيُعْطَى بِقَدْرِ أُجْرَتِهِ وَلَوْ غَنِيًّا أَوْ قِنًّا."]]},{"id":"da32_5","label":"بَابُ أَهْلِ الزَّكَاةِ · ٥","segs":[["matn","وَيُجْزِئُ دَفْعُهَا إِلَى الْخَوَارِجِ وَالْبُغَاةِ وَكَذَلِكَ مَنْ أَخَذَهَا مِنَ السَّلَاطِينِ قَهْرًا أَوِ اخْتِيَارًا عَدَلَ فِيهَا أَوْ جَارَ."]]},{"id":"da32_6","label":"بَابُ أَهْلِ الزَّكَاةِ · ٦","segs":[["matn","فَصْلٌ: وَلَا يُجْزِئُ: دَفْعُ الزَّكَاةِ لِلْكَافِرِ وَلَا لِلرَّقِيقِ وَلَا لِلْغَنِيِّ بِمَالٍ أَوْ كَسْبٍ وَلَا لِمَنْ تَلْزَمُهُ نَفَقَتُهُ وَلَا لِلزَّوْجِ وَلَا لِبَنِي هَاشِمٍ."]]},{"id":"da32_7","label":"بَابُ أَهْلِ الزَّكَاةِ · ٧","segs":[["matn","فَإِنْ دَفَعَهَا لِغَيْرِ مُسْتَحِقِّهَا وَهُوَ يَجْهَلُ ثُمَّ عَلِمَ لَمْ يُجْزِئْهُ وَيَسْتَرِدُّهَا مِنْهُ بِنَمَائِهَا. وَإِنْ دَفَعَهَا لِمَنْ يَظُنُّهُ فَقِيرًا فَبَانَ غَنِيًّا أَجْزَأَ."]]},{"id":"da32_8","label":"بَابُ أَهْلِ الزَّكَاةِ · ٨","segs":[["matn","وَسُنَّ أَنْ يُفَرِّقَ الزَّكَاةَ عَلَى أَقَارِبِهِ الَّذِينَ لَا تَلْزَمُهُ نَفَقَتُهُمْ عَلَى قَدْرِ حَاجَتِهِمْ وَعَلَى ذَوِي أَرْحَامِهِ كَعَمَّتِهِ وَبِنْتِ أَخِيهِ. وَتُجْزِئُ إِنْ دَفَعَهَا لِمَنْ تَبَرَّعَ بِنَفَقَتِهِ بِضَمِّهِ إِلَى عِيَالِهِ."]]},{"id":"da32_9","label":"بَابُ أَهْلِ الزَّكَاةِ · ٩","segs":[["matn","فَصْلٌ: وَتُسَنُّ: صَدَقَةُ التَّطَوُّعِ فِي كُلِّ وَقْتٍ لَا سِيَّمَا سِرًّا وَفِي الزَّمَانِ وَالْمَكَانِ الْفَاضِلِ وَعَلَى جَارِهِ وَذَوِي رَحِمِهِ فَهِيَ صَدَقَةٌ وَصِلَةٌ."]]},{"id":"da32_10","label":"بَابُ أَهْلِ الزَّكَاةِ · ١٠","segs":[["matn","وَمَنْ تَصَدَّقَ بِمَا يَنْقُصُ مُؤْنَةٌ تَلْزَمُهُ أَوْ أَضَرَّ بِنَفْسِهِ أَوْ غَرِيمِهِ أَثِمَ بِذَلِكَ. وَكُرِهَ: لِمَنْ لَا صَبْرَ لَهُ أَوْ لَا عَادَةَ لَهُ عَلَى الضِّيقِ أَنْ يَنْقُصَ نَفْسَهُ عَنِ الْكِفَايَةِ التَّامَّةِ. وَالْمَنُّ بِالصَّدَقَةِ كَبِيرَةٌ وَيَبْطُلُ بِهِ الثَّوَابُ."]]}],"group":"كِتَابُ الزَّكَاةِ"},{"id":"da33","title":"كِتَابُ الصِّيَامِ","units":[{"id":"da33_1","label":"كِتَابُ الصِّيَامِ · ١","segs":[["matn","يَجِبُ: صَوْمُ رَمَضَانَ بِرُؤْيَةِ هِلَالِهِ عَلَى جَمِيعِ النَّاسِ وَعَلَى مَنْ حَالَ دُونَهُمْ وَدُونَ مَطْلِعِهِ غَيْمٌ أَوْ قَتَرٌ لَيْلَةَ الثَّلَاثِينَ مِنْ شَعْبَانَ احْتِيَاطًا بِنِيَّةِ رَمَضَانَ وَيُجْزِئُ إِنْ ظَهَرَ مِنْهُ وَتُصَلَّى التَّرَاوِيحُ وَلَا تَثْبُتُ بَقِيَّةُ الْأَحْكَامِ: كَوُقُوعِ الطَّلَاقِ وَالْعِتْقِ وَحُلُولِ الْأَجَلِ."]]},{"id":"da33_2","label":"كِتَابُ الصِّيَامِ · ٢","segs":[["matn","وَتَثْبُتُ رُؤْيَةُ هِلَالِهِ بِخَبَرِ مُسْلِمٍ مُكَلَّفٍ عَدْلٍ وَلَوْ عَبْدًا أَوْ أُنْثَى. وَتَثْبُتُ بَقِيَّةُ الْأَحْكَامِ تَبَعًا وَلَا يُقْبَلُ فِي بَقِيَّةِ الشُّهُورِ إِلَّا رَجُلَانِ عَدْلَانِ."]]},{"id":"da33_3","label":"كِتَابُ الصِّيَامِ · ٣","segs":[["matn","فَصْلٌ: وَشَرْطُ وُجُوبِ الصَّوْمِ أَرْبَعَةُ أَشْيَاءَ: الْإِسْلَامُ وَالْبُلُوغُ وَالْعَقْلُ وَالْقُدْرَةُ عَلَيْهِ."]]},{"id":"da33_4","label":"كِتَابُ الصِّيَامِ · ٤","segs":[["matn","فَمَنْ عَجَزَ عَنْهُ لِكِبَرٍ أَوْ مَرَضٍ لَا يُرْجَى زَوَالُهُ أَفْطَرَ وَأَطْعَمَ عَنْ كُلِّ يَوْمٍ مِسْكِينًا مُدَّ بُرٍّ أَوْ نِصْفَ صَاعٍ مِنْ غَيْرِهِ. وَشَرْطُ صِحَّتِهِ سِتَّةٌ: الْإِسْلَامُ وَانْقِطَاعُ دَمِ الْحَيْضِ وَالنِّفَاسِ."]]},{"id":"da33_5","label":"كِتَابُ الصِّيَامِ · ٥","segs":[["matn","الرَّابِعُ: التَّمْيِيزُ فَيَجِبُ عَلَى وَلِيِّ الْمُمَيِّزِ الْمُطِيقِ لِلصَّوْمِ أَمْرُهُ بِهِ وَضَرْبُهُ عَلَيْهِ لِيَعْتَادَهُ. الْخَامِسُ: الْعَقْلُ لَكِنْ لَوْ نَوَى لَيْلًا ثُمَّ جُنَّ أَوْ أُغْمِيَ عَلَيْهِ جَمِيعَ النَّهَارِ وَأَفَاقَ مِنْهُ قَلِيلًا: صَحَّ."]]},{"id":"da33_6","label":"كِتَابُ الصِّيَامِ · ٦","segs":[["matn","السَّادِسُ: النِّيَّةُ مِنَ اللَّيْلِ لِكُلِّ يَوْمٍ وَاجِبٍ. فَمَنْ خَطَرَ بِقَلْبِهِ لَيْلًا أَنَّهُ صَائِمٌ فَقَدْ نَوَى وَكَذَا الْأَكْلُ وَالشُّرْبُ بِنِيَّةِ الصَّوْمِ."]]},{"id":"da33_7","label":"كِتَابُ الصِّيَامِ · ٧","segs":[["matn","وَلَا يَضُرُّ إِنْ أَتَى بَعْدَ النِّيَّةِ بِمُنَافٍ لِلصَّوْمِ أَوْ قَالَ إِنْ شَاءَ اللَّهُ غَيْرَ مُتَرَدِّدٍ وَكَذَا لَوْ قَالَ لَيْلَةَ الثَّلَاثِينَ مِنْ رَمَضَانَ:"]]},{"id":"da33_8","label":"كِتَابُ الصِّيَامِ · ٨","segs":[["matn","إِنْ كَانَ غَدًا مِنْ رَمَضَانَ فَفَرْضِي وَإِلَّا فَمُفْطِرٌ وَيَضُرُّ إِنْ قَالَهُ فِي أَوَّلِهِ وَفَرْضُهُ الْإِمْسَاكُ عَنِ الْمُفَطِّرَاتِ مِنْ طُلُوعِ الْفَجْرِ الثَّانِي إِلَى غُرُوبِ الشَّمْسِ."]]},{"id":"da33_9","label":"كِتَابُ الصِّيَامِ · ٩","segs":[["matn","وَسُنَنُهُ سِتَّةٌ: تَعْجِيلُ الْفِطْرِ وَتَأْخِيرُ السَّحُورِ وَالزِّيَادَةُ فِي أَعْمَالِ الْخَيْرِ وَقَوْلُهُ جَهْرًا إِذَا شُتِمَ: إِنِّي صَائِمٌ وَقَوْلُهُ عِنْدَ فِطْرِهِ:"]]},{"id":"da33_10","label":"كِتَابُ الصِّيَامِ · ١٠","segs":[["matn","اللَّهُمَّ لَكَ صُمْتُ وَعَلَى رِزْقِكَ أَفْطَرْتُ سُبْحَانَكَ وَبِحَمْدِكَ اللَّهُمَّ تَقَبَّلْ مِنِّي إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ وَفِطْرُهُ عَلَى رُطَبٍ فَإِنْ عُدِمَ فَتَمْرٍ فَإِنْ عَدِمَ فَمَاءٍ."]]},{"id":"da33_11","label":"كِتَابُ الصِّيَامِ · ١١","segs":[["matn","فَصْلٌ: يَحْرُمُ: عَلَى مَنْ لَا عُذْرَ لَهُ الْفِطْرُ بِرَمَضَانَ وَيَجِبُ الْفِطْرُ عَلَى الْحَائِضِ وَالنُّفَسَاءِ وَعَلَى مَنْ يَحْتَاجُهُ لِإِنْقَاذِ مَعْصُومٍ مِنْ مَهْلَكَةٍ وَيُسَنُّ لِمُسَافِرٍ يُبَاحُ لَهُ الْقَصْرُ وَلِمَرِيضٍ يَخَافُ الضَّرَرَ."]]},{"id":"da33_12","label":"كِتَابُ الصِّيَامِ · ١٢","segs":[["matn","وَيُبَاحُ: لِحَاضِرٍ سَافَرَ فِي أَثْنَاءِ النَّهَارِ وَلِحَامِلٍ وَمُرْضِعٍ خَافَتَا عَلَى أَنْفُسِهِمَا أَوْ عَلَى الْوَلَدِ لَكِنْ لَوْ أَفْطَرَتَا لِلْخَوْفِ عَلَى الْوَلَدِ فَقَطْ لَزِمَ وَلِيَّهُ إِطْعَامُ مِسْكِينٍ لِكُلِّ يَوْمٍ."]]},{"id":"da33_13","label":"كِتَابُ الصِّيَامِ · ١٣","segs":[["matn","وَإِنْ أَسْلَمَ الْكَافِرُ وَطَهُرَتِ الْحَائِضُ أَوْ بَرِئَ الْمَرِيضُ أَوْ قَدِمَ الْمُسَافِرُ أَوْ بَلَغَ الصَّغِيرُ أَوْ عَقَلَ الْمَجْنُونُ فِي أَثْنَاءِ النَّهَارِ وَهُمْ مُفْطِرُونَ لَزِمَهُمُ الْإِمْسَاكُ وَالْقَضَاءُ."]]},{"id":"da33_14","label":"كِتَابُ الصِّيَامِ · ١٤","segs":[["matn","وَلَيْسَ لِمَنْ جَازَ لَهُ الْفِطْرُ بِرَمَضَانَ أَنْ يَصُومَ غَيْرَهُ فِيهِ."]]},{"id":"da33_15","label":"كِتَابُ الصِّيَامِ · ١٥","segs":[["matn","فَصْلٌ فِي الْمُفَطِّرَاتِ: وَهِيَ اثْنَا عَشَرَ: خُرُوجُ دَمِ الْحَيْضِ، وَالنِّفَاسِ، وَالْمَوْتُ وَالرِّدَّةُ وَالْعَزْمُ عَلَى الْفِطْرِ، وَالتَّرَدُّدُ فِيهِ، وَالْقَيْءُ عَمْدًا، وَالِاحْتِقَانُ مِنَ الدُّبُرِ، وَبَلْعُ النُّخَامَةِ إِذَا وَصَلَتْ إِلَى الْفَمِ."]]},{"id":"da33_16","label":"كِتَابُ الصِّيَامِ · ١٦","segs":[["matn","التَّاسِعُ: الْحِجَامَةُ خَاصَّةً حَاجِمًا كَانَ أَوْ مَحْجُومًا. الْعَاشِرُ: إِنْزَالُ الْمَنِيِّ بِتَكْرَارِ النَّظَرِ لَا بِنَظْرَةٍ وَلَا بِالتَّفَكُّرِ وَالِاحْتِلَامِ وَلَا بِالْمَذْيِ."]]},{"id":"da33_17","label":"كِتَابُ الصِّيَامِ · ١٧","segs":[["matn","الْحَادِيَ عَشَرَ: خُرُوجُ الْمَنِيِّ وَالْمَذْيِ بِتَقْبِيلٍ أَوْ لَمْسٍ أَوِ اسْتِمْنَاءٍ أَوْ مُبَاشَرَةٍ دُونَ الْفَرْجِ. الثَّانِيَ عَشَرَ: كُلُّ مَا وَصَلَ إِلَى الْجَوْفِ أَوِ الْحَلْقِ أَوِ الدِّمَاغِ مِنْ مَائِعٍ وَغَيْرِهِ."]]},{"id":"da33_18","label":"كِتَابُ الصِّيَامِ · ١٨","segs":[["matn","فَيُفْطِرُ إِنْ قَطَّرَ فِي أُذُنِهِ مَا وَصَلَ إِلَى دِمَاغِهِ أَوْ دَاوَى الْجَائِفَةَ فَوَصَلَ إِلَى جَوْفِهِ أَوِ اكْتَحَلَ بِمَا عَلِمَ وُصُولَهُ إِلَى حَلْقِهِ أَوْ مَضَغَ عِلْكًا أَوْ ذَاقَ طَعَامًا وَوَجَدَ الطَّعْمَ بِحَلْقِهِ أَوْ بَلَعَ رِيقَهُ بَعْدَ أَنْ وَصَلَ إِلَى بَيْنِ شَفَتَيْهِ."]]},{"id":"da33_19","label":"كِتَابُ الصِّيَامِ · ١٩","segs":[["matn","وَلَا يُفْطِرُ إِنْ فَعَلَ شَيْئًا مِنْ جَمِيعِ الْمُفَطِّرَاتِ نَاسِيًا أَوْ مُكْرَهًا وَلَا إِنْ دَخَلَ الْغُبَارُ حَلْقَهُ أَوِ الذُّبَابُ بِغَيْرِ قَصْدِهِ وَلَا إِنْ جَمَعَ رِيقَهُ فَابْتَلَعَهُ."]]},{"id":"da33_20","label":"كِتَابُ الصِّيَامِ · ٢٠","segs":[["matn","فَصْلٌ: وَمَنْ جَامَعَ نَهَارَ رَمَضَانَ فِي قُبُلٍ أَوْ دُبُرٍ وَلَوْ لِمَيِّتٍ أَوْ بَهِيمَةٍ فِي حَالَةٍ يَلْزَمُهُ فِيهَا الْإِمْسَاكُ مُكْرَهًا كَانَ أَوْ نَاسِيًا لَزِمَهُ الْقَضَاءُ وَالْكَفَّارَةُ."]]},{"id":"da33_21","label":"كِتَابُ الصِّيَامِ · ٢١","segs":[["matn","وَكَذَا مَنْ جُومِعَ إِنْ طَاوَعَ غَيْرَ جَاهِلٍ وَنَاسٍ."]]},{"id":"da33_22","label":"كِتَابُ الصِّيَامِ · ٢٢","segs":[["matn","وَالْكَفَّارَةُ: عِتْقُ رَقَبَةٍ مُؤْمِنَةٍ فَإِنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ فَإِنْ لَمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا فَإِنْ لَمْ يَجِدْ: سَقَطَتْ بِخِلَافِ غَيْرِهَا مِنَ الْكَفَّارَاتِ."]]},{"id":"da33_23","label":"كِتَابُ الصِّيَامِ · ٢٣","segs":[["matn","وَلَا كَفَّارَةَ فِي رَمَضَانَ بِغَيْرِ الْجِمَاعِ وَالْإِنْزَالِ بِالْمُسَاحَقَةِ."]]},{"id":"da33_24","label":"كِتَابُ الصِّيَامِ · ٢٤","segs":[["matn","فَصْلٌ: وَمَنْ فَاتَهُ رَمَضَانُ كُلُّهُ قَضَى عَدَدَ أَيَّامِهِ. وَيُسَنُّ: الْقَضَاءُ عَلَى الْفَوْرِ إِلَّا إِذَا بَقِيَ مِنْ شَعْبَانَ بِقَدْرِ مَا عَلَيْهِ فَيَجِبُ."]]},{"id":"da33_25","label":"كِتَابُ الصِّيَامِ · ٢٥","segs":[["matn","وَلَا يَصِحُّ ابْتِدَاءُ تَطَوُّعِ مَنْ عَلَيْهِ قَضَاءُ رَمَضَانَ فَإِنْ نَوَى صَوْمًا وَاجِبًا أَوْ قَضَاءً ثُمَّ قَلَبَهُ نَفْلًا صَحَّ. وَيُسَنُّ: صَوْمُ التَّطَوُّعِ وَأَفْضَلُهُ يَوْمٌ وَيَوْمٌ."]]},{"id":"da33_26","label":"كِتَابُ الصِّيَامِ · ٢٦","segs":[["matn","وَيُسَنُّ: صَوْمُ أَيَّامِ الْبِيضِ: وَهِيَ ثَلَاثَ عَشْرَةَ وَأَرْبَعَ عَشْرَةَ وَخَمْسَ عَشْرَةَ وَصَوْمُ الْخَمِيسِ وَالْإِثْنَيْنِ وَسِتَّةٍ مِنْ شَوَّالٍ."]]},{"id":"da33_27","label":"كِتَابُ الصِّيَامِ · ٢٧","segs":[["matn","وَسُنَّ: صَوْمُ الْمُحَرَّمِ وَآكَدُهُ عَاشُورَاءُ وَهُوَ كَفَّارَةُ سَنَةٍ وَصَوْمُ عَشْرِ ذِي الْحِجَّةِ وَآكَدُهُ يَوْمُ عَرَفَةَ وَهُوَ كَفَّارَةُ سَنَتَيْنِ. وَكُرِهَ إِفْرَادُ رَجَبٍ وَالْجُمُعَةِ وَالسَّبْتِ بِالصَّوْمِ."]]},{"id":"da33_28","label":"كِتَابُ الصِّيَامِ · ٢٨","segs":[["matn","وَكُرِهَ صَوْمُ يَوْمِ الشَّكِّ وَهُوَ الثَّلَاثُونَ مِنْ شَعْبَانَ إِذَا لَمْ يَكُنْ غَيْمٌ أَوْ قَتَرٌ وَيَحْرُمُ صَوْمُ الْعِيدَيْنِ وَأَيَّامِ التَّشْرِيقِ."]]},{"id":"da33_29","label":"كِتَابُ الصِّيَامِ · ٢٩","segs":[["matn","وَمَنْ دَخَلَ فِي تَطَوُّعٍ لَمْ يَجِبْ إِتْمَامُهُ وَفِي فَرْضٍ يَجِبُ مَا لَمْ يَقْلِبْهُ نَفْلًا."]]}],"group":"كِتَابُ الصِّيَامِ"},{"id":"da34","title":"كِتَابُ الِاعْتِكَافِ","units":[{"id":"da34_1","label":"كِتَابُ الِاعْتِكَافِ · ١","segs":[["matn","وَهُوَ سُنَّةٌ، وَيَجِبُ بِالنَّذْرِ. وَشَرْطُ صِحَّتِهِ سِتَّةُ أَشْيَاءَ: النِّيَّةُ وَالْإِسْلَامُ وَالْعَقْلُ وَالتَّمْيِيزُ وَعَدَمُ مَا يُوجِبُ الْغُسْلَ وَكَوْنُهُ بِمَسْجِدٍ وَيُزَادُ فِي حَقِّ مَنْ تَلْزَمُهُ الْجَمَاعَةُ أَنْ يَكُونَ الْمَسْجِدُ مِمَّا تُقَامُ فِيهِ."]]},{"id":"da34_2","label":"كِتَابُ الِاعْتِكَافِ · ٢","segs":[["matn","وَمِنَ الْمَسْجِدِ مَا زِيدَ فِيهِ وَمِنْهُ سَطْحُهُ وَرَحْبَتُهُ الْمَحُوطَةُ وَمَنَارَتُهُ الَّتِي هِيَ أَوْ بَابُهَا فِيهِ وَمَنْ عَيَّنَ الِاعْتِكَافَ بِمَسْجِدٍ غَيْرِ الثَّلَاثَةِ لَمْ يَتَعَيَّنْ."]]},{"id":"da34_3","label":"كِتَابُ الِاعْتِكَافِ · ٣","segs":[["matn","وَيَبْطُلُ الِاعْتِكَافُ بِالْخُرُوجِ مِنَ الْمَسْجِدِ لِغَيْرِ عُذْرٍ وَبِنِيَّةِ الْخُرُوجِ وَلَوْ لَمْ يَخْرُجْ وَبِالْوَطْءِ فِي الْفَرْجِ وَبِالْإِنْزَالِ بِالْمُبَاشَرَةِ دُونَ الْفَرْجِ وَبِالرِّدَّةِ وَبِالسُّكْرِ."]]},{"id":"da34_4","label":"كِتَابُ الِاعْتِكَافِ · ٤","segs":[["matn","وَحَيْثُ بَطَلَ الِاعْتِكَافُ وَجَبَ اسْتِئْنَافُ النَّذْرِ الْمُتَتَابِعِ غَيْرِ الْمُقَيَّدِ بِزَمَنٍ وَلَا كَفَّارَةَ وَإِنْ كَانَ مُقَيَّدًا بِزَمَنٍ مُعَيَّنٍ اسْتَأْنَفَهُ وَعَلَيْهِ كَفَّارَةُ يَمِينٍ لِفَوَاتِ الْمَحَلِّ."]]},{"id":"da34_5","label":"كِتَابُ الِاعْتِكَافِ · ٥","segs":[["matn","وَلَا يَبْطُلُ الِاعْتِكَافُ إِنْ خَرَجَ مِنَ الْمَسْجِدِ لِبَوْلٍ أَوْ غَائِطٍ أَوْ طَهَارَةٍ وَاجِبَةٍ أَوْ لِإِزَالَةِ نَجَاسَةٍ أَوْ لِجُمُعَةٍ تَلْزَمُهُ وَلَا إِنْ خَرَجَ لِلْإِتْيَانِ بِمَأْكَلٍ وَمَشْرَبٍ لِعَدَمِ خَادِمٍ وَلَهُ الْمَشْيُ عَلَى عَادَتِهِ."]]},{"id":"da34_6","label":"كِتَابُ الِاعْتِكَافِ · ٦","segs":[["matn","وَيَنْبَغِي لِمَنْ قَصَدَ الْمَسْجِدَ أَنْ يَنْوِيَ الِاعْتِكَافَ مُدَّةَ لُبْثِهِ فِيهِ لَا سِيَّمَا إِنْ كَانَ صَائِمًا."]]}],"group":"كِتَابُ الِاعْتِكَافِ"},{"id":"da35","title":"كِتَابُ الْحَجِّ","units":[{"id":"da35_1","label":"كِتَابُ الْحَجِّ · ١","segs":[["matn","وَهُوَ: وَاجِبٌ مَعَ الْعُمْرَةِ فِي الْعُمْرِ مَرَّةً. وَشَرْطُ الْوُجُوبِ خَمْسَةُ أَشْيَاءَ: الْإِسْلَامُ، وَالْعَقْلُ وَالْبُلُوغُ وَكَمَالُ الْحُرِّيَّةِ."]]},{"id":"da35_2","label":"كِتَابُ الْحَجِّ · ٢","segs":[["matn","لَكِنْ يَصِحَّانِ مِنَ الصَّغِيرِ وَالرَّقِيقِ وَلَا يُجْزِيَانِ عَنْ حَجَّةِ الْإِسْلَامِ وَعُمْرَتِهِ فَإِنْ بَلَغَ الصَّغِيرُ أَوْ عَتَقَ الرَّقِيقُ قَبْلَ الْوُقُوفِ أَوْ بَعْدَهُ إِنْ عَادَ فَوَقَفَ فِي"]]},{"id":"da35_3","label":"كِتَابُ الْحَجِّ · ٣","segs":[["matn","وَقْتِهِ أَجْزَأَهُ عَنْ حَجَّةِ الْإِسْلَامِ مَا لَمْ يَكُنْ أَحْرَمَ مُفْرِدًا أَوْ قَارِنًا وَسَعَى بَعْدَ طَوَافِ الْقُدُومِ وَكَذَا تُجْزِئُ الْعُمْرَةُ إِنْ بَلَغَ أَوْ عَتَقَ قَبْلَ طَوَافِهَا."]]},{"id":"da35_4","label":"كِتَابُ الْحَجِّ · ٤","segs":[["matn","الْخَامِسُ: الِاسْتِطَاعَةُ: وَهِيَ مِلْكُ زَادٍ وَرَاحِلَةٍ تَصْلُحُ لِمِثْلِهِ أَوْ مِلْكُ مَا يَقْدِرُ بِهِ عَلَى تَحْصِيلِ ذَلِكَ بِشَرْطِ كَوْنِهِ فَاضِلًا عَمَّا يَحْتَاجُهُ مِنْ كُتُبٍ وَمَسْكَنٍ وَخَادِمٍ وَأَنْ يَكُونَ فَاضِلًا عَنْ مُؤْنَتِهِ وَمُؤْنَةِ عِيَالِهِ عَلَى الدَّوَامِ."]]},{"id":"da35_5","label":"كِتَابُ الْحَجِّ · ٥","segs":[["matn","فَمَنْ كَمَلَتْ لَهُ هَذِهِ الشُّرُوطُ لَزِمَهُ السَّعْيُ فَوْرًا إِنْ كَانَ فِي الطَّرِيقِ أَمْنٌ فَإِنْ عَجَزَ عَنِ السَّعْيِ لِعُذْرٍ كَكِبَرٍ أَوْ مَرَضٍ لَا يُرْجَى بُرْؤُهُ:"]]},{"id":"da35_6","label":"كِتَابُ الْحَجِّ · ٦","segs":[["matn","لَزِمَهُ أَنْ يُقِيمَ نَائِبًا حُرًّا وَلَوِ امْرَأَةً يَحُجُّ وَيَعْتَمِرُ عَنْهُ مِنْ بَلَدِهِ وَيُجْزِئُهُ ذَلِكَ مَا لَمْ يَزُلِ الْعُذْرُ قَبْلَ إِحْرَامِ نَائِبِهِ فَلَوْ مَاتَ قَبْلَ أَنْ يَسْتَنِيبَ وَجَبَ أَنْ يُدْفَعَ مِنْ تَرِكَتِهِ لِمَنْ يَحُجُّ وَيَعْتَمِرُ عَنْهُ."]]},{"id":"da35_7","label":"كِتَابُ الْحَجِّ · ٧","segs":[["matn","وَلَا يَصِحُّ مِمَّنْ لَمْ يَحُجَّ عَنْ نَفْسِهِ حَجٌّ عَنْ غَيْرِهِ. وَتَزِيدُ الْأُنْثَى شَرْطًا سَادِسًا وَهُوَ: أَنْ تَجِدَ لَهَا زَوْجًا أَوْ مَحْرَمًا مُكَلَّفًا وَتَقْدِرَ عَلَى أُجْرَتِهِ وَعَلَى الزَّادِ وَالرَّاحِلَةِ لَهَا وَلَهُ. فَإِنْ حَجَّتْ بِلَا مَحْرَمٍ حَرُمَ وَأَجْزَأَهَا."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da36","title":"بَابُ الْإِحْرَامِ","units":[{"id":"da36_1","label":"بَابُ الْإِحْرَامِ · ١","segs":[["matn","وَهُوَ وَاجِبٌ مِنَ الْمِيقَاتِ، وَمَنْ مَنْزِلُهُ دُونَ الْمِيقَاتِ فَمِيقَاتُهُ مَنْزِلُهُ وَلَا يَنْعَقِدُ الْإِحْرَامُ مَعَ وُجُودِ الْجُنُونِ أَوِ الْإِغْمَاءِ أَوِ السُّكْرِ."]]},{"id":"da36_2","label":"بَابُ الْإِحْرَامِ · ٢","segs":[["matn","وَإِذَا انْعَقَدَ لَمْ يَبْطُلْ إِلَّا بِالرِّدَّةِ لَكِنْ يَفْسُدُ بِالْوَطْءِ فِي الْفَرْجِ قَبْلَ التَّحَلُّلِ الْأَوَّلِ وَلَا يَبْطُلُ بَلْ يَلْزَمُهُ إِتْمَامُهُ وَالْقَضَاءُ."]]},{"id":"da36_3","label":"بَابُ الْإِحْرَامِ · ٣","segs":[["matn","وَيُخَيَّرُ مَنْ يُرِيدُ الْإِحْرَامَ بَيْنَ أَنْ يَنْوِيَ التَّمَتُّعَ وَهُوَ أَفْضَلُ أَوْ يَنْوِيَ الْإِفْرَادَ أَوِ الْقِرَانَ. فَالتَّمَتُّعُ: هُوَ أَنْ يُحْرِمَ بِالْعُمْرَةِ فِي أَشْهُرِ الْحَجِّ ثُمَّ بَعْدَ فَرَاغِهِ مِنْهَا يُحْرِمُ بِالْحَجِّ."]]},{"id":"da36_4","label":"بَابُ الْإِحْرَامِ · ٤","segs":[["matn","وَالْإِفْرَادُ: هُوَ أَنْ يُحْرِمَ بِالْحَجِّ ثُمَّ بَعْدَ فَرَاغِهِ مِنْهُ يُحْرِمُ بِالْعُمْرَةِ. وَالْقِرَانُ: هُوَ أَنْ يُحْرِمَ بِالْحَجِّ وَالْعُمْرَةِ مَعًا أَوْ يُحْرِمَ بِالْعُمْرَةِ ثُمَّ يُدْخِلَ الْحَجَّ عَلَيْهَا قَبْلَ الشُّرُوعِ فِي طَوَافِهَا."]]},{"id":"da36_5","label":"بَابُ الْإِحْرَامِ · ٥","segs":[["matn","فَإِنْ أَحْرَمَ بِهِ ثُمَّ بِهَا لَمْ يَصِحَّ. وَمَنْ أَحْرَمَ وَأَطْلَقَ: صَحَّ وَصَرَفَهُ لِمَا شَاءَ وَمَا عَمِلَ قَبْلُ فَلَغْوٌ."]]},{"id":"da36_6","label":"بَابُ الْإِحْرَامِ · ٦","segs":[["matn","لَكِنِ السُّنَّةُ لِمَنْ أَرَادَ نُسُكًا أَنْ يُعَيِّنَهُ وَأَنْ يَشْتَرِطَ فَيَقُولَ: اللَّهُمَّ إِنِّي أُرِيدُ النُّسُكَ الْفُلَانِيَّ فَيَسِّرْهُ لِي وَتَقَبَّلْهُ مِنِّي وَإِنْ حَبَسَنِي حَابِسٌ فَمَحِلِّي حَيْثُ حَبَسَنِي"]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da37","title":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ","units":[{"id":"da37_1","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ١","segs":[["matn","وَهِيَ سَبْعَةُ أَشْيَاءَ: أَحَدُهَا: تَعَمُّدُ لُبْسِ الْمَخِيطِ عَلَى الرَّجُلِ حَتَّى الْخُفَّيْنِ."]]},{"id":"da37_2","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٢","segs":[["matn","الثَّانِي: تَعَمُّدُ تَغْطِيَةِ الرَّأْسِ مِنَ الرَّجُلِ وَلَوْ بِطِينٍ أَوِ اسْتِظْلَالٍ بِمَحْمِلٍ وَتَغْطِيَةُ الْوَجْهِ مِنَ الْأُنْثَى لَكِنْ تَسْدِلُ عَلَى وَجْهِهَا لِلْحَاجَةِ."]]},{"id":"da37_3","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٣","segs":[["matn","الثَّالِثُ: قَصْدُ شَمِّ الطِّيبِ وَمَسُّ مَا يَعْلَقُ وَاسْتِعْمَالُهُ فِي أَكْلٍ أَوْ شُرْبٍ بِحَيْثُ يَظْهَرُ طَعْمُهُ أَوْ رِيحُهُ فَمَنْ لَبِسَ أَوْ تَطَيَّبَ أَوْ غَطَّى رَأْسَهُ نَاسِيًا أَوْ جَاهِلًا أَوْ مُكْرَهًا فَلَا شَيْءَ عَلَيْهِ وَمَتَى زَالَ عُذْرُهُ أَزَالَهُ فِي الْحَالِ وَإِلَّا فَدَى."]]},{"id":"da37_4","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٤","segs":[["matn","الرَّابِعُ: إِزَالَةُ الشَّعْرِ مِنَ الْبَدَنِ وَلَوْ مِنَ الْأَنْفِ وَتَقْلِيمُ الْأَظْفَارِ."]]},{"id":"da37_5","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٥","segs":[["matn","الْخَامِسُ: قَتْلُ صَيْدِ الْبَرِّ الْوَحْشِيِّ الْمَأْكُولِ وَالدَّلَالَةُ عَلَيْهِ وَالْإِعَانَةُ عَلَى قَتْلِهِ وَإِفْسَادُ بَيْضِهِ وَقَتْلُ الْجَرَادِ وَالْقَمْلِ لَا الْبَرَاغِيثِ بَلْ يُسَنُّ قَتْلُ كُلِّ مُؤْذٍ مُطْلَقًا. السَّادِسُ: عَقْدُ النِّكَاحِ وَلَا يَصِحُّ."]]},{"id":"da37_6","label":"بَابُ مَحْظُورَاتِ الْإِحْرَامِ · ٦","segs":[["matn","السَّابِعُ: الْوَطْءُ فِي الْفَرْجِ وَدَوَاعِيهِ وَالْمُبَاشَرَةُ دُونَ الْفَرْجِ وَالِاسْتِمْنَاءُ وَفِي جَمِيعِ الْمَحْظُورَاتِ الْفِدْيَةُ إِلَّا قَتْلَ الْقَمْلِ وَعَقْدَ النِّكَاحِ وَفِي الْبَيْضِ وَالْجَرَادِ قِيمَتُهُ مَكَانَهُ وَفِي الشَّعْرَةِ أَوِ الظُّفْرِ إِطْعَامُ مِسْكِينٍ وَفِي الِاثْنَيْنِ: إِطْعَامُ اثْنَيْنِ وَالضَّرُورَاتُ تُبِيحُ الْمَحْظُورَاتِ وَيَفْدِي."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da38","title":"بَابُ الْفِدْيَةِ","units":[{"id":"da38_1","label":"بَابُ الْفِدْيَةِ · ١","segs":[["matn","وَهِيَ مَا يَجِبُ بِسَبَبِ الْإِحْرَامِ أَوِ الْحَرَمِ. وَهِيَ قِسْمَانِ: قِسْمٌ عَلَى التَّخْيِيرِ وَقِسْمٌ عَلَى التَّرْتِيبِ."]]},{"id":"da38_2","label":"بَابُ الْفِدْيَةِ · ٢","segs":[["matn","فَقِسْمُ التَّخْيِيرِ: كَفِدْيَةِ اللُّبْسِ وَالطِّيبِ وَتَغْطِيَةِ الرَّأْسِ وَإِزَالَةِ أَكْثَرَ مِنْ شَعْرَتَيْنِ أَوْ ظُفْرَيْنِ وَالْإِمْنَاءِ بِنَظْرَةٍ وَالْمُبَاشَرَةِ بِغَيْرِ إِنْزَالِ مَنِيٍّ يُخَيَّرُ بَيْنَ ذَبْحِ شَاةٍ أَوْ صِيَامِ ثَلَاثَةِ أَيَّامٍ أَوْ إِطْعَامِ سِتَّةِ مَسَاكِينَ لِكُلِّ مِسْكِينٍ مُدُّ بُرٍّ أَوْ نِصْفُ صَاعٍ مِنْ غَيْرِهِ"]]},{"id":"da38_3","label":"بَابُ الْفِدْيَةِ · ٣","segs":[["matn","وَمِنَ التَّخْيِيرِ جَزَاءُ الصَّيْدِ يُخَيَّرُ فِيهِ بَيْنَ الْمِثْلِ مِنَ النَّعَمِ أَوْ تَقْوِيمِ الْمِثْلِ بِمَحَلِّ التَّلَفِ وَيَشْتَرِي بِقِيمَتِهِ طَعَامًا يُجْزِئُ فِي الْفِطْرَةِ فَيُطْعِمُ كُلَّ مِسْكِينٍ مُدَّ بُرٍّ أَوْ نِصْفَ صَاعٍ مِنْ غَيْرِهِ أَوْ يَصُومُ عَنْ طَعَامِ كُلِّ مِسْكِينٍ يَوْمًا."]]},{"id":"da38_4","label":"بَابُ الْفِدْيَةِ · ٤","segs":[["matn","وَقِسْمُ التَّرْتِيبِ كَدَمِ الْمُتْعَةِ وَالْقِرَانِ وَتَرْكِ الْوَاجِبِ وَالْإِحْصَارِ وَالْوَطْءِ وَنَحْوِهِ فَيَجِبُ عَلَى مُتَمَتِّعٍ وَقَارِنٍ وَتَارِكِ وَاجِبٍ دَمٌ فَإِنْ عَدِمَهُ أَوْ ثَمَنَهُ صَامَ ثَلَاثَةَ أَيَّامٍ فِي الْحَجِّ وَالْأَفْضَلُ كَوْنُ آخِرِهَا يَوْمَ عَرَفَةَ وَيَصِحُّ أَيَّامَ التَّشْرِيقِ وَسَبْعَةً إِذَا رَجَعَ إِلَى أَهْلِهِ."]]},{"id":"da38_5","label":"بَابُ الْفِدْيَةِ · ٥","segs":[["matn","وَيَجِبُ: عَلَى مُحْصَرٍ دَمٌ فَإِنْ لَمْ يَجِدْ صَامَ عَشَرَةَ أَيَّامٍ ثُمَّ حَلَّ وَيَجِبُ عَلَى مَنْ وَطِئَ فِي الْحَجِّ قَبْلَ التَّحَلُّلِ الْأَوَّلِ أَوْ أَنْزَلَ مَنِيًّا بِمُبَاشَرَةٍ أَوِ اسْتِمْنَاءٍ أَوْ تَقْبِيلٍ أَوْ لَمْسٍ بِشَهْوَةٍ أَوْ تَكْرَارِ نَظَرٍ:"]]},{"id":"da38_6","label":"بَابُ الْفِدْيَةِ · ٦","segs":[["matn","بَدَنَةٌ فَإِنْ لَمْ يَجِدْهَا صَامَ عَشَرَةَ أَيَّامٍ: ثَلَاثَةً فِي الْحَجِّ وَسَبْعَةً إِذَا رَجَعَ. وَفِي الْعُمْرَةِ إِذَا أَفْسَدَهَا قَبْلَ تَمَامِ السَّعْيِ شَاةٌ."]]},{"id":"da38_7","label":"بَابُ الْفِدْيَةِ · ٧","segs":[["matn","وَالتَّحَلُّلُ الْأَوَّلُ: يَحْصُلُ بِاثْنَيْنِ مِنْ رَمْيٍ وَحَلْقٍ وَطَوَافٍ وَيَحِلُّ لَهُ كُلُّ شَيْءٍ إِلَّا النِّسَاءَ وَالثَّانِي: يَحْصُلُ بِمَا بَقِيَ مَعَ السَّعْيِ إِنْ لَمْ يَكُنْ سَعَى قَبْلُ."]]},{"id":"da38_8","label":"بَابُ الْفِدْيَةِ · ٨","segs":[["matn","فَصْلٌ: وَالصَّيْدُ الَّذِي لَهُ مِثْلٌ مِنَ النَّعَمِ كَالنَّعَامَةِ وَفِيهَا بَدَنَةٌ وَفِي حِمَارِ الْوَحْشِ وَبَقَرِهِ بَقَرَةٌ وَفِي الضَّبُعِ كَبْشٌ وَفِي الْغَزَالِ شَاةٌ وَفِي الْوَبْرِ"]]},{"id":"da38_9","label":"بَابُ الْفِدْيَةِ · ٩","segs":[["matn","وَالضَّبِّ جَدْيٌ لَهُ نِصْفُ سَنَةٍ وَفِي الْيَرْبُوعِ جَفْرَةٌ لَهَا أَرْبَعَةُ أَشْهُرٍ وَفِي الْأَرْنَبِ عَنَاقٌ دُونَ الْجَفْرَةِ وَفِي الْحَمَامِ وَهُوَ كُلُّ مَا عَبَّ الْمَاءَ كَالْقَطَا وَالْوَرَشَانِ وَالْفَوَاخِتِ:"]]},{"id":"da38_10","label":"بَابُ الْفِدْيَةِ · ١٠","segs":[["matn","شَاةٌ وَمَا لَا مِثْلَ لَهُ كَالْإِوَزِّ وَالْحُبَارَى وَالْحَجَلِ وَالْكُرْكِيِّ فَفِيهِ قِيمَتُهُ مَكَانَهُ."]]},{"id":"da38_11","label":"بَابُ الْفِدْيَةِ · ١١","segs":[["matn","فَصْلٌ: وَيَحْرُمُ: صَيْدُ حَرَمِ مَكَّةَ وَحُكْمُهُ حُكْمُ صَيْدِ الْإِحْرَامِ. وَيَحْرُمُ: قَطْعُ شَجَرِهِ وَحَشِيشِهِ وَالْمُحِلُّ وَالْمُحْرِمُ فِي ذَلِكَ سَوَاءٌ فَتَضْمَنُ الشَّجَرَةَ الصَّغِيرَةَ عُرْفًا بِشَاةٍ وَمَا فَوْقَهَا بِبَقَرَةٍ وَيُضْمَنُ الْحَشِيشُ وَالْوَرَقُ بِقِيمَتِهِ."]]},{"id":"da38_12","label":"بَابُ الْفِدْيَةِ · ١٢","segs":[["matn","وَيُجْزِئُ عَنِ الْبَدَنَةِ بَقَرَةٌ كَعَكْسِهِ وَيُجْزِئُ عَنْ سَبْعِ شِيَاهٍ بَدَنَةٌ أَوْ بَقَرَةٌ."]]},{"id":"da38_13","label":"بَابُ الْفِدْيَةِ · ١٣","segs":[["matn","وَالْمُرَادُ بِالدَّمِ الْوَاجِبِ: مَا يُجْزِئُ فِي الْأُضْحِيَةِ جَذَعُ ضَأْنٍ أَوْ ثَنِيُّ مَعْزٍ أَوْ سُبْعُ بَدَنَةٍ أَوْ بَقَرَةٍ فَإِنْ ذَبَحَ إِحْدَاهُمَا فَأَفْضَلُ وَتَجِبُ كُلُّهَا."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da39","title":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ","units":[{"id":"da39_1","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١","segs":[["matn","أَرْكَانُ الْحَجِّ أَرْبَعَةٌ: الْأَوَّلُ: الْإِحْرَامُ وَهُوَ مُجَرَّدُ النِّيَّةِ فَمَنْ تَرَكَهُ لَمْ يَنْعَقِدْ حَجُّهُ."]]},{"id":"da39_2","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٢","segs":[["matn","الثَّانِي: الْوُقُوفُ بِعَرَفَةَ وَوَقْتُهُ مِنْ طُلُوعِ فَجْرِ يَوْمِ عَرَفَةَ إِلَى طُلُوعِ فَجْرِ يَوْمِ النَّحْرِ فَمَنْ حَصَلَ فِي هَذَا الْوَقْتِ بِعَرَفَةَ لَحْظَةً وَاحِدَةً وَهُوَ أَهْلٌ"]]},{"id":"da39_3","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٣","segs":[["matn","وَلَوْ مَارًّا أَوْ نَائِمًا أَوْ حَائِضًا أَوْ جَاهِلًا أَنَّهَا عَرَفَةُ صَحَّ حَجُّهُ لَا إِنْ كَانَ سَكْرَانَ أَوْ مَجْنُونًا أَوْ مُغْمًى عَلَيْهِ وَلَوْ وَقَفَ النَّاسُ كُلُّهُمْ أَوْ كُلُّهُمْ إِلَّا قَلِيلًا فِي الْيَوْمِ الثَّامِنِ أَوِ الْعَاشِرِ خَطَأً أَجْزَأَهُمْ."]]},{"id":"da39_4","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٤","segs":[["matn","الثَّالِثُ: طَوَافُ الْإِفَاضَةِ وَأَوَّلُ وَقْتِهِ: مِنْ نِصْفِ لَيْلَةِ النَّحْرِ لِمَنْ وَقَفَ وَإِلَّا فَبَعْدَ الْوُقُوفِ وَلَا حَدَّ لِآخِرِهِ. الرَّابِعُ: السَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ."]]},{"id":"da39_5","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٥","segs":[["matn","وَوَاجِبَاتُهُ سَبْعَةٌ: الْإِحْرَامُ مِنَ الْمِيقَاتِ، وَالْوُقُوفُ إِلَى الْغُرُوبِ لِمَنْ وَقَفَ نَهَارًا، وَالْمَبِيتُ لَيْلَةَ النَّحْرِ بِمُزْدَلِفَةَ إِلَى بَعْدِ نِصْفِ اللَّيْلِ، وَالْمَبِيتُ بِمِنًى فِي لَيَالِي التَّشْرِيقِ، وَرَمْيُ الْجِمَارِ مُرَتَّبًا، وَالْحَلْقُ أَوِ التَّقْصِيرُ، وَطَوَافُ الْوَدَاعِ."]]},{"id":"da39_6","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٦","segs":[["matn","وَأَرْكَانُ الْعُمْرَةِ ثَلَاثَةٌ: الْإِحْرَامُ وَالطَّوَافُ وَالسَّعْيُ. وَوَاجِبَاتُهَا شَيْئَانِ: الْإِحْرَامُ بِهَا مِنَ الْحِلِّ وَالْحَلْقُ أَوِ التَّقْصِيرُ."]]},{"id":"da39_7","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٧","segs":[["matn","وَالْمَسْنُونُ: كَالْمَبِيتِ بِمِنًى لَيْلَةَ عَرَفَةَ وَطَوَافِ الْقُدُومِ وَالرَّمَلِ فِي الثَّلَاثَةِ الْأَشْوَاطِ الْأُوَلِ مِنْهُ وَالِاضْطِبَاعِ فِيهِ وَتَجَرُّدِ الرَّجُلِ مِنَ الْمَخِيطِ عِنْدَ الْإِحْرَامِ وَلُبْسِ إِزَارٍ وَرِدَاءٍ أَبْيَضَيْنِ نَظِيفَيْنِ وَالتَّلْبِيَةِ مِنْ حِينِ الْإِحْرَامِ إِلَى أَوَّلِ الرَّمْيِ."]]},{"id":"da39_8","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٨","segs":[["matn","فَمَنْ تَرَكَ رُكْنًا لَمْ يَتِمَّ حَجُّهُ إِلَّا بِهِ وَمَنْ تَرَكَ وَاجِبًا فَعَلَيْهِ دَمٌ وَحَجُّهُ صَحِيحٌ وَمَنْ تَرَكَ مَسْنُونًا فَلَا شَيْءَ عَلَيْهِ."]]},{"id":"da39_9","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ٩","segs":[["matn","فَصْلٌ: وَشُرُوطُ صِحَّةِ الطَّوَافِ أَحَدَ عَشَرَ: النِّيَّةُ وَالْإِسْلَامُ وَالْعَقْلُ وَدُخُولُ وَقْتِهِ وَسَتْرُ الْعَوْرَةِ وَاجْتِنَابُ النَّجَاسَةِ وَالطَّهَارَةُ مِنَ الْحَدَثِ وَتَكْمِيلُ السَّبْعِ وَجَعْلُ الْبَيْتِ عَنْ يَسَارِهِ وَكَوْنُهُ مَاشِيًا مَعَ الْقُدْرَةِ وَالْمُوَالَاةُ."]]},{"id":"da39_10","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١٠","segs":[["matn","فَيَسْتَأْنِفُهُ لِحَدَثٍ فِيهِ وَكَذَا لِقَطْعٍ طَوِيلٍ وَإِنْ كَانَ يَسِيرًا أَوْ أُقِيمَتِ الصَّلَاةُ أَوْ حَضَرَتْ جِنَازَةٌ صَلَّى وَبَنَى مِنَ الْحَجَرِ الْأَسْوَدِ."]]},{"id":"da39_11","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١١","segs":[["matn","وَسُنَنُهُ: اسْتِلَامُ الرُّكْنِ الْيَمَانِيِّ بِيَدِهِ الْيُمْنَى وَكَذَا الْحَجَرُ الْأَسْوَدُ وَتَقْبِيلُهُ وَالدُّعَاءُ، وَالذِّكْرُ وَالدُّنُوُّ مِنَ الْبَيْتِ، وَالرَّكْعَتَانِ بَعْدَهُ."]]},{"id":"da39_12","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١٢","segs":[["matn","فَصْلٌ: وَشُرُوطُ صِحَّةِ السَّعْيِ ثَمَانِيَةٌ: النِّيَّةُ وَالْإِسْلَامُ وَالْعَقْلُ وَالْمُوَالَاةُ وَالْمَشْيُ مَعَ الْقُدْرَةِ وَكَوْنُهُ بَعْدَ طَوَافٍ وَلَوْ مَسْنُونًا كَطَوَافِ الْقُدُومِ وَتَكْمِيلُ السَّبْعِ وَاسْتِيعَابُ مَا بَيْنَ الصَّفَا وَالْمَرْوَةِ."]]},{"id":"da39_13","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١٣","segs":[["matn","وَإِنْ بَدَأَ بِالْمَرْوَةِ لَمْ يَعْتَدَّ بِذَلِكَ الشَّوْطِ. وَسُنَنُهُ: الطَّهَارَةُ وَسَتْرُ الْعَوْرَةِ وَالْمُوَالَاةُ بَيْنَهُ وَبَيْنَ الطَّوَافِ."]]},{"id":"da39_14","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١٤","segs":[["matn","وَسُنَّ أَنْ يَشْرَبَ مِنْ مَاءِ زَمْزَمَ لِمَا أَحَبَّ وَيَرُشَّ عَلَى بَدَنِهِ وَثَوْبِهِ وَيَقُولَ: بِسْمِ اللَّهِ اللَّهُمَّ اجْعَلْهُ لَنَا عِلْمًا نَافِعًا وَرِزْقًا وَاسِعًا وَرِيًّا وَشِبَعًا وَشِفَاءً مِنْ كُلِّ دَاءٍ وَاغْسِلْ بِهِ قَلْبِي وَامْلَأْهُ مِنْ خَشْيَتِكَ وَسُنَّ:"]]},{"id":"da39_15","label":"بَابُ أَرْكَانِ الْحَجِّ وَوَاجِبَاتِهِ · ١٥","segs":[["matn","زِيَارَةُ قَبْرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَبْرِ صَاحِبَيْهِ رِضْوَانُ اللَّهِ عَلَيْهِمَا وَتُسْتَحَبُّ الصَّلَاةُ بِمَسْجِدِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ بِأَلْفِ صَلَاةٍ. وَفِي الْمَسْجِدِ الْحَرَامِ بِمِائَةِ أَلْفٍ. وَفِي الْمَسْجِدِ الْأَقْصَى بِخَمْسِمِائَةٍ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da40","title":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ","units":[{"id":"da40_1","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ١","segs":[["matn","مَنْ طَلَعَ عَلَيْهِ فَجْرُ يَوْمِ النَّحْرِ وَلَمْ يَقِفْ بِعَرَفَةَ لِعُذْرٍ حَصْرٍ أَوْ غَيْرِهِ فَاتَهُ الْحَجُّ وَانْقَلَبَ إِحْرَامُهُ عُمْرَةً"]]},{"id":"da40_2","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ٢","segs":[["matn","وَلَا تُجْزِئُ عَنْ عُمْرَةِ الْإِسْلَامِ فَيَتَحَلَّلُ بِهَا وَعَلَيْهِ دَمٌ وَالْقَضَاءُ فِي الْعَامِ الْقَابِلِ لَكِنْ لَوْ صُدَّ عَنِ الْوُقُوفِ فَتَحَلَّلَ قَبْلَ فَوَاتِهِ فَلَا قَضَاءَ."]]},{"id":"da40_3","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ٣","segs":[["matn","وَمَنْ حُصِرَ عَنِ الْبَيْتِ وَلَوْ بَعْدَ الْوُقُوفِ ذَبَحَ هَدْيًا بِنِيَّةِ التَّحَلُّلِ فَإِنْ لَمْ يَجِدْ صَامَ عَشَرَةَ أَيَّامٍ بِنِيَّةِ التَّحَلُّلِ وَقَدْ حَلَّ."]]},{"id":"da40_4","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ٤","segs":[["matn","وَمَنْ حُصِرَ عَنْ طَوَافِ الْإِفَاضَةِ فَقَطْ وَقَدْ رَمَى وَحَلَقَ لَمْ يَتَحَلَّلْ حَتَّى يَطُوفَ."]]},{"id":"da40_5","label":"بَابُ الْفَوَاتِ وَالْإِحْصَارِ · ٥","segs":[["matn","وَمَنْ شَرَطَ فِي ابْتِدَاءِ إِحْرَامِهِ: إِنَّ مَحِلِّي حَيْثُ حَبَسْتَنِي أَوْ قَالَ: إِنْ مَرِضْتُ أَوْ عَجَزْتُ أَوْ ذَهَبَتْ نَفَقَتِي فَلِي أَنْ أَحِلَّ كَانَ لَهُ أَنْ يَتَحَلَّلَ مَتَى شَاءَ مِنْ غَيْرِ شَيْءٍ وَلَا قَضَاءَ عَلَيْهِ."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da41","title":"بَابُ الْأُضْحِيَةِ","units":[{"id":"da41_1","label":"بَابُ الْأُضْحِيَةِ · ١","segs":[["matn","وَهِيَ سُنَّةٌ مُؤَكَّدَةٌ. وَتَجِبُ بِالنَّذْرِ وَبِقَوْلِهِ: هَذِهِ أُضْحِيَةٌ أَوْ لِلَّهِ وَالْأَفْضَلُ: الْإِبِلُ فَالْبَقَرُ فَالْغَنَمُ. وَلَا تُجْزِئُ: مِنْ غَيْرِ هَذِهِ الثَّلَاثَةِ. وَتُجْزِئُ: الشَّاةُ عَنِ الْوَاحِدِ وَعَنْ أَهْلِ بَيْتِهِ وَعِيَالِهِ."]]},{"id":"da41_2","label":"بَابُ الْأُضْحِيَةِ · ٢","segs":[["matn","وَتُجْزِئُ: الْبَدَنَةُ وَالْبَقَرَةُ عَنْ سَبْعٍ. وَأَقَلُّ مَا يُجْزِئُ مِنَ الضَّأْنِ: مَا لَهُ نِصْفُ سَنَةٍ وَمِنَ الْمَعْزِ: مَا لَهُ سَنَةٌ وَمِنَ الْبَقَرِ وَالْجَامُوسِ مَا لَهُ سَنَتَانِ وَمِنَ الْإِبِلِ مَا لَهُ خَمْسُ سِنِينَ."]]},{"id":"da41_3","label":"بَابُ الْأُضْحِيَةِ · ٣","segs":[["matn","وَتُجْزِئُ الْجَمَّاءُ وَالْبَتْرَاءُ وَالْخَصِيُّ وَالْحَامِلُ وَمَا خُلِقَ بِلَا أُذُنٍ أَوْ ذَهَبَ نِصْفُ أَلْيَتِهِ أَوْ أُذُنِهِ."]]},{"id":"da41_4","label":"بَابُ الْأُضْحِيَةِ · ٤","segs":[["matn","لَا بَيِّنَةُ الْمَرَضِ وَلَا بَيِّنَةُ الْعَوَرِ بِأَنِ انْخَسَفَتْ عَيْنُهَا وَلَا قَائِمَةُ الْعَيْنَيْنِ مَعَ ذَهَابِ أَبْصَارِهِمَا وَلَا عَجْفَاءُ: وَهِيَ الْهَزِيلَةُ الَّتِي لَا مُخَّ فِيهَا."]]},{"id":"da41_5","label":"بَابُ الْأُضْحِيَةِ · ٥","segs":[["matn","وَلَا عَرْجَاءُ لَا تُطِيقُ مَشْيًا مَعَ صَحِيحَةٍ وَلَا هَتْمَاءُ: وَهِيَ الَّتِي ذَهَبَتْ ثَنَايَاهَا مِنْ أَصْلِهَا وَلَا عَصْمَاءُ: وَهِيَ مَا انْكَسَرَ غِلَافُ قَرْنِهَا وَلَا خَصِيٌّ مَجْبُوبٌ وَلَا عَضْبَاءُ وَهِيَ مَا ذَهَبَ أَكْثَرُ أُذُنِهَا أَوْ قَرْنِهَا."]]},{"id":"da41_6","label":"بَابُ الْأُضْحِيَةِ · ٦","segs":[["matn","فَصْلٌ: وَيُسَنُّ: نَحْرُ الْإِبِلِ قَائِمَةً مَعْقُولَةً يَدُهَا الْيُسْرَى وَذَبْحُ الْبَقَرِ وَالْغَنَمِ عَلَى جَنْبِهَا الْأَيْسَرِ مُوَجَّهَةً إِلَى الْقِبْلَةِ."]]},{"id":"da41_7","label":"بَابُ الْأُضْحِيَةِ · ٧","segs":[["matn","وَيُسَمِّي حِينَ يُحَرِّكُ يَدَهُ بِالْفِعْلِ وَيُكَبِّرُ وَيَقُولُ: اللَّهُمَّ هَذَا مِنْكَ وَلَكَ وَأَوَّلُ وَقْتِ الذَّبْحِ مِنْ بَعْدِ أَسْبَقِ صَلَاةِ الْعِيدِ بِالْبَلَدِ أَوْ قَدْرِهَا لِمَنْ لَمْ يُصَلِّ فَلَا يُجْزِئُ قَبْلَ ذَلِكَ وَيَسْتَمِرُّ وَقْتُ الذَّبْحِ نَهَارًا وَلَيْلًا إِلَى آخِرِ ثَانِي أَيَّامِ التَّشْرِيقِ."]]},{"id":"da41_8","label":"بَابُ الْأُضْحِيَةِ · ٨","segs":[["matn","فَإِنْ فَاتَ الْوَقْتُ قَضَى الْوَاجِبَ وَسَقَطَ التَّطَوُّعُ. وَسُنَّ لَهُ: الْأَكْلُ مِنْ هَدْيِ التَّطَوُّعِ وَمِنْ أُضْحِيَتِهِ وَلَوْ وَاجِبَةً. وَيَجُوزُ مِنَ الْمُتْعَةِ وَالْقِرَانِ."]]},{"id":"da41_9","label":"بَابُ الْأُضْحِيَةِ · ٩","segs":[["matn","وَيَجِبُ: أَنْ يَتَصَدَّقَ بِأَقَلِّ مَا يَقَعُ عَلَيْهِ اسْمُ اللَّحْمِ وَيُعْتَبَرُ تَمْلِيكُ الْفَقِيرِ فَلَا يَكْفِي إِطْعَامُهُ. وَالسُّنَّةُ: أَنْ يَأْكُلَ مِنْ أُضْحِيَتِهِ ثُلُثَهَا وَيُهْدِيَ ثُلُثَهَا وَيَتَصَدَّقَ بِثُلُثِهَا."]]},{"id":"da41_10","label":"بَابُ الْأُضْحِيَةِ · ١٠","segs":[["matn","وَيَحْرُمُ: بَيْعُ شَيْءٍ مِنْهَا حَتَّى مِنْ شَعْرِهَا وَجِلْدِهَا. وَلَا يُعْطِي الْجَازِرَ بِأُجْرَتِهِ مِنْهَا شَيْئًا وَلَهُ إِعْطَاؤُهُ صَدَقَةً وَهَدِيَّةً."]]},{"id":"da41_11","label":"بَابُ الْأُضْحِيَةِ · ١١","segs":[["matn","وَإِذَا دَخَلَ الْعَشْرُ: حَرُمَ عَلَى مَنْ يُضَحِّي أَوْ يُضَحَّى عَنْهُ أَخْذُ شَيْءٍ مِنْ شَعْرِهِ أَوْ ظُفْرِهِ إِلَى الذَّبْحِ. وَيُسَنُّ الْحَلْقُ بَعْدَهُ."]]},{"id":"da41_12","label":"بَابُ الْأُضْحِيَةِ · ١٢","segs":[["matn","فَصْلٌ فِي الْعَقِيقَةِ: وَهِيَ سُنَّةٌ فِي حَقِّ الْأَبِ وَلَوْ مُعْسِرًا فَعَنِ الْغُلَامِ شَاتَانِ وَعَنِ الْجَارِيَةِ شَاةٌ وَلَا تُجْزِئُ: بَدَنَةٌ وَلَا بَقَرَةٌ إِلَّا كَامِلَةً."]]},{"id":"da41_13","label":"بَابُ الْأُضْحِيَةِ · ١٣","segs":[["matn","وَالسُّنَّةُ: ذَبْحُهَا فِي سَابِعِ يَوْمِ وِلَادَتِهِ فَإِنْ فَاتَ فَفِي أَرْبَعَةَ عَشَرَ فَإِنْ فَاتَ فَفِي إِحْدَى وَعِشْرِينَ وَلَا تُعْتَبَرُ الْأَسَابِيعُ بَعْدَ ذَلِكَ. وَكُرِهَ لَطْخُهُ مِنْ دَمِهَا."]]},{"id":"da41_14","label":"بَابُ الْأُضْحِيَةِ · ١٤","segs":[["matn","وَيُسَنُّ الْأَذَانُ فِي أُذُنِ الْمَوْلُودِ الْيُمْنَى حِينَ يُولَدُ وَالْإِقَامَةُ فِي الْيُسْرَى. وَيُسَنُّ: أَنْ يُحْلَقَ رَأْسُ الْغُلَامِ فِي الْيَوْمِ السَّابِعِ وَيُتَصَدَّقَ بِوَزْنِهِ فِضَّةً وَيُسَمَّى فِيهِ. وَأَحَبُّ الْأَسْمَاءِ: عَبْدُ اللَّهِ وَعَبْدُ الرَّحْمَنِ."]]},{"id":"da41_15","label":"بَابُ الْأُضْحِيَةِ · ١٥","segs":[["matn","وَتَحْرُمُ: التَّسْمِيَةُ بِعَبْدِ غَيْرِ اللَّهِ كَعَبْدِ النَّبِيِّ وَعَبْدِ الْمَسِيحِ. وَتُكْرَهُ: بِحَرْبٍ وَيَسَارٍ وَمُبَارَكٍ وَمُفْلِحٍ وَخَيْرٍ وَسُرُورٍ. لَا بِأَسْمَاءِ الْمَلَائِكَةِ وَالْأَنْبِيَاءِ. وَإِنِ اتَّفَقَ وَقْتُ عَقِيقَةٍ وَأُضْحِيَةٍ أَجْزَأَتْ إِحْدَاهُمَا عَنِ الْأُخْرَى."]]}],"group":"كِتَابُ الْحَجِّ"},{"id":"da42","title":"كِتَابُ الْجِهَادِ","units":[{"id":"da42_1","label":"كِتَابُ الْجِهَادِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ. وَيُسَنُّ: مَعَ قِيَامِ مَنْ يَكْفِي بِهِ."]]},{"id":"da42_2","label":"كِتَابُ الْجِهَادِ · ٢","segs":[["matn","وَلَا يَجِبُ: إِلَّا عَلَى ذَكَرٍ حُرٍّ مُسْلِمٍ مُكَلَّفٍ صَحِيحٍ وَاجِدٍ مِنَ الْمَالِ مَا يَكْفِيهِ وَيَكْفِي أَهْلَهُ فِي غَيْبَتِهِ وَيَجِدُ مَعَ مَسَافَةِ قَصْرٍ مَا يَحْمِلُهُ. وَسُنَّ تَشْيِيعُ الْغَازِي لَا تَلَقِّيهِ."]]},{"id":"da42_3","label":"كِتَابُ الْجِهَادِ · ٣","segs":[["matn","وَأَفْضَلُ مُتَطَوَّعٍ بِهِ الْجِهَادُ وَغَزْوُ الْبَحْرِ أَفْضَلُ. وَتُكَفِّرُ الشَّهَادَةُ جَمِيعَ الذُّنُوبِ سِوَى الدَّيْنِ."]]},{"id":"da42_4","label":"كِتَابُ الْجِهَادِ · ٤","segs":[["matn","وَلَا يَتَطَوَّعُ: بِهِ مَدِينٌ لَا وَفَاءَ لَهُ إِلَّا بِإِذْنِ غَرِيمِهِ وَلَا مَنْ أَحَدُ أَبَوَيْهِ حُرٌّ مُسْلِمٌ إِلَّا بِإِذْنِهِ."]]},{"id":"da42_5","label":"كِتَابُ الْجِهَادِ · ٥","segs":[["matn","وَيُسَنُّ الرِّبَاطُ: وَهُوَ لُزُومُ الثَّغْرِ لِلْجِهَادِ وَأَقَلُّهُ سَاعَةٌ وَتَمَامُهُ أَرْبَعُونَ يَوْمًا وَهُوَ أَفْضَلُ مِنَ الْمُقَامِ بِمَكَّةَ وَأَفْضَلُهُ مَا كَانَ أَشَدَّ خَوْفًا."]]},{"id":"da42_6","label":"كِتَابُ الْجِهَادِ · ٦","segs":[["matn","وَلَا يَجُوزُ لِلْمُسْلِمِينَ الْفِرَارُ مِنْ مِثْلَيْهِمْ وَلَوْ وَاحِدًا مِنَ اثْنَيْنِ فَإِنْ زَادُوا عَلَى مِثْلَيْهِمْ جَازَ."]]},{"id":"da42_7","label":"كِتَابُ الْجِهَادِ · ٧","segs":[["matn","وَالْهِجْرَةُ وَاجِبَةٌ عَلَى كُلِّ مَنْ عَجَزَ عَنْ إِظْهَارِ دِينِهِ بِمَحَلٍّ يَغْلِبُ فِيهِ حُكْمُ الْكُفْرِ وَالْبِدَعِ الْمُضِلَّةِ فَإِنْ قَدَرَ عَلَى إِظْهَارِ دِينِهِ فَمَسْنُونَةٌ."]]},{"id":"da42_8","label":"كِتَابُ الْجِهَادِ · ٨","segs":[["matn","فَصْلٌ: وَالْأُسَارَى مِنَ الْكُفَّارِ عَلَى قِسْمَيْنِ: قِسْمٌ يَكُونُ رَقِيقًا بِمُجَرَّدِ السَّبْيِ: وَهُمُ النِّسَاءُ وَالصِّبْيَانُ."]]},{"id":"da42_9","label":"كِتَابُ الْجِهَادِ · ٩","segs":[["matn","وَقِسْمٌ لَا: وَهُمُ الرِّجَالُ الْبَالِغُونَ الْمُقَاتِلُونَ وَالْإِمَامُ فِيهِمْ مُخَيَّرٌ بَيْنَ: قَتْلٍ وَرِقٍّ وَمَنٍّ وَفِدَاءٍ بِمَالٍ أَوْ بِأَسِيرٍ مُسْلِمٍ وَيَجِبُ عَلَيْهِ فِعْلُ الْأَصْلَحِ. وَلَا يَصِحُّ بَيْعُ مُسْتَرَقٍّ مِنْهُمْ لِكَافِرٍ."]]},{"id":"da42_10","label":"كِتَابُ الْجِهَادِ · ١٠","segs":[["matn","وَيُحْكَمُ بِإِسْلَامِ مَنْ لَمْ يَبْلُغْ مِنْ أَوْلَادِ الْكُفَّارِ عِنْدَ وُجُودِ أَحَدِ ثَلَاثَةِ أَسْبَابٍ: أَحَدُهَا: أَنْ يُسْلِمَ أَحَدُ أَبَوَيْهِ خَاصَّةً. الثَّانِي: أَنْ يُعْدَمَ أَحَدُهُمَا بِدَارِنَا."]]},{"id":"da42_11","label":"كِتَابُ الْجِهَادِ · ١١","segs":[["matn","الثَّالِثُ: أَنْ يَسْبِيَهُ مُسْلِمٌ مُنْفَرِدًا عَنْ أَحَدِ أَبَوَيْهِ. فَإِنْ سَبَاهُ ذِمِّيٌّ فَعَلَى دِينِهِ أَوْ سُبِيَ مَعَ أَبَوَيْهِ فَعَلَى دِينِهِمَا."]]},{"id":"da42_12","label":"كِتَابُ الْجِهَادِ · ١٢","segs":[["matn","فَصْلٌ: وَمَنْ قَتَلَ قَتِيلًا فِي حَالَةِ الْحَرْبِ فَلَهُ سَلَبُهُ وَهُوَ مَا عَلَيْهِ مِنْ ثِيَابٍ وَحُلِيٍّ وَسِلَاحٍ وَكَذَا دَابَّتُهُ الَّتِي قَاتَلَ عَلَيْهَا وَمَا عَلَيْهَا وَأَمَّا نَفَقَتُهُ وَرَحْلُهُ وَخَيْمَتُهُ وَجَنِيبُهُ فَغَنِيمَةٌ."]]},{"id":"da42_13","label":"كِتَابُ الْجِهَادِ · ١٣","segs":[["matn","وَتُقْسَمُ الْغَنِيمَةُ بَيْنَ الْغَانِمِينَ فَيُعْطَى لَهُمْ أَرْبَعَةُ أَخْمَاسِهَا لِلرَّاجِلِ: سَهْمٌ وَلِلْفَارِسِ عَلَى فَرَسٍ هَجِينٍ سَهْمَانِ وَعَلَى فَرَسٍ عَرَبِيٍّ ثَلَاثَةٌ."]]},{"id":"da42_14","label":"كِتَابُ الْجِهَادِ · ١٤","segs":[["matn","وَلَا يُسْهَمُ لِغَيْرِ الْخَيْلِ وَلَا يُسْهَمُ إِلَّا لِمَنْ فِيهِ أَرْبَعَةُ شُرُوطٍ: الْبُلُوغُ وَالْعَقْلُ وَالْحُرِّيَّةُ وَالذُّكُورَةُ. فَإِنِ اخْتَلَّ شَرْطٌ رُضِخَ لَهُ وَلَمْ يُسْهَمْ."]]},{"id":"da42_15","label":"كِتَابُ الْجِهَادِ · ١٥","segs":[["matn","وَيُقْسَمُ الْخُمُسُ الْبَاقِي خَمْسَةَ أَسْهُمٍ: سَهْمٌ لِلَّهِ وَلِرَسُولِهِ يُصْرَفُ مَصْرِفَ الْفَيْءِ وَسَهْمٌ لِذَوِي الْقُرْبَى وَهُمْ: بَنُو هَاشِمٍ وَبَنُو الْمُطَّلِبِ حَيْثُ كَانُوا لِلذَّكَرِ مِثْلَ حَظِّ الْأُنْثَيَيْنِ وَسَهْمٌ لِفُقَرَاءِ الْيَتَامَى وَهُمْ مَنْ لَا أَبَ لَهُ وَلَمْ يَبْلُغْ وَسَهْمٌ لِلْمَسَاكِينِ وَسَهْمٌ لِأَبْنَاءِ السَّبِيلِ."]]},{"id":"da42_16","label":"كِتَابُ الْجِهَادِ · ١٦","segs":[["matn","فَصْلٌ: وَالْفَيْءُ: هُوَ مَا أُخِذَ مِنْ مَالِ الْكُفَّارِ بِحَقٍّ مِنْ غَيْرِ قِتَالٍ كَالْجِزْيَةِ وَالْخَرَاجِ وَعُشْرِ التِّجَارَةِ مِنَ الْحَرْبِيِّ وَنِصْفِ الْعُشْرِ مِنَ الذِّمِّيِّ وَمَا تَرَكُوهُ فَزَعًا أَوْ عَنْ مَيِّتٍ وَلَا وَارِثَ لَهُ."]]},{"id":"da42_17","label":"كِتَابُ الْجِهَادِ · ١٧","segs":[["matn","وَمَصْرِفُهُ فِي مَصَالِحِ الْمُسْلِمِينَ وَيُبْدَأُ بِالْأَهَمِّ فَالْأَهَمِّ مِنْ سَدِّ ثَغْرٍ وَكِفَايَةِ أَهْلِهِ وَحَاجَةِ مَنْ يَدْفَعُ عَنِ الْمُسْلِمِينَ وَعِمَارَةِ الْقَنَاطِرِ وَرِزْقِ الْقُضَاةِ وَالْفُقَهَاءِ وَغَيْرِ ذَلِكَ فَإِنْ فَضَلَ شَيْءٌ قُسِمَ بَيْنَ أَحْرَارِ الْمُسْلِمِينَ غَنِيِّهِمْ وَفَقِيرِهِمْ."]]},{"id":"da42_18","label":"كِتَابُ الْجِهَادِ · ١٨","segs":[["matn","وَبَيْتُ الْمَالِ مِلْكٌ لِلْمُسْلِمِينَ وَيَضْمَنُهُ مُتْلِفُهُ وَيَحْرُمُ الْأَخْذُ مِنْهُ بِلَا إِذْنِ الْإِمَامِ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"da43","title":"بَابُ عَقْدِ الذِّمَّةِ","units":[{"id":"da43_1","label":"بَابُ عَقْدِ الذِّمَّةِ · ١","segs":[["matn","لَا تُعْقَدُ إِلَّا لِأَهْلِ الْكِتَابِ أَوْ لِمَنْ لَهُ شُبْهَةُ كِتَابٍ كَالْمَجُوسِ. وَيَجِبُ عَلَى الْإِمَامِ عَقْدُهَا حَيْثُ أَمِنَ مَكْرَهُمْ وَالْتَزَمُوا لَنَا بِأَرْبَعَةِ أَحْكَامٍ: أَحَدُهَا: أَنْ يُعْطُوا الْجِزْيَةَ عَنْ يَدٍ وَهُمْ صَاغِرُونَ."]]},{"id":"da43_2","label":"بَابُ عَقْدِ الذِّمَّةِ · ٢","segs":[["matn","الثَّانِي: أَنْ لَا يَذْكُرُوا دِينَ الْإِسْلَامِ إِلَّا بِالْخَيْرِ. الثَّالِثُ: أَنْ لَا يَفْعَلُوا مَا فِيهِ ضَرَرٌ عَلَى الْمُسْلِمِينَ."]]},{"id":"da43_3","label":"بَابُ عَقْدِ الذِّمَّةِ · ٣","segs":[["matn","الرَّابِعُ: أَنْ تَجْرِيَ عَلَيْهِمْ أَحْكَامُ الْإِسْلَامِ فِي نَفْسٍ وَمَالٍ وَعِرْضٍ وَإِقَامَةِ حَدٍّ فِيمَا يُحَرِّمُونَهُ كَالزِّنَا لَا فِيمَا يُحِلُّونَهُ كَالْخَمْرِ."]]},{"id":"da43_4","label":"بَابُ عَقْدِ الذِّمَّةِ · ٤","segs":[["matn","وَلَا تُؤْخَذُ الْجِزْيَةُ مِنِ امْرَأَةٍ وَخُنْثَى وَصَبِيٍّ وَمَجْنُونٍ وَقِنٍّ وَزَمِنٍ وَأَعْمَى وَشَيْخٍ فَانٍ وَرَاهِبٍ بِصَوْمَعَةٍ. وَمَنْ أَسْلَمَ مِنْهُمْ بَعْدَ الْحَوْلِ سَقَطَتْ عَنْهُ الْجِزْيَةُ."]]},{"id":"da43_5","label":"بَابُ عَقْدِ الذِّمَّةِ · ٥","segs":[["matn","فَصْلٌ: وَيَحْرُمُ قَتْلُ أَهْلِ الذِّمَّةِ وَأَخْذُ مَالِهِمْ. وَيَجِبُ عَلَى الْإِمَامِ حِفْظُهُمْ وَمَنْعُ مَنْ يُؤْذِيهِمْ."]]},{"id":"da43_6","label":"بَابُ عَقْدِ الذِّمَّةِ · ٦","segs":[["matn","وَيُمْنَعُونَ مِنْ رُكُوبِ الْخَيْلِ وَحَمْلِ السِّلَاحِ وَمِنْ إِحْدَاثِ الْكَنَائِسِ وَمِنْ بِنَاءِ مَا انْهَدَمَ مِنْهَا وَمِنْ إِظْهَارِ الْمُنْكَرِ وَالْعِيدِ وَالصَّلِيبِ وَضَرْبِ النَّاقُوسِ وَمِنَ الْجَهْرِ بِكِتَابِهِمْ"]]},{"id":"da43_7","label":"بَابُ عَقْدِ الذِّمَّةِ · ٧","segs":[["matn","وَمِنَ الْأَكْلِ وَالشُّرْبِ نَهَارَ رَمَضَانَ وَمِنْ شُرْبِ الْخَمْرِ وَأَكْلِ الْخِنْزِيرِ وَيُمْنَعُونَ مِنْ قِرَاءَةِ الْقُرْآنِ وَشِرَاءِ الْمُصْحَفِ وَكُتُبِ الْفِقْهِ وَالْحَدِيثِ وَمِنْ تَعْلِيَةِ الْبِنَاءِ عَلَى الْمُسْلِمِينَ. وَيَلْزَمُهُمُ التَّمْيِيزُ عَنَّا بِلُبْسِهِمْ."]]},{"id":"da43_8","label":"بَابُ عَقْدِ الذِّمَّةِ · ٨","segs":[["matn","وَيُكْرَهُ لَنَا التَّشَبُّهُ بِهِمْ. وَيَحْرُمُ الْقِيَامُ لَهُمْ وَتَصْدِيرُهُمْ فِي الْمَجَالِسِ وَبُدَاءَتُهُمْ بِالسَّلَامِ وَبِكَيْفَ أَصْبَحْتَ أَوْ أَمْسَيْتَ؟ أَوْ كَيْفَ أَنْتَ أَوْ حَالُكَ؟ وَتَحْرُمُ تَهْنِئَتُهُمْ وَتَعْزِيَتُهُمْ وَعِيَادَتُهُمْ."]]},{"id":"da43_9","label":"بَابُ عَقْدِ الذِّمَّةِ · ٩","segs":[["matn","وَمَنْ سَلَّمَ عَلَى ذِمِّيٍّ ثُمَّ عَلِمَهُ سُنَّ قَوْلُهُ: رُدَّ عَلَيَّ سَلَامِي. وَإِنْ سَلَّمَ الذِّمِّيُّ لَزِمَ رَدُّهُ فَيُقَالُ: وَعَلَيْكُمْ وَإِنْ شَمَّتَ كَافِرٌ مُسْلِمًا أَجَابَهُ. وَتُكْرَهُ مُصَافَحَتُهُ."]]},{"id":"da43_10","label":"بَابُ عَقْدِ الذِّمَّةِ · ١٠","segs":[["matn","فَصْلٌ: وَمَنْ أَبَى مِنْ أَهْلِ الذِّمَّةِ بَذْلَ الْجِزْيَةِ أَوْ أَبَى الصَّغَارَ أَوْ أَبَى الْتِزَامَ حُكْمِنَا أَوْ زَنَى بِمُسْلِمَةٍ أَوْ أَصَابَهَا بِنِكَاحٍ أَوْ قَطَعَ الطَّرِيقَ أَوْ ذَكَرَ اللَّهَ تَعَالَى أَوْ رَسُولَهُ بِسُوءٍ أَوْ تَعَدَّى عَلَى مُسْلِمٍ بِقَتْلٍ أَوْ فِتْنَةٍ عَنْ دِينِهِ انْتَقَضَ عَهْدُهُ."]]},{"id":"da43_11","label":"بَابُ عَقْدِ الذِّمَّةِ · ١١","segs":[["matn","وَيُخَيَّرُ الْإِمَامُ فِيهِ كَالْأَسِيرِ وَمَالُهُ فَيْءٌ وَلَا يَنْتَقِضُ عَهْدُ نِسَائِهِ وَأَوْلَادِهِ فَإِنْ أَسْلَمَ حَرُمَ قَتْلُهُ وَلَوْ كَانَ سَبَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]}],"group":"كِتَابُ الْجِهَادِ"},{"id":"da44","title":"كِتَابُ الْبَيْعِ","units":[{"id":"da44_1","label":"كِتَابُ الْبَيْعِ · ١","segs":[["matn","وَيَنْعَقِدُ لَا هَزْلًا بِالْقَوْلِ الدَّالِّ عَلَى الْبَيْعِ وَالشِّرَاءِ وَبِالْمُعَاطَاةِ كَأَعْطِنِيَ بِهَذَا خُبْزًا فَيُعْطِيهِ مَا يُرْضِيهِ. وَشُرُوطُهُ سَبْعَةٌ: أَحَدُهَا: الرِّضَى فَلَا يَصِحُّ بَيْعُ الْمُكْرَهِ بِغَيْرِ حَقٍّ."]]},{"id":"da44_2","label":"كِتَابُ الْبَيْعِ · ٢","segs":[["matn","الثَّانِي الرُّشْدُ فَلَا يَصِحُّ بَيْعُ الْمُمَيِّزِ وَالسَّفِيهِ مَا لَمْ يَأْذَنْ وَلِيُّهُمَا. الثَّالِثُ: كَوْنُ الْمَبِيعِ مَالًا فَلَا يَصِحُّ بَيْعُ الْخَمْرِ وَالْكَلْبِ وَالْمَيْتَةِ."]]},{"id":"da44_3","label":"كِتَابُ الْبَيْعِ · ٣","segs":[["matn","الرَّابِعُ: أَنْ يَكُونَ الْمَبِيعُ مِلْكًا لِلْبَائِعِ أَوْ مَأْذُونًا لَهُ فِيهِ وَقْتَ الْعَقْدِ فَلَا يَصِحُّ بَيْعُ الْفُضُولِيِّ وَلَوْ أُجِيزَ بَعْدُ."]]},{"id":"da44_4","label":"كِتَابُ الْبَيْعِ · ٤","segs":[["matn","الْخَامِسُ: الْقُدْرَةُ عَلَى تَسْلِيمِهِ فَلَا يَصِحُّ بَيْعُ الْآبِقِ وَالشَّارِدِ وَلَوْ لِقَادِرٍ عَلَى تَحْصِيلِهِمَا. السَّادِسُ: مَعْرِفَةُ الثَّمَنِ وَالْمُثْمَنِ إِمَّا بِالْوَصْفِ أَوِ الْمُشَاهَدَةِ حَالَ الْعَقْدِ أَوْ قَبْلَهُ بِيَسِيرٍ."]]},{"id":"da44_5","label":"كِتَابُ الْبَيْعِ · ٥","segs":[["matn","السَّابِعُ: أَنْ يَكُونَ مُنَجَّزًا لَا مُعَلَّقًا كَبِعْتُكَ إِذَا جَاءَ رَأْسُ الشَّهْرِ أَوْ إِنْ رَضِيَ زَيْدٌ وَيَصِحُّ بِعْتُ وَقَبِلْتُ إِنْ شَاءَ اللَّهُ."]]},{"id":"da44_6","label":"كِتَابُ الْبَيْعِ · ٦","segs":[["matn","وَمَنْ بَاعَ مَعْلُومًا وَمَجْهُولًا لَمْ يَتَعَذَّرْ عِلْمُهُ صَحَّ فِي الْمَعْلُومِ بِقِسْطِهِ وَإِنْ تَعَذَّرَ مَعْرِفَةُ الْمَجْهُولِ وَلَمْ يُبَيِّنْ ثَمَنَ الْمَعْلُومِ فَبَاطِلٌ."]]},{"id":"da44_7","label":"كِتَابُ الْبَيْعِ · ٧","segs":[["matn","فَصْلٌ: وَيَحْرُمُ وَلَا يَصِحُّ بَيْعٌ وَلَا شِرَاءٌ فِي الْمَسْجِدِ وَلَا مِمَّنْ تَلْزَمُهُ الْجُمُعَةُ بَعْدَ نِدَائِهَا الَّذِي عِنْدَ الْمِنْبَرِ وَكَذَا لَوْ تَضَايَقَ وَقْتُ الْمَكْتُوبَةِ وَلَا بَيْعُ الْعِنَبِ أَوِ الْعَصِيرِ لِمُتَّخِذِهِ خَمْرًا وَلَا بَيْعُ الْبَيْضِ وَالْجَوْزِ وَنَحْوِهِمَا لِلْقِمَارِ وَلَا بَيْعُ السِّلَاحِ"]]},{"id":"da44_8","label":"كِتَابُ الْبَيْعِ · ٨","segs":[["matn","فِي الْفِتْنَةِ أَوْ لِأَهْلِ الْحَرْبِ أَوْ قُطَّاعِ الطَّرِيقِ وَلَا بَيْعُ قِنٍّ مُسْلِمٍ لِكَافِرٍ لَا يَعْتِقُ عَلَيْهِ وَلَا بَيْعٌ عَلَى بَيْعِ الْمُسْلِمِ كَقَوْلِهِ لِمَنِ اشْتَرَى شَيْئًا بِعَشَرَةٍ أُعْطِيكَ مِثْلَهُ بِتِسْعَةٍ وَلَا شِرَاءٌ عَلَيْهِ كَقَوْلِهِ لِمَنْ بَاعَ شَيْئًا بِتِسْعَةٍ: عِنْدِي فِيهِ عَشَرَةٌ."]]},{"id":"da44_9","label":"كِتَابُ الْبَيْعِ · ٩","segs":[["matn","وَأَمَّا السَّوْمُ عَلَى سَوْمِ الْمُسْلِمِ مَعَ الرِّضَى الصَّرِيحِ وَبَيْعُ الْمُصْحَفِ وَالْأَمَةِ الَّتِي يَطَؤُهَا قَبْلَ اسْتِبْرَائِهَا فَحَرَامٌ وَيَصِحُّ الْعَقْدُ. وَلَا يَصِحُّ التَّصَرُّفُ فِي الْمَقْبُوضِ بِعَقْدٍ فَاسِدٍ وَيُضْمَنُ هُوَ وَزِيَادَتُهُ كَمَغْصُوبٍ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da45","title":"بَابُ الشُّرُوطِ فِي الْبَيْعِ","units":[{"id":"da45_1","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ١","segs":[["matn","وَهِيَ قِسْمَانِ: صَحِيحٌ لَازِمٌ وَفَاسِدٌ مُبْطِلٌ لِلْبَيْعِ. فَالصَّحِيحُ: كَشَرْطِ تَأْجِيلِ الثَّمَنِ أَوْ بَعْضِهِ أَوْ رَهْنٍ أَوْ ضَمِينٍ مُعَيَّنٍ أَوْ شَرَطَ صِفَةً فِي الْمَبِيعِ كَالْعَبْدِ كَاتِبًا أَوْ صَانِعًا أَوْ مُسْلِمًا."]]},{"id":"da45_2","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٢","segs":[["matn","وَالْأَمَةِ: بِكْرًا أَوْ تَحِيضُ وَالدَّابَّةِ هِمْلَاجَةً أَوْ لَبُونًا أَوْ حَامِلًا وَالْفَهْدِ أَوِ الْبَازِي: صَيُودًا فَإِنْ وُجِدَ الْمَشْرُوطُ لَزِمَ الْبَيْعُ وَإِلَّا فَلِلْمُشْتَرِي الْفَسْخُ أَوْ أَرْشُ فَقْدِ الصِّفَةِ."]]},{"id":"da45_3","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٣","segs":[["matn","وَيَصِحُّ: أَنْ يَشْتَرِطَ الْبَائِعُ عَلَى الْمُشْتَرِي مَنْفَعَةَ مَا بَاعَهُ مُدَّةً مَعْلُومَةً كَسُكْنَى الدَّارِ شَهْرًا وَحُمْلَانِ الدَّابَّةِ إِلَى مَحَلٍّ مُعَيَّنٍ وَأَنْ يَشْتَرِطَ الْمُشْتَرِي عَلَى الْبَائِعِ حَمْلَ مَا بَاعَهُ أَوْ تَكْسِيرَهُ أَوْ خِيَاطَتَهُ أَوْ تَفْصِيلَهُ."]]},{"id":"da45_4","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٤","segs":[["matn","فَصْلٌ: وَالْفَاسِدُ الْمُبْطِلُ كَشَرْطِ بَيْعٍ آخَرَ أَوْ سَلَفٍ أَوْ قَرْضٍ أَوْ إِجَارَةٍ أَوْ شَرِكَةٍ."]]},{"id":"da45_5","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٥","segs":[["matn","أَوْ صَرْفٍ لِلثَّمَنِ وَهُوَ بَيْعَتَانِ فِي بَيْعَةٍ الْمَنْهِيُّ عَنْهُ وَكَذَا كُلُّ مَا كَانَ فِي مَعْنَى ذَلِكَ مِثْلَ أَنْ تُزَوِّجَنِي ابْنَتَكَ أَوْ أُزَوِّجَكَ ابْنَتِي أَوْ تُنْفِقَ عَلَى عَبْدِي أَوْ دَابَّتِي؟"]]},{"id":"da45_6","label":"بَابُ الشُّرُوطِ فِي الْبَيْعِ · ٦","segs":[["matn","وَمَنْ بَاعَ مَا يُذْرَعُ عَلَى أَنَّهُ عَشَرَةٌ فَبَانَ أَكْثَرَ أَوْ أَقَلَّ صَحَّ الْبَيْعُ وَلِكُلٍّ الْفَسْخُ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da46","title":"بَابُ الْخِيَارِ","units":[{"id":"da46_1","label":"بَابُ الْخِيَارِ · ١","segs":[["matn","وَأَقْسَامُهُ سَبْعَةٌ: أَحَدُهَا: خِيَارُ الْمَجْلِسِ وَيَثْبُتُ لِلْمُتَعَاقِدَيْنِ مِنْ حِينِ الْعَقْدِ إِلَى أَنْ يَتَفَرَّقَا مِنْ غَيْرِ إِكْرَاهٍ مَا لَمْ يَتَبَايَعَا عَلَى أَنْ لَا خِيَارَ أَوْ يُسْقِطَاهُ بَعْدَ الْعَقْدِ"]]},{"id":"da46_2","label":"بَابُ الْخِيَارِ · ٢","segs":[["matn","وَإِنْ أَسْقَطَهُ أَحَدُهُمَا بَقِيَ خِيَارُ الْآخَرِ وَيَنْقَطِعُ الْخِيَارُ بِمَوْتِ أَحَدِهِمَا لَا بِجُنُونِهِ وَهُوَ عَلَى خِيَارِهِ إِذَا أَفَاقَ وَتَحْرُمُ الْفُرْقَةُ مِنَ الْمَجْلِسِ خَشْيَةَ الِاسْتِقَالَةِ."]]},{"id":"da46_3","label":"بَابُ الْخِيَارِ · ٣","segs":[["matn","الثَّانِي: خِيَارُ الشَّرْطِ: وَهُوَ أَنْ يَشْرِطَا أَوْ أَحَدُهُمَا الْخِيَارَ إِلَى مُدَّةٍ مَعْلُومَةٍ فَيَصِحُّ وَإِنْ طَالَتِ الْمُدَّةُ لَكِنْ يَحْرُمُ تَصَرُّفُهُمَا فِي الثَّمَنِ وَالْمُثْمَنِ فِي مُدَّةِ الْخِيَارِ وَيَنْتَقِلُ الْمِلْكُ مِنْ حِينِ الْعَقْدِ فَمَا حَصَلَ"]]},{"id":"da46_4","label":"بَابُ الْخِيَارِ · ٤","segs":[["matn","فِي تِلْكَ الْمُدَّةِ مِنَ النَّمَاءِ الْمُنْفَصِلِ فَلِلْمُنْتَقِلِ لَهُ وَلَوْ أَنَّ الشَّرْطَ لِلْآخَرِ فَقَطْ وَلَا يَفْتَقِرُ فَسْخُ مَنْ يَمْلِكُهُ إِلَى حُضُورِ صَاحِبِهِ وَلَا رِضَاهُ فَإِنْ مَضَى زَمَنُ الْخِيَارِ وَلَمْ يُفْسَخْ صَارَ لَازِمًا."]]},{"id":"da46_5","label":"بَابُ الْخِيَارِ · ٥","segs":[["matn","وَيَسْقُطُ الْخِيَارُ بِالْقَوْلِ وَبِالْفِعْلِ كَتَصَرُّفِ الْمُشْتَرِي فِي الْمَبِيعِ بِوَقْفٍ أَوْ هِبَةٍ أَوْ سَوْمٍ أَوْ لَمْسٍ بِشَهْوَةٍ وَيَنْفُذُ تَصَرُّفُهُ إِنْ كَانَ الْخِيَارُ لَهُ فَقَطْ."]]},{"id":"da46_6","label":"بَابُ الْخِيَارِ · ٦","segs":[["matn","الثَّالِثُ: خِيَارُ الْغَبْنِ: وَهُوَ أَنْ يَبِيعَ مَا يُسَاوِي عَشَرَةً بِثَمَانِيَةٍ أَوْ يَشْتَرِيَ مَا يُسَاوِي ثَمَانِيَةً بِعَشَرَةٍ فَيَثْبُتُ الْخِيَارُ وَلَا أَرْشَ مَعَ الْإِمْسَاكِ."]]},{"id":"da46_7","label":"بَابُ الْخِيَارِ · ٧","segs":[["matn","الرَّابِعُ: خِيَارُ التَّدْلِيسِ: وَهُوَ أَنْ يُدَلِّسَ الْبَائِعُ عَلَى الْمُشْتَرِي مَا يَزِيدُ بِهِ الثَّمَنُ كَتَصْرِيَةِ اللَّبَنِ فِي الضَّرْعِ وَتَحْمِيرِ الْوَجْهِ وَتَسْوِيدِ الشَّعْرِ فَيَحْرُمُ وَيَثْبُتُ لِلْمُشْتَرِي الْخِيَارُ حَتَّى وَلَوْ حَصَلَ التَّدْلِيسُ مِنَ الْبَائِعِ بِلَا قَصْدٍ."]]},{"id":"da46_8","label":"بَابُ الْخِيَارِ · ٨","segs":[["matn","الْخَامِسُ: خِيَارُ الْعَيْبِ فَإِذَا وَجَدَ الْمُشْتَرِي بِمَا اشْتَرَاهُ عَيْبًا يَجْهَلُهُ خُيِّرَ بَيْنَ رَدِّ الْمَبِيعِ بِنَمَائِهِ الْمُتَّصِلِ وَعَلَيْهِ أُجْرَةُ الرَّدِّ وَيَرْجِعُ بِالثَّمَنِ كَامِلًا وَبَيْنَ إِمْسَاكِهِ وَيَأْخُذُ الْأَرْشَ"]]},{"id":"da46_9","label":"بَابُ الْخِيَارِ · ٩","segs":[["matn","وَيَتَعَيَّنُ الْأَرْشُ مَعَ تَلَفِ الْمَبِيعِ عِنْدَ الْمُشْتَرِي مَا لَمْ يَكُنِ الْبَائِعُ عَلِمَ بِالْعَيْبِ وَكَتَمَهُ تَدْلِيسًا عَلَى الْمُشْتَرِي فَيَحْرُمُ وَيَذْهَبُ عَلَى الْبَائِعِ وَيَرْجِعُ الْمُشْتَرِي بِجَمِيعِ مَا دَفَعَهُ لَهُ."]]},{"id":"da46_10","label":"بَابُ الْخِيَارِ · ١٠","segs":[["matn","وَخِيَارُ الْعَيْبِ عَلَى التَّرَاخِي لَا يَسْقُطُ إِلَّا إِنْ وُجِدَ مِنَ الْمُشْتَرِي مَا يَدُلُّ عَلَى رِضَاهُ كَتَصَرُّفِهِ وَاسْتِعْمَالِهِ لِغَيْرِ تَجْرِبَةٍ وَلَا يَفْتَقِرُ الْفَسْخُ إِلَى حُضُورِ الْبَائِعِ وَلَا لِحُكْمِ الْحَاكِمِ وَالْمَبِيعُ بَعْدَ الْفَسْخِ أَمَانَةٌ بِيَدِ الْمُشْتَرِي."]]},{"id":"da46_11","label":"بَابُ الْخِيَارِ · ١١","segs":[["matn","وَإِنِ اخْتَلَفَا عِنْدَ مَنْ حَدَثَ الْعَيْبُ مَعَ الِاحْتِمَالِ وَلَا بَيِّنَةَ فَقَوْلُ الْمُشْتَرِي بِيَمِينِهِ وَإِنْ لَمْ يَحْتَمِلْ إِلَّا قَوْلَ أَحَدِهِمَا قُبِلَ بِلَا يَمِينٍ السَّادِسُ:"]]},{"id":"da46_12","label":"بَابُ الْخِيَارِ · ١٢","segs":[["matn","خِيَارُ الْخُلْفِ فِي الصِّفَةِ فَإِذَا وَجَدَ الْمُشْتَرِي مَا وُصِفَ لَهُ أَوْ تَقَدَّمَتْ رُؤْيَتُهُ قَبْلَ الْعَقْدِ بِزَمَنٍ يَسِيرٍ مُتَغَيِّرًا فَلَهُ الْفَسْخُ وَيَحْلِفُ إِنِ اخْتَلَفَا."]]},{"id":"da46_13","label":"بَابُ الْخِيَارِ · ١٣","segs":[["matn","السَّابِعُ: خِيَارُ الْخُلْفِ فِي قَدْرِ الثَّمَنِ فَإِذَا اخْتَلَفَا فِي قَدْرِهِ حَلَفَ الْبَائِعُ: مَا بِعْتُهُ بِكَذَا وَإِنَّمَا بِعْتُهُ بِكَذَا ثُمَّ الْمُشْتَرِي: مَا اشْتَرَيْتُهُ بِكَذَا وَإِنَّمَا اشْتَرَيْتُهُ بِكَذَا وَيَتَفَاسَخَانِ."]]},{"id":"da46_14","label":"بَابُ الْخِيَارِ · ١٤","segs":[["matn","فَصْلٌ: وَيَمْلِكُ الْمُشْتَرِي الْمَبِيعَ مُطْلَقًا بِمُجَرَّدِ الْعَقْدِ وَيَصِحُّ تَصَرُّفُهُ فِيهِ قَبْلَ قَبْضِهِ وَإِنْ تَلِفَ فَمِنْ ضَمَانِهِ إِلَّا الْمَبِيعُ بِكَيْلٍ أَوْ وَزْنٍ أَوْ عَدٍّ أَوْ ذَرْعٍ فَمِنْ ضَمَانِ بَائِعِهِ حَتَّى يَقْبِضَهُ مُشْتَرِيهِ وَلَا يَصِحُّ تَصَرُّفُهُ"]]},{"id":"da46_15","label":"بَابُ الْخِيَارِ · ١٥","segs":[["matn","فِيهِ بِبَيْعٍ أَوْ هِبَةٍ أَوْ رَهْنٍ قَبْلَ قَبْضِهِ وَإِنْ تَلِفَ بِآفَةٍ سَمَاوِيَّةٍ قَبْلَ قَبْضِهِ انْفَسَخَ الْعَقْدُ وَبِفِعْلِ بَائِعٍ أَوْ أَجْنَبِيٍّ خُيِّرَ الْمُشْتَرِي بَيْنَ الْفَسْخِ وَيَرْجِعُ بِالثَّمَنِ أَوِ الْإِمْضَاءِ وَيُطَالِبُ مَنْ أَتْلَفَهُ بِبَدَلِهِ وَالثَّمَنُ كَالْمُثْمَنِ فِي جَمِيعِ مَا تَقَدَّمَ."]]},{"id":"da46_16","label":"بَابُ الْخِيَارِ · ١٦","segs":[["matn","فَصْلٌ: وَيَحْصُلُ قَبْضُ الْمَكِيلِ بِالْكَيْلِ وَالْمَوْزُونِ بِالْوَزْنِ وَالْمَعْدُودِ بِالْعَدِّ وَالْمَذْرُوعِ بِالذَّرْعِ بِشَرْطِ حُضُورِ الْمُسْتَحِقِّ أَوْ نَائِبِهِ. وَأُجْرَةُ الْكَيَّالِ وَالْوَزَّانِ وَالْعَدَّادِ وَالذَّرَّاعِ وَالنَّقَّادِ عَلَى الْبَاذِلِ وَأُجْرَةُ النَّقْلِ عَلَى الْقَابِضِ."]]},{"id":"da46_17","label":"بَابُ الْخِيَارِ · ١٧","segs":[["matn","وَلَا يَضْمَنُ نَاقِدٌ حَاذِقٌ أَمِينٌ خَطَأً. وَتُسَنُّ الْإِقَالَةُ لِلنَّادِمِ مِنْ بَائِعٍ وَمُشْتَرٍ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da47","title":"بَابُ الرِّبَا","units":[{"id":"da47_1","label":"بَابُ الرِّبَا · ١","segs":[["matn","يَجْرِي الرِّبَا فِي كُلِّ مَكِيلٍ وَمَوْزُونٍ وَلَوْ لَمْ يُؤْكَلْ."]]},{"id":"da47_2","label":"بَابُ الرِّبَا · ٢","segs":[["matn","فَالْمَكِيلُ: كَسَائِرِ الْحُبُوبِ وَالْأَبَازِيرِ وَالْمَائِعَاتِ لَكِنِ الْمَاءُ لَيْسَ بِرِبَوِيٍّ وَمِنَ الثِّمَارِ: كَالتَّمْرِ وَالزَّبِيبِ وَالْفُسْتُقِ وَالْبُنْدُقِ وَاللَّوْزِ وَالْبُطْمِ وَالزَّعْرُورِ وَالْعُنَّابِ وَالْمِشْمِشِ وَالزَّيْتُونِ وَالْمِلْحِ."]]},{"id":"da47_3","label":"بَابُ الرِّبَا · ٣","segs":[["matn","وَالْمَوْزُونُ: كَالذَّهَبِ وَالْفِضَّةِ وَالنُّحَاسِ وَالرَّصَاصِ وَالْحَدِيدِ وَغَزْلِ الْكَتَّانِ وَالْقُطْنِ وَالْحَرِيرِ وَالشَّعَرِ وَالْقِنَّبِ وَالشَّمْعِ وَالزَّعْفَرَانِ وَالْخُبْزِ وَالْجُبْنِ. وَمَا عَدَا ذَلِكَ فَمَعْدُودٌ لَا يَجْرِي فِيهِ الرِّبَا وَلَوْ مَطْعُومًا كَالْبِطِّيخِ."]]},{"id":"da47_4","label":"بَابُ الرِّبَا · ٤","segs":[["matn","وَالْقِثَّاءِ وَالْخِيَارِ وَالْجَوْزِ وَالْبَيْضِ وَالرُّمَّانِ. وَلَا فِيمَا أَخْرَجَتْهُ الصِّنَاعَةُ عَنِ الْوَزْنِ كَالثِّيَابِ وَالسِّلَاحِ وَالْفُلُوسِ وَالْأَوَانِي غَيْرَ الذَّهَبِ وَالْفِضَّةِ."]]},{"id":"da47_5","label":"بَابُ الرِّبَا · ٥","segs":[["matn","فَصْلٌ: فَإِذَا بِيعَ الْمَكِيلُ بِجِنْسِهِ: كَتَمْرٍ بِتَمْرٍ أَوِ الْمَوْزُونُ بِجِنْسِهِ: كَذَهَبٍ بِذَهَبٍ صَحَّ بِشَرْطَيْنِ: الْمُمَاثَلَةُ فِي الْقَدْرِ وَالْقَبْضُ قَبْلَ التَّفَرُّقِ."]]},{"id":"da47_6","label":"بَابُ الرِّبَا · ٦","segs":[["matn","وَإِذَا بِيعَ بِغَيْرِ جِنْسِهِ كَذَهَبٍ بِفِضَّةٍ وَبُرٍّ بِشَعِيرٍ صَحَّ بِشَرْطِ الْقَبْضِ قَبْلَ التَّفَرُّقِ وَجَازَ التَّفَاضُلُ. وَإِنْ بِيعَ الْمَكِيلُ بِالْمَوْزُونِ كَبُرٍّ بِذَهَبٍ مَثَلًا جَازَ التَّفَاضُلُ وَالتَّفَرُّقُ قَبْلَ الْقَبْضِ."]]},{"id":"da47_7","label":"بَابُ الرِّبَا · ٧","segs":[["matn","وَلَا يَصِحُّ بَيْعُ الْمَكِيلِ بِجِنْسِهِ وَزْنًا وَلَا الْمَوْزُونِ بِجِنْسِهِ كَيْلًا وَيَصِحُّ بَيْعُ اللَّحْمِ بِمِثْلِهِ إِذَا نُزِعَ عَظْمُهُ وَبِحَيَوَانٍ مِنْ غَيْرِ جِنْسِهِ"]]},{"id":"da47_8","label":"بَابُ الرِّبَا · ٨","segs":[["matn","وَيَصِحُّ بَيْعُ دَقِيقِ رِبَوِيٍّ بِدَقِيقِهِ إِذَا اسْتَوَيَا نُعُومَةً أَوْ خُشُونَةً وَرَطْبِهِ بِرَطْبِهِ وَيَابِسِهِ بِيَابِسِهِ وَعَصِيرِهِ بِعَصِيرِهِ وَمَطْبُوخِهِ بِمَطْبُوخِهِ إِذَا اسْتَوَيَا نَشَافًا أَوْ رُطُوبَةً."]]},{"id":"da47_9","label":"بَابُ الرِّبَا · ٩","segs":[["matn","وَلَا يَصِحُّ بَيْعُ فَرْعٍ بِأَصْلِهِ: كَزَيْتٍ بِزَيْتُونٍ وَشَيْرَجٍ بِسِمْسِمٍ وَجُبْنٍ بِلَبَنٍ وَخُبْزٍ بِعَجِينٍ وَزَلَابِيَةٍ بِقَمْحٍ وَلَا بَيْعُ الْحَبِّ الْمُشْتَدِّ فِي سُنْبُلِهِ بِجِنْسِهِ. وَيَصِحُّ بِغَيْرِ جِنْسِهِ."]]},{"id":"da47_10","label":"بَابُ الرِّبَا · ١٠","segs":[["matn","وَلَا يَصِحُّ بَيْعُ رِبَوِيٍّ بِجِنْسِهِ وَمَعَهُمَا أَوْ مَعَ أَحَدِهِمَا مِنْ غَيْرِ جِنْسِهِمَا كَمُدِّ عَجْوَةٍ وَدِرْهَمٍ بِمِثْلِهِمَا أَوْ دِينَارٍ وَدِرْهَمٍ بِدِينَارٍ وَيَصِحُّ: أَعْطِنِي بِنِصْفِ هَذَا الدِّرْهَمِ فِضَّةً وَبِالْآخَرِ فُلُوسًا."]]},{"id":"da47_11","label":"بَابُ الرِّبَا · ١١","segs":[["matn","وَيَصِحُّ صَرْفُ الذَّهَبِ بِالذَّهَبِ وَالْفِضَّةِ بِالْفِضَّةِ مُتَمَاثِلًا وَزْنًا لَا عَدًّا بِشَرْطِ الْقَبْضِ قَبْلَ التَّفَرُّقِ وَأَنْ يُعَوِّضَ أَحَدَ النَّقْدَيْنِ عَنِ الْآخَرِ بِسِعْرِ يَوْمِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da48","title":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ","units":[{"id":"da48_1","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ١","segs":[["matn","مَنْ بَاعَ أَوْ وَهَبَ أَوْ رَهَنَ أَوْ وَقَفَ دَارًا أَوْ أَقَرَّ أَوْ وَصَّى بِهَا تَنَاوَلَ أَرْضَهَا وَبِنَاءَهَا وَفِنَاءَهَا إِنْ كَانَ"]]},{"id":"da48_2","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٢","segs":[["matn","وَمُتَّصِلًا بِهَا لِمَصْلَحَتِهَا كَالسَّلَالِيمِ وَالرُّفُوفِ الْمُسَمَّرَةِ وَالْأَبْوَابِ الْمَنْصُوبَةِ وَالْخَوَابِي الْمَدْفُونَةِ وَمَا فِيهَا مِنْ شَجَرٍ وَعُرُشٍ لَا كَنْزٍ وَحَجَرٍ مَدْفُونَيْنِ وَلَا مُنْفَصِلٍ. كَحَبْلٍ وَدَلْوٍ وَبَكَرَةٍ وَفُرُشٍ وَمِفْتَاحٍ."]]},{"id":"da48_3","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٣","segs":[["matn","وَإِنْ كَانَ الْمُبَاعُ وَنَحْوُهُ أَرْضًا دَخَلَ مَا فِيهَا مِنْ غِرَاسٍ وَبِنَاءٍ لَا مَا فِيهَا مِنْ زَرْعٍ لَا يُحْصَدُ إِلَّا مَرَّةً كَبُرٍّ"]]},{"id":"da48_4","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٤","segs":[["matn","وَشَعِيرٍ وَبَصَلٍ وَنَحْوِهِ وَيُبَقَّى لِلْبَائِعِ إِلَى أَوَّلِ وَقْتِ أَخْذِهِ بِلَا أُجْرَةٍ مَا لَمْ يَشْتَرِطْهُ الْمُشْتَرِي لِنَفْسِهِ وَإِنْ كَانَ يُجَزُّ مَرَّةً بَعْدَ أُخْرَى:"]]},{"id":"da48_5","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٥","segs":[["matn","كَرَطْبَةٍ وَبُقُولٍ أَوْ تَكَرَّرُ ثَمَرَتُهُ: كَقِثَّاءٍ وَبَاذِنْجَانٍ فَالْأُصُولُ لِلْمُشْتَرِي وَالْجَزَّةُ الظَّاهِرَةُ وَاللَّقْطَةُ الْأُولَى لِلْبَائِعِ وَعَلَيْهِ قَطْعُهُمَا فِي الْحَالِ."]]},{"id":"da48_6","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٦","segs":[["matn","فَصْلٌ: وَإِذَا بِيعَ شَجَرُ النَّخْلِ بَعْدَ تَشَقُّقِ طَلْعِهِ فَالثَّمَرُ لِلْبَائِعِ مَتْرُوكًا إِلَى أَوَّلِ وَقْتِ أَخْذِهِ وَكَذَا إِنْ بِيعَ شَجَرُ مَا ظَهَرَ مِنْ عِنَبٍ وَتِينٍ وَتُوتٍ وَرُمَّانٍ وَجَوْزٍ."]]},{"id":"da48_7","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٧","segs":[["matn","أَوْ ظَهَرَ مِنْ نَوْرِهِ كَمِشْمِشٍ وَتُفَّاحٍ وَسَفَرْجَلٍ وَلَوْزٍ أَوْ خَرَجَ مِنْ أَكْمَامِهِ كَوَرْدٍ وَمَا بِيعَ قَبْلَ ذَلِكَ فَلِلْمُشْتَرِي. وَلَا تَدْخُلُ الْأَرْضُ تَبَعًا لِلشَّجَرِ فَإِذَا بَادَ لَمْ يَمْلِكْ غَرْسَ مَكَانِهِ."]]},{"id":"da48_8","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٨","segs":[["matn","فَصْلٌ: وَلَا يَصِحُّ بَيْعُ الثَّمَرَةِ قَبْلَ بُدُوِّ صَلَاحِهَا لِغَيْرِ مَالِكِ الْأَصْلِ وَلَا بَيْعُ الزَّرْعِ قَبْلَ اشْتِدَادِ حَبِّهِ لِغَيْرِ مَالِكِ الْأَرْضِ وَصَلَاحُ بَعْضِ ثَمَرَةِ شَجَرَةٍ صَلَاحٌ لِجَمِيعِ نَوْعِهَا الَّذِي بِالْبُسْتَانِ"]]},{"id":"da48_9","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ٩","segs":[["matn","فَصَلَاحُ الْبَلَحِ أَنْ يَحْمَرَّ أَوْ يَصْفَرَّ وَالْعِنَبِ أَنْ يَتَمَوَّهَ بِالْمَاءِ الْحُلْوِ وَبَقِيَّةِ الْفَوَاكِهِ طِيبُ أَكْلِهَا وَظُهُورُ نُضْجِهَا وَمَا يَظْهَرُ فَمًا بَعْدَ فَمٍ كَالْقِثَّاءِ وَالْخِيَارِ أَنْ يُؤْكَلَ عَادَةً."]]},{"id":"da48_10","label":"بَابُ بَيْعِ الْأُصُولِ وَالثِّمَارِ · ١٠","segs":[["matn","وَمَا تَلِفَ مِنَ الثَّمَرَةِ قَبْلَ أَخْذِهَا فَمِنْ ضَمَانِ الْبَائِعِ مَا لَمْ تُبَعْ مَعَ أَصْلِهَا أَوْ يُؤَخِّرِ الْمُشْتَرِي أَخْذَهَا عَنْ عَادَتِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da49","title":"بَابُ السَّلَمِ","units":[{"id":"da49_1","label":"بَابُ السَّلَمِ · ١","segs":[["matn","يَنْعَقِدُ بِكُلِّ مَا يَدُلُّ عَلَيْهِ وَبِلَفْظِ الْبَيْعِ وَشُرُوطُهُ سَبْعَةٌ."]]},{"id":"da49_2","label":"بَابُ السَّلَمِ · ٢","segs":[["matn","أَحَدُهَا: انْضِبَاطُ صِفَاتِ الْمُسْلَمِ فِيهِ: كَالْمَكِيلِ وَالْمَوْزُونِ وَالْمَذْرُوعِ وَالْمَعْدُودِ مِنَ الْحَيَوَانِ وَلَوْ آدَمِيًّا فَلَا يَصِحُّ فِي الْمَعْدُودِ مِنَ الْفَوَاكِهِ وَلَا فِيمَا لَا يَنْضَبِطُ كَالْبُقُولِ وَالْجُلُودِ وَالرُّؤُوسِ وَالْأَكَارِعِ وَالْبَيْضِ وَالْأَوَانِي الْمُخْتَلِفَةِ رُؤُوسًا وَأَوْسَاطًا كَالْقَمَاقِمِ وَنَحْوِهَا."]]},{"id":"da49_3","label":"بَابُ السَّلَمِ · ٣","segs":[["matn","الثَّانِي: ذِكْرُ جِنْسِهِ وَنَوْعِهِ بِالصِّفَاتِ الَّتِي يَخْتَلِفُ بِهَا الثَّمَنُ وَيَجُوزُ أَنْ يَأْخُذَ دُونَ مَا وُصِفَ لَهُ وَمِنْ غَيْرِ نَوْعِهِ مِنْ جِنْسِهِ."]]},{"id":"da49_4","label":"بَابُ السَّلَمِ · ٤","segs":[["matn","الثَّالِثُ: مَعْرِفَةُ قَدْرِهِ بِمِعْيَارِهِ الشَّرْعِيِّ فَلَا يَصِحُّ فِي مَكِيلٍ وَزْنًا وَلَا فِي مَوْزُونٍ كَيْلًا. الرَّابِعُ: أَنْ يَكُونَ فِي الذِّمَّةِ إِلَى أَجَلٍ مَعْلُومٍ لَهُ وَقْعٌ فِي الْعَادَةِ كَشَهْرٍ وَنَحْوِهِ."]]},{"id":"da49_5","label":"بَابُ السَّلَمِ · ٥","segs":[["matn","الْخَامِسُ: أَنْ يَكُونَ مِمَّا يُوجَدُ غَالِبًا عِنْدَ حُلُولِ الْأَجَلِ. السَّادِسُ: مَعْرِفَةُ قَدْرِ رَأْسِ مَالِ السَّلَمِ وَانْضِبَاطُهُ فَلَا تَكْفِي مُشَاهَدَتُهُ وَلَا يَصِحُّ بِمَا لَا يَنْضَبِطُ."]]},{"id":"da49_6","label":"بَابُ السَّلَمِ · ٦","segs":[["matn","السَّابِعُ: أَنْ يَقْبِضَهُ قَبْلَ التَّفَرُّقِ مِنْ مَجْلِسِ الْعَقْدِ وَلَا يُشْتَرَطُ ذِكْرُ مَكَانِ الْوَفَاءِ لِأَنَّهُ يَجِبُ مَكَانَ الْعَقْدِ مَا لَمْ يُعْقَدْ بِبَرِّيَّةٍ وَنَحْوِهَا فَيُشْتَرَطُ."]]},{"id":"da49_7","label":"بَابُ السَّلَمِ · ٧","segs":[["matn","وَلَا يَصِحُّ أَخْذُ رَهْنٍ أَوْ كَفِيلٍ بِمُسْلَمٍ فِيهِ وَإِنْ تَعَذَّرَ حُصُولُهُ خُيِّرَ رَبُّ السَّلَمِ بَيْنَ صَبْرٍ أَوْ فَسْخٍ وَيَرْجِعُ بِرَأْسِ مَالِهِ أَوْ بَدَلِهِ إِنْ تَعَذَّرَ."]]},{"id":"da49_8","label":"بَابُ السَّلَمِ · ٨","segs":[["matn","وَمَنْ أَرَادَ قَضَاءَ دَيْنٍ عَنْ غَيْرِهِ فَأَبَى رَبُّهُ لَمْ يُلْزَمْ بِقَبُولِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da50","title":"بَابُ الْقَرْضِ","units":[{"id":"da50_1","label":"بَابُ الْقَرْضِ · ١","segs":[["matn","يَصِحُّ بِكُلِّ عَيْنٍ يَصِحُّ بَيْعُهَا إِلَّا بَنِي آدَمَ. وَيُشْتَرَطُ عِلْمُ قَدْرِهِ وَوَصْفِهِ وَكَوْنُ مُقْرِضٍ يَصِحُّ تَبَرُّعُهُ."]]},{"id":"da50_2","label":"بَابُ الْقَرْضِ · ٢","segs":[["matn","وَيَتِمُّ الْعَقْدُ بِالْقَبُولِ وَيُمْلَكُ وَيَلْزَمُ بِالْقَبْضِ فَلَا يَمْلِكُ الْمُقْرِضُ اسْتِرْجَاعَهُ وَيَثْبُتُ لَهُ الْبَدَلُ حَالًّا فَإِنْ كَانَ مُتَقَوَّمًا فَقِيمَتُهُ وَقْتَ الْقَرْضِ وَإِنْ كَانَ مِثْلِيًّا فَمِثْلُهُ مَا لَمْ يَكُنْ مَعِيبًا أَوْ فُلُوسًا وَنَحْوَهَا فَيُحَرِّمُهَا السُّلْطَانُ فَلَهُ الْقِيمَةُ."]]},{"id":"da50_3","label":"بَابُ الْقَرْضِ · ٣","segs":[["matn","وَيَجُوزُ شَرْطُ رَهْنٍ وَضَمِينٍ فِيهِ وَيَجُوزُ قَرْضُ الْمَاءِ كَيْلًا وَالْخُبْزِ وَالْخَمِيرِ عَدَدًا وَرَدُّهُ عَدَدًا بِلَا قَصْدِ زِيَادَةٍ."]]},{"id":"da50_4","label":"بَابُ الْقَرْضِ · ٤","segs":[["matn","وَكُلُّ قَرْضٍ جَرَّ نَفْعًا فَحَرَامٌ كَأَنْ يُسْكِنَهُ دَارَهُ أَوْ يُعِيرَهُ دَابَّتَهُ أَوْ يَقْضِيَهُ خَيْرًا مِنْهُ وَإِنْ فَعَلَ ذَلِكَ بِلَا شَرْطٍ أَوْ قَضَى خَيْرًا مِنْهُ بِلَا مُوَاطَأَةٍ جَازَ."]]},{"id":"da50_5","label":"بَابُ الْقَرْضِ · ٥","segs":[["matn","وَمَتَى بَذَلَ الْمُقْتَرِضُ مَا عَلَيْهِ بِغَيْرِ بَلَدِ الْقَرْضِ وَلَا مَؤْنَةَ لِحَمْلِهِ لَزِمَ رَبَّهُ قَبُولُهُ مَعَ أَمْنِ الْبَلَدِ وَالطَّرِيقِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da51","title":"بَابُ الرَّهْنِ","units":[{"id":"da51_1","label":"بَابُ الرَّهْنِ · ١","segs":[["matn","يَصِحُّ بِشُرُوطٍ خَمْسَةٍ: كَوْنُهُ مُنَجَّزًا وَكَوْنُهُ مَعَ الْحَقِّ أَوْ بَعْدَهُ وَكَوْنُهُ مِمَّنْ يَصِحُّ بَيْعُهُ وَكَوْنُهُ مِلْكَهُ أَوْ مَأْذُونًا لَهُ فِي رَهْنِهِ وَكَوْنُهُ مَعْلُومًا جِنْسُهُ وَقَدْرُهُ وَصِفَتُهُ."]]},{"id":"da51_2","label":"بَابُ الرَّهْنِ · ٢","segs":[["matn","وَكُلُّ مَا صَحَّ بَيْعُهُ صَحَّ رَهْنُهُ إِلَّا الْمُصْحَفَ وَمَا لَا يَصِحُّ بَيْعُهُ لَا يَصِحُّ رَهْنُهُ إِلَّا الثَّمَرَةَ قَبْلَ بُدُوِّ صَلَاحِهَا وَالزَّرْعَ قَبْلَ اشْتِدَادِ حَبِّهِ وَالْقِنَّ دُونَ رَحِمِهِ الْمَحْرَمِ وَلَا يَصِحُّ رَهْنُ مَالِ الْيَتِيمِ لِلْفَاسِقِ."]]},{"id":"da51_3","label":"بَابُ الرَّهْنِ · ٣","segs":[["matn","فَصْلٌ: وَلِلرَّاهِنِ الرُّجُوعُ فِي الرَّهْنِ مَا لَمْ يَقْبِضْهُ الْمُرْتَهِنُ فَإِنْ قَبَضَهُ لَزِمَ وَلَمْ يَصِحَّ تَصَرُّفُهُ فِيهِ بِلَا إِذْنِ الْمُرْتَهِنِ إِلَّا بِالْعِتْقِ وَعَلَيْهِ قِيمَتُهُ تَكُونُ رَهْنًا مَكَانَهُ."]]},{"id":"da51_4","label":"بَابُ الرَّهْنِ · ٤","segs":[["matn","وَكَسْبُ الرَّهْنِ وَنَمَاؤُهُ رَهْنٌ وَهُوَ أَمَانَةٌ بِيَدِ الْمُرْتَهِنِ لَا يَضْمَنُهُ إِلَّا بِالتَّفْرِيطِ وَيُقْبَلُ قَوْلُهُ بِيَمِينِهِ فِي تَلَفِهِ وَأَنَّهُ لَمْ يُفَرِّطْ وَإِنْ تَلِفَ بَعْضُ الرَّهْنِ فَبَاقِيهِ رَهْنٌ بِجَمِيعِ الْحَقِّ وَلَا يَنْفَكُّ مِنْهُ شَيْءٌ حَتَّى يَقْضِيَ الدَّيْنَ كُلَّهُ."]]},{"id":"da51_5","label":"بَابُ الرَّهْنِ · ٥","segs":[["matn","وَإِذَا حَلَّ أَجَلُ الدَّيْنِ وَكَانَ الرَّاهِنُ قَدْ شَرَطَ لِلْمُرْتَهِنِ أَنَّهُ إِنْ لَمْ يَأْتِهِ بِحَقِّهِ عِنْدَ حُلُولِ الْأَجَلِ وَإِلَّا"]]},{"id":"da51_6","label":"بَابُ الرَّهْنِ · ٦","segs":[["matn","فَالرَّهْنُ لَهُ لَمْ يَصِحَّ الشَّرْطُ بَلْ يَلْزَمُهُ الْوَفَاءُ أَوْ يَأْذَنَ لِلْمُرْتَهِنِ فِي بَيْعِ الرَّهْنِ أَوْ يَبِيعَهُ هُوَ بِنَفْسِهِ لِيُوَفِّيَهُ حَقَّهُ فَإِنْ أَبَى حُبِسَ أَوْ عُزِّرَ فَإِنْ أَصَرَّ بَاعَهُ الْحَاكِمُ."]]},{"id":"da51_7","label":"بَابُ الرَّهْنِ · ٧","segs":[["matn","فَصْلٌ: وَلِلْمُرْتَهِنِ رُكُوبُ الرَّهْنِ وَحَلْبُهُ بِقَدْرِ نَفَقَتِهِ بِلَا إِذْنِ الرَّاهِنِ وَلَوْ حَاضِرًا وَلَهُ الِانْتِفَاعُ بِهِ مَجَّانًا بِإِذْنِ الرَّاهِنِ لَكِنْ يَصِيرُ مَضْمُونًا عَلَيْهِ بِالِانْتِفَاعِ."]]},{"id":"da51_8","label":"بَابُ الرَّهْنِ · ٨","segs":[["matn","وَمُؤْنَةُ الرَّهْنِ وَأُجْرَةُ مَخْزَنِهِ وَأُجْرَةُ رَدِّهِ مِنْ إِبَاقِهِ عَلَى مَالِكِهِ. وَإِنْ أَنْفَقَ الْمُرْتَهِنُ عَلَى الرَّهْنِ بِلَا إِذْنِ الرَّاهِنِ مَعَ قُدْرَتِهِ عَلَى اسْتِئْذَانِهِ فَمُتَبَرِّعٌ."]]},{"id":"da51_9","label":"بَابُ الرَّهْنِ · ٩","segs":[["matn","فَصْلٌ: مَنْ قَبَضَ الْعَيْنَ لِحَظِّ نَفْسِهِ كَمُرْتَهِنٍ وَأَجِيرٍ وَمُسْتَأْجِرٍ وَمُشْتَرٍ وَبَائِعٍ وَغَاصِبٍ وَمُلْتَقِطٍ وَمُقْتَرِضٍ وَمُضَارِبٍ وَادَّعَى الرَّدَّ لِلْمَالِكِ."]]},{"id":"da51_10","label":"بَابُ الرَّهْنِ · ١٠","segs":[["matn","فَأَنْكَرَهُ لَمْ يُقْبَلْ قَوْلُهُ إِلَّا بِبَيِّنَةٍ وَكَذَا مُودَعٌ وَوَكِيلٌ وَوَصِيٌّ وَدَلَّالٌ بِجُعْلٍ إِذَا ادَّعَى الرَّدَّ وَبِلَا جُعْلٍ فَيُقْبَلُ قَوْلُهُ بِيَمِينِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da52","title":"بَابُ الضَّمَانِ وَالْكَفَالَةِ","units":[{"id":"da52_1","label":"بَابُ الضَّمَانِ وَالْكَفَالَةِ · ١","segs":[["matn","يَصِحَّانِ تَنْجِيزًا وَتَعْلِيقًا وَتَوْقِيتًا مِمَّنْ يَصِحُّ تَبَرُّعُهُ وَلِرَبِّ الْحَقِّ مُطَالَبَةُ الضَّامِنِ وَالْمَضْمُونِ مَعًا أَوْ أَيَّهُمَا شَاءَ لَكِنْ لَوْ ضَمِنَ دَيْنًا حَالًّا إِلَى أَجَلٍ مَعْلُومٍ صَحَّ وَلَمْ يُطَالِبِ الضَّامِنَ قَبْلَ مُضِيِّهِ."]]},{"id":"da52_2","label":"بَابُ الضَّمَانِ وَالْكَفَالَةِ · ٢","segs":[["matn","وَيَصِحُّ ضَمَانُ عُهْدَةِ الثَّمَنِ وَالْمُثْمَنِ وَالْمَقْبُوضِ عَلَى وَجْهِ السَّوْمِ وَالْعَيْنِ الْمَضْمُونَةِ كَالْغَصْبِ وَالْعَارِيَّةِ. وَلَا يَصِحُّ ضَمَانُ غَيْرِ الْمَضْمُونَةِ كَالْوَدِيعَةِ وَنَحْوِهَا وَلَا دَيْنِ الْكِتَابَةِ وَلَا بَعْضِ دَيْنٍ لَمْ يُقَدَّرْ."]]},{"id":"da52_3","label":"بَابُ الضَّمَانِ وَالْكَفَالَةِ · ٣","segs":[["matn","وَإِنْ قَضَى الضَّامِنُ مَا عَلَى الْمَدِينِ وَنَوَى الرُّجُوعَ عَلَيْهِ رَجَعَ وَلَوْ لَمْ يَأْذَنْ لَهُ الْمَدِينُ فِي الضَّمَانِ وَالْقَضَاءِ وَكَذَا كُلُّ مَنْ أَدَّى عَنْ غَيْرِهِ دَيْنًا وَاجِبًا."]]},{"id":"da52_4","label":"بَابُ الضَّمَانِ وَالْكَفَالَةِ · ٤","segs":[["matn","وَإِنْ بَرِئَ الْمَدْيُونُ بَرِئَ ضَامِنُهُ وَلَا عَكْسَ وَلَوْ ضَمِنَ اثْنَانِ وَاحِدًا وَقَالَ كُلٌّ: ضَمِنْتُ لَكَ الدَّيْنَ كَانَ لِرَبِّهِ طَلَبُ كُلِّ وَاحِدٍ بِالدَّيْنِ كُلِّهِ وَإِنْ قَالَا: ضَمِنَّا لَكَ الدَّيْنَ فَبَيْنَهُمَا بِالْحِصَصِ."]]},{"id":"da52_5","label":"بَابُ الضَّمَانِ وَالْكَفَالَةِ · ٥","segs":[["matn","فَصْلٌ: وَالْكَفَالَةُ: هِيَ أَنْ يَلْتَزِمَ بِإِحْضَارِ بَدَنِ مَنْ عَلَيْهِ حَقٌّ مَالِيٌّ إِلَى رَبِّهِ وَيُعْتَبَرُ رِضَى الْكَفِيلِ لَا الْمَكْفُولِ وَلَا الْمَكْفُولِ لَهُ وَمَتَى سَلَّمَ الْكَفِيلُ الْمَكْفُولَ لِرَبِّ الْحَقِّ بِمَحَلِّ الْعَقْدِ أَوْ سَلَّمَ الْمَكْفُولُ نَفْسَهُ أَوْ مَاتَ بَرِئَ الْكَفِيلُ."]]},{"id":"da52_6","label":"بَابُ الضَّمَانِ وَالْكَفَالَةِ · ٦","segs":[["matn","وَإِنْ تَعَذَّرَ عَلَى الْكَفِيلِ إِحْضَارُ الْمَكْفُولِ ضَمِنَ جَمِيعَ مَا عَلَيْهِ وَمَنْ كَفَلَهُ اثْنَانِ فَسَلَّمَهُ أَحَدُهُمَا لَمْ يَبْرَأِ الْآخَرُ وَإِنْ سَلَّمَ نَفْسَهُ بَرِئَا."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da53","title":"بَابُ الْحَوَالَةِ","units":[{"id":"da53_1","label":"بَابُ الْحَوَالَةِ · ١","segs":[["matn","وَشُرُوطُهَا خَمْسَةٌ:. أَحَدُهَا: اتِّفَاقُ الدَّيْنَيْنِ فِي الْجِنْسِ وَالصِّفَةِ وَالْحُلُولِ وَالْأَجَلِ. الثَّانِي: عِلْمُ قَدْرِ كُلٍّ مِنَ الدَّيْنَيْنِ. الثَّالِثُ: اسْتِقْرَارُ الْمَالِ الْمُحَالِ عَلَيْهِ لَا الْمُحَالِ بِهِ. الرَّابِعُ: كَوْنُهُ يَصِحُّ السَّلَمُ فِيهِ."]]},{"id":"da53_2","label":"بَابُ الْحَوَالَةِ · ٢","segs":[["matn","الْخَامِسُ: رِضَى الْمُحِيلِ لَا الْمُحْتَالِ إِنْ كَانَ الْمُحَالُ عَلَيْهِ مَلِيئًا وَهُوَ مَنْ لَهُ الْقُدْرَةُ عَلَى الْوَفَاءِ وَلَيْسَ مُمَاطِلًا وَيُمْكِنُ حُضُورُهُ لِمَجْلِسِ الْحُكْمِ فَمَتَى تَوَفَّرَتِ الشُّرُوطُ بَرِئَ الْمُحِيلُ مِنَ الدَّيْنِ بِمُجَرَّدِ الْحَوَالَةِ أَفْلَسَ الْمُحَالُ عَلَيْهِ بَعْدَ ذَلِكَ أَوْ مَاتَ."]]},{"id":"da53_3","label":"بَابُ الْحَوَالَةِ · ٣","segs":[["matn","وَمَتَى لَمْ تَتَوَفَّرِ الشُّرُوطُ لَمْ تَصِحَّ الْحَوَالَةُ وَإِنَّمَا تَكُونُ وَكَالَةً."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da54","title":"بَابُ الصُّلْحِ","units":[{"id":"da54_1","label":"بَابُ الصُّلْحِ · ١","segs":[["matn","يَصِحُّ مِمَّنْ يَصِحُّ تَبَرُّعُهُ مَعَ الْإِقْرَارِ وَالْإِنْكَارِ فَإِذَا أَقَرَّ لِلْمُدَّعِي بِدَيْنٍ أَوْ عَيْنٍ ثُمَّ صَالَحَهُ عَلَى بَعْضِ الدَّيْنِ أَوْ بَعْضِ الْعَيْنِ الْمُدَّعَاةِ فَهُوَ هِبَةٌ يَصِحُّ بِلَفْظِهَا لَا بِلَفْظِ الصُّلْحِ وَإِنْ صَالَحَهُ عَلَى عَيْنٍ غَيْرِ الْمُدَّعَاةِ"]]},{"id":"da54_2","label":"بَابُ الصُّلْحِ · ٢","segs":[["matn","فَهُوَ بَيْعٌ يَصِحُّ بِلَفْظِ الصُّلْحِ وَتَثْبُتُ فِيهِ أَحْكَامُ الْبَيْعِ فَلَوْ صَالَحَهُ عَنِ الدَّيْنِ بِعَيْنٍ وَاتَّفَقَا فِي عِلَّةٍ عَلَى الرِّبَا اشْتُرِطَ قَبْضُ الْعِوَضِ فِي الْمَجْلِسِ وَبِشَيْءٍ فِي الذِّمَّةِ يَبْطُلُ بِالتَّفَرُّقِ قَبْلَ الْقَبْضِ."]]},{"id":"da54_3","label":"بَابُ الصُّلْحِ · ٣","segs":[["matn","وَإِنْ صَالَحَ عَنْ عَيْبٍ فِي الْمَبِيعِ صَحَّ فَلَوْ زَالَ الْعَيْبُ سَرِيعًا أَوْ لَمْ يَكُنْ رَجَعَ بِمَا دَفَعَهُ وَيَصِحُّ الصُّلْحُ عَمَّا تَعَذَّرَ عِلْمُهُ مِنْ دَيْنٍ أَوْ عَيْنٍ وَأَقِرَّ لِي بِدَيْنِي وَأُعْطِيكَ مِنْهُ كَذَا فَأَقَرَّ لَزِمَهُ الدَّيْنُ وَلَمْ يَلْزَمْهُ أَنْ يُعْطِيَهُ."]]},{"id":"da54_4","label":"بَابُ الصُّلْحِ · ٤","segs":[["matn","فَصْلٌ: وَإِذَا أَنْكَرَ دَعْوَى الْمُدَّعِي أَوْ سَكَتَ وَهُوَ يَجْهَلُهُ ثُمَّ صَالَحَهُ صَحَّ الصُّلْحُ وَكَانَ إِبْرَاءً فِي حَقِّهِ وَبَيْعًا فِي حَقِّ الْمُدَّعِي."]]},{"id":"da54_5","label":"بَابُ الصُّلْحِ · ٥","segs":[["matn","وَمَنْ عَلِمَ بِكَذِبِ نَفْسِهِ فَالصُّلْحُ بَاطِلٌ فِي حَقِّهِ وَمَا أَخَذَ فَحَرَامٌ وَمَنْ قَالَ: صَالِحْنِي عَنِ الْمِلْكِ الَّذِي تَدَّعِيهِ لَمْ يَكُنْ مُقِرًّا وَإِنْ صَالَحَ أَجْنَبِيٌّ عَنْ مُنْكِرٍ لِلدَّعْوَى صَحَّ الصُّلْحُ أَذِنَ لَهُ أَوْ لَا لَكِنْ لَا يَرْجِعُ عَلَيْهِ بِدُونِ إِذْنِهِ."]]},{"id":"da54_6","label":"بَابُ الصُّلْحِ · ٦","segs":[["matn","وَمَنْ صَالَحَ عَنْ دَارٍ أَوْ نَحْوِهَا فَبَانَ الْعِوَضُ مُسْتَحَقًّا رَجَعَ بِالدَّارِ مَعَ الْإِقْرَارِ وَبِالدَّعْوَى مَعَ الْإِنْكَارِ وَلَا يَصِحُّ الصُّلْحُ عَنْ خِيَارٍ أَوْ شُفْعَةٍ أَوْ حَدِّ قَذْفٍ وَتَسْقُطُ جَمِيعُهَا وَلَا شَارِبًا أَوْ سَارِقًا لِيُطْلِقَهُ أَوْ شَاهِدًا لِيَكْتُمَ شَهَادَتَهُ."]]},{"id":"da54_7","label":"بَابُ الصُّلْحِ · ٧","segs":[["matn","فَصْلٌ: وَيَحْرُمُ عَلَى الشَّخْصِ أَنْ يُجْرِيَ مَاءً فِي أَرْضِ غَيْرِهِ أَوْ سَطْحِهِ بِلَا إِذْنِهِ وَيَصِحُّ الصُّلْحُ عَلَى ذَلِكَ بِعِوَضٍ وَمَنْ لَهُ حَقُّ مَاءٍ يَجْرِي عَلَى سَطْحِ جَارِهِ لَمْ يَجُزْ لِجَارِهِ تَعْلِيَةُ سَطْحِهِ لِيَمْنَعَ جَرْيَ الْمَاءِ."]]},{"id":"da54_8","label":"بَابُ الصُّلْحِ · ٨","segs":[["matn","وَحَرُمَ عَلَى الْجَارِ أَنْ يُحْدِثَ بِمِلْكِهِ مَا يَضُرُّ بِجَارِهِ: كَحَمَّامٍ. وَكَنِيفٍ وَرَحًى وَتَنُّورٍ وَلَهُ مَنْعُهُ مِنْ ذَلِكَ."]]},{"id":"da54_9","label":"بَابُ الصُّلْحِ · ٩","segs":[["matn","وَيَحْرُمُ التَّصَرُّفُ فِي جِدَارِ جَارٍ مُشْتَرَكٍ بِفَتْحِ رَوْزَنَةٍ أَوْ طَاقٍ أَوْ ضَرْبِ وَتِدٍ وَنَحْوِهِ إِلَّا بِإِذْنِهِ وَكَذَا وَضْعُ الْخَشَبِ إِلَّا أَنْ لَا يُمْكِنَ تَسْقِيفٌ إِلَّا بِهِ"]]},{"id":"da54_10","label":"بَابُ الصُّلْحِ · ١٠","segs":[["matn","وَيُجْبَرُ الْجَارُ إِنْ أَبَى وَلَهُ أَنْ يُسْنِدَ قُمَاشَهُ وَيَجْلِسَ فِي ظِلِّ حَائِطِ غَيْرِهِ وَيَنْظُرَ فِي ضَوْءِ سِرَاجِهِ مِنْ غَيْرِ إِذْنِهِ."]]},{"id":"da54_11","label":"بَابُ الصُّلْحِ · ١١","segs":[["matn","وَحَرُمَ أَنْ يَتَصَرَّفَ فِي طَرِيقٍ نَافِذٍ بِمَا يَضُرُّ الْمَارَّ كَإِخْرَاجِ دُكَّانٍ وَدَكَّةٍ وَجَنَاحٍ وَسَابَاطٍ وَمِيزَابٍ وَيَضْمَنُ مَا تَلِفَ بِهِ."]]},{"id":"da54_12","label":"بَابُ الصُّلْحِ · ١٢","segs":[["matn","وَيَحْرُمُ التَّصَرُّفُ بِذَلِكَ فِي مِلْكِ غَيْرِهِ أَوْ هَوَائِهِ أَوْ دَرْبٍ غَيْرِ نَافِذٍ إِلَّا بِإِذْنِ أَهْلِهِ وَيُجْبَرُ الشَّرِيكُ عَلَى الْعِمَارَةِ مَعَ شَرِيكِهِ فِي الْمِلْكِ وَالْوَقْفِ."]]},{"id":"da54_13","label":"بَابُ الصُّلْحِ · ١٣","segs":[["matn","وَإِنْ هَدَمَ الشَّرِيكُ الْبِنَاءَ وَكَانَ لِخَوْفِ سُقُوطِهِ فَلَا شَيْءَ عَلَيْهِ وَإِلَّا لَزِمَهُ إِعَادَتُهُ وَإِنْ أَهْمَلَ شَرِيكٌ بِنَاءَ حَائِطِ بُسْتَانٍ اتَّفَقَا عَلَيْهِ فَمَا تَلِفَ مِنْ ثَمَرَتِهِ بِسَبَبِ إِهْمَالِهِ ضَمِنَ حِصَّةَ شَرِيكِهِ."]]}],"group":"كِتَابُ الْبَيْعِ"},{"id":"da55","title":"كِتَابُ الْحَجْرِ","units":[{"id":"da55_1","label":"كِتَابُ الْحَجْرِ · ١","segs":[["matn","وَهُوَ: مَنْعُ الْمَالِكِ مِنَ التَّصَرُّفِ فِي مَالِهِ وَهُوَ نَوْعَانِ: الْأَوَّلُ: لِحَقِّ الْغَيْرِ كَالْحَجْرِ عَلَى مُفْلِسٍ وَرَاهِنٍ وَمَرِيضٍ وَقِنٍّ وَمُكَاتَبٍ وَمُرْتَدٍّ وَمُشْتَرٍ بَعْدَ طَلَبِ الشَّفِيعِ."]]},{"id":"da55_2","label":"كِتَابُ الْحَجْرِ · ٢","segs":[["matn","الثَّانِي: لِحَظِّ نَفْسِهِ كَعَلَى صَغِيرٍ وَمَجْنُونٍ وَسَفِيهٍ."]]},{"id":"da55_3","label":"كِتَابُ الْحَجْرِ · ٣","segs":[["matn","وَلَا يُطَالَبُ الْمَدِينُ وَلَا يُحْجَرُ عَلَيْهِ بِدَيْنٍ لَمْ يَحِلَّ لَكِنْ لَوْ أَرَادَ سَفَرًا طَوِيلًا فَلِغَرِيمِهِ مَنْعُهُ حَتَّى يُوَثِّقَهُ بِرَهْنٍ يُحْرِزُ أَوْ كَفِيلٍ مَلِيءٍ وَلَا يَحِلُّ دَيْنٌ مُؤَجَّلٌ بِجُنُونٍ وَلَا بِمَوْتٍ إِنْ وَثَّقَ وَرَثَتُهُ بِمَا تَقَدَّمَ."]]},{"id":"da55_4","label":"كِتَابُ الْحَجْرِ · ٤","segs":[["matn","وَيَجِبُ عَلَى مَدِينٍ قَادِرٍ وَفَاءُ دَيْنٍ حَالٍّ فَوْرًا بِطَلَبِ رَبِّهِ وَإِنْ مَطَلَهُ حَتَّى شَكَاهُ وَجَبَ عَلَى الْحَاكِمِ أَمْرُهُ بِوَفَائِهِ فَإِنْ أَبَى حَبَسَهُ وَلَا يُخْرِجُهُ حَتَّى يَتَبَيَّنَ أَمْرُهُ فَإِنْ كَانَ ذُو عُسْرَةٍ وَجَبَ تَخْلِيَتُهُ وَحَرُمَتْ مُطَالَبَتُهُ وَالْحَجْرُ عَلَيْهِ مَا دَامَ مُعْسِرًا."]]},{"id":"da55_5","label":"كِتَابُ الْحَجْرِ · ٥","segs":[["matn","وَإِنْ سَأَلَ غُرَمَاءُ مَنْ لَهُ مَالٌ لَا يَفِي بِدَيْنِهِ الْحَاكِمَ الْحَجْرَ عَلَيْهِ لَزِمَهُ إِجَابَتُهُمْ وَسُنَّ إِظْهَارُ حَجْرٍ لِفَلَسٍ."]]},{"id":"da55_6","label":"كِتَابُ الْحَجْرِ · ٦","segs":[["matn","فَصْلٌ: وَفَائِدَةُ الْحَجْرِ أَحْكَامٌ أَرْبَعَةٌ: أَحَدُهَا تَعَلُّقُ حَقِّ الْغُرَمَاءِ بِالْمَالِ فَلَا يَصِحُّ تَصَرُّفُهُ فِيهِ بِشَيْءٍ وَلَوْ بِالْعِتْقِ وَإِنْ تَصَرَّفَ فِي ذِمَّتِهِ بِشِرَاءٍ أَوْ إِقْرَارٍ صَحَّ وَطُولِبَ بِهِ بَعْدَ فَكِّ الْحَجْرِ عَنْهُ."]]},{"id":"da55_7","label":"كِتَابُ الْحَجْرِ · ٧","segs":[["matn","الثَّانِي: إِنَّ مَنْ وَجَدَ عَيْنَ مَا بَاعَهُ أَوْ أَقْرَضَهُ فَهُوَ أَحَقُّ بِهَا بِشَرْطِ كَوْنِهِ لَا يَعْلَمُ بِالْحَجْرِ وَأَنْ يَكُونَ الْمُفْلِسُ حَيًّا وَأَنْ يَكُونَ عِوَضُ الْعَيْنِ كُلُّهُ بَاقِيًا فِي ذِمَّتِهِ وَأَنْ تَكُونَ كُلُّهَا"]]},{"id":"da55_8","label":"كِتَابُ الْحَجْرِ · ٨","segs":[["matn","فِي مِلْكِهِ وَأَنْ تَكُونَ بِحَالِهَا وَلَمْ تَتَغَيَّرْ صِفَتُهَا بِمَا يُزِيلُ اسْمَهَا وَلَمْ تَزِدْ زِيَادَةً مُتَّصِلَةً وَلَمْ تَخْتَلِطْ بِغَيْرِ مُتَمَيِّزٍ وَلَمْ يَتَعَلَّقْ بِهَا حَقٌّ لِلْغَيْرِ فَمَتَى وُجِدَ شَيْءٌ مِنْ ذَلِكَ امْتَنَعَ الرُّجُوعُ."]]},{"id":"da55_9","label":"كِتَابُ الْحَجْرِ · ٩","segs":[["matn","الثَّالِثُ: يَلْزَمُ الْحَاكِمَ قَسْمُ مَالِهِ الَّذِي مِنْ جِنْسِ الدَّيْنِ وَبَيْعُ مَا لَيْسَ مِنْ جِنْسِهِ وَيَقْسِمُهُ عَلَى الْغُرَمَاءِ بِقَدْرِ دُيُونِهِمْ وَلَا يَلْزَمُهُمْ بَيَانُ أَنْ لَا غَرِيمَ سِوَاهُمْ"]]},{"id":"da55_10","label":"كِتَابُ الْحَجْرِ · ١٠","segs":[["matn","ثُمَّ إِنْ ظَهَرَ رَبُّ دَيْنٍ حَالٍّ رَجَعَ عَلَى كُلِّ غَرِيمٍ بِقِسْطِهِ وَيَجِبُ أَنْ يُتْرَكَ لَهُ مَا يَحْتَاجُهُ مِنْ مَسْكَنٍ وَخَادِمٍ وَمَا يَتَّجِرُ بِهِ وَآلَةِ حِرْفَةٍ وَيَجِبُ لَهُ وَلِعِيَالِهِ أَدْنَى نَفَقَةِ مِثْلِهِمْ مِنْ مَأْكَلٍ وَمَشْرَبٍ وَكِسْوَةٍ."]]},{"id":"da55_11","label":"كِتَابُ الْحَجْرِ · ١١","segs":[["matn","الرَّابِعُ: انْقِطَاعُ الطَّلَبِ عَنْهُ فَمَنْ أَقْرَضَهُ أَوْ بَاعَهُ شَيْئًا عَالِمًا بِحَجْرِهِ لَمْ يَمْلِكْ طَلَبَهُ حَتَّى يَنْفَكَّ حَجْرُهُ."]]},{"id":"da55_12","label":"كِتَابُ الْحَجْرِ · ١٢","segs":[["matn","فَصْلٌ: وَمَنْ دَفَعَ مَالَهُ إِلَى صَغِيرٍ أَوْ مَجْنُونٍ أَوْ سَفِيهٍ فَأَتْلَفَهُ لَمْ يَضْمَنْهُ وَمَنْ أَخَذَ مِنْ أَحَدِهِمْ مَالًا ضَمِنَهُ حَتَّى يَأْخُذَهُ وَلِيُّهُ لَا إِنْ أَخَذَهُ لِيَحْفَظَهُ وَتَلِفَ وَلَمْ يُفَرِّطْ كَمَنْ أَخَذَ مَغْصُوبًا لِيَحْفَظَهُ لِرَبِّهِ."]]},{"id":"da55_13","label":"كِتَابُ الْحَجْرِ · ١٣","segs":[["matn","وَمَنْ بَلَغَ رَشِيدًا أَوْ بَلَغَ مَجْنُونًا ثُمَّ عَقَلَ وَرَشَدَ انْفَكَّ الْحَجْرُ عَنْهُ وَدُفِعَ إِلَيْهِ مَالُهُ لَا قَبْلَ ذَلِكَ بِحَالٍ."]]},{"id":"da55_14","label":"كِتَابُ الْحَجْرِ · ١٤","segs":[["matn","وَبُلُوغُ الذَّكَرِ بِثَلَاثَةِ أَشْيَاءَ: بِالْإِمْنَاءِ وَبِتَمَامِ خَمْسَ عَشْرَةَ سَنَةً أَوْ بِنَبَاتِ شَعَرٍ خَشِنٍ حَوْلَ قُبُلِهِ. وَبُلُوغُ الْأُنْثَى بِذَلِكَ وَبِالْحَيْضِ. وَالرُّشْدُ: إِصْلَاحُ الْمَالِ وَصَوْنُهُ عَمَّا لَا فَائِدَةَ فِيهِ."]]},{"id":"da55_15","label":"كِتَابُ الْحَجْرِ · ١٥","segs":[["matn","فَصْلٌ: وَوِلَايَةُ الْمَمْلُوكِ لِمَالِكِهِ وَلَوْ فَاسِقًا. وَوِلَايَةُ الصَّغِيرِ وَالْبَالِغِ بِسَفَهٍ أَوْ جُنُونٍ لِأَبِيهِ فَإِنْ لَمْ يَكُنْ فَوَصِيُّهُ ثُمَّ الْحَاكِمُ فَإِنْ عُدِمَ الْحَاكِمُ فَأَمِينٌ يَقُومُ مَقَامَهُ."]]},{"id":"da55_16","label":"كِتَابُ الْحَجْرِ · ١٦","segs":[["matn","وَشُرِطَ فِي الْوَلِيِّ الرُّشْدُ وَالْعَدَالَةُ وَلَوْ ظَاهِرًا. وَالْجَدُّ وَالْأُمُّ وَسَائِرُ الْعَصَبَاتِ لَا وِلَايَةَ لَهُمْ إِلَّا بِالْوَصِيَّةِ."]]},{"id":"da55_17","label":"كِتَابُ الْحَجْرِ · ١٧","segs":[["matn","وَيَحْرُمُ عَلَى وَلِيِّ الصَّغِيرِ وَالْمَجْنُونِ وَالسَّفِيهِ أَنْ يَتَصَرَّفَ فِي مَالِهِمْ إِلَّا بِمَا فِيهِ حَظٌّ وَمَصْلَحَةٌ."]]},{"id":"da55_18","label":"كِتَابُ الْحَجْرِ · ١٨","segs":[["matn","وَتَصَرُّفُ الثَّلَاثَةِ بِبَيْعٍ أَوْ شِرَاءٍ أَوْ عِتْقٍ أَوْ وَقْفٍ أَوْ إِقْرَارٍ غَيْرُ صَحِيحٍ لَكِنِ السَّفِيهُ إِنْ أَقَرَّ بِحَدٍّ أَوْ نَسَبٍ أَوْ طَلَاقٍ أَوْ قِصَاصٍ صَحَّ وَأُخِذَ بِهِ فِي الْحَالِ. وَإِنْ أَقَرَّ بِمَالٍ أُخِذَ بِهِ بَعْدَ فَكِّ الْحَجْرِ."]]},{"id":"da55_19","label":"كِتَابُ الْحَجْرِ · ١٩","segs":[["matn","فَصْلٌ: وَلِلْوَلِيِّ مَعَ الْحَاجَةِ أَنْ يَأْكُلَ مِنْ مَالِ مَوْلِيِّهِ الْأَقَلَّ مِنْ أُجْرَةِ مِثْلِهِ أَوْ كِفَايَتِهِ وَمَعَ عَدَمِ الْحَاجَةِ يَأْكُلُ مَا فَرَضَهُ لَهُ الْحَاكِمُ وَلِلزَّوْجَةِ."]]},{"id":"da55_20","label":"كِتَابُ الْحَجْرِ · ٢٠","segs":[["matn","وَلِكُلِّ مُتَصَرِّفٍ فِي بَيْتٍ أَنْ يَتَصَدَّقَ مِنْهُ بِلَا إِذْنِ صَاحِبِهِ بِمَا لَا يَضُرُّ كَرَغِيفٍ وَنَحْوِهِ إِلَّا أَنْ يَمْنَعَهُ أَوْ يَكُونَ بَخِيلًا فَيَحْرُمُ."]]}],"group":"كِتَابُ الْحَجْرِ"},{"id":"da56","title":"بَابُ الْوَكَالَةِ","units":[{"id":"da56_1","label":"بَابُ الْوَكَالَةِ · ١","segs":[["matn","وَهِيَ اسْتِنَابَةُ جَائِزِ التَّصَرُّفِ مِثْلَهُ فِيمَا تَدْخُلُهُ النِّيَابَةُ كَعَقْدٍ وَفَسْخٍ وَطَلَاقٍ وَرَجْعَةٍ وَكِتَابَةٍ وَتَدْبِيرٍ وَصُلْحٍ وَتَفْرِقَةِ صَدَقَةٍ وَنَذْرٍ وَكَفَّارَةٍ وَفِعْلِ حَجٍّ وَعُمْرَةٍ."]]},{"id":"da56_2","label":"بَابُ الْوَكَالَةِ · ٢","segs":[["matn","لَا فِيمَا لَا تَدْخُلُهُ النِّيَابَةُ كَصَلَاةٍ وَصَوْمٍ وَحَلِفٍ وَطَهَارَةٍ مِنْ حَدَثٍ."]]},{"id":"da56_3","label":"بَابُ الْوَكَالَةِ · ٣","segs":[["matn","وَتَصِحُّ الْوَكَالَةُ مُنَجَّزَةً وَمُعَلَّقَةً وَمُؤَقَّتَةً وَتَنْعَقِدُ بِكُلِّ مَا دَلَّ عَلَيْهَا مِنْ قَوْلٍ وَفِعْلٍ وَشُرِطَ تَعْيِينُ الْوَكِيلِ لَا عِلْمُهُ بِهَا وَتَصِحُّ فِي بَيْعِ مَالِهِ كُلِّهِ أَوْ مَا شَاءَ مِنْهُ"]]},{"id":"da56_4","label":"بَابُ الْوَكَالَةِ · ٤","segs":[["matn","وَبِالْمُطَالَبَةِ بِحُقُوقِهِ كُلِّهَا وَبِالْإِبْرَاءِ مِنْهَا كُلِّهَا أَوْ مَا شَاءَ مِنْهَا وَلَا تَصِحُّ إِنْ قَالَ: وَكَّلْتُكَ فِي كُلِّ قَلِيلٍ وَكَثِيرٍ وَتُسَمَّى: الْمُفَوَّضَةَ."]]},{"id":"da56_5","label":"بَابُ الْوَكَالَةِ · ٥","segs":[["matn","وَلِلْوَكِيلِ أَنْ يُوَكِّلَ فِيمَا يَعْجِزُ عَنْهُ لَا أَنْ يَعْقِدَ مَعَ فَقِيرٍ أَوْ قَاطِعِ طَرِيقٍ أَوْ يَبِيعَ مُؤَجَّلًا أَوْ بِمَنْفَعَةٍ أَوْ عَرْضٍ أَوْ بِغَيْرِ نَقْدِ الْبَلَدِ إِلَّا بِإِذْنِ مُوَكِّلِهِ."]]},{"id":"da56_6","label":"بَابُ الْوَكَالَةِ · ٦","segs":[["matn","فَصْلٌ: وَالْوَكَالَةُ وَالشَّرِكَةُ وَالْمُضَارَبَةُ وَالْمُسَاقَاةُ وَالْمُزَارَعَةُ وَالْوَدِيعَةُ وَالْجُعَالَةُ: عُقُودٌ جَائِزَةٌ مِنَ الطَّرَفَيْنِ لِكُلٍّ مِنَ الْمُتَعَاقِدَيْنِ فَسْخُهَا وَتَبْطُلُ كُلُّهَا بِمَوْتِ أَحَدِهِمَا أَوْ جُنُونِهِ وَبِالْحَجْرِ لِسَفَهٍ حَيْثُ اعْتُبِرَ الرُّشْدُ."]]},{"id":"da56_7","label":"بَابُ الْوَكَالَةِ · ٧","segs":[["matn","وَتَبْطُلُ الْوَكَالَةُ بِطُرُوِّ فِسْقٍ لِمُوَكِّلٍ وَوَكِيلٍ فِيمَا يُنَافِيهِ كَإِيجَابِ النِّكَاحِ وَبِفَلَسِ مُوَكِّلٍ فِيمَا حُجِرَ عَلَيْهِ فِيهِ وَبِرِدَّتِهِ وَبِتَدْبِيرِهِ أَوْ كِتَابَتِهِ قِنًّا وُكِّلَ فِي عِتْقِهِ وَبِوَطْئِهِ زَوْجَةً وَكَّلَ فِي طَلَاقِهَا وَبِمَا يَدُلُّ عَلَى الرُّجُوعِ مِنْ أَحَدِهِمَا."]]},{"id":"da56_8","label":"بَابُ الْوَكَالَةِ · ٨","segs":[["matn","وَيَنْعَزِلُ الْوَكِيلُ بِمَوْتِ مُوَكِّلِهِ وَبِعَزْلِهِ لَهُ وَلَوْ لَمْ يَعْلَمْ وَيَكُونُ مَا بِيَدِهِ بَعْدَ الْعَزْلِ أَمَانَةً."]]},{"id":"da56_9","label":"بَابُ الْوَكَالَةِ · ٩","segs":[["matn","فَصْلٌ: وَإِنْ بَاعَ الْوَكِيلُ بِأَنْقَصَ مِنْ ثَمَنِ الْمِثْلِ أَوْ عَنْ مَا قَدَّرَهُ لَهُ مُوَكِّلُهُ أَوِ اشْتَرَى بِأَزْيَدَ أَوْ بِأَكْثَرَ مِمَّا قَدَّرَهُ لَهُ صَحَّ وَضَمِنَ فِي الْبَيْعِ كُلَّ النَّقْصِ وَفِي الشِّرَاءِ كُلَّ الزَّائِدِ وَبِعْهُ لِزَيْدٍ فَبَاعَهُ لِغَيْرِهِ لَمْ يَصِحَّ."]]},{"id":"da56_10","label":"بَابُ الْوَكَالَةِ · ١٠","segs":[["matn","وَمَنْ أُمِرَ بِدَفْعِ شَيْءٍ إِلَى مُعَيَّنٍ لِيَصْنَعَهُ فَدَفَعَ وَنَسِيَهُ لَمْ يَضْمَنْ وَإِنْ أَطْلَقَ الْمَالِكُ فَدَفَعَهُ إِلَى مَنْ لَا يَعْرِفُهُ ضَمِنَ."]]},{"id":"da56_11","label":"بَابُ الْوَكَالَةِ · ١١","segs":[["matn","وَالْوَكِيلُ أَمِينٌ لَا يَضْمَنُ مَا تَلِفَ بِيَدِهِ بِلَا تَفْرِيطٍ وَيُصَدَّقُ بِيَمِينِهِ فِي التَّلَفِ وَأَنَّهُ لَمْ يُفَرِّطْ وَأَنَّهُ أَذِنَ لَهُ فِي الْبَيْعِ مُؤَجَّلًا أَوْ بِغَيْرِ نَقْدِ الْبَلَدِ وَإِنِ ادَّعَى الرَّدَّ لِوَرَثَةِ الْمُوَكِّلِ مُطْلَقًا أَوْ لَهُ وَكَانَ بِجُعْلٍ لَمْ يُقْبَلْ."]]},{"id":"da56_12","label":"بَابُ الْوَكَالَةِ · ١٢","segs":[["matn","وَمَنْ عَلَيْهِ حَقٌّ فَادَّعَى إِنْسَانٌ أَنَّهُ وَكِيلُ رَبِّهِ فِي قَبْضِهِ فَصَدَّقَهُ لَمْ يَلْزَمْهُ دَفْعُهُ إِلَيْهِ وَإِنِ ادَّعَى مَوْتَهُ وَأَنَّهُ وَارِثُهُ لَزِمَهُ دَفْعُهُ وَإِنْ كَذَّبَهُ حَلَفَ أَنَّهُ لَا يَعْلَمُ أَنَّهُ وَارِثُهُ وَلَمْ يَدْفَعْهُ."]]}],"group":"كِتَابُ الْحَجْرِ"},{"id":"da57","title":"كِتَابُ الشَّرِكَةِ","units":[{"id":"da57_1","label":"كِتَابُ الشَّرِكَةِ · ١","segs":[["matn","وَهِيَ خَمْسَةُ أَنْوَاعٍ كُلُّهَا جَائِزَةٌ مِمَّنْ يَجُوزُ تَصَرُّفُهُ: أَحَدُهَا: شَرِكَةُ الْعِنَانِ وَهِيَ: أَنْ يَشْتَرِكَ اثْنَانِ فَأَكْثَرُ فِي مَالٍ يَتَّجِرَانِ فِيهِ وَيَكُونُ الرِّبْحُ بَيْنَهُمَا بِحَسَبِ مَا يَتَّفِقَانِ."]]},{"id":"da57_2","label":"كِتَابُ الشَّرِكَةِ · ٢","segs":[["matn","وَشُرُوطُهَا أَرْبَعَةٌ: الْأَوَّلُ: أَنْ يَكُونَ رَأْسُ الْمَالِ مِنَ النَّقْدَيْنِ الْمَضْرُوبَيْنِ: الذَّهَبِ وَالْفِضَّةِ وَلَوْ لَمْ يَتَّفِقِ الْجِنْسُ. الثَّانِي: أَنْ يَكُونَ كُلٌّ مِنَ الْمَالَيْنِ مَعْلُومًا."]]},{"id":"da57_3","label":"كِتَابُ الشَّرِكَةِ · ٣","segs":[["matn","الثَّالِثُ: حُضُورُ الْمَالَيْنِ وَلَا يُشْتَرَطُ خَلْطُهُمَا وَلَا الْإِذْنُ فِي التَّصَرُّفِ."]]},{"id":"da57_4","label":"كِتَابُ الشَّرِكَةِ · ٤","segs":[["matn","الرَّابِعُ: أَنْ يَشْتَرِطَا لِكُلِّ وَاحِدٍ مِنْهُمَا جُزْءًا مَعْلُومًا مِنَ الرِّبْحِ سَوَاءٌ شَرَطَا لِكُلِّ وَاحِدٍ مِنْهُمَا عَلَى قَدْرِ مَالِهِ أَوْ أَقَلَّ أَوْ أَكْثَرَ."]]},{"id":"da57_5","label":"كِتَابُ الشَّرِكَةِ · ٥","segs":[["matn","فَمَتَى فُقِدَ شَرْطٌ فَهِيَ فَاسِدَةٌ وَحَيْثُ فَسَدَتْ فَالرِّبْحُ عَلَى قَدْرِ الْمَالَيْنِ لَا عَلَى مَا شَرَطَا لَكِنْ يَرْجِعُ كُلٌّ مِنْهُمَا عَلَى صَاحِبِهِ بِأُجْرَةِ نِصْفِ عَمَلِهِ."]]},{"id":"da57_6","label":"كِتَابُ الشَّرِكَةِ · ٦","segs":[["matn","وَكُلُّ عَقْدٍ لَا ضَمَانَ فِي صَحِيحِهِ لَا ضَمَانَ فِي فَاسِدِهِ إِلَّا بِالتَّعَدِّي أَوِ التَّفْرِيطِ كَالشَّرِكَةِ وَالْمُضَارَبَةِ وَالْوَكَالَةِ وَالْوَدِيعَةِ وَالرَّهْنِ وَالْهِبَةِ."]]},{"id":"da57_7","label":"كِتَابُ الشَّرِكَةِ · ٧","segs":[["matn","وَلِكُلٍّ مِنَ الشَّرِيكَيْنِ أَنْ يَبِيعَ وَيَشْتَرِيَ وَيَأْخُذَ وَيُعْطِيَ وَيُطَالِبَ وَيُخَاصِمَ وَيَفْعَلَ كُلَّ مَا فِيهِ حَظٌّ لِلشَّرِكَةِ."]]},{"id":"da57_8","label":"كِتَابُ الشَّرِكَةِ · ٨","segs":[["matn","فَصْلٌ: الثَّانِي: الْمُضَارَبَةُ وَهِيَ: أَنْ يَدْفَعَ مِنْ مَالِهِ إِلَى إِنْسَانٍ لِيَتَّجِرَ فِيهِ وَيَكُونَ الرِّبْحُ بَيْنَهُمَا بِحَسَبِ مَا يَتَّفِقَانِ. وَشُرُوطُهَا ثَلَاثَةٌ: أَحَدُهَا: أَنْ يَكُونَ رَأْسُ الْمَالِ مِنَ النَّقْدَيْنِ الْمَضْرُوبَيْنِ."]]},{"id":"da57_9","label":"كِتَابُ الشَّرِكَةِ · ٩","segs":[["matn","الثَّانِي: أَنْ يَكُونَ مُعَيَّنًا مَعْلُومًا وَلَا يُعْتَبَرُ قَبْضُهُ بِالْمَجْلِسِ وَلَا الْقَبُولُ. الثَّالِثُ: أَنْ يُشْتَرَطَ لِلْعَامِلِ جُزْءٌ مَعْلُومٌ مِنَ الرِّبْحِ."]]},{"id":"da57_10","label":"كِتَابُ الشَّرِكَةِ · ١٠","segs":[["matn","فَإِنْ فُقِدَ شَرْطٌ فَهِيَ فَاسِدَةٌ وَيَكُونُ لِلْعَامِلِ أُجْرَةُ مِثْلِهِ وَمَا حَصَلَ مِنْ خَسَارَةٍ أَوْ رِبْحٍ فَلِلْمَالِكِ وَلَيْسَ لِلْعَامِلِ شِرَاءُ مَنْ يَعْتِقُ عَلَى رَبِّ الْمَالِ فَإِنْ فَعَلَ عَتَقَ وَضَمِنَ ثَمَنَهُ وَلَوْ لَمْ يَعْلَمْ."]]},{"id":"da57_11","label":"كِتَابُ الشَّرِكَةِ · ١١","segs":[["matn","وَلَا نَفَقَةَ لِلْعَامِلِ إِلَّا بِشَرْطٍ فَإِنْ شُرِطَتْ مُطْلَقَةً وَاخْتَلَفَا فَلَهُ نَفَقَةُ مِثْلِهِ عُرْفًا مِنْ طَعَامٍ وَكِسْوَةٍ."]]},{"id":"da57_12","label":"كِتَابُ الشَّرِكَةِ · ١٢","segs":[["matn","وَيَمْلِكُ الْعَامِلُ حِصَّتَهُ مِنَ الرِّبْحِ بِظُهُورِهِ قَبْلَ الْقِسْمَةِ كَالْمَالِكِ لَا الْأَخْذَ مِنْهُ إِلَّا بِإِذْنٍ وَحَيْثُ فُسِخَتْ وَالْمَالُ عَرْضٌ فَرَضِيَ رَبُّهُ بِأَخْذِهِ قَوَّمَهُ وَدَفَعَ لِلْعَامِلِ حِصَّتَهُ وَإِنْ لَمْ يَرْضَ فَعَلَى الْعَامِلِ بَيْعُهُ وَقَبْضُ ثَمَنِهِ."]]},{"id":"da57_13","label":"كِتَابُ الشَّرِكَةِ · ١٣","segs":[["matn","وَالْعَامِلُ أَمِينٌ يُصَدَّقُ بِيَمِينِهِ فِي قَدْرِ رَأْسِ الْمَالِ وَفِي الرِّبْحِ وَعَدَمِهِ وَفِي الْهَلَاكِ وَالْخُسْرَانِ حَتَّى لَوْ أَقَرَّ بِالرِّبْحِ وَيُقْبَلُ قَوْلُ الْمَالِكِ فِي قَدْرِ مَا شَرَطَ لِلْعَامِلِ."]]},{"id":"da57_14","label":"كِتَابُ الشَّرِكَةِ · ١٤","segs":[["matn","فَصْلٌ: الثَّالِثُ: شَرِكَةُ الْوُجُوهِ وَهِيَ: أَنْ يَشْتَرِكَ اثْنَانِ لَا مَالَ لَهُمَا فِي رِبْحِ مَا يَشْتَرِيَانِ مِنَ النَّاسِ فِي ذِمَمِهِمَا وَيَكُونُ الْمِلْكُ وَالرِّبْحُ كَمَا شَرَطَا وَالْخَسَارَةُ عَلَى قَدْرِ الْمِلْكِ."]]},{"id":"da57_15","label":"كِتَابُ الشَّرِكَةِ · ١٥","segs":[["matn","الرَّابِعُ: شَرِكَةُ الْأَبْدَانِ وَهِيَ: أَنْ يَشْتَرِكَا فِيمَا يَتَمَلَّكَانِ بِأَبْدَانِهِمَا مِنَ الْمُبَاحِ: كَالِاحْتِشَاشِ وَالِاحْتِطَابِ وَالِاصْطِيَادِ أَوْ يَشْتَرِكَا فِيمَا يَتَقَبَّلَانِ فِي ذِمَمِهِمَا مِنَ الْعَمَلِ."]]},{"id":"da57_16","label":"كِتَابُ الشَّرِكَةِ · ١٦","segs":[["matn","الْخَامِسُ: شَرِكَةُ الْمُفَاوَضَةِ وَهِيَ: أَنْ يُفَوِّضَ كُلٌّ إِلَى صَاحِبِهِ شِرَاءً وَبَيْعًا فِي الذِّمَّةِ وَمُضَارَبَةً وَتَوْكِيلًا وَمُسَافَرَةً بِالْمَالِ وَارْتِهَانًا."]]},{"id":"da57_17","label":"كِتَابُ الشَّرِكَةِ · ١٧","segs":[["matn","وَيَصِحُّ دَفْعُ دَابَّةٍ أَوْ عَبْدٍ لِمَنْ يَعْمَلُ بِهِ بِجُزْءٍ مِنْ أُجْرَتِهِ وَمِثْلُهُ خِيَاطَةُ ثَوْبٍ وَنَسْجُ غَزْلٍ وَحَصَادُ زَرْعٍ وَرَضَاعُ قِنٍّ وَاسْتِيفَاءُ مَالٍ بِجُزْءٍ مُشَاعٍ مِنْهُ وَبَيْعُ مَتَاعٍ بِجُزْءٍ مِنْ رِبْحِهِ"]]},{"id":"da57_18","label":"كِتَابُ الشَّرِكَةِ · ١٨","segs":[["matn","وَيَصِحُّ دَفْعُ دَابَّةٍ أَوْ نَحْلٍ أَوْ نَحْوِهِمَا لِمَنْ يَقُومُ بِهِمَا مُدَّةً مَعْلُومَةً بِجُزْءٍ مِنْهُمَا وَالنَّمَاءُ مِلْكٌ لَهُمَا لَا إِنْ كَانَ بِجُزْءٍ مِنَ النَّمَاءِ كَالدَّرِّ وَالنَّسْلِ وَالصُّوفِ وَالْعَسَلِ وَلِلْعَامِلِ أُجْرَةُ مِثْلِهِ."]]}],"group":"كِتَابُ الشَّرِكَةِ"},{"id":"da58","title":"بَابُ الْمُسَاقَاةِ","units":[{"id":"da58_1","label":"بَابُ الْمُسَاقَاةِ · ١","segs":[["matn","وَهِيَ: دَفْعُ شَجَرٍ لِمَنْ يَقُومُ بِمَصَالِحِهِ بِجُزْءٍ مِنْ ثَمَرِهِ بِشَرْطِ كَوْنِ الشَّجَرِ مَعْلُومًا وَأَنْ يَكُونَ لَهُ ثَمَرٌ يُؤْكَلُ وَأَنْ يُشْرَطَ لِلْعَامِلِ جُزْءٌ مُشَاعٌ مَعْلُومٌ مِنْ ثَمَرِهِ."]]},{"id":"da58_2","label":"بَابُ الْمُسَاقَاةِ · ٢","segs":[["matn","وَالْمُزَارَعَةُ: دَفْعُ الْأَرْضِ وَالْحَبِّ لِمَنْ يَزْرَعُهُ وَيَقُومُ بِمَصَالِحِهِ بِشَرْطِ كَوْنِ الْبَذْرِ مَعْلُومًا جِنْسُهُ وَقَدْرُهُ وَلَوْ لَمْ يُؤْكَلْ وَكَوْنِهِ مِنْ رَبِّ الْأَرْضِ وَأَنْ يُشْرَطَ لِلْعَامِلِ جُزْءٌ مَعْلُومٌ مُشَاعٌ مِنْهُ وَيَصِحُّ كَوْنُ الْأَرْضِ وَالْبَذْرِ وَالْبَقَرِ مِنْ وَاحِدٍ وَالْعَمَلِ مِنْ آخَرَ."]]},{"id":"da58_3","label":"بَابُ الْمُسَاقَاةِ · ٣","segs":[["matn","فَإِنْ فُقِدَ شَرْطٌ فَالْمُسَاقَاةُ وَالْمُزَارَعَةُ فَاسِدَةٌ وَالثَّمَرُ وَالزَّرْعُ لِرَبِّهِ وَلِلْعَامِلِ أُجْرَةُ مِثْلِهِ. وَلَا شَيْءَ لَهُ إِنْ فَسَخَ أَوْ هَرَبَ قَبْلَ ظُهُورِ الثَّمَرَةِ."]]},{"id":"da58_4","label":"بَابُ الْمُسَاقَاةِ · ٤","segs":[["matn","وَإِنْ فُسِخَ بَعْدَ ظُهُورِهَا فَالثَّمَرَةُ بَيْنَهُمَا عَلَى مَا شَرَطَا وَعَلَى الْعَامِلِ تَمَامُ الْعَمَلِ مِمَّا فِيهِ نُمُوٌّ أَوْ صَلَاحٌ لِلثَّمَرَةِ."]]},{"id":"da58_5","label":"بَابُ الْمُسَاقَاةِ · ٥","segs":[["matn","وَالْجِذَاذُ عَلَيْهِمَا بِقَدْرِ حِصَّتَيْهِمَا وَيَتْبَعَانِ الْعُرْفَ فِي الْكُلَفِ السُّلْطَانِيَّةِ مَا لَمْ يَكُنْ شَرْطٌ فَيُتَّبَعُ."]]}],"group":"كِتَابُ الشَّرِكَةِ"},{"id":"da59","title":"بَابُ الْإِجَارَةِ","units":[{"id":"da59_1","label":"بَابُ الْإِجَارَةِ · ١","segs":[["matn","شُرُوطُهَا ثَلَاثَةٌ: مَعْرِفَةُ الْمَنْفَعَةِ وَمَعْرِفَةُ الْأُجْرَةِ وَكَوْنُ النَّفْعِ مُبَاحًا يُسْتَوْفَى دُونَ الْأَجْزَاءِ."]]},{"id":"da59_2","label":"بَابُ الْإِجَارَةِ · ٢","segs":[["matn","فَتَصِحُّ إِجَارَةُ كُلِّ مَا أَمْكَنَ الِانْتِفَاعُ بِهِ مَعَ بَقَاءِ عَيْنِهِ إِذَا قُدِّرَتْ مَنْفَعَتُهُ بِالْعَمَلِ كَرُكُوبِ الدَّابَّةِ لِمَحَلٍّ مُعَيَّنٍ أَوْ قُدِّرَتْ بِالْأَمَدِ وَإِنْ طَالَ حَيْثُ كَانَ يَغْلِبُ عَلَى الظَّنِّ بَقَاءُ الْعَيْنِ"]]},{"id":"da59_3","label":"بَابُ الْإِجَارَةِ · ٣","segs":[["matn","فَصْلٌ: وَالْإِجَارَةُ ضَرْبَانِ: الْأَوَّلُ: عَلَى عَيْنٍ فَإِنْ كَانَتْ مَوْصُوفَةً اشْتُرِطَ فِيهَا اسْتِقْصَاءُ صِفَاتِ السَّلَمِ وَكَيْفِيَّةُ السَّيْرِ مِنْ هِمْلَاجٍ وَغَيْرِهِ لَا الذُّكُورَةُ وَالْأُنُوثَةُ وَالنَّوْعُ."]]},{"id":"da59_4","label":"بَابُ الْإِجَارَةِ · ٤","segs":[["matn","وَإِنْ كَانَتْ مُعَيَّنَةً اشْتُرِطَ مَعْرِفَتُهَا وَالْقُدْرَةُ عَلَى تَسْلِيمِهَا وَكَوْنُ الْمُؤْجِرِ يَمْلِكُ نَفْعَهَا وَصِحَّةُ بَيْعِهَا سِوَى حُرٍّ وَوَقْفٍ وَأُمِّ وَلَدٍ وَاشْتِمَالُهَا عَلَى النَّفْعِ الْمَقْصُودِ مِنْهَا فَلَا تَصِحُّ فِي زَمِنَةٍ لِحَمْلٍ وَسَبِخَةٍ لِزَرْعٍ."]]},{"id":"da59_5","label":"بَابُ الْإِجَارَةِ · ٥","segs":[["matn","الثَّانِي: عَلَى مَنْفَعَةٍ فِي الذِّمَّةِ فَيُشْتَرَطُ ضَبْطُهَا بِمَا لَا يَخْتَلِفُ كَخِيَاطَةِ ثَوْبٍ بِصِفَةِ كَذَا وَبِنَاءِ حَائِطٍ يَذْكُرُ طُولَهُ وَعَرْضَهُ وَسَمْكَهُ وَآلَتَهُ وَأَنْ لَا يُجْمَعَ بَيْنَ تَقْدِيرِ الْمُدَّةِ وَالْعَمَلِ:"]]},{"id":"da59_6","label":"بَابُ الْإِجَارَةِ · ٦","segs":[["matn","كَلِتَخِيطَهُ فِي يَوْمٍ وَكَوْنُ الْعَمَلِ لَا يُشْتَرَطُ أَنْ يَكُونَ فَاعِلُهُ مُسْلِمًا فَلَا تَصِحُّ الْإِجَارَةُ لِأَذَانٍ وَإِقَامَةٍ وَإِمَامَةٍ وَتَعْلِيمِ قُرْآنٍ وَفِقْهٍ وَحَدِيثٍ وَنِيَابَةٍ فِي حَجٍّ وَقَضَاءٍ وَلَا يَقَعُ إِلَّا قُرْبَةً لِفَاعِلِهِ. وَيَحْرُمُ أَخْذُ الْأُجْرَةِ عَلَيْهِ وَتَجُوزُ الْجُعَالَةُ."]]},{"id":"da59_7","label":"بَابُ الْإِجَارَةِ · ٧","segs":[["matn","فَصْلٌ: وَلِلْمُسْتَأْجِرِ اسْتِيفَاءُ النَّفْعِ بِنَفْسِهِ: وَبِمَنْ يَقُومُ مَقَامَهُ لَكِنْ بِشَرْطِ كَوْنِهِ مِثْلَهُ فِي الضَّرَرِ أَوْ دُونَهُ."]]},{"id":"da59_8","label":"بَابُ الْإِجَارَةِ · ٨","segs":[["matn","وَعَلَى الْمُؤْجِرِ كُلُّ مَا جَرَتْ بِهِ الْعَادَةُ مِنْ آلَةِ الْمَرْكُوبِ وَالْقَوْدُ وَالسَّوْقُ وَالشَّيْلُ وَالْحَطُّ وَتَرْمِيمُ الدَّارِ بِإِصْلَاحِ الْمُنْكَسِرِ وَإِقَامَةِ الْمَائِلِ وَتَطْيِينِ السَّطْحِ وَتَنْظِيفِهِ مِنَ الثَّلْجِ وَنَحْوِهِ."]]},{"id":"da59_9","label":"بَابُ الْإِجَارَةِ · ٩","segs":[["matn","وَعَلَى الْمُسْتَأْجِرِ الْمَحْمِلُ وَالْمِظَلَّةُ وَتَفْرِيغُ الْبَالُوعَةِ وَالْكَنِيفِ وَكَنْسُ الدَّارِ مِنَ الزِّبْلِ وَنَحْوِهِ إِنْ حَصَلَ بِفِعْلِهِ."]]},{"id":"da59_10","label":"بَابُ الْإِجَارَةِ · ١٠","segs":[["matn","فَصْلٌ: وَالْإِجَارَةُ عَقْدٌ لَازِمٌ لَا تَنْفَسِخُ بِمَوْتِ الْمُتَعَاقِدَيْنِ وَلَا بِتَلَفِ الْمَحْمُولِ وَلَا بِوَقْفِ الْعَيْنِ الْمُؤَجَّرَةِ وَلَا بِانْتِقَالِ الْمِلْكِ فِيهَا بِنَحْوِ هِبَةٍ. وَبَيْعٍ وَلِمُشْتَرٍ لَمْ يَعْلَمِ الْفَسْخُ أَوْ: الْإِمْضَاءُ وَالْأُجْرَةُ لَهُ."]]},{"id":"da59_11","label":"بَابُ الْإِجَارَةِ · ١١","segs":[["matn","وَتَنْفَسِخُ بِتَلَفِ الْعَيْنِ الْمُؤَجَّرَةِ الْمُعَيَّنَةِ وَبِمَوْتِ الْمُرْتَضِعِ وَهَدْمِ الدَّارِ. وَمَتَى تَعَذَّرَ اسْتِيفَاءُ النَّفْعِ وَلَوْ بَعْضَهُ مِنْ جِهَةِ الْمُؤْجِرِ فَلَا شَيْءَ لَهُ وَمِنْ جِهَةِ الْمُسْتَأْجِرِ فَعَلَيْهِ جَمِيعُ الْأُجْرَةِ."]]},{"id":"da59_12","label":"بَابُ الْإِجَارَةِ · ١٢","segs":[["matn","وَإِنْ تَعَذَّرَ بِغَيْرِ فِعْلِ أَحَدِهِمَا كَشُرُودِ الْمُؤَجَّرَةِ وَهَدْمِ الدَّارِ وَجَبَ مِنْهَا الْأُجْرَةُ بِقَدْرِ مَا اسْتَوْفَى."]]},{"id":"da59_13","label":"بَابُ الْإِجَارَةِ · ١٣","segs":[["matn","وَإِنْ هَرَبَ الْمُؤْجِرُ وَتَرَكَ بَهَائِمَهُ وَأَنْفَقَ عَلَيْهَا الْمُسْتَأْجِرُ بِنِيَّةِ الرُّجُوعِ رَجَعَ لِأَنَّ النَّفَقَةَ عَلَى الْمُؤْجِرِ كَالْمُعِيرِ."]]},{"id":"da59_14","label":"بَابُ الْإِجَارَةِ · ١٤","segs":[["matn","فَصْلٌ: وَالْأَجِيرُ قِسْمَانِ: خَاصٌّ: وَهُوَ مَنْ قُدِّرَ نَفْعُهُ بِالزَّمَنِ وَمُشْتَرَكٌ: وَهُوَ: مَنْ قُدِّرَ نَفْعُهُ بِالْعَمَلِ. فَالْخَاصُّ لَا يَضْمَنُ مَا تَلِفَ فِي يَدِهِ إِلَّا إِنْ فَرَّطَ."]]},{"id":"da59_15","label":"بَابُ الْإِجَارَةِ · ١٥","segs":[["matn","وَالْمُشْتَرَكُ يَضْمَنُ مَا تَلِفَ بِفِعْلِهِ مِنْ تَخْرِيقٍ وَغَلَطٍ فِي تَفْصِيلٍ وَبِزَلَقِهِ وَبِسُقُوطِهِ عَنْ دَابَّتِهِ وَبِانْقِطَاعِ حَبْلِهِ لَا مَا تَلِفَ بِحِرْزِهِ أَوْ بِغَيْرِ فِعْلِهِ إِنْ لَمْ يُفَرِّطْ."]]},{"id":"da59_16","label":"بَابُ الْإِجَارَةِ · ١٦","segs":[["matn","وَلَا يَضْمَنُ حَجَّامٌ وَخَتَّانٌ وَبَيْطَارٌ خَاصًّا كَانَ أَوْ مُشْتَرَكًا إِنْ كَانَ حَاذِقًا وَلَمْ تَجْنِ يَدُهُ وَأَذِنَ فِيهِ مُكَلَّفٌ أَوْ وَلِيُّهُ وَلَا رَاعٍ لَمْ يَتَعَدَّ أَوْ يُفَرِّطْ بِنَوْمٍ أَوْ غَيْبَتِهَا عَنْهُ. وَلَا يَصِحُّ أَنْ يَرْعَاهَا بِجُزْءٍ مِنْ نَمَائِهَا."]]},{"id":"da59_17","label":"بَابُ الْإِجَارَةِ · ١٧","segs":[["matn","فَصْلٌ: وَتَسْتَقِرُّ الْأُجْرَةُ بِفَرَاغِ الْعَمَلِ وَبِانْتِهَاءِ الْمُدَّةِ وَكَذَا بِبَذْلِ تَسْلِيمِ الْعَيْنِ إِذَا مَضَتْ مُدَّةٌ يُمْكِنُ اسْتِيفَاءُ الْمَنْفَعَةِ فِيهَا وَلَمْ تُسْتَوْفَ. وَيَصِحُّ: شَرْطُ تَعْجِيلِ الْأُجْرَةِ وَتَأْخِيرِهَا."]]},{"id":"da59_18","label":"بَابُ الْإِجَارَةِ · ١٨","segs":[["matn","وَإِنِ اخْتَلَفَا فِي قَدْرِهَا تَحَالَفَا وَتَفَاسَخَا وَإِنْ كَانَ قَدِ اسْتَوْفَى مَا لَهُ أُجْرَةٌ فَأُجْرَةُ الْمِثْلِ."]]},{"id":"da59_19","label":"بَابُ الْإِجَارَةِ · ١٩","segs":[["matn","وَالْمُسْتَأْجِرُ أَمِينٌ لَا يَضْمَنُ وَلَوْ شَرَطَ عَلَى نَفْسِهِ الضَّمَانَ إِلَّا بِالتَّفْرِيطِ وَيُقْبَلُ قَوْلُهُ فِي أَنَّهُ لَمْ يُفَرِّطْ أَوْ أَنَّ مَا اسْتَأْجَرَهُ أَبَقَ أَوْ شَرَدَ أَوْ مَرِضَ أَوْ مَاتَ."]]},{"id":"da59_20","label":"بَابُ الْإِجَارَةِ · ٢٠","segs":[["matn","وَإِنْ شَرَطَ عَلَيْهِ أَنْ لَا يَسِيرَ بِهَا فِي اللَّيْلِ أَوْ وَقْتَ الْقَائِلَةِ أَوْ لَا يَتَأَخَّرَ بِهَا عَنِ الْقَافِلَةِ وَنَحْوَ ذَلِكَ مِمَّا فِيهِ غَرَضٌ صَحِيحٌ فَخَالَفَ ضَمِنَ وَمَتَى انْقَضَتِ الْإِجَارَةُ رَفَعَ الْمُسْتَأْجِرُ يَدَهُ وَلَمْ يَلْزَمْهُ الرَّدُّ وَلَا مُؤْنَتُهُ كَالْمُودَعِ."]]}],"group":"كِتَابُ الشَّرِكَةِ"},{"id":"da60","title":"بَابُ الْمُسَابَقَةِ","units":[{"id":"da60_1","label":"بَابُ الْمُسَابَقَةِ · ١","segs":[["matn","وَهِيَ جَائِزَةٌ فِي السُّفُنِ وَالْمَزَارِيقِ وَالطُّيُورِ وَغَيْرِهَا وَعَلَى الْأَقْدَامِ وَبِكُلِّ الْحَيَوَانَاتِ. لَكِنْ لَا يَجُوزُ أَخْذُ الْعِوَضِ إِلَّا فِي مُسَابَقَةِ الْخَيْلِ وَالْإِبِلِ وَالسِّهَامِ بِشُرُوطٍ خَمْسَةٍ: أَحَدُهَا: تَعْيِينُ الْمَرْكُوبَيْنِ أَوِ الرَّامِيَيْنِ بِالرُّؤْيَةِ."]]},{"id":"da60_2","label":"بَابُ الْمُسَابَقَةِ · ٢","segs":[["matn","الثَّانِي: اتِّحَادُ الْمَرْكُوبَيْنِ أَوِ الْقَوْسَيْنِ بِالنَّوْعِ. الثَّالِثُ: تَحْدِيدُ الْمَسَافَةِ بِمَا جَرَتْ بِهِ الْعَادَةُ. الرَّابِعُ: عِلْمُ الْعِوَضِ وَإِبَاحَتُهُ."]]},{"id":"da60_3","label":"بَابُ الْمُسَابَقَةِ · ٣","segs":[["matn","الْخَامِسُ: الْخُرُوجُ عَنْ شَبَهِ الْقِمَارِ بِأَنْ يَكُونَ الْعِوَضُ مِنْ وَاحِدٍ فَإِنْ أَخْرَجَا مَعًا لَمْ يَجُزْ إِلَّا بِمُحَلِّلٍ لَا يُخْرِجُ شَيْئًا."]]},{"id":"da60_4","label":"بَابُ الْمُسَابَقَةِ · ٤","segs":[["matn","وَلَا يَجُوزُ أَكْثَرَ مِنْ وَاحِدٍ يُكَافِئُ مَرْكُوبُهُ مَرْكُوبَيْهِمَا أَوْ رَمْيُهُ رَمْيَيْهِمَا فَإِنْ سَبَقَا مَعًا أَحْرَزَا سَبَقَيْهِمَا وَلَمْ يَأْخُذَا مِنَ الْمُحَلِّلِ شَيْئًا وَإِنْ سَبَقَ أَحَدُهُمَا أَوْ سَبَقَ الْمُحَلِّلُ أَحْرَزَ السَّبَقَيْنِ."]]},{"id":"da60_5","label":"بَابُ الْمُسَابَقَةِ · ٥","segs":[["matn","وَالْمُسَابَقَةُ جُعَالَةٌ لَا يُؤْخَذُ بِعِوَضِهَا رَهْنٌ وَلَا كَفِيلٌ وَلِكُلٍّ فَسْخُهَا مَا لَمْ يَظْهَرِ الْفَضْلُ لِصَاحِبِهِ."]]}],"group":"كِتَابُ الشَّرِكَةِ"},{"id":"da61","title":"كِتَابُ الْعَارِيَّةِ","units":[{"id":"da61_1","label":"كِتَابُ الْعَارِيَّةِ · ١","segs":[["matn","وَهِيَ مُسْتَحَبَّةٌ مُنْعَقِدَةٌ بِكُلِّ قَوْلٍ أَوْ فِعْلٍ يَدُلُّ عَلَيْهَا بِشُرُوطٍ ثَلَاثَةٍ: كَوْنُ الْعَيْنِ مُنْتَفَعًا بِهَا مَعَ بَقَائِهَا وَكَوْنُ النَّفْعِ مُبَاحًا وَكَوْنُ الْمُعِيرِ أَهْلًا لِلتَّبَرُّعِ."]]},{"id":"da61_2","label":"كِتَابُ الْعَارِيَّةِ · ٢","segs":[["matn","وَلِلْمُعِيرِ الرُّجُوعُ فِي عَارِيَّتِهِ أَيَّ وَقْتٍ شَاءَ مَا لَمْ يَضُرَّ بِالْمُسْتَعِيرِ."]]},{"id":"da61_3","label":"كِتَابُ الْعَارِيَّةِ · ٣","segs":[["matn","فَمَنْ أَعَارَ سَفِينَةً لِحَمْلٍ أَوْ أَرْضًا لِدَفْنٍ أَوْ زَرْعٍ لَمْ يَرْجِعْ حَتَّى تُرْسِيَ السَّفِينَةُ وَيَبْلَى الْمَيِّتُ وَيُحْصَدَ الزَّرْعُ وَلَا أُجْرَةَ لَهُ مُنْذُ رَجَعَ إِلَّا فِي الزَّرْعِ."]]},{"id":"da61_4","label":"كِتَابُ الْعَارِيَّةِ · ٤","segs":[["matn","فَصْلٌ: وَالْمُسْتَعِيرُ فِي اسْتِيفَاءِ النَّفْعِ كَالْمُسْتَأْجِرِ إِلَّا أَنَّهُ لَا يُعِيرُ وَلَا يُؤْجِرُ إِلَّا بِإِذْنِ الْمَالِكِ."]]},{"id":"da61_5","label":"كِتَابُ الْعَارِيَّةِ · ٥","segs":[["matn","وَإِذَا قَبَضَ الْمُسْتَعِيرُ الْعَارِيَّةَ فَهِيَ مَضْمُونَةٌ عَلَيْهِ بِمِثْلِ مِثْلِيٍّ وَقِيمَةِ مُتَقَوِّمٍ يَوْمَ تَلَفٍ فَرَّطَ أَوْ لَا."]]},{"id":"da61_6","label":"كِتَابُ الْعَارِيَّةِ · ٦","segs":[["matn","لَكِنْ لَا ضَمَانَ فِي أَرْبَعِ مَسَائِلَ إِلَّا بِالتَّفْرِيطِ: فِيمَا إِذَا كَانَتِ الْعَارِيَّةُ وَقْفًا كَكُتُبِ عِلْمٍ وَسِلَاحٍ وَفِيمَا إِذَا أَعَارَهَا الْمُسْتَأْجِرُ أَوْ بَلِيَتْ فِيمَا أُعِيرَتْ لَهُ أَوْ أَرْكَبَ دَابَّتَهُ مُنْقَطِعًا لِلَّهِ تَعَالَى فَتَلِفَتْ تَحْتَهُ."]]},{"id":"da61_7","label":"كِتَابُ الْعَارِيَّةِ · ٧","segs":[["matn","وَمَنِ اسْتَعَارَ لِيَرْهَنَ فَالْمُرْتَهِنُ أَمِينٌ وَيَضْمَنُ الْمُسْتَعِيرُ. وَمَنْ سَلَّمَ لِشَرِيكِهِ الدَّابَّةَ وَلَمْ يَسْتَعْمِلْهَا أَوِ اسْتَعْمَلَهَا فِي مُقَابَلَةِ عَلَفِهَا بِإِذْنِ شَرِيكِهِ وَتَلِفَتْ بِلَا تَفْرِيطٍ لَمْ يَضْمَنْ."]]}],"group":"كِتَابُ الْعَارِيَّةِ"},{"id":"da62","title":"كِتَابُ الْغَصْبِ","units":[{"id":"da62_1","label":"كِتَابُ الْغَصْبِ · ١","segs":[["matn","وَهُوَ الِاسْتِيلَاءُ عُرْفًا عَلَى حَقِّ الْغَيْرِ عُدْوَانًا. وَيَلْزَمُ الْغَاصِبَ رَدُّ مَا غَصَبَ بِنَمَائِهِ وَلَوْ غَرِمَ عَلَى رَدِّهِ أَضْعَافَ قِيمَتِهِ."]]},{"id":"da62_2","label":"كِتَابُ الْغَصْبِ · ٢","segs":[["matn","وَإِنْ سَمَّرَ بِالْمَسَامِيرِ بَابًا قَلَعَهَا وَرَدَّهَا وَإِنْ زَرَعَ الْأَرْضَ فَلَيْسَ لِرَبِّهَا بَعْدَ حَصْدِهِ إِلَّا الْأُجْرَةُ وَقَبْلَ الْحَصْدِ يُخَيَّرُ بَيْنَ تَرْكِهِ بِأُجْرَتِهِ أَوْ تَمَلُّكِهِ بِنَفَقَتِهِ وَهِيَ: مِثْلُ الْبَذْرِ وَعِوَضُ لَوَاحِقِهِ."]]},{"id":"da62_3","label":"كِتَابُ الْغَصْبِ · ٣","segs":[["matn","وَإِنْ غَرَسَ أَوْ بَنَى فِي الْأَرْضِ أُلْزِمَ بِقَلْعِ غَرْسِهِ وَبِنَائِهِ حَتَّى وَلَوْ كَانَ أَحَدَ الشَّرِيكَيْنِ وَفَعَلَهُ بِغَيْرِ إِذْنِ شَرِيكِهِ."]]},{"id":"da62_4","label":"كِتَابُ الْغَصْبِ · ٤","segs":[["matn","فَصْلٌ: وَعَلَى الْغَاصِبِ أَرْشُ نَقْصِ الْمَغْصُوبِ وَأُجْرَتُهُ مُدَّةَ مُقَامِهِ بِيَدِهِ. فَإِنْ تَلِفَ ضَمِنَ الْمِثْلِيَّ بِمِثْلِهِ وَالْمُتَقَوَّمَ بِقِيمَتِهِ يَوْمَ تَلَفِهِ فِي بَلَدِ غَصْبِهِ."]]},{"id":"da62_5","label":"كِتَابُ الْغَصْبِ · ٥","segs":[["matn","وَيَضْمَنُ مَصَاغًا مُبَاحًا مِنْ ذَهَبٍ أَوْ فِضَّةٍ بِالْأَكْثَرِ مِنْ قِيمَتِهِ أَوْ وَزْنِهِ وَالْمُحَرَّمَ بِوَزْنِهِ. وَيُقْبَلُ قَوْلُ الْغَاصِبِ فِي قِيمَةِ الْمَغْصُوبِ وَفِي قَدْرِهِ."]]},{"id":"da62_6","label":"كِتَابُ الْغَصْبِ · ٦","segs":[["matn","وَيَضْمَنُ جِنَايَتَهُ وَإِتْلَافَهُ بِالْأَقَلِّ مِنَ الْأَرْشِ أَوْ قِيمَتِهِ وَإِنْ أَطْعَمَ الْغَاصِبُ مَا غَصَبَهُ حَتَّى وَلَوْ لِمَالِكِهِ وَلَمْ يَعْلَمْ لَمْ يَبْرَأِ الْغَاصِبُ وَإِنْ عَلِمَ الْآكِلُ حَقِيقَةَ الْحَالِ اسْتَقَرَّ الضَّمَانُ عَلَيْهِ."]]},{"id":"da62_7","label":"كِتَابُ الْغَصْبِ · ٧","segs":[["matn","وَمَنِ اشْتَرَى أَرْضًا فَغَرَسَ أَوْ بَنَى فِيهَا فَخَرَجَتْ مُسْتَحَقَّةً لِلْغَيْرِ وَقُلِعَ غَرْسُهُ وَبِنَاؤُهُ رَجَعَ عَلَى الْبَائِعِ بِجَمِيعِ مَا غَرِمَهُ."]]},{"id":"da62_8","label":"كِتَابُ الْغَصْبِ · ٨","segs":[["matn","فَصْلٌ: وَمَنْ أَتْلَفَ وَلَوْ سَهْوًا مَالًا لِغَيْرِهِ ضَمِنَهُ وَإِنْ أُكْرِهَ عَلَى الْإِتْلَافِ ضَمِنَ مَنْ أَكْرَهَهُ."]]},{"id":"da62_9","label":"كِتَابُ الْغَصْبِ · ٩","segs":[["matn","وَإِنْ فَتَحَ قَفَصًا عَنْ طَائِرٍ أَوْ حَلَّ قِنًّا أَوْ أَسِيرًا أَوْ حَيَوَانًا مَرْبُوطًا فَذَهَبَ أَوْ حَلَّ وِكَاءَ زِقٍّ فِيهِ مَائِعٌ فَانْدَفَقَ ضَمِنَهُ."]]},{"id":"da62_10","label":"كِتَابُ الْغَصْبِ · ١٠","segs":[["matn","وَلَوْ بَقِيَ الْحَيَوَانُ أَوِ الطَّائِرُ حَتَّى نَفَّرَهُ آخَرُ ضَمِنَ الْمُنَفِّرُ وَمَنْ أَوْقَفَ دَابَّةً بِطَرِيقٍ وَلَوْ وَاسِعًا أَوْ تَرَكَ بِهَا نَحْوَ طِينٍ أَوْ خَشَبَةٍ ضَمِنَ مَا تَلِفَ بِذَلِكَ لَكِنْ لَوْ كَانَتِ الدَّابَّةُ بِطَرِيقٍ وَاسِعٍ فَضَرَبَهَا فَرَفَسَتْهُ فَلَا ضَمَانَ."]]},{"id":"da62_11","label":"كِتَابُ الْغَصْبِ · ١١","segs":[["matn","وَمَنِ اقْتَنَى كَلْبًا عَقُورًا أَوْ أَسْوَدَ بَهِيمًا أَوْ أَسَدًا أَوْ ذِئْبًا أَوْ جَارِحًا فَأَتْلَفَ شَيْئًا ضَمِنَهُ لَا إِنْ دَخَلَ دَارَ رَبِّهِ بِلَا إِذْنِهِ."]]},{"id":"da62_12","label":"كِتَابُ الْغَصْبِ · ١٢","segs":[["matn","وَمَنْ أَجَّجَ نَارًا فِي مِلْكِهِ فَتَعَدَّتْ إِلَى مِلْكِ غَيْرِهِ بِتَفْرِيطِهِ ضَمِنَ لَا إِنْ طَرَأَتْ رِيحٌ."]]},{"id":"da62_13","label":"كِتَابُ الْغَصْبِ · ١٣","segs":[["matn","وَمَنِ اضْطَجَعَ فِي مَسْجِدٍ أَوْ فِي طَرِيقٍ أَوْ وَضَعَ حَجَرًا بِطِينٍ فِي الطَّرِيقِ لِيَطَأَ عَلَيْهِ النَّاسُ لَمْ يَضْمَنْ."]]},{"id":"da62_14","label":"كِتَابُ الْغَصْبِ · ١٤","segs":[["matn","فَصْلٌ: وَلَا يَضْمَنُ رَبُّ بَهِيمَةٍ غَيْرِ ضَارِيَةٍ مَا أَتْلَفَتْهُ نَهَارًا مِنَ الْأَمْوَالِ وَالْأَبْدَانِ وَيَضْمَنُ رَاكِبٌ وَسَائِقٌ وَقَائِدٌ قَادِرٌ عَلَى التَّصَرُّفِ فِيهَا"]]},{"id":"da62_15","label":"كِتَابُ الْغَصْبِ · ١٥","segs":[["matn","وَإِنْ تَعَدَّدَ رَاكِبٌ ضَمِنَ الْأَوَّلُ أَوْ مَنْ خَلْفَهُ إِنِ انْفَرَدَ بِتَدْبِيرِهَا وَإِنِ اشْتَرَكَا فِي تَدْبِيرِهَا أَوْ لَمْ يَكُنْ إِلَّا قَائِدٌ وَسَائِقٌ اشْتَرَكَا فِي الضَّمَانِ."]]},{"id":"da62_16","label":"كِتَابُ الْغَصْبِ · ١٦","segs":[["matn","وَيَضْمَنُ رَبُّهَا مَا أَتْلَفَتْهُ لَيْلًا إِنْ كَانَ بِتَفْرِيطِهِ وَكَذَا مُسْتَعِيرُهَا وَمُسْتَأْجِرُهَا وَمَنْ يَحْفَظُهَا."]]},{"id":"da62_17","label":"كِتَابُ الْغَصْبِ · ١٧","segs":[["matn","وَمَنْ قَتَلَ صَائِلًا عَلَيْهِ وَلَوْ آدَمِيًّا دَفْعًا عَنْ نَفْسِهِ أَوْ مَالِهِ أَوْ أَتْلَفَ مِزْمَارًا أَوْ آلَةَ لَهْوٍ أَوْ كَسَرَ إِنَاءَ فِضَّةٍ أَوْ ذَهَبٍ أَوْ"]]},{"id":"da62_18","label":"كِتَابُ الْغَصْبِ · ١٨","segs":[["matn","فِيهِ خَمْرٌ مَأْمُورٌ بِإِرَاقَتِهِ أَوْ كَسَرَ حُلِيًّا مُحَرَّمًا أَوْ أَتْلَفَ آلَةَ سِحْرٍ أَوْ تَعْزِيمٍ أَوْ تَنْجِيمٍ أَوْ صُوَرَ خَيَالٍ أَوْ أَتْلَفَ كُتُبَ مُبْتَدِعَةٍ مُضِلَّةٍ أَوْ أَتْلَفَ كِتَابًا فِيهِ أَحَادِيثُ رَدِيئَةٌ لَمْ يَضْمَنْ فِي الْجَمِيعِ."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da63","title":"بَابُ الشُّفْعَةِ","units":[{"id":"da63_1","label":"بَابُ الشُّفْعَةِ · ١","segs":[["matn","لَا شُفْعَةَ لِكَافِرٍ عَلَى مُسْلِمٍ. وَتَثْبُتُ لِلشَّرِيكِ فِيمَا انْتَقَلَ عَنْهُ مِلْكُ شَرِيكِهِ بِشُرُوطٍ خَمْسَةٍ: أَحَدُهَا: كَوْنُهُ مَبِيعًا فَلَا شُفْعَةَ فِيمَا انْتَقَلَ عَنْهُ مِلْكُهُ بِغَيْرِ بَيْعٍ الثَّانِي: كَوْنُهُ مُشَاعًا مِنْ عَقَارٍ فَلَا شُفْعَةَ لِلْجَارِ وَلَا فِيمَا لَيْسَ بِعَقَارٍ كَشَجَرٍ وَبِنَاءٍ مُفْرَدٍ وَيُؤْخَذُ الْغِرَاسُ وَالْبِنَاءُ تَبَعًا لِلْأَرْضِ."]]},{"id":"da63_2","label":"بَابُ الشُّفْعَةِ · ٢","segs":[["matn","الثَّالِثُ: طَلَبُ الشُّفْعَةِ سَاعَةَ يَعْلَمُ فَإِنْ أَخَّرَ الطَّلَبَ لِغَيْرِ عُذْرٍ سَقَطَتْ وَالْجَهْلُ بِالْحُكْمِ عُذْرٌ."]]},{"id":"da63_3","label":"بَابُ الشُّفْعَةِ · ٣","segs":[["matn","الرَّابِعُ: أَخْذُ جَمِيعِ الْمَبِيعِ فَإِنْ طَلَبَ أَخْذَ الْبَعْضِ مَعَ بَقَاءِ الْكُلِّ سَقَطَتْ وَالشُّفْعَةُ بَيْنَ الشُّفَعَاءِ عَلَى قَدْرِ أَمْلَاكِهِمْ."]]},{"id":"da63_4","label":"بَابُ الشُّفْعَةِ · ٤","segs":[["matn","الْخَامِسُ: سَبْقُ مِلْكِ الشَّفِيعِ لِرَقَبَةِ الْعَقَارِ فَلَا شُفْعَةَ لِأَحَدِ اثْنَيْنِ اشْتَرَيَا عَقَارًا مَعًا. وَتَصَرُّفُ الْمُشْتَرِي بَعْدَ أَخْذِ الشَّفِيعِ بِالشُّفْعَةِ بَاطِلٌ وَقَبْلَهُ صَحِيحٌ."]]},{"id":"da63_5","label":"بَابُ الشُّفْعَةِ · ٥","segs":[["matn","وَيَلْزَمُ الشَّفِيعَ أَنْ يَدْفَعَ لِلْمُشْتَرِي الثَّمَنَ الَّذِي وَقَعَ عَلَيْهِ الْعَقْدُ فَإِنْ كَانَ مِثْلِيًّا فَمِثْلُهُ أَوْ مُتَقَوَّمًا فَقِيمَتُهُ فَإِنْ جُهِلَ الثَّمَنُ وَلَا حِيلَةَ: سَقَطَتِ الشُّفْعَةُ وَكَذَا إِنْ عَجَزَ الشَّفِيعُ وَلَوْ عَنْ بَعْضِ الثَّمَنِ وَانْتُظِرَ ثَلَاثَةَ أَيَّامٍ وَلَمْ يَأْتِ بِهِ."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da64","title":"بَابُ الْوَدِيعَةِ","units":[{"id":"da64_1","label":"بَابُ الْوَدِيعَةِ · ١","segs":[["matn","يُشْتَرَطُ لِصِحَّتِهَا كَوْنُهَا مِنْ جَائِزِ التَّصَرُّفِ لِمِثْلِهِ فَلَوْ أَوْدَعَ مَالَهُ لِصَغِيرٍ أَوْ مَجْنُونٍ أَوْ سَفِيهٍ فَأَتْلَفَهُ فَلَا ضَمَانَ وَإِنْ أَوْدَعَهُ أَحَدُهُمْ صَارَ ضَامِنًا وَلَمْ يَبْرَأْ إِلَّا بِرَدِّهِ لِوَلِيِّهِ."]]},{"id":"da64_2","label":"بَابُ الْوَدِيعَةِ · ٢","segs":[["matn","وَيَلْزَمُ الْمُودَعَ حِفْظُ الْوَدِيعَةِ فِي حِرْزِ مِثْلِهَا بِنَفْسِهِ أَوْ بِمَنْ يَقُومُ مَقَامَهُ كَزَوْجَتِهِ وَعَبْدِهِ."]]},{"id":"da64_3","label":"بَابُ الْوَدِيعَةِ · ٣","segs":[["matn","وَإِنْ دَفَعَهَا لِعُذْرٍ إِلَى أَجْنَبِيٍّ لَمْ يَضْمَنْ وَإِنْ نَهَاهُ مَالِكُهَا عَنْ إِخْرَاجِهَا مِنَ الْحِرْزِ فَأَخْرَجَهَا لِطَرَيَانِ شَيْءٍ الْغَالِبُ مِنْهُ الْهَلَاكُ لَمْ يَضْمَنْ"]]},{"id":"da64_4","label":"بَابُ الْوَدِيعَةِ · ٤","segs":[["matn","وَإِنْ تَرَكَهَا وَلَمْ يُخْرِجْهَا أَوْ أَخْرَجَهَا لِغَيْرِ خَوْفٍ ضَمِنَ فَإِنْ قَالَ لَهُ لَا تُخْرِجْهَا وَلَوْ خِفْتَ عَلَيْهَا فَحَصَلَ خَوْفٌ وَأَخْرَجَهَا أَوْ لَا لَمْ يَضْمَنْ."]]},{"id":"da64_5","label":"بَابُ الْوَدِيعَةِ · ٥","segs":[["matn","وَإِنْ أَلْقَاهَا عِنْدَ هُجُومِ نَاهِبٍ وَنَحْوِهِ إِخْفَاءً لَهَا لَمْ يَضْمَنْ. وَإِنْ لَمْ يَعْلِفِ الْبَهِيمَةَ حَتَّى مَاتَتْ ضَمِنَهَا."]]},{"id":"da64_6","label":"بَابُ الْوَدِيعَةِ · ٦","segs":[["matn","فَصْلٌ: وَإِنْ أَرَادَ الْمُودَعُ السَّفَرَ رَدَّ الْوَدِيعَةَ إِلَى مَالِكِهَا أَوْ إِلَى مَنْ يَحْفَظُ مَالَهُ عَادَةً أَوْ إِلَى وَكِيلِهِ فَإِنْ تَعَذَّرَ وَلَمْ يَخَفْ عَلَيْهَا مَعَهُ فِي السَّفَرِ سَافَرَ بِهَا وَلَا ضَمَانَ فَإِنْ خَافَ عَلَيْهَا دَفَعَهَا لِلْحَاكِمِ فَإِنْ تَعَذَّرَ فَلِثِقَةٍ."]]},{"id":"da64_7","label":"بَابُ الْوَدِيعَةِ · ٧","segs":[["matn","وَلَا يَضْمَنُ مُسَافِرٌ أُودِعَ فَسَافَرَ بِهَا فَتَلِفَتْ بِالسَّفَرِ. وَإِنْ تَعَدَّى الْمُودَعُ فِي الْوَدِيعَةِ بِأَنْ رَكِبَهَا لَا لِسَقْيِهَا أَوْ لَبِسَهَا لَا لِخَوْفٍ مِنْ عُثٍّ أَوْ أَخْرَجَ الدَّرَاهِمَ لِيُنْفِقَهَا أَوْ لِيَنْظُرَ إِلَيْهَا"]]},{"id":"da64_8","label":"بَابُ الْوَدِيعَةِ · ٨","segs":[["matn","ثُمَّ رَدَّهَا أَوْ حَلَّ كِيسَهَا فَقَطْ حَرُمَ عَلَيْهِ وَصَارَ ضَامِنًا وَوَجَبَ عَلَيْهِ رَدُّهَا فَوْرًا وَلَا تَعُودُ أَمَانَةً بِغَيْرِ عَقْدٍ مُتَجَدِّدٍ. وَصَحَّ: كُلَّمَا خُنْتَ ثُمَّ عُدْتَ إِلَى الْأَمَانَةِ فَأَنْتَ أَمِينٌ"]]},{"id":"da64_9","label":"بَابُ الْوَدِيعَةِ · ٩","segs":[["matn","فَصْلٌ: وَالْمُودَعُ أَمِينٌ لَا يَضْمَنُ إِلَّا إِنْ تَعَدَّى أَوْ فَرَّطَ أَوْ خَانَ وَيُقْبَلُ قَوْلُهُ بِيَمِينِهِ فِي عَدَمِ ذَلِكَ وَفِي أَنَّهَا تَلِفَتْ أَوْ أَنَّكَ أَذِنْتَ لِي فِي دَفْعِهَا لِفُلَانٍ وَفَعَلْتُ"]]},{"id":"da64_10","label":"بَابُ الْوَدِيعَةِ · ١٠","segs":[["matn","وَإِنِ ادَّعَى الرَّدَّ بَعْدَ مَطْلِهِ بِلَا عُذْرٍ أَوِ ادَّعَى وَرَثَتُهُ الرَّدَّ لَمْ يُقْبَلْ إِلَّا بِبَيِّنَةٍ وَكَذَا كُلُّ أَمِينٍ وَحَيْثُ أَخَّرَ رَدَّهَا بَعْدَ طَلَبٍ بِلَا عُذْرٍ وَلَمْ يَكُنْ لِحَمْلِهَا مُؤْنَةٌ ضَمِنَ وَإِنْ أُكْرِهَ عَلَى دَفْعِهَا لِغَيْرِ رَبِّهَا لَمْ يَضْمَنْ."]]},{"id":"da64_11","label":"بَابُ الْوَدِيعَةِ · ١١","segs":[["matn","وَإِنْ قَالَ لَهُ: عِنْدِي أَلْفٌ وَدِيعَةً ثُمَّ قَالَ: قَبَضَهَا أَوْ تَلِفَتْ قَبْلَ ذَلِكَ أَوْ ظَنَنْتُهَا بَاقِيَةً ثُمَّ عَلِمْتُ تَلَفَهَا صُدِّقَ بِيَمِينِهِ وَلَا ضَمَانَ وَإِنْ قَالَ: قَبَضْتُ مِنْهُ أَلْفًا وَدِيعَةً فَتَلِفَتْ فَقَالَ بَلْ غَصْبًا أَوْ عَارِيَّةً ضَمِنَ."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da65","title":"بَابُ إِحْيَاءِ الْمَوَاتِ","units":[{"id":"da65_1","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ١","segs":[["matn","وَهِيَ الْأَرْضُ الْخَرَابُ الدَّارِسَةُ الَّتِي لَمْ يَجْرِ عَلَيْهَا مِلْكٌ لِأَحَدٍ وَلَمْ يُوجَدْ فِيهَا أَثَرُ عِمَارَةٍ أَوْ وُجِدَ بِهَا أَثَرُ مِلْكٍ وَعِمَارَةٍ كَالْخِرَبِ الَّتِي ذَهَبَتْ أَنْهَارُهَا وَانْدَرَسَتْ آثَارُهَا وَلَمْ يُعْلَمْ لَهَا مَالِكٌ."]]},{"id":"da65_2","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٢","segs":[["matn","فَمَنْ أَحْيَا شَيْئًا مِنْ ذَلِكَ وَلَوْ كَانَ ذِمِّيًّا أَوْ بِلَا إِذْنِ الْإِمَامِ مَلَكَهُ بِمَا فِيهِ مِنْ مَعْدِنٍ جَامِدٍ كَذَهَبٍ وَفِضَّةٍ وَحَدِيدٍ وَكُحْلٍ وَلَا خَرَاجَ عَلَيْهِ إِلَّا إِنْ كَانَ ذِمِّيًّا لَا مَا فِيهِ مِنْ مَعْدِنٍ جَارٍ: كَنِفْطٍ وَقَارٍ."]]},{"id":"da65_3","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٣","segs":[["matn","وَمَنْ حَفَرَ بِئْرًا بِالسَّابِلَةِ لِيَرْتَفِقَ بِهَا كَالسَّفَّارَةِ لِشُرْبِهِمْ وَدَوَابِّهِمْ فَهُمْ أَحَقُّ بِمَائِهَا مَا أَقَامُوا وَبَعْدَ رَحِيلِهِمْ تَكُونُ سَبِيلًا لِلْمُسْلِمِينَ فَإِنْ عَادُوا كَانُوا أَحَقَّ بِهَا."]]},{"id":"da65_4","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٤","segs":[["matn","فَصْلٌ: وَيَحْصُلُ إِحْيَاءُ الْأَرْضِ الْمَوَاتِ إِمَّا بِحَائِطٍ مَنِيعٍ أَوْ إِجْرَاءِ مَاءٍ لَا تُزْرَعُ إِلَّا بِهِ أَوْ غَرْسِ شَجَرٍ أَوْ حَفْرِ بِئْرٍ فِيهَا."]]},{"id":"da65_5","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٥","segs":[["matn","فَإِنْ تَحَجَّرَ مَوَاتًا بِأَنْ أَدَارَ حَوْلَهُ أَحْجَارًا أَوْ حَفَرَ بِئْرًا لَمْ يَصِلْ مَاؤُهَا أَوْ سَقَى شَجَرًا مُبَاحًا كَزَيْتُونٍ وَنَحْوِهِ أَوْ أَصْلَحَهُ وَلَمْ."]]},{"id":"da65_6","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٦","segs":[["matn","يُرَكِّبْهُ لَمْ يَمْلِكْهُ لَكِنَّهُ أَحَقُّ بِهِ مِنْ غَيْرِهِ وَوَارِثُهُ بَعْدَهُ فَإِنْ أَعْطَاهُ لِأَحَدٍ كَانَ لَهُ."]]},{"id":"da65_7","label":"بَابُ إِحْيَاءِ الْمَوَاتِ · ٧","segs":[["matn","وَمَنْ سَبَقَ إِلَى مُبَاحٍ فَهُوَ لَهُ كَصَيْدٍ وَعَنْبَرٍ وَلُؤْلُؤٍ وَمَرْجَانٍ وَحَطَبٍ وَثَمَرٍ وَمَنْبُوذٍ رَغْبَةً عَنْهُ وَالْمِلْكُ مَقْصُورٌ فِيهِ عَلَى الْقَدْرِ الْمَأْخُوذِ."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da66","title":"بَابُ الْجُعَالَةِ","units":[{"id":"da66_1","label":"بَابُ الْجُعَالَةِ · ١","segs":[["matn","وَهِيَ جَعْلُ مَالٍ مَعْلُومٍ لِمَنْ يَعْمَلُ لَهُ عَمَلًا مُبَاحًا وَلَوْ مَجْهُولًا كَقَوْلِهِ: مَنْ رَدَّ لُقَطَتِي أَوْ بَنَى لِي هَذَا الْحَائِطَ أَوْ أَذَّنَ بِهَذَا الْمَسْجِدِ شَهْرًا فَلَهُ كَذَا."]]},{"id":"da66_2","label":"بَابُ الْجُعَالَةِ · ٢","segs":[["matn","فَمَنْ فَعَلَ الْعَمَلَ بَعْدَ أَنْ بَلَغَهُ الْجُعْلُ اسْتَحَقَّهُ كُلَّهُ وَإِنْ بَلَغَهُ فِي أَثْنَاءِ الْعَمَلِ اسْتَحَقَّ حِصَّةَ تَمَامِهِ وَبَعْدَ فَرَاغِ الْعَمَلِ لَمْ يَسْتَحِقَّ شَيْئًا."]]},{"id":"da66_3","label":"بَابُ الْجُعَالَةِ · ٣","segs":[["matn","وَإِنْ فَسَخَ الْجَاعِلُ قَبْلَ تَمَامِ الْعَمَلِ لَزِمَهُ أُجْرَةُ الْمِثْلِ وَإِنْ فَسَخَ الْعَامِلُ فَلَا شَيْءَ لَهُ. وَمَنْ عَمِلَ لِغَيْرِهِ عَمَلًا بِإِذْنِهِ مِنْ غَيْرِ تَقْدِيرِ أُجْرَةٍ وَجُعَالَةٍ فَلَهُ أُجْرَةُ الْمِثْلِ."]]},{"id":"da66_4","label":"بَابُ الْجُعَالَةِ · ٤","segs":[["matn","وَبِغَيْرِ إِذْنِهِ فَلَا شَيْءَ لَهُ إِلَّا فِي مَسْأَلَتَيْنِ: إِحْدَاهُمَا: أَنْ يُخَلِّصَ مَتَاعَ غَيْرِهِ مِنْ مَهْلَكَةٍ فَلَهُ أُجْرَةُ مِثْلِهِ."]]},{"id":"da66_5","label":"بَابُ الْجُعَالَةِ · ٥","segs":[["matn","الثَّانِيَةُ: أَنْ يَرُدَّ رَقِيقًا آبِقًا لِسَيِّدِهِ فَلَهُ مَا قَدَّرَهُ الشَّارِعُ وَهُوَ دِينَارٌ أَوِ اثْنَا عَشَرَ دِرْهَمًا."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da67","title":"بَابُ اللُّقَطَةِ","units":[{"id":"da67_1","label":"بَابُ اللُّقَطَةِ · ١","segs":[["matn","وَهِيَ ثَلَاثَةُ أَقْسَامٍ: أَحَدُهَا: مَا لَا تَتْبَعُهُ هِمَّةُ أَوْسَاطِ النَّاسِ: كَسَوْطٍ وَرَغِيفٍ وَنَحْوِهِمَا فَهَذَا يُمْلَكُ بِالِالْتِقَاطِ وَلَا يَلْزَمُ تَعْرِيفُهُ لَكِنْ إِنْ وَجَدَ رَبَّهُ دَفَعَهُ لَهُ إِنْ كَانَ بَاقِيًا وَإِلَّا لَمْ يَلْزَمْهُ شَيْءٌ."]]},{"id":"da67_2","label":"بَابُ اللُّقَطَةِ · ٢","segs":[["matn","وَمَنْ تَرَكَ دَابَّتَهُ تَرْكَ إِيَاسٍ بِمَهْلَكَةٍ أَوْ فَلَاةٍ لِانْقِطَاعِهَا أَوْ لِعَجْزِهِ عَنْ عَلْفِهَا مَلَكَهَا آخِذُهَا وَكَذَا مَا يُلْقَى فِي الْبَحْرِ خَوْفًا مِنَ الْغَرَقِ."]]},{"id":"da67_3","label":"بَابُ اللُّقَطَةِ · ٣","segs":[["matn","الثَّانِي: الضَّوَالُّ الَّتِي تَمْتَنِعُ مِنْ صِغَارِ السِّبَاعِ: كَالْإِبِلِ وَالْبَقَرِ وَالْخَيْلِ وَالْبِغَالِ وَالْحَمِيرِ وَالظِّبَاءِ فَيَحْرُمُ الْتِقَاطُهَا وَتُضْمَنُ كَالْغَصْبِ وَلَا يَزُولُ الضَّمَانُ إِلَّا بِدَفْعِهَا لِلْإِمَامِ أَوْ نَائِبِهِ أَوْ بِرَدِّهَا إِلَى مَكَانِهَا بِإِذْنِهِ"]]},{"id":"da67_4","label":"بَابُ اللُّقَطَةِ · ٤","segs":[["matn","وَمَنْ كَتَمَ شَيْئًا مِنْهَا فَتَلِفَ لَزِمَهُ قِيمَتُهُ مَرَّتَيْنِ وَإِنْ تَبِعَ شَيْءٌ مِنْهَا دَوَابَّهُ فَطَرَدَهُ أَوْ دَخَلَ دَارَهُ فَأَخْرَجَهُ لَمْ يَضْمَنْهُ حَيْثُ لَمْ يَأْخُذْهُ."]]},{"id":"da67_5","label":"بَابُ اللُّقَطَةِ · ٥","segs":[["matn","الثَّالِثُ: كَالذَّهَبِ وَالْفِضَّةِ وَالْمَتَاعِ وَمَا لَا يَمْتَنِعُ مِنْ صِغَارِ السِّبَاعِ كَالْغَنَمِ وَالْفُصْلَانِ وَالْعَجَاجِيلِ وَالْإِوَزِّ وَالدَّجَاجِ فَهَذِهِ يَجُوزُ الْتِقَاطُهَا لِمَنْ وَثِقَ مِنْ نَفْسِهِ الْأَمَانَةَ وَالْقُدْرَةَ عَلَى تَعْرِيفِهَا وَالْأَفْضَلُ مَعَ ذَلِكَ تَرْكُهَا فَإِنْ أَخَذَهَا ثُمَّ رَدَّهَا إِلَى مَوْضِعِهَا ضَمِنَ."]]},{"id":"da67_6","label":"بَابُ اللُّقَطَةِ · ٦","segs":[["matn","فَصْلٌ: وَهَذَا الْقِسْمُ الْأَخِيرُ ثَلَاثَةُ أَنْوَاعٍ: أَحَدُهَا: مَا الْتَقَطَهُ مِنْ حَيَوَانٍ فَيَلْزَمُهُ خَيْرُ ثَلَاثَةِ أُمُورٍ: أَكْلُهُ بِقِيمَتِهِ أَوْ بَيْعُهُ وَحِفْظُ ثَمَنِهِ أَوْ حِفْظُهُ وَيُنْفِقُ عَلَيْهِ مِنْ مَالِهِ وَلَهُ الرُّجُوعُ بِمَا أَنْفَقَ إِنْ نَوَاهُ فَإِنِ اسْتَوَتِ الثَّلَاثَةُ خُيِّرَ."]]},{"id":"da67_7","label":"بَابُ اللُّقَطَةِ · ٧","segs":[["matn","الثَّانِي: مَا يُخْشَى فَسَادُهُ فَيَلْزَمُهُ فِعْلُ الْأَصْلَحِ مِنْ بَيْعِهِ أَوْ أَكْلِهِ بِقِيمَتِهِ أَوْ تَجْفِيفِ مَا يُجَفَّفُ فَإِنِ اسْتَوَتِ الثَّلَاثَةُ خُيِّرَ."]]},{"id":"da67_8","label":"بَابُ اللُّقَطَةِ · ٨","segs":[["matn","الثَّالِثُ: بَاقِي الْمَالِ وَيَلْزَمُهُ التَّعْرِيفُ فِي الْجَمِيعِ فَوْرًا نَهَارًا أَوَّلَ كُلِّ يَوْمٍ مُدَّةَ أُسْبُوعٍ ثُمَّ عَادَةً مُدَّةَ حَوْلٍ."]]},{"id":"da67_9","label":"بَابُ اللُّقَطَةِ · ٩","segs":[["matn","وَتَعْرِيفُهَا: بِأَنْ يُنَادِيَ عَلَيْهَا فِي الْأَسْوَاقِ وَأَبْوَابِ الْمَسَاجِدِ مَنْ ضَاعَ مِنْهُ شَيْءٌ أَوْ نَفَقَةٌ."]]},{"id":"da67_10","label":"بَابُ اللُّقَطَةِ · ١٠","segs":[["matn","وَأُجْرَةُ الْمُنَادِي عَلَى الْمُلْتَقِطِ فَإِذَا عَرَّفَهَا حَوْلًا وَلَمْ تُعْرَفْ دَخَلَتْ فِي مِلْكِهِ قَهْرًا عَلَيْهِ فَيَتَصَرَّفُ فِيهَا بِمَا شَاءَ بِشَرْطِ ضَمَانِهَا."]]},{"id":"da67_11","label":"بَابُ اللُّقَطَةِ · ١١","segs":[["matn","فَصْلٌ: وَيَحْرُمُ تَصَرُّفُهُ فِيهَا حَتَّى يَعْرِفَ وِعَاءَهَا وَوِكَاءَهَا وَهُوَ مَا شُدَّ بِهِ الْوِعَاءُ. وَعِفَاصَهَا: وَهُوَ: صِفَةُ الشَّدِّ وَيَعْرِفَ قَدْرَهَا وَجِنْسَهَا وَصِفَتَهَا."]]},{"id":"da67_12","label":"بَابُ اللُّقَطَةِ · ١٢","segs":[["matn","وَمَتَى وَصَفَهَا طَالِبُهَا يَوْمًا مِنَ الدَّهْرِ لَزِمَ دَفْعُهَا إِلَيْهِ بِنَمَائِهَا الْمُتَّصِلِ وَأَمَّا الْمُنْفَصِلُ بَعْدَ حَوْلِ التَّعْرِيفِ فَلِوَاجِدِهَا."]]},{"id":"da67_13","label":"بَابُ اللُّقَطَةِ · ١٣","segs":[["matn","وَإِنْ تَلِفَتْ أَوْ نَقَصَتْ فِي حَوْلِ التَّعْرِيفِ وَلَمْ يُفَرِّطْ لَمْ يَضْمَنْ وَبَعْدَ الْحَوْلِ يَضْمَنُ مُطْلَقًا."]]},{"id":"da67_14","label":"بَابُ اللُّقَطَةِ · ١٤","segs":[["matn","وَإِنْ أَدْرَكَهَا رَبُّهَا بَعْدَ الْحَوْلِ مَبِيعَةً أَوْ مَوْهُوبَةً لَمْ يَكُنْ لَهُ إِلَّا الْبَدَلُ وَمَنْ وَجَدَ فِي حَيَوَانٍ نَقْدًا أَوْ دُرَّةً فَلُقَطَةٌ لِوَاجِدِهِ يَلْزَمُهُ تَعْرِيفُهُ."]]},{"id":"da67_15","label":"بَابُ اللُّقَطَةِ · ١٥","segs":[["matn","وَمَنِ اسْتَيْقَظَ فَوَجَدَ فِي ثَوْبِهِ مَالًا لَا يَدْرِي مَنْ صَرَّهُ فَهُوَ لَهُ وَلَا يَبْرَأُ مَنْ أَخَذَ مِنْ نَائِمٍ شَيْئًا إِلَّا بِتَسْلِيمِهِ لَهُ بَعْدَ انْتِبَاهِهِ."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da68","title":"بَابُ اللَّقِيطِ","units":[{"id":"da68_1","label":"بَابُ اللَّقِيطِ · ١","segs":[["matn","وَهُوَ طِفْلٌ يُوجَدُ لَا يُعْرَفُ نَسَبُهُ وَلَا رِقُّهُ وَالْتِقَاطُهُ وَالْإِنْفَاقُ عَلَيْهِ فَرْضُ كِفَايَةٍ وَيُحْكَمُ بِإِسْلَامِهِ وَحُرِّيَّتِهِ وَيُنْفَقُ عَلَيْهِ مِمَّا مَعَهُ إِنْ كَانَ فَإِنْ لَمْ يَكُنْ"]]},{"id":"da68_2","label":"بَابُ اللَّقِيطِ · ٢","segs":[["matn","فَمِنْ بَيْتِ الْمَالِ فَإِنْ تَعَذَّرَ اقْتَرَضَ عَلَيْهِ الْحَاكِمُ فَإِنْ تَعَذَّرَ فَعَلَى مَنْ عَلِمَ بِحَالِهِ وَالْأَحَقُّ بِحَضَانَتِهِ وَاجِدُهُ إِنْ كَانَ حُرًّا مُكَلَّفًا رَشِيدًا أَمِينًا عَدْلًا وَلَوْ ظَاهِرًا."]]},{"id":"da68_3","label":"بَابُ اللَّقِيطِ · ٣","segs":[["matn","فَصْلٌ: وَمِيرَاثُ اللَّقِيطِ وَدِيَتُهُ إِنْ قُتِلَ لِبَيْتِ الْمَالِ وَإِنِ ادَّعَاهُ مَنْ يُمْكِنُ كَوْنُهُ مِنْهُ مِنْ ذَكَرٍ أَوْ أُنْثَى أُلْحِقَ بِهِ وَلَوْ مَيِّتًا وَثَبَتَ نَسَبُهُ وَإِرْثُهُ."]]},{"id":"da68_4","label":"بَابُ اللَّقِيطِ · ٤","segs":[["matn","وَإِنِ ادَّعَاهُ اثْنَانِ فَأَكْثَرُ مَعًا قُدِّمَ مَنْ لَهُ بَيِّنَةٌ فَإِنْ لَمْ تَكُنْ عُرِضَ عَلَى الْقَافَةِ فَإِنْ أَلْحَقَتْهُ بِوَاحِدٍ لَحِقَهُ وَإِنْ أَلْحَقَتْهُ بِالْجَمِيعِ لَحِقَهُمْ وَإِنْ أَشْكَلَ أَمْرُهُ ضَاعَ نَسَبُهُ."]]},{"id":"da68_5","label":"بَابُ اللَّقِيطِ · ٥","segs":[["matn","وَيَكْفِي قَائِفٌ وَاحِدٌ وَهُوَ كَالْحَاكِمِ فَيَكْفِي مُجَرَّدُ خَبَرِهِ بِشَرْطِ كَوْنِهِ مُكَلَّفًا ذَكَرًا عَدْلًا حُرًّا مُجَرَّبًا فِي الْإِصَابَةِ."]]}],"group":"كِتَابُ الْغَصْبِ"},{"id":"da69","title":"كِتَابُ الْوَقْفِ","units":[{"id":"da69_1","label":"كِتَابُ الْوَقْفِ · ١","segs":[["matn","يَحْصُلُ بِأَحَدِ أَمْرَيْنِ: بِالْفِعْلِ مَعَ دَلِيلٍ يَدُلُّ عَلَيْهِ: كَأَنْ يَبْنِيَ بُنْيَانًا عَلَى هَيْئَةِ الْمَسْجِدِ وَيَأْذَنَ إِذْنًا عَامًّا بِالصَّلَاةِ فِيهِ أَوْ يَجْعَلَ أَرْضَهُ مَقْبَرَةً وَيَأْذَنَ إِذْنًا عَامًّا بِالدَّفْنِ فِيهَا."]]},{"id":"da69_2","label":"كِتَابُ الْوَقْفِ · ٢","segs":[["matn","وَبِالْقَوْلِ وَلَهُ صَرِيحٌ وَكِنَايَةٌ. فَصَرِيحُهُ: وَقَفْتُ وَحَبَّسْتُ وَسَبَّلْتُ. وَكِنَايَتُهُ: تَصَدَّقْتُ وَحَرَّمْتُ وَأَبَّدْتُ فَلَا بُدَّ فِيهَا مِنْ نِيَّةِ الْوَقْفِ مَا لَمْ يَقُلْ: عَلَى قَبِيلَةِ كَذَا أَوْ طَائِفَةِ كَذَا"]]},{"id":"da69_3","label":"كِتَابُ الْوَقْفِ · ٣","segs":[["matn","فَصْلٌ: وَشُرُوطُ الْوَقْفِ سَبْعَةٌ: أَحَدُهَا: كَوْنُهُ مِنْ مَالِكٍ جَائِزِ التَّصَرُّفِ أَوْ مِمَّنْ يَقُومُ مَقَامَهُ."]]},{"id":"da69_4","label":"كِتَابُ الْوَقْفِ · ٤","segs":[["matn","الثَّانِي: كَوْنُ الْمَوْقُوفِ عَيْنًا يَصِحُّ بَيْعُهَا وَيُنْتَفَعُ بِهَا نَفْعًا مُبَاحًا مَعَ بَقَائِهَا فَلَا يَصِحُّ وَقْفُ مَطْعُومٍ وَمَشْرُوبٍ غَيْرِ الْمَاءِ وَلَا وَقْفُ دُهْنٍ وَشَمْعٍ وَأَثْمَانٍ وَقَنَادِيلِ نَقْدٍ عَلَى الْمَسَاجِدِ وَلَا عَلَى غَيْرِهَا."]]},{"id":"da69_5","label":"كِتَابُ الْوَقْفِ · ٥","segs":[["matn","الثَّالِثُ: كَوْنُهُ عَلَى جِهَةِ بِرٍّ وَقُرْبَةٍ: كَالْمَسَاكِينِ وَالْمَسَاجِدِ وَالْقَنَاطِرِ وَالْأَقَارِبِ فَلَا يَصِحُّ عَلَى الْكَنَائِسِ وَلَا عَلَى الْيَهُودِ وَالنَّصَارَى وَلَا عَلَى جِنْسِ الْأَغْنِيَاءِ أَوِ الْفُسَّاقِ أَمَّا لَوْ وَقَفَ عَلَى ذِمِّيٍّ أَوْ فَاسِقٍ أَوْ غَنِيٍّ مُعَيَّنٍ صَحَّ."]]},{"id":"da69_6","label":"كِتَابُ الْوَقْفِ · ٦","segs":[["matn","الرَّابِعُ: كَوْنُهُ عَلَى مُعَيَّنٍ غَيْرَ نَفْسِهِ يَصِحُّ أَنْ يَمْلِكَ فَلَا يَصِحُّ الْوَقْفُ عَلَى مَجْهُولٍ كَرَجُلٍ وَمَسْجِدٍ أَوْ عَلَى أَحَدِ هَذَيْنِ"]]},{"id":"da69_7","label":"كِتَابُ الْوَقْفِ · ٧","segs":[["matn","وَلَا عَلَى نَفْسِهِ وَلَا عَلَى مَنْ لَا يَمْلِكُ كَالرَّقِيقِ وَلَوْ مُكَاتَبًا وَالْمَلَائِكَةِ وَالْجِنِّ وَالْبَهَائِمِ وَالْأَمْوَاتِ وَلَا عَلَى الْحَمْلِ اسْتِقْلَالًا بَلْ تَبَعًا."]]},{"id":"da69_8","label":"كِتَابُ الْوَقْفِ · ٨","segs":[["matn","الْخَامِسُ: كَوْنُ الْوَقْفِ مُنَجَّزًا فَلَا يَصِحُّ تَعْلِيقُهُ إِلَّا بِمَوْتِهِ فَيَلْزَمُ مِنْ حِينِ الْوَقْفِ إِنْ خَرَجَ مِنَ الثُّلُثِ."]]},{"id":"da69_9","label":"كِتَابُ الْوَقْفِ · ٩","segs":[["matn","السَّادِسُ: أَنْ لَا يَشْتَرِطَ فِيهِ مَا يُنَافِيهِ كَقَوْلِهِ: وَقَفْتُ كَذَا عَلَى أَنْ أَبِيعَهُ أَوْ أَهَبَهُ مَتَى شِئْتُ أَوْ بِشَرْطِ الْخِيَارِ لِي أَوْ بِشَرْطِ أَنْ أُحَوِّلَهُ مِنْ جِهَةٍ إِلَى جِهَةٍ."]]},{"id":"da69_10","label":"كِتَابُ الْوَقْفِ · ١٠","segs":[["matn","السَّابِعُ: أَنْ يَقِفَهُ عَلَى التَّأْبِيدِ. فَلَا يَصِحُّ: وَقَفْتُهُ شَهْرًا أَوْ إِلَى سَنَةٍ وَنَحْوِهَا. وَلَا يُشْتَرَطُ تَعْيِينُ الْجِهَةِ فَلَوْ قَالَ: وَقَفْتُ كَذَا وَسَكَتَ صَحَّ وَكَانَ لِوَرَثَتِهِ مِنَ النَّسَبِ عَلَى قَدْرِ إِرْثِهِمْ."]]},{"id":"da69_11","label":"كِتَابُ الْوَقْفِ · ١١","segs":[["matn","فَصْلٌ: وَيَلْزَمُ الْوَقْفُ بِمُجَرَّدِهِ وَيَمْلِكُهُ الْمَوْقُوفُ عَلَيْهِ فَيَنْظُرُ فِيهِ هُوَ أَوْ وَلِيُّهُ مَا لَمْ يَشْرُطِ الْوَاقِفُ نَاظِرًا فَيَتَعَيَّنُ وَيَتَعَيَّنُ صَرْفُهُ إِلَى الْجِهَةِ الَّتِي"]]},{"id":"da69_12","label":"كِتَابُ الْوَقْفِ · ١٢","segs":[["matn","وُقِفَ عَلَيْهَا فِي الْحَالِ مَا لَمْ يَسْتَثْنِ الْوَاقِفُ مَنْفَعَتَهُ أَوْ غَلَّتَهُ لَهُ أَوْ لِوَلَدِهِ أَوْ لِصَدِيقِهِ مُدَّةَ حَيَاتِهِ أَوْ مُدَّةً مَعْلُومَةً فَيُعْمَلُ بِذَلِكَ."]]},{"id":"da69_13","label":"كِتَابُ الْوَقْفِ · ١٣","segs":[["matn","وَحَيْثُ انْقَطَعَتِ الْجِهَةُ وَالْوَاقِفُ حَيٌّ رَجَعَ إِلَيْهِ وَقْفًا. وَمَنْ وَقَفَ عَلَى الْفُقَرَاءِ فَافْتَقَرَ تَنَاوَلَ مِنْهُ."]]},{"id":"da69_14","label":"كِتَابُ الْوَقْفِ · ١٤","segs":[["matn","وَلَا يَصِحُّ عِتْقُ الرَّقِيقِ الْمَوْقُوفِ بِحَالٍ لَكِنْ لَوْ وَطِئَ الْأَمَةَ الْمَوْقُوفَةَ عَلَيْهِ حَرُمَ فَإِنْ حَمَلَتْ صَارَتْ أُمَّ وَلَدٍ تَعْتِقُ بِمَوْتِهِ وَتَجِبُ قِيمَتُهَا فِي تَرِكَتِهِ لِيَشْتَرِيَ بِهَا مِثْلَهَا."]]},{"id":"da69_15","label":"كِتَابُ الْوَقْفِ · ١٥","segs":[["matn","فَصْلٌ: وَيُرْجَعُ فِي مَصْرِفِ الْوَقْفِ إِلَى شَرْطِ الْوَاقِفِ فَإِنْ جُهِلَ عُمِلَ بِالْعَادَةِ الْجَارِيَةِ فَإِنْ لَمْ يَكُنْ فَبِالْعُرْفِ فَإِنْ لَمْ يَكُنْ فَالتَّسَاوِي بَيْنَ الْمُسْتَحِقِّينَ."]]},{"id":"da69_16","label":"كِتَابُ الْوَقْفِ · ١٦","segs":[["matn","وَيُرْجَعُ إِلَى شَرْطِهِ فِي التَّرْتِيبِ بَيْنَ الْبُطُونِ أَوِ الِاشْتِرَاكِ وَفِي إِيجَارِ الْوَقْفِ أَوْ عَدَمِهِ وَفِي قَدْرِ مُدَّةِ الْإِيجَارِ فَلَا يُزَادُ عَلَى مَا قُدِّرَ."]]},{"id":"da69_17","label":"كِتَابُ الْوَقْفِ · ١٧","segs":[["matn","وَنَصُّ الْوَاقِفِ كَنَصِّ الشَّارِعِ يَجِبُ الْعَمَلُ بِجَمِيعِ مَا شَرَطَهُ مَا لَمْ يُفْضِ إِلَى الْإِخْلَالِ بِالْمَقْصُودِ فَيُعْمَلُ بِهِ فِيمَا إِذَا شَرَطَ أَنْ لَا يَنْزِلَ فِي الْوَقْفِ فَاسِقٌ وَلَا شِرِّيرٌ وَلَا ذُو جَاهٍ."]]},{"id":"da69_18","label":"كِتَابُ الْوَقْفِ · ١٨","segs":[["matn","وَإِنْ خَصَّصَ مَقْبَرَةً أَوْ مَدْرَسَةً أَوْ إِمَامَتَهَا بِأَهْلِ مَذْهَبٍ أَوْ بَلَدٍ أَوْ قَبِيلَةٍ تَخَصَّصَتْ لَا الْمُصَلِّينَ بِهَا وَلَا إِنْ شَرَطَ عَدَمَ اسْتِحْقَاقِ مَنِ ارْتَكَبَ طَرِيقَ الصَّلَاحِ."]]},{"id":"da69_19","label":"كِتَابُ الْوَقْفِ · ١٩","segs":[["matn","فَصْلٌ: وَيُرْجَعُ فِي شَرْطِهِ إِلَى النَّاظِرِ. وَيُشْتَرَطُ فِي النَّاظِرِ خَمْسَةُ أَشْيَاءَ: الْإِسْلَامُ وَالتَّكْلِيفُ وَالْكِفَايَةُ لِلتَّصَرُّفِ وَالْخِبْرَةُ بِهِ وَالْقُوَّةُ عَلَيْهِ فَإِنْ كَانَ ضَعِيفًا ضُمَّ إِلَيْهِ قَوِيٌّ أَمِينٌ."]]},{"id":"da69_20","label":"كِتَابُ الْوَقْفِ · ٢٠","segs":[["matn","وَلَا تُشْتَرَطُ الذُّكُورَةُ وَلَا الْعَدَالَةُ حَيْثُ كَانَ بِجَعْلِ الْوَاقِفِ لَهُ فَإِنْ كَانَ مِنْ غَيْرِهِ فَلَا بُدَّ مِنَ الْعَدَالَةِ."]]},{"id":"da69_21","label":"كِتَابُ الْوَقْفِ · ٢١","segs":[["matn","فَإِنْ لَمْ يَشْرِطِ الْوَاقِفُ نَاظِرًا فَالنَّظَرُ لِلْمَوْقُوفِ عَلَيْهِ مُطْلَقًا حَيْثُ كَانَ مَحْصُورًا وَإِلَّا فَلِلْحَاكِمِ. وَلَا نَظَرَ لِحَاكِمٍ مَعَ نَاظِرٍ خَاصٍّ لَكِنْ لَهُ أَنْ يَعْتَرِضَ عَلَيْهِ إِنْ فَعَلَ مَا لَا يَسُوغُ."]]},{"id":"da69_22","label":"كِتَابُ الْوَقْفِ · ٢٢","segs":[["matn","وَوَظِيفَةُ النَّاظِرِ: حِفْظُ الْوَقْفِ وَعِمَارَتُهُ وَإِيجَارُهُ وَزَرْعُهُ وَالْمُخَاصَمَةُ فِيهِ وَتَحْصِيلُ رَيْعِهِ وَالِاجْتِهَادُ فِي تَنْمِيَتِهِ وَصَرْفُ الرَّيْعِ فِي جِهَاتِهِ مِنْ عِمَارَةٍ وَإِصْلَاحٍ وَإِعْطَاءِ الْمُسْتَحِقِّينَ. وَإِنْ آجَرَهُ بِأَنْقَصَ صَحَّ وَضَمِنَ النَّقْصَ."]]},{"id":"da69_23","label":"كِتَابُ الْوَقْفِ · ٢٣","segs":[["matn","وَلَهُ الْأَكْلُ بِالْمَعْرُوفِ وَلَوْ لَمْ يَكُنْ مُحْتَاجًا وَلَهُ التَّقْرِيرُ فِي وَظَائِفِهِ."]]},{"id":"da69_24","label":"كِتَابُ الْوَقْفِ · ٢٤","segs":[["matn","وَمَنْ قُرِّرَ فِي وَظِيفَةٍ عَلَى وَفْقِ الشَّرْعِ حَرُمَ إِخْرَاجُهُ مِنْهَا بِلَا مُوجِبٍ شَرْعِيٍّ وَمَنْ نَزَلَ عَنْ وَظِيفَةٍ بِيَدِهِ لِمَنْ هُوَ أَهْلٌ لَهَا صَحَّ وَكَانَ أَحَقَّ بِهَا."]]},{"id":"da69_25","label":"كِتَابُ الْوَقْفِ · ٢٥","segs":[["matn","وَمَا يَأْخُذُهُ الْفُقَهَاءُ مِنَ الْوَقْفِ فَكَالرِّزْقِ مِنْ بَيْتِ الْمَالِ لَا كَجُعْلٍ وَلَا كَأُجْرَةٍ."]]},{"id":"da69_26","label":"كِتَابُ الْوَقْفِ · ٢٦","segs":[["matn","فَصْلٌ: وَمَنْ وَقَفَ عَلَى وَلَدِهِ وَوَلَدِ غَيْرِهِ دَخَلَ الْمَوْجُودُونَ فَقَطْ مِنْ ذُكُورٍ وَإِنَاثٍ بِالسَّوِيَّةِ مِنْ غَيْرِ تَفْضِيلٍ وَدَخَلَ أَوْلَادُ الذُّكُورِ خَاصَّةً."]]},{"id":"da69_27","label":"كِتَابُ الْوَقْفِ · ٢٧","segs":[["matn","وَإِنْ قَالَ: عَلَى وَلَدِي دَخَلَ أَوْلَادُهُ الْمَوْجُودُونَ وَمَنْ يُولَدُ لَهُمْ لَا الْحَادِثُونَ وَعَلَى وَلَدِي وَمَنْ يُولَدُ لِي دَخَلَ الْمَوْجُودُونَ وَالْحَادِثُونَ تَبَعًا."]]},{"id":"da69_28","label":"كِتَابُ الْوَقْفِ · ٢٨","segs":[["matn","وَمَنْ وَقَفَ عَلَى عَقِبِهِ أَوْ نَسْلِهِ أَوْ وَلَدِ وَلَدِهِ أَوْ ذُرِّيَّتِهِ دَخَلَ الذُّكُورُ وَالْإِنَاثُ لَا أَوْلَادُ الْإِنَاثِ إِلَّا بِقَرِينَةٍ. وَمَنْ وَقَفَ عَلَى بَنِيهِ أَوْ بَنِي فُلَانٍ فَلِلذُّكُورِ خَاصَّةً."]]},{"id":"da69_29","label":"كِتَابُ الْوَقْفِ · ٢٩","segs":[["matn","وَيُكْرَهُ هُنَا أَنْ يُفَضِّلَ بَعْضَ أَوْلَادِهِ عَلَى بَعْضٍ لِغَيْرِ سَبَبٍ وَالسُّنَّةُ أَنْ لَا يُزَادَ ذَكَرٌ عَلَى أُنْثَى فَإِنْ كَانَ لِبَعْضِهِمْ عِيَالٌ أَوْ بِهِ حَاجَةٌ أَوْ عَاجِزٌ عَنِ التَّكَسُّبِ أَوْ خَصَّ الْمُشْتَغِلِينَ بِالْعِلْمِ أَوْ خَصَّ ذَا الدِّينِ وَالصَّلَاحِ فَلَا بَأْسَ."]]},{"id":"da69_30","label":"كِتَابُ الْوَقْفِ · ٣٠","segs":[["matn","فَصْلٌ: وَالْوَقْفُ عَقْدٌ لَازِمٌ لَا يُفْسَخُ بِإِقَالَةٍ وَلَا غَيْرِهَا وَلَا يُوهَبُ وَلَا يُرْهَنُ وَلَا يُورَثُ وَلَا يُبَاعُ إِلَّا أَنْ تَتَعَطَّلَ مَنَافِعُهُ بِخَرَابٍ أَوْ غَيْرِهِ وَلَمْ يُوجَدْ مَا يُعَمَّرُ بِهِ"]]},{"id":"da69_31","label":"كِتَابُ الْوَقْفِ · ٣١","segs":[["matn","فَيُبَاعُ وَيُصْرَفُ ثَمَنُهُ فِي مِثْلِهِ أَوْ بَعْضِ مِثْلِهِ وَبِمُجَرَّدِ شِرَاءِ الْبَدَلِ يَصِيرُ وَقْفًا وَكَذَا حُكْمُ الْمَسْجِدِ لَوْ ضَاقَ عَلَى أَهْلِهِ أَوْ خَرِبَتْ مَحِلَّتُهُ أَوِ اسْتُقْذِرَ مَوْضِعُهُ."]]},{"id":"da69_32","label":"كِتَابُ الْوَقْفِ · ٣٢","segs":[["matn","وَيَجُوزُ نَقْلُ آلَتِهِ وَحِجَارَتِهِ لِمَسْجِدٍ آخَرَ احْتَاجَ إِلَيْهَا وَذَلِكَ أَوْلَى مِنْ بَيْعِهِ وَيَجُوزُ نَقْضُ مَنَارَةِ الْمَسْجِدِ وَجَعْلُهَا فِي حَائِطِهِ لِتَحْصِينِهِ وَمَنْ وَقَفَ عَلَى ثَغْرٍ فَاخْتَلَّ صُرِفَ فِي ثَغْرٍ مِثْلِهِ وَعَلَى قِيَاسِهِ مَسْجِدٌ وَرِبَاطٌ وَنَحْوُهُمَا."]]},{"id":"da69_33","label":"كِتَابُ الْوَقْفِ · ٣٣","segs":[["matn","وَيَحْرُمُ: حَفْرُ الْبِئْرِ وَغَرْسُ الشَّجَرِ بِالْمَسَاجِدِ وَلَعَلَّ هَذَا حَيْثُ لَمْ يَكُنْ فِيهِ مَصْلَحَةٌ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"da70","title":"بَابُ الْهِبَةِ","units":[{"id":"da70_1","label":"بَابُ الْهِبَةِ · ١","segs":[["matn","وَهِيَ التَّبَرُّعُ بِالْمَالِ فِي حَالِ الْحَيَاةِ. وَهِيَ مُسْتَحَبَّةٌ مُنْعَقِدَةٌ بِكُلِّ قَوْلٍ أَوْ فِعْلٍ يَدُلُّ عَلَيْهَا."]]},{"id":"da70_2","label":"بَابُ الْهِبَةِ · ٢","segs":[["matn","وَشُرُوطُهَا ثَمَانِيَةٌ: كَوْنُهَا مِنْ جَائِزِ التَّصَرُّفِ وَكَوْنُهُ مُخْتَارًا غَيْرَ هَازِلٍ وَكَوْنُ الْمَوْهُوبِ يَصِحُّ بَيْعُهُ وَكَوْنُ الْمَوْهُوبِ لَهُ يَصِحُّ تَمَلُّكُهُ وَكَوْنُهُ يَقْبَلُ مَا وُهِبَ لَهُ بِقَوْلٍ أَوْ"]]},{"id":"da70_3","label":"بَابُ الْهِبَةِ · ٣","segs":[["matn","فِعْلٍ يَدُلُّ عَلَيْهِ قَبْلَ تَشَاغُلِهِمَا بِمَا يَقْطَعُ الْبَيْعَ عُرْفًا وَكَوْنُ الْهِبَةِ مُنَجَّزَةً وَكَوْنُهَا غَيْرَ مُؤَقَّتَةٍ لَكِنْ لَوْ وُقِّتَتْ بِعُمُرِ أَحَدِهِمَا لَزِمَتْ وَلَغَا التَّوْقِيتُ وَكَوْنُهَا بِغَيْرِ عِوَضٍ فَإِنْ كَانَتْ بِعِوَضٍ مَعْلُومٍ فَبَيْعٌ وَبِعِوَضٍ مَجْهُولٍ فَبَاطِلَةٌ."]]},{"id":"da70_4","label":"بَابُ الْهِبَةِ · ٤","segs":[["matn","وَمَنْ أَهْدَى لِيُهْدَى لَهُ أَكْثَرُ فَلَا بَأْسَ. وَيُكْرَهُ رَدُّ الْهِبَةِ وَإِنْ قَلَّتْ بَلِ السُّنَّةُ أَنْ يُكَافِئَ أَوْ يَدْعُوَ وَإِنْ عَلِمَ أَنَّهُ أَهْدَى حَيَاءً وَجَبَ الرَّدُّ."]]},{"id":"da70_5","label":"بَابُ الْهِبَةِ · ٥","segs":[["matn","فَصْلٌ: وَتُمْلَكُ الْهِبَةُ بِالْعَقْدِ. وَتَلْزَمُ بِالْقَبْضِ بِشَرْطِ أَنْ يَكُونَ الْقَبْضُ بِإِذْنِ الْوَاهِبِ فَقَبْضُ مَا وُهِبَ بِكَيْلٍ أَوْ وَزْنٍ أَوْ عَدٍّ أَوْ ذَرْعٍ بِذَلِكَ وَقَبْضُ الصُّبْرَةِ وَمَا يُنْقَلُ بِالنَّقْلِ وَقَبْضُ مَا يُتَنَاوَلُ بِالتَّنَاوُلِ وَقَبْضُ غَيْرِ ذَلِكَ بِالتَّخْلِيَةِ وَيَقْبَلُ وَيَقْبِضُ لِصَغِيرٍ وَمَجْنُونٍ وَلِيُّهُمَا."]]},{"id":"da70_6","label":"بَابُ الْهِبَةِ · ٦","segs":[["matn","وَيَصِحُّ أَنْ يَهَبَ شَيْئًا وَيَسْتَثْنِيَ نَفْعَهُ مُدَّةً مَعْلُومَةً وَأَنْ يَهَبَ حَامِلًا وَيَسْتَثْنِيَ حَمْلَهَا. وَإِنْ وَهَبَهُ وَشَرَطَ الرُّجُوعَ مَتَى شَاءَ لَزِمَتْ وَلَغَا الشَّرْطُ."]]},{"id":"da70_7","label":"بَابُ الْهِبَةِ · ٧","segs":[["matn","وَإِنْ وَهَبَ دَيْنَهُ لِمَدِينِهِ أَوْ أَبْرَأَهُ مِنْهُ أَوْ تَرَكَهُ لَهُ صَحَّ وَلَزِمَ بِمُجَرَّدِهِ وَلَوْ قَبْلَ حُلُولِهِ. وَتَصِحُّ الْبَرَاءَةُ وَلَوْ مَجْهُولًا."]]},{"id":"da70_8","label":"بَابُ الْهِبَةِ · ٨","segs":[["matn","وَلَا تَصِحُّ هِبَةُ الدَّيْنِ لِغَيْرِ مَنْ هُوَ عَلَيْهِ إِلَّا إِنْ كَانَ ضَامِنًا."]]},{"id":"da70_9","label":"بَابُ الْهِبَةِ · ٩","segs":[["matn","فَصْلٌ: وَلِكُلِّ وَاهِبٍ أَنْ يَرْجِعَ فِي هِبَتِهِ قَبْلَ إِقْبَاضِهَا مَعَ الْكَرَاهَةِ."]]},{"id":"da70_10","label":"بَابُ الْهِبَةِ · ١٠","segs":[["matn","وَلَا يَصِحُّ الرُّجُوعُ إِلَّا بِالْقَوْلِ وَبَعْدَ إِقْبَاضِهَا يَحْرُمُ وَلَا يَصِحُّ مَا لَمْ يَكُنْ أَبًا فَلَهُ أَنْ يَرْجِعَ بِشُرُوطٍ أَرْبَعَةٍ: أَنْ لَا يُسْقِطَ حَقَّهُ مِنَ الرُّجُوعِ وَأَنْ لَا تَزِيدَ زِيَادَةً مُتَّصِلَةً وَأَنْ تَكُونَ بَاقِيَةً فِي مِلْكِهِ وَأَنْ لَا يَرْهَنَهَا."]]},{"id":"da70_11","label":"بَابُ الْهِبَةِ · ١١","segs":[["matn","وَلِلْأَبِ الْحُرِّ أَنْ يَتَمَلَّكَ مِنْ مَالِ وَلَدِهِ مَا شَاءَ بِشُرُوطٍ خَمْسَةٍ:"]]},{"id":"da70_12","label":"بَابُ الْهِبَةِ · ١٢","segs":[["matn","أَنْ لَا يَضُرَّهُ وَأَنْ لَا يَكُونَ فِي مَرَضِ مَوْتِ أَحَدِهِمَا وَأَنْ لَا يُعْطِيَهُ لِوَلَدٍ آخَرَ وَأَنْ يَكُونَ التَّمَلُّكُ بِالْقَبْضِ مَعَ الْقَوْلِ أَوِ النِّيَّةِ"]]},{"id":"da70_13","label":"بَابُ الْهِبَةِ · ١٣","segs":[["matn","وَأَنْ يَكُونَ مَا يَتَمَلَّكُهُ عَيْنًا مَوْجُودَةً فَلَا يَصِحُّ أَنْ يَتَمَلَّكَ مَا فِي ذِمَّتِهِ مِنْ دَيْنِ وَلَدِهِ وَلَا أَنْ يُبْرِئَ نَفْسَهُ."]]},{"id":"da70_14","label":"بَابُ الْهِبَةِ · ١٤","segs":[["matn","وَلَيْسَ لِوَلَدِهِ أَنْ يُطَالِبَهُ بِمَا فِي ذِمَّتِهِ مِنَ الدَّيْنِ بَلْ إِذَا مَاتَ أَخَذَهُ مِنْ تَرِكَتِهِ مِنْ رَأْسِ الْمَالِ."]]},{"id":"da70_15","label":"بَابُ الْهِبَةِ · ١٥","segs":[["matn","فَصْلٌ: وَيُبَاحُ لِلْإِنْسَانِ أَنْ يَقْسِمَ مَالَهُ بَيْنَ وَرَثَتِهِ فِي حَالِ حَيَاتِهِ وَيُعْطِي مَنْ حَدَثَ حِصَّتَهُ وُجُوبًا وَيَجِبُ عَلَيْهِ التَّسْوِيَةُ بَيْنَهُمْ عَلَى قَدْرِ إِرْثِهِمْ."]]},{"id":"da70_16","label":"بَابُ الْهِبَةِ · ١٦","segs":[["matn","فَإِنْ زَوَّجَ أَحَدَهُمْ أَوْ خَصَّصَهُ بِلَا إِذْنِ الْبَقِيَّةِ حَرُمَ عَلَيْهِ وَلَزِمَهُ أَنْ يُعْطِيَهُمْ حَتَّى يَسْتَوُوا فَإِنْ مَاتَ قَبْلَ التَّسْوِيَةِ بَيْنَهُمْ"]]},{"id":"da70_17","label":"بَابُ الْهِبَةِ · ١٧","segs":[["matn","وَلَيْسَ التَّخْصِيصُ بِمَرَضِ مَوْتِهِ الْمَخُوفِ ثَبَتَ لِلْآخِذِ وَإِنْ كَانَ بِمَرَضِ مَوْتِهِ لَمْ يَثْبُتْ لَهُ شَيْءٌ زَائِدٌ عَنْهُمْ إِلَّا بِإِجَازَتِهِمْ مَا لَمْ يَكُنْ وَقْفًا فَيَصِحُّ بِالثُّلُثِ كَالْأَجْنَبِيِّ"]]},{"id":"da70_18","label":"بَابُ الْهِبَةِ · ١٨","segs":[["matn","فَصْلٌ: وَالْمَرَضُ غَيْرُ الْمَخُوفِ كَالصُّدَاعِ وَوَجَعِ الضِّرْسِ وَتَبَرُّعُ صَاحِبِهِ نَافِذٌ فِي جَمِيعِ مَالِهِ كَتَبَرُّعِ الصَّحِيحِ حَتَّى وَلَوْ صَارَ مَخُوفًا وَمَاتَ مِنْهُ بَعْدَ ذَلِكَ."]]},{"id":"da70_19","label":"بَابُ الْهِبَةِ · ١٩","segs":[["matn","وَالْمَرَضُ الْمَخُوفُ كَالْبِرْسَامِ وَذَاتِ الْجَنْبِ وَالرُّعَافِ الدَّائِمِ وَالْقِيَامِ الْمُتَدَارِكِ وَكَذَلِكَ مَنْ بَيْنَ الصَّفَّيْنِ وَقْتَ الْحَرْبِ أَوْ كَانَ بِاللُّجَّةِ وَقْتَ الْهَيَجَانِ أَوْ"]]},{"id":"da70_20","label":"بَابُ الْهِبَةِ · ٢٠","segs":[["matn","وَقَعَ الطَّاعُونُ بِبَلَدِهِ أَوْ قُدِّمَ لِلْقَتْلِ أَوْ حُبِسَ لَهُ أَوْ جُرِحَ جُرْحًا مُوحِيًا فَكُلُّ مَنْ أَصَابَهُ شَيْءٌ مِنْ ذَلِكَ ثُمَّ تَبَرَّعَ وَمَاتَ نَفَذَ تَبَرُّعُهُ بِالثُّلُثِ فَقَطْ لِلْأَجْنَبِيِّ فَقَطْ وَإِنْ لَمْ يَمُتْ فَكَالصَّحِيحِ."]]}],"group":"كِتَابُ الْوَقْفِ"},{"id":"da71","title":"كِتَابُ الْوَصِيَّةِ","units":[{"id":"da71_1","label":"كِتَابُ الْوَصِيَّةِ · ١","segs":[["matn","تَصِحُّ: الْوَصِيَّةُ مِنْ كُلِّ عَاقِلٍ لَمْ يُعَايِنِ الْمَوْتَ وَلَوْ مُمَيِّزًا أَوْ سَفِيهًا. فَتُسَنُّ بِخُمْسِ مَنْ تَرَكَ خَيْرًا وَهُوَ الْمَالُ الْكَثِيرُ عُرْفًا. وَتُكْرَهُ لِفَقِيرٍ لَهُ وَرَثَةٌ. وَتُبَاحُ لَهُ إِنْ كَانُوا أَغْنِيَاءَ."]]},{"id":"da71_2","label":"كِتَابُ الْوَصِيَّةِ · ٢","segs":[["matn","وَتَجِبُ عَلَى مَنْ عَلَيْهِ حَقٌّ بِلَا بَيِّنَةٍ. وَتَحْرُمُ عَلَى مَنْ لَهُ وَارِثٌ بِزَائِدٍ عَلَى الثُّلُثِ وَلِوَارِثٍ بِشَيْءٍ وَتَصِحُّ وَتَقِفُ عَلَى إِجَازَةِ الْوَرَثَةِ وَالِاعْتِبَارُ بِكَوْنِ مَنْ وُصِّيَ أَوْ وُهِبَ لَهُ وَارِثًا أَوْ لَا عِنْدَ الْمَوْتِ وَبِالْإِجَازَةِ أَوِ الرَّدِّ بَعْدَهُ."]]},{"id":"da71_3","label":"كِتَابُ الْوَصِيَّةِ · ٣","segs":[["matn","فَإِنِ امْتَنَعَ الْمُوصَى لَهُ بَعْدَ مَوْتِ الْمُوصِي مِنَ الْقَبُولِ وَمِنَ الرَّدِّ حُكِمَ عَلَيْهِ بِالرَّدِّ وَسَقَطَ حَقُّهُ. وَإِنْ قَبِلَ ثُمَّ رَدَّ لَزِمَتْ وَلَمْ يَصِحَّ الرَّدُّ."]]},{"id":"da71_4","label":"كِتَابُ الْوَصِيَّةِ · ٤","segs":[["matn","وَتَدْخُلُ فِي مِلْكِهِ مِنْ حِينِ قَبُولِهِ فَمَا حَدَثَ مِنْ نَمَاءٍ مُنْفَصِلٍ قَبْلَ ذَلِكَ فَلِلْوَرَثَةِ."]]},{"id":"da71_5","label":"كِتَابُ الْوَصِيَّةِ · ٥","segs":[["matn","وَتَبْطُلُ الْوَصِيَّةُ بِخَمْسَةِ أَشْيَاءَ: بِرُجُوعِ الْمُوصِي بِقَوْلٍ أَوْ فِعْلٍ يَدُلُّ عَلَيْهِ وَبِمَوْتِ الْمُوصَى لَهُ قَبْلَ الْمُوصِي وَبِقَتْلِهِ لِلْمُوصِي وَبِرَدِّهِ لِلْوَصِيَّةِ وَبِتَلَفِ الْعَيْنِ الْمُعَيَّنَةِ الْمُوصَى بِهَا."]]}],"group":"كِتَابُ الْوَصِيَّةِ"},{"id":"da72","title":"بَابُ الْمُوصَى لَهُ","units":[{"id":"da72_1","label":"بَابُ الْمُوصَى لَهُ · ١","segs":[["matn","تَصِحُّ الْوَصِيَّةُ لِكُلِّ مَنْ يَصِحُّ تَمْلِيكُهُ وَلَوْ مُرْتَدًّا أَوْ حَرْبِيًّا أَوْ لَا يَمْلِكُ: كَحَمْلٍ وَبَهِيمَةٍ وَيُصْرَفُ فِي عَلَفِهَا. وَتَصِحُّ لِلْمَسَاجِدِ وَالْقَنَاطِرِ وَنَحْوِهَا وَلِلَّهِ وَرَسُولِهِ وَتُصْرَفُ فِي الْمَصَالِحِ الْعَامَّةِ."]]},{"id":"da72_2","label":"بَابُ الْمُوصَى لَهُ · ٢","segs":[["matn","وَإِنْ وَصَّى بِإِحْرَاقِ ثُلُثِ مَالِهِ صَحَّ وَصُرِفَ فِي تَجْمِيرِ الْكَعْبَةِ وَتَنْوِيرِ الْمَسَاجِدِ وَبِدَفْنِهِ فِي التُّرَابِ: صُرِفَ فِي تَكْفِينِ الْمَوْتَى وَبِرَمْيِهِ فِي الْمَاءِ: صُرِفَ فِي عَمَلِ سُفُنٍ لِلْجِهَادِ."]]},{"id":"da72_3","label":"بَابُ الْمُوصَى لَهُ · ٣","segs":[["matn","وَلَا تَصِحُّ لِكَنِيسَةٍ أَوْ بَيْتِ نَارٍ أَوْ كُتُبِ التَّوْرَاةِ وَالْإِنْجِيلِ أَوْ مَلَكٍ أَوْ مَيِّتٍ أَوْ جِنِّيٍّ وَلَا لِمُبْهَمٍ كَأَحَدِ هَذَيْنِ"]]},{"id":"da72_4","label":"بَابُ الْمُوصَى لَهُ · ٤","segs":[["matn","فَلَوْ أَوْصَى بِثُلُثِ مَالِهِ لِمَنْ تَصِحُّ لَهُ الْوَصِيَّةُ وَلِمَنْ لَا تَصِحُّ كَانَ الْكُلُّ لِمَنْ تَصِحُّ لَهُ لَكِنْ لَوْ أَوْصَى لِحَيٍّ وَمَيِّتٍ كَانَ لِلْحَيِّ النِّصْفُ فَقَطْ"]]},{"id":"da72_5","label":"بَابُ الْمُوصَى لَهُ · ٥","segs":[["matn","فَصْلٌ: وَإِذَا أَوْصَى لِأَهْلِ سِكَّتِهِ فَلِأَهْلِ زُقَاقِهِ حَالَ الْوَصِيَّةِ وَلِجِيرَانِهِ تَنَاوَلَ أَرْبَعِينَ دَارًا مِنْ كُلِّ جَانِبٍ. وَالصَّغِيرُ وَالصَّبِيُّ وَالْغُلَامُ وَالْيَافِعُ وَالْيَتِيمُ: مَنْ لَمْ يَبْلُغْ. وَالْمُمَيِّزُ: مَنْ بَلَغَ سَبْعًا."]]},{"id":"da72_6","label":"بَابُ الْمُوصَى لَهُ · ٦","segs":[["matn","وَالطِّفْلُ: مَنْ دُونَ سَبْعٍ. وَالْمُرَاهِقُ: مَنْ قَارَبَ الْبُلُوغَ. وَالشَّابُّ وَالْفَتَى: مِنَ الْبُلُوغِ إِلَى ثَلَاثِينَ. وَالْكَهْلُ: مِنَ الثَّلَاثِينَ إِلَى الْخَمْسِينَ. وَالشَّيْخُ مِنَ الْخَمْسِينَ إِلَى السَّبْعِينَ ثُمَّ بَعْدَ ذَلِكَ هَرِمٌ."]]},{"id":"da72_7","label":"بَابُ الْمُوصَى لَهُ · ٧","segs":[["matn","وَالْأَيِّمُ وَالْعَزَبُ: مَنْ لَا زَوْجَ لَهُ مِنْ رَجُلٍ وَامْرَأَةٍ. وَالْبِكْرُ: مَنْ لَمْ يَتَزَوَّجْ. وَرَجُلٌ ثَيِّبٌ وَامْرَأَةٌ ثَيِّبَةٌ: إِذَا كَانَا قَدْ تَزَوَّجَا. وَالثُّيُوبَةُ: زَوَالُ الْبَكَارَةِ وَلَوْ مِنْ غَيْرِ زَوْجٍ."]]},{"id":"da72_8","label":"بَابُ الْمُوصَى لَهُ · ٨","segs":[["matn","وَالْأَرَامِلُ: النِّسَاءُ اللَّاتِي فَارَقَهُنَّ أَزْوَاجُهُنَّ بِمَوْتٍ أَوْ حَيَاةٍ. وَالرَّهْطُ: مَا دُونَ الْعَشَرَةِ مِنَ الرِّجَالِ خَاصَّةً."]]}],"group":"كِتَابُ الْوَصِيَّةِ"},{"id":"da73","title":"بَابُ الْمُوصَى بِهِ","units":[{"id":"da73_1","label":"بَابُ الْمُوصَى بِهِ · ١","segs":[["matn","تَصِحُّ الْوَصِيَّةُ حَتَّى بِمَا لَا يَصِحُّ بَيْعُهُ: كَالْآبِقِ وَالشَّارِدِ وَالطَّيْرِ بِالْهَوَاءِ وَالْحَمْلِ بِالْبَطْنِ وَاللَّبَنِ بِالضَّرْعِ وَبِالْمَعْدُومِ: كَبِمَا تَحْمِلُ أَمَتُهُ أَوْ شَجَرَتُهُ أَبَدًا أَوْ مُدَّةً مَعْلُومَةً."]]},{"id":"da73_2","label":"بَابُ الْمُوصَى بِهِ · ٢","segs":[["matn","فَإِنْ حَصَلَ شَيْءٌ فَلِلْمُوصَى لَهُ إِلَّا حَمْلَ الْأَمَةِ فَقِيمَتُهُ يَوْمَ وَضْعِهِ."]]},{"id":"da73_3","label":"بَابُ الْمُوصَى بِهِ · ٣","segs":[["matn","وَتَصِحُّ بِغَيْرِ مَالٍ كَكَلْبٍ مُبَاحِ النَّفْعِ وَزَيْتٍ مُتَنَجِّسٍ وَتَصِحُّ بِالْمَنْفَعَةِ الْمُفْرَدَةِ كَخِدْمَةِ عَبْدٍ وَأُجْرَةِ دَارٍ وَنَحْوِهِمَا وَتَصِحُّ بِالْمُبْهَمِ كَثَوْبٍ وَيُعْطَى مَا يَقَعُ عَلَيْهِ الِاسْمُ."]]},{"id":"da73_4","label":"بَابُ الْمُوصَى بِهِ · ٤","segs":[["matn","فَإِنِ اخْتَلَفَ الِاسْمُ بِالْعُرْفِ وَالْحَقِيقَةِ غُلِّبَتِ الْحَقِيقَةُ. فَالشَّاةُ وَالْبَعِيرُ وَالثَّوْرُ: اسْمٌ لِلذَّكَرِ وَالْأُنْثَى مِنْ صَغِيرٍ وَكَبِيرٍ. وَالْحِصَانُ وَالْجَمَلُ وَالْحِمَارُ وَالْبَغْلُ وَالْعَبْدُ: اسْمٌ لِلذَّكَرِ خَاصَّةً. وَالْحِجْرُ وَالْأَتَانُ وَالنَّاقَةُ وَالْبَقَرَةُ: اسْمٌ لِلْأُنْثَى."]]},{"id":"da73_5","label":"بَابُ الْمُوصَى بِهِ · ٥","segs":[["matn","وَالْفَرَسُ وَالرَّقِيقُ: اسْمٌ لَهُمَا. وَالنَّعْجَةُ: اسْمٌ لِلْأُنْثَى مِنَ الضَّأْنِ. وَالْكَبْشُ: اسْمٌ لِلذَّكَرِ الْكَبِيرِ مِنْهُ. وَالتَّيْسُ: اسْمٌ لِلذَّكَرِ الْكَبِيرِ مِنَ الْمَعْزِ. وَالدَّابَّةُ عُرْفًا: اسْمٌ لِلذَّكَرِ وَالْأُنْثَى مِنَ الْخَيْلِ وَالْبِغَالِ وَالْحَمِيرِ."]]}],"group":"كِتَابُ الْوَصِيَّةِ"},{"id":"da74","title":"بَابُ الْمُوصَى إِلَيْهِ","units":[{"id":"da74_1","label":"بَابُ الْمُوصَى إِلَيْهِ · ١","segs":[["matn","تَصِحُّ وَصِيَّةُ الْمُسْلِمِ إِلَى كُلِّ مُسْلِمٍ مُكَلَّفٍ رَشِيدٍ عَدْلٍ وَلَوْ ظَاهِرًا أَوْ أَعْمَى أَوِ امْرَأَةً أَوْ رَقِيقًا لَكِنْ لَا يَقْبَلُ إِلَّا بِإِذْنِ سَيِّدِهِ وَتَصِحُّ مِنْ كَافِرٍ إِلَى عَدْلٍ فِي دِينِهِ."]]},{"id":"da74_2","label":"بَابُ الْمُوصَى إِلَيْهِ · ٢","segs":[["matn","وَيُعْتَبَرُ وُجُودُ هَذِهِ الصِّفَاتِ عِنْدَ الْوَصِيَّةِ وَالْمَوْتِ. وَلِلْمُوصَى إِلَيْهِ أَنْ يَقْبَلَ وَأَنْ يَعْزِلَ نَفْسَهُ مَتَى شَاءَ."]]},{"id":"da74_3","label":"بَابُ الْمُوصَى إِلَيْهِ · ٣","segs":[["matn","وَتَصِحُّ الْوَصِيَّةُ مُعَلَّقَةً: كَإِذَا بَلَغَ أَوْ حَضَرَ أَوْ رَشَدَ أَوْ تَابَ مِنْ فِسْقِهِ أَوْ: إِنْ مَاتَ زَيْدٌ فَعَمْرٌو مَكَانَهُ وَتَصِحُّ مُؤَقَّتَةً: كَزَيْدٌ وَصِيِّي سَنَةً ثُمَّ عَمْرٌو."]]},{"id":"da74_4","label":"بَابُ الْمُوصَى إِلَيْهِ · ٤","segs":[["matn","وَلَيْسَ لِلْوَصِيِّ أَنْ يُوصِيَ إِلَّا إِنْ جُعِلَ لَهُ ذَلِكَ. وَلَا نَظَرَ لِلْحَاكِمِ مَعَ الْوَصِيِّ الْخَاصِّ إِذَا كَانَ كُفْؤًا."]]},{"id":"da74_5","label":"بَابُ الْمُوصَى إِلَيْهِ · ٥","segs":[["matn","فَصْلٌ: وَلَا تَصِحُّ الْوَصِيَّةُ إِلَّا فِي شَيْءٍ مَعْلُومٍ يَمْلِكُ الْمُوصِي فِعْلَهُ كَقَضَاءِ الدَّيْنِ وَتَفْرِيقِ الْوَصِيَّةِ وَرَدِّ الْحُقُوقِ إِلَى أَهْلِهَا وَالنَّظَرِ فِي أَمْرِ غَيْرِ مُكَلَّفٍ لَا بِاسْتِيفَاءِ الدَّيْنِ مَعَ رُشْدِ وَارِثِهِ."]]},{"id":"da74_6","label":"بَابُ الْمُوصَى إِلَيْهِ · ٦","segs":[["matn","وَمَنْ وُصِّيَ فِي شَيْءٍ لَمْ يَصِرْ وَصِيًّا فِي غَيْرِهِ. وَإِنْ صَرَفَ أَجْنَبِيٌّ الْمُوصَى بِهِ لِمُعَيَّنٍ فِي جِهَتِهِ لَمْ يَضْمَنْهُ."]]},{"id":"da74_7","label":"بَابُ الْمُوصَى إِلَيْهِ · ٧","segs":[["matn","وَإِذَا قَالَ لَهُ: ضَعْ ثُلُثَ مَالِي حَيْثُ شِئْتَ أَوْ أَعْطِهِ أَوْ تَصَدَّقْ بِهِ عَلَى مَنْ شِئْتَ لَمْ يَجُزْ لَهُ أَخْذُهُ وَلَا دَفْعُهُ إِلَى أَقَارِبِهِ الْوَارِثِينَ وَلَا إِلَى وَرَثَةِ الْمُوصِي."]]},{"id":"da74_8","label":"بَابُ الْمُوصَى إِلَيْهِ · ٨","segs":[["matn","وَمَنْ مَاتَ بِبَرِّيَّةٍ وَنَحْوِهَا وَلَا حَاكِمَ وَلَا وَصِيَّ فَلِكُلِّ مُسْلِمٍ أَخْذُ تَرِكَتِهِ وَبَيْعُ مَا يَرَاهُ وَيُجَهِّزُهُ مِنْهَا إِنْ كَانَتْ وَإِلَّا جَهَّزَهُ مِنْ عِنْدِهِ وَلَهُ الرُّجُوعُ بِمَا غَرِمَهُ إِنْ نَوَى الرُّجُوعَ."]]}],"group":"كِتَابُ الْوَصِيَّةِ"},{"id":"da75","title":"كِتَابُ الْفَرَائِضِ","units":[{"id":"da75_1","label":"كِتَابُ الْفَرَائِضِ · ١","segs":[["matn","وَهِيَ: الْعِلْمُ بِقِسْمَةِ الْمَوَارِيثِ. وَإِذَا مَاتَ الْإِنْسَانُ بُدِئَ مِنْ تَرِكَتِهِ بِكَفَنِهِ وَحَنُوطِهِ وَمُؤْنَةِ تَجْهِيزِهِ مِنْ رَأْسِ مَالِهِ سَوَاءٌ كَانَ قَدْ تَعَلَّقَ بِهِ حَقُّ رَهْنٍ أَوْ أَرْشُ جِنَايَةٍ أَوْ لَا"]]},{"id":"da75_2","label":"كِتَابُ الْفَرَائِضِ · ٢","segs":[["matn","وَمَا بَقِيَ بَعْدَ ذَلِكَ يُقْضَى مِنْهُ دُيُونُ اللَّهِ وَدُيُونُ الْآدَمِيِّينَ وَمَا بَقِيَ بَعْدَ ذَلِكَ تُنَفَّذُ وَصَايَاهُ مِنْ ثُلُثِهِ ثُمَّ يُقْسَمُ مَا بَقِيَ بَعْدَ ذَلِكَ عَلَى وَرَثَتِهِ."]]},{"id":"da75_3","label":"كِتَابُ الْفَرَائِضِ · ٣","segs":[["matn","فَصْلٌ: وَأَسْبَابُ الْإِرْثِ ثَلَاثَةٌ: النَّسَبُ وَالنِّكَاحُ الصَّحِيحُ وَالْوَلَاءُ. وَمَوَانِعُهُ ثَلَاثَةٌ: الْقَتْلُ وَالرِّقُّ وَاخْتِلَافُ الدِّينِ."]]},{"id":"da75_4","label":"كِتَابُ الْفَرَائِضِ · ٤","segs":[["matn","وَالْمُجْمَعُ عَلَى تَوْرِيثِهِمْ مِنَ الذُّكُورِ بِالِاخْتِصَارِ عَشَرَةٌ: الِابْنُ وَابْنُهُ وَإِنْ نَزَلَ وَالْأَبُ وَأَبُوهُ وَإِنْ عَلَا وَالْأَخُ مُطْلَقًا وَابْنُ الْأَخِ لَا مِنَ الْأُمِّ وَالْعَمُّ وَابْنُهُ كَذَلِكَ وَالزَّوْجُ وَالْمُعْتِقُ."]]},{"id":"da75_5","label":"كِتَابُ الْفَرَائِضِ · ٥","segs":[["matn","وَمِنَ الْإِنَاثِ بِالِاخْتِصَارِ سَبْعٌ: الْبِنْتُ وَبِنْتُ الِابْنِ وَإِنْ نَزَلَ أَبُوهَا وَالْأُمُّ وَالْجَدَّةُ مُطْلَقًا وَالْأُخْتُ مُطْلَقًا وَالزَّوْجَةُ وَالْمُعْتِقَةُ."]]},{"id":"da75_6","label":"كِتَابُ الْفَرَائِضِ · ٦","segs":[["matn","فَصْلٌ: وَالْوَارِثُ ثَلَاثَةٌ ذُو فَرْضٍ وَعَصَبَةٌ وَرَحِمٌ. وَالْفُرُوضُ الْمُقَدَّرَةُ سِتَّةٌ: النِّصْفُ وَالرُّبُعُ وَالثُّمُنُ وَالثُّلُثَانِ وَالثُّلُثُ وَالسُّدُسُ."]]},{"id":"da75_7","label":"كِتَابُ الْفَرَائِضِ · ٧","segs":[["matn","وَأَصْحَابُ هَذِهِ الْفُرُوضِ بِالِاخْتِصَارِ عَشَرَةٌ: الزَّوْجَانِ وَالْأَبَوَانِ وَالْجَدُّ وَالْجَدَّةُ مُطْلَقًا وَالْأُخْتُ مُطْلَقًا وَالْبِنْتُ وَبِنْتُ الِابْنِ وَالْأَخُ مِنَ الْأُمِّ."]]},{"id":"da75_8","label":"كِتَابُ الْفَرَائِضِ · ٨","segs":[["matn","فَالنِّصْفُ فَرْضُ خَمْسَةٍ: فَرْضُ الزَّوْجِ حَيْثُ لَا فَرْعَ وَارِثٍ لِلزَّوْجَةِ وَفَرْضُ الْبِنْتِ وَفَرْضُ بِنْتِ الِابْنِ مَعَ عَدَمِ أَوْلَادِ الصُّلْبِ وَفَرْضُ الْأُخْتِ الشَّقِيقَةِ مَعَ عَدَمِ الْفَرْعِ الْوَارِثِ وَفَرْضُ الْأُخْتِ لِلْأَبِ مَعَ عَدَمِ الْأَشِقَّاءِ."]]},{"id":"da75_9","label":"كِتَابُ الْفَرَائِضِ · ٩","segs":[["matn","وَالرُّبُعُ فَرْضُ اثْنَيْنِ: فَرْضُ الزَّوْجِ مَعَ الْفَرْعِ الْوَارِثِ وَفَرْضُ الزَّوْجَةِ فَأَكْثَرَ مَعَ عَدَمِهِ. وَالثُّمُنُ فَرْضُ وَاحِدٍ وَهُوَ: الزَّوْجَةُ فَأَكْثَرُ مَعَ الْفَرْعِ الْوَارِثِ."]]},{"id":"da75_10","label":"كِتَابُ الْفَرَائِضِ · ١٠","segs":[["matn","فَصْلٌ: وَالثُّلُثَانِ: فَرْضُ أَرْبَعَةٍ: فَرْضُ الْبِنْتَيْنِ فَأَكْثَرَ وَبِنْتَيِ الِابْنِ فَأَكْثَرَ وَالْأُخْتَيْنِ الشَّقِيقَتَيْنِ فَأَكْثَرَ وَالْأُخْتَيْنِ لِلْأَبِ فَأَكْثَرَ."]]},{"id":"da75_11","label":"كِتَابُ الْفَرَائِضِ · ١١","segs":[["matn","وَالثُّلُثُ: فَرْضُ اثْنَيْنِ: فَرْضُ وَلَدَيِ الْأُمِّ فَأَكْثَرَ يَسْتَوِي فِيهِ ذَكَرُهُمْ وَأُنْثَاهُمْ وَفَرْضُ الْأُمِّ حَيْثُ لَا فَرْعَ وَارِثٍ لِلْمَيِّتِ وَلَا جَمْعَ مِنَ الْإِخْوَةِ وَالْأَخَوَاتِ لَكِنْ لَوْ كَانَ هُنَاكَ أَبٌ وَأُمٌّ وَزَوْجٌ أَوْ زَوْجَةٌ كَانَ لِلْأُمِّ ثُلُثُ الْبَاقِي."]]},{"id":"da75_12","label":"كِتَابُ الْفَرَائِضِ · ١٢","segs":[["matn","وَالسُّدُسُ فَرْضُ سَبْعَةٍ: فَرْضُ الْأُمِّ مَعَ الْفَرْعِ الْوَارِثِ: أَوْ جَمْعٍ مِنَ الْإِخْوَةِ وَالْأَخَوَاتِ وَفَرْضُ الْجَدَّةِ فَأَكْثَرَ إِلَى ثَلَاثٍ إِنْ تَسَاوَيْنَ مَعَ عَدَمِ الْأُمِّ وَفَرْضُ وَلَدِ الْأُمِّ الْوَاحِدِ وَفَرْضُ بِنْتِ الِابْنِ"]]},{"id":"da75_13","label":"كِتَابُ الْفَرَائِضِ · ١٣","segs":[["matn","فَأَكْثَرَ مَعَ بِنْتِ الصُّلْبِ وَفَرْضُ الْأُخْتِ لِلْأَبِ مَعَ الْأُخْتِ الشَّقِيقَةِ وَفَرْضُ الْأَبِ مَعَ الْفَرْعِ الْوَارِثِ وَفَرْضُ الْجَدِّ كَذَلِكَ وَلَا يَنْزِلَانِ عَنْهُ بِحَالٍ."]]},{"id":"da75_14","label":"كِتَابُ الْفَرَائِضِ · ١٤","segs":[["matn","فَصْلٌ: وَالْجَدُّ مَعَ الْإِخْوَةِ الْأَشِقَّاءِ أَوْ لِأَبٍ ذُكُورًا كَانُوا أَوْ إِنَاثًا كَأَحَدِهِمْ فَإِنْ لَمْ يَكُنْ هُنَاكَ صَاحِبُ فَرْضٍ فَلَهُ مَعَهُمْ خَيْرُ أَمْرَيْنِ: إِمَّا الْمُقَاسَمَةُ أَوْ ثُلُثُ جَمِيعِ الْمَالِ."]]},{"id":"da75_15","label":"كِتَابُ الْفَرَائِضِ · ١٥","segs":[["matn","وَإِنْ كَانَ هُنَاكَ صَاحِبُ فَرْضٍ فَلَهُ خَيْرُ ثَلَاثَةِ أُمُورٍ إِمَّا الْمُقَاسَمَةُ أَوْ ثُلُثُ الْبَاقِي بَعْدَ صَاحِبِ الْفَرْضِ أَوْ سُدُسُ جَمِيعِ الْمَالِ."]]},{"id":"da75_16","label":"كِتَابُ الْفَرَائِضِ · ١٦","segs":[["matn","فَإِنْ لَمْ يَبْقَ بَعْدَ صَاحِبِ الْفَرْضِ إِلَّا السُّدُسُ أَخَذَهُ وَسَقَطَ الْإِخْوَةُ إِلَّا الْأُخْتَ الشَّقِيقَةَ أَوْ لِأَبٍ فِي الْمَسْأَلَةِ الْمُسَمَّاةِ بِالْأَكْدَرِيَّةِ."]]},{"id":"da75_17","label":"كِتَابُ الْفَرَائِضِ · ١٧","segs":[["matn","وَهِيَ زَوْجٌ وَأُمٌّ وَجَدٌّ وَأُخْتٌ: فَلِلزَّوْجِ النِّصْفُ وَلِلْأُمِّ: الثُّلُثُ وَلِلْجَدِّ: السُّدُسُ وَيُفْرَضُ لِلْأُخْتِ: النِّصْفُ فَتَعُولُ إِلَى تِسْعَةٍ ثُمَّ يُقْسَمُ نَصِيبُ الْجَدِّ وَالْأُخْتِ بَيْنَهُمَا أَرْبَعَةٌ عَلَى ثَلَاثَةٍ فَتَصِحُّ مِنْ سَبْعَةٍ وَعِشْرِينَ."]]},{"id":"da75_18","label":"كِتَابُ الْفَرَائِضِ · ١٨","segs":[["matn","وَإِذَا اجْتَمَعَ مَعَ الشَّقِيقِ وَلَدُ الْأَبِ عَدَّهُ عَلَى الْجَدِّ إِنِ احْتَاجَ لِعَدِّهِ ثُمَّ يَأْخُذُ الشَّقِيقُ مَا حَصَلَ لِوَلَدِ الْأَبِ إِلَّا أَنْ يَكُونَ الشَّقِيقُ أُخْتًا وَاحِدَةً فَتَأْخُذُ تَمَامَ النِّصْفِ وَمَا فَضَلَ فَهُوَ لِوَلَدِ الْأَبِ."]]},{"id":"da75_19","label":"كِتَابُ الْفَرَائِضِ · ١٩","segs":[["matn","فَمِنْ صُوَرِ ذَلِكَ الزَّيْدِيَّاتُ الْأَرْبَعُ: الْعَشْرِيَّةُ وَهِيَ: جَدٌّ وَشَقِيقَةٌ وَأَخٌ لِأَبٍ وَالْعِشْرِينِيَّةُ وَهِيَ: جَدٌّ وَشَقِيقَةٌ وَأُخْتَانِ لِأَبٍ وَمُخْتَصَرَةُ زَيْدٍ وَهِيَ: أُمٌّ وَجَدٌّ وَشَقِيقَةٌ وَأَخٌ وَأُخْتٌ لِأَبٍ وَتِسْعِينِيَّةُ زَيْدٍ وَهِيَ: أُمٌّ وَجَدٌّ وَشَقِيقَةٌ وَأَخَوَانِ وَأُخْتٌ لِأَبٍ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da76","title":"بَابُ الْحَجْبِ","units":[{"id":"da76_1","label":"بَابُ الْحَجْبِ · ١","segs":[["matn","اعْلَمْ: أَنَّ الْحَجْبَ بِالْوَصْفِ يَتَأَتَّى دُخُولُهُ عَلَى جَمِيعِ الْوَرَثَةِ وَالْحَجْبُ بِالشَّخْصِ نُقْصَانًا كَذَلِكَ وَحِرْمَانًا فَلَا يَدْخُلُ عَلَى خَمْسَةٍ: الزَّوْجَيْنِ وَالْأَبَوَيْنِ وَالْوَلَدِ."]]},{"id":"da76_2","label":"بَابُ الْحَجْبِ · ٢","segs":[["matn","وَأَنَّ الْجَدَّ يَسْقُطُ بِالْأَبِ وَكُلَّ جَدٍّ أَبْعَدَ بِجَدٍّ أَقْرَبَ وَأَنَّ الْجَدَّةَ مُطْلَقًا تَسْقُطُ بِالْأُمِّ وَكُلَّ جَدَّةٍ بُعْدَى بِجَدَّةٍ قُرْبَى وَأَنَّ كُلَّ ابْنٍ أَبْعَدَ يَسْقُطُ بِابْنٍ أَقْرَبَ وَتَسْقُطُ الْإِخْوَةُ الْأَشِقَّاءُ بِاثْنَيْنِ: بِالِابْنِ وَإِنْ نَزَلَ وَبِالْأَبِ الْأَقْرَبِ."]]},{"id":"da76_3","label":"بَابُ الْحَجْبِ · ٣","segs":[["matn","وَالْإِخْوَةُ لِلْأَبِ يَسْقُطُونَ بِالْأَخِ الشَّقِيقِ أَيْضًا وَبَنُو الْإِخْوَةِ يَسْقُطُونَ حَتَّى بِالْجَدِّ أَبِي الْأَبِ وَإِنْ عَلَا وَالْأَعْمَامُ يَسْقُطُونَ حَتَّى بِبَنِي الْإِخْوَةِ وَإِنْ نَزَلُوا وَالْأَخُ لِلْأُمِّ يَسْقُطُ بِاثْنَيْنِ: بِفُرُوعِ الْمَيِّتِ مُطْلَقًا وَإِنْ نَزَلُوا وَبِأُصُولِهِ الذُّكُورِ وَإِنْ عَلَوْا."]]},{"id":"da76_4","label":"بَابُ الْحَجْبِ · ٤","segs":[["matn","وَتَسْقُطُ بَنَاتُ الِابْنِ بِبِنْتَيِ الصُّلْبِ فَأَكْثَرَ مَا لَمْ يَكُنْ مَعَهُنَّ مَنْ يُعَصِّبُهُنَّ مِنْ وَلَدِ الِابْنِ. وَتَسْقُطُ الْأَخَوَاتُ لِلْأَبِ بِالْأُخْتَيْنِ الشَّقِيقَتَيْنِ فَأَكْثَرَ مَا لَمْ يَكُنْ مَعَهُنَّ أَخُوهُنَّ فَيُعَصِّبُهُنَّ."]]},{"id":"da76_5","label":"بَابُ الْحَجْبِ · ٥","segs":[["matn","وَمَنْ لَا يَرِثُ لَا يَحْجُبُ أَحَدًا مُطْلَقًا إِلَّا الْإِخْوَةَ مِنْ حَيْثُ هُمْ فَقَدْ لَا يَرِثُونَ وَيَحْجُبُونَ الْأُمَّ نُقْصَانًا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da77","title":"بَابُ الْعَصَبَاتِ","units":[{"id":"da77_1","label":"بَابُ الْعَصَبَاتِ · ١","segs":[["matn","اعْلَمْ أَنَّ النِّسَاءَ كُلَّهُنَّ صَاحِبَاتُ فَرْضٍ وَلَيْسَ فِيهِنَّ عَصَبَةٌ بِنَفْسِهِ إِلَّا الْمُعْتِقَةُ."]]},{"id":"da77_2","label":"بَابُ الْعَصَبَاتِ · ٢","segs":[["matn","وَأَنَّ الرِّجَالَ كُلَّهُمْ عَصَبَاتٌ بِأَنْفُسِهِمْ إِلَّا الزَّوْجَ وَوَلَدَ الْأُمِّ وَأَنَّ الْأَخَوَاتِ مَعَ الْبَنَاتِ عَصَبَاتٌ وَأَنَّ الْبَنَاتِ وَبَنَاتِ الِابْنِ وَالْأَخَوَاتِ الشَّقِيقَاتِ وَالْأَخَوَاتِ لِلْأَبِ كُلُّ وَاحِدَةٍ مِنْهُنَّ مَعَ أَخِيهَا عَصَبَةٌ بِهِ لَهُ مِثْلُ مَا لَهَا."]]},{"id":"da77_3","label":"بَابُ الْعَصَبَاتِ · ٣","segs":[["matn","وَأَنَّ حُكْمَ الْعَاصِبِ أَنْ يَأْخُذَ مَا أَبْقَتِ الْفُرُوضُ وَإِنْ لَمْ يَبْقَ شَيْءٌ سَقَطَ وَإِذَا انْفَرَدَ أَخَذَ جَمِيعَ الْمَالِ لَكِنْ لِلْجَدِّ وَالْأَبِ ثَلَاثُ حَالَاتٍ: يَرِثَانِ بِالتَّعْصِيبِ فَقَطْ مَعَ عَدَمِ الْفَرْعِ الْوَارِثِ وَبِالْفَرْضِ فَقَطْ مَعَ ذُكُورِيَّتِهِ وَبِالْفَرْضِ وَالتَّعْصِيبِ مَعَ أُنُوثِيَّتِهِ."]]},{"id":"da77_4","label":"بَابُ الْعَصَبَاتِ · ٤","segs":[["matn","وَلَا تَتَمَشَّى عَلَى قَوَاعِدِنَا الْمُشَرَّكَةُ وَهِيَ: زَوْجٌ، وَأُمٌّ، وَإِخْوَةٌ لِأُمٍّ وَإِخْوَةٌ أَشِقَّاءُ."]]},{"id":"da77_5","label":"بَابُ الْعَصَبَاتِ · ٥","segs":[["matn","فَصْلٌ: وَإِذَا اجْتَمَعَ كُلُّ الرِّجَالِ وَرِثَ مِنْهُمْ ثَلَاثَةٌ الِابْنُ وَالْأَبُ وَالزَّوْجُ وَإِذَا اجْتَمَعَ كُلُّ النِّسَاءِ وَرِثَ مِنْهُنَّ خَمْسَةٌ: الْبِنْتُ وَبِنْتُ الِابْنِ وَالْأُمُّ وَالزَّوْجَةُ وَالْأُخْتُ الشَّقِيقَةُ."]]},{"id":"da77_6","label":"بَابُ الْعَصَبَاتِ · ٦","segs":[["matn","وَإِذَا اجْتَمَعَ مُمْكِنُ الْجَمْعِ مِنَ الصِّنْفَيْنِ وَرِثَ مِنْهُمْ خَمْسَةٌ: الْأَبَوَانِ وَالْوَلَدَانِ وَأَحَدُ الزَّوْجَيْنِ. وَمَتَى كَانَ الْعَاصِبُ عَمًّا أَوِ ابْنَ عَمٍّ أَوِ ابْنَ أَخٍ انْفَرَدَ بِالْإِرْثِ دُونَ أَخَوَاتِهِ."]]},{"id":"da77_7","label":"بَابُ الْعَصَبَاتِ · ٧","segs":[["matn","وَمَتَى عُدِمَتِ الْعَصَبَاتُ مِنَ النَّسَبِ وَرِثَ الْمَوْلَى الْمُعْتِقُ وَلَوْ أُنْثَى ثُمَّ عَصَبَتُهُ الذُّكُورُ الْأَقْرَبُ فَالْأَقْرَبُ كَالنَّسَبِ فَإِنْ لَمْ يَكُنْ عَمِلْنَا بِالرَّدِّ فَإِنْ لَمْ يَكُنْ وَرَّثْنَا ذَوِي الْأَرْحَامِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da78","title":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ","units":[{"id":"da78_1","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ١","segs":[["matn","حَيْثُ لَمْ تَسْتَغْرِقِ الْفُرُوضُ التَّرِكَةَ وَلَا عَاصِبَ رُدَّ الْفَاضِلُ عَلَى كُلِّ ذِي فَرْضٍ بِقَدْرِهِ مَا عَدَا الزَّوْجَيْنِ فَلَا يُرَدُّ عَلَيْهِمَا مِنْ حَيْثُ الزَّوْجِيَّةُ"]]},{"id":"da78_2","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٢","segs":[["matn","فَإِنْ لَمْ يَكُنْ إِلَّا صَاحِبُ فَرْضٍ أَخَذَ الْكُلَّ فَرْضًا وَرَدًّا وَإِنْ كَانَ جَمَاعَةٌ مِنْ جِنْسٍ كَالْبَنَاتِ فَأَعْطِهِمْ بِالسَّوِيَّةِ فَإِنِ اخْتَلَفَ جِنْسُهُمْ فَخُذْ عَدَدَ سِهَامِهِمْ مِنْ أَصْلِ سِتَّةٍ: دَائِمًا."]]},{"id":"da78_3","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٣","segs":[["matn","فَجَدَّةٌ وَأَخٌ لِأُمٍّ تَصِحُّ مِنَ اثْنَيْنِ وَأُمٌّ وَأَخٌ لِأُمٍّ مِنْ ثَلَاثَةٍ وَأُمٌّ وَبِنْتٌ مِنْ أَرْبَعَةٍ وَأُمٌّ وَبِنْتَانِ مِنْ خَمْسَةٍ وَلَا تَزِيدُ عَلَيْهَا لِأَنَّهَا لَوْ زَادَتْ سُدُسًا آخَرَ لَاسْتَغْرَقَتِ الْفُرُوضُ."]]},{"id":"da78_4","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٤","segs":[["matn","وَإِنْ كَانَ هُنَاكَ أَحَدُ الزَّوْجَيْنِ فَاعْمَلْ مَسْأَلَةَ الرَّدِّ ثُمَّ مَسْأَلَةَ الزَّوْجِيَّةِ ثُمَّ تَقْسِمُ مَا فَضَلَ عَنْ فَرْضِ الزَّوْجِيَّةِ عَلَى مَسْأَلَةِ الرَّدِّ فَإِنِ انْقَسَمَ صَحَّتِ مَسْأَلَةُ الرَّدِّ مِنْ مَسْأَلَةِ الزَّوْجِيَّةِ وَإِلَّا فَاضْرِبْ مَسْأَلَةَ الرَّدِّ فِي مَسْأَلَةِ الزَّوْجِيَّةِ."]]},{"id":"da78_5","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٥","segs":[["matn","ثُمَّ مَنْ لَهُ شَيْءٌ مِنْ مَسْأَلَةِ الزَّوْجِيَّةِ أَخَذَهُ مَضْرُوبًا فِي مَسْأَلَةِ الرَّدِّ وَمَنْ لَهُ شَيْءٌ مِنْ مَسْأَلَةِ الرَّدِّ أَخَذَهُ مَضْرُوبًا فِي الْفَاضِلِ عَنْ مَسْأَلَةِ الزَّوْجِيَّةِ فَزَوْجٌ وَجَدَّةٌ وَأَخٌ لِأُمٍّ مَثَلًا:"]]},{"id":"da78_6","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٦","segs":[["matn","فَاضْرِبْ مَسْأَلَةَ الرَّدِّ وَهِيَ: اثْنَانِ فِي مَسْأَلَةِ الزَّوْجِ وَهِيَ: اثْنَانِ فَتَصِحُّ مِنْ أَرْبَعَةٍ وَهَكَذَا."]]},{"id":"da78_7","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٧","segs":[["matn","فَصْلٌ فِي ذَوِي الْأَرْحَامِ: وَهُمْ: كُلُّ قَرَابَةٍ لَيْسَ بِذِي فَرْضٍ وَلَا عَصَبَةٍ."]]},{"id":"da78_8","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٨","segs":[["matn","وَأَصْنَافُهُمْ أَحَدَ عَشَرَ: وَلَدُ الْبَنَاتِ لِصُلْبٍ أَوْ لِابْنٍ وَوَلَدُ الْأَخَوَاتِ وَبَنَاتُ الْإِخْوَةِ وَبَنَاتُ الْأَعْمَامِ وَوَلَدُ وَلَدِ الْأُمِّ وَالْعَمُّ لِأُمٍّ وَالْعَمَّاتُ وَالْأَخْوَالُ وَالْخَالَاتُ وَأَبُو الْأُمِّ وَكُلُّ جَدَّةٍ أَدْلَتْ بِأَبٍ بَيْنَ أُمَّيْنِ."]]},{"id":"da78_9","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ٩","segs":[["matn","وَيَرِثُونَ بِتَنْزِيلِهِمْ مَنْزِلَةَ مَنْ أَدْلَوْا بِهِ. وَإِنْ أَدْلَى جَمَاعَةٌ مِنْهُمْ بِوَارِثٍ وَاسْتَوَتْ مَنْزِلَتُهُمْ مِنْهُ فَنَصِيبُهُ لَهُمْ بِالسَّوِيَّةِ: الذَّكَرُ كَالْأُنْثَى."]]},{"id":"da78_10","label":"بَابُ الرَّدِّ وَذَوِي الْأَرْحَامِ · ١٠","segs":[["matn","وَمَنْ لَا وَارِثَ لَهُ فَمَالُهُ لِبَيْتِ الْمَالِ وَلَيْسَ وَارِثًا وَإِنَّمَا يَحْفَظُ الْمَالَ الضَّائِعَ وَغَيْرَهُ فَهُوَ جِهَةٌ وَمَصْلَحَةٌ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da79","title":"بَابُ أُصُولِ الْمَسَائِلِ","units":[{"id":"da79_1","label":"بَابُ أُصُولِ الْمَسَائِلِ · ١","segs":[["matn","وَهِيَ سَبْعَةٌ: اثْنَانِ وَثَلَاثَةٌ وَأَرْبَعَةٌ وَسِتَّةٌ وَثَمَانِيَةٌ وَاثْنَا عَشَرَ وَأَرْبَعَةٌ وَعِشْرُونَ. وَلَا يَعُولُ مِنْهَا إِلَّا السِّتَّةُ وَضِعْفُهَا وَضِعْفُ ضِعْفِهَا. فَالسِّتَّةُ: تَعُولُ مُتَوَالِيَةً إِلَى عَشَرَةٍ."]]},{"id":"da79_2","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٢","segs":[["matn","فَتَعُولُ إِلَى سَبْعَةٍ: كَزَوْجٍ وَأُخْتٍ لِغَيْرِ أُمٍّ وَجَدَّةٍ. وَإِلَى ثَمَانِيَةٍ كَزَوْجٍ وَأُمٍّ وَأُخْتٍ لِغَيْرِ أُمٍّ وَتُسَمَّى الْمُبَاهَلَةَ وَإِلَى تِسْعَةٍ: كَزَوْجٍ وَوَلَدَيْ أُمٍّ وَأُخْتَيْنِ لِغَيْرِهَا وَتُسَمَّى الْغَرَّاءَ وَالْمَرْوَانِيَّةَ وَإِلَى عَشَرَةٍ:"]]},{"id":"da79_3","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٣","segs":[["matn","كَزَوْجٍ وَأُمٍّ وَأُخْتَيْنِ لِأُمٍّ وَأُخْتَيْنِ لِغَيْرِهَا وَتُسَمَّى أُمَّ الْفُرُوخِ وَالِاثْنَا عَشَرَ تَعُولُ أَفْرَادًا إِلَى سَبْعَةَ عَشَرَ فَتَعُولُ إِلَى ثَلَاثَةَ عَشَرَ: كَزَوْجٍ وَبِنْتَيْنِ وَأُمٍّ. وَإِلَى خَمْسَةَ عَشَرَ: كَزَوْجٍ وَبِنْتَيْنِ وَأَبَوَيْنِ."]]},{"id":"da79_4","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٤","segs":[["matn","وَإِلَى سَبْعَةَ عَشَرَ: كَثَلَاثِ زَوْجَاتٍ وَجَدَّتَيْنِ وَأَرْبَعِ أَخَوَاتٍ لِأُمٍّ. وَثَمَانِ أَخَوَاتٍ لِغَيْرِهَا وَتُسَمَّى أُمَّ الْأَرَامِلِ."]]},{"id":"da79_5","label":"بَابُ أُصُولِ الْمَسَائِلِ · ٥","segs":[["matn","وَالْأَرْبَعَةُ وَالْعِشْرُونَ تَعُولُ مَرَّةً وَاحِدَةً إِلَى سَبْعَةٍ وَعِشْرِينَ: كَزَوْجَةٍ وَبِنْتَيْنِ وَأَبَوَيْنِ وَتُسَمَّى الْمِنْبَرِيَّةَ وَالْبَخِيلَةَ لِقِلَّةِ عَوْلِهَا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da80","title":"بَابُ مِيرَاثِ الْحَمْلِ","units":[{"id":"da80_1","label":"بَابُ مِيرَاثِ الْحَمْلِ · ١","segs":[["matn","مَنْ مَاتَ عَنْ حَمْلٍ يَرِثُهُ فَطَلَبَ بَقِيَّةُ وَرَثَتِهِ قِسْمَةَ التَّرِكَةِ قُسِمَتْ وَوُقِفَ لَهُ الْأَكْثَرُ مِنْ إِرْثِ ذَكَرَيْنِ أَوْ أُنْثَيَيْنِ"]]},{"id":"da80_2","label":"بَابُ مِيرَاثِ الْحَمْلِ · ٢","segs":[["matn","وَدُفِعَ لِمَنْ لَا يَحْجُبُهُ الْحَمْلُ إِرْثُهُ كَامِلًا وَلِمَنْ يَحْجُبُهُ حَجْبَ نُقْصَانٍ أَقَلُّ مِيرَاثِهِ وَلَا يُدْفَعُ لِمَنْ يُسْقِطُهُ شَيْءٌ فَإِذَا وُلِدَ أَخَذَ نَصِيبَهُ وَرُدَّ مَا بَقِيَ لِمُسْتَحِقِّهِ."]]},{"id":"da80_3","label":"بَابُ مِيرَاثِ الْحَمْلِ · ٣","segs":[["matn","وَلَا يَرِثُ إِلَّا إِنِ اسْتَهَلَّ صَارِخًا أَوْ عَطَسَ أَوْ تَنَفَّسَ أَوْ وُجِدَ مِنْهُ مَا يَدُلُّ عَلَى الْحَيَاةِ: كَالْحَرَكَةِ الطَّوِيلَةِ وَنَحْوِهَا. وَلَوْ ظَهَرَ بَعْضُهُ فَاسْتَهَلَّ ثُمَّ انْفَصَلَ مَيْتًا لَمْ يَرِثْ"]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da81","title":"بَابُ مِيرَاثِ الْمَفْقُودِ","units":[{"id":"da81_1","label":"بَابُ مِيرَاثِ الْمَفْقُودِ · ١","segs":[["matn","مَنِ انْقَطَعَ خَبَرُهُ لِغَيْبَةٍ ظَاهِرُهَا السَّلَامَةُ: كَالْأَسْرِ وَالْخُرُوجِ لِلتِّجَارَةِ وَالسِّيَاحَةِ وَطَلَبِ الْعِلْمِ انْتُظِرَ تَتِمَّةَ تِسْعِينَ سَنَةً مُنْذُ وُلِدَ فَإِنْ فُقِدَ ابْنَ تِسْعِينَ اجْتَهَدَ الْحَاكِمُ."]]},{"id":"da81_2","label":"بَابُ مِيرَاثِ الْمَفْقُودِ · ٢","segs":[["matn","وَإِنْ كَانَ ظَاهِرُهَا الْهَلَاكَ: كَمَنْ فُقِدَ مِنْ بَيْنِ أَهْلِهِ أَوْ فِي مَهْلَكَةٍ كَدَرْبِ الْحِجَازِ أَوْ فُقِدَ بَيْنَ الصَّفَّيْنِ حَالَ الْحَرْبِ أَوْ غَرِقَتْ سَفِينَةٌ وَنَجَا قَوْمٌ وَغَرِقَ آخَرُونَ انْتُظِرَ تَتِمَّةَ أَرْبَعِ سِنِينَ مُنْذُ فُقِدَ."]]},{"id":"da81_3","label":"بَابُ مِيرَاثِ الْمَفْقُودِ · ٣","segs":[["matn","ثُمَّ يُقْسَمُ مَالُهُ فِي الْحَالَتَيْنِ. فَإِنْ قَدِمَ بَعْدَ الْقِسْمَةِ أَخَذَ مَا وَجَدَهُ بِعَيْنِهِ وَرَجَعَ بِالْبَاقِي. فَإِنْ مَاتَ مُوَرِّثُ هَذَا الْمَفْقُودِ فِي زَمَنِ انْتِظَارِهِ أَخَذَ كُلُّ وَارِثٍ الْيَقِينَ وَوُقِفَ لَهُ الْبَاقِي. وَمَنْ أَشْكَلَ نَسَبُهُ فَكَالْمَفْقُودِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da82","title":"بَابُ مِيرَاثِ الْخُنْثَى","units":[{"id":"da82_1","label":"بَابُ مِيرَاثِ الْخُنْثَى · ١","segs":[["matn","وَهُوَ: مَنْ لَهُ شَكْلُ الذَّكَرِ وَفَرْجُ الْمَرْأَةِ. وَيُعْتَبَرُ بِبَوْلِهِ فَبِسَبْقِهِ مِنْ أَحَدِهِمَا. فَإِنْ خَرَجَ مِنْهُمَا مَعًا اعْتُبِرَ أَكْثَرُهُمَا فَإِنِ اسْتَوَيَا فَمُشْكِلٌ."]]},{"id":"da82_2","label":"بَابُ مِيرَاثِ الْخُنْثَى · ٢","segs":[["matn","فَإِنْ رُجِيَ كَشْفُهُ بَعْدَ كِبَرِهِ أُعْطِيَ وَمَنْ مَعَهُ الْيَقِينَ وَوُقِفَ الْبَاقِي لِتَظْهَرَ ذُكُورَتُهُ بِنَبَاتِ لِحْيَتِهِ أَوْ إِمْنَاءٍ مِنْ ذَكَرِهِ أَوْ أُنُوثَتُهُ بِحَيْضٍ أَوْ تَفَلُّكِ ثَدْيٍ أَوْ إِمْنَاءٍ مِنْ فَرْجٍ."]]},{"id":"da82_3","label":"بَابُ مِيرَاثِ الْخُنْثَى · ٣","segs":[["matn","فَإِنْ مَاتَ أَوْ بَلَغَ بِلَا أَمَارَةٍ وَاخْتَلَفَ إِرْثُهُ أَخَذَ نِصْفَ مِيرَاثِ ذَكَرٍ وَنِصْفَ مِيرَاثِ أُنْثَى."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da83","title":"بَابُ مِيرَاثِ الْغَرْقَى وَنَحْوِهِمْ","units":[{"id":"da83_1","label":"بَابُ مِيرَاثِ الْغَرْقَى وَنَحْوِهِمْ · ١","segs":[["matn","إِذَا عُلِمَ مَوْتُ الْمُتَوَارِثَيْنِ مَعًا فَلَا إِرْثَ وَكَذَا إِنْ جُهِلَ الْأَسْبَقُ أَوْ عُلِمَ ثُمَّ نُسِيَ وَادَّعَى وَرَثَةُ كُلٍّ سَبْقَ الْآخَرِ"]]},{"id":"da83_2","label":"بَابُ مِيرَاثِ الْغَرْقَى وَنَحْوِهِمْ · ٢","segs":[["matn","وَلَا بَيِّنَةَ أَوْ تَعَارَضَتَا وَإِنْ لَمْ يَدَّعِ وَرَثَةُ كُلٍّ سَبْقَ الْآخَرِ وَرِثَ كُلُّ مَيِّتٍ صَاحِبَهُ ثُمَّ يُقْسَمُ مَا وَرِثَهُ عَلَى الْأَحْيَاءِ مِنْ وَرَثَتِهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da84","title":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ","units":[{"id":"da84_1","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ١","segs":[["matn","لَا تَوَارُثَ بَيْنَ مُخْتَلِفَيْنِ فِي الدِّينِ إِلَّا بِالْوَلَاءِ فَيَرِثُ بِهِ الْمُسْلِمُ الْكَافِرَ وَالْكَافِرُ الْمُسْلِمَ وَكَذَا يَرِثُ الْكَافِرُ وَلَوْ مُرْتَدًّا إِذَا أَسْلَمَ قَبْلَ قَسْمِ مِيرَاثِ مُوَرِّثِهِ الْمُسْلِمِ."]]},{"id":"da84_2","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ٢","segs":[["matn","وَالْكُفَّارُ مِلَلٌ شَتَّى لَا يَتَوَارَثُونَ مَعَ اخْتِلَافِهَا. فَإِنِ اتَّفَقَتْ وَوُجِدَتِ الْأَسْبَابُ وَرِثَ بَعْضُهُمْ بَعْضًا وَلَوْ أَنَّ أَحَدَهُمَا ذِمِّيٌّ وَالْآخَرَ حَرْبِيٌّ أَوْ مُسْتَأْمِنٌ وَالْآخَرَ ذِمِّيٌّ أَوْ حَرْبِيٌّ."]]},{"id":"da84_3","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ٣","segs":[["matn","وَمَنْ حُكِمَ بِكُفْرِهِ مِنْ أَهْلِ الْبِدَعِ وَالْمُرْتَدُّ وَالزِّنْدِيقُ وَهُوَ: الْمُنَافِقُ فَمَا لَهُمْ فَيْءٌ لَا يُوَرِّثُونَ وَلَا يَرِثُونَ."]]},{"id":"da84_4","label":"بَابُ مِيرَاثِ أَهْلِ الْمِلَلِ · ٤","segs":[["matn","وَيَرِثُ الْمَجُوسِيُّ وَنَحْوُهُ بِجَمِيعِ قَرَابَاتِهِ فَلَوْ خَلَّفَ أُمَّهُ وَهِيَ أُخْتُهُ مِنْ أَبِيهِ وَرِثَتِ الثُّلُثَ بِكَوْنِهَا أُمًّا وَالنِّصْفَ بِكَوْنِهَا أُخْتًا."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da85","title":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ","units":[{"id":"da85_1","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ١","segs":[["matn","يَثْبُتُ الْإِرْثُ لِكُلٍّ مِنَ الزَّوْجَيْنِ فِي الطَّلَاقِ الرَّجْعِيِّ. وَلَا يَثْبُتُ فِي الْبَائِنِ إِلَّا لَهَا إِنِ اتُّهِمَ بِقَصْدِ حِرْمَانِهَا:"]]},{"id":"da85_2","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ٢","segs":[["matn","بِأَنْ طَلَّقَهَا فِي مَرَضِ مَوْتِهِ الْمَخُوفِ ابْتِدَاءً أَوْ سَأَلَتْهُ رَجْعِيًّا فَطَلَّقَهَا بَائِنًا أَوْ عَلَّقَ فِي مَرَضِهِ طَلَاقَهَا عَلَى مَالَا غِنَى لَهَا عَنْهُ أَوْ أَقَرَّ أَنَّهُ طَلَّقَهَا سَابِقًا"]]},{"id":"da85_3","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ٣","segs":[["matn","فِي حَالِ صِحَّتِهِ أَوْ وَكَّلَ فِي صِحَّتِهِ مَنْ يُبِينُهَا مَتَى شَاءَ فَأَبَانَهَا فِي مَرَضِ مَوْتِهِ فَتَرِثُ فِي الْجَمِيعِ حَتَّى وَلَوِ انْقَضَتْ عِدَّتُهَا مَا لَمْ تَتَزَوَّجْ أَوْ تَرْتَدَّ:"]]},{"id":"da85_4","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ٤","segs":[["matn","فَلَوْ طَلَّقَ الْمُتَّهَمُ أَرْبَعًا وَانْقَضَتْ عِدَّتُهُنَّ وَتَزَوَّجَ أَرْبَعًا سِوَاهُنَّ وَرِثَ الثَّمَانُ عَلَى السَّوَاءِ بِشَرْطِهِ."]]},{"id":"da85_5","label":"بَابُ مِيرَاثِ الْمُطَلَّقَةِ · ٥","segs":[["matn","وَيَثْبُتُ لَهُ إِنْ فَعَلَتْ بِمَرَضِ مَوْتِهَا الْمَخُوفِ مَا يَفْسَخُ نِكَاحَهَا مَا دَامَتْ مُعْتَدَّةً إِنِ اتُّهِمَتْ وَإِلَّا سَقَطَ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da86","title":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ","units":[{"id":"da86_1","label":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ · ١","segs":[["matn","إِذَا أَقَرَّ الْوَارِثُ بِمَنْ يُشَارِكُهُ فِي الْإِرْثِ أَوْ بِمَنْ يَحْجُبُهُ كَأَخٍ أَقَرَّ بِابْنٍ لِلْمَيِّتِ صَحَّ وَثَبَتَ الْإِرْثُ وَالْحَجْبُ."]]},{"id":"da86_2","label":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ · ٢","segs":[["matn","فَإِذَا أَقَرَّ الْوَرَثَةُ الْمُكَلَّفُونَ بِشَخْصٍ مَجْهُولِ النَّسَبِ وَصَدَّقَ أَوْ كَانَ صَغِيرًا أَوْ مَجْنُونًا ثَبَتَ نَسَبُهُ وَإِرْثُهُ."]]},{"id":"da86_3","label":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ · ٣","segs":[["matn","لَكِنْ يُعْتَبَرُ لِثُبُوتِ نَسَبِهِ مِنَ الْمَيِّتِ إِقْرَارُ جَمِيعِ الْوَرَثَةِ حَتَّى الزَّوْجِ وَوَلَدِ الْأُمِّ أَوْ شَهَادَةُ عَدْلَيْنِ مِنَ الْوَرَثَةِ أَوْ مِنْ غَيْرِهِمْ."]]},{"id":"da86_4","label":"بَابُ الْإِقْرَارِ بِمُشَارِكٍ فِي الْمِيرَاثِ · ٤","segs":[["matn","فَإِنْ لَمْ يُقِرَّ جَمِيعُهُمْ ثَبَتَ نَسَبُهُ وَإِرْثُهُ مِمَّنْ أَقَرَّ بِهِ فَيُشَارِكُهُ فِيمَا بِيَدِهِ أَوْ يَأْخُذُ الْكُلَّ إِنْ أَسْقَطَهُ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da87","title":"بَابُ مِيرَاثِ الْقَاتِلِ","units":[{"id":"da87_1","label":"بَابُ مِيرَاثِ الْقَاتِلِ · ١","segs":[["matn","لَا إِرْثَ لِمَنْ قَتَلَ مُوَرِّثَهُ بِغَيْرِ حَقٍّ أَوْ شَارَكَ فِي قَتْلِهِ وَلَوْ خَطَأً فَلَا يَرِثُ مَنْ سَقَى وَلَدَهُ دَوَاءً فَمَاتَ أَوْ أَدَّبَهُ أَوْ فَصَدَهُ أَوْ بَطَّ سِلْعَةً."]]},{"id":"da87_2","label":"بَابُ مِيرَاثِ الْقَاتِلِ · ٢","segs":[["matn","وَتَلْزَمُ الْغُرَّةُ مَنْ شَرِبَتْ دَوَاءً فَأَسْقَطَتْ وَلَا تَرِثُ مِنْهَا شَيْئًا. وَإِنْ قَتَلَهُ بِحَقٍّ وَرِثَهُ كَالْقَتْلِ قِصَاصًا أَوْ حَدًّا أَوْ دَفْعًا عَنْ نَفْسِهِ وَكَذَا لَوْ قَتَلَ الْبَاغِي الْعَادِلَ كَعَكْسِهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da88","title":"بَابُ مِيرَاثِ الْمُعْتَقِ بَعْضُهُ","units":[{"id":"da88_1","label":"بَابُ مِيرَاثِ الْمُعْتَقِ بَعْضُهُ · ١","segs":[["matn","الرَّقِيقُ مِنْ حَيْثُ هُوَ: لَا يَرِثُ وَلَا يُورَثُ. لَكِنَّ الْمُبَعَّضَ يَرِثُ وَيُورَثُ وَيَحْجُبُ بِقَدْرِ مَا فِيهِ مِنَ الْحُرِّيَّةِ."]]},{"id":"da88_2","label":"بَابُ مِيرَاثِ الْمُعْتَقِ بَعْضُهُ · ٢","segs":[["matn","وَإِنْ حَصَلَ بَيْنَهُ وَبَيْنَ سَيِّدِهِ مُهَايَأَةٌ فَكُلُّ تَرِكَتِهِ لِوَارِثِهِ وَإِلَّا فَبَيْنَهُ وَبَيْنَ سَيِّدِهِ بِالْحِصَصِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da89","title":"بَابُ الْوَلَاءِ","units":[{"id":"da89_1","label":"بَابُ الْوَلَاءِ · ١","segs":[["matn","مَنْ أَعْتَقَ رَقِيقًا أَوْ بَعْضَهُ فَسَرَى إِلَى الْبَاقِي أَوْ عَتَقَ عَلَيْهِ بِرَحِمٍ أَوْ فِعْلٍ أَوْ عِوَضٍ أَوْ كِتَابَةٍ أَوْ تَدْبِيرٍ أَوْ إِيلَادٍ أَوْ وَصِيَّةٍ أَوْ أَعْتَقَهُ"]]},{"id":"da89_2","label":"بَابُ الْوَلَاءِ · ٢","segs":[["matn","فِي زَكَاتِهِ أَوْ نَذْرِهِ أَوْ كَفَّارَتِهِ فَلَهُ عَلَيْهِ الْوَلَاءُ وَعَلَى أَوْلَادِهِ بِشَرْطِ كَوْنِهِمْ مِنْ زَوْجَةٍ عَتِيقَةٍ أَوْ أَمَةٍ وَعَلَى مَنْ لَهُ أَوْ لَهُمْ عَلَيْهِ الْوَلَاءُ."]]},{"id":"da89_3","label":"بَابُ الْوَلَاءِ · ٣","segs":[["matn","وَإِنْ قَالَ: أَعْتِقْ عَبْدَكَ عَنِّي مَجَّانًا أَوْ عَنِّي أَوْ عَنْكَ وَعَلَيَّ ثَمَنُهُ إِنْ أَعْتَقَهُ صَحَّ وَكَانَ وَلَاؤُهُ لِلْمُعْتَقِ عَنْهُ وَيَلْزَمُ الْقَائِلَ ثَمَنُهُ فِيمَا إِذَا الْتَزَمَ بِهِ."]]},{"id":"da89_4","label":"بَابُ الْوَلَاءِ · ٤","segs":[["matn","وَإِنْ قَالَ الْكَافِرُ: أَعْتِقْ عَبْدَكَ الْمُسْلِمَ عَنِّي فَأَعْتَقَهُ صَحَّ وَوَلَاؤُهُ لِلْكَافِرِ."]]},{"id":"da89_5","label":"بَابُ الْوَلَاءِ · ٥","segs":[["matn","فَصْلٌ: وَلَا يَرِثُ صَاحِبُ الْوَلَاءِ إِلَّا عِنْدَ عَدَمِ عَصَبَاتِ النَّسَبِ وَبَعْدَ أَنْ يَأْخُذَ أَصْحَابُ الْفُرُوضِ فُرُوضَهُمْ فَبَعْدَ ذَلِكَ يَرِثُ الْمُعْتِقُ وَلَوْ أُنْثَى ثُمَّ عَصَبَتُهُ الْأَقْرَبُ فَالْأَقْرَبُ."]]},{"id":"da89_6","label":"بَابُ الْوَلَاءِ · ٦","segs":[["matn","وَحُكْمُ الْجَدِّ مَعَ الْإِخْوَةِ فِي الْوَلَاءِ كَحُكْمِهِ مَعَهُمْ فِي النَّسَبِ."]]},{"id":"da89_7","label":"بَابُ الْوَلَاءِ · ٧","segs":[["matn","وَالْوَلَاءُ لَا يُبَاعُ وَلَا يُوهَبُ وَلَا يُوقَفُ وَلَا يُوصَى بِهِ وَلَا يُورَثُ وَإِنَّمَا يَرِثُ بِهِ أَقْرَبُ عَصَبَاتِ الْمُعْتِقِ يَوْمَ مَوْتِ الْعَتِيقِ لَكِنْ يَتَأَتَّى انْتِقَالُهُ مِنْ جِهَةٍ إِلَى أُخْرَى"]]},{"id":"da89_8","label":"بَابُ الْوَلَاءِ · ٨","segs":[["matn","فَلَوْ تَزَوَّجَ عَبْدٌ بِمُعْتَقَةٍ فَوَلَاءُ مَنْ تَلِدُهُ لِمَنْ أَعْتَقَهَا فَإِنْ أُعْتِقَ الْأَبُ انْجَرَّ الْوَلَاءُ لِمَوَالِيهِ."]]}],"group":"كِتَابُ الْفَرَائِضِ"},{"id":"da90","title":"كِتَابُ الْعِتْقِ","units":[{"id":"da90_1","label":"كِتَابُ الْعِتْقِ · ١","segs":[["matn","وَهُوَ مِنْ أَعْظَمِ الْقُرَبِ فَيُسَنُّ عِتْقُ رَقِيقٍ لَهُ كَسْبٌ وَيُكْرَهُ إِنْ كَانَ لَا قُوَّةَ لَهُ وَلَا كَسْبَ أَوْ يُخَافُ مِنْهُ الزِّنَا أَوِ الْفَسَادُ وَيَحْرُمُ إِنْ عَلِمَ ذَلِكَ مِنْهُ وَهَكَذَا الْكِتَابَةُ."]]},{"id":"da90_2","label":"كِتَابُ الْعِتْقِ · ٢","segs":[["matn","وَيَحْصُلُ الْعِتْقُ بِالْقَوْلِ وَصَرِيحُهُ لَفْظُ: الْعِتْقِ وَالْحُرِّيَّةِ كَيْفَ صُرِّفَا غَيْرَ أَمْرٍ وَمُضَارِعٍ وَاسْمِ فَاعِلٍ."]]},{"id":"da90_3","label":"كِتَابُ الْعِتْقِ · ٣","segs":[["matn","وَكِنَايَتُهُ مَعَ النِّيَّةِ سِتَّةَ عَشَرَ: خَلَّيْتُكَ وَأَطْلَقْتُكَ وَالْحَقْ بِأَهْلِكَ وَاذْهَبْ حَيْثُ شِئْتَ وَلَا سَبِيلَ لِي أَوْ لَا سُلْطَانَ أَوْ لَا مِلْكَ أَوْ لَا رِقَّ أَوْ:"]]},{"id":"da90_4","label":"كِتَابُ الْعِتْقِ · ٤","segs":[["matn","لَا خِدْمَةَ لِي عَلَيْكَ وَوَهَبْتُكَ لِلَّهِ وَأَنْتَ لِلَّهِ وَرَفَعْتُ يَدِي عَنْكَ إِلَى اللَّهِ وَأَنْتَ مَوْلَايَ أَوْ سَائِبَةٌ وَمَلَّكْتُكَ نَفْسَكَ وَتَزِيدُ الْأَمَةُ بِأَنْتِ طَالِقٌ أَوْ حَرَامٌ."]]},{"id":"da90_5","label":"كِتَابُ الْعِتْقِ · ٥","segs":[["matn","وَيَعْتِقُ حَمْلٌ لَمْ يُسْتَثْنَ بِعِتْقِ أُمِّهِ لَا عَكْسُهُ."]]},{"id":"da90_6","label":"كِتَابُ الْعِتْقِ · ٦","segs":[["matn","وَإِنْ قَالَ لِمَنْ يُمْكِنُ كَوْنُهُ أَبَاهُ أَنْتَ أَبِي أَوْ قَالَ لِمَنْ يُمْكِنُ كَوْنُهُ ابْنَهُ: أَنْتَ ابْنِي عَتَقَ لَا إِنْ لَمْ يُمْكِنْ إِلَّا بِالنِّيَّةِ."]]},{"id":"da90_7","label":"كِتَابُ الْعِتْقِ · ٧","segs":[["matn","فَصْلٌ: وَيَحْصُلُ بِالْفِعْلِ: فَمَنْ مَثَّلَ بِرَقِيقِهِ فَجَدَعَ أَنْفَهُ أَوْ أُذُنَهُ وَنَحْوَهُمَا أَوْ خَرَقَ أَوْ حَرَقَ عُضْوًا مِنْهُ أَوِ اسْتَكْرَهَهُ عَلَى الْفَاحِشَةِ أَوْ وَطِئَ مَنْ لَا يُوطَأُ مِثْلُهَا لِصِغَرٍ فَأَفْضَاهَا عَتَقَ فِي الْجَمِيعِ."]]},{"id":"da90_8","label":"كِتَابُ الْعِتْقِ · ٨","segs":[["matn","وَلَا عِتْقَ بِخَدْشٍ وَضَرْبٍ وَلَعْنٍ. وَيَحْصُلُ بِالْمِلْكِ فَمَنْ مَلَكَ لِذِي رَحِمٍ مَحْرَمٍ مِنَ النَّسَبِ عَتَقَ عَلَيْهِ وَلَوْ حَمْلًا وَإِنْ مَلَكَ بَعْضَهُ عَتَقَ الْبَعْضُ وَالْبَاقِي بِالسِّرَايَةِ إِنْ كَانَ مُوسِرًا وَيَغْرَمُ حِصَّةَ شَرِيكِهِ."]]},{"id":"da90_9","label":"كِتَابُ الْعِتْقِ · ٩","segs":[["matn","وَكَذَا حُكْمُ كُلِّ مَنْ أَعْتَقَ حِصَّتَهُ مِنْ مُشْتَرَكٍ فَلَوِ ادَّعَى كُلٌّ مِنْ مُوسِرَيْنِ أَنَّ شَرِيكَهُ أَعْتَقَ نَصِيبَهُ عَتَقَ لِاعْتِرَافِ كُلٍّ بِحُرِّيَّتِهِ وَيَحْلِفُ كُلٌّ لِصَاحِبِهِ وَوَلَاؤُهُ لِبَيْتِ الْمَالِ مَا لَمْ يَعْتَرِفْ أَحَدُهُمَا بِعِتْقِهِ فَيَثْبُتُ لَهُ وَيَضْمَنُ حَقَّ شَرِيكِهِ."]]},{"id":"da90_10","label":"كِتَابُ الْعِتْقِ · ١٠","segs":[["matn","فَصْلٌ: وَيَصِحُّ تَعْلِيقُ الْعِتْقِ بِالصِّفَةِ كَإِنْ فَعَلْتَ كَذَا فَأَنْتَ حُرٌّ وَلَهُ وَقْفُهُ وَكَذَا بَيْعُهُ وَنَحْوُهُ قَبْلَ وُجُودِ الصِّفَةِ فَإِنْ عَادَ لِمِلْكِهِ عَادَتْ فَمَتَى وُجِدَتْ عَتَقَ وَلَا يَبْطُلُ إِلَّا بِمَوْتِهِ فَقَوْلُهُ:"]]},{"id":"da90_11","label":"كِتَابُ الْعِتْقِ · ١١","segs":[["matn","إِنْ دَخَلْتَ الدَّارَ بَعْدَ مَوْتِي فَأَنْتَ حُرٌّ لَغْوٌ وَيَصِحُّ: أَنْتَ حُرٌّ بَعْدَ مَوْتِي بِشَهْرٍ فَلَا يَمْلِكُ الْوَارِثُ بَيْعَهُ."]]},{"id":"da90_12","label":"كِتَابُ الْعِتْقِ · ١٢","segs":[["matn","وَيَصِحُّ قَوْلُهُ: كُلُّ مَمْلُوكٍ أَمْلِكُهُ فَهُوَ حُرٌّ فَكُلُّ مَنْ مَلَكَهُ عَتَقَ وَأَوَّلُ أَوْ آخِرُ قِنٍّ أَمْلِكُهُ وَأَوَّلُ أَوْ آخِرُ مَنْ يَطْلُعُ مِنْ رَقِيقِي حُرٌّ"]]},{"id":"da90_13","label":"كِتَابُ الْعِتْقِ · ١٣","segs":[["matn","فَلَمْ يُمْلَكْ أَوْ يَطْلُعْ إِلَّا وَاحِدٌ عَتَقَ وَلَوْ مَلَكَ اثْنَيْنِ مَعًا أَوْ طَلَعَا مَعًا عَتَقَ وَاحِدٌ بِقُرْعَةٍ وَمِثْلُهُ الطَّلَاقُ."]]},{"id":"da90_14","label":"كِتَابُ الْعِتْقِ · ١٤","segs":[["matn","فَصْلٌ: وَإِنْ قَالَ لِرَقِيقِهِ: أَنْتَ حُرٌّ وَعَلَيْكَ أَلْفٌ عَتَقَ فِي الْحَالِ بِلَا شَيْءٍ وَعَلَى أَلْفٍ أَوْ بِأَلْفٍ لَا يَعْتِقُ حَتَّى يَقْبَلَ وَيَلْزَمُهُ الْأَلْفُ وَعَلَى أَنْ تَخْدُمَنِي سَنَةً يَعْتِقُ بِلَا قَبُولٍ وَتَلْزَمُهُ الْخِدْمَةُ."]]},{"id":"da90_15","label":"كِتَابُ الْعِتْقِ · ١٥","segs":[["matn","وَيَصِحُّ أَنْ يُعْتِقَهُ وَيَسْتَثْنِيَ خِدْمَتَهُ مُدَّةَ حَيَاتِهِ أَوْ مُدَّةً مَعْلُومَةً. وَمَنْ قَالَ: رَقِيقِي حُرٌّ أَوْ زَوْجَتِي طَالِقٌ وَلَهُ مُتَعَدِّدٌ وَلَمْ يَنْوِ مُعَيَّنًا عَتَقَ وَطَلَقَ الْكُلُّ لِأَنَّهُ مُفْرَدٌ مُضَافٌ فَيَعُمُّ."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"da91","title":"بَابُ التَّدْبِيرِ","units":[{"id":"da91_1","label":"بَابُ التَّدْبِيرِ · ١","segs":[["matn","وَهُوَ: تَعْلِيقُ الْعِتْقِ بِالْمَوْتِ كَقَوْلِهِ لِرَقِيقِهِ: إِنْ مِتُّ فَأَنْتَ حُرٌّ بَعْدَ مَوْتِي وَيُعْتَبَرُ كَوْنُهُ مِمَّنْ تَصِحُّ وَصِيَّتُهُ وَكَوْنُهُ مِنَ الثُّلُثِ. وَصَرِيحُهُ وَكِنَايَتُهُ كَالْعِتْقِ. وَيَصِحُّ مُطْلَقًا كَأَنْتَ مُدَبَّرٌ."]]},{"id":"da91_2","label":"بَابُ التَّدْبِيرِ · ٢","segs":[["matn","وَمُقَيَّدًا كَإِنْ مِتُّ فِي عَامِي أَوْ مَرَضِي هَذَا فَأَنْتَ مُدَبَّرٌ. وَمُعَلَّقًا كَإِذَا قَدِمَ زَيْدٌ فَأَنْتَ مُدَبَّرٌ. وَمُؤَقَّتًا كَأَنْتَ مُدَبَّرٌ الْيَوْمَ أَوْ سَنَةً. وَيَصِحُّ بَيْعُ الْمُدَبَّرِ وَهِبَتُهُ."]]},{"id":"da91_3","label":"بَابُ التَّدْبِيرِ · ٣","segs":[["matn","فَإِنْ عَادَ لِمِلْكِهِ عَادَ التَّدْبِيرُ. وَيَبْطُلُ بِثَلَاثَةِ أَشْيَاءَ: بِوَقْفِهِ وَبِقَتْلِهِ لِسَيِّدِهِ وَبِإِيلَادِ الْأَمَةِ. وَوَلَدُ الْمُدَبَّرَةِ الَّذِي يُولَدُ بَعْدَ التَّدْبِيرِ كَهِيَ. وَلَهُ وَطْؤُهَا وَإِنْ لَمْ يَشْتَرِطْهُ وَوَطْءُ بِنْتِهَا إِنْ جَازَ."]]},{"id":"da91_4","label":"بَابُ التَّدْبِيرِ · ٤","segs":[["matn","وَلَوْ أَسْلَمَ مُدَبَّرٌ أَوْ قِنٌّ أَوْ مُكَاتَبٌ لِكَافِرٍ أُلْزِمَ بِإِزَالَةِ مِلْكِهِ فَإِنْ أَبَى بِيعَ عَلَيْهِ."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"da92","title":"بَابُ الْكِتَابَةِ","units":[{"id":"da92_1","label":"بَابُ الْكِتَابَةِ · ١","segs":[["matn","وَهِيَ: بَيْعُ السَّيِّدِ رَقِيقَهُ نَفْسَهُ بِمَالٍ فِي ذِمَّتِهِ مُبَاحٍ مَعْلُومٍ يَصِحُّ السَّلَمُ فِيهِ مُنَجَّمٍ بِنَجْمَيْنِ فَصَاعِدًا يُعْلَمُ قَدْرُ كُلِّ نَجْمٍ وَمُدَّتُهُ وَلَا يُشْتَرَطُ أَجَلٌ لَهُ وَقْعٌ فِي الْقُدْرَةِ عَلَى الْكَسْبِ."]]},{"id":"da92_2","label":"بَابُ الْكِتَابَةِ · ٢","segs":[["matn","فَإِنْ فُقِدَ شَيْءٌ مِنْ هَذَا فَفَاسِدَةٌ. وَالْكِتَابَةُ فِي الصِّحَّةِ وَالْمَرَضِ مِنْ رَأْسِ الْمَالِ. وَلَا تَصِحُّ إِلَّا بِالْقَوْلِ مِنْ جَائِزِ التَّصَرُّفِ لَكِنْ لَوْ كُوتِبَ الْمُمَيِّزُ صَحَّ."]]},{"id":"da92_3","label":"بَابُ الْكِتَابَةِ · ٣","segs":[["matn","وَمَتَى أَدَّى الْمُكَاتَبُ مَا عَلَيْهِ لِسَيِّدِهِ أَوْ أَبْرَأَهُ مِنْهُ عَتَقَ وَمَا فَضَلَ بِيَدِهِ فَلَهُ."]]},{"id":"da92_4","label":"بَابُ الْكِتَابَةِ · ٤","segs":[["matn","وَإِنْ أَعْتَقَهُ سَيِّدُهُ وَعَلَيْهِ شَيْءٌ مِنْ مَالِ الْكِتَابَةِ أَوْ مَاتَ قَبْلَ وَفَائِهَا كَانَ جَمِيعُ مَا مَعَهُ لِسَيِّدِهِ."]]},{"id":"da92_5","label":"بَابُ الْكِتَابَةِ · ٥","segs":[["matn","وَلَوْ أَخَذَ السَّيِّدُ حَقَّهُ ظَاهِرًا ثُمَّ قَالَ: هُوَ حُرٌّ ثُمَّ بَانَ الْعِوَضُ مُسْتَحَقًّا لَمْ يَعْتِقْ."]]},{"id":"da92_6","label":"بَابُ الْكِتَابَةِ · ٦","segs":[["matn","فَصْلٌ: وَيَمْلِكُ الْمُكَاتَبُ كَسْبَهُ وَنَفْعَهُ وَكُلَّ تَصَرُّفٍ يُصْلِحُ مَالَهُ: كَالْبَيْعِ وَالشِّرَاءِ وَالْإِجَارَةِ وَالِاسْتِدَانَةِ وَالنَّفَقَةِ عَلَى نَفْسِهِ وَمَمْلُوكِهِ."]]},{"id":"da92_7","label":"بَابُ الْكِتَابَةِ · ٧","segs":[["matn","لَكِنْ مِلْكُهُ غَيْرُ تَامٍّ فَلَا يَمْلِكُ أَنْ يُكَفِّرَ بِمَالٍ أَوْ يُسَافِرَ لِجِهَادٍ أَوْ يَتَزَوَّجَ أَوْ يَتَسَرَّى أَوْ يَتَبَرَّعَ أَوْ يُقْرِضَ أَوْ يُحَابِيَ أَوْ يَرْهَنَ أَوْ يُضَارِبَ أَوْ يَبِيعَ مُؤَجَّلًا أَوْ يُزَوِّجَ رَقِيقَهُ أَوْ يَحُدَّهُ أَوْ يُكَاتِبَهُ إِلَّا بِإِذْنِ سَيِّدِهِ وَالْوَلَاءُ لِلسَّيِّدِ."]]},{"id":"da92_8","label":"بَابُ الْكِتَابَةِ · ٨","segs":[["matn","وَوَلَدُ الْمُكَاتَبَةِ إِذَا وَضَعَتْهُ بَعْدَهَا يَتْبَعُهَا فِي الْعِتْقِ بِالْأَدَاءِ وَالْإِبْرَاءِ لَا بِإِعْتَاقِهَا وَلَا إِنْ مَاتَتْ. وَيَصِحُّ شَرْطُ وَطْءِ مُكَاتَبَتِهِ."]]},{"id":"da92_9","label":"بَابُ الْكِتَابَةِ · ٩","segs":[["matn","فَإِنْ وَطِئَهَا بِلَا شَرْطٍ عُزِّرَ وَلَزِمَهُ الْمَهْرُ وَلَوْ مُطَاوِعَةً وَتَصِيرُ إِنْ وَلَدَتْ أُمَّ وَلَدٍ ثُمَّ إِنْ أَدَّتْ عَتَقَتْ وَإِلَّا فَبِمَوْتِهِ. وَيَصِحُّ نَقْلُ الْمِلْكِ فِي الْمُكَاتَبِ."]]},{"id":"da92_10","label":"بَابُ الْكِتَابَةِ · ١٠","segs":[["matn","وَلِمُشْتَرٍ جَهِلَ الْكِتَابَةَ الرَّدُّ أَوِ الْأَرْشُ. وَهُوَ كَالْبَائِعِ فِي أَنَّهُ إِذَا أَدَّى مَا عَلَيْهِ يَعْتِقُ وَلَهُ. الْوَلَاءُ وَيَصِحُّ وَقْفُهُ فَإِذَا أَدَّى بَطَلَ الْوَقْفُ."]]},{"id":"da92_11","label":"بَابُ الْكِتَابَةِ · ١١","segs":[["matn","فَصْلٌ: وَالْكِتَابَةُ عَقْدٌ لَازِمٌ مِنَ الطَّرَفَيْنِ لَا يَدْخُلُهَا خِيَارٌ مُطْلَقًا وَلَا تَنْفَسِخُ بِمَوْتِ السَّيِّدِ وَجُنُونِهِ وَلَا بِحَجْرٍ عَلَيْهِ. وَيُعْتَقُ بِالْأَدَاءِ إِلَى مَنْ يَقُومُ مَقَامَهُ."]]},{"id":"da92_12","label":"بَابُ الْكِتَابَةِ · ١٢","segs":[["matn","وَإِنْ حَلَّ نَجْمٌ فَلَمْ يُؤَدِّهِ فَلِسَيِّدِهِ الْفَسْخُ. وَيَلْزَمُ إِنْظَارُهُ ثَلَاثًا لِبَيْعِ عَرْضٍ وَلِمَالٍ غَائِبٍ دُونَ مَسَافَةِ قَصْرٍ يَرْجُو قُدُومَهُ. وَيَجِبُ: عَلَى السَّيِّدِ أَنْ يَدْفَعَ لِلْمُكَاتَبِ رُبْعَ مَالِ الْكِتَابَةِ."]]},{"id":"da92_13","label":"بَابُ الْكِتَابَةِ · ١٣","segs":[["matn","وَلِلسَّيِّدِ الْفَسْخُ بِعَجْزِهِ عَنْ رُبْعِهَا. وَلِلْمُكَاتَبِ وَلَوْ قَادِرًا عَلَى التَّكَسُّبِ تَعْجِيزُ نَفْسِهِ. وَيَصِحُّ فَسْخُ الْكِتَابَةِ بِاتِّفَاقِهِمَا."]]},{"id":"da92_14","label":"بَابُ الْكِتَابَةِ · ١٤","segs":[["matn","فَصْلٌ: وَإِنِ اخْتَلَفَا فِي الْكِتَابَةِ فَقَوْلُ الْمُنْكِرِ وَفِي قَدْرِ عِوَضِهَا أَوْ جِنْسِهِ أَوْ أَجَلِهَا أَوْ وَفَاءِ مَالِهَا فَقَوْلُ السَّيِّدِ."]]},{"id":"da92_15","label":"بَابُ الْكِتَابَةِ · ١٥","segs":[["matn","وَالْكِتَابَةُ الْفَاسِدَةُ: كَعَلَى خَمْرٍ أَوْ خِنْزِيرٍ أَوْ مَجْهُولٍ يُغَلَّبُ فِيهَا حُكْمُ الصِّفَةِ فِي أَنَّهُ إِذَا أَدَّى عَتَقَ لَا إِنْ أُبْرِئَ وَلِكُلٍّ فَسْخُهَا وَتَنْفَسِخُ بِمَوْتِ السَّيِّدِ وَجُنُونِهِ وَالْحَجْرِ عَلَيْهِ."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"da93","title":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ","units":[{"id":"da93_1","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ١","segs":[["matn","وَهِيَ: مَنْ وَلَدَتْ مِنَ الْمَالِكِ مَا فِيهِ صُورَةٌ وَلَوْ خَفِيَّةً. وَتَعْتِقُ بِمَوْتِهِ وَإِنْ لَمْ يَمْلِكْ غَيْرَهَا. وَمَنْ مَلَكَ حَامِلًا فَوَطِئَهَا حَرُمَ بَيْعُ ذَلِكَ الْوَلَدِ وَيَلْزَمُ: عِتْقُهُ."]]},{"id":"da93_2","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ٢","segs":[["matn","وَمَنْ قَالَ لِأَمَتِهِ: أَنْتِ أُمُّ وَلَدِي أَوْ: يَدُكِ أُمُّ وَلَدِي صَارَتْ أُمَّ وَلَدٍ وَكَذَا لَوْ قَالَ لِابْنِهَا: أَنْتَ ابْنِي أَوْ يَدُكَ ابْنِي وَيَثْبُتُ النَّسَبُ."]]},{"id":"da93_3","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ٣","segs":[["matn","فَإِنْ مَاتَ وَلَمْ يُبَيِّنْ هَلْ حَمَلَتْ بِهِ فِي مِلْكِهِ أَوْ غَيْرِهِ لَمْ تَصِرْ أُمَّ وَلَدٍ إِلَّا بِقَرِينَةٍ."]]},{"id":"da93_4","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ٤","segs":[["matn","وَلَا يَبْطُلُ الْإِيلَادُ بِحَالٍ وَلَوْ بِقَتْلِهَا لِسَيِّدِهَا وَوَلَدُهَا الْحَادِثُ بَعْدَ إِيلَادِهَا كَهِيَ لَكِنْ لَا يَعْتِقُ بِإِعْتَاقِهَا أَوْ مَوْتِهَا قَبْلَ السَّيِّدِ بَلْ بِمَوْتِهِ."]]},{"id":"da93_5","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ٥","segs":[["matn","وَإِنْ مَاتَ سَيِّدُهَا وَهِيَ حَامِلٌ فَنَفَقَتُهَا مُدَّةَ حَمْلِهَا مِنْ مَالِهِ إِنْ كَانَ وَإِلَّا فَعَلَى وَارِثِهِ. وَكُلَّمَا جَنَتْ أُمُّ الْوَلَدِ لَزِمَ السَّيِّدَ فِدَاؤُهَا بِالْأَقَلِّ مِنَ الْأَرْشِ أَوْ قِيمَتِهَا يَوْمَ الْفِدَاءِ."]]},{"id":"da93_6","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ٦","segs":[["matn","وَإِنِ اجْتَمَعَتْ أُرُوشٌ قَبْلَ إِعْطَاءِ شَيْءٍ مِنْهَا تَعَلَّقَ الْجَمِيعُ بِرَقَبَتِهَا وَلَمْ يَكُنْ عَلَى السَّيِّدِ إِلَّا الْأَقَلُّ مِنْ أَرْشِ الْجَمِيعِ أَوْ قِيمَتِهَا وَيَتَحَاصُّونَ بِقَدْرِ حُقُوقِهِمْ."]]},{"id":"da93_7","label":"بَابُ أَحْكَامِ أُمِّ الْوَلَدِ · ٧","segs":[["matn","وَإِنْ أَسْلَمَتْ أُمُّ وَلَدٍ لِكَافِرٍ مُنِعَ مِنْ غِشْيَانِهَا وَحِيلَ بَيْنَهُ وَبَيْنَهَا وَأُجْبِرَ عَلَى نَفَقَتِهَا إِنْ عُدِمَ كَسْبُهَا. فَإِنْ أَسْلَمَ حَلَّتْ لَهُ وَإِنْ مَاتَ كَافِرًا عَتَقَتْ."]]}],"group":"كِتَابُ الْعِتْقِ"},{"id":"da94","title":"كِتَابُ النِّكَاحِ","units":[{"id":"da94_1","label":"كِتَابُ النِّكَاحِ · ١","segs":[["matn","يُسَنُّ: لِذِي شَهْوَةٍ لَا يَخَافُ الزِّنَا وَيَجِبُ: عَلَى مَنْ يَخَافُهُ وَيُبَاحُ لِمَنْ لَا شَهْوَةَ لَهُ وَيَحْرُمُ بِدَارِ الْحَرْبِ لِغَيْرِ ضَرُورَةٍ."]]},{"id":"da94_2","label":"كِتَابُ النِّكَاحِ · ٢","segs":[["matn","وَيُسَنُّ نِكَاحُ ذَاتِ الدِّينِ الْوَلُودِ الْبِكْرِ الْحَسِيبَةِ الْأَجْنَبِيَّةِ وَيَجِبُ غَضُّ الْبَصَرِ عَنْ كُلِّ مَا حَرَّمَ اللَّهُ تَعَالَى فَلَا يَنْظُرُ إِلَّا مَا وَرَدَ الشَّرْعُ بِجَوَازِهِ."]]},{"id":"da94_3","label":"كِتَابُ النِّكَاحِ · ٣","segs":[["matn","وَالنَّظَرُ ثَمَانِيَةُ أَقْسَامٍ: الْأَوَّلُ: نَظَرُ الرَّجُلِ الْبَالِغِ وَلَوْ مَجْبُوبًا لِلْحُرَّةِ الْبَالِغَةِ الْأَجْنَبِيَّةِ لِغَيْرِ حَاجَةٍ فَلَا يَجُوزُ لَهُ نَظَرُ شَيْءٍ مِنْهَا حَتَّى شَعْرِهَا الْمُتَّصِلِ."]]},{"id":"da94_4","label":"كِتَابُ النِّكَاحِ · ٤","segs":[["matn","الثَّانِي: نَظَرُهُ لِمَنْ لَا تُشْتَهَى: كَعَجُوزٍ وَقَبِيحَةٍ فَيَجُوزُ لِوَجْهِهَا خَاصَّةً. الثَّالِثُ: نَظَرُهُ لِلشَّهَادَةِ عَلَيْهَا أَوْ لِمُعَامَلَتِهَا فَيَجُوزُ لِوَجْهِهَا وَكَذَا كَفَّيْهَا لِحَاجَةٍ."]]},{"id":"da94_5","label":"كِتَابُ النِّكَاحِ · ٥","segs":[["matn","الرَّابِعُ: نَظَرُهُ لِحُرَّةٍ بَالِغَةٍ يَخْطُبُهَا فَيَجُوزُ لِلْوَجْهِ وَالرَّقَبَةِ وَالْيَدِ وَالْقَدَمِ."]]},{"id":"da94_6","label":"كِتَابُ النِّكَاحِ · ٦","segs":[["matn","الْخَامِسُ: نَظَرُهُ إِلَى ذَوَاتِ مَحَارِمِهِ أَوْ لِبِنْتِ تِسْعٍ أَوْ أَمَةٍ لَا يَمْلِكُهَا أَوْ يَمْلِكُ بَعْضَهَا أَوْ كَانَ لَا شَهْوَةَ لَهُ كَعِنِّينٍ أَوْ كَبِيرٍ أَوْ كَانَ مُمَيِّزًا وَلَهُ شَهْوَةٌ أَوْ رَقِيقًا غَيْرَ مُبَعَّضٍ وَمُشْتَرَكٍ وَنَظَرُهُ لِسَيِّدَتِهِ فَيَجُوزُ لِلْوَجْهِ وَالرَّقَبَةِ وَالْيَدِ وَالْقَدَمِ وَالرَّأْسِ وَالسَّاقِ."]]},{"id":"da94_7","label":"كِتَابُ النِّكَاحِ · ٧","segs":[["matn","السَّادِسُ: نَظَرُهُ لِلْمُدَاوَاةِ فَيَجُوزُ لِلْمَوَاضِعِ الَّتِي يُحْتَاجُ إِلَيْهَا."]]},{"id":"da94_8","label":"كِتَابُ النِّكَاحِ · ٨","segs":[["matn","السَّابِعُ: نَظَرُهُ لِأَمَتِهِ الْمُحَرَّمَةِ وَلِحُرَّةٍ مُمَيِّزَةٍ دُونَ تِسْعٍ وَنَظَرُ الْمَرْأَةِ لِلْمَرْأَةِ وَلِلرَّجُلِ الْأَجْنَبِيِّ وَنَظَرُ الْمُمَيِّزِ الَّذِي لَا شَهْوَةَ لَهُ لِلْمَرْأَةِ وَنَظَرُ الرَّجُلِ لِلرَّجُلِ وَلَوْ أَمْرَدَ فَيَجُوزُ إِلَى مَا عَدَا مَا بَيْنَ السُّرَّةِ وَالرُّكْبَةِ."]]},{"id":"da94_9","label":"كِتَابُ النِّكَاحِ · ٩","segs":[["matn","الثَّامِنُ: نَظَرُهُ لِزَوْجَتِهِ وَأَمَتِهِ الْمُبَاحَةِ لَهُ وَلَوْ لِشَهْوَةٍ وَنَظَرُ مَنْ دُونَ سَبْعٍ فَيَجُوزُ لِكُلٍّ نَظَرُ جَمِيعِ بَدَنِ الْآخَرِ."]]},{"id":"da94_10","label":"كِتَابُ النِّكَاحِ · ١٠","segs":[["matn","فَصْلٌ: وَيَحْرُمُ: النَّظَرُ لِشَهْوَةٍ أَوْ مَعَ خَوْفِ ثَوَرَانِهَا إِلَى أَحَدٍ مِمَّنْ ذَكَرْنَا. وَلَمْسٌ كَنَظَرٍ وَأَوْلَى. وَيَحْرُمُ: التَّلَذُّذُ بِصَوْتِ الْأَجْنَبِيَّةِ وَلَوْ بِقِرَاءَةٍ. وَتَحْرُمُ خَلْوَةُ رَجُلٍ غَيْرِ مَحْرَمٍ بِالنِّسَاءِ وَعَكْسُهُ."]]},{"id":"da94_11","label":"كِتَابُ النِّكَاحِ · ١١","segs":[["matn","وَيَحْرُمُ التَّصْرِيحُ بِخِطْبَةِ الْمُعْتَدَّةِ الْبَائِنِ لَا التَّعْرِيضُ إِلَّا بِخِطْبَةِ الرَّجْعِيَّةِ. وَتَحْرُمُ خِطْبَةٌ عَلَى خِطْبَةِ مُسْلِمٍ أُجِيبَ وَيَصِحُّ الْعَقْدُ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"da95","title":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ","units":[{"id":"da95_1","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١","segs":[["matn","رُكْنَاهُ: الْإِيجَابُ وَالْقَبُولُ مُرَتَّبَيْنِ. وَيَصِحُّ النِّكَاحُ هَزْلًا وَبِكُلِّ لِسَانٍ مِنْ عَاجِزٍ عَنْ عَرَبِيٍّ لَا بِالْكِتَابَةِ وَالْإِشَارَةِ إِلَّا مِنْ أَخْرَسَ."]]},{"id":"da95_2","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٢","segs":[["matn","وَشُرُوطُهُ خَمْسَةٌ: تَعْيِينُ الزَّوْجَيْنِ: فَلَا يَصِحُّ: زَوَّجْتُكَ بِنْتِي وَلَهُ غَيْرُهَا وَلَا: قَبِلْتُ نِكَاحَهَا لِابْنِي وَلَهُ غَيْرُهُ حَتَّى يُمَيِّزَ كُلٌّ مِنْهُمَا بِاسْمِهِ أَوْ صِفَتِهِ."]]},{"id":"da95_3","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٣","segs":[["matn","الثَّانِي: رِضَى زَوْجٍ مُكَلَّفٍ وَلَوْ رَقِيقًا فَيُجْبِرُ الْأَبُ لَا الْجَدُّ غَيْرَ الْمُكَلَّفِ فَإِنْ لَمْ يَكُنْ فَوَصِيُّهُ فَإِنْ لَمْ يَكُنْ فَالْحَاكِمُ لِحَاجَةٍ وَلَا يَصِحُّ مِنْ غَيْرِهِمْ أَنْ يُزَوِّجَ غَيْرَ الْمُكَلَّفِ وَلَوْ رَضِيَ."]]},{"id":"da95_4","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٤","segs":[["matn","وَرِضَى زَوْجَةٍ حُرَّةٍ عَاقِلَةٍ ثَيِّبٍ تَمَّ لَهَا تِسْعُ سِنِينَ وَيُجْبِرُ الْأَبُ ثَيِّبًا دُونَ ذَلِكَ وَبِكْرًا وَلَوْ بَالِغَةً."]]},{"id":"da95_5","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٥","segs":[["matn","وَلِكُلِّ وَلِيٍّ تَزْوِيجُ يَتِيمَةٍ بَلَغَتْ تِسْعًا بِإِذْنِهَا لَا مَنْ دُونَهَا بِحَالٍ إِلَّا وَصِيَّ أَبِيهَا."]]},{"id":"da95_6","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٦","segs":[["matn","وَإِذْنُ الثَّيِّبِ: الْكَلَامُ وَإِذْنُ الْبِكْرِ الصُّمَاتُ وَشُرِطَ فِي اسْتِئْذَانِهَا: تَسْمِيَةُ الزَّوْجِ لَهَا عَلَى وَجْهٍ تَقَعُ بِهِ الْمَعْرِفَةُ وَيُجْبِرُ السَّيِّدُ وَلَوْ فَاسِقًا عَبْدَهُ غَيْرَ الْمُكَلَّفِ وَأَمَتَهُ وَلَوْ مُكَلَّفَةً."]]},{"id":"da95_7","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٧","segs":[["matn","الثَّالِثُ: الْوَلِيُّ وَشُرِطَ فِيهِ ذُكُورِيَّةٌ وَعَقْلٌ وَبُلُوغٌ وَحُرِّيَّةٌ وَاتِّفَاقُ دِينٍ وَعَدَالَةٌ وَلَوْ ظَاهِرَةً وَرُشْدٌ وَهُوَ مَعْرِفَةُ الْكُفْءِ وَمَصَالِحِ النِّكَاحِ."]]},{"id":"da95_8","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٨","segs":[["matn","وَالْأَحَقُّ بِتَزْوِيجِ الْحُرَّةِ أَبُوهَا وَإِنْ عَلَا فَابْنُهَا وَإِنْ نَزَلَ فَالْأَخُ الشَّقِيقُ فَالْأَخُ لِلْأَبِ ثُمَّ الْأَقْرَبُ فَالْأَقْرَبُ كَالْإِرْثِ ثُمَّ السُّلْطَانُ أَوْ نَائِبُهُ فَإِنْ عُدِمَ الْكُلُّ زَوَّجَهَا ذُو سُلْطَانٍ فِي مَكَانِهَا فَإِنْ تَعَذَّرَ وَكَّلَتْ مَنْ يُزَوِّجُهَا."]]},{"id":"da95_9","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٩","segs":[["matn","فَلَوْ زَوَّجَ الْحَاكِمُ أَوِ الْوَلِيُّ الْأَبْعَدُ بِلَا عُذْرٍ لِلْأَقْرَبِ لَمْ يَصِحَّ."]]},{"id":"da95_10","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٠","segs":[["matn","وَمِنَ الْعُذْرِ غَيْبَةُ الْوَلِيِّ فَوْقَ مَسَافَةِ قَصْرٍ أَوْ تُجْهَلَ الْمَسَافَةُ أَوْ يُجْهَلَ مَكَانُهُ مَعَ قُرْبِهِ أَوْ يَمْنَعَ مَنْ بَلَغَتْ تِسْعًا كُفْؤًا رَضِيَتْهُ."]]},{"id":"da95_11","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١١","segs":[["matn","فَصْلٌ: وَوَكِيلُ الْوَلِيِّ يَقُومُ مَقَامَهُ وَلَهُ أَنْ يُوَكِّلَ بِدُونِ إِذْنِهَا لَكِنْ لَا بُدَّ مِنْ إِذْنِ غَيْرِ الْمُجْبَرَةِ لِلْوَكِيلِ بَعْدَ تَوْكِيلِهِ."]]},{"id":"da95_12","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٢","segs":[["matn","وَيُشْتَرَطُ فِي وَكِيلِ الْوَلِيِّ مَا يُشْتَرَطُ فِيهِ وَيَصِحُّ تَوْكِيلُ الْفَاسِقِ فِي الْقَبُولِ. وَيَصِحُّ التَّوْكِيلُ مُطْلَقًا."]]},{"id":"da95_13","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٣","segs":[["matn","كَزَوِّجْ مَنْ شِئْتَ وَيَتَقَيَّدُ بِالْكُفْءِ وَمُقَيَّدًا كَزَوِّجْ زَيْدًا وَيُشْتَرَطُ قَوْلُ الْوَلِيِّ أَوْ وَكِيلِهِ: زَوَّجْتُ فُلَانَةَ فُلَانًا أَوْ لِفُلَانٍ وَقَوْلُ وَكِيلِ الزَّوْجِ: قَبِلْتُهُ لِمُوَكِّلِي فُلَانًا أَوْ لِفُلَانٍ."]]},{"id":"da95_14","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٤","segs":[["matn","وَوَصِيُّ الْوَلِيِّ فِي النِّكَاحِ بِمَنْزِلَتِهِ فَيَجْبُرُ مَنْ يَجْبُرُهُ مِنْ ذَكَرٍ وَأُنْثَى."]]},{"id":"da95_15","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٥","segs":[["matn","وَإِنِ اسْتَوَى وَلِيَّانِ فَأَكْثَرُ فِي دَرَجَةٍ صَحَّ التَّزْوِيجُ مِنْ كُلِّ وَاحِدٍ إِنْ أَذِنَتْ لَهُمْ فَإِنْ أَذِنَتْ لِأَحَدِهِمْ تَعَيَّنَ وَلَمْ يَصِحَّ نِكَاحُ غَيْرِهِ."]]},{"id":"da95_16","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٦","segs":[["matn","وَمَنْ زَوَّجَ بِحَضْرَةِ شَاهِدَيْنِ عَبْدَهُ الصَّغِيرَ بِأَمَتِهِ أَوْ زَوَّجَ ابْنَهُ بِنَحْوِ بِنْتِ أَخِيهِ أَوْ وَكَّلَ الزَّوْجُ الْوَلِيَّ أَوْ عَكْسُهُ أَوْ وَكَّلَا وَاحِدًا صَحَّ أَنْ يَتَوَلَّى طَرَفَيِ الْعَقْدِ وَيَكْفِي: زَوَّجْتُ فُلَانًا فُلَانَةَ أَوْ: تَزَوَّجْتُهَا إِنْ كَانَ هُوَ الزَّوْجَ."]]},{"id":"da95_17","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٧","segs":[["matn","وَمَنْ قَالَ لِأَمَتِهِ: أَعْتَقْتُكِ وَجَعَلْتُ عِتْقَكِ صَدَاقَكِ عَتَقَتْ وَصَارَتْ زَوْجَةً لَهُ إِنْ تَوَفَّرَتْ شُرُوطُ النِّكَاحِ."]]},{"id":"da95_18","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٨","segs":[["matn","الرَّابِعُ: الشَّهَادَةُ فَلَا يَنْعَقِدُ إِلَّا بِشَهَادَةِ ذَكَرَيْنِ مُكَلَّفَيْنِ وَلَوْ رَقِيقَيْنِ مُتَكَلِّمَيْنِ سَمِيعَيْنِ مُسْلِمَيْنِ عَدْلَيْنِ وَلَوْ ظَاهِرًا مِنْ غَيْرِ أَصْلَيِ الزَّوْجَيْنِ وَفَرْعَيْهِمَا."]]},{"id":"da95_19","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ١٩","segs":[["matn","الْخَامِسُ: خُلُوُّ الزَّوْجَيْنِ مِنَ الْمَوَانِعِ بِأَنْ لَا يَكُونَ بِهِمَا أَوْ بِأَحَدِهِمَا مَا يَمْنَعُ التَّزْوِيجَ مِنْ نَسَبٍ أَوْ سَبَبٍ."]]},{"id":"da95_20","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٢٠","segs":[["matn","وَالْكَفَاءَةُ لَيْسَتْ شَرْطًا لِصِحَّةِ النِّكَاحِ لَكِنْ لِمَنْ زُوِّجَتْ بِغَيْرِ كُفْءٍ أَنْ تَفْسَخَ نِكَاحَهَا وَلَوْ مُتَرَاخِيًا مَا لَمْ تَرْضَ بِقَوْلٍ أَوْ فِعْلٍ وَكَذَا لِأَوْلِيَائِهَا وَلَوْ رَضِيَتْ أَوْ رَضِيَ بَعْضُهُمْ فَلِمَنْ لَمْ يَرْضَ الْفَسْخُ."]]},{"id":"da95_21","label":"بَابُ رُكْنَيِ النِّكَاحِ وَشُرُوطِهِ · ٢١","segs":[["matn","وَلَوْ زَالَتِ الْكَفَاءَةُ بَعْدَ الْعَقْدِ فَلَهَا فَقَطِ الْفَسْخُ. وَالْكَفَاءَةُ مُعْتَبَرَةٌ فِي خَمْسَةِ أَشْيَاءَ: الدِّيَانَةُ وَالصِّنَاعَةُ وَالْمَيْسَرَةُ وَالْحُرِّيَّةُ وَالنَّسَبُ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"da96","title":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ","units":[{"id":"da96_1","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١","segs":[["matn","تَحْرُمُ أَبَدًا: الْأُمُّ وَالْجَدَّةُ مِنْ كُلِّ جِهَةٍ وَالْبِنْتُ وَلَوْ مِنْ زِنًا وَبِنْتُ الْوَلَدِ وَالْأُخْتُ مِنْ كُلِّ جِهَةٍ وَبِنْتُ وَلَدِهَا وَبِنْتُ كُلِّ أَخٍ وَبِنْتُ وَلَدِهَا وَالْعَمَّةُ وَالْخَالَةُ."]]},{"id":"da96_2","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٢","segs":[["matn","وَيَحْرُمُ بِالرَّضَاعِ مَا يَحْرُمُ بِالنَّسَبِ إِلَّا أُمَّ أَخِيهِ وَأُخْتَ ابْنِهِ مِنَ الرَّضَاعِ فَتَحِلُّ كَبِنْتِ عَمَّتِهِ وَعَمِّهِ وَبِنْتِ خَالَتِهِ وَخَالِهِ."]]},{"id":"da96_3","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٣","segs":[["matn","وَيَحْرُمُ أَبَدًا بِالْمُصَاهَرَةِ أَرْبَعٌ: ثَلَاثٌ بِمُجَرَّدِ الْعَقْدِ: زَوْجَةُ أَبِيهِ وَإِنْ عَلَا وَزَوْجَةُ ابْنِهِ وَإِنْ سَفَلَ وَأُمُّ زَوْجَتِهِ فَإِنْ وَطِئَهَا حَرُمَتْ عَلَيْهِ أَيْضًا بِنْتُهَا وَبِنْتُ ابْنِهَا."]]},{"id":"da96_4","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٤","segs":[["matn","وَبِغَيْرِ الْعَقْدِ لَا حُرْمَةَ إِلَّا بِالْوَطْءِ فِي قُبُلٍ أَوْ دُبُرٍ إِنْ كَانَ ابْنَ عَشْرٍ فِي بِنْتِ تِسْعٍ وَكَانَا حَيَّيْنِ. وَيَحْرُمُ بِوَطْءِ الذَّكَرِ مَا يَحْرُمُ بِوَطْءِ الْأُنْثَى."]]},{"id":"da96_5","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٥","segs":[["matn","وَلَا تَحْرُمُ أُمُّ وَلَا بِنْتُ زَوْجَةِ أَبِيهِ وَابْنِهِ."]]},{"id":"da96_6","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٦","segs":[["matn","فَصْلٌ: وَيَحْرُمُ الْجَمْعُ بَيْنَ الْأُخْتَيْنِ وَبَيْنَ الْمَرْأَةِ وَعَمَّتِهَا أَوْ خَالَتِهَا."]]},{"id":"da96_7","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٧","segs":[["matn","فَمَنْ تَزَوَّجَ نَحْوَ أُخْتَيْنِ فِي عَقْدٍ أَوْ عَقْدَيْنِ مَعًا لَمْ يَصِحَّ فَإِنْ جُهِلَ فَسَخَهُمَا حَاكِمٌ وَلِإِحْدَاهُمَا نِصْفُ مَهْرِهَا بِقُرْعَةٍ وَإِنْ وَقَعَ الْعَقْدُ مُرَتَّبًا صَحَّ الْأَوَّلُ فَقَطْ."]]},{"id":"da96_8","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٨","segs":[["matn","وَمَنْ مَلَكَ أُخْتَيْنِ أَوْ نَحْوَهُمَا صَحَّ وَلَهُ أَنْ يَطَأَ أَيَّتَهُمَا شَاءَ وَتَحْرُمُ الْأُخْرَى حَتَّى يُحَرِّمَ الْمَوْطُوءَةَ بِإِخْرَاجٍ عَنْ مِلْكِهِ أَوْ تَزْوِيجٍ بَعْدَ الِاسْتِبْرَاءِ."]]},{"id":"da96_9","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ٩","segs":[["matn","وَمَنْ وَطِئَ امْرَأَةً بِشُبْهَةٍ أَوْ زِنًا حَرُمَ فِي زَمَنِ عِدَّتِهَا نِكَاحُ أُخْتِهَا وَوَطْؤُهَا إِنْ كَانَتْ زَوْجَةً أَوْ أَمَةً. وَحَرُمَ أَنْ يَزِيدَ عَلَى ثَلَاثٍ غَيْرِهَا بِعَقْدٍ أَوْ وَطْءٍ."]]},{"id":"da96_10","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١٠","segs":[["matn","وَلَيْسَ لِحُرٍّ جَمْعُ أَكْثَرَ مِنْ أَرْبَعٍ وَلَا لِعَبْدٍ جَمْعُ أَكْثَرَ مِنْ ثِنْتَيْنِ وَلِمَنْ نِصْفُهُ حُرٌّ فَأَكْثَرُ جَمْعُ ثَلَاثٍ."]]},{"id":"da96_11","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١١","segs":[["matn","وَمَنْ طَلَّقَ وَاحِدَةً مِنْ نِهَايَةِ جَمْعِهِ حَرُمَ نِكَاحُهُ بَدَلَهَا حَتَّى تَنْقَضِيَ عِدَّتُهَا وَإِنْ مَاتَتْ فَلَا."]]},{"id":"da96_12","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١٢","segs":[["matn","فَصْلٌ: وَتَحْرُمُ الزَّانِيَةُ عَلَى الزَّانِي وَغَيْرِهِ حَتَّى تَتُوبَ وَتَنْقَضِيَ عِدَّتُهَا. وَتَحْرُمُ مُطَلَّقَتُهُ ثَلَاثًا حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ. وَالْمُحْرِمَةُ حَتَّى تَحِلَّ مِنْ إِحْرَامِهَا. وَالْمُسْلِمَةُ عَلَى الْكَافِرِ. وَالْكَافِرَةُ غَيْرُ الْكِتَابِيَّةِ عَلَى الْمُسْلِمِ."]]},{"id":"da96_13","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١٣","segs":[["matn","وَلَا يَحِلُّ لِحُرٍّ كَامِلِ الْحُرِّيَّةِ نِكَاحُ أَمَةٍ وَلَوْ مُبَعَّضَةً إِلَّا إِنْ عَدِمَ الطَّوْلَ وَخَافَ الْعَنَتَ. وَلَا يَكُونُ وَلَدُ الْأَمَةِ حُرًّا إِلَّا بِاشْتِرَاطِ الْحُرِّيَّةِ أَوِ الْغُرُورِ."]]},{"id":"da96_14","label":"بَابُ الْمُحَرَّمَاتِ فِي النِّكَاحِ · ١٤","segs":[["matn","وَإِنْ مَلَكَ أَحَدُ الزَّوْجَيْنِ الْآخَرَ أَوْ بَعْضَهُ انْفَسَخَ النِّكَاحُ. وَمَنْ جَمَعَ فِي عَقْدٍ بَيْنَ مُبَاحَةٍ وَمُحَرَّمَةٍ صَحَّ فِي الْمُبَاحَةِ. وَمَنْ حَرُمَ نِكَاحُهَا حَرُمَ وَطْؤُهَا بِالْمِلْكِ إِلَّا الْأَمَةَ الْكِتَابِيَّةَ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"da97","title":"بَابُ الشُّرُوطِ فِي النِّكَاحِ","units":[{"id":"da97_1","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ١","segs":[["matn","وَهِيَ قِسْمَانِ: صَحِيحٌ لَازِمٌ لِلزَّوْجِ فَلَيْسَ لَهُ فَكُّهُ:"]]},{"id":"da97_2","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٢","segs":[["matn","كَزِيَادَةِ مَهْرٍ أَوْ نَقْدٍ مُعَيَّنٍ أَوْ لَا يُخْرِجَهَا مِنْ دَارِهَا أَوْ بَلَدِهَا أَوْ لَا يَتَزَوَّجَ عَلَيْهَا أَوْ لَا يُفَرِّقَ بَيْنَهَا وَبَيْنَ أَبَوَيْهَا أَوْ أَوْلَادِهَا أَوْ أَنْ تُرْضِعَ"]]},{"id":"da97_3","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٣","segs":[["matn","وَلَدَهَا أَوْ يُطَلِّقَ ضَرَّتَهَا فَمَتَى لَمْ يَفِ بِمَا شُرِطَ كَانَ لَهَا الْفَسْخُ عَلَى التَّرَاخِي وَلَا يَسْقُطُ إِلَّا بِمَا يَدُلُّ عَلَى رِضَاهَا مِنْ قَوْلٍ أَوْ تَمْكِينٍ مَعَ الْعِلْمِ."]]},{"id":"da97_4","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٤","segs":[["matn","وَالْقِسْمُ الْفَاسِدُ نَوْعَانِ: نَوْعٌ يُبْطِلُ النِّكَاحَ وَهُوَ: أَنْ يُزَوِّجَهُ مَوْلِيَّتَهُ بِشَرْطِ أَنْ يُزَوِّجَهُ الْآخَرُ مَوْلِيَّتَهُ وَلَا مَهْرَ بَيْنَهُمَا أَوْ يَجْعَلَ بُضْعَ كُلِّ وَاحِدَةٍ مَعَ دَرَاهِمَ مَعْلُومَةٍ مَهْرًا لِلْأُخْرَى أَوْ يَتَزَوَّجَهَا بِشَرْطِ أَنَّهُ:"]]},{"id":"da97_5","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٥","segs":[["matn","إِذَا أَحَلَّهَا طَلَّقَهَا أَوْ يَنْوِيَهُ بِقَلْبِهِ أَوْ يَتَّفِقَا عَلَيْهِ قَبْلَ الْعَقْدِ أَوْ يَتَزَوَّجَهَا إِلَى مُدَّةٍ أَوْ يَشْتَرِطَ طَلَاقَهَا"]]},{"id":"da97_6","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٦","segs":[["matn","فِي الْعَقْدِ بِوَقْتِ كَذَا أَوْ يَنْوِيَهُ بِقَلْبِهِ أَوْ يَتَزَوَّجَ الْغَرِيبُ بِنِيَّةِ طَلَاقِهَا إِذَا خَرَجَ أَوْ يُعَلِّقَ نِكَاحَهَا كَزَوَّجْتُكَ إِذَا جَاءَ رَأْسُ الشَّهْرِ أَوْ إِنْ رَضِيَتْ أُمُّهَا أَوْ إِنْ وَضَعَتْ زَوْجَتِي ابْنَةً فَقَدْ زَوَّجْتُكَهَا الثَّانِي:"]]},{"id":"da97_7","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٧","segs":[["matn","لَا يُبْطِلُهُ كَأَنْ يَشْرُطَ أَنْ لَا مَهْرَ لَهَا أَوْ لَا نَفَقَةَ أَوْ أَنْ يَقْسِمَ لَهَا أَكْثَرَ مِنْ ضَرَّتِهَا أَوْ أَقَلَّ أَوْ إِنْ فَارَقَهَا رَجَعَ عَلَيْهَا بِمَا أَنْفَقَ فَيَصِحُّ النِّكَاحُ دُونَ الشَّرْطِ."]]},{"id":"da97_8","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٨","segs":[["matn","فَصْلٌ: وَإِنْ شَرَطَهَا مُسْلِمَةً فَبَانَتْ كِتَابِيَّةً أَوْ شَرَطَهَا بِكْرًا أَوْ جَمِيلَةً أَوْ نَسِيبَةً أَوْ شَرَطَ نَفْيَ عَيْبٍ فَبَانَتْ بِخِلَافِهِ فَلَهُ الْخِيَارُ لَا إِنْ شَرَطَهَا أَدْنَى فَبَانَتْ أَعْلَى."]]},{"id":"da97_9","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ٩","segs":[["matn","وَمَنْ تَزَوَّجَتْ رَجُلًا عَلَى أَنَّهُ حُرٌّ. فَبَانَ عَبْدًا فَلَهَا الْخِيَارُ. وَإِنْ شَرَطَتْ فِيهِ صِفَةً فَبَانَ أَقَلَّ فَلَا فَسْخَ لَهَا. وَتَمْلِكُ الْفَسْخَ مَنْ عَتَقَتْ كُلُّهَا تَحْتَ رَقِيقٍ كُلِّهِ بِغَيْرِ حُكْمِ الْحَاكِمِ."]]},{"id":"da97_10","label":"بَابُ الشُّرُوطِ فِي النِّكَاحِ · ١٠","segs":[["matn","فَإِنْ مَكَّنَتْهُ مِنْ وَطْئِهَا أَوْ مُبَاشَرَتِهَا أَوْ قُبْلَتِهَا وَلَوْ جَهِلَتْ عِتْقَهَا أَوْ مِلْكَ الْفَسْخِ بَطَلَ خِيَارُهَا."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"da98","title":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ","units":[{"id":"da98_1","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ١","segs":[["matn","وَأَقْسَامُهَا الْمُثْبِتَةُ لِلْخِيَارِ ثَلَاثَةٌ: قِسْمٌ يَخْتَصُّ بِالرَّجُلِ وَهُوَ:"]]},{"id":"da98_2","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٢","segs":[["matn","كَوْنُهُ قَدْ قُطِعَ ذَكَرُهُ أَوْ خُصْيَتَاهُ أَوْ أَشَلَّ فَلَهَا الْفَسْخُ فِي الْحَالِ وَإِنْ كَانَ عِنِّينًا بِإِقْرَارِهِ أَوْ بِبَيِّنَةٍ أَوْ طَلَبَتْ يَمِينَهُ فَنَكَلَ وَلَمْ يَدَّعِ وَطْأً أُجِّلَ سَنَةً هِلَالِيَّةً مُنْذُ تُرَافِعُهُ إِلَى الْحَاكِمِ فَإِنْ مَضَتْ وَلَمْ يَطَأْهَا فَلَهَا الْفَسْخُ."]]},{"id":"da98_3","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٣","segs":[["matn","وَقِسْمٌ يَخْتَصُّ بِالْأُنْثَى وَهُوَ: كَوْنُ فَرْجِهَا مَسْدُودًا لَا يَسْلُكُهُ ذَكَرٌ أَوْ بِهِ بَخَرٌ أَوْ قُرُوحٌ سَيَّالَةٌ أَوْ كَوْنُهَا فَتْقَاءَ بِانْخِرَاقِ مَا بَيْنَ سَبِيلَيْهَا أَوْ كَوْنُهَا مُسْتَحَاضَةً."]]},{"id":"da98_4","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٤","segs":[["matn","وَقِسْمٌ مُشْتَرَكٌ وَهُوَ: الْجُنُونُ وَلَوْ أَحْيَانًا وَالْجُذَامُ وَالْبَرَصُ وَبَخَرُ الْفَمِ وَالْبَاسُورُ وَالنَّاصُورُ وَاسْتِطْلَاقُ الْبَوْلِ أَوِ الْغَائِطِ. فَيُفْسَخُ بِكُلِّ عَيْبٍ تَقَدَّمَ لَا بِغَيْرِهِ: كَعَوَرٍ وَعَرَجٍ وَقَطْعِ يَدٍ وَرِجْلٍ وَعَمًى وَخَرَسٍ وَطَرَشٍ."]]},{"id":"da98_5","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٥","segs":[["matn","فَصْلٌ: وَلَا يَثْبُتُ الْخِيَارُ فِي عَيْبٍ زَالَ بَعْدَ الْعَقْدِ وَلَا لِعَالِمٍ بِهِ حَالَ الْعَقْدِ."]]},{"id":"da98_6","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٦","segs":[["matn","وَالْفَسْخُ عَلَى التَّرَاخِي لَا يَسْقُطُ فِي الْعُنَّةِ إِلَّا بِقَوْلِهَا: رَضِيتُ أَوْ: بِاعْتِرَافِهَا بِوَطْئِهِ فِي قُبُلِهَا وَيَسْقُطُ فِي غَيْرِ الْعُنَّةِ بِالْقَوْلِ وَبِمَا يَدُلُّ عَلَى الرِّضَا مِنْ وَطْءٍ أَوْ تَمْكِينٍ مَعَ الْعِلْمِ."]]},{"id":"da98_7","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٧","segs":[["matn","وَلَا يَصِحُّ الْفَسْخُ هُنَا وَفِي خِيَارِ الشَّرْطِ بِلَا حَاكِمٍ. فَإِنْ فُسِخَ قَبْلَ الدُّخُولِ فَلَا مَهْرَ وَبَعْدَ الدُّخُولِ أَوِ الْخَلْوَةِ يَسْتَقِرُّ الْمُسَمَّى وَيَرْجِعُ بِهِ عَلَى الْمُغِرِّ."]]},{"id":"da98_8","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٨","segs":[["matn","وَإِنْ حَصَلَتِ الْفُرْقَةُ مِنْ غَيْرِ فَسْخٍ بِمَوْتٍ أَوْ طَلَاقٍ فَلَا رُجُوعَ."]]},{"id":"da98_9","label":"بَابُ حُكْمِ الْعُيُوبِ فِي النِّكَاحِ · ٩","segs":[["matn","وَلَيْسَ لِوَلِيِّ صَغِيرٍ أَوْ مَجْنُونٍ أَوْ رَقِيقٍ تَزْوِيجُهُ بِمَعِيبٍ فَلَوْ فَعَلَ لَمْ يَصِحَّ إِنْ عَلِمَ، وَإِلَّا صَحَّ وَلَزِمَهُ الْفَسْخُ إِذَا عَلِمَ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"da99","title":"بَابُ نِكَاحِ الْكُفَّارِ","units":[{"id":"da99_1","label":"بَابُ نِكَاحِ الْكُفَّارِ · ١","segs":[["matn","يُقَرُّونَ عَلَى أَنْكِحَةٍ مُحَرَّمَةٍ مَا دَامُوا مُعْتَقِدِينَ حِلَّهَا وَلَمْ يَرْتَفِعُوا إِلَيْنَا. فَإِنْ أَتَوْنَا قَبْلَ عَقْدِهِ عَقَدْنَاهُ عَلَى حُكْمِنَا. وَإِنْ أَسْلَمَ الزَّوْجَانِ مَعًا أَوْ أَسْلَمَ زَوْجُ الْكِتَابِيَّةِ فَهُمَا عَلَى نِكَاحِهِمَا."]]},{"id":"da99_2","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٢","segs":[["matn","وَإِنْ أَسْلَمَتِ الْكِتَابِيَّةُ تَحْتَ زَوْجِهَا الْكَافِرِ أَوْ أَسْلَمَ أَحَدُ الزَّوْجَيْنِ غَيْرِ الْكِتَابِيَّيْنِ وَكَانَ قَبْلَ الدُّخُولِ انْفَسَخَ النِّكَاحُ وَلَهَا نِصْفُ الْمَهْرِ إِنْ أَسْلَمَ فَقَطْ أَوْ سَبَقَهَا"]]},{"id":"da99_3","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٣","segs":[["matn","وَإِنْ كَانَ بَعْدَ الدُّخُولِ وُقِفَ الْأَمْرُ إِلَى انْقِضَاءِ الْعِدَّةِ فَإِنْ أَسْلَمَ الْمُتَخَلِّفُ قَبْلَ انْقِضَائِهَا فَعَلَى نِكَاحِهِمَا وَإِلَّا تَبَيَّنَّا فَسْخَهُ مُنْذُ أَسْلَمَ الْأَوَّلُ وَيَجِبُ الْمَهْرُ بِكُلِّ حَالٍ."]]},{"id":"da99_4","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٤","segs":[["matn","فَصْلٌ: وَإِنْ أَسْلَمَ الْكَافِرُ وَتَحْتَهُ أَكْثَرُ مِنْ أَرْبَعٍ فَأَسْلَمْنَ أَوْ لَا وَكُنَّ كِتَابِيَّاتٍ اخْتَارَ مِنْهُنَّ أَرْبَعًا إِنْ كَانَ مُكَلَّفًا وَإِلَّا فَحَتَّى يُكَلَّفَ."]]},{"id":"da99_5","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٥","segs":[["matn","فَإِنْ لَمْ يَخْتَرْ أُجْبِرَ بِحَبْسٍ ثُمَّ تَعْزِيرٍ وَعَلَيْهِ نَفَقَتُهُنَّ إِلَى أَنْ يَخْتَارَ."]]},{"id":"da99_6","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٦","segs":[["matn","وَيَكْفِي فِي الِاخْتِيَارِ: أَمْسَكْتُ هَؤُلَاءِ وَتَرَكْتُ هَؤُلَاءِ وَيَحْصُلُ الِاخْتِيَارُ بِالْوَطْءِ فَإِنْ وَطِئَ الْكُلَّ تَعَيَّنَ الْأَوَّلُ وَيَحْصُلُ بِالطَّلَاقِ: فَمَنْ طَلَّقَهَا فَهِيَ مُخْتَارَةٌ."]]},{"id":"da99_7","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٧","segs":[["matn","وَإِنْ أَسْلَمَ الْحُرُّ وَتَحْتَهُ إِمَاءٌ فَأَسْلَمْنَ فِي الْعِدَّةِ اخْتَارَ مَا يُعِفُّهُ إِنْ جَازَ لَهُ نِكَاحُهُنَّ وَقْتَ اجْتِمَاعِ إِسْلَامِهِ بِإِسْلَامِهِنَّ وَإِنْ لَمْ يَجُزْ لَهُ فَسَدَ: نِكَاحُهُنَّ."]]},{"id":"da99_8","label":"بَابُ نِكَاحِ الْكُفَّارِ · ٨","segs":[["matn","وَإِنِ ارْتَدَّ أَحَدُ الزَّوْجَيْنِ أَوْ هُمَا مَعًا قَبْلَ الدُّخُولِ انْفَسَخَ النِّكَاحُ وَلَهَا نِصْفُ الْمَهْرِ إِنْ سَبَقَهَا وَبَعْدَ الدُّخُولِ تَقِفُ الْفُرْقَةُ عَلَى انْقِضَاءِ الْعِدَّةِ."]]}],"group":"كِتَابُ النِّكَاحِ"},{"id":"da100","title":"كِتَابُ الصَّدَاقِ","units":[{"id":"da100_1","label":"كِتَابُ الصَّدَاقِ · ١","segs":[["matn","تُسَنُّ تَسْمِيَتُهُ فِي الْعَقْدِ. وَيَصِحُّ بِأَقَلِّ مُتَمَوَّلٍ. فَإِنْ لَمْ يُسَمِّ أَوْ سَمَّى فَاسِدًا صَحَّ الْعَقْدُ وَوَجَبَ مَهْرُ الْمِثْلِ."]]},{"id":"da100_2","label":"كِتَابُ الصَّدَاقِ · ٢","segs":[["matn","وَإِنْ أَصْدَقَهَا تَعْلِيمَ شَيْءٍ مِنَ الْقُرْآنِ لَمْ يَصِحَّ وَتَعْلِيمَ مُعَيَّنٍ مِنْ فِقْهٍ أَوْ حَدِيثٍ أَوْ شِعْرٍ مُبَاحٍ أَوْ صَنْعَةٍ صَحَّ."]]},{"id":"da100_3","label":"كِتَابُ الصَّدَاقِ · ٣","segs":[["matn","وَيُشْتَرَطُ عِلْمُ الصَّدَاقِ: فَلَوْ أَصْدَقَهَا دَارًا أَوْ دَابَّةً أَوْ ثَوْبًا مُطْلَقًا أَوْ رَدَّ عَبْدِهَا أَيْنَ كَانَ أَوْ خِدْمَتَهَا مُدَّةً فِيمَا شَاءَتْ أَوْ مَا يُثْمِرُ شَجَرُهُ أَوْ حَمْلَ أَمَتِهِ أَوْ دَابَّتِهِ لَمْ يَصِحَّ."]]},{"id":"da100_4","label":"كِتَابُ الصَّدَاقِ · ٤","segs":[["matn","وَلَا يَضُرُّ جَهْلٌ يَسِيرٌ فَلَوْ أَصْدَقَهَا عَبْدًا مِنْ عَبِيدِهِ أَوْ دَابَّةً مِنْ دَوَابِّهِ أَوْ قَمِيصًا مِنْ قُمْصَانِهِ صَحَّ وَلَهَا أَحَدُهُمْ بِقُرْعَةٍ. وَإِنْ أَصْدَقَهَا عِتْقَ قِنِّهِ صَحَّ لَا طَلَاقُ زَوْجَتِهِ."]]},{"id":"da100_5","label":"كِتَابُ الصَّدَاقِ · ٥","segs":[["matn","وَإِنْ أَصْدَقَهَا خَمْرًا أَوْ خِنْزِيرًا أَوْ مَالًا مَغْصُوبًا يَعْلَمَانِهِ لَمْ يَصِحَّ وَإِنْ لَمْ يَعْلَمَاهُ صَحَّ وَلَهَا قِيمَتُهُ يَوْمَ الْعَقْدِ وَعَصِيرًا فَبَانَ خَمْرًا صَحَّ وَلَهَا مِثْلُ الْعَصِيرِ"]]},{"id":"da100_6","label":"كِتَابُ الصَّدَاقِ · ٦","segs":[["matn","فَصْلٌ: وَلِلْأَبِ تَزْوِيجُ ابْنَتِهِ مُطْلَقًا بِدُونِ صَدَاقِ مِثْلِهَا وَإِنْ كَرِهَتْ وَلَا يَلْزَمُ أَحَدًا تَتِمَّتُهُ. وَإِنْ فَعَلَ ذَلِكَ غَيْرُ الْأَبِ بِإِذْنِهَا مَعَ رُشْدِهَا صَحَّ وَبِدُونِ إِذْنِهَا يَلْزَمُ الزَّوْجَ تَتِمَّتُهُ."]]},{"id":"da100_7","label":"كِتَابُ الصَّدَاقِ · ٧","segs":[["matn","فَإِنْ قَدَّرَتْ لِوَلِيِّهَا مَبْلَغًا فَزَوَّجَهَا بِدُونِهِ ضَمِنَ. وَإِنْ زَوَّجَ ابْنَهُ فَقِيلَ لَهُ: ابْنُكَ فَقِيرٌ مِنْ أَيْنَ يُؤْخَذُ الصَّدَاقُ فَقَالَ: عِنْدِي لَزِمَهُ."]]},{"id":"da100_8","label":"كِتَابُ الصَّدَاقِ · ٨","segs":[["matn","وَلَيْسَ لِلْأَبِ قَبْضُ صَدَاقِ ابْنَتِهِ الرَّشِيدَةِ وَلَوْ بِكْرًا إِلَّا بِإِذْنِهَا فَإِنْ أَقْبَضَهُ الزَّوْجُ لِأَبِيهَا لَمْ يَبْرَأْ وَرَجَعَتْ عَلَيْهِ وَرَجَعَ هُوَ عَلَى أَبِيهَا وَإِنْ كَانَتْ غَيْرَ رَشِيدَةٍ سَلَّمَهُ إِلَى وَلِيِّهَا فِي مَالِهَا."]]},{"id":"da100_9","label":"كِتَابُ الصَّدَاقِ · ٩","segs":[["matn","وَإِنْ تَزَوَّجَ الْعَبْدُ بِإِذْنِ سَيِّدِهِ صَحَّ وَعَلَى سَيِّدِهِ الْمَهْرُ وَالنَّفَقَةُ وَالْكُسْوَةُ وَالْمَسْكَنُ وَإِنْ تَزَوَّجَ بِلَا إِذْنِهِ لَمْ يَصِحَّ فَلَوْ وَطِئَ وَجَبَ فِي رَقَبَتِهِ مَهْرُ الْمِثْلِ."]]},{"id":"da100_10","label":"كِتَابُ الصَّدَاقِ · ١٠","segs":[["matn","فَصْلٌ: وَتَمْلِكُ الزَّوْجَةُ بِالْعَقْدِ جَمِيعَ الْمُسَمَّى وَلَهَا نَمَاؤُهُ إِنْ كَانَ مُعَيَّنًا وَلَهَا التَّصَرُّفُ فِيهِ وَضَمَانُهُ وَنَقْصُهُ عَلَيْهَا إِنْ لَمْ يَمْنَعْهَا قَبْضَهُ."]]},{"id":"da100_11","label":"كِتَابُ الصَّدَاقِ · ١١","segs":[["matn","وَإِنْ أَقْبَضَهَا الصَّدَاقَ ثُمَّ طَلَّقَ قَبْلَ الدُّخُولِ رَجَعَ عَلَيْهَا بِنِصْفِهِ إِنْ كَانَ بَاقِيًا وَإِنْ كَانَ قَدْ زَادَ زِيَادَةً مُنْفَصِلَةً فَالزِّيَادَةُ لَهَا وَإِنْ كَانَ تَالِفًا رَجَعَ فِي الْمِثْلِيِّ بِنِصْفِ مِثْلِهِ وَفِي الْمُتَقَوِّمِ بِنِصْفِ قِيمَتِهِ يَوْمَ الْعَقْدِ."]]},{"id":"da100_12","label":"كِتَابُ الصَّدَاقِ · ١٢","segs":[["matn","وَالَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ: الزَّوْجُ. فَإِذَا طَلَّقَ قَبْلَ الدُّخُولِ: فَأَيُّ الزَّوْجَيْنِ عَفَا لِصَاحِبِهِ عَمَّا وَجَبَ لَهُ مِنَ الْمَهْرِ وَهُوَ جَائِزُ التَّصَرُّفِ بَرِئَ مِنْهُ صَاحِبُهُ."]]},{"id":"da100_13","label":"كِتَابُ الصَّدَاقِ · ١٣","segs":[["matn","وَإِنْ وَهَبَتْهُ صَدَاقَهَا قَبْلَ الْفُرْقَةِ ثُمَّ حَصَلَ مَا يُنَصِّفُهُ: كَطَلَاقٍ رَجَعَ عَلَيْهَا بِبَدَلِ نِصْفِهِ وَإِنْ حَصَلَ مَا يُسْقِطُهُ رَجَعَ بِبَدَلِ جَمِيعِهِ."]]},{"id":"da100_14","label":"كِتَابُ الصَّدَاقِ · ١٤","segs":[["matn","فَصْلٌ فِيمَا يُسْقِطُ الصَّدَاقَ وَيُنَصِّفُهُ وَيُقَرِّرُهُ: يَسْقُطُ كُلُّهُ قَبْلَ الدُّخُولِ حَتَّى الْمُتْعَةُ بِفُرْقَةِ اللِّعَانِ وَبِفَسْخِهِ لِعَيْبِهَا وَبِفُرْقَةٍ مِنْ قِبَلِهَا: كَفَسْخِهَا لِعَيْبِهِ وَإِسْلَامِهَا تَحْتَ كَافِرٍ وَرِدَّتِهَا تَحْتَ مُسْلِمٍ وَرَضَاعِهَا مَنْ يَنْفَسِخُ بِهِ نِكَاحُهَا."]]},{"id":"da100_15","label":"كِتَابُ الصَّدَاقِ · ١٥","segs":[["matn","وَيَتَنَصَّفُ بِالْفُرْقَةِ مِنْ قِبَلِ الزَّوْجِ: كَطَلَاقِهِ وَخُلْعِهِ وَإِسْلَامِهِ وَرِدَّتِهِ وَبِمِلْكِ أَحَدِهِمَا الْآخَرَ أَوْ قِبَلِ أَجْنَبِيٍّ كَرَضَاعٍ وَنَحْوِهِ."]]},{"id":"da100_16","label":"كِتَابُ الصَّدَاقِ · ١٦","segs":[["matn","وَيُقَرِّرُهُ كَامِلًا مَوْتُ أَحَدِهِمَا وَوَطْؤُهَا وَلَمْسُهُ لَهَا وَنَظَرُهُ إِلَى فَرْجِهَا لِشَهْوَةٍ وَبِطَلَاقِهَا فِي مَرَضِ مَوْتٍ تَرِثُ فِيهِ وَتَقْبِيلُهَا وَلَوْ بِحَضْرَةِ النَّاسِ وَبِخَلْوَتِهِ بِهَا عَنْ مُمَيِّزٍ إِنْ كَانَ يَطَأُ مِثْلُهُ وَيُوطَأُ مِثْلُهَا."]]},{"id":"da100_17","label":"كِتَابُ الصَّدَاقِ · ١٧","segs":[["matn","فَصْلٌ: وَإِذَا اخْتَلَفَا فِي قَدْرِ الصَّدَاقِ أَوْ جِنْسِهِ أَوْ مَا يَسْتَقِرُّ بِهِ فَقَوْلُ الزَّوْجِ أَوْ وَارِثِهِ وَفِي الْقَبْضِ أَوْ تَسْمِيَةِ الْمَهْرِ فَقَوْلُهَا أَوْ وَارِثِهَا."]]},{"id":"da100_18","label":"كِتَابُ الصَّدَاقِ · ١٨","segs":[["matn","وَإِنْ تَزَوَّجَهَا بِعَقْدَيْنِ عَلَى صَدَاقَيْنِ سِرًّا وَعَلَانِيَةً أُخِذَ بِالزَّائِدِ."]]},{"id":"da100_19","label":"كِتَابُ الصَّدَاقِ · ١٩","segs":[["matn","وَهَدِيَّةُ الزَّوْجِ لَيْسَتْ مِنَ الْمَهْرِ فَمَا قَبْلَ الْعَقْدِ إِنْ وَعَدُوهُ وَلَمْ يَفُوا رَجَعَ بِهَا وَتُرَدُّ الْهَدِيَّةُ فِي كُلِّ فُرْقَةٍ اخْتِيَارِيَّةٍ مُسْقِطَةٍ لِلْمَهْرِ وَتَثْبُتُ كُلُّهَا مَعَ مُقَرِّرٍ لَهُ أَوْ لِنِصْفِهِ."]]},{"id":"da100_20","label":"كِتَابُ الصَّدَاقِ · ٢٠","segs":[["matn","فَصْلٌ: وَلِمَنْ زُوِّجَتْ بِلَا مَهْرٍ أَوْ بِمَهْرٍ فَاسِدٍ فَرْضُ مَهْرِ مِثْلِهَا عِنْدَ الْحَاكِمِ فَإِنْ تَرَاضَيَا فِيمَا بَيْنَهُمَا وَلَوْ عَلَى قَلِيلٍ صَحَّ وَلَزِمَ فَإِنْ حَصَلَتْ لَهَا"]]},{"id":"da100_21","label":"كِتَابُ الصَّدَاقِ · ٢١","segs":[["matn","فُرْقَةٌ مُنَصِّفَةٌ لِلصَّدَاقِ قَبْلَ فَرْضِهِ أَوْ تَرَاضِيهِمَا وَجَبَتْ لَهَا الْمُتْعَةُ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ فَأَعْلَاهَا خَادِمٌ وَأَدْنَاهَا: كِسْوَةٌ تُجْزِئُهَا فِي صَلَاتِهَا إِذَا كَانَ مُعْسِرًا."]]},{"id":"da100_22","label":"كِتَابُ الصَّدَاقِ · ٢٢","segs":[["matn","فَصْلٌ: وَلَا مَهْرَ فِي النِّكَاحِ الْفَاسِدِ إِلَّا بِالْخَلْوَةِ أَوِ الْوَطْءِ. فَإِنْ حَصَلَ أَحَدُهُمَا اسْتَقَرَّ الْمُسَمَّى إِنْ كَانَ وَإِلَّا فَمَهْرُ الْمِثْلِ."]]},{"id":"da100_23","label":"كِتَابُ الصَّدَاقِ · ٢٣","segs":[["matn","وَلَا مَهْرَ فِي النِّكَاحِ الْبَاطِلِ إِلَّا بِالْوَطْءِ فِي الْقُبُلِ وَكَذَا الْمَوْطُوءَةُ بِشُبْهَةٍ وَالْمُكْرَهَةُ عَلَى الزِّنَا لَا الْمُطَاوِعَةُ مَا لَمْ تَكُنْ أَمَةً. وَيَتَعَدَّدُ الْمَهْرُ بِتَعَدُّدِ الشُّبْهَةِ وَالْإِكْرَاهِ."]]},{"id":"da100_24","label":"كِتَابُ الصَّدَاقِ · ٢٤","segs":[["matn","وَعَلَى مَنْ أَزَالَ بَكَارَةَ أَجْنَبِيَّةٍ بِلَا وَطْءٍ أَرْشُ الْبَكَارَةِ وَإِنْ أَزَالَهَا الزَّوْجُ ثُمَّ طَلَّقَ قَبْلَ الدُّخُولِ لَمْ يَكُنْ عَلَيْهِ إِلَّا نِصْفُ الْمُسَمَّى إِنْ كَانَ وَإِلَّا فَالْمُتْعَةُ."]]},{"id":"da100_25","label":"كِتَابُ الصَّدَاقِ · ٢٥","segs":[["matn","وَلَا يَصِحُّ تَزْوِيجُ مَنْ نِكَاحُهَا فَاسِدٌ قَبْلَ الْفُرْقَةِ فَإِنْ أَبَاهَا الزَّوْجُ فَسَخَهُ الْحَاكِمُ."]]}],"group":"كِتَابُ الصَّدَاقِ"},{"id":"da101","title":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ","units":[{"id":"da101_1","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ١","segs":[["matn","وَلِيمَةُ الْعُرْسِ سُنَّةٌ مُؤَكَّدَةٌ. وَالْإِجَابَةُ إِلَيْهَا فِي الْمَرَّةِ الْأُولَى وَاجِبَةٌ إِنْ كَانَ لَا عُذْرَ وَلَا مُنْكَرَ. وَفِي الثَّانِيَةِ: سُنَّةٌ وَفِي الثَّالِثَةِ: مَكْرُوهَةٌ."]]},{"id":"da101_2","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٢","segs":[["matn","وَإِنَّمَا تَجِبُ إِذَا كَانَ الدَّاعِي مُسْلِمًا يَحْرُمُ هَجْرُهُ وَكَسْبُهُ طَيِّبٌ. فَإِنْ كَانَ فِي مَالِهِ حَرَامٌ كُرِهَ إِجَابَتُهُ وَمُعَامَلَتُهُ وَقَبُولُ هَدِيَّتِهِ وَتَقْوَى الْكَرَاهَةُ وَتَضْعُفُ بِحَسَبِ كَثْرَةِ الْحَرَامِ وَقِلَّتِهِ."]]},{"id":"da101_3","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٣","segs":[["matn","وَإِنْ دَعَاهُ اثْنَانِ فَأَكْثَرُ وَجَبَ عَلَيْهِ إِجَابَةُ الْكُلِّ إِنْ أَمْكَنَهُ الْجَمْعُ وَإِلَّا أَجَابَ: الْأَسْبَقَ قَوْلًا فَالْأَدْيَنَ فَالْأَقْرَبَ رَحِمًا فَجِوَارًا ثُمَّ يُقْرِعُ."]]},{"id":"da101_4","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٤","segs":[["matn","وَلَا يَقْصِدُ بِالْإِجَابَةِ نَفْسَ الْأَكْلِ بَلْ يَنْوِي الِاقْتِدَاءَ بِالسُّنَّةِ وَإِكْرَامَ أَخِيهِ الْمُؤْمِنِ وَلِئَلَّا يُظَنَّ بِهِ التَّكَبُّرُ. وَيُسْتَحَبُّ أَكْلُهُ وَلَوْ صَائِمًا لَا صَوْمًا وَاجِبًا وَيَنْوِي بِأَكْلِهِ وَشُرْبِهِ التَّقَوِّيَ عَلَى الطَّاعَةِ."]]},{"id":"da101_5","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٥","segs":[["matn","وَيَحْرُمُ الْأَكْلُ بِلَا إِذْنٍ صَرِيحٍ أَوْ قَرِينَةٍ وَلَوْ مِنْ بَيْتِ قَرِيبِهِ أَوْ صَدِيقِهِ وَالدُّعَاءُ إِلَى الْوَلِيمَةِ وَتَقْدِيمُ الطَّعَامِ إِذْنٌ فِي الْأَكْلِ. وَيُقَدِّمُ مَا حَضَرَ مِنَ الطَّعَامِ مِنْ غَيْرِ تَكَلُّفٍ."]]},{"id":"da101_6","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٦","segs":[["matn","وَلَا يُشْرَعُ تَقْبِيلُ الْخُبْزِ. وَتُكْرَهُ: إِهَانَتُهُ وَمَسْحُ يَدَيْهِ بِهِ وَوَضْعُهُ تَحْتَ الْقَصْعَةِ."]]},{"id":"da101_7","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٧","segs":[["matn","فَصْلٌ: وَيُسْتَحَبُّ غَسْلُ الْيَدَيْنِ قَبْلَ الطَّعَامِ وَبَعْدَهُ. وَتُسَنُّ التَّسْمِيَةُ جَهْرًا عَلَى الطَّعَامِ وَالشَّرَابِ وَأَنْ يَجْلِسَ عَلَى رِجْلِهِ الْيُسْرَى وَيَنْصِبَ الْيُمْنَى أَوْ يَتَرَبَّعَ وَيَأْكُلَ بِيَمِينِهِ بِثَلَاثِ أَصَابِعَ مِمَّا يَلِيهِ وَيُصَغِّرَ اللُّقْمَةَ وَيُطِيلَ الْمَضْغَ وَيَمْسَحَ الصَّحْفَةَ وَيَأْكُلَ مَا تَنَاثَرَ"]]},{"id":"da101_8","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٨","segs":[["matn","وَيَغُضَّ طَرْفَهُ عَنْ جَلِيسِهِ وَيُؤْثِرَ الْمُحْتَاجَ وَيَأْكُلَ مَعَ الزَّوْجَةِ وَالْمَمْلُوكِ وَالْوَلَدِ وَلَوْ طِفْلًا وَيَلْعَقَ أَصَابِعَهُ وَيُخَلِّلَ أَسْنَانَهُ وَيُلْقِيَ مَا أَخْرَجَهُ الْخِلَالُ وَيُكْرَهُ أَنْ يَبْتَلِعَهُ فَإِنْ قَلَعَهُ بِلِسَانِهِ لَمْ يُكْرَهْ."]]},{"id":"da101_9","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ٩","segs":[["matn","وَيُكْرَهُ نَفْخُ الطَّعَامِ وَكَوْنِهِ حَارًّا وَأَكْلُهُ بِأَقَلَّ أَوْ أَكْثَرَ مِنْ ثَلَاثِ أَصَابِعَ أَوْ بِشِمَالِهِ وَمِنْ أَعْلَى الصَّحْفَةِ:"]]},{"id":"da101_10","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ١٠","segs":[["matn","أَوْ وَسَطِهَا وَنَفْضُ يَدِهِ فِي الْقَصْعَةِ وَتَقْدِيمُ رَأْسِهِ إِلَيْهَا عِنْدَ وَضْعِ اللُّقْمَةِ فِي فَمِهِ وَكَلَامُهُ بِمَا يُسْتَقْذَرُ وَأَكْلُهُ مُتَّكِئًا أَوْ مُضْطَجِعًا وَأَكْلُهُ كَثِيرًا بِحَيْثُ يُؤْذِيهِ أَوْ قَلِيلًا بِحَيْثُ يَضُرُّهُ."]]},{"id":"da101_11","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ١١","segs":[["matn","وَيَأْكُلُ وَيَشْرَبُ مَعَ أَبْنَاءِ الدُّنْيَا بِالْأَدَبِ وَالْمُرُوءَةِ وَمَعَ الْفُقَرَاءِ بِالْإِيثَارِ وَمَعَ الْعُلَمَاءِ بِالتَّعَلُّمِ وَمَعَ الْإِخْوَانِ بِالِانْبِسَاطِ وَبِالْحَدِيثِ الطَّيِّبِ وَالْحِكَايَاتِ الَّتِي تَلِيقُ بِالْحَالِ."]]},{"id":"da101_12","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ١٢","segs":[["matn","وَمَا جَرَتْ بِهِ الْعَادَةُ مِنْ إِطْعَامِ السَّائِلِ وَنَحْوِ الْهِرِّ فَفِي جَوَازِهِ وَجْهَانِ."]]},{"id":"da101_13","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ١٣","segs":[["matn","فَصْلٌ: وَسُنَّ أَنْ يَحْمَدَ اللَّهَ إِذَا فَرَغَ وَيَقُولَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا الطَّعَامَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ وَيَدْعُوَ لِصَاحِبِ الطَّعَامِ وَيُفْضِلَ مِنْهُ شَيْئًا لَا سِيَّمَا إِنْ كَانَ مِمَّنْ يُتَبَرَّكُ بِفَضْلَتِهِ."]]},{"id":"da101_14","label":"بَابُ الْوَلِيمَةِ وَآدَابِ الْأَكْلِ · ١٤","segs":[["matn","وَيُسَنُّ إِعْلَانُ النِّكَاحِ وَالضَّرْبُ فِيهِ بِدُفٍّ لَا حِلَقَ فِيهِ وَلَا صُنُوجَ لِلنِّسَاءِ وَيُكْرَهُ لِلرِّجَالِ. وَلَا بَأْسَ بِالْغَزَلِ فِي الْعُرْسِ. وَضَرْبُ الدُّفِّ فِي الْخِتَانِ وَقُدُومِ الْغَائِبِ: كَالْعُرْسِ."]]}],"group":"كِتَابُ الصَّدَاقِ"},{"id":"da102","title":"بَابُ عِشْرَةِ النِّسَاءِ","units":[{"id":"da102_1","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١","segs":[["matn","يَلْزَمُ كُلًّا مِنَ الزَّوْجَيْنِ مُعَاشَرَةُ الْآخَرِ بِالْمَعْرُوفِ مِنَ الصُّحْبَةِ الْجَمِيلَةِ وَكَفِّ الْأَذَى وَأَنْ لَا يَمْطُلَهُ بِحَقِّهِ. وَحَقُّ الزَّوْجِ عَلَيْهَا أَعْظَمُ مِنْ حَقِّهَا عَلَيْهِ. وَلْيَكُنْ غَيُورًا مِنْ غَيْرِ إِفْرَاطٍ."]]},{"id":"da102_2","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٢","segs":[["matn","وَإِذَا تَمَّ الْعَقْدُ وَجَبَ عَلَى الْمَرْأَةِ أَنْ تُسَلِّمَ نَفْسَهَا لِبَيْتِ زَوْجِهَا إِذَا طَلَبَهَا وَهِيَ حُرَّةٌ يُمْكِنُ الِاسْتِمْتَاعُ بِهَا كَبِنْتِ تِسْعٍ إِنْ لَمْ تَشْتَرِطْ دَارَهَا."]]},{"id":"da102_3","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٣","segs":[["matn","وَلَا يَجِبُ عَلَيْهَا التَّسْلِيمُ إِنْ طَلَبَهَا وَهِيَ مُحْرِمَةٌ أَوْ مَرِيضَةٌ أَوْ صَغِيرَةٌ أَوْ حَائِضٌ وَلَوْ قَالَ: لَا أَطَأُ."]]},{"id":"da102_4","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٤","segs":[["matn","فَصْلٌ: وَلِلزَّوْجِ أَنْ يَسْتَمْتِعَ بِزَوْجَتِهِ كُلَّ وَقْتٍ عَلَى أَيِّ صِفَةٍ كَانَتْ مَا لَمْ يَضُرَّهَا أَوْ يَشْغَلْهَا عَنِ الْفَرَائِضِ. وَلَا يَجُوزُ لَهَا أَنْ تَتَطَوَّعَ بِصَلَاةٍ أَوْ صَوْمٍ وَهُوَ حَاضِرٌ إِلَّا بِإِذْنِهِ."]]},{"id":"da102_5","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٥","segs":[["matn","وَلَهُ الِاسْتِمْتَاعُ بِيَدِهَا وَالسَّفَرُ بِلَا إِذْنِهَا وَيَحْرُمُ وَطْؤُهَا فِي الدُّبُرِ وَنَحْوِ الْحَيْضِ وَعَزْلُهُ عَنْهَا بِلَا إِذْنِهَا وَيُكْرَهُ أَنْ يُقَبِّلَهَا أَوْ يُبَاشِرَهَا عِنْدَ النَّاسِ أَوْ يُكْثِرَ الْكَلَامَ حَالَ الْجِمَاعِ أَوْ يُحَدِّثَا بِمَا جَرَى بَيْنَهُمَا."]]},{"id":"da102_6","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٦","segs":[["matn","وَيُسَنُّ أَنْ يُلَاعِبَهَا قَبْلَ الْجِمَاعِ وَأَنْ يُغَطِّيَ رَأْسَهُ وَأَنْ لَا يَسْتَقْبِلَ الْقِبْلَةَ وَأَنْ يَقُولَ عِنْدَ الْوَطْءِ: بِسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا وَأَنْ تَتَّخِذَ الْمَرْأَةُ خِرْقَةً تُنَاوِلُهَا لِلزَّوْجِ بَعْدَ فَرَاغِهِ مِنَ الْجِمَاعِ."]]},{"id":"da102_7","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٧","segs":[["matn","فَصْلٌ: وَلَيْسَ عَلَيْهَا خِدْمَةُ زَوْجِهَا فِي عَجْنٍ وَخَبْزٍ وَطَبْخٍ وَنَحْوِهِ لَكِنِ الْأَوْلَى لَهَا فِعْلُ مَا جَرَتْ بِهِ الْعَادَةُ."]]},{"id":"da102_8","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٨","segs":[["matn","وَلَهُ أَنْ يُلْزِمَهَا بِغَسْلِ نَجَاسَةٍ عَلَيْهَا وَبِالْغُسْلِ مِنَ الْحَيْضِ وَالنِّفَاسِ وَالْجَنَابَةِ وَبِأَخْذِ مَا يُعَافُ مِنْ ظُفُرٍ وَشَعَرٍ."]]},{"id":"da102_9","label":"بَابُ عِشْرَةِ النِّسَاءِ · ٩","segs":[["matn","وَيَحْرُمُ عَلَيْهَا الْخُرُوجُ بِلَا إِذْنِهِ وَلَوْ لِمَوْتِ أَبِيهَا لَكِنْ لَهَا أَنْ تَخْرُجَ لِقَضَاءِ حَوَائِجِهَا حَيْثُ لَمْ يَقُمْ بِهَا."]]},{"id":"da102_10","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٠","segs":[["matn","وَلَا يَمْلِكُ مَنْعَهَا مِنْ كَلَامِ أَبَوَيْهَا وَلَا مَنْعَهُمَا مِنْ زِيَارَتِهَا مَا لَمْ يَخَفْ مِنْهُمَا الضَّرَرَ. وَلَا يَلْزَمُهَا طَاعَةُ أَبَوَيْهَا بَلْ طَاعَةُ زَوْجِهَا أَحَقُّ."]]},{"id":"da102_11","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١١","segs":[["matn","فَصْلٌ: وَيَلْزَمُهُ أَنْ يَبِيتَ عِنْدَ الْحُرَّةِ بِطَلَبِهَا لَيْلَةً مِنْ أَرْبَعٍ وَالْأَمَةِ لَيْلَةً مِنْ سَبْعٍ وَأَنْ يَطَأَهَا فِي كُلِّ ثُلُثِ سَنَةٍ مَرَّةً إِنْ قَدَرَ فَإِنْ أَبَى فَرَّقَ الْحَاكِمُ بَيْنَهُمَا إِنْ طَلَبَتْ."]]},{"id":"da102_12","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٢","segs":[["matn","وَإِنْ سَافَرَ فَوْقَ نِصْفِ سَنَةٍ فِي غَيْرِ أَمْرٍ وَاجِبٍ أَوْ طَلَبِ رِزْقٍ يَحْتَاجُ إِلَيْهِ وَطَلَبَتْ قُدُومَهُ لَزِمَهُ."]]},{"id":"da102_13","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٣","segs":[["matn","وَيَجِبُ عَلَيْهِ التَّسْوِيَةُ بَيْنَ زَوْجَاتِهِ فِي الْمَبِيتِ وَيَكُونُ لَيْلَةً وَلَيْلَةً إِلَّا أَنْ يَرْضَيْنَ بِأَكْثَرَ."]]},{"id":"da102_14","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٤","segs":[["matn","وَيَحْرُمُ دُخُولُهُ فِي نَوْبَةِ وَاحِدَةٍ إِلَى غَيْرِهَا إِلَّا لِضَرُورَةٍ وَفِي نَهَارِهَا إِلَّا لِحَاجَةٍ وَإِنْ لَبِثَ أَوْ جَامَعَ لَزِمَهُ الْقَضَاءُ. وَإِنْ طَلَّقَ وَاحِدَةً وَقْتَ نَوْبَتِهَا أَثِمَ وَيَقْضِيهَا مَتَى نَكَحَهَا."]]},{"id":"da102_15","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٥","segs":[["matn","وَلَا يَجِبُ عَلَيْهِ أَنْ يُسَوِّيَ بَيْنَهُنَّ فِي الْوَطْءِ وَدَوَاعِيهِ وَلَا فِي النَّفَقَةِ وَالْكِسْوَةِ حَيْثُ قَامَ بِالْوَاجِبِ وَإِنْ أَمْكَنَهُ ذَلِكَ كَانَ حَسَنًا."]]},{"id":"da102_16","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٦","segs":[["matn","فَصْلٌ: وَإِذَا تَزَوَّجَ بِكْرًا أَقَامَ عِنْدَهَا سَبْعًا وَثَيِّبًا ثَلَاثًا ثُمَّ يَعُودُ إِلَى الْقَسْمِ بَيْنَهُنَّ. وَلَهُ تَأْدِيبُهُنَّ عَلَى تَرْكِ الْفَرَائِضِ."]]},{"id":"da102_17","label":"بَابُ عِشْرَةِ النِّسَاءِ · ١٧","segs":[["matn","وَمَنْ عَصَتْهُ وَعَظَهَا فَإِنْ أَصَرَّتْ هَجَرَهَا فِي الْمَضْجَعِ مَا شَاءَ وَفِي الْكَلَامِ ثَلَاثَةَ أَيَّامٍ فَقَطْ فَإِنْ أَصَرَّتْ ضَرَبَهَا ضَرْبًا غَيْرَ شَدِيدٍ بِعَشَرَةِ أَسْوَاطٍ لَا فَوْقَهَا وَيُمْنَعُ مِنْ ذَلِكَ إِنْ كَانَ مَانِعًا لِحَقِّهَا."]]}],"group":"كِتَابُ الصَّدَاقِ"},{"id":"da103","title":"كِتَابُ الْخُلْعِ","units":[{"id":"da103_1","label":"كِتَابُ الْخُلْعِ · ١","segs":[["matn","وَشُرُوطُهُ سَبْعَةٌ: الْأَوَّلُ: أَنْ يَقَعَ مِنْ زَوْجٍ يَصِحُّ طَلَاقُهُ. الثَّانِي: أَنْ يَكُونَ عَلَى عِوَضٍ وَلَوْ مَجْهُولًا مِمَّنْ يَصِحُّ تَبَرُّعُهُ مِنْ أَجْنَبِيٍّ وَزَوْجَةٍ لَكِنْ لَوْ عَضَلَهَا ظُلْمًا لِتَخْتَلِعَ لَمْ يَصِحَّ."]]},{"id":"da103_2","label":"كِتَابُ الْخُلْعِ · ٢","segs":[["matn","الثَّالِثُ: أَنْ يَقَعَ مُنَجَّزًا. الرَّابِعُ: أَنْ يَقَعَ الْخُلْعُ عَلَى جَمِيعِ الزَّوْجَةِ. الْخَامِسُ: أَنْ لَا يَقَعَ حِيلَةً لِإِسْقَاطِ يَمِينِ الطَّلَاقِ. السَّادِسُ: أَنْ لَا يَقَعَ بِلَفْظِ الطَّلَاقِ بَلْ بِصِيغَتِهِ الْمَوْضُوعَةِ لَهُ."]]},{"id":"da103_3","label":"كِتَابُ الْخُلْعِ · ٣","segs":[["matn","السَّابِعُ: أَنْ لَا يَنْوِيَ بِهِ الطَّلَاقَ. فَمَتَى تَوَفَّرَتِ الشُّرُوطُ كَانَ فَسْخًا بَائِنًا لَا يَنْقُصُ بِهِ عَدَدُ الطَّلَاقِ."]]},{"id":"da103_4","label":"كِتَابُ الْخُلْعِ · ٤","segs":[["matn","وَصِيغَتُهُ الصَّرِيحَةُ لَا تَحْتَاجُ إِلَى نِيَّةٍ وَهِيَ: خَلَعْتُ وَفَسَخْتُ، وَفَادَيْتُ، وَالْكِنَايَةُ: بَارَيْتُكِ وَأَبْرَأْتُكِ وَأَبَنْتُكِ."]]},{"id":"da103_5","label":"كِتَابُ الْخُلْعِ · ٥","segs":[["matn","فَمَعَ سُؤَالِ الْخُلْعِ وَبَذْلِ الْعِوَضِ يَصِحُّ بِلَا نِيَّةٍ وَإِلَّا فَلَا بُدَّ مِنْهَا وَيَصِحُّ بِكُلِّ لُغَةٍ مِنْ أَهْلِهَا كَالطَّلَاقِ."]]}],"group":"كِتَابُ الْخُلْعِ"},{"id":"da104","title":"كِتَابُ الطَّلَاقِ","units":[{"id":"da104_1","label":"كِتَابُ الطَّلَاقِ · ١","segs":[["matn","يُبَاحُ لِسُوءِ عِشْرَةِ الزَّوْجَةِ وَيُسَنُّ إِنْ تَرَكَتِ الصَّلَاةَ وَنَحْوَهَا وَيُكْرَهُ مِنْ غَيْرِ حَاجَةٍ وَيَحْرُمُ فِي الْحَيْضِ وَنَحْوِهِ وَيَجِبُ عَلَى الْمُؤْلِي بَعْدَ التَّرَبُّصِ قِيلَ: وَعَلَى مَنْ يَعْلَمُ بِفُجُورِ زَوْجَتِهِ."]]},{"id":"da104_2","label":"كِتَابُ الطَّلَاقِ · ٢","segs":[["matn","وَيَقَعُ طَلَاقُ الْمُمَيِّزِ إِنْ عَقَلَ الطَّلَاقَ وَطَلَاقُ السَّكْرَانِ بِمَائِعٍ. وَلَا يَقَعُ مِمَّنْ نَامَ أَوْ زَالَ عَقْلُهُ بِجُنُونٍ أَوْ إِغْمَاءٍ وَلَا مِمَّنْ أَكْرَهَهُ قَادِرٌ ظُلْمًا بِعُقُوبَةٍ أَوْ تَهْدِيدٍ لَهُ أَوْ لِوَلَدِهِ."]]},{"id":"da104_3","label":"كِتَابُ الطَّلَاقِ · ٣","segs":[["matn","فَصْلٌ: وَمَنْ صَحَّ طَلَاقُهُ صَحَّ أَنْ يُوَكِّلَ غَيْرَهُ فِيهِ وَأَنْ يَتَوَكَّلَ عَنْ غَيْرِهِ وَلِلْوَكِيلِ أَنْ يُطَلِّقَ مَتَى شَاءَ مَا لَمْ يَحُدَّ لَهُ حَدًّا وَيَمْلِكُ طَلْقَةً مَا لَمْ يَجْعَلْ لَهُ أَكْثَرَ."]]},{"id":"da104_4","label":"كِتَابُ الطَّلَاقِ · ٤","segs":[["matn","وَإِنْ قَالَ لَهَا: طَلِّقِي نَفْسَكِ كَانَ لَهَا ذَلِكَ مَتَى شَاءَتْ وَتَمْلِكُ الثَّلَاثَ إِنْ قَالَ طَلَاقُكِ أَوْ أَمْرُكِ بِيَدِكِ أَوْ: وَكَّلْتُكِ فِي طَلَاقِكِ. وَيَبْطُلُ التَّوْكِيلُ بِالرُّجُوعِ وَبِالْوَطْءِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"da105","title":"بَابُ سُنَّةِ الطَّلَاقِ وَبِدْعَتِهِ","units":[{"id":"da105_1","label":"بَابُ سُنَّةِ الطَّلَاقِ وَبِدْعَتِهِ · ١","segs":[["matn","السُّنَّةُ لِمَنْ أَرَادَ طَلَاقَ زَوْجَتِهِ: أَنْ يُطَلِّقَهَا وَاحِدَةً فِي طُهْرٍ لَمْ يَطَأْهَا فِيهِ."]]},{"id":"da105_2","label":"بَابُ سُنَّةِ الطَّلَاقِ وَبِدْعَتِهِ · ٢","segs":[["matn","فَإِنْ طَلَّقَهَا ثَلَاثًا وَلَوْ بِكَلِمَاتٍ فَحَرَامٌ وَفِي الْحَيْضِ أَوْ فِي طُهْرٍ وَطِئَ فِيهِ وَلَوْ بِوَاحِدَةٍ فَبِدْعِيٌّ حَرَامٌ وَيَقَعُ. وَلَا سُنَّةَ وَلَا بِدْعَةَ لِمَنْ لَمْ يَدْخُلْ بِهَا وَلَا لِصَغِيرَةٍ وَآيِسَةٍ وَحَامِلٍ. وَيُبَاحُ الطَّلَاقُ وَالْخُلْعُ بِسُؤَالِهَا زَمَنَ الْبِدْعَةِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"da106","title":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ","units":[{"id":"da106_1","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ١","segs":[["matn","صَرِيحُهُ: لَا يَحْتَاجُ إِلَى نِيَّةٍ وَهُوَ: لَفْظُ الطَّلَاقِ وَمَا تَصَرَّفَ مِنْهُ غَيْرَ أَمْرٍ وَمُضَارِعٍ وَمُطَلِّقَةٍ: اسْمِ فَاعِلٍ."]]},{"id":"da106_2","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٢","segs":[["matn","فَإِذَا قَالَ لِزَوْجَتِهِ: أَنْتِ طَالِقٌ طَلُقَتْ هَازِلًا كَانَ أَوْ لَاعِبًا أَوْ لَمْ يَنْوِ حَتَّى وَلَوْ قِيلَ لَهُ: أَطَلَّقْتَ امْرَأَتَكَ؟ فَقَالَ: نَعَمْ يُرِيدُ الْكَذِبَ."]]},{"id":"da106_3","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٣","segs":[["matn","بِذَلِكَ وَمَنْ قَالَ: حَلَفْتُ بِالطَّلَاقِ وَأَرَادَ الْكَذِبَ ثُمَّ فَعَلَ مَا حَلَفَ عَلَيْهِ وَقَعَ الطَّلَاقُ حُكْمًا وَدُيِّنَ. وَإِنْ قَالَ: عَلَيَّ الطَّلَاقُ أَوْ يَلْزَمُنِي الطَّلَاقُ فَصَرِيحٌ مُنَجَّزًا أَوْ مُعَلَّقًا أَوْ مَحْلُوفًا بِهِ."]]},{"id":"da106_4","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٤","segs":[["matn","وَإِنْ قَالَ: عَلَيَّ الْحَرَامُ إِنْ نَوَى امْرَأَتَهُ فَظِهَارٌ وَإِلَّا فَلَغْوٌ. وَمَنْ طَلَّقَ زَوْجَتَهُ ثُمَّ قَالَ عَقِبَهُ لِضَرَّتِهَا: شَرَّكْتُكِ أَوْ: أَنْتِ شَرِيكَتُهَا أَوْ مِثْلُهَا: وَقَعَ عَلَيْهِمَا."]]},{"id":"da106_5","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٥","segs":[["matn","وَإِنْ قَالَ: عَلَيَّ الطَّلَاقُ أَوْ: امْرَأَتِي طَالِقٌ وَمَعَهُ أَكْثَرُ مِنِ امْرَأَةٍ فَإِنْ نَوَى امْرَأَةً مُعَيَّنَةً انْصَرَفَ إِلَيْهَا وَإِنْ نَوَى وَاحِدَةً مُبْهَمَةً أُخْرِجَتْ بِقُرْعَةٍ وَإِنْ لَمْ يَنْوِ شَيْئًا: طَلَقَ الْكُلُّ."]]},{"id":"da106_6","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٦","segs":[["matn","وَمَنْ طَلَّقَ فِي قَلْبِهِ لَمْ يَقَعْ فَإِنْ تَلَفَّظَ بِهِ أَوْ حَرَّكَ لِسَانَهُ: وَقَعَ وَلَوْ لَمْ يَسْمَعْهُ."]]},{"id":"da106_7","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٧","segs":[["matn","وَمَنْ كَتَبَ صَرِيحَ طَلَاقِ زَوْجَتِهِ وَقَعَ فَلَوْ قَالَ: لَمْ أُرِدْ إِلَّا تَجْوِيدَ خَطِّي أَوْ غَمَّ أَهْلِي قُبِلَ حُكْمًا. وَيَقَعُ بِإِشَارَةِ الْأَخْرَسِ فَقَطْ."]]},{"id":"da106_8","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٨","segs":[["matn","فَصْلٌ: وَكِنَايَتُهُ لَا بُدَّ فِيهَا مِنْ نِيَّةِ الطَّلَاقِ. وَهِيَ قِسْمَانِ: ظَاهِرَةٌ وَخَفِيَّةٌ. فَالظَّاهِرَةُ: يَقَعُ بِهَا الثَّلَاثُ وَالْخَفِيَّةُ: يَقَعُ بِهَا وَاحِدَةٌ مَا لَمْ يَنْوِ أَكْثَرَ."]]},{"id":"da106_9","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ٩","segs":[["matn","فَالظَّاهِرَةُ: أَنْتِ خَلِيَّةٌ وَبَرِيَّةٌ وَبَائِنٌ وَبَتَّةٌ وَبَتْلَةٌ وَأَنْتِ حُرَّةٌ وَأَنْتِ الْحَرَجُ وَحَبْلُكِ عَلَى غَارِبِكِ وَتَزَوَّجِي مَنْ شِئْتِ وَحَلَلْتِ لِلْأَزْوَاجِ وَلَا سَبِيلَ لِي عَلَيْكِ أَوْ لَا سُلْطَانَ وَأَعْتَقْتُكِ وَغَطِّي شَعْرَكِ وَتَقَنَّعِي."]]},{"id":"da106_10","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ١٠","segs":[["matn","وَالْخَفِيَّةُ: اخْرُجِي وَاذْهَبِي وَذُوقِي وَتَجَرَّعِي وَخَلَّيْتُكِ وَأَنْتِ مُخَلَّاةٌ وَأَنْتِ وَاحِدَةٌ وَلَسْتِ لِي بِامْرَأَةٍ وَاعْتَدِّي وَاسْتَبْرِئِي وَاعْتَزِلِي وَالْحَقِي بِأَهْلِكِ وَلَا حَاجَةَ لِي فِيكِ وَمَا بَقِيَ شَيْءٌ وَأَغْنَاكِ اللَّهُ وَإِنَّ اللَّهَ قَدْ طَلَّقَكِ وَاللَّهُ قَدْ أَرَاحَكِ مِنِّي وَجَرَى الْقَلَمُ."]]},{"id":"da106_11","label":"بَابُ صَرِيحِ الطَّلَاقِ وَكِنَايَتِهِ · ١١","segs":[["matn","وَلَا تُشْتَرَطُ النِّيَّةُ فِي حَالِ الْخُصُومَةِ وَالْغَضَبِ وَإِذَا سَأَلَتْهُ طَلَاقَهَا فَلَوْ قَالَ فِي هَذِهِ الْحَالَةِ: لَمْ أُرِدِ الطَّلَاقَ دُيِّنَ وَلَمْ يُقْبَلْ حُكْمًا."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"da107","title":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ","units":[{"id":"da107_1","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١","segs":[["matn","يَمْلِكُ الْحُرُّ وَالْمُبَعَّضُ ثَلَاثَ طَلَقَاتٍ وَالْعَبْدُ طَلْقَتَيْنِ. وَيَقَعُ الطَّلَاقُ بَائِنًا فِي أَرْبَعِ مَسَائِلَ: إِذَا كَانَ عَلَى عِوَضٍ أَوْ قَبْلَ الدُّخُولِ أَوْ فِي نِكَاحٍ فَاسِدٍ أَوْ بِالثَّلَاثِ."]]},{"id":"da107_2","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٢","segs":[["matn","وَيَقَعُ ثَلَاثًا إِذَا قَالَ: أَنْتِ طَالِقٌ بِلَا رَجْعَةٍ أَوِ الْبَتَّةَ أَوْ بَائِنًا وَإِنْ قَالَ: أَنْتِ الطَّلَاقُ أَوْ: أَنْتِ طَالِقٌ وَقَعَ وَاحِدَةٌ وَإِنْ نَوَى ثَلَاثًا وَقَعَ مَا نَوَاهُ."]]},{"id":"da107_3","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٣","segs":[["matn","وَيَقَعُ ثَلَاثًا إِذَا قَالَ: أَنْتِ طَالِقٌ كُلَّ الطَّلَاقِ أَوْ أَكْثَرَهُ أَوْ جَمِيعَهُ أَوْ عَدَدَ الْحَصَى وَنَحْوَهُ أَوْ قَالَ لَهَا: يَا مِائَةَ طَالِقٍ."]]},{"id":"da107_4","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٤","segs":[["matn","وَإِنْ قَالَ: أَنْتِ طَالِقٌ أَشَدَّ الطَّلَاقِ أَوْ أَغْلَظَهُ أَوْ أَطْوَلَهُ أَوْ مِلْءَ الدُّنْيَا أَوْ مِثْلَ الْجَبَلِ أَوْ عَلَى سَائِرِ الْمَذَاهِبِ: وَقَعَ وَاحِدَةٌ مَا لَمْ يَنْوِ أَكْثَرَ."]]},{"id":"da107_5","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٥","segs":[["matn","فَصْلٌ: وَالطَّلَاقُ لَا يَتَبَعَّضُ بَلْ جُزْءُ الطَّلْقَةِ كَهِيَ. وَإِنْ طَلَّقَ بَعْضَ زَوْجَتِهِ طَلُقَتْ كُلُّهَا."]]},{"id":"da107_6","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٦","segs":[["matn","وَإِنْ طَلَّقَ مِنْهَا جُزْءًا لَا يَنْفَصِلُ: كَيَدِهَا وَأُذُنِهَا وَأَنْفِهَا طَلُقَتْ وَإِنْ طَلَّقَ جُزْءًا يَنْفَصِلُ: كَشَعْرِهَا وَظُفُرِهَا وَسِنِّهَا لَمْ تَطْلُقْ."]]},{"id":"da107_7","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٧","segs":[["matn","فَصْلٌ: وَإِذَا قَالَ: أَنْتِ طَالِقٌ لَا بَلْ أَنْتِ طَالِقٌ: فَوَاحِدَةٌ. وَإِنْ قَالَ: أَنْتِ طَالِقٌ، طَالِقٌ، طَالِقٌ فَوَاحِدَةٌ مَا لَمْ يَنْوِ أَكْثَرَ."]]},{"id":"da107_8","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٨","segs":[["matn","وَأَنْتِ طَالِقٌ أَنْتِ طَالِقٌ: وَقَعَ ثِنْتَانِ إِلَّا أَنْ يَنْوِيَ تَأْكِيدًا مُتَّصِلًا أَوْ إِفْهَامًا. وَأَنْتِ طَالِقٌ فَطَالِقٌ أَوْ: ثُمَّ طَالِقٌ: فَثِنْتَانِ فِي الْمَدْخُولِ بِهَا وَتَبِينُ غَيْرُهَا بِالْأُولَى."]]},{"id":"da107_9","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ٩","segs":[["matn","وَ: أَنْتِ طَالِقٌ وَطَالِقٌ وَطَالِقٌ: فَثَلَاثٌ مَعًا وَلَوْ غَيْرَ مَدْخُولٍ بِهَا."]]},{"id":"da107_10","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١٠","segs":[["matn","فَصْلٌ: وَيَصِحُّ الِاسْتِثْنَاءُ فِي النِّصْفِ فَأَقَلَّ مِنْ مُطَلَّقَاتٍ وَطَلَقَاتٍ."]]},{"id":"da107_11","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١١","segs":[["matn","فَلَوْ قَالَ: أَنْتِ طَالِقٌ ثَلَاثًا إِلَّا وَاحِدَةً طَلُقَتْ ثِنْتَيْنِ وَ: أَنْتِ طَالِقٌ أَرْبَعًا إِلَّا ثِنْتَيْنِ: يَقَعُ ثِنْتَانِ وَنِسَائِي الْأَرْبَعُ طَوَالِقُ إِلَّا ثِنْتَيْنِ: طَلَقَ ثِنْتَانِ."]]},{"id":"da107_12","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١٢","segs":[["matn","وَشُرِطَ فِي الِاسْتِثْنَاءِ اتِّصَالٌ مُعْتَادٌ لَفْظًا أَوْ حُكْمًا: كَانْقِطَاعِهِ بِعُطَاسٍ وَنَحْوِهِ."]]},{"id":"da107_13","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١٣","segs":[["matn","فَصْلٌ فِي طَلَاقِ الزَّمَنِ: إِذَا قَالَ: أَنْتِ طَالِقٌ أَمْسِ أَوْ: قَبْلَ أَنْ أَتَزَوَّجَكِ وَنَوَى وُقُوعَهُ إِذًا: وَقَعَ وَإِلَّا فَلَا. وَأَنْتِ طَالِقٌ الْيَوْمَ إِذَا جَاءَ غَدٌ: فَلَغْوٌ."]]},{"id":"da107_14","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١٤","segs":[["matn","وَأَنْتِ طَالِقٌ غَدًا أَوْ يَوْمَ كَذَا وَقَعَ بِأَوَّلِهِمَا وَلَا يُقْبَلُ حُكْمًا إِنْ قَالَ: أَرَدْتُ آخِرَهُمَا. وَأَنْتِ طَالِقٌ فِي غَدٍ أَوْ فِي رَجَبٍ: يَقَعُ بِأَوَّلِهِمَا فَإِنْ قَالَ: أَرَدْتُ آخِرَهُمَا: قُبِلَ حُكْمًا."]]},{"id":"da107_15","label":"بَابُ مَا يَخْتَلِفُ بِهِ عَدَدُ الطَّلَاقِ · ١٥","segs":[["matn","وَأَنْتِ طَالِقٌ كُلَّ يَوْمٍ فَوَاحِدَةٌ. وَأَنْتِ طَالِقٌ فِي كُلِّ يَوْمٍ فَتَطْلُقُ فِي كُلِّ يَوْمٍ وَاحِدَةً وَ: أَنْتِ طَالِقٌ إِذَا مَضَى شَهْرٌ: فَبِمُضِيِّ ثَلَاثِينَ يَوْمًا وَإِذَا مَضَى الشَّهْرُ فَبِمُضِيِّهِ وَكَذَلِكَ إِذَا مَضَتْ سَنَةٌ أَوِ السَّنَةُ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"da108","title":"بَابُ تَعْلِيقِ الطَّلَاقِ","units":[{"id":"da108_1","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ١","segs":[["matn","إِذَا عَلَّقَ الطَّلَاقَ عَلَى وُجُودِ فِعْلٍ مُسْتَحِيلٍ كَإِنْ صَعِدْتِ السَّمَاءَ فَأَنْتِ طَالِقٌ لَمْ تَطْلُقْ وَإِنْ عَلَّقَهُ عَلَى عَدَمِ وُجُودِهِ كَإِنْ لَمْ تَصْعَدِي فَأَنْتِ طَالِقٌ طَلُقَتْ فِي الْحَالِ."]]},{"id":"da108_2","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٢","segs":[["matn","وَإِنْ عَلَّقَهُ عَلَى غَيْرِ الْمُسْتَحِيلِ لَمْ تَطْلُقْ إِلَّا بِالْيَأْسِ مِمَّا عَلَّقَ عَلَيْهِ الطَّلَاقَ مَا لَمْ يَكُنْ هُنَاكَ نِيَّةٌ أَوْ قَرِينَةٌ تَدُلُّ عَلَى الْفَوْرِ أَوْ يُقَيِّدْ بِزَمَنٍ فَيُعْمَلُ بِذَلِكَ."]]},{"id":"da108_3","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٣","segs":[["matn","فَصْلٌ: وَيَصِحُّ التَّعْلِيقُ مَعَ تَقَدُّمِ الشَّرْطِ وَتَأَخُّرِهِ كَإِنْ قُمْتِ فَأَنْتِ طَالِقٌ أَوْ أَنْتِ طَالِقٌ إِنْ قُمْتِ."]]},{"id":"da108_4","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٤","segs":[["matn","وَيُشْتَرَطُ لِصِحَّةِ التَّعْلِيقِ أَنْ يَنْوِيَهُ قَبْلَ فَرَاغِ التَّلَفُّظِ بِالطَّلَاقِ وَأَنْ يَكُونَ مُتَّصِلًا لَفْظًا أَوْ حُكْمًا فَلَا يَضُرُّ لَوْ عَطَسَ"]]},{"id":"da108_5","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٥","segs":[["matn","وَنَحْوَهُ أَوْ قَطَعَهُ بِكَلَامٍ مُنْتَظِمٍ كَأَنْتِ طَالِقٌ يَا زَانِيَةُ إِنْ قُمْتِ وَيَضُرُّ إِنْ قَطَعَهُ بِسُكُوتٍ أَوْ كَلَامٍ غَيْرِ مُنْتَظِمٍ كَقَوْلِهِ: سُبْحَانَ اللَّهِ وَتَطْلُقُ فِي الْحَالِ."]]},{"id":"da108_6","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٦","segs":[["matn","فَصْلٌ فِي مَسَائِلَ مُتَفَرِّقَةٍ: إِذَا قَالَ: إِنْ خَرَجْتِ بِغَيْرِ إِذْنِي فَأَنْتِ طَالِقٌ: فَأَذِنَ لَهَا وَلَمْ تَعْلَمْ أَوْ عَلِمَتْ وَخَرَجَتْ ثُمَّ خَرَجَتْ ثَانِيًا بِلَا إِذْنِهِ طَلُقَتْ مَا لَمْ يَأْذَنْ لَهَا فِي الْخُرُوجِ كُلَّمَا شَاءَتْ."]]},{"id":"da108_7","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٧","segs":[["matn","وَإِنْ خَرَجْتِ بِغَيْرِ إِذْنِ فُلَانٍ فَأَنْتِ طَالِقٌ فَمَاتَ فُلَانٌ وَخَرَجَتْ: لَمْ تَطْلُقْ. وَإِنْ خَرَجْتِ إِلَى غَيْرِ الْحَمَّامِ فَأَنْتِ طَالِقٌ فَخَرَجَتْ لَهُ ثُمَّ بَدَا لَهَا غَيْرُهُ: طَلُقَتْ."]]},{"id":"da108_8","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٨","segs":[["matn","وَزَوْجَتِي طَالِقٌ أَوْ عَبْدِي حُرٌّ إِنْ شَاءَ اللَّهُ أَوْ إِلَّا أَنْ يَشَاءَ اللَّهُ لَمْ تَنْفَعْهُ الْمَشِيئَةُ شَيْئًا وَوَقَعَ."]]},{"id":"da108_9","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ٩","segs":[["matn","وَإِنْ قَالَ: إِنْ شَاءَ فُلَانٌ: فَتَعْلِيقٌ لَمْ يَقَعْ إِلَّا أَنْ يَشَاءَ وَإِنْ قَالَ: إِلَّا أَنْ يَشَاءَ: فَمَوْقُوفٌ فَإِنْ أَبَى الْمَشِيئَةَ أَوْ جُنَّ أَوْ مَاتَ: وَقَعَ الطَّلَاقُ إِذًا."]]},{"id":"da108_10","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ١٠","segs":[["matn","وَأَنْتِ طَالِقٌ إِنْ رَأَيْتِ الْهِلَالَ عِيَانًا فَرَأَتْهُ فِي أَوَّلِ أَوْ ثَانِي أَوْ ثَالِثِ لَيْلَةٍ: وَقَعَ وَبَعْدَهَا لَمْ يَقَعْ."]]},{"id":"da108_11","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ١١","segs":[["matn","وَأَنْتِ طَالِقٌ إِنْ فَعَلْتِ كَذَا أَوْ إِنْ فَعَلْتُ أَنَا كَذَا فَفَعَلَتْهُ أَوْ فَعَلَهُ مُكْرَهًا أَوْ مَجْنُونًا أَوْ مُغْمًى عَلَيْهِ أَوْ نَائِمًا لَمْ يَقَعْ وَإِنْ فَعَلَتْهُ أَوْ فَعَلَهُ نَاسِيًا أَوْ جَاهِلًا وَقَعَ."]]},{"id":"da108_12","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ١٢","segs":[["matn","وَعَكْسُهُ مِثْلُهُ كَإِنْ لَمْ تَفْعَلِي كَذَا أَوْ إِنْ لَمْ أَفْعَلْ كَذَا فَلَمْ تَفْعَلْهُ أَوْ لَمْ يَفْعَلْهُ هُوَ."]]},{"id":"da108_13","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ١٣","segs":[["matn","فَصْلٌ: وَلَا يَقَعُ الطَّلَاقُ بِالشَّكِّ فِيهِ أَوْ فِيمَا عَلَّقَ عَلَيْهِ. فَمَنْ حَلَفَ لَا يَأْكُلُ تَمْرَةً مَثَلًا فَاشْتَبَهَتْ بِغَيْرِهَا وَأَكَلَ الْجَمِيعَ إِلَّا وَاحِدَةً: لَمْ يَحْنَثْ."]]},{"id":"da108_14","label":"بَابُ تَعْلِيقِ الطَّلَاقِ · ١٤","segs":[["matn","وَمَنْ شَكَّ فِي عَدَدِ مَا طَلَّقَ بَنَى عَلَى الْيَقِينِ وَهُوَ الْأَقَلُّ. وَمَنْ أَوْقَعَ بِزَوْجَتِهِ كَلِمَةً وَشَكَّ هَلْ هِيَ طَلَاقٌ أَوْ ظِهَارٌ: لَمْ يَلْزَمْهُ شَيْءٌ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"da109","title":"بَابُ الرَّجْعَةِ","units":[{"id":"da109_1","label":"بَابُ الرَّجْعَةِ · ١","segs":[["matn","وَهِيَ: إِعَادَةُ زَوْجَتِهِ الْمُطَلَّقَةِ إِلَى مَا كَانَتْ عَلَيْهِ بِغَيْرِ عَقْدٍ. وَمِنْ شَرْطِهَا: أَنْ يَكُونَ الطَّلَاقُ غَيْرَ بَائِنٍ وَأَنْ تَكُونَ فِي الْعِدَّةِ."]]},{"id":"da109_2","label":"بَابُ الرَّجْعَةِ · ٢","segs":[["matn","وَتَصِحُّ الرَّجْعَةُ بَعْدَ انْقِطَاعِ دَمِ الْحَيْضَةِ الثَّالِثَةِ حَيْثُ لَمْ تَغْتَسِلْ وَتَصِحُّ قَبْلَ وَضْعِ وَلَدٍ مُتَأَخِّرٍ. وَأَلْفَاظُهَا: رَاجَعْتُهَا وَرَجَعْتُهَا وَارْتَجَعْتُهَا وَأَمْسَكْتُهَا وَرَدَدْتُهَا وَنَحْوُهُ."]]},{"id":"da109_3","label":"بَابُ الرَّجْعَةِ · ٣","segs":[["matn","وَلَا تُشْتَرَطُ هَذِهِ الْأَلْفَاظُ بَلْ تَحْصُلُ رَجْعَتُهَا بِوَطْئِهَا لَا بِنَكَحْتُهَا أَوْ تَزَوَّجْتُهَا."]]},{"id":"da109_4","label":"بَابُ الرَّجْعَةِ · ٤","segs":[["matn","وَمَتَى اغْتَسَلَتْ مِنَ الْحَيْضَةِ الثَّالِثَةِ وَلَمْ يَرْتَجِعْهَا بَانَتْ وَلَمْ تَحِلَّ لَهُ إِلَّا بِعَقْدٍ جَدِيدٍ وَتَعُودُ عَلَى مَا بَقِيَ مِنْ طَلَاقِهَا."]]},{"id":"da109_5","label":"بَابُ الرَّجْعَةِ · ٥","segs":[["matn","فَصْلٌ: وَإِذَا طَلَّقَ الْحُرُّ ثَلَاثًا أَوْ طَلَّقَ الْعَبْدُ ثِنْتَيْنِ لَمْ تَحِلَّ لَهُ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ نِكَاحًا صَحِيحًا وَيَطَأَهَا"]]},{"id":"da109_6","label":"بَابُ الرَّجْعَةِ · ٦","segs":[["matn","فِي قُبُلِهَا مَعَ الِانْتِشَارِ وَلَوْ مَجْنُونًا أَوْ نَائِمًا أَوْ مُغْمًى عَلَيْهِ وَأَدْخَلَتْ ذَكَرَهُ فِي فَرْجِهَا أَوْ لَمْ يَبْلُغْ عَشْرًا أَوْ لَمْ يُنْزِلْ."]]},{"id":"da109_7","label":"بَابُ الرَّجْعَةِ · ٧","segs":[["matn","وَيَكْفِي تَغْيِيبُ الْحَشَفَةِ أَوْ قَدْرِهَا مِنْ مَجْبُوبٍ وَيَحْصُلُ التَّحْلِيلُ بِذَلِكَ مَا لَمْ يَكُنْ وَطِئَهَا فِي حَالِ الْحَيْضِ أَوِ النِّفَاسِ أَوِ الْإِحْرَامِ أَوْ فِي صَوْمِ الْفَرْضِ."]]},{"id":"da109_8","label":"بَابُ الرَّجْعَةِ · ٨","segs":[["matn","فَلَوْ طَلَّقَهَا الثَّانِي وَادَّعَتْ أَنَّهُ وَطِئَهَا وَكَذَّبَهَا فَالْقَوْلُ قَوْلُهُ فِي تَنْصِيفِ الْمَهْرِ وَقَوْلُهَا فِي إِبَاحَتِهَا لِلْأَوَّلِ."]]}],"group":"كِتَابُ الطَّلَاقِ"},{"id":"da110","title":"كِتَابُ الْإِيلَاءِ","units":[{"id":"da110_1","label":"كِتَابُ الْإِيلَاءِ · ١","segs":[["matn","وَهُوَ حَرَامٌ كَالظِّهَارِ. وَيَصِحُّ مِنْ زَوْجٍ يَصِحُّ طَلَاقُهُ سِوَى عَاجِزٍ عَنِ الْوَطْءِ: إِمَّا لِمَرَضٍ لَا يُرْجَى بُرْؤُهُ أَوْ لِجَبٍّ كَامِلٍ أَوْ شَلَلٍ."]]},{"id":"da110_2","label":"كِتَابُ الْإِيلَاءِ · ٢","segs":[["matn","فَإِذَا حَلَفَ الزَّوْجُ بِاللَّهِ تَعَالَى أَوْ بِصِفَةٍ مِنْ صِفَاتِهِ أَنَّهُ لَا يَطَأُ زَوْجَتَهُ أَبَدًا أَوْ مُدَّةً تَزِيدُ عَلَى أَرْبَعَةِ أَشْهُرٍ: صَارَ مُولِيًا."]]},{"id":"da110_3","label":"كِتَابُ الْإِيلَاءِ · ٣","segs":[["matn","وَيُؤَجِّلُ لَهُ الْحَاكِمُ إِنْ سَأَلَتْ زَوْجَتُهُ ذَلِكَ أَرْبَعَةَ أَشْهُرٍ مِنْ حِينِ يَمِينِهِ ثُمَّ يُخَيَّرُ بَعْدَهَا بَيْنَ أَنْ يُكَفِّرَ وَيَطَأَ أَوْ يُطَلِّقَ. فَإِنِ امْتَنَعَ مِنْ ذَلِكَ طَلَّقَ عَلَيْهِ الْحَاكِمُ."]]}],"group":"كِتَابُ الْإِيلَاءِ"},{"id":"da111","title":"كِتَابُ الظِّهَارِ","units":[{"id":"da111_1","label":"كِتَابُ الظِّهَارِ · ١","segs":[["matn","وَهُوَ: أَنْ يُشَبِّهَ امْرَأَتَهُ أَوْ عُضْوًا مِنْهَا بِمَنْ يَحْرُمُ عَلَيْهِ مِنْ رَجُلٍ أَوِ امْرَأَةٍ أَوْ بِعُضْوٍ مِنْهُ."]]},{"id":"da111_2","label":"كِتَابُ الظِّهَارِ · ٢","segs":[["matn","فَمَنْ قَالَ لِزَوْجَتِهِ: أَنْتِ أَوْ: يَدُكِ عَلَيَّ كَظَهْرِ أَوْ: يَدِ أُمِّي أَوْ: كَظَهْرِ أَوْ يَدِ زَيْدٍ أَوْ: أَنْتِ عَلَيَّ كَفُلَانَةَ الْأَجْنَبِيَّةِ أَوْ أَنْتِ عَلَيَّ حَرَامٌ أَوْ قَالَ: الْحِلُّ عَلَيَّ حَرَامٌ أَوْ مَا أَحَلَّ اللَّهُ لِي صَارَ مُظَاهِرًا."]]},{"id":"da111_3","label":"كِتَابُ الظِّهَارِ · ٣","segs":[["matn","وَإِنْ قَالَ: أَنْتِ عَلَيَّ كَأُمِّي أَوْ مِثْلُ أُمِّي وَأَطْلَقَ فَظِهَارٌ وَإِنْ نَوَى فِي الْكَرَامَةِ وَنَحْوِهَا فَلَا."]]},{"id":"da111_4","label":"كِتَابُ الظِّهَارِ · ٤","segs":[["matn","وَأَنْتِ أُمِّي أَوْ مِثْلُ أُمِّي أَوْ: عَلَيَّ الظِّهَارُ أَوْ: يَلْزَمُنِي لَيْسَ بِظِهَارٍ إِلَّا مَعَ نِيَّةٍ أَوْ قَرِينَةٍ."]]},{"id":"da111_5","label":"كِتَابُ الظِّهَارِ · ٥","segs":[["matn","وَأَنْتِ عَلَيَّ كَالْمَيْتَةِ أَوِ الدَّمِ أَوِ الْخِنْزِيرِ يَقَعُ مَا نَوَاهُ مِنْ طَلَاقٍ وَظِهَارٍ وَيَمِينٍ فَإِنْ لَمْ يَنْوِ شَيْئًا فَظِهَارٌ."]]},{"id":"da111_6","label":"كِتَابُ الظِّهَارِ · ٦","segs":[["matn","فَصْلٌ: وَيَصِحُّ الظِّهَارُ مِنْ كُلِّ مَنْ يَصِحُّ طَلَاقُهُ مُنَجَّزًا وَمُعَلَّقًا وَمَحْلُوفًا بِهِ."]]},{"id":"da111_7","label":"كِتَابُ الظِّهَارِ · ٧","segs":[["matn","فَإِنْ نَجَّزَهُ لِأَجْنَبِيَّةٍ أَوْ عَلَّقَهُ بِتَزْوِيجِهَا أَوْ قَالَ لَهَا أَنْتِ عَلَيَّ حَرَامٌ وَنَوَى أَبَدًا صَحَّ ظِهَارًا لَا إِنْ أَطْلَقَ أَوْ نَوَى إِذًا."]]},{"id":"da111_8","label":"كِتَابُ الظِّهَارِ · ٨","segs":[["matn","وَيَصِحُّ الظِّهَارُ مُؤَقَّتًا كَأَنْتِ عَلَيَّ كَظَهْرِ أُمِّي شَهْرَ رَمَضَانَ فَإِنْ وَطِئَ فِيهِ فَمُظَاهِرٌ وَإِلَّا فَلَا."]]},{"id":"da111_9","label":"كِتَابُ الظِّهَارِ · ٩","segs":[["matn","وَإِذَا صَحَّ الظِّهَارُ حَرُمَ عَلَى الْمُظَاهِرِ الْوَطْءُ وَدَوَاعِيهِ قَبْلَ التَّكْفِيرِ فَإِنْ وَطِئَ ثَبَتَتِ الْكَفَّارَةُ فِي ذِمَّتِهِ وَلَوْ مَجْنُونًا ثُمَّ لَا يَطَأُ حَتَّى يُكَفِّرَ وَإِنْ مَاتَ أَحَدُهُمَا قَبْلَ الْوَطْءِ فَلَا كَفَّارَةَ."]]},{"id":"da111_10","label":"كِتَابُ الظِّهَارِ · ١٠","segs":[["matn","فَصْلٌ: وَالْكَفَّارَةُ فِيهِ عَلَى التَّرْتِيبِ: عِتْقُ رَقَبَةٍ مُؤْمِنَةٍ سَالِمَةٍ مِنَ الْعُيُوبِ الْمُضِرَّةِ فِي الْعَمَلِ وَلَا يُجْزِئُ عِتْقُ الْأَخْرَسِ الْأَصَمِّ وَلَا الْجَنِينِ."]]},{"id":"da111_11","label":"كِتَابُ الظِّهَارِ · ١١","segs":[["matn","فَإِنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ وَيَلْزَمُهُ تَبْيِيتُ النِّيَّةِ مِنَ اللَّيْلِ."]]},{"id":"da111_12","label":"كِتَابُ الظِّهَارِ · ١٢","segs":[["matn","فَإِنْ لَمْ يَسْتَطِعِ الصَّوْمَ لِكِبَرٍ أَوْ مَرَضٍ لَا يُرْجَى بُرْؤُهُ أَطْعَمَ سِتِّينَ مِسْكِينًا لِكُلِّ مِسْكِينٍ مُدُّ بُرٍّ أَوْ نِصْفُ صَاعٍ مِنْ غَيْرِهِ وَلَا يُجْزِئُ الْخُبْزُ وَلَا غَيْرُ مَا يُجْزِئُ فِي الْفِطْرَةِ. وَلَا يُجْزِئُ الْعِتْقُ وَالصَّوْمُ وَالْإِطْعَامُ إِلَّا بِالنِّيَّةِ."]]}],"group":"كِتَابُ الظِّهَارِ"},{"id":"da112","title":"كِتَابُ اللِّعَانِ","units":[{"id":"da112_1","label":"كِتَابُ اللِّعَانِ · ١","segs":[["matn","إِذَا رَمَى الرَّجُلُ زَوْجَتَهُ بِالزِّنَا فَعَلَيْهِ حَدُّ الْقَذْفِ أَوِ التَّعْزِيرُ إِلَّا أَنْ يُقِيمَ الْبَيِّنَةَ أَوْ يُلَاعِنَ."]]},{"id":"da112_2","label":"كِتَابُ اللِّعَانِ · ٢","segs":[["matn","وَصِفَةُ اللِّعَانِ أَنْ يَقُولَ الزَّوْجُ أَرْبَعَ مَرَّاتٍ: أَشْهَدُ بِاللَّهِ إِنِّي لَمِنَ الصَّادِقِينَ فِيمَا رَمَيْتُهَا بِهِ مِنَ الزِّنَا وَيُشِيرُ إِلَيْهَا ثُمَّ يَزِيدُ فِي الْخَامِسَةِ:"]]},{"id":"da112_3","label":"كِتَابُ اللِّعَانِ · ٣","segs":[["matn","وَأَنَّ لَعْنَةَ اللَّهِ عَلَيْهِ إِنْ كَانَ مِنَ الْكَاذِبِينَ ثُمَّ تَقُولُ الزَّوْجَةُ أَرْبَعًا: أَشْهَدُ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ فِيمَا رَمَانِي بِهِ مِنَ الزِّنَا ثُمَّ تَزِيدُ فِي الْخَامِسَةِ:"]]},{"id":"da112_4","label":"كِتَابُ اللِّعَانِ · ٤","segs":[["matn","﴿أَنَّ غَضَبَ اللَّهِ عَلَيْهَا إِنْ كَانَ مِنَ الصَّادِقِينَ﴾ وَسُنَّ تَلَاعُنُهُمَا قِيَامًا بِحَضْرَةِ جَمَاعَةٍ وَأَنْ لَا يَنْقُصُوا عَنْ أَرْبَعَةٍ وَأَنْ يَأْمُرَ الْحَاكِمُ مَنْ يَضَعُ يَدَهُ عَلَى فَمِ الزَّوْجِ وَالزَّوْجَةِ عِنْدَ الْخَامِسَةِ وَيَقُولُ:"]]},{"id":"da112_5","label":"كِتَابُ اللِّعَانِ · ٥","segs":[["matn","اتَّقِ اللَّهَ فَإِنَّهَا الْمُوجِبَةُ وَعَذَابُ الدُّنْيَا أَهْوَنُ مِنْ عَذَابِ الْآخِرَةِ."]]},{"id":"da112_6","label":"كِتَابُ اللِّعَانِ · ٦","segs":[["matn","فَصْلٌ: وَشُرُوطُ اللِّعَانِ ثَلَاثَةٌ: كَوْنُهُ بَيْنَ زَوْجَيْنِ مُكَلَّفَيْنِ. الثَّانِي: أَنْ يَتَقَدَّمَهُ قَذْفُهَا بِالزِّنَا. الثَّالِثُ: أَنْ تُكَذِّبَهُ وَيَسْتَمِرَّ تَكْذِيبُهَا إِلَى انْقِضَاءِ اللِّعَانِ."]]},{"id":"da112_7","label":"كِتَابُ اللِّعَانِ · ٧","segs":[["matn","وَيَثْبُتُ بِتَمَامِ تَلَاعُنِهِمَا أَرْبَعَةُ أَحْكَامٍ: الْأَوَّلُ: سُقُوطُ الْحَدِّ أَوِ التَّعْزِيرِ. الثَّانِي: الْفُرْقَةُ وَلَوْ بِلَا فِعْلِ الْحَاكِمِ الثَّالِثُ: التَّحْرِيمُ الْمُؤَبَّدُ."]]},{"id":"da112_8","label":"كِتَابُ اللِّعَانِ · ٨","segs":[["matn","الرَّابِعُ: انْتِفَاءُ الْوَلَدِ وَيُعْتَبَرُ لِنَفْيِهِ ذِكْرُهُ صَرِيحًا كَأَشْهَدُ بِاللَّهِ لَقَدْ زَنَتْ وَمَا هَذَا وَلَدِي"]]},{"id":"da112_9","label":"كِتَابُ اللِّعَانِ · ٩","segs":[["matn","فَصْلٌ فِيمَا يَلْحَقُ مِنَ النَّسَبِ: إِذَا أَتَتْ زَوْجَةُ الرَّجُلِ بِوَلَدٍ بَعْدَ نِصْفِ سَنَةٍ مُنْذُ أَمْكَنَ اجْتِمَاعُهُ بِهَا وَلَوْ مَعَ غَيْبَتِهِ فَوْقَ أَرْبَعِ سِنِينَ حَتَّى"]]},{"id":"da112_10","label":"كِتَابُ اللِّعَانِ · ١٠","segs":[["matn","وَلَوْ كَانَ ابْنَ عَشْرٍ لَحِقَهُ نَسَبُهُ وَمَعَ هَذَا لَا يُحْكَمُ بِبُلُوغِهِ وَلَا يَلْزَمُهُ كُلُّ الْمَهْرِ وَلَا تَثْبُتُ بِهِ عِدَّةٌ وَلَا رَجْعَةٌ."]]},{"id":"da112_11","label":"كِتَابُ اللِّعَانِ · ١١","segs":[["matn","وَإِنْ أَتَتْ بِهِ لِدُونِ نِصْفِ سَنَةٍ مُنْذُ تَزَوَّجَهَا أَوْ عُلِمَ أَنَّهُ لَمْ يَجْتَمِعْ بِهَا كَمَا لَوْ تَزَوَّجَهَا بِحَضْرَةِ جَمَاعَةٍ ثُمَّ أَبَانَهَا فِي الْمَجْلِسِ أَوْ مَاتَ: لَمْ يَلْحَقْهُ."]]},{"id":"da112_12","label":"كِتَابُ اللِّعَانِ · ١٢","segs":[["matn","فَصْلٌ: وَمَنْ ثَبَتَ أَوْ أَقَرَّ أَنَّهُ وَطِئَ أَمَتَهُ فِي الْفَرْجِ أَوْ دُونَهُ ثُمَّ وَلَدَتْ لِنِصْفِ سَنَةٍ لَحِقَهُ."]]},{"id":"da112_13","label":"كِتَابُ اللِّعَانِ · ١٣","segs":[["matn","وَمَنْ أَعْتَقَ أَوْ بَاعَ مَنْ أَقَرَّ بِوَطْئِهَا فَوَلَدَتْ لِدُونِ نِصْفِ سَنَةٍ لَحِقَهُ وَالْبَيْعُ بَاطِلٌ وَلِنِصْفِ سَنَةٍ فَأَكْثَرَ لَحِقَ الْمُشْتَرِيَ."]]},{"id":"da112_14","label":"كِتَابُ اللِّعَانِ · ١٤","segs":[["matn","وَيَتْبَعُ الْوَلَدُ أَبَاهُ فِي النَّسَبِ وَأُمَّهُ فِي الْحُرِّيَّةِ وَكَذَا فِي الرِّقِّ إِلَّا مَعَ شَرْطٍ أَوْ غُرُورٍ وَيَتْبَعُ فِي الدِّينِ خَيْرَهُمَا وَفِي النَّجَاسَةِ وَتَحْرِيمِ النِّكَاحِ وَالذَّكَاةِ وَالْأَكْلِ أَخْبَثَهُمَا."]]}],"group":"كِتَابُ اللِّعَانِ"},{"id":"da113","title":"كِتَابُ الْعِدَّةِ","units":[{"id":"da113_1","label":"كِتَابُ الْعِدَّةِ · ١","segs":[["matn","وَهِيَ: تَرَبُّصُ مَنْ فَارَقَتْ زَوْجَهَا بِوَفَاةٍ أَوْ حَيَاةٍ. فَالْمُفَارَقَةُ بِالْوَفَاةِ تَعْتَدُّ مُطْلَقًا فَإِنْ كَانَتْ حَامِلًا مِنَ الْمَيِّتِ فَعِدَّتُهَا: حَتَّى تَضَعَ كُلَّ الْحَمْلِ."]]},{"id":"da113_2","label":"كِتَابُ الْعِدَّةِ · ٢","segs":[["matn","وَإِنْ لَمْ تَكُنْ حَامِلًا فَإِنْ كَانَتْ حُرَّةً فَعِدَّتُهَا: أَرْبَعَةُ أَشْهُرٍ وَعَشْرُ لَيَالٍ بِأَيَّامِهَا. وَعِدَّةُ الْأَمَةِ نِصْفُهَا."]]},{"id":"da113_3","label":"كِتَابُ الْعِدَّةِ · ٣","segs":[["matn","وَالْمُفَارَقَةُ فِي الْحَيَاةِ لَا تَعْتَدُّ إِلَّا إِنْ خَلَا بِهَا أَوْ وَطِئَهَا وَكَانَ مِمَّنْ يَطَأُ مِثْلُهُ وَيُوطَأُ مِثْلُهَا وَهُوَ: ابْنُ عَشْرٍ وَبِنْتُ تِسْعٍ. وَعِدَّتُهَا إِنْ كَانَتْ حَامِلًا بِوَضْعِ الْحَمْلِ."]]},{"id":"da113_4","label":"كِتَابُ الْعِدَّةِ · ٤","segs":[["matn","وَإِنْ لَمْ تَكُنْ حَامِلًا فَإِنْ كَانَتْ تَحِيضُ فَعِدَّتُهَا: ثَلَاثُ حِيَضٍ إِنْ كَانَتْ حُرَّةً وَحَيْضَتَانِ: إِنْ كَانَتْ أَمَةً وَإِنْ لَمْ تَكُنْ تَحِيضُ:"]]},{"id":"da113_5","label":"كِتَابُ الْعِدَّةِ · ٥","segs":[["matn","بِأَنْ كَانَتْ صَغِيرَةً أَوْ بَالِغَةً وَلَمْ تَرَ حَيْضًا وَلَا نِفَاسًا أَوْ كَانَتْ آيِسَةً وَهِيَ: مَنْ بَلَغَتْ خَمْسِينَ سَنَةً فَعِدَّتُهَا: ثَلَاثَةُ أَشْهُرٍ إِنْ كَانَتْ حُرَّةً وَشَهْرَانِ إِنْ كَانَتْ أَمَةً."]]},{"id":"da113_6","label":"كِتَابُ الْعِدَّةِ · ٦","segs":[["matn","وَمَنْ كَانَتْ تَحِيضُ ثُمَّ ارْتَفَعَ حَيْضُهَا قَبْلَ أَنْ تَبْلُغَ سِنَّ الْإِيَاسِ وَلَمْ تَعْلَمْ مَا رَفَعَهُ فَتَتَرَبَّصُ تِسْعَةَ أَشْهُرٍ ثُمَّ تَعْتَدُّ عِدَّةَ آيِسَةٍ."]]},{"id":"da113_7","label":"كِتَابُ الْعِدَّةِ · ٧","segs":[["matn","وَإِنْ عَلِمَتْ مَا رَفَعَهُ مِنْ مَرَضٍ أَوْ رَضَاعٍ أَوْ نَحْوِهِ فَلَا تَزَالُ مُتَرَبِّصَةً حَتَّى يَعُودَ الْحَيْضُ فَتَعْتَدَّ بِهِ أَوْ تَصِيرَ آيِسَةً فَتَعْتَدَّ عِدَّةَ آيِسَةٍ."]]},{"id":"da113_8","label":"كِتَابُ الْعِدَّةِ · ٨","segs":[["matn","فَصْلٌ: وَإِنْ وَطِئَ الْأَجْنَبِيُّ بِشُبْهَةٍ أَوْ نِكَاحٍ فَاسِدٍ أَوْ زِنًا مَنْ هِيَ فِي عِدَّتِهَا: أَتَمَّتْ عِدَّةَ الْأَوَّلِ ثُمَّ تَعْتَدُّ لِلثَّانِي."]]},{"id":"da113_9","label":"كِتَابُ الْعِدَّةِ · ٩","segs":[["matn","وَإِنْ وَطِئَهَا عَمْدًا مَنْ أَبَانَهَا: فَكَالْأَجْنَبِيِّ وَبِشُبْهَةٍ: اسْتَأْنَفَتِ الْعِدَّةَ مِنْ أَوَّلِهَا."]]},{"id":"da113_10","label":"كِتَابُ الْعِدَّةِ · ١٠","segs":[["matn","وَتَتَعَدَّدُ الْعِدَّةُ بِتَعَدُّدِ الْوَطْءِ بِالشُّبْهَةِ لَا بِالزِّنَا وَيَحْرُمُ عَلَى زَوْجِ الْمَوْطُوءَةِ بِشُبْهَةٍ أَوْ زِنًا أَنْ يَطَأَهَا فِي الْفَرْجِ مَا دَامَتْ فِي الْعِدَّةِ."]]},{"id":"da113_11","label":"كِتَابُ الْعِدَّةِ · ١١","segs":[["matn","فَصْلٌ: وَيَجِبُ الْإِحْدَادُ عَلَى الْمُتَوَفَّى عَنْهَا زَوْجُهَا بِنِكَاحٍ صَحِيحٍ مَا دَامَتْ فِي الْعِدَّةِ. وَيَجُوزُ لِلْبَائِنِ."]]},{"id":"da113_12","label":"كِتَابُ الْعِدَّةِ · ١٢","segs":[["matn","وَالْإِحْدَادُ: تَرْكُ الزِّينَةِ وَالطِّيبِ كَالزَّعْفَرَانِ وَلُبْسِ الْحُلِيِّ وَلَوْ خَاتَمًا وَلُبْسِ الْمُلَوَّنِ مِنَ الثِّيَابِ: كَالْأَحْمَرِ وَالْأَصْفَرِ وَالْأَخْضَرِ وَالتَّحْسِينِ بِالْحِنَّاءِ وَالْأَسْفِيدَاجِ وَالِاكْتِحَالِ بِالْأَسْوَدِ وَالِادِّهَانِ بِالْمُطَيَّبِ وَتَحْمِيرِ الْوَجْهِ وَحَفِّهِ."]]},{"id":"da113_13","label":"كِتَابُ الْعِدَّةِ · ١٣","segs":[["matn","وَلَهَا لُبْسُ الْأَبْيَضِ وَلَوْ حَرِيرًا. وَتَجِبُ: عِدَّةُ الْوَفَاةِ فِي الْمَنْزِلِ الَّذِي مَاتَ زَوْجُهَا فِيهِ مَا لَمْ يَتَعَذَّرْ. وَتَنْقَضِي الْعِدَّةُ بِمُضِيِّ الزَّمَانِ حَيْثُ كَانَتْ."]]}],"group":"كِتَابُ الْعِدَّةِ"},{"id":"da114","title":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ","units":[{"id":"da114_1","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ١","segs":[["matn","وَهُوَ وَاجِبٌ فِي ثَلَاثَةِ مَوَاضِعَ: أَحَدُهَا: إِذَا مَلَكَ الرَّجُلُ وَلَوْ طِفْلًا أَمَةً يُوطَأُ مِثْلُهَا حَتَّى وَلَوْ مَلَكَهَا مِنْ طِفْلٍ أَوْ أُنْثَى أَوْ كَانَ بَائِعُهَا قَدِ اسْتَبْرَأَهَا أَوْ بَاعَ أَوْ"]]},{"id":"da114_2","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ٢","segs":[["matn","وَهَبَ أَمَتَهُ ثُمَّ عَادَتْ إِلَيْهِ بِفَسْخٍ أَوْ غَيْرِهِ حَيْثُ انْتَقَلَ الْمِلْكُ لَمْ يَحِلَّ اسْتِمْتَاعُهُ بِهَا وَلَوْ بِالْقُبْلَةِ حَتَّى يَسْتَبْرِئَهَا."]]},{"id":"da114_3","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ٣","segs":[["matn","الثَّانِي: إِذَا مَلَكَ أَمَةً وَوَطِئَهَا ثُمَّ أَرَادَ أَنْ يُزَوِّجَهَا أَوْ يَبِيعَهَا قَبْلَ الِاسْتِبْرَاءِ فَيَحْرُمُ فَلَوْ خَالَفَ صَحَّ الْبَيْعُ دُونَ النِّكَاحِ وَإِنْ لَمْ يَطَأْهَا جَازَ."]]},{"id":"da114_4","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ٤","segs":[["matn","الثَّالِثُ: إِذَا أَعْتَقَ أَمَتَهُ أَوْ أُمَّ وَلَدِهِ أَوْ مَاتَ عَنْهَا لَزِمَهَا اسْتِبْرَاءُ نَفْسِهَا إِنْ لَمْ تَسْتَبْرِئْ قَبْلُ."]]},{"id":"da114_5","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ٥","segs":[["matn","فَصْلٌ: وَاسْتِبْرَاءُ الْحَامِلِ: بِوَضْعِ الْحَمْلِ وَمَنْ تَحِيضُ: بِحَيْضَةٍ وَالْآيِسَةِ وَالصَّغِيرَةِ وَالْبَالِغَةِ الَّتِي لَمْ تَرَ حَيْضًا: بِشَهْرٍ وَالْمُرْتَفِعِ حَيْضُهَا وَلَمْ تَدْرِ مَا رَفَعَهُ: بِعَشَرَةِ أَشْهُرٍ وَالْعَالِمَةِ مَا رَفَعَهُ: بِخَمْسِينَ سَنَةً وَشَهْرٍ."]]},{"id":"da114_6","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ٦","segs":[["matn","وَلَا يَكُونُ الِاسْتِبْرَاءُ إِلَّا بَعْدَ تَمَامِ مِلْكِ الْأَمَةِ كُلِّهَا وَلَوْ لَمْ يَقْبِضْهَا وَإِنْ مَلَكَهَا حَائِضًا لَمْ يَكْتَفِ بِتِلْكَ الْحَيْضَةِ. وَإِنْ مَلَكَ مَنْ تَلْزَمُهَا عِدَّةٌ اكْتُفِيَ بِهَا."]]},{"id":"da114_7","label":"بَابُ اسْتِبْرَاءِ الْإِمَاءِ · ٧","segs":[["matn","وَإِنِ ادَّعَتِ الْأَمَةُ الْمَوْرُوثَةُ تَحْرِيمَهَا عَلَى الْوَارِثِ بِوَطْءِ مُوَرِّثِهِ أَوِ ادَّعَتِ الْمُشْتَرَاةُ أَنَّ لَهَا زَوْجًا صُدِّقَتْ."]]}],"group":"كِتَابُ الْعِدَّةِ"},{"id":"da115","title":"كِتَابُ الرَّضَاعِ","units":[{"id":"da115_1","label":"كِتَابُ الرَّضَاعِ · ١","segs":[["matn","يُكْرَهُ اسْتِرْضَاعُ الْفَاجِرَةِ وَالْكَافِرَةِ وَسَيِّئَةِ الْخُلُقِ وَالْجَذْمَاءِ وَالْبَرْصَاءِ."]]},{"id":"da115_2","label":"كِتَابُ الرَّضَاعِ · ٢","segs":[["matn","وَإِذَا أَرْضَعَتِ الْمَرْأَةُ طِفْلًا بِلَبَنِ حَمْلٍ لَاحِقٍ بِالْوَاطِئِ صَارَ ذَلِكَ الطِّفْلُ وَلَدَهُمَا وَأَوْلَادُهُ وَإِنْ سَفَلُوا أَوْلَادَ وَلَدِهِمَا وَأَوْلَادُ كُلٍّ مِنْهُمَا مِنَ الْآخَرِ أَوْ غَيْرِهِ إِخْوَتَهُ وَأَخَوَاتِهِ وَقِسْ عَلَى ذَلِكَ."]]},{"id":"da115_3","label":"كِتَابُ الرَّضَاعِ · ٣","segs":[["matn","وَتَحْرِيمُ الرَّضَاعِ فِي النِّكَاحِ وَثُبُوتُ الْمَحْرَمِيَّةِ كَالنَّسَبِ بِشَرْطِ أَنْ يَرْتَضِعَ خَمْسَ رَضَعَاتٍ فِي الْعَامَيْنِ فَلَوِ ارْتَضَعَ بَقِيَّةَ الْخَمْسِ بَعْدَ الْعَامَيْنِ بِلَحْظَةٍ: لَمْ تَثْبُتِ الْحُرْمَةُ."]]},{"id":"da115_4","label":"كِتَابُ الرَّضَاعِ · ٤","segs":[["matn","وَمَتَى امْتَصَّ الثَّدْيَ ثُمَّ قَطَعَهُ وَلَوْ قَهْرًا ثُمَّ امْتَصَّ ثَانِيًا: فَرَضْعَةٌ ثَانِيَةٌ. وَالسُّعُوطُ فِي الْأَنْفِ وَالْوَجُورُ فِي الْفَمِ وَأَكْلُ مَا جُبِّنَ أَوْ خُلِطَ بِالْمَاءِ وَصِفَاتُهُ بَاقِيَةٌ: كَالرَّضَاعِ فِي الْحُرْمَةِ."]]},{"id":"da115_5","label":"كِتَابُ الرَّضَاعِ · ٥","segs":[["matn","وَإِنْ شُكَّ فِي الرَّضَاعِ أَوْ عَدَدِ الرَّضَعَاتِ بَنَى عَلَى الْيَقِينِ. وَإِنْ شَهِدَتْ بِهِ مَرْضِيَّةٌ ثَبَتَ التَّحْرِيمُ. وَمَنْ حَرُمَتْ عَلَيْهِ بِنْتُ امْرَأَةٍ كَأُمِّهِ وَجَدَّتِهِ وَأُخْتِهِ إِذَا أَرْضَعَتْ طِفْلَةً حَرَّمَتْهَا عَلَيْهِ أَبَدًا."]]},{"id":"da115_6","label":"كِتَابُ الرَّضَاعِ · ٦","segs":[["matn","وَمَنْ حَرُمَتْ عَلَيْهِ بِنْتُ رَجُلٍ: كَأَبِيهِ وَجَدِّهِ وَأَخِيهِ وَابْنِهِ إِذَا أَرْضَعَتْ زَوْجَتُهُ بِلَبَنِهِ طِفْلَةً حَرَّمَتْهَا عَلَيْهِ أَبَدًا."]]}],"group":"كِتَابُ الرَّضَاعِ"},{"id":"da116","title":"كِتَابُ النَّفَقَاتِ","units":[{"id":"da116_1","label":"كِتَابُ النَّفَقَاتِ · ١","segs":[["matn","يَجِبُ عَلَى الزَّوْجِ مَا لَا غِنَى لِزَوْجَتِهِ عَنْهُ مِنْ مَأْكَلٍ وَمَشْرَبٍ وَمَلْبَسٍ وَمَسْكَنٍ بِالْمَعْرُوفِ وَيَعْتَبِرُ الْحَاكِمُ ذَلِكَ إِنْ تَنَازَعَا بِحَالِهِمَا."]]},{"id":"da116_2","label":"كِتَابُ النَّفَقَاتِ · ٢","segs":[["matn","وَعَلَيْهِ مُؤْنَةُ نَظَافَتِهَا مِنْ دُهْنٍ وَسِدْرٍ وَثَمَنِ مَاءِ الشُّرْبِ وَالطَّهَارَةِ مِنَ الْحَدَثِ وَالْخَبَثِ وَغَسْلِ الثِّيَابِ. وَعَلَيْهِ لَهَا خَادِمٌ إِنْ كَانَتْ مِمَّنْ يُخْدَمُ مِثْلُهَا وَتَلْزَمُهُ مُؤْنِسَةٌ لِحَاجَةٍ."]]},{"id":"da116_3","label":"كِتَابُ النَّفَقَاتِ · ٣","segs":[["matn","فَصْلٌ: وَالْوَاجِبُ عَلَيْهِ دَفْعُ الطَّعَامِ فِي أَوَّلِ كُلِّ يَوْمٍ وَيَجُوزُ دَفْعُ عِوَضِهِ إِنْ تَرَاضَيَا وَلَا يَمْلِكُ الْحَاكِمُ أَنْ يَفْرِضَ عِوَضَ الْقُوتِ دَرَاهِمَ إِلَّا بِتَرَاضِيهِمَا وَفَرْضُهُ لَيْسَ بِلَازِمٍ."]]},{"id":"da116_4","label":"كِتَابُ النَّفَقَاتِ · ٤","segs":[["matn","وَيَجِبُ لَهَا الْكُسْوَةُ فِي أَوَّلِ كُلِّ عَامٍ وَتَمْلِكُهَا بِالْقَبْضِ فَلَا بَدَلَ لِمَا سُرِقَ أَوْ بَلِيَ وَإِنِ انْقَضَى الْعَامُ وَالْكُسْوَةُ بَاقِيَةٌ فَعَلَيْهِ كُسْوَةٌ لِلْعَامِ الْجَدِيدِ وَإِنْ مَاتَ أَوْ مَاتَتْ قَبْلَ انْقِضَائِهِ رَجَعَ عَلَيْهَا بِقِسْطِ مَا بَقِيَ."]]},{"id":"da116_5","label":"كِتَابُ النَّفَقَاتِ · ٥","segs":[["matn","وَإِنْ أَكَلَتْ مَعَهُ عَادَةً أَوْ كَسَاهَا بِلَا إِذْنٍ سَقَطَتْ."]]},{"id":"da116_6","label":"كِتَابُ النَّفَقَاتِ · ٦","segs":[["matn","فَصْلٌ: وَالرَّجْعِيَّةُ مُطْلَقًا وَالْبَائِنُ وَالنَّاشِزُ الْحَامِلُ وَالْمُتَوَفَّى عَنْهَا زَوْجُهَا حَامِلًا كَالزَّوْجَةِ فِي النَّفَقَةِ وَالْكُسْوَةِ وَالْمَسْكَنِ."]]},{"id":"da116_7","label":"كِتَابُ النَّفَقَاتِ · ٧","segs":[["matn","وَلَا شَيْءَ لِغَيْرِ الْحَامِلِ مِنْهُنَّ وَلَا لِمَنْ سَافَرَتْ لِحَاجَتِهَا أَوْ لِنُزْهَةٍ أَوْ زِيَارَةٍ وَلَوْ بِإِذْنِ الزَّوْجِ. وَإِنِ ادَّعَى نُشُوزَهَا أَوْ أَنَّهَا أَخَذَتْ نَفَقَتَهَا وَأَنْكَرَتْ فَقَوْلُهَا بِيَمِينِهَا."]]},{"id":"da116_8","label":"كِتَابُ النَّفَقَاتِ · ٨","segs":[["matn","وَمَتَى أَعْسَرَ بِنَفَقَةِ الْمُعْسِرِ أَوْ كُسْوَتِهِ أَوْ مَسْكَنِهِ أَوْ صَارَ لَا يَجِدُ النَّفَقَةَ إِلَّا يَوْمًا دُونَ يَوْمٍ أَوْ غَابَ الْمُوسِرُ وَتَعَذَّرَتْ عَلَيْهَا النَّفَقَةُ بِالِاسْتِدَانَةِ وَغَيْرِهَا فَلَهَا الْفَسْخُ فَوْرًا وَمُتَرَاخِيًا وَلَا يَصِحُّ بِلَا حَاكِمٍ فَيَفْسَخُ بِطَلَبِهَا أَوْ تَفْسَخُ بِأَمْرِهِ."]]},{"id":"da116_9","label":"كِتَابُ النَّفَقَاتِ · ٩","segs":[["matn","وَإِنِ امْتَنَعَ الْمُوسِرُ مِنَ النَّفَقَةِ أَوِ الْكُسْوَةِ وَقَدَرَتْ عَلَى مَالِهِ: فَلَهَا الْأَخْذُ مِنْهُ بِلَا إِذْنِهِ بِقَدْرِ كِفَايَتِهَا وَكِفَايَةِ وَلَدِهَا الصَّغِيرِ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"da117","title":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ","units":[{"id":"da117_1","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ١","segs":[["matn","يَجِبُ عَلَى الْقَرِيبِ نَفَقَةُ أَقَارِبِهِ وَكُسْوَتُهُمْ وَسُكْنَاهُمْ بِالْمَعْرُوفِ بِثَلَاثَةِ شُرُوطٍ الْأَوَّلُ: أَنْ يَكُونُوا فُقَرَاءَ لَا مَالَ لَهُمْ وَلَا كَسْبَ."]]},{"id":"da117_2","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٢","segs":[["matn","الثَّانِي: أَنْ يَكُونَ الْمُنْفِقُ غَنِيًّا إِمَّا بِمَالِهِ أَوْ كَسْبِهِ وَأَنْ يَفْضُلَ عَنْ قُوتِ نَفْسِهِ وَزَوْجَتِهِ وَرَقِيقِهِ يَوْمَهُ وَلَيْلَتَهُ."]]},{"id":"da117_3","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٣","segs":[["matn","الثَّالِثُ: أَنْ يَكُونَ وَارِثًا لَهُمْ بِفَرْضٍ أَوْ تَعْصِيبٍ إِلَّا الْأُصُولَ وَالْفُرُوعَ فَتَجِبُ لَهُمْ وَعَلَيْهِمْ مُطْلَقًا."]]},{"id":"da117_4","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٤","segs":[["matn","وَإِذَا كَانَ لِلْفَقِيرِ وَرَثَةٌ دُونَ الْأَبِ فَنَفَقَتُهُ عَلَى قَدْرِ إِرْثِهِمْ وَلَا يَلْزَمُ الْمُوسِرَ مِنْهُمْ مَعَ فَقْرِ الْآخَرِ سِوَى قَدْرِ إِرْثِهِ."]]},{"id":"da117_5","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٥","segs":[["matn","وَمَنْ قَدَرَ عَلَى الْكَسْبِ أُجْبِرَ لِنَفَقَةِ مَنْ تَجِبُ عَلَيْهِ مِنْ قَرِيبٍ وَزَوْجَةٍ وَمَنْ لَمْ يَجِدْ مَا يَكْفِي الْجَمِيعَ بَدَأَ بِنَفْسِهِ فَزَوْجَتِهِ فَرَقِيقِهِ فَوَلَدِهِ فَأَبِيهِ فَأُمِّهِ فَوَلَدِ ابْنِهِ فَجَدِّهِ فَأَخِيهِ ثُمَّ الْأَقْرَبِ فَالْأَقْرَبِ."]]},{"id":"da117_6","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٦","segs":[["matn","وَلِمُسْتَحِقِّ النَّفَقَةِ أَنْ يَأْخُذَ مَا يَكْفِيهِ مِنْ مَالِ مَنْ تَجِبُ عَلَيْهِ بِلَا إِذْنِهِ إِنِ امْتَنَعَ وَحَيْثُ امْتَنَعَ مِنْهَا زَوْجٌ أَوْ قَرِيبٌ وَأَنْفَقَ أَجْنَبِيٌّ بِنِيَّةِ الرُّجُوعِ رَجَعَ. وَلَا نَفَقَةَ مَعَ اخْتِلَافِ الدِّينِ إِلَّا بِالْوَلَاءِ."]]},{"id":"da117_7","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٧","segs":[["matn","فَصْلٌ: وَعَلَى السَّيِّدِ: نَفَقَةُ مَمْلُوكِهِ وَكُسْوَتُهُ وَمَسْكَنُهُ وَتَزْوِيجُهُ إِنْ طَلَبَ. وَلَهُ أَنْ يُسَافِرَ بِعَبْدِهِ الْمُزَوَّجِ وَأَنْ يَسْتَخْدِمَهُ نَهَارًا. وَعَلَيْهِ إِعْفَافُ أَمَتِهِ: إِمَّا بِوَطْئِهَا أَوْ تَزْوِيجِهَا أَوْ بَيْعِهَا."]]},{"id":"da117_8","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٨","segs":[["matn","وَيَحْرُمُ أَنْ يَضْرِبَهُ عَلَى وَجْهِهِ أَوْ يَشْتُمَ أَبَوَيْهِ وَلَوْ كَافِرَيْنِ أَوْ يُكَلِّفَهُ مِنَ الْعَمَلِ مَا لَا يُطِيقُ. وَيَجِبُ أَنْ يُرِيحَهُ وَقْتَ الْقَيْلُولَةِ وَوَقْتَ النَّوْمِ وَالصَّلَاةِ الْمَفْرُوضَةِ."]]},{"id":"da117_9","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ٩","segs":[["matn","وَتُسَنُّ مُدَاوَاتُهُ إِنْ مَرِضَ وَأَنْ يُطْعِمَهُ مِنْ طَعَامِهِ. وَلَهُ تَقْيِيدُهُ إِنْ خَافَ عَلَيْهِ وَتَأْدِيبُهُ. وَلَا يَصِحُّ نَفْلُهُ إِنْ أَبَقَ. وَلِلْإِنْسَانِ تَأْدِيبُ زَوْجَتِهِ وَوَلَدِهِ وَلَوْ مُكَلَّفًا بِضَرْبٍ غَيْرِ مُبَرِّحٍ. وَلَا يَلْزَمُهُ بَيْعُ رَقِيقِهِ مَعَ قِيَامِهِ بِحُقُوقِهِ."]]},{"id":"da117_10","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ١٠","segs":[["matn","فَصْلٌ: وَعَلَى مَالِكِ الْبَهِيمَةِ إِطْعَامُهَا وَسَقْيُهَا فَإِنِ امْتَنَعَ أُجْبِرَ فَإِنْ أَبَى أَوْ عَجَزَ: أُجْبِرَ عَلَى بَيْعِهَا أَوْ إِجَارَتِهَا أَوْ ذَبْحِهَا إِنْ كَانَتْ تُؤْكَلُ."]]},{"id":"da117_11","label":"بَابُ نَفَقَةِ الْأَقَارِبِ وَالْمَمَالِيكِ · ١١","segs":[["matn","وَيَحْرُمُ لَعْنُهَا وَتَحْمِيلُهَا مُشِقًّا وَحَلْبُهَا مَا يَضُرُّ وَلَدَهَا وَضَرْبُهَا فِي وَجْهِهَا وَوَسْمُهَا فِيهِ وَذَبْحُهَا إِنْ كَانَتْ لَا تُؤْكَلُ. وَيَجُوزُ اسْتِعْمَالُهَا فِي غَيْرِ مَا خُلِقَتْ لَهُ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"da118","title":"بَابُ الْحَضَانَةِ","units":[{"id":"da118_1","label":"بَابُ الْحَضَانَةِ · ١","segs":[["matn","وَهِيَ حِفْظُ الطِّفْلِ غَالِبًا عَمَّا يَضُرُّهُ وَالْقِيَامُ بِمَصَالِحِهِ: كَغَسْلِ رَأْسِهِ وَثِيَابِهِ وَدَهْنِهِ وَتَكْحِيلِهِ وَرَبْطِهِ فِي الْمَهْدِ وَنَحْوِهِ وَتَحْرِيكِهِ لِيَنَامَ."]]},{"id":"da118_2","label":"بَابُ الْحَضَانَةِ · ٢","segs":[["matn","وَالْأَحَقُّ بِهَا: الْأُمُّ وَلَوْ بِأُجْرَةِ مِثْلِهَا مَعَ وُجُودِ مُتَبَرِّعَةٍ ثُمَّ أُمَّهَاتُهَا الْقُرْبَى فَالْقُرْبَى ثُمَّ الْأَبُ ثُمَّ أُمَّهَاتُهُ ثُمَّ الْجَدُّ ثُمَّ أُمَّهَاتُهُ ثُمَّ الْأُخْتُ لِأَبَوَيْنِ ثُمَّ لِأُمٍّ ثُمَّ لِأَبٍ ثُمَّ الْخَالَةُ لِأَبَوَيْنِ"]]},{"id":"da118_3","label":"بَابُ الْحَضَانَةِ · ٣","segs":[["matn","ثُمَّ لِأُمٍّ ثُمَّ لِأَبٍ ثُمَّ الْعَمَّاتُ كَذَلِكَ ثُمَّ خَالَاتُ أُمِّهِ ثُمَّ خَالَاتُ أَبِيهِ ثُمَّ عَمَّاتُ أَبِيهِ ثُمَّ بَنَاتُ إِخْوَتِهِ وَأَخَوَاتِهِ ثُمَّ بَنَاتُ أَعْمَامِهِ وَعَمَّاتِهِ ثُمَّ لِبَاقِي الْعَصَبَةِ: الْأَقْرَبِ فَالْأَقْرَبِ."]]},{"id":"da118_4","label":"بَابُ الْحَضَانَةِ · ٤","segs":[["matn","وَلَا حَضَانَةَ لِمَنْ فِيهِ رِقٌّ وَلَا لِفَاسِقٍ وَلَا لِكَافِرٍ عَلَى مُسْلِمٍ وَلَا لِمُتَزَوِّجَةٍ بِأَجْنَبِيٍّ. وَمَتَى زَالَ الْمَانِعُ أَوْ أَسْقَطَ الْأَحَقُّ حَقَّهُ ثُمَّ عَادَ، عَادَ الْحَقُّ لَهُ."]]},{"id":"da118_5","label":"بَابُ الْحَضَانَةِ · ٥","segs":[["matn","وَإِنْ أَرَادَ أَحَدُ الْأَبَوَيْنِ السَّفَرَ وَيَرْجِعَ فَالْمُقِيمُ أَحَقُّ بِالْحَضَانَةِ وَإِنْ كَانَ لِلسُّكْنَى وَهُوَ: مَسَافَةَ قَصْرٍ فَالْأَبُ أَحَقُّ وَدُونَهَا فَالْأُمُّ أَحَقُّ."]]},{"id":"da118_6","label":"بَابُ الْحَضَانَةِ · ٦","segs":[["matn","فَصْلٌ: وَإِذَا بَلَغَ الصَّبِيُّ سَبْعَ سِنِينَ عَاقِلًا خُيِّرَ بَيْنَ أَبَوَيْهِ فَإِنِ اخْتَارَ أَبَاهُ كَانَ عِنْدَهُ لَيْلًا وَنَهَارًا وَلَا يُمْنَعُ مِنْ زِيَارَةِ أُمِّهِ وَلَا هِيَ مِنْ زِيَارَتِهِ وَإِنِ اخْتَارَ أُمَّهُ كَانَ عِنْدَهَا لَيْلًا وَعِنْدَ أَبِيهِ نَهَارًا لِيُؤَدِّبَهُ وَيُعَلِّمَهُ."]]},{"id":"da118_7","label":"بَابُ الْحَضَانَةِ · ٧","segs":[["matn","وَإِذَا بَلَغَتِ الْأُنْثَى سَبْعًا كَانَتْ عِنْدَ أَبِيهَا وُجُوبًا إِلَى أَنْ تَتَزَوَّجَ. وَيَمْنَعُهَا وَمَنْ يَقُومُ مَقَامَهُ مِنَ الِانْفِرَادِ."]]},{"id":"da118_8","label":"بَابُ الْحَضَانَةِ · ٨","segs":[["matn","وَلَا تُمْنَعُ الْأُمُّ مِنْ زِيَارَتِهَا وَلَا هِيَ مِنْ زِيَارَةِ أُمِّهَا إِنْ لَمْ يُخَفِ الْفَسَادُ. وَالْمَجْنُونُ وَلَوْ أُنْثَى عِنْدَ أُمِّهِ مُطْلَقًا. وَلَا يُتْرَكُ الْمَحْضُونُ بِيَدِ مَنْ لَا يَصُونُهُ وَيُصْلِحُهُ."]]}],"group":"كِتَابُ النَّفَقَاتِ"},{"id":"da119","title":"كِتَابُ الْجِنَايَاتِ","units":[{"id":"da119_1","label":"كِتَابُ الْجِنَايَاتِ · ١","segs":[["matn","وَهِيَ: التَّعَدِّي عَلَى الْبَدَنِ بِمَا يُوجِبُ قِصَاصًا أَوْ مَالًا. وَالْقَتْلُ ثَلَاثَةُ أَقْسَامٍ: أَحَدُهَا: الْعَمْدُ الْعُدْوَانُ وَيَخْتَصُّ بِهِ الْقِصَاصُ أَوِ الدِّيَةُ فَالْوَلِيُّ مُخَيَّرٌ وَعَفْوُهُ مَجَّانًا أَفْضَلُ."]]},{"id":"da119_2","label":"كِتَابُ الْجِنَايَاتِ · ٢","segs":[["matn","وَهُوَ: أَنْ يَقْصِدَ الْجَانِي مَنْ يَعْلَمُهُ آدَمِيًّا مَعْصُومًا فَيَقْتُلَهُ بِمَا يَغْلِبُ عَلَى الظَّنِّ مَوْتُهُ بِهِ فَلَوْ تَعَمَّدَ جَمَاعَةٌ قَتْلَ وَاحِدٍ قُتِلُوا جَمِيعًا إِنْ صَلَحَ فِعْلُ كُلِّ وَاحِدٍ مِنْهُمْ لِلْقَتْلِ"]]},{"id":"da119_3","label":"كِتَابُ الْجِنَايَاتِ · ٣","segs":[["matn","وَإِنْ جَرَحَ وَاحِدٌ جُرْحًا وَآخَرُ مِائَةً فَسَوَاءٌ وَمَنْ قَطَعَ أَوْ بَطَّ سِلْعَةً خَطِرَةً مِنْ مُكَلَّفٍ بِلَا إِذْنِهِ أَوْ مِنْ غَيْرِ مُكَلَّفٍ بِلَا إِذْنِ وَلِيِّهِ فَمَاتَ فَعَلَيْهِ الْقَوَدُ."]]},{"id":"da119_4","label":"كِتَابُ الْجِنَايَاتِ · ٤","segs":[["matn","الثَّانِي: شِبْهُ الْعَمْدِ وَهُوَ: أَنْ يَقْصِدَهُ بِجِنَايَةٍ لَا تَقْتُلُ غَالِبًا وَلَمْ يَجْرَحْهُ بِهَا فَإِنْ جَرَحَهُ وَلَوْ جُرْحًا صَغِيرًا قُتِلَ بِهِ."]]},{"id":"da119_5","label":"كِتَابُ الْجِنَايَاتِ · ٥","segs":[["matn","الثَّالِثُ: الْخَطَأُ وَهُوَ: أَنْ يَفْعَلَ مَا يَجُوزُ لَهُ فِعْلُهُ مِنْ دَقٍّ أَوْ رَمْيِ صَيْدٍ وَنَحْوِهِ أَوْ يَظُنَّهُ مُبَاحَ الدَّمِ فَيَبِينَ آدَمِيًّا مَعْصُومًا."]]},{"id":"da119_6","label":"كِتَابُ الْجِنَايَاتِ · ٦","segs":[["matn","فَفِي الْقِسْمَيْنِ الْأَخِيرَيْنِ الْكَفَّارَةُ عَلَى الْقَاتِلِ وَالدِّيَةُ عَلَى عَاقِلَتِهِ."]]},{"id":"da119_7","label":"كِتَابُ الْجِنَايَاتِ · ٧","segs":[["matn","وَمَنْ قَالَ لِإِنْسَانٍ: اقْتُلْنِي أَوِ اجْرَحْنِي فَقَتَلَهُ أَوْ جَرَحَهُ: لَمْ يَلْزَمْهُ شَيْءٌ وَكَذَا لَوْ دَفَعَ لِغَيْرِ مُكَلَّفٍ آلَةَ قَتْلٍ وَلَمْ يَأْمُرْهُ بِهِ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"da120","title":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ","units":[{"id":"da120_1","label":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ · ١","segs":[["matn","وَهِيَ أَرْبَعَةٌ: أَحَدُهَا: تَكْلِيفُ الْقَاتِلِ فَلَا قِصَاصَ عَلَى صَغِيرٍ وَمَجْنُونٍ بَلِ الْكَفَّارَةُ فِي مَالِهِمَا وَالدِّيَةُ عَلَى عَاقِلَتِهِمَا."]]},{"id":"da120_2","label":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ · ٢","segs":[["matn","الثَّانِي: عِصْمَةُ الْمَقْتُولِ فَلَا كَفَّارَةَ وَلَا دِيَةَ عَلَى قَاتِلِ حَرْبِيٍّ أَوْ مُرْتَدٍّ أَوْ زَانٍ مُحْصَنٍ وَلَوْ أَنَّهُ مِثْلُهُ."]]},{"id":"da120_3","label":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ · ٣","segs":[["matn","الثَّالِثُ: الْمُكَافَأَةُ: بِأَنْ لَا يَفْضُلَ الْقَاتِلُ الْمَقْتُولَ حَالَ الْجِنَايَةِ بِالْإِسْلَامِ أَوِ الْحُرِّيَّةِ أَوِ الْمِلْكِ."]]},{"id":"da120_4","label":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ · ٤","segs":[["matn","فَلَا يُقْتَلُ الْمُسْلِمُ وَلَوْ عَبْدًا بِالْكَافِرِ وَلَوْ حُرًّا وَلَا الْحُرُّ وَلَوْ ذِمِّيًّا بِالْعَبْدِ وَلَوْ مُسْلِمًا وَلَا الْمُكَاتَبُ بِعَبْدِهِ وَلَوْ كَانَ ذَا رَحِمٍ مَحْرَمٍ لَهُ."]]},{"id":"da120_5","label":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ · ٥","segs":[["matn","وَيُقْتَلُ الْحُرُّ الْمُسْلِمُ وَلَوْ ذَكَرًا بِالْحُرِّ الْمُسْلِمِ وَلَوْ أُنْثَى وَالرَّقِيقُ كَذَلِكَ وَبِمَنْ هُوَ أَعْلَى مِنْهُ وَالذِّمِّيُّ كَذَلِكَ."]]},{"id":"da120_6","label":"بَابُ شُرُوطِ الْقِصَاصِ فِي النَّفْسِ · ٦","segs":[["matn","الرَّابِعُ: أَنْ يَكُونَ الْمَقْتُولُ لَيْسَ بِوَلَدٍ لِلْقَاتِلِ فَلَا يُقْتَلُ الْأَبُ وَإِنْ عَلَا وَلَا الْأُمُّ وَإِنْ عَلَتْ بِالْوَلَدِ وَلَا بِوَلَدِ الْوَلَدِ وَإِنْ سَفَلَ وَيُورَثُ الْقِصَاصُ عَلَى قَدْرِ الْمِيرَاثِ فَمَتَى وَرِثَ الْقَاتِلُ أَوْ وَلَدُهُ شَيْئًا مِنَ الْقِصَاصِ فَلَا قِصَاصَ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"da121","title":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ","units":[{"id":"da121_1","label":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ · ١","segs":[["matn","وَهِيَ ثَلَاثَةٌ: أَحَدُهَا: تَكْلِيفُ الْمُسْتَحِقِّ فَإِنْ كَانَ صَغِيرًا أَوْ مَجْنُونًا حُبِسَ الْجَانِي إِلَى تَكْلِيفِهِ فَإِنِ احْتَاجَ لِنَفَقَةٍ فَلِوَلِيِّ الْمَجْنُونِ فَقَطِ الْعَفْوُ إِلَى الدِّيَةِ."]]},{"id":"da121_2","label":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ · ٢","segs":[["matn","الثَّانِي: اتِّفَاقُ الْمُسْتَحِقِّينَ عَلَى اسْتِيفَائِهِ فَلَا يَنْفَرِدُ بِهِ بَعْضُهُمْ وَيُنْتَظَرُ قُدُومُ الْغَائِبِ وَتَكْلِيفُ غَيْرِ الْمُكَلَّفِ. وَمَنْ مَاتَ مِنَ الْمُسْتَحِقِّينَ فَوَارِثُهُ كَهُوَ."]]},{"id":"da121_3","label":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ · ٣","segs":[["matn","وَإِنْ عَفَا بَعْضُهُمْ وَلَوْ زَوْجًا أَوْ زَوْجَةً أَوْ أَقَرَّ بِعَفْوِ شَرِيكِهِ سَقَطَ الْقِصَاصُ."]]},{"id":"da121_4","label":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ · ٤","segs":[["matn","الثَّالِثُ: أَنْ يُؤْمَنَ فِي اسْتِيفَائِهِ تَعَدِّيهِ إِلَى الْغَيْرِ فَلَوْ لَزِمَ الْقِصَاصُ حَامِلًا لَمْ تُقْتَلْ حَتَّى تَضَعَ ثُمَّ إِنْ وُجِدَ مَنْ يُرْضِعُهُ قُتِلَتْ وَإِلَّا فَلَا حَتَّى تُرْضِعَهُ حَوْلَيْنِ."]]},{"id":"da121_5","label":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ · ٥","segs":[["matn","فَصْلٌ: وَيَحْرُمُ اسْتِيفَاءُ الْقِصَاصِ بِلَا حَضْرَةِ السُّلْطَانِ أَوْ نَائِبِهِ وَيَقَعُ الْمَوْقِعَ. وَيَحْرُمُ قَتْلُ الْجَانِي بِغَيْرِ السَّيْفِ وَقَطْعُ طَرَفِهِ بِغَيْرِ السِّكِّينِ لِئَلَّا يَحِيفَ."]]},{"id":"da121_6","label":"بَابُ شُرُوطِ اسْتِيفَاءِ الْقِصَاصِ · ٦","segs":[["matn","وَإِنْ بَطَشَ وَلِيُّ الْمَقْتُولِ بِالْجَانِي فَظَنَّ أَنَّهُ قَتَلَهُ فَلَمْ يَكُنْ وَدَاوَاهُ أَهْلُهُ حَتَّى بَرِئَ: فَإِنْ شَاءَ الْوَلِيُّ دَفَعَ دِيَةَ فِعْلِهِ وَقَتَلَهُ وَإِلَّا تَرَكَهُ."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"da122","title":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ","units":[{"id":"da122_1","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ١","segs":[["matn","مَنْ أُخِذَ بِغَيْرِهِ فِي النَّفْسِ أُخِذَ بِهِ فِيمَا دُونَهَا وَمَنْ لَا فَلَا. وَشُرُوطُهُ أَرْبَعَةٌ: أَحَدُهَا: الْعَمْدُ الْعُدْوَانُ فَلَا قِصَاصَ فِي غَيْرِهِ."]]},{"id":"da122_2","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٢","segs":[["matn","الثَّانِي: إِمْكَانُ الِاسْتِيفَاءِ بِلَا حَيْفٍ: بِأَنْ يَكُونَ الْقَطْعُ مِنْ مَفْصِلٍ أَوْ يَنْتَهِيَ إِلَى حَدٍّ كَمَارِنِ الْأَنْفِ وَهُوَ: مَا لَانَ مِنْهُ فَلَا قِصَاصَ فِي جَائِفَةٍ وَلَا فِي قَطْعِ الْقَصَبَةِ أَوْ قَطْعِ بَعْضِ سَاعِدٍ أَوْ سَاقٍ أَوْ."]]},{"id":"da122_3","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٣","segs":[["matn","عَضُدٍ أَوْ وَرِكٍ فَإِنْ خَالَفَ فَاقْتَصَّ بِقَدْرِ حَقِّهِ وَلَمْ يَسْرِ: وَقَعَ الْمَوْقِعَ وَلَمْ يَلْزَمْهُ شَيْءٌ."]]},{"id":"da122_4","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٤","segs":[["matn","الثَّالِثُ: الْمُسَاوَاةُ فِي الِاسْمِ فَلَا تُقْطَعُ الْيَدُ بِالرِّجْلِ وَعَكْسُهُ وَفِي الْمَوْضِعِ: فَلَا تُقْطَعُ الْيَمِينُ بِالشِّمَالِ وَعَكْسُهُ."]]},{"id":"da122_5","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٥","segs":[["matn","الرَّابِعُ: مُرَاعَاةُ الصِّحَّةِ وَالْكَمَالِ فَلَا تُؤْخَذُ كَامِلَةُ الْأَصَابِعِ أَوِ الْأَظْفَارِ بِنَاقِصَتِهَا وَلَا عَيْنٌ صَحِيحَةٌ بِقَائِمَةٍ وَلَا لِسَانٌ نَاطِقٌ بِأَخْرَسَ"]]},{"id":"da122_6","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٦","segs":[["matn","وَلَا صَحِيحٌ بِأَشَلَّ مِنْ يَدٍ وَرِجْلٍ وَأُصْبُعٍ وَذَكَرٍ وَلَا ذَكَرُ فَحْلٍ بِذَكَرِ خَصِيٍّ وَيُؤْخَذُ مَارِنُ صَحِيحٍ بِمَارِنٍ أَشَلَّ وَأُذُنٌ صَحِيحَةٌ بِأُذُنٍ شَلَّاءَ."]]},{"id":"da122_7","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٧","segs":[["matn","فَصْلٌ: وَيُشْتَرَطُ لِجَوَازِ الْقِصَاصِ فِي الْجُرُوحِ انْتِهَاؤُهَا إِلَى عَظْمٍ: كَجُرْحِ الْعَضُدِ وَالسَّاعِدِ وَالْفَخِذِ وَالسَّاقِ وَالْقَدَمِ وَكَالْمُوضِحَةِ وَالْهَاشِمَةِ وَالْمُنَقِّلَةِ وَالْمَأْمُومَةِ."]]},{"id":"da122_8","label":"بَابُ شُرُوطِ الْقِصَاصِ فِيمَا دُونَ النَّفْسِ · ٨","segs":[["matn","وَسِرَايَةُ الْقِصَاصِ هَدْرٌ وَسِرَايَةُ الْجِنَايَةِ مَضْمُونَةٌ مَا لَمْ يَقْتَصَّ رَبُّهَا قَبْلَ بُرْئِهِ: فَهَدْرٌ أَيْضًا."]]}],"group":"كِتَابُ الْجِنَايَاتِ"},{"id":"da123","title":"كِتَابُ الدِّيَاتِ","units":[{"id":"da123_1","label":"كِتَابُ الدِّيَاتِ · ١","segs":[["matn","مَنْ أَتْلَفَ إِنْسَانًا أَوْ جُزْءًا مِنْهُ بِمُبَاشَرَةٍ أَوْ سَبَبٍ: إِنْ كَانَ عَمْدًا فَالدِّيَةُ فِي مَالِهِ وَإِنْ كَانَ غَيْرَ عَمْدٍ فَعَلَى عَاقِلَتِهِ."]]},{"id":"da123_2","label":"كِتَابُ الدِّيَاتِ · ٢","segs":[["matn","وَمَنْ حَفَرَ تَعَدِّيًا بِئْرًا قَصِيرَةً فَعَمَّقَهَا آخَرُ: فَضَمَانُ تَالِفٍ بَيْنَهُمَا وَإِنْ وَضَعَ ثَالِثٌ سِكِّينًا فَأَثْلَاثًا وَإِنْ وَضَعَ وَاحِدٌ حَجَرًا تَعَدِّيًا فَعَثَرَ فِيهِ إِنْسَانٌ فَوَقَعَ فِي الْبِئْرِ: فَالضَّمَانُ عَلَى وَاضِعِ الْحَجَرِ كَالدَّافِعِ."]]},{"id":"da123_3","label":"كِتَابُ الدِّيَاتِ · ٣","segs":[["matn","وَإِنْ تَجَاذَبَ حُرَّانِ مُكَلَّفَانِ حَبْلًا فَانْقَطَعَ فَسَقَطَا مَيِّتَيْنِ: فَعَلَى عَاقِلَةِ كُلٍّ دِيَةُ الْآخَرِ وَإِنِ اصْطَدَمَا فَكَذَلِكَ. وَمَنْ أَرْكَبَ صَغِيرَيْنِ لَا وِلَايَةَ لَهُ عَلَى وَاحِدٍ مِنْهُمَا فَاصْطَدَمَا فَمَاتَا: فَدِيَتُهُمَا مِنْ مَالِهِ."]]},{"id":"da123_4","label":"كِتَابُ الدِّيَاتِ · ٤","segs":[["matn","وَمَنْ أَرْسَلَ صَغِيرًا لِحَاجَةٍ فَأَتْلَفَ نَفْسًا أَوْ مَالًا: فَالضَّمَانُ عَلَى مُرْسِلِهِ. وَمَنْ أَلْقَى حَجَرًا أَوْ عِدْلًا مَمْلُوءًا بِسَفِينَةٍ فَغَرِقَتْ ضَمِنَ جَمِيعَ مَا فِيهَا."]]},{"id":"da123_5","label":"كِتَابُ الدِّيَاتِ · ٥","segs":[["matn","وَمَنِ اضْطُرَّ إِلَى طَعَامِ غَيْرِ مُضْطَرٍّ أَوْ شَرَابِهِ فَمَنَعَهُ حَتَّى مَاتَ أَوْ أَخَذَ طَعَامَ غَيْرِهِ أَوْ شَرَابَهُ وَهُوَ عَاجِزٌ أَوْ أَخَذَ دَابَّتَهُ أَوْ مَا يَدْفَعُ بِهِ عَنْ نَفْسِهِ مِنْ سَبُعٍ وَنَحْوِهِ فَأَهْلَكَهُ ضَمِنَهُ."]]},{"id":"da123_6","label":"كِتَابُ الدِّيَاتِ · ٦","segs":[["matn","وَإِنْ مَاتَتْ حَامِلٌ أَوْ حَمْلُهَا مِنْهُ مِنْ رِيحِ طَعَامٍ ضَمِنَ رَبُّهُ إِنْ عَلِمَ ذَلِكَ مِنْ عَادَتِهَا"]]},{"id":"da123_7","label":"كِتَابُ الدِّيَاتِ · ٧","segs":[["matn","فَصْلٌ: وَإِنْ تَلِفَ وَاقِعٌ عَلَى نَائِمٍ غَيْرِ مُتَعَدٍّ بِنَوْمِهِ فَهَدْرٌ وَإِنْ تَلِفَ النَّائِمُ فَغَيْرُ هَدْرٍ."]]},{"id":"da123_8","label":"كِتَابُ الدِّيَاتِ · ٨","segs":[["matn","وَإِنْ سَلَّمَ بَالِغٌ عَاقِلٌ نَفْسَهُ أَوْ وَلَدَهُ إِلَى سَابِحٍ حَاذِقٍ لِيُعَلِّمَهُ فَغَرِقَ أَوْ أَمَرَ مُكَلَّفًا يَنْزِلُ بِئْرًا أَوْ يَصْعَدُ شَجَرَةً فَهَلَكَ أَوْ تَلِفَ أَجِيرٌ لِحَفْرِ بِئْرٍ أَوْ بِنَاءِ حَائِطٍ بِهَدْمٍ"]]},{"id":"da123_9","label":"كِتَابُ الدِّيَاتِ · ٩","segs":[["matn","وَنَحْوِهِ أَوْ أَمْكَنَهُ إِنْجَاءُ نَفْسٍ مِنْ مَهْلَكَةٍ فَلَمْ يَفْعَلْ أَوْ أَدَّبَ وَلَدَهُ أَوْ زَوْجَتَهُ فِي نُشُوزٍ أَوْ أَدَّبَ سُلْطَانٌ رَعِيَّتَهُ وَلَمْ يُسْرِفْ فَهَدْرٌ فِي الْجَمِيعِ."]]},{"id":"da123_10","label":"كِتَابُ الدِّيَاتِ · ١٠","segs":[["matn","وَإِنْ أَسْرَفَ أَوْ زَادَ عَلَى مَا يَحْصُلُ بِهِ الْمَقْصُودُ أَوْ ضَرَبَ مَنْ لَا عَقْلَ لَهُ مِنْ صَبِيٍّ أَوْ غَيْرِهِ: ضَمِنَ."]]},{"id":"da123_11","label":"كِتَابُ الدِّيَاتِ · ١١","segs":[["matn","وَمَنْ نَامَ عَلَى سَقْفٍ فَهَوَى بِهِ لَمْ يَضْمَنْ مَا تَلِفَ بِسُقُوطِهِ."]]},{"id":"da123_12","label":"كِتَابُ الدِّيَاتِ · ١٢","segs":[["matn","فَصْلٌ فِي مَقَادِيرِ دِيَاتِ النَّفْسِ: دِيَةُ الْحُرِّ الْمُسْلِمِ طِفْلًا كَانَ أَوْ كَبِيرًا مِائَةُ بَعِيرٍ أَوْ مِائَتَا بَقَرَةٍ أَوْ أَلْفَا شَاةٍ أَوْ أَلْفُ مِثْقَالٍ ذَهَبٍ أَوِ اثْنَا عَشَرَ أَلْفَ دِرْهَمٍ فِضَّةٍ."]]},{"id":"da123_13","label":"كِتَابُ الدِّيَاتِ · ١٣","segs":[["matn","وَدِيَةُ الْحُرَّةِ الْمُسْلِمَةِ عَلَى النِّصْفِ مِنْ ذَلِكَ وَدِيَةُ الْكِتَابِيِّ الْحُرِّ كَدِيَةِ الْحُرَّةِ الْمُسْلِمَةِ وَدِيَةُ الْكِتَابِيَّةِ عَلَى النِّصْفِ وَدِيَةُ الْمَجُوسِيِّ الْحُرِّ ثَمَانُمِائَةِ دِرْهَمٍ وَالْمَجُوسِيَّةِ عَلَى النِّصْفِ."]]},{"id":"da123_14","label":"كِتَابُ الدِّيَاتِ · ١٤","segs":[["matn","وَيَسْتَوِي الذَّكَرُ وَالْأُنْثَى فِيمَا يُوجِبُ دُونَ ثُلُثِ الدِّيَةِ فَلَوْ قَطَعَ ثَلَاثَ أَصَابِعِ حُرَّةٍ مُسْلِمَةٍ لَزِمَهُ ثَلَاثُونَ بَعِيرًا فَلَوْ قَطَعَ رَابِعَةً قَبْلَ بُرْءٍ رُدَّتْ إِلَى عِشْرِينَ."]]},{"id":"da123_15","label":"كِتَابُ الدِّيَاتِ · ١٥","segs":[["matn","وَتُغَلَّظُ دِيَةُ قَتْلِ الْخَطَأِ فِي كُلٍّ مِنْ حَرَمِ مَكَّةَ وَإِحْرَامٍ وَشَهْرٍ حَرَامٍ بِالثُّلُثِ فَمَعَ اجْتِمَاعِ الثَّلَاثَةِ يَجِبُ دِيَتَانِ."]]},{"id":"da123_16","label":"كِتَابُ الدِّيَاتِ · ١٦","segs":[["matn","وَإِنْ قَتَلَ مُسْلِمٌ كَافِرًا عَمْدًا أُضْعِفَتْ دِيَتُهُ وَدِيَةُ الرَّقِيقِ: قِيمَتُهُ قَلَّتْ أَوْ كَثُرَتْ."]]},{"id":"da123_17","label":"كِتَابُ الدِّيَاتِ · ١٧","segs":[["matn","فَصْلٌ: وَمَنْ جَنَى عَلَى حَامِلٍ فَأَلْقَتْ جَنِينًا حُرًّا مُسْلِمًا ذَكَرًا كَانَ أَوْ أُنْثَى فَدِيَتُهُ: غُرَّةٌ قِيمَتُهَا: عُشْرُ دِيَةِ أُمِّهِ وَهِيَ: خَمْسٌ مِنَ الْإِبِلِ."]]},{"id":"da123_18","label":"كِتَابُ الدِّيَاتِ · ١٨","segs":[["matn","وَالْغُرَّةُ: هِيَ عَبْدٌ أَوْ أَمَةٌ وَتَتَعَدَّدُ الْغُرَّةُ بِتَعَدُّدِ الْجَنِينِ. وَدِيَةُ الْجَنِينِ الرَّقِيقِ: عُشْرُ قِيمَةِ أُمِّهِ. وَدِيَةُ الْجَنِينِ الْمَحْكُومِ بِكُفْرِهِ: غُرَّةٌ قِيمَتُهَا: عُشْرُ دِيَةِ أُمِّهِ."]]},{"id":"da123_19","label":"كِتَابُ الدِّيَاتِ · ١٩","segs":[["matn","وَإِنْ أَلْقَتِ الْجَنِينَ حَيًّا لِوَقْتٍ يَعِيشُ لِمِثْلِهِ وَهُوَ: نِصْفُ سَنَةٍ فَصَاعِدًا فَفِيهِ مَا فِي الْحَيِّ فَإِنْ كَانَ حُرًّا فَفِيهِ دِيَةٌ كَامِلَةٌ وَإِنْ كَانَ رَقِيقًا فَقِيمَتُهُ وَإِنِ اخْتَلَفَا فِي خُرُوجِهِ حَيًّا أَوْ مَيِّتًا فَقَوْلُ الْجَانِي."]]},{"id":"da123_20","label":"كِتَابُ الدِّيَاتِ · ٢٠","segs":[["matn","وَيَجِبُ فِي جَنِينِ الدَّابَّةِ: مَا نَقَصَ مِنْ قِيمَةِ أُمِّهِ."]]},{"id":"da123_21","label":"كِتَابُ الدِّيَاتِ · ٢١","segs":[["matn","فَصْلٌ فِي دِيَةِ الْأَعْضَاءِ: مَنْ أَتْلَفَ مَا فِي الْإِنْسَانِ مِنْهُ وَاحِدٌ: كَالْأَنْفِ وَاللِّسَانِ وَالذَّكَرِ فَفِيهِ دِيَةٌ كَامِلَةٌ."]]},{"id":"da123_22","label":"كِتَابُ الدِّيَاتِ · ٢٢","segs":[["matn","وَمَنْ أَتْلَفَ مَا فِي الْإِنْسَانِ مِنْهُ شَيْئَانِ كَالْيَدَيْنِ وَالرِّجْلَيْنِ وَالْعَيْنَيْنِ وَالْأُذُنَيْنِ وَالْحَاجِبَيْنِ وَالثَّدْيَيْنِ وَالْخُصْيَتَيْنِ فَفِيهِ الدِّيَةُ وَفِي أَحَدِهِمَا: نِصْفُهَا."]]},{"id":"da123_23","label":"كِتَابُ الدِّيَاتِ · ٢٣","segs":[["matn","وَفِي الْأَجْفَانِ الْأَرْبَعَةِ: الدِّيَةُ وَفِي أَحَدِهَا: رُبُعُهَا وَفِي أَصَابِعِ الْيَدَيْنِ: الدِّيَةُ وَفِي أَحَدِهَا عُشْرُهَا وَفِي الْأَنْمُلَةِ إِنْ كَانَتْ مِنْ إِبْهَامٍ نِصْفُ عُشْرِ الدِّيَةِ وَإِنْ كَانَتْ مِنْ غَيْرِهِ:"]]},{"id":"da123_24","label":"كِتَابُ الدِّيَاتِ · ٢٤","segs":[["matn","فَثُلُثُ عُشْرِهَا وَكَذَا أَصَابِعِ الرِّجْلَيْنِ وَفِي السِّنِّ: خَمْسٌ مِنَ الْإِبِلِ وَفِي إِذْهَابِ نَفْعِ عُضْوٍ مِنَ الْأَعْضَاءِ: دِيَةٌ كَامِلَةٌ."]]},{"id":"da123_25","label":"كِتَابُ الدِّيَاتِ · ٢٥","segs":[["matn","فَصْلٌ فِي دِيَةِ الْمَنَافِعِ: تَجِبُ الدِّيَةُ كَامِلَةً فِي إِذْهَابِ كُلٍّ مِنْ سَمْعٍ وَبَصَرٍ وَشَمٍّ وَذَوْقٍ وَكَلَامٍ وَعَقْلٍ وَحَدَبٍ وَمَنْفَعَةِ مَشْيٍ وَنِكَاحٍ وَأَكْلٍ وَصَوْتٍ وَبَطْشٍ."]]},{"id":"da123_26","label":"كِتَابُ الدِّيَاتِ · ٢٦","segs":[["matn","وَإِنْ أَفْزَعَ إِنْسَانًا أَوْ ضَرَبَهُ فَأَحْدَثَ بِغَائِطٍ أَوْ بَوْلٍ أَوْ رِيحٍ: وَلَمْ يَدُمْ فَعَلَيْهِ ثُلُثُ الدِّيَةِ وَإِنْ دَامَ فَعَلَيْهِ الدِّيَةُ."]]},{"id":"da123_27","label":"كِتَابُ الدِّيَاتِ · ٢٧","segs":[["matn","وَإِنْ جَنَى عَلَيْهِ فَأَذْهَبَ سَمْعَهُ وَبَصَرَهُ وَعَقْلَهُ وَشَمَّهُ وَذَوْقَهُ وَكَلَامَهُ وَنِكَاحَهُ فَعَلَيْهِ سَبْعُ دِيَاتٍ وَأَرْشُ تِلْكَ الْجِنَايَةِ وَإِنْ مَاتَ مِنَ الْجِنَايَةِ فَعَلَيْهِ دِيَةٌ وَاحِدَةٌ."]]},{"id":"da123_28","label":"كِتَابُ الدِّيَاتِ · ٢٨","segs":[["matn","فَصْلٌ: دِيَةُ الشَّجَّةِ وَالْجَائِفَةِ الشَّجَّةُ: اسْمٌ لِجُرْحِ الرَّأْسِ وَالْوَجْهِ."]]},{"id":"da123_29","label":"كِتَابُ الدِّيَاتِ · ٢٩","segs":[["matn","وَهِيَ خَمْسَةٌ: أَحَدُهَا: الْمُوضِحَةُ الَّتِي تُوضِحُ الْعَظْمَ وَتُبْرِزُهُ وَفِيهَا: نِصْفُ عُشْرِ الدِّيَةِ: خَمْسَةُ أَبْعِرَةٍ فَإِنْ كَانَ بَعْضُهَا فِي الرَّأْسِ وَبَعْضُهَا فِي الْوَجْهِ: فَمُوضِحَتَانِ."]]},{"id":"da123_30","label":"كِتَابُ الدِّيَاتِ · ٣٠","segs":[["matn","الثَّانِي: الْهَاشِمَةُ: الَّتِي تُوضِحُ الْعَظْمَ وَتَهْشِمُهُ وَفِيهَا: عَشَرَةُ أَبْعِرَةٍ. الثَّالِثُ: الْمُنَقِّلَةُ: الَّتِي تُوضِحُ وَتَهْشِمُ وَتَنْقُلُ الْعَظْمَ وَفِيهَا: خَمْسَةَ عَشَرَ بَعِيرًا. الرَّابِعُ: الْمَأْمُومَةُ الَّتِي تَصِلُ إِلَى جِلْدَةِ الدِّمَاغِ وَفِيهَا: ثُلُثُ الدِّيَةِ."]]},{"id":"da123_31","label":"كِتَابُ الدِّيَاتِ · ٣١","segs":[["matn","الْخَامِسُ: الدَّامِغَةُ: الَّتِي تَخْرِقُ الْجِلْدَةَ وَفِيهَا الثُّلُثُ أَيْضًا"]]},{"id":"da123_32","label":"كِتَابُ الدِّيَاتِ · ٣٢","segs":[["matn","فَصْلٌ: وَفِي الْجَائِفَةِ: ثُلُثُ الدِّيَةِ وَهِيَ: كُلُّ مَا يَصِلُ إِلَى الْجَوْفِ: كَبَطْنٍ وَظَهْرٍ وَصَدْرٍ وَحَلْقٍ. وَإِنْ جَرَحَ جَانِبًا فَخَرَجَ مِنَ الْآخَرِ: فَجَائِفَتَانِ."]]},{"id":"da123_33","label":"كِتَابُ الدِّيَاتِ · ٣٣","segs":[["matn","وَمَنْ وَطِئَ زَوْجَةً صَغِيرَةً لَا يُوطَأُ مِثْلُهَا فَخَرَقَ مَا بَيْنَ مَخْرَجِ بَوْلٍ وَمَنِيٍّ أَوْ مَا بَيْنَ السَّبِيلَيْنِ فَعَلَيْهِ الدِّيَةُ إِنْ لَمْ يَسْتَمْسِكِ الْبَوْلُ وَإِلَّا فَجَائِفَةٌ."]]},{"id":"da123_34","label":"كِتَابُ الدِّيَاتِ · ٣٤","segs":[["matn","وَإِنْ كَانَتْ مِمَّنْ يُوطَأُ مِثْلُهَا لِمِثْلِهِ أَوْ أَجْنَبِيَّةً كَبِيرَةً مُطَاوِعَةً وَلَا شُبْهَةَ فَوَقَعَ ذَلِكَ فَهَدْرٌ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"da124","title":"بَابُ الْعَاقِلَةِ","units":[{"id":"da124_1","label":"بَابُ الْعَاقِلَةِ · ١","segs":[["matn","وَهِيَ: ذُكُورُ عَصَبَةِ الْجَانِي نَسَبًا وَوَلَاءً. وَلَا تَحْمِلُ الْعَاقِلَةُ عَمْدًا وَلَا عَبْدًا وَلَا إِقْرَارًا وَلَا مَا دُونَ ثُلُثِ دِيَةِ ذَكَرٍ مُسْلِمٍ وَلَا قِيمَةَ مُتْلَفٍ."]]},{"id":"da124_2","label":"بَابُ الْعَاقِلَةِ · ٢","segs":[["matn","وَتَحْمِلُ الْخَطَأَ وَشِبْهَ الْعَمْدِ مُؤَجَّلًا فِي ثَلَاثِ سِنِينَ وَابْتِدَاءُ حَوْلِ الْقَتْلِ مِنَ الزُّهُوقِ وَالْجُرْحِ مِنَ الْبُرْءِ وَيُبْدَأُ بِالْأَقْرَبِ فَالْأَقْرَبِ كَالْإِرْثِ."]]},{"id":"da124_3","label":"بَابُ الْعَاقِلَةِ · ٣","segs":[["matn","وَلَا يُعْتَبَرُ أَنْ يَكُونُوا وَارِثِينَ لِمَنْ يَعْقِلُونَ عَنْهُ بَلْ مَتَى كَانُوا يَرِثُونَ لَوْلَا الْحَجْبُ عَقَلُوا. وَلَا عَقْلَ عَلَى فَقِيرٍ وَصَبِيٍّ وَمَجْنُونٍ وَامْرَأَةٍ وَلَوْ مُعْتِقَةً."]]},{"id":"da124_4","label":"بَابُ الْعَاقِلَةِ · ٤","segs":[["matn","وَمَنْ لَا عَاقِلَةَ لَهُ أَوْ لَهُ وَعَجَزَتْ فَلَا دِيَةَ عَلَيْهِ وَتَكُونُ فِي بَيْتِ الْمَالِ كَدِيَةِ مَنْ مَاتَ فِي زَحْمَةٍ: كَجُمُعَةٍ وَطَوَافٍ فَإِنْ تَعَذَّرَ الْأَخْذُ مِنْهُ سَقَطَتْ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"da125","title":"بَابُ كَفَّارَةِ الْقَتْلِ","units":[{"id":"da125_1","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ١","segs":[["matn","لَا كَفَّارَةَ فِي الْعَمْدِ. وَتَجِبُ فِيمَا دُونَهُ فِي مَالِ الْقَاتِلِ لِنَفْسٍ مُحَرَّمَةٍ وَلَوْ جَنِينًا."]]},{"id":"da125_2","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ٢","segs":[["matn","وَيُكَفِّرُ الرَّقِيقُ بِالصَّوْمِ وَالْكَافِرُ بِالْعِتْقِ وَغَيْرُهُمَا يُكَفِّرُ بِعِتْقِ رَقَبَةٍ مُؤْمِنَةٍ فَإِنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ وَلَا إِطْعَامَ هُنَا. وَتَتَعَدَّدُ الْكَفَّارَةُ بِتَعَدُّدِ الْمَقْتُولِ."]]},{"id":"da125_3","label":"بَابُ كَفَّارَةِ الْقَتْلِ · ٣","segs":[["matn","وَلَا كَفَّارَةَ عَلَى مَنْ قَتَلَ مَنْ يُبَاحُ قَتْلُهُ: كَزَانٍ مُحْصَنٍ وَمُرْتَدٍّ وَحَرْبِيٍّ وَبَاغٍ وَقِصَاصٍ وَدَفْعًا عَنْ نَفْسِهِ."]]}],"group":"كِتَابُ الدِّيَاتِ"},{"id":"da126","title":"كِتَابُ الْحُدُودِ","units":[{"id":"da126_1","label":"كِتَابُ الْحُدُودِ · ١","segs":[["matn","لَا حَدَّ إِلَّا عَلَى مُكَلَّفٍ مُلْتَزِمٍ عَالِمٍ بِالتَّحْرِيمِ. وَتَحْرُمُ الشَّفَاعَةُ وَقَبُولُهَا فِي حَدِّ اللَّهِ تَعَالَى بَعْدَ أَنْ يَبْلُغَ الْإِمَامَ وَتَجِبُ إِقَامَةُ الْحَدِّ وَلَوْ كَانَ مَنْ يُقِيمُهُ شَرِيكًا فِي الْمَعْصِيَةِ."]]},{"id":"da126_2","label":"كِتَابُ الْحُدُودِ · ٢","segs":[["matn","وَلَا يُقِيمُهُ إِلَّا الْإِمَامُ أَوْ نَائِبُهُ وَالسَّيِّدُ عَلَى رَقِيقِهِ. وَتَحْرُمُ إِقَامَتُهُ فِي الْمَسْجِدِ. وَأَشَدُّهُ: جَلْدُ الزِّنَا فَالْقَذْفِ فَالشُّرْبِ فَالتَّعْزِيرِ. وَيُضْرَبُ الرَّجُلُ قَائِمًا بِالسَّوْطِ. وَيَجِبُ اتِّقَاءُ الْوَجْهِ وَالرَّأْسِ وَالْفَرْجِ وَالْمَقْتَلِ."]]},{"id":"da126_3","label":"كِتَابُ الْحُدُودِ · ٣","segs":[["matn","وَتُضْرَبُ الْمَرْأَةُ جَالِسَةً وَتُشَدُّ عَلَيْهَا ثِيَابُهَا وَتُمْسَكُ يَدَاهَا. وَيَحْرُمُ بَعْدَ الْحَدِّ حَبْسٌ وَإِيذَاءٌ بِكَلَامٍ وَالْحَدُّ كَفَّارَةٌ لِذَلِكَ الذَّنْبِ. وَمَنْ أَتَى حَدًّا سَتَرَ نَفْسَهُ وَلَمْ يُسَنَّ أَنْ يُقِرَّ بِهِ عِنْدَ الْحَاكِمِ."]]},{"id":"da126_4","label":"كِتَابُ الْحُدُودِ · ٤","segs":[["matn","وَإِنِ اجْتَمَعَتْ حُدُودٌ لِلَّهِ تَعَالَى مِنْ جِنْسٍ تَدَاخَلَتْ وَمِنْ أَجْنَاسٍ: فَلَا."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"da127","title":"بَابُ حَدِّ الزِّنَا","units":[{"id":"da127_1","label":"بَابُ حَدِّ الزِّنَا · ١","segs":[["matn","الزِّنَا: هُوَ فِعْلُ الْفَاحِشَةِ فِي قُبُلٍ أَوْ دُبُرٍ. فَإِذَا زَنَا الْمُحْصَنُ وَجَبَ رَجْمُهُ حَتَّى يَمُوتَ وَالْمُحْصَنُ هُوَ مَنْ وَطِئَ زَوْجَتَهُ فِي قُبُلِهَا بِنِكَاحٍ صَحِيحٍ وَهُمَا حُرَّانِ مُكَلَّفَانِ."]]},{"id":"da127_2","label":"بَابُ حَدِّ الزِّنَا · ٢","segs":[["matn","وَإِنْ زَنَا الْحُرُّ غَيْرُ الْمُحْصَنِ جُلِدَ مِائَةَ جَلْدَةٍ وَغُرِّبَ عَامًا إِلَى مَسَافَةِ قَصْرٍ. وَإِنْ زَنَى الرَّقِيقُ: جُلِدَ خَمْسِينَ وَلَا يُغَرَّبُ. وَإِنْ زَنَى الذِّمِّيُّ بِمُسْلِمَةٍ: قُتِلَ."]]},{"id":"da127_3","label":"بَابُ حَدِّ الزِّنَا · ٣","segs":[["matn","وَإِنْ زَنَى الْحَرْبِيُّ: فَلَا شَيْءَ عَلَيْهِ. وَإِنْ زَنَى الْمُحْصَنُ بِغَيْرِ الْمُحْصَنِ فَلِكُلٍّ حَدُّهُ. وَمَنْ زَنَى بِبَهِيمَةٍ عُزِّرَ."]]},{"id":"da127_4","label":"بَابُ حَدِّ الزِّنَا · ٤","segs":[["matn","وَشَرْطُ وُجُوبِ الْحَدِّ ثَلَاثَةٌ: أَحَدُهَا: تَغْيِيبُ الْحَشَفَةِ أَوْ قَدْرِهَا فِي فَرْجٍ أَوْ دُبُرٍ لِآدَمِيٍّ حَيٍّ. الثَّانِي: انْتِفَاءُ الشُّبْهَةِ."]]},{"id":"da127_5","label":"بَابُ حَدِّ الزِّنَا · ٥","segs":[["matn","الثَّالِثُ: ثُبُوتُهُ إِمَّا بِإِقْرَارٍ أَرْبَعَ مَرَّاتٍ وَيَسْتَمِرُّ عَلَى إِقْرَارِهِ أَوْ بِشَهَادَةِ أَرْبَعَةِ رِجَالٍ عُدُولٍ. فَإِنْ كَانَ أَحَدُهُمْ غَيْرَ عَدْلٍ حُدُّوا لِلْقَذْفِ."]]},{"id":"da127_6","label":"بَابُ حَدِّ الزِّنَا · ٦","segs":[["matn","وَإِنْ شَهِدَ أَرْبَعَةٌ بِزِنَاهُ بِفُلَانَةَ فَشَهِدَ أَرْبَعَةٌ آخَرُونَ أَنَّ الشُّهُودَ هُمُ الزُّنَاةُ بِهَا صُدِّقُوا وَحُدَّ الْأَوَّلُونَ فَقَطْ لِلْقَذْفِ وَالزِّنَا. وَإِنْ حَمَلَتْ مَنْ لَا زَوْجَ لَهَا وَلَا سَيِّدَ: لَمْ يَلْزَمْهَا شَيْءٌ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"da128","title":"بَابُ حَدِّ الْقَذْفِ","units":[{"id":"da128_1","label":"بَابُ حَدِّ الْقَذْفِ · ١","segs":[["matn","مَنْ قَذَفَ غَيْرَهُ بِالزِّنَا حُدَّ لِلْقَذْفِ ثَمَانِينَ إِنْ كَانَ حُرًّا وَأَرْبَعِينَ إِنْ كَانَ رَقِيقًا."]]},{"id":"da128_2","label":"بَابُ حَدِّ الْقَذْفِ · ٢","segs":[["matn","وَإِنَّمَا يَجِبُ بِشُرُوطٍ تِسْعَةٍ: أَرْبَعَةٌ مِنْهَا فِي الْقَاذِفِ: وَهُوَ أَنْ يَكُونَ: بَالِغًا عَاقِلًا مُخْتَارًا لَيْسَ بِوَالِدٍ لِلْمَقْذُوفِ وَإِنْ عَلَا كَقَوَدٍ."]]},{"id":"da128_3","label":"بَابُ حَدِّ الْقَذْفِ · ٣","segs":[["matn","وَخَمْسَةٌ فِي الْمَقْذُوفِ: وَهُوَ كَوْنُهُ: حُرًّا مُسْلِمًا عَاقِلًا عَفِيفًا عَنِ الزِّنَا يَطَأُ وَيُوطَأُ مِثْلُهُ."]]},{"id":"da128_4","label":"بَابُ حَدِّ الْقَذْفِ · ٤","segs":[["matn","لَكِنْ لَا يُحَدُّ قَاذِفُ غَيْرِ الْبَالِغِ حَتَّى: يَبْلُغَ لِأَنَّ الْحَقَّ فِي حَدِّ الْقَذْفِ لِلْآدَمِيِّ فَلَا يُقَامُ بِلَا طَلَبِهِ. وَمَنْ قَذَفَ غَيْرَ مُحْصَنٍ عُزِّرَ."]]},{"id":"da128_5","label":"بَابُ حَدِّ الْقَذْفِ · ٥","segs":[["matn","وَيَثْبُتُ الْحَدُّ هُنَا وَفِي الشُّرْبِ وَالتَّعْزِيرِ بِأَحَدِ أَمْرَيْنِ إِمَّا بِإِقْرَارِهِ مَرَّةً أَوْ شَهَادَةِ عَدْلَيْنِ."]]},{"id":"da128_6","label":"بَابُ حَدِّ الْقَذْفِ · ٦","segs":[["matn","فَصْلٌ: وَيَسْقُطُ حَدُّ الْقَذْفِ بِأَرْبَعَةٍ بِعَفْوِ الْمَقْذُوفِ أَوْ بِتَصْدِيقِهِ أَوْ بِإِقَامَةِ الْبَيِّنَةِ أَوْ بِاللِّعَانِ. وَالْقَذْفُ: حَرَامٌ وَوَاجِبٌ وَمُبَاحٌ. فَيَحْرُمُ فِيمَا تَقَدَّمَ."]]},{"id":"da128_7","label":"بَابُ حَدِّ الْقَذْفِ · ٧","segs":[["matn","وَيَجِبُ عَلَى مَنْ يَرَى زَوْجَتَهُ تَزْنِي ثُمَّ تَلِدُ وَلَدًا يَقْوَى فِي ظَنِّهِ أَنَّهُ مِنَ الزَّانِي لِشَبَهِهِ بِهِ. وَيُبَاحُ إِذَا رَآهَا تَزْنِي وَلَمْ تَلِدْ مَا يَلْزَمُهُ نَفْيُهُ وَفِرَاقُهَا: أَوْلَى."]]},{"id":"da128_8","label":"بَابُ حَدِّ الْقَذْفِ · ٨","segs":[["matn","فَصْلٌ: وَصَرِيحُ الْقَذْفِ: يَا مَنْيُوكَةُ يَا مَنْيُوكُ يَا زَانِي يَا عَاهِرُ يَا لُوطِيُّ وَلَسْتَ وَلَدَ فُلَانٍ فَقَذْفٌ لِأُمِّهِ. وَكِنَايَتُهُ: زَنَتْ يَدَاكَ أَوْ رِجْلَاكَ أَوْ يَدُكَ أَوْ رِجْلُكَ أَوْ بَدَنُكَ."]]},{"id":"da128_9","label":"بَابُ حَدِّ الْقَذْفِ · ٩","segs":[["matn","يَا مُخَنَّثُ يَا قَحْبَةُ يَا فَاجِرَةُ يَا خَبِيثَةُ."]]},{"id":"da128_10","label":"بَابُ حَدِّ الْقَذْفِ · ١٠","segs":[["matn","أَوْ يَقُولُ لِزَوْجَةِ شَخْصٍ: فَضَحْتِ زَوْجَكِ وَغَطَّيْتِ رَأْسَهُ وَجَعَلْتِ لَهُ قُرُونًا وَعَلَّقْتِ عَلَيْهِ أَوْلَادًا مِنْ غَيْرِهِ وَأَفْسَدْتِ فِرَاشَهُ فَإِنْ أَرَادَ بِهَذِهِ الْأَلْفَاظِ حَقِيقَةَ الزِّنَا حُدَّ وَإِلَّا عُزِّرَ."]]},{"id":"da128_11","label":"بَابُ حَدِّ الْقَذْفِ · ١١","segs":[["matn","وَمَنْ قَذَفَ أَهْلَ بَلْدَةٍ أَوْ جَمَاعَةً لَا يُتَصَوَّرُ الزِّنَا مِنْهُمْ عَادَةً عُزِّرَ وَلَا حَدَّ وَإِنْ كَانَ يُتَصَوَّرُ الزِّنَا مِنْهُمْ عَادَةً وَقَذَفَ كُلَّ وَاحِدٍ بِكَلِمَةٍ: فَلِكُلِّ وَاحِدٍ حَدٌّ وَإِنْ كَانَ إِجْمَالًا فَحَدٌّ وَاحِدٌ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"da129","title":"بَابُ حَدِّ الْمُسْكِرِ","units":[{"id":"da129_1","label":"بَابُ حَدِّ الْمُسْكِرِ · ١","segs":[["matn","مَنْ شَرِبَ مُسْكِرًا مَائِعًا أَوِ اسْتَعَطَ بِهِ أَوِ احْتَقَنَ أَوْ أَكَلَ عَجِينًا مَلْتُوتًا بِهِ وَلَوْ لَمْ يُسْكِرْ: حُدَّ ثَمَانِينَ إِنْ كَانَ حُرًّا وَأَرْبَعِينَ إِنْ كَانَ رَقِيقًا."]]},{"id":"da129_2","label":"بَابُ حَدِّ الْمُسْكِرِ · ٢","segs":[["matn","بِشَرْطِ كَوْنِهِ مُسْلِمًا مُكَلَّفًا مُخْتَارًا عَالِمًا أَنَّ كَثِيرَهُ يُسْكِرُ. وَمَنْ تَشَبَّهَ بِشُرَّابِ الْخَمْرِ فِي مَجْلِسِهِ وَآنِيَتِهِ حَرُمَ وَعُزِّرَ. وَيَحْرُمُ: الْعَصِيرُ إِذَا أَتَى عَلَيْهِ ثَلَاثَةُ أَيَّامٍ وَلَمْ يُطْبَخْ."]]}],"group":"كِتَابُ الْحُدُودِ"},{"id":"da130","title":"كِتَابُ التَّعْزِيرِ","units":[{"id":"da130_1","label":"كِتَابُ التَّعْزِيرِ · ١","segs":[["matn","يَجِبُ فِي كُلِّ مَعْصِيَةٍ لَا حَدَّ فِيهَا وَلَا كَفَّارَةَ. وَهُوَ مِنْ حُقُوقِ اللَّهِ تَعَالَى لَا يُحْتَاجُ فِي إِقَامَتِهِ إِلَى مُطَالَبَةٍ إِلَّا إِذَا شَتَمَ الْوَلَدُ وَالِدَهُ فَلَا يُعَزَّرُ إِلَّا بِمُطَالَبَةِ وَالِدِهِ."]]},{"id":"da130_2","label":"كِتَابُ التَّعْزِيرِ · ٢","segs":[["matn","وَلَا يُعَزَّرُ: الْوَالِدُ بِحُقُوقِ وَلَدِهِ. وَلَا يُزَادُ فِي جَلْدِ التَّعْزِيرِ عَلَى عَشَرَةِ أَسْوَاطٍ إِلَّا إِذَا وَطِئَ أَمَةً لَهُ فِيهَا شِرْكٌ: فَيُعَزَّرُ بِمِائَةِ سَوْطٍ إِلَّا سَوْطًا وَإِذَا شَرِبَ مُسْكِرًا نَهَارَ رَمَضَانَ: فَيُعَزَّرُ بِعِشْرِينَ مَعَ الْحَدِّ."]]},{"id":"da130_3","label":"كِتَابُ التَّعْزِيرِ · ٣","segs":[["matn","وَلَا بَأْسَ: بِتَسْوِيدِ وَجْهِ مَنْ يَسْتَحِقُّ التَّعْزِيرَ وَالْمُنَادَاةِ عَلَيْهِ بِذَنْبِهِ. وَيَحْرُمُ حَلْقُ لِحْيَتِهِ وَأَخْذُ مَالِهِ."]]},{"id":"da130_4","label":"كِتَابُ التَّعْزِيرِ · ٤","segs":[["matn","فَصْلٌ: وَمِنَ الْأَلْفَاظِ الْمُوجِبَةِ لِلتَّعْزِيرِ قَوْلُهُ لِغَيْرِهِ: يَا كَافِرُ يَا فَاسِقُ يَا فَاجِرُ يَا شَقِيُّ يَا كَلْبُ يَا حِمَارُ يَا تَيْسُ يَا رَافِضِيُّ يَا خَبِيثُ يَا كَذَّابُ يَا خَائِنُ يَا قَرْنَانُ يَا قَوَّادُ يَا دَيُّوثُ يَا عِلْقُ."]]},{"id":"da130_5","label":"كِتَابُ التَّعْزِيرِ · ٥","segs":[["matn","وَيُعَزَّرُ مَنْ قَالَ لِذِمِّيٍّ: يَا حَاجُّ أَوْ لَعَنَهُ بِغَيْرِ مُوجِبٍ."]]}],"group":"كِتَابُ التَّعْزِيرِ"},{"id":"da131","title":"بَابُ الْقَطْعِ فِي السَّرِقَةِ","units":[{"id":"da131_1","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١","segs":[["matn","وَيَجِبُ بِثَمَانِيَةِ شُرُوطٍ: أَحَدُهَا: السَّرِقَةُ وَهِيَ: أَخْذُ مَالِ الْغَيْرِ مِنْ مَالِكِهِ أَوْ نَائِبِهِ عَلَى وَجْهِ الِاخْتِفَاءِ. فَلَا قَطْعَ عَلَى: مُنْتَهِبٍ وَمُخْتَطِفٍ وَخَائِنٍ فِي وَدِيعَةٍ لَكِنْ يُقْطَعُ جَاحِدُ الْعَارِيَّةِ."]]},{"id":"da131_2","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٢","segs":[["matn","الثَّانِي: كَوْنُ السَّارِقِ مُكَلَّفًا مُخْتَارًا عَالِمًا بِأَنَّ مَا سَرَقَهُ يُسَاوِي نِصَابًا."]]},{"id":"da131_3","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٣","segs":[["matn","الثَّالِثُ: كَوْنُ الْمَسْرُوقِ مَالًا لَكِنْ لَا قَطْعَ بِسَرِقَةِ الْمَاءِ وَلَا بِإِنَاءٍ فِيهِ خَمْرٌ أَوْ مَاءٌ وَلَا بِسَرِقَةِ مُصْحَفٍ وَلَا بِمَا عَلَيْهِ مِنْ حُلِيٍّ وَلَا بِكُتُبِ بِدَعٍ وَتَصَاوِيرَ وَلَا بِآلَةِ لَهْوٍ وَلَا بِصَلِيبٍ أَوْ صَنَمٍ."]]},{"id":"da131_4","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٤","segs":[["matn","الرَّابِعُ: كَوْنُ الْمَسْرُوقِ نِصَابًا وَهُوَ: ثَلَاثَةُ دَرَاهِمَ أَوْ رُبُعُ دِينَارٍ أَوْ مَا يُسَاوِي أَحَدَهُمَا وَتُعْتَبَرُ الْقِيمَةُ حَالَ الْإِخْرَاجِ. الْخَامِسُ: إِخْرَاجُهُ مِنْ حِرْزٍ فَلَوْ سَرَقَ مِنْ غَيْرِ حِرْزٍ فَلَا قَطْعَ."]]},{"id":"da131_5","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٥","segs":[["matn","وَحِرْزُ كُلِّ مَالٍ: مَا حُفِظَ فِيهِ عَادَةً فَنَعْلٌ بِرِجْلٍ وَعِمَامَةٌ عَلَى رَأْسٍ: حِرْزٌ وَيَخْتَلِفُ الْحِرْزُ بِالْبُلْدَانِ وَبِالسَّلَاطِينِ."]]},{"id":"da131_6","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٦","segs":[["matn","وَلَوِ اشْتَرَكَ جَمَاعَةٌ فِي هَتْكِ الْحِرْزِ وَإِخْرَاجِ النِّصَابِ: قُطِعُوا جَمِيعًا وَإِنْ هَتَكَ الْحِرْزَ أَحَدُهُمَا وَدَخَلَ الْآخَرُ فَأَخْرَجَ الْمَالَ: فَلَا قَطْعَ عَلَيْهِمَا وَلَوْ تَوَاطَآ."]]},{"id":"da131_7","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٧","segs":[["matn","السَّادِسُ: انْتِفَاءُ الشُّبْهَةِ: فَلَا قَطْعَ بِسَرِقَتِهِ مِنْ مَالِ فُرُوعِهِ وَأُصُولِهِ وَزَوْجِهِ وَلَا بِسَرِقَتِهِ مِنْ مَالٍ لَهُ فِيهِ شِرْكٌ أَوْ لِأَحَدٍ مِمَّنْ ذُكِرَ."]]},{"id":"da131_8","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٨","segs":[["matn","السَّابِعُ: ثُبُوتُهَا إِمَّا بِشَهَادَةِ عَدْلَيْنِ وَيَصِفَانِهَا وَلَا تُسْمَعُ قَبْلَ الدَّعْوَى أَوْ بِإِقْرَارٍ مَرَّتَيْنِ وَلَا يَرْجِعُ حَتَّى يُقْطَعَ. الثَّامِنُ: مُطَالَبَةُ الْمَسْرُوقِ مِنْهُ بِمَالِهِ. وَلَا قَطْعَ عَامَ مَجَاعَةِ غَلَاءٍ."]]},{"id":"da131_9","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ٩","segs":[["matn","فَمَتَى تَوَفَّرَتِ الشُّرُوطُ قُطِعَتْ يَدُهُ الْيُمْنَى مِنْ مَفْصِلِ كَفِّهِ وَغُمِسَتْ وُجُوبًا فِي زَيْتٍ مَغْلِيٍّ وَسُنَّ تَعْلِيقُهَا فِي عُنُقِهِ ثَلَاثَةَ أَيَّامٍ إِنْ رَآهُ الْإِمَامُ."]]},{"id":"da131_10","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١٠","segs":[["matn","فَإِنْ عَادَ قُطِعَتْ رِجْلُهُ الْيُسْرَى مِنْ مَفْصِلِ كَعْبِهِ بِتَرْكِ عَقِبِهِ فَإِنْ عَادَ لَمْ تُقْطَعْ وَحُبِسَ حَتَّى يَمُوتَ أَوْ يَتُوبَ."]]},{"id":"da131_11","label":"بَابُ الْقَطْعِ فِي السَّرِقَةِ · ١١","segs":[["matn","وَيَجْتَمِعُ الْقَطْعُ وَالضَّمَانُ فَيَرُدُّ مَا أَخَذَهُ لِمَالِكِهِ وَيُعِيدُ مَا خَرَّبَ مِنَ الْحِرْزِ. وَعَلَيْهِ أُجْرَةُ الْقَاطِعِ وَثَمَنُ الزَّيْتِ."]]}],"group":"كِتَابُ التَّعْزِيرِ"},{"id":"da132","title":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ","units":[{"id":"da132_1","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ١","segs":[["matn","وَهُمْ: الْمُكَلَّفُونَ الْمُلْتَزِمُونَ الَّذِينَ يَخْرُجُونَ عَلَى النَّاسِ فَيَأْخُذُونَ أَمْوَالَهُمْ مُجَاهَرَةً وَيُعْتَبَرُ ثُبُوتُهُ بِبَيِّنَةٍ أَوْ إِقْرَارٍ مَرَّتَيْنِ وَالْحِرْزُ وَالنِّصَابُ وَلَهُمْ أَرْبَعَةُ أَحْكَامٍ. إِنْ قَتَلُوا وَلَمْ يَأْخُذُوا مَالًا: تَحَتَّمَ قَتْلُهُمْ جَمِيعًا."]]},{"id":"da132_2","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٢","segs":[["matn","وَإِنْ قَتَلُوا وَأَخَذُوا مَالًا: تَحَتَّمَ قَتْلُهُمْ وَصَلْبُهُمْ حَتَّى يَشْتَهِرُوا. وَإِنْ أَخَذُوا مَالًا وَلَمْ يَقْتُلُوا: قُطِعَتْ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلَافٍ حَتْمًا فِي آنٍ وَاحِدٍ."]]},{"id":"da132_3","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٣","segs":[["matn","وَإِنْ أَخَافُوا النَّاسَ وَلَمْ يَأْخُذُوا مَالًا: نُفُوا مِنَ الْأَرْضِ فَلَا يُتْرَكُونَ يَأْوُونَ إِلَى بَلَدٍ حَتَّى تَظْهَرَ تَوْبَتُهُمْ."]]},{"id":"da132_4","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٤","segs":[["matn","وَمَنْ تَابَ مِنْهُمْ قَبْلَ الْقُدْرَةِ عَلَيْهِ سَقَطَتْ عَنْهُ حُقُوقُ اللَّهِ تَعَالَى وَأُخِذَ بِحُقُوقِ الْآدَمِيِّينَ."]]},{"id":"da132_5","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٥","segs":[["matn","فَصْلٌ: وَمَنْ أُرِيدَ بِأَذًى فِي نَفْسِهِ أَوْ مَالِهِ أَوْ حَرِيمِهِ فَلَهُ دَفْعُهُ بِالْأَسْهَلِ فَالْأَسْهَلِ فَإِنْ لَمْ يَنْدَفِعْ إِلَّا بِالْقَتْلِ قَتَلَهُ وَلَا شَيْءَ عَلَيْهِ."]]},{"id":"da132_6","label":"بَابُ حَدِّ قُطَّاعِ الطَّرِيقِ · ٦","segs":[["matn","وَيَجِبُ أَنْ يَدْفَعَ عَنْ حَرِيمِهِ وَحَرِيمِ غَيْرِهِ وَكَذَا فِي غَيْرِ الْفِتْنَةِ عَنْ نَفْسِهِ وَنَفْسِ غَيْرِهِ وَمَالِهِ لَا مَالُ نَفْسِهِ. وَلَا يَلْزَمُهُ حِفْظُهُ عَنِ الضَّيَاعِ وَالْهَلَاكِ."]]}],"group":"كِتَابُ التَّعْزِيرِ"},{"id":"da133","title":"بَابُ قِتَالِ الْبُغَاةِ","units":[{"id":"da133_1","label":"بَابُ قِتَالِ الْبُغَاةِ · ١","segs":[["matn","وَهُمْ: الْخَارِجُونَ عَلَى الْإِمَامِ بِتَأْوِيلٍ سَائِغٍ وَلَهُمْ شَوْكَةٌ. فَإِنِ اخْتَلَّ شَرْطٌ مِنْ ذَلِكَ فَقُطَّاعُ طَرِيقٍ. وَنَصْبُ الْإِمَامِ فَرْضُ كِفَايَةٍ."]]},{"id":"da133_2","label":"بَابُ قِتَالِ الْبُغَاةِ · ٢","segs":[["matn","وَيُعْتَبَرُ كَوْنُهُ قُرَشِيًّا بَالِغًا عَاقِلًا سَمِيعًا بَصِيرًا نَاطِقًا حُرًّا ذَكَرًا عَدْلًا عَالِمًا ذَا بَصِيرَةٍ كَافِيًا ابْتِدَاءً وَدَوَامًا. وَلَا يَنْعَزِلُ بِفِسْقِهِ."]]},{"id":"da133_3","label":"بَابُ قِتَالِ الْبُغَاةِ · ٣","segs":[["matn","وَتَلْزَمُهُ مُرَاسَلَةُ الْبُغَاةِ وَإِزَالَةُ شُبَهِهِمْ وَمَا يَدَّعُونَهُ مِنَ الْمَظَالِمِ فَإِنْ رَجَعُوا وَإِلَّا لَزِمَهُ قِتَالُهُمْ وَيَجِبُ عَلَى رَعِيَّتِهِ مَعُونَتُهُ. وَإِذَا تَرَكَ الْبُغَاةُ الْقِتَالَ حَرُمَ قَتْلُهُمْ وَقَتْلُ مُدْبِرِهِمْ وَجَرِيحِهِمْ."]]},{"id":"da133_4","label":"بَابُ قِتَالِ الْبُغَاةِ · ٤","segs":[["matn","وَلَا يُغْنَمُ مَالُهُمْ وَلَا تُسْبَى ذَرَارِيُّهُمْ وَيَجِبُ رَدُّ ذَلِكَ إِلَيْهِمْ. وَلَا يَضْمَنُ الْبُغَاةُ مَا أَتْلَفُوهُ حَالَ الْحَرْبِ. وَهُمْ: فِي شَهَادَتِهِمْ وَإِمْضَاءِ حُكْمِ حَاكِمِهِمْ كَأَهْلِ الْعَدْلِ."]]}],"group":"كِتَابُ التَّعْزِيرِ"},{"id":"da134","title":"بَابُ حُكْمِ الْمُرْتَدِّ","units":[{"id":"da134_1","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ١","segs":[["matn","وَهُوَ: مَنْ كَفَرَ بَعْدَ إِسْلَامِهِ. وَيَحْصُلُ الْكُفْرُ بِأَحَدِ أَرْبَعَةِ أُمُورٍ: بِالْقَوْلِ: كَسَبِّ اللَّهِ تَعَالَى وَرَسُولِهِ أَوْ مَلَائِكَتِهِ أَوِ ادِّعَاءِ النُّبُوَّةِ أَوِ الشَّرِكَةِ لَهُ تَعَالَى."]]},{"id":"da134_2","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٢","segs":[["matn","وَبِالْفِعْلِ: كَالسُّجُودِ لِلصَّنَمِ وَنَحْوِهِ وَكَإِلْقَاءِ الْمُصْحَفِ فِي قَاذُورَةٍ."]]},{"id":"da134_3","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٣","segs":[["matn","وَبِالِاعْتِقَادِ كَاعْتِقَادِ الشَّرِيكِ لَهُ تَعَالَى أَوْ أَنَّ الزِّنَا أَوِ الْخَمْرَ حَلَالٌ أَوْ أَنَّ الْخُبْزَ حَرَامٌ وَنَحْوِ ذَلِكَ مِمَّا أُجْمِعَ عَلَيْهِ إِجْمَاعًا قَطْعِيًّا وَبِالشَّكِّ فِي شَيْءٍ مِنْ ذَلِكَ."]]},{"id":"da134_4","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٤","segs":[["matn","فَمَنِ ارْتَدَّ وَهُوَ مُكَلَّفٌ مُخْتَارٌ اسْتُتِيبَ ثَلَاثَةَ أَيَّامٍ: وُجُوبًا فَإِنْ تَابَ فَلَا شَيْءَ عَلَيْهِ وَلَا يَحْبَطُ عَمَلُهُ وَإِنْ أَصَرَّ قُتِلَ بِالسَّيْفِ وَلَا يَقْتُلُهُ إِلَّا الْإِمَامُ أَوْ نَائِبُهُ فَإِنْ قَتَلَهُ غَيْرُهُمَا بِلَا إِذْنٍ أَسَاءَ وَعُزِّرَ وَلَا ضَمَانَ وَلَوْ كَانَ قَبْلَ اسْتِتَابَتِهِ."]]},{"id":"da134_5","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٥","segs":[["matn","وَيَصِحُّ إِسْلَامُ الْمُمَيِّزِ وَرِدَّتُهُ لَكِنْ لَا يُقْتَلُ حَتَّى يُسْتَتَابَ بَعْدَ بُلُوغِهِ ثَلَاثَةَ أَيَّامٍ."]]},{"id":"da134_6","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٦","segs":[["matn","فَصْلٌ: وَتَوْبَةُ الْمُرْتَدِّ وَكُلِّ كَافِرٍ: إِتْيَانُهُ بِالشَّهَادَتَيْنِ مَعَ رُجُوعِهِ عَمَّا كَفَرَ بِهِ وَلَا يُغْنِي قَوْلُهُ: مُحَمَّدٌ رَسُولُ اللَّهِ عَنْ كَلِمَةِ التَّوْحِيدِ وَقَوْلُهُ:"]]},{"id":"da134_7","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٧","segs":[["matn","أَنَا مُسْلِمٌ تَوْبَةٌ وَإِنْ كَتَبَ كَافِرٌ الشَّهَادَتَيْنِ صَارَ مُسْلِمًا وَإِنْ قَالَ: أَسْلَمْتُ أَوْ: أَنَا مُسْلِمٌ أَوْ: أَنَا مُؤْمِنٌ: صَارَ مُسْلِمًا."]]},{"id":"da134_8","label":"بَابُ حُكْمِ الْمُرْتَدِّ · ٨","segs":[["matn","وَلَا يُقْبَلُ فِي الدُّنْيَا بِحَسَبِ الظَّاهِرِ تَوْبَةُ زِنْدِيقٍ وَهُوَ: الْمُنَافِقُ الَّذِي يُظْهِرُ الْإِسْلَامَ وَيُخْفِي الْكُفْرَ وَلَا مَنْ تَكَرَّرَتْ رِدَّتُهُ أَوْ سَبَّ اللَّهَ تَعَالَى أَوْ رَسُولَهُ أَوْ مَلَكًا لَهُ وَكَذَا مَنْ قَذَفَ نَبِيًّا أَوْ أُمَّهُ وَيُقْتَلُ حَتَّى وَلَوْ كَانَ كَافِرًا فَأَسْلَمَ."]]}],"group":"كِتَابُ التَّعْزِيرِ"},{"id":"da135","title":"كِتَابُ الْأَطْعِمَةِ","units":[{"id":"da135_1","label":"كِتَابُ الْأَطْعِمَةِ · ١","segs":[["matn","يُبَاحُ كُلُّ طَعَامٍ طَاهِرٍ لَا مَضَرَّةَ فِيهِ حَتَّى الْمِسْكُ وَنَحْوُهُ. وَيَحْرُمُ النَّجِسُ: كَالْمَيْتَةِ وَالدَّمِ وَلَحْمُ الْخِنْزِيرِ. وَكَذَا الْبَوْلُ وَالرَّوْثُ وَلَوْ طَاهِرَيْنِ."]]},{"id":"da135_2","label":"كِتَابُ الْأَطْعِمَةِ · ٢","segs":[["matn","وَيَحْرُمُ مِنْ حَيَوَانِ الْبَرِّ الْحُمُرُ الْأَهْلِيَّةُ وَمَا يَفْتَرِسُ بِنَابِهِ: كَأَسَدٍ وَنَمِرٍ وَذِئْبٍ وَفَهْدٍ وَكَلْبٍ وَقِرْدٍ وَدُبٌّ وَنِمْسٌ وَابْنُ آوَى وَابْنُ عِرْسٍ وَسِنَّوْرٌ وَلَوْ بَرِّيًّا وَثَعْلَبٌ وَسِنْجَابٌ وَسَمُّورٌ."]]},{"id":"da135_3","label":"كِتَابُ الْأَطْعِمَةِ · ٣","segs":[["matn","وَيَحْرُمُ مِنَ الطَّيْرِ مَا يَصِيدُ بِمِخْلَبِهِ كَعُقَابٍ وَبَازٍ وَصَقْرٍ وَبَاشِقٍ وَشَاهِينٍ وَحِدَأَةٍ وَبُومَةٍ."]]},{"id":"da135_4","label":"كِتَابُ الْأَطْعِمَةِ · ٤","segs":[["matn","وَمَا يَأْكُلُ الْجِيَفَ: كَنَسْرٍ وَرَخَمٍ وَقَاقٍ وَغُرَابٍ وَخُفَّاشٍ وَفَأْرٌ وَزُنْبُورٌ وَنَحْلٌ وَذُبَابٌ وَهُدْهُدٌ وَخُطَّافٌ وَقُنْفُذٌ وَنِيصٌ وَحَيَّةٌ وَحَشَرَاتٌ."]]},{"id":"da135_5","label":"كِتَابُ الْأَطْعِمَةِ · ٥","segs":[["matn","وَيُؤْكَلُ مَا تَوَلَّدَ مِنْ مَأْكُولٍ طَاهِرٍ: كَذُبَابِ الْبَاقِلَّا وَدُودِ الْخَلِّ وَالْجُبْنِ تَبَعًا لَا انْفِرَادًا."]]},{"id":"da135_6","label":"كِتَابُ الْأَطْعِمَةِ · ٦","segs":[["matn","فَصْلٌ: وَيُبَاحُ مَا عَدَا هَذَا: كَبَهِيمَةِ الْأَنْعَامِ وَالْخَيْلِ وَبَاقِي الْوَحْشِ: كَضَبُعٍ وَزَرَافَةٍ وَأَرْنَبٍ وَوَبْرٍ وَيَرْبُوعٍ وَبَقَرِ وَحْشٍ وَحُمُرِهِ وَضَبٍّ وَظِبَاءٍ وَبَاقِي الطَّيْرِ: كَنَعَامٍ وَدَجَاجٍ وَطَاوُوسٍ وَبَبَّغَاءَ وَزَاغٍ وَغُرَابِ زَرْعٍ."]]},{"id":"da135_7","label":"كِتَابُ الْأَطْعِمَةِ · ٧","segs":[["matn","وَيَحِلُّ كُلُّ مَا فِي الْبَحْرِ غَيْرَ ضِفْدَعٍ وَحَيَّةٍ وَتِمْسَاحٍ. وَتَحْرُمُ الْجَلَّالَةُ: وَهِيَ الَّتِي أَكْثَرُ عَلَفِهَا النَّجَاسَةُ وَلَبَنُهَا وَبَيْضُهَا حَتَّى تُحْبَسَ ثَلَاثًا وَتُطْعَمَ الطَّاهِرَ."]]},{"id":"da135_8","label":"كِتَابُ الْأَطْعِمَةِ · ٨","segs":[["matn","وَيُكْرَهُ أَكْلُ تُرَابٍ وَفَحْمٍ وَطِينٍ وَأُذُنِ قَلْبٍ وَبَصَلٍ وَثُومٍ وَنَحْوِهِمَا مَا لَمْ يُنْضَجْ بِطَبْخٍ."]]},{"id":"da135_9","label":"كِتَابُ الْأَطْعِمَةِ · ٩","segs":[["matn","فَصْلٌ: وَمَنِ اضْطُرَّ جَازَ لَهُ أَنْ يَأْكُلَ مِنَ الْمُحَرَّمِ مَا يَسُدُّ رَمَقَهُ فَقَطْ وَمَنْ لَمْ يَجِدْ إِلَّا آدَمِيًّا مُبَاحَ الدَّمِ: كَحَرْبِيٍّ وَزَانٍ مُحْصَنٍ: فَلَهُ قَتْلُهُ وَأَكْلُهُ."]]},{"id":"da135_10","label":"كِتَابُ الْأَطْعِمَةِ · ١٠","segs":[["matn","وَمَنِ اضْطُرَّ إِلَى نَفْعِ مَالِ الْغَيْرِ مَعَ بَقَاءِ عَيْنِهِ وَجَبَ عَلَى رَبِّهِ بَذْلُهُ مَجَّانًا."]]},{"id":"da135_11","label":"كِتَابُ الْأَطْعِمَةِ · ١١","segs":[["matn","وَمَنْ مَرَّ بِثَمَرَةِ بُسْتَانٍ لَا حَائِطَ عَلَيْهِ وَلَا نَاظِرَ: فَلَهُ مِنْ غَيْرِ أَنْ يَصْعَدَ عَلَى شَجَرَةٍ أَوْ يَرْمِيَهُ بِحَجَرٍ أَنْ يَأْكُلَ وَلَا يَحْمِلُ. وَكَذَلِكَ الْبَاقِلَّا وَالْحِمِّصُ."]]},{"id":"da135_12","label":"كِتَابُ الْأَطْعِمَةِ · ١٢","segs":[["matn","وَتَجِبُ ضِيَافَةُ الْمُسْلِمِ عَلَى الْمُسْلِمِ فِي الْقُرَى دُونَ الْأَمْصَارِ يَوْمًا وَلَيْلَةً وَيُسْتَحَبُّ ثَلَاثًا."]]}],"group":"كِتَابُ الْأَطْعِمَةِ"},{"id":"da136","title":"بَابُ الذَّكَاةِ","units":[{"id":"da136_1","label":"بَابُ الذَّكَاةِ · ١","segs":[["matn","وَهِيَ: ذَبْحُ أَوْ نَحْرُ الْحَيَوَانِ الْمَقْدُورِ عَلَيْهِ. وَشُرُوطُهَا أَرْبَعَةٌ: أَحَدُهَا: كَوْنُ الْفَاعِلِ عَاقِلًا مُمَيِّزًا قَاصِدًا لِلذَّكَاةِ. فَيَحِلُّ: ذَبْحُ الْأُنْثَى وَالْقِنِّ وَالْجُنُبِ وَالْكِتَابِيِّ لَا: الْمُرْتَدِّ وَالْمَجُوسِيِّ وَالْوَثَنِيِّ وَالدُّرْزِيِّ وَالنُّصَيْرِيِّ."]]},{"id":"da136_2","label":"بَابُ الذَّكَاةِ · ٢","segs":[["matn","الثَّانِي: الْآلَةُ فَيَحِلُّ الذَّبْحُ بِكُلِّ مُحَدَّدٍ مِنْ حَجَرٍ وَقَصَبٍ وَخَشَبٍ وَعَظْمٍ غَيْرَ السِّنِّ وَالظُّفُرِ. الثَّالِثُ: قَطْعُ الْحُلْقُومِ وَالْمَرِيءِ وَيَكْفِي قَطْعُ الْبَعْضِ مِنْهُمَا فَلَوْ قَطَعَ رَأْسَهُ حَلَّ."]]},{"id":"da136_3","label":"بَابُ الذَّكَاةِ · ٣","segs":[["matn","وَيَحِلُّ ذَبْحُ مَا أَصَابَهُ سَبَبُ الْمَوْتِ: مِنْ مُنْخَنِقَةٍ وَمَرِيضَةٍ وَأَكِيلَةِ سَبُعٍ وَمَا صِيدَ بِشَبَكَةٍ أَوْ فَخٍّ أَوْ أَنْقَذَهُ مِنْ مَهْلَكَةٍ إِنْ ذَكَّاهُ وَفِيهِ حَيَاةٌ مُسْتَقِرَّةٌ: كَتَحْرِيكِ يَدِهِ أَوْ رِجْلِهِ أَوْ طَرْفِ عَيْنِهِ."]]},{"id":"da136_4","label":"بَابُ الذَّكَاةِ · ٤","segs":[["matn","وَمَا قُطِعَ حُلْقُومُهُ أَوْ أُبِينَتْ حَشْوَتُهُ فَوُجُودُ حَيَاتِهِ كَعَدَمِهَا لَكِنْ لَوْ قَطَعَ الذَّابِحُ الْحُلْقُومَ ثُمَّ رَفَعَ يَدَهُ قَبْلَ قَطْعِ الْمَرِيءِ:"]]},{"id":"da136_5","label":"بَابُ الذَّكَاةِ · ٥","segs":[["matn","لَمْ يَضُرَّ إِنْ عَادَ فَتَمَّمَ الذَّكَاةَ عَلَى الْفَوْرِ وَمَا عُجِزَ عَنْ ذَبْحِهِ: كَوَاقِعٍ فِي بِئْرٍ أَوْ: مُتَوَحِّشٍ فَذَكَاتُهُ بِجَرْحِهِ فِي أَيِّ مَحَلٍّ كَانَ."]]},{"id":"da136_6","label":"بَابُ الذَّكَاةِ · ٦","segs":[["matn","الرَّابِعُ: قَوْلُ: بِسْمِ اللَّهِ لَا يُجْزِئُ غَيْرُهَا عِنْدَ حَرَكَةِ يَدِهِ بِالذَّبْحِ وَتُجْزِئُ بِغَيْرِ الْعَرَبِيَّةِ وَلَوْ أَحْسَنَهَا. وَيُسَنُّ التَّكْبِيرُ."]]},{"id":"da136_7","label":"بَابُ الذَّكَاةِ · ٧","segs":[["matn","وَتَسْقُطُ: التَّسْمِيَةُ سَهْوًا لَا جَهْلًا وَمَنْ ذَكَرَ مَعَ اسْمِ اللَّهِ تَعَالَى اسْمَ غَيْرِهِ لَمْ تَحِلَّ."]]},{"id":"da136_8","label":"بَابُ الذَّكَاةِ · ٨","segs":[["matn","فَصْلٌ: وَتَحْصُلُ ذَكَاةُ الْجَنِينِ بِذَكَاةِ أُمِّهِ وَإِنْ خَرَجَ حَيًّا حَيَاةً مُسْتَقِرَّةً لَمْ يُبَحْ إِلَّا بِذَبْحِهِ. وَيُكْرَهُ الذَّبْحُ بِآلَةٍ كَالَّةٍ وَسَلْخُ الْحَيَوَانِ أَوْ كَسْرُ عُنُقِهِ قَبْلَ زُهُوقِ نَفْسِهِ."]]},{"id":"da136_9","label":"بَابُ الذَّكَاةِ · ٩","segs":[["matn","وَسُنَّ: تَوْجِيهُهُ لِلْقِبْلَةِ عَلَى جَنْبِهِ الْأَيْسَرِ وَالْإِسْرَاعُ فِي الذَّبْحِ. وَمَا ذُبِحَ فَغَرِقَ أَوْ تَرَدَّى مِنْ عُلْوٍ أَوْ وَطِئَ عَلَيْهِ شَيْءٌ يَقْتُلُهُ مِثْلُهُ: لَمْ يَحِلَّ."]]}],"group":"كِتَابُ الْأَطْعِمَةِ"},{"id":"da137","title":"كِتَابُ الصَّيْدِ","units":[{"id":"da137_1","label":"كِتَابُ الصَّيْدِ · ١","segs":[["matn","يُبَاحُ: لِقَاصِدِهِ وَيُكْرَهُ: لَهْوًا. وَهُوَ أَفْضَلُ مَأْكُولٍ. فَمَنْ أَدْرَكَ صَيْدًا مَجْرُوحًا مُتَحَرِّكًا فَوْقَ حَرَكَةِ مَذْبُوحٍ وَاتَّسَعَ الْوَقْتُ لِتَذْكِيَتِهِ: لَمْ يُبَحْ إِلَّا بِهَا."]]},{"id":"da137_2","label":"كِتَابُ الصَّيْدِ · ٢","segs":[["matn","وَإِنْ لَمْ يَتَّسِعْ بَلْ مَاتَ فِي الْحَالِ: حَلَّ بِأَرْبَعَةِ شُرُوطٍ: أَحَدُهَا: كَوْنُ الصَّائِدِ أَهْلًا لِلذَّكَاةِ حَالَ إِرْسَالِ الْآلَةِ وَمَنْ رَمَى صَيْدًا فَأَثْبَتَهُ ثُمَّ رَمَاهُ ثَانِيًا فَقَتَلَهُ: لَمْ يَحِلَّ."]]},{"id":"da137_3","label":"كِتَابُ الصَّيْدِ · ٣","segs":[["matn","الثَّانِي: الْآلَةُ وَهِيَ نَوْعَانِ: مَا لَهُ حَدٌّ يَجْرَحُ بِهِ كَسَيْفٍ وَسِكِّينٍ وَسَهْمٍ. الثَّانِي: جَارِحَةٌ مُعَلَّمَةٌ: كَكَلْبٍ غَيْرِ أَسْوَدَ وَفَهْدٍ وَبَازٍ وَصَقْرٍ وَعُقَابٍ وَشَاهِينٍ."]]},{"id":"da137_4","label":"كِتَابُ الصَّيْدِ · ٤","segs":[["matn","فَتَعْلِيمُ الْكَلْبِ وَالْفَهْدِ بِثَلَاثَةِ أُمُورٍ: بِأَنْ يَسْتَرْسِلَ إِذَا أُرْسِلَ وَيَنْزَجِرَ إِذَا زُجِرَ وَإِذَا أَمْسَكَ لَمْ يَأْكُلْ. وَتَعْلِيمُ الطَّيْرِ بِأَمْرَيْنِ: بِأَنْ يَسْتَرْسِلَ إِذَا أُرْسِلَ وَيَرْجِعَ إِذَا دُعِيَ."]]},{"id":"da137_5","label":"كِتَابُ الصَّيْدِ · ٥","segs":[["matn","وَيُشْتَرَطُ: أَنْ يَجْرَحَ الصَّيْدَ فَلَوْ قَتَلَهُ بِصَدْمٍ أَوْ خَنْقٍ: لَمْ يُبَحْ."]]},{"id":"da137_6","label":"كِتَابُ الصَّيْدِ · ٦","segs":[["matn","الثَّالِثُ: قَصْدُ الْفِعْلِ وَهُوَ: أَنْ يُرْسِلَ الْآلَةَ لِقَصْدِ الصَّيْدِ فَلَوْ سَمَّى وَأَرْسَلَهَا لَا لِقَصْدِ الصَّيْدِ أَوْ لِقَصْدِهِ وَلَمْ يَرَهُ أَوِ اسْتَرْسَلَ الْجَارِحُ بِنَفْسِهِ فَقَتَلَ صَيْدًا لَمْ يَحِلَّ."]]},{"id":"da137_7","label":"كِتَابُ الصَّيْدِ · ٧","segs":[["matn","الرَّابِعُ: قَوْلُ: بِسْمِ اللَّهِ عِنْدَ إِرْسَالِ جَارِحِهِ أَوْ رَمْيِ سِلَاحِهِ وَلَا تَسْقُطُ هُنَا سَهْوًا."]]},{"id":"da137_8","label":"كِتَابُ الصَّيْدِ · ٨","segs":[["matn","وَمَا رُمِيَ مِنْ صَيْدٍ فَوَقَعَ فِي مَاءٍ أَوْ تَرَدَّى مِنْ عُلْوٍ أَوْ وَطِئَ عَلَيْهِ شَيْءٌ وَكُلٌّ مِنْ ذَلِكَ يَقْتُلُ مِثْلَهُ؛ لَمْ يَحِلَّ."]]},{"id":"da137_9","label":"كِتَابُ الصَّيْدِ · ٩","segs":[["matn","وَمِثْلُهُ: لَوْ رَمَاهُ بِمُحَدَّدٍ فِيهِ سُمٌّ وَإِنْ رَمَاهُ بِالْهَوَاءِ أَوْ عَلَى شَجَرَةٍ أَوْ حَائِطٍ فَسَقَطَ مَيِّتًا حَلَّ."]]}],"group":"كِتَابُ الصَّيْدِ"},{"id":"da138","title":"كِتَابُ الْأَيْمَانِ","units":[{"id":"da138_1","label":"كِتَابُ الْأَيْمَانِ · ١","segs":[["matn","لَا تَنْعَقِدُ الْيَمِينُ إِلَّا بِاللَّهِ تَعَالَى أَوِ اسْمٍ مِنْ أَسْمَائِهِ أَوْ صِفَةٍ مِنْ صِفَاتِهِ: كَعِزَّةِ اللَّهِ وَقُدْرَتِهِ وَأَمَانَتِهِ. وَإِنْ قَالَ: يَمِينًا بِاللَّهِ أَوْ قَسَمًا أَوْ شَهَادَةً انْعَقَدَتْ."]]},{"id":"da138_2","label":"كِتَابُ الْأَيْمَانِ · ٢","segs":[["matn","وَتَنْعَقِدُ بِالْقُرْآنِ وَبِالْمُصْحَفِ وَبِالتَّوْرَاةِ وَنَحْوِهَا مِنَ الْكُتُبِ الْمُنَزَّلَةِ. وَمَنْ حَلَفَ بِمَخْلُوقٍ: كَالْأَوْلِيَاءِ وَالْأَنْبِيَاءِ عَلَيْهِمُ السَّلَامُ أَوْ: بِالْكَعْبَةِ وَنَحْوِهَا: حَرُمَ وَلَا كَفَّارَةَ."]]},{"id":"da138_3","label":"كِتَابُ الْأَيْمَانِ · ٣","segs":[["matn","فَصْلٌ: وَشُرُوطُ وُجُوبِ الْكَفَّارَةِ خَمْسَةُ أَشْيَاءَ: أَحَدُهَا: كَوْنُ الْحَالِفِ مُكَلَّفًا. الثَّانِي: كَوْنُهُ مُخْتَارًا."]]},{"id":"da138_4","label":"كِتَابُ الْأَيْمَانِ · ٤","segs":[["matn","الثَّالِثُ: كَوْنُهُ قَاصِدًا لِلْيَمِينِ فَلَا تَنْعَقِدُ مِمَّنْ سَبَقَ عَلَى لِسَانِهِ بِلَا قَصْدٍ كَقَوْلِهِ: لَا وَاللَّهِ وَبَلَى وَاللَّهِ فِي عُرْضِ حَدِيثِهِ."]]},{"id":"da138_5","label":"كِتَابُ الْأَيْمَانِ · ٥","segs":[["matn","الرَّابِعُ: كَوْنُهَا عَلَى أَمْرٍ مُسْتَقْبَلٍ فَلَا كَفَّارَةَ عَلَى مَاضٍ بَلْ إِنْ تَعَمَّدَ الْكَذِبَ فَحَرَامٌ وَإِلَّا فَلَا شَيْءَ عَلَيْهِ."]]},{"id":"da138_6","label":"كِتَابُ الْأَيْمَانِ · ٦","segs":[["matn","الْخَامِسُ: الْحِنْثُ بِفِعْلِ مَا حَلَفَ عَلَى تَرْكِهِ أَوْ تَرْكِ مَا حَلَفَ عَلَى فِعْلِهِ فَإِنْ كَانَ عَيَّنَ وَقْتًا تَعَيَّنَ وَإِلَّا لَمْ يَحْنَثْ حَتَّى يَيْأَسَ مِنْ فِعْلِهِ بِتَلَفِ الْمَحْلُوفِ عَلَيْهِ أَوْ مَوْتِ الْحَالِفِ."]]},{"id":"da138_7","label":"كِتَابُ الْأَيْمَانِ · ٧","segs":[["matn","وَمَنْ حَلَفَ بِاللَّهِ لَا يَفْعَلُ كَذَا أَوْ لَيَفْعَلَنَّ كَذَا إِنْ شَاءَ اللَّهُ أَوْ أَرَادَ اللَّهُ أَوْ إِلَّا أَنْ يَشَاءَ اللَّهُ وَاتَّصَلَ لَفْظًا أَوْ حُكْمًا لَمْ يَحْنَثْ فَعَلَ أَوْ تَرَكَ بِشَرْطِ أَنْ يَقْصِدَ الِاسْتِثْنَاءَ قَبْلَ تَمَامِ الْمُسْتَثْنَى مِنْهُ."]]},{"id":"da138_8","label":"كِتَابُ الْأَيْمَانِ · ٨","segs":[["matn","فَصْلٌ: وَمَنْ قَالَ: طَعَامِي عَلَيَّ حَرَامٌ أَوْ: إِنْ أَكَلْتُ كَذَا فَحَرَامٌ أَوْ: إِنْ فَعَلْتُ كَذَا فَحَرَامٌ: لَمْ يَحْرُمْ وَعَلَيْهِ إِنْ فَعَلَ كَفَّارَةُ يَمِينٍ."]]},{"id":"da138_9","label":"كِتَابُ الْأَيْمَانِ · ٩","segs":[["matn","وَمَنْ قَالَ: هُوَ يَهُودِيٌّ أَوْ: نَصْرَانِيٌّ أَوْ يَعْبُدُ الصَّلِيبَ أَوِ الشَّرْقَ إِنْ فَعَلَ كَذَا أَوْ: هُوَ بَرِيءٌ مِنَ الْإِسْلَامِ أَوْ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ:"]]},{"id":"da138_10","label":"كِتَابُ الْأَيْمَانِ · ١٠","segs":[["matn","هُوَ كَافِرٌ بِاللَّهِ تَعَالَى إِنْ لَمْ يَفْعَلْ كَذَا: فَقَدِ ارْتَكَبَ مُحَرَّمًا وَعَلَيْهِ كَفَّارَةُ يَمِينٍ إِنْ فَعَلَ مَا نَفَاهُ أَوْ تَرَكَ مَا أَثْبَتَهُ."]]},{"id":"da138_11","label":"كِتَابُ الْأَيْمَانِ · ١١","segs":[["matn","وَمَنْ أَخْبَرَ عَنْ نَفْسِهِ بِأَنَّهُ حَلَفَ بِاللَّهِ وَلَمْ يَكُنْ حَلَفَ: فَكَذْبَةٌ لَا كَفَّارَةَ فِيهَا."]]},{"id":"da138_12","label":"كِتَابُ الْأَيْمَانِ · ١٢","segs":[["matn","فَصْلٌ: وَكَفَّارَةُ الْيَمِينِ عَلَى التَّخْيِيرِ: إِطْعَامُ عَشَرَةِ مَسَاكِينَ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ مُؤْمِنَةٍ فَإِنْ لَمْ يَجِدْ صَامَ ثَلَاثَةَ أَيَّامٍ مُتَتَابِعَةٍ وُجُوبًا إِنْ لَمْ يَكُنْ عُذْرٌ."]]},{"id":"da138_13","label":"كِتَابُ الْأَيْمَانِ · ١٣","segs":[["matn","وَلَا يَصِحُّ أَنْ يُكَفِّرَ الرَّقِيقُ بِغَيْرِ الصَّوْمِ وَعَكْسُهُ الْكَافِرُ. وَإِخْرَاجُ الْكَفَّارَةِ قَبْلَ الْحِنْثِ وَبَعْدَهُ سَوَاءٌ. وَمَنْ حَنِثَ وَلَوْ فِي أَلْفِ يَمِينٍ بِاللَّهِ تَعَالَى وَلَمْ يُكَفِّرْ: فَكَفَّارَةٌ وَاحِدَةٌ."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"da139","title":"بَابُ جَامِعِ الْأَيْمَانِ","units":[{"id":"da139_1","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١","segs":[["matn","يُرْجَعُ فِي الْأَيْمَانِ إِلَى نِيَّةِ الْحَالِفِ فَمَنْ دُعِيَ لِغَدَاءٍ فَحَلَفَ لَا يَتَغَدَّى: لَمْ يَحْنَثْ بِغَدَاءِ غَيْرِهِ إِنْ قَصَدَهُ."]]},{"id":"da139_2","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢","segs":[["matn","أَوْ حَلَفَ: لَا يَدْخُلُ دَارَ فُلَانٍ وَقَالَ: نَوَيْتُ الْيَوْمَ: قُبِلَ حُكْمًا فَلَا يَحْنَثُ بِالدُّخُولِ فِي غَيْرِهِ. وَلَا عُدْتُ رَأَيْتُكِ تَدْخُلِينَ دَارَ فُلَانٍ يَنْوِي مَنْعَهَا فَدَخَلَتْهَا: حَنِثَ وَلَوْ لَمْ يَرَهَا."]]},{"id":"da139_3","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٣","segs":[["matn","فَصْلٌ: فَإِنْ لَمْ يَنْوِ شَيْئًا رُجِعَ إِلَى سَبَبِ الْيَمِينِ وَمَا هَيَّجَهَا."]]},{"id":"da139_4","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٤","segs":[["matn","فَمَنْ حَلَفَ: لَيَقْضِيَنَّ زَيْدًا حَقَّهُ غَدًا فَقَضَاهُ قَبْلَهُ أَوْ: لَا يَبِيعُ كَذَا إِلَّا بِمِائَةٍ فَبَاعَهُ بِأَكْثَرَ أَوْ: لَا يَدْخُلُ بَلَدَ كَذَا لِظُلْمٍ فِيهَا فَزَالَ وَدَخَلَهَا أَوْ: لَا يُكَلِّمُ زَيْدًا لِشُرْبِهِ الْخَمْرَ فَكَلَّمَهُ وَقَدْ تَرَكَهُ: لَمْ يَحْنَثْ فِي الْجَمِيعِ."]]},{"id":"da139_5","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٥","segs":[["matn","فَصْلٌ: فَإِنْ عُدِمَ النِّيَّةُ وَالسَّبَبُ رُجِعَ إِلَى التَّعْيِينِ فَمَنْ حَلَفَ: لَا يَدْخُلُ دَارَ فُلَانٍ هَذِهِ فَدَخَلَهَا وَقَدْ بَاعَهَا أَوْ:"]]},{"id":"da139_6","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٦","segs":[["matn","وَهِيَ فَضَاءٌ أَوْ: لَا كَلَّمْتُ هَذَا الصَّبِيَّ فَصَارَ شَيْخًا وَكَلَّمَهُ أَوْ: لَا أَكَلْتُ هَذَا الرُّطَبَ فَصَارَ تَمْرًا ثُمَّ أَكَلَهُ: حَنِثَ فِي الْجَمِيعِ"]]},{"id":"da139_7","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٧","segs":[["matn","فَصْلٌ: فَإِنْ عُدِمَ النِّيَّةُ وَالسَّبَبُ وَالتَّعْيِينُ: رُجِعَ إِلَى مَا تَنَاوَلَهُ الِاسْمُ وَهُوَ ثَلَاثَةٌ: شَرْعِيٌّ فَعُرْفِيٌّ فَلُغَوِيٌّ. فَالْيَمِينُ الْمُطْلَقَةُ تَنْصَرِفُ إِلَى الشَّرْعِيِّ وَتَتَنَاوَلُ الصَّحِيحَ مِنْهُ."]]},{"id":"da139_8","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٨","segs":[["matn","فَمَنْ حَلَفَ: لَا يَنْكِحُ أَوْ لَا يَبِيعُ أَوْ لَا يَشْتَرِي فَعَقَدَ عَقْدًا فَاسِدًا: لَمْ يَحْنَثْ لَكِنْ لَوْ قَيَّدَ يَمِينَهُ بِمُمْتَنِعِ الصِّحَّةِ كَحَلِفِهِ: لَا يَبِيعُ الْخَمْرَ ثُمَّ بَاعَهُ: حَنِثَ بِصُورَةِ ذَلِكَ."]]},{"id":"da139_9","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٩","segs":[["matn","فَصْلٌ: فَإِنْ عُدِمَ الشَّرْعِيُّ فَالْأَيْمَانُ مَبْنَاهَا عَلَى الْعُرْفِ."]]},{"id":"da139_10","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٠","segs":[["matn","فَمَنْ حَلَفَ: لَا يَطَأُ امْرَأَتَهُ: حَنِثَ بِجِمَاعِهَا أَوْ: لَا يَطَأُ أَوْ لَا يَضَعُ قَدَمَهُ فِي دَارِ فُلَانٍ: حَنِثَ بِدُخُولِهَا رَاكِبًا أَوْ مَاشِيًا حَافِيًا أَوْ مُنْتَعِلًا."]]},{"id":"da139_11","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١١","segs":[["matn","أَوْ لَا يَدْخُلُ بَيْتًا: حَنِثَ بِدُخُولِ الْمَسْجِدِ وَالْحَمَّامِ وَبَيْتِ الشَّعَرِ. وَلَا يَضْرِبُ فُلَانَةَ فَخَنَقَهَا أَوْ نَتَفَ شَعَرَهَا أَوْ عَضَّهَا: حَنِثَ."]]},{"id":"da139_12","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٢","segs":[["matn","فَصْلٌ: فَإِنْ عُدِمَ الْعُرْفُ رُجِعَ إِلَى اللُّغَةِ. فَمَنْ حَلَفَ: لَا يَأْكُلُ لَحْمًا حَنِثَ بِكُلِّ لَحْمٍ حَتَّى بِالْمُحَرَّمِ: كَالْمَيْتَةِ وَالْخِنْزِيرِ لَا بِمَا لَا يُسَمَّى لَحْمًا كَالشَّحْمِ وَنَحْوِهِ."]]},{"id":"da139_13","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٣","segs":[["matn","وَلَا يَأْكُلُ لَبَنًا فَأَكَلَهُ وَلَوْ مِنْ لَبَنِ آدَمِيَّةٍ: حَنِثَ وَلَا يَأْكُلُ رَأْسًا وَلَا بَيْضًا: حَنِثَ بِكُلِّ رَأْسٍ وَبَيْضٍ حَتَّى بِرَأْسِ الْجَرَادِ وَبَيْضِهِ وَلَا يَأْكُلُ فَاكِهَةً: حَنِثَ."]]},{"id":"da139_14","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٤","segs":[["matn","بِكُلِّ مَا يُتَفَكَّهُ بِهِ حَتَّى بِالْبِطِّيخِ لَا الْقِثَّاءِ وَالْخِيَارِ وَالزَّيْتُونِ وَالزُّعْرُورِ الْأَحْمَرِ."]]},{"id":"da139_15","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٥","segs":[["matn","وَلَا يَتَغَدَّى فَأَكَلَ بَعْدَ الزَّوَالِ أَوْ لَا يَتَعَشَّى فَأَكَلَ بَعْدَ نِصْفِ اللَّيْلِ أَوْ لَا يَتَسَحَّرُ فَأَكَلَ قَبْلَهُ: لَمْ يَحْنَثْ."]]},{"id":"da139_16","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٦","segs":[["matn","وَلَا يَأْكُلُ مِنْ هَذِهِ الشَّجَرَةِ: حَنِثَ بِأَكْلِ ثَمَرَتِهَا فَقَطْ وَلَا يَأْكُلُ مِنْ هَذِهِ الْبَقَرَةِ: حَنِثَ بِأَكْلِ كُلِّ شَيْءٍ مِنْهَا لَا مِنْ لَبَنِهَا وَوَلَدِهَا."]]},{"id":"da139_17","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٧","segs":[["matn","وَلَا يَشْرَبُ مِنْ هَذَا النَّهْرِ أَوِ الْبِئْرِ فَاغْتَرَفَ بِإِنَاءٍ وَشَرِبَ حَنِثَ لَا إِنْ حَلَفَ: لَا يَشْرَبُ مِنْ هَذَا الْإِنَاءِ فَاغْتَرَفَ مِنْهُ وَشَرِبَ."]]},{"id":"da139_18","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٨","segs":[["matn","فَصْلٌ: وَمَنْ حَلَفَ: لَا يَدْخُلُ دَارَ فُلَانٍ أَوْ لَا يَرْكَبُ دَابَّتَهُ: حَنِثَ بِمَا جَعَلَهُ لِعَبْدِهِ أَوْ آجَرَهُ أَوِ اسْتَأْجَرَهُ لَا بِمَا اسْتَعَارَهُ."]]},{"id":"da139_19","label":"بَابُ جَامِعِ الْأَيْمَانِ · ١٩","segs":[["matn","وَلَا يُكَلِّمُ إِنْسَانًا: حَنِثَ بِكَلَامِ كُلِّ إِنْسَانٍ حَتَّى بِقَوْلِهِ: اسْكُتْ وَلَا كَلَّمْتُ فُلَانًا فَكَاتَبَهُ أَوْ رَاسَلَهُ: حَنِثَ وَلَا بَدَأْتُ فُلَانًا بِكَلَامٍ فَتَكَلَّمَا مَعًا: لَمْ يَحْنَثْ وَلَا مِلْكَ لَهُ:"]]},{"id":"da139_20","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢٠","segs":[["matn","لَمْ يَحْنَثْ بِدَيْنٍ وَلَا مَالَ لَهُ أَوْ لَا يَمْلِكُ مَالًا: حَنِثَ بِالدَّيْنِ وَلَيَضْرِبَنَّ فُلَانًا بِمِائَةٍ فَجَمَعَهَا وَضَرَبَهُ بِهَا ضَرْبَةً وَاحِدَةً: بَرَّ لَا إِنْ حَلَفَ لَيَضْرِبَنَّهُ مِائَةً."]]},{"id":"da139_21","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢١","segs":[["matn","وَمَنْ حَلَفَ: لَا يَسْكُنُ هَذِهِ الدَّارَ أَوْ لَيَخْرُجَنَّ أَوْ لَيَرْحَلَنَّ مِنْهَا:"]]},{"id":"da139_22","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢٢","segs":[["matn","لَزِمَهُ الْخُرُوجُ بِنَفْسِهِ وَأَهْلِهِ وَمَتَاعِهِ الْمَقْصُودِ فَإِنْ أَقَامَ فَوْقَ زَمَنٍ يُمْكِنُهُ الْخُرُوجُ فِيهِ عَادَةً وَلَمْ يَخْرُجْ حَنِثَ فَإِنْ لَمْ يَجِدْ مَسْكَنًا أَوْ أَبَتْ زَوْجَتُهُ الْخُرُوجَ مَعَهُ"]]},{"id":"da139_23","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢٣","segs":[["matn","وَلَا يُمْكِنُهُ إِجْبَارُهَا فَخَرَجَ وَحْدَهُ لَمْ يَحْنَثْ وَكَذَا الْبَلَدُ إِلَّا أَنَّهُ يَبَرُّ بِخُرُوجِهِ وَحْدَهُ إِذَا حَلَفَ لَيَخْرُجَنَّ مِنْهُ وَلَا يَحْنَثُ فِي الْجَمِيعِ بِالْعَوْدِ مَا لَمْ تَكُنْ نِيَّةٌ أَوْ سَبَبٌ."]]},{"id":"da139_24","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢٤","segs":[["matn","وَالسَّفَرُ الْقَصِيرُ: سَفَرٌ يَبَرُّ بِهِ مَنْ حَلَفَ: لَيُسَافِرَنَّ وَيَحْنَثُ بِهِ مَنْ حَلَفَ: لَا يُسَافِرُ. وَكَذَا النَّوْمُ الْيَسِيرُ."]]},{"id":"da139_25","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢٥","segs":[["matn","وَمَنْ حَلَفَ: لَا يَسْتَخْدِمُ فُلَانًا فَخَدَمَهُ وَهُوَ سَاكِتٌ: حَنِثَ وَلَا يَبِيتُ أَوْ لَا يَأْكُلُ بِبَلَدِ كَذَا فَبَاتَ أَوْ أَكَلَ خَارِجَ بُنْيَانِهِ: لَمْ يَحْنَثْ."]]},{"id":"da139_26","label":"بَابُ جَامِعِ الْأَيْمَانِ · ٢٦","segs":[["matn","وَفِعْلُ الْوَكِيلِ كَالْمُوَكِّلِ فَمَنْ حَلَفَ: لَا يَفْعَلُ كَذَا فَوَكَّلَ فِيهِ مَنْ يَفْعَلُهُ: حَنِثَ"]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"da140","title":"بَابُ النَّذْرِ","units":[{"id":"da140_1","label":"بَابُ النَّذْرِ · ١","segs":[["matn","وَهُوَ مَكْرُوهٌ لَا يَأْتِي بِخَيْرٍ وَلَا يَرُدُّ قَضَاءً. وَلَا يَصِحُّ إِلَّا بِالْقَوْلِ مِنْ مُكَلَّفٍ مُخْتَارٍ."]]},{"id":"da140_2","label":"بَابُ النَّذْرِ · ٢","segs":[["matn","وَأَنْوَاعُهُ الْمُنْعَقِدَةُ سِتَّةٌ أَحْكَامُهَا مُخْتَلِفَةٌ: أَحَدُهَا: النَّذْرُ الْمُطْلَقُ كَقَوْلِهِ: لِلَّهِ عَلَيَّ نَذْرٌ فَيَلْزَمُهُ كَفَّارَةُ يَمِينٍ وَكَذَا: إِنْ قَالَ: عَلَيَّ نَذْرٌ إِنْ فَعَلْتُ كَذَا ثُمَّ يَفْعَلُهُ."]]},{"id":"da140_3","label":"بَابُ النَّذْرِ · ٣","segs":[["matn","الثَّانِي: نَذْرُ لَجَاجٍ وَغَضَبٍ كَإِنْ كَلَّمْتُكَ أَوْ: إِنْ لَمْ أُعْطِكَ أَوْ: إِنْ كَانَ هَذَا كَذَا: فَعَلَيَّ الْحَجُّ أَوِ الْعِتْقُ أَوْ صَوْمُ سَنَةٍ أَوْ مَالِي صَدَقَةٌ: فَيُخَيَّرُ بَيْنَ الْفِعْلِ أَوْ كَفَّارَةِ يَمِينٍ."]]},{"id":"da140_4","label":"بَابُ النَّذْرِ · ٤","segs":[["matn","الثَّالِثُ: نَذْرٌ مُبَاحٌ كَلِلَّهِ عَلَيَّ أَنْ أَلْبَسَ ثَوْبِي أَوْ أَرْكَبَ دَابَّتِي فَيُخَيَّرُ أَيْضًا. الرَّابِعُ: نَذْرٌ مَكْرُوهٌ كَطَلَاقٍ وَنَحْوِهِ: فَيُسَنُّ أَنْ يُكَفِّرَ وَلَا يَفْعَلَهُ."]]},{"id":"da140_5","label":"بَابُ النَّذْرِ · ٥","segs":[["matn","الْخَامِسُ: نَذْرُ مَعْصِيَةٍ كَشُرْبِ الْخَمْرِ وَصَوْمِ يَوْمِ الْعِيدِ وَنَحْوِهِ فَيَحْرُمُ الْوَفَاءُ بِهِ وَيُكَفِّرُ وَيَقْضِي الصَّوْمَ."]]},{"id":"da140_6","label":"بَابُ النَّذْرِ · ٦","segs":[["matn","السَّادِسُ: نَذْرُ تَبَرُّرٍ: كَصَلَاةٍ وَصِيَامٍ وَلَوْ وَاجِبَيْنِ وَاعْتِكَافٍ وَصَدَقَةٍ وَحَجٍّ وَعُمْرَةٍ بِقَصْدِ التَّقَرُّبِ أَوْ يُعَلِّقُ ذَلِكَ بِشَرْطِ حُصُولِ نِعْمَةٍ أَوْ دَفْعِ نِقْمَةٍ كَإِنْ شَفَى اللَّهُ مَرِيضِي أَوْ سَلِمَ مَالِي فَعَلَيَّ كَذَا: فَهَذَا يَجِبُ الْوَفَاءُ بِهِ."]]},{"id":"da140_7","label":"بَابُ النَّذْرِ · ٧","segs":[["matn","فَصْلٌ: وَمَنْ نَذَرَ صَوْمَ شَهْرٍ مُعَيَّنٍ: لَزِمَهُ صَوْمُهُ مُتَتَابِعًا فَإِنْ أَفْطَرَ لِغَيْرِ عُذْرٍ: حَرُمَ وَلَزِمَهُ اسْتِئْنَافُ الصَّوْمِ مَعَ كَفَّارَةِ يَمِينٍ لِفَوَاتِ الْمَحَلِّ وَلِعُذْرٍ: بَنَى وَيُكَفِّرُ لِفَوَاتِ التَّتَابُعِ."]]},{"id":"da140_8","label":"بَابُ النَّذْرِ · ٨","segs":[["matn","وَلَوْ نَذَرَ شَهْرًا مُطْلَقًا أَوْ صَوْمًا مُتَتَابِعًا غَيْرَ مُقَيَّدٍ بِزَمَنٍ: لَزِمَهُ التَّتَابُعُ. فَإِنْ أَفْطَرَ لِغَيْرِ عُذْرٍ: لَزِمَهُ اسْتِئْنَافُهُ بِلَا كَفَّارَةٍ وَلِعُذْرٍ: خُيِّرَ بَيْنَ اسْتِئْنَافِهِ وَلَا شَيْءَ عَلَيْهِ وَبَيْنَ الْبِنَاءِ وَيُكَفِّرُ. وَلِمَنْ نَذَرَ صَلَاةً جَالِسًا أَنْ يُصَلِّيَهَا قَائِمًا."]]}],"group":"كِتَابُ الْأَيْمَانِ"},{"id":"da141","title":"كِتَابُ الْقَضَاءِ","units":[{"id":"da141_1","label":"كِتَابُ الْقَضَاءِ · ١","segs":[["matn","وَهُوَ فَرْضُ كِفَايَةٍ. فَيَجِبُ عَلَى الْإِمَامِ أَنْ يَنْصِبَ بِكُلِّ إِقْلِيمٍ قَاضِيًا وَيَخْتَارَ لِذَلِكَ أَفْضَلَ مَنْ يَجِدُ عِلْمًا وَوَرَعًا وَيَأْمُرَهُ بِالتَّقْوَى وَتَحَرِّي الْعَدْلِ. وَتَصِحُّ وِلَايَةُ الْقَضَاءِ وَالْإِمَارَةُ مُنَجَّزَةً وَمُعَلَّقَةً."]]},{"id":"da141_2","label":"كِتَابُ الْقَضَاءِ · ٢","segs":[["matn","وَشُرِطَ لِصِحَّةِ التَّوْلِيَةِ: كَوْنُهَا مِنْ إِمَامٍ أَوْ نَائِبِهِ فِيهِ وَأَنْ يُعَيِّنَ لَهُ مَا يُوَلِّيهِ فِيهِ الْحُكْمَ مِنْ عَمَلٍ وَبَلَدٍ."]]},{"id":"da141_3","label":"كِتَابُ الْقَضَاءِ · ٣","segs":[["matn","وَأَلْفَاظُ التَّوْلِيَةِ الصَّرِيحَةُ سَبْعَةٌ: وَلَّيْتُكَ الْحُكْمَ أَوْ قَلَّدْتُكَهُ وَفَوَّضْتُ أَوْ رَدَدْتُ أَوْ جَعَلْتُ إِلَيْكَ الْحُكْمَ وَاسْتَخْلَفْتُكَ وَاسْتَنَبْتُكَ فِي الْحُكْمِ."]]},{"id":"da141_4","label":"كِتَابُ الْقَضَاءِ · ٤","segs":[["matn","وَالْكِنَايَةُ نَحْوُ: اعْتَمَدْتُ أَوْ عَوَّلْتُ عَلَيْكَ وَوَكَّلْتُكَ أَوِ اسْتَنَدْتُ إِلَيْكَ: لَا تَنْعَقِدُ بِهَا إِلَّا بِقَرِينَةٍ نَحْوُ: فَاحْكُمْ أَوْ: فَتَوَلَّ مَا عَوَّلْتُ عَلَيْكَ فِيهِ."]]},{"id":"da141_5","label":"كِتَابُ الْقَضَاءِ · ٥","segs":[["matn","فَصْلٌ: وَتُفِيدُ وِلَايَةُ الْحُكْمِ الْعَامَّةُ فَصْلَ الْخُصُومَاتِ وَأَخْذَ الْحَقِّ وَدَفْعَهُ لِلْمُسْتَحِقِّ وَالنَّظَرَ فِي مَالِ الْيَتِيمِ وَالْمَجْنُونِ وَالسَّفِيهِ وَالْغَائِبِ وَالْحَجْرَ لِسَفَهٍ وَفَلَسٍ وَالنَّظَرَ فِي الْأَوْقَافِ لِتَجْرِيَ عَلَى شَرْطِهَا وَتَزْوِيجَ مَنْ لَا وَلِيَّ لَهَا."]]},{"id":"da141_6","label":"كِتَابُ الْقَضَاءِ · ٦","segs":[["matn","وَلَا يَسْتَفِيدُ الِاحْتِسَابَ عَلَى الْبَاعَةِ وَلَا إِلْزَامَهُمْ بِالشَّرْعِ. وَلَا يَنْفُذُ حُكْمُهُ: فِي غَيْرِ مَحَلِّ عَمَلِهِ."]]},{"id":"da141_7","label":"كِتَابُ الْقَضَاءِ · ٧","segs":[["matn","فَصْلٌ: وَيُشْتَرَطُ فِي الْقَاضِي عَشْرُ خِصَالٍ: كَوْنُهُ بَالِغًا عَاقِلًا ذَكَرًا حُرًّا مُسْلِمًا عَدْلًا سَمِيعًا بَصِيرًا مُتَكَلِّمًا مُجْتَهِدًا وَلَوْ فِي مَذْهَبِ إِمَامِهِ لِلضَّرُورَةِ."]]},{"id":"da141_8","label":"كِتَابُ الْقَضَاءِ · ٨","segs":[["matn","فَلَوْ حَكَّمَ اثْنَانِ فَأَكْثَرُ بَيْنَهُمَا شَخْصًا صَالِحًا لِلْقَضَاءِ: نَفَذَ حُكْمُهُ فِي كُلِّ مَا يَنْفُذُ فِيهِ حُكْمُ مَنْ وَلَّاهُ الْإِمَامُ أَوْ نَائِبُهُ وَيَرْفَعُ الْخِلَافَ فَلَا يَحِلُّ لِأَحَدٍ نَقْضُهُ حَيْثُ أَصَابَ الْحَقَّ."]]},{"id":"da141_9","label":"كِتَابُ الْقَضَاءِ · ٩","segs":[["matn","فَصْلٌ: وَيُسَنُّ كَوْنُ الْحَاكِمِ قَوِيًّا بِلَا عُنْفٍ لَيِّنًا بِلَا ضَعْفٍ حَلِيمًا مُتَأَنِّيًا مُتَفَطِّنًا عَفِيفًا بَصِيرًا بِأَحْكَامِ الْحُكَّامِ قَبْلَهُ."]]},{"id":"da141_10","label":"كِتَابُ الْقَضَاءِ · ١٠","segs":[["matn","وَيَجِبُ عَلَيْهِ الْعَدْلُ بَيْنَ الْخَصْمَيْنِ فِي لَحْظِهِ وَلَفْظِهِ وَمَجْلِسِهِ وَالدُّخُولِ عَلَيْهِ إِلَّا الْمُسْلِمَ مَعَ الْكَافِرِ: فَيُقَدَّمُ دُخُولًا وَيُرْفَعُ جُلُوسًا."]]},{"id":"da141_11","label":"كِتَابُ الْقَضَاءِ · ١١","segs":[["matn","وَيَحْرُمُ عَلَيْهِ أَخْذُ الرِّشْوَةِ وَأَنْ يُسَارَّ أَحَدَ الْخَصْمَيْنِ أَوْ يُضَيِّفَهُ أَوْ يَقُومَ لَهُ دُونَ الْآخَرِ."]]},{"id":"da141_12","label":"كِتَابُ الْقَضَاءِ · ١٢","segs":[["matn","وَيَحْرُمُ عَلَيْهِ الْحُكْمُ وَهُوَ غَضْبَانُ كَثِيرًا أَوْ حَاقِنٌ أَوْ فِي شِدَّةِ جُوعٍ أَوْ عَطَشٍ أَوْ هَمٍّ أَوْ مَلَلٍ أَوْ كَسَلٍ أَوْ نُعَاسٍ أَوْ بَرْدٍ مُؤْلِمٍ أَوْ حَرٍّ مُزْعِجٍ فَإِنْ خَالَفَ وَحَكَمَ صَحَّ إِنْ أَصَابَ الْحَقَّ."]]},{"id":"da141_13","label":"كِتَابُ الْقَضَاءِ · ١٣","segs":[["matn","وَيَحْرُمُ عَلَيْهِ أَنْ يَحْكُمَ بِالْجَهْلِ أَوْ وَهُوَ مُتَرَدِّدٌ فَإِنْ خَالَفَ وَحَكَمَ: لَمْ يَصِحَّ وَلَوْ أَصَابَ الْحَقَّ."]]},{"id":"da141_14","label":"كِتَابُ الْقَضَاءِ · ١٤","segs":[["matn","وَيُوصِي الْوُكَلَاءَ وَالْأَعْوَانَ بِبَابِهِ بِالرِّفْقِ بِالْخُصُومِ وَقِلَّةِ الطَّمَعِ وَيَجْتَهِدُ أَنْ يَكُونُوا شُيُوخًا أَوْ كُهُولًا مِنْ أَهْلِ الدِّينِ وَالْعِفَّةِ وَالصِّيَانَةِ."]]},{"id":"da141_15","label":"كِتَابُ الْقَضَاءِ · ١٥","segs":[["matn","وَيُبَاحُ لَهُ: أَنْ يَتَّخِذَ كَاتِبًا يَكْتُبُ الْوَقَائِعَ وَيُشْتَرَطُ كَوْنُهُ مُسْلِمًا مُكَلَّفًا عَدْلًا وَيُسَنُّ كَوْنُهُ حَافِظًا عَالِمًا."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"da142","title":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ","units":[{"id":"da142_1","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١","segs":[["matn","إِذَا حَضَرَ إِلَى الْحَاكِمِ خَصْمَانِ: فَلَهُ أَنْ يَسْكُتَ حَتَّى يَبْتَدِئَا وَلَهُ أَنْ يَقُولَ: أَيُّكُمَا الْمُدَّعِي؟."]]},{"id":"da142_2","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٢","segs":[["matn","فَإِذَا ادَّعَى أَحَدُهُمَا: اشْتُرِطَ كَوْنُ الدَّعْوَى مَعْلُومَةً وَكَوْنُهَا مُنْفَكَّةً عَمَّا يُكَذِّبُهَا ثُمَّ إِنْ كَانَتْ بِدَيْنٍ: اشْتُرِطَ كَوْنُهُ حَالًّا."]]},{"id":"da142_3","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٣","segs":[["matn","وَإِنْ كَانَتْ بِعَيْنٍ: اشْتُرِطَ حُضُورُهَا لِمَجْلِسِ الْحُكْمِ لِتُعَيَّنَ بِالْإِشَارَةِ فَإِنْ كَانَتْ غَائِبَةً عَنِ الْبَلَدِ: وَصَفَهَا كَصِفَاتِ السَّلَمِ."]]},{"id":"da142_4","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٤","segs":[["matn","فَإِذَا أَتَمَّ الْمُدَّعِي دَعْوَاهُ: فَإِنْ أَقَرَّ خَصْمُهُ بِمَا ادَّعَاهُ أَوِ اعْتَرَفَ بِسَبَبِ الْحَقِّ ثُمَّ ادَّعَى الْبَرَاءَةَ: لَمْ يَلْتَفِتْ لِقَوْلِهِ بَلْ يُحَلِّفُ الْمُدَّعِيَ عَلَى نَفْيِ مَا ادَّعَاهُ وَيُلْزِمُهُ بِالْحَقِّ إِلَّا أَنْ يُقِيمَ بَيِّنَةً بِبَرَاءَتِهِ."]]},{"id":"da142_5","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٥","segs":[["matn","وَإِنْ أَنْكَرَ الْخَصْمُ ابْتِدَاءً: بِأَنْ قَالَ لِمُدَّعٍ قَرْضًا أَوْ ثَمَنًا: مَا أَقْرَضَنِي أَوْ: مَا بَاعَنِي أَوْ لَا يَسْتَحِقُّ عَلَيَّ شَيْئًا مِمَّا ادَّعَاهُ أَوْ لَا حَقَّ لَهُ عَلَيَّ: صَحَّ الْجَوَابُ فَيَقُولُ الْحَاكِمُ لِلْمُدَّعِي: هَلْ لَكَ بَيِّنَةٌ؟"]]},{"id":"da142_6","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٦","segs":[["matn","فَإِنْ قَالَ: نَعَمْ قَالَ لَهُ: إِنْ شِئْتَ فَأَحْضِرْهَا فَإِذَا أَحْضَرَهَا وَشَهِدَتْ سَمِعَهَا وَحَرُمَ تَرْدِيدُهَا."]]},{"id":"da142_7","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٧","segs":[["matn","فَصْلٌ: وَيُعْتَبَرُ فِي الْبَيِّنَةِ: الْعَدَالَةُ ظَاهِرًا وَبَاطِنًا. وَلِلْحَاكِمِ أَنْ يَعْمَلَ بِعِلْمِهِ فِيمَا أَقَرَّ بِهِ فِي مَجْلِسِ حُكْمِهِ وَفِي عَدَالَةِ الْبَيِّنَةِ وَفِسْقِهَا."]]},{"id":"da142_8","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٨","segs":[["matn","فَإِنِ ارْتَابَ مِنْهَا: فَلَا بُدَّ مِنَ الْمُزَكِّينَ لَهَا فَإِنْ طَلَبَ الْمُدَّعِي مِنَ الْحَاكِمِ أَنْ يَحْبِسَ غَرِيمَهُ حَتَّى يَأْتِيَ بِمَنْ يُزَكِّي بَيِّنَتَهُ: أَجَابَهُ لِمَا سَأَلَ وَانْتَظَرَهُ ثَلَاثَةَ أَيَّامٍ فَإِنْ أَتَى بِالْمُزَكِّينَ اعْتُبِرَ مَعْرِفَتُهُمْ لِمَنْ يُزَكُّونَهُ بِالصُّحْبَةِ وَالْمُعَامَلَةِ."]]},{"id":"da142_9","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ٩","segs":[["matn","فَإِنِ ادَّعَى الْغَرِيمُ فِسْقَ الْمُزَكِّينَ أَوْ فِسْقَ الْبَيِّنَةِ الْمُزَكَّاةِ وَأَقَامَ بِذَلِكَ بَيِّنَةً سُمِعَتْ وَبَطَلَتِ الشَّهَادَةُ. وَلَا يُقْبَلُ: مِنَ النِّسَاءِ تَعْدِيلٌ وَلَا تَجْرِيحٌ."]]},{"id":"da142_10","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٠","segs":[["matn","وَحَيْثُ ظَهَرَ فِسْقُ بَيِّنَةِ الْمُدَّعِي أَوْ قَالَ ابْتِدَاءً: لَيْسَ لِي بَيِّنَةٌ قَالَ لَهُ الْحَاكِمُ: لَيْسَ لَكَ عَلَى غَرِيمِكَ إِلَّا الْيَمِينُ فَيُحَلِّفُ الْغَرِيمَ عَلَى صِفَةِ جَوَابِهِ فِي الدَّعْوَى وَيُخَلِّي سَبِيلَهُ وَيَحْرُمُ تَحْلِيفُهُ بَعْدَ ذَلِكَ."]]},{"id":"da142_11","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١١","segs":[["matn","وَإِنْ كَانَ لِلْمُدَّعِي بَيِّنَةٌ فَلَهُ أَنْ يُقِيمَهَا بَعْدَ ذَلِكَ. وَإِنْ لَمْ يَحْلِفِ الْغَرِيمُ: قَالَ لَهُ الْحَاكِمُ: إِنْ لَمْ تَحْلِفْ وَإِلَّا حَكَمْتُ عَلَيْكَ بِالنُّكُولِ."]]},{"id":"da142_12","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٢","segs":[["matn","وَيُسَنُّ تَكْرَارُهُ ثَلَاثًا فَإِنْ لَمْ يَحْلِفْ حَكَمَ عَلَيْهِ بِالنُّكُولِ وَلَزِمَهُ الْحَقُّ."]]},{"id":"da142_13","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٣","segs":[["matn","فَصْلٌ: وَحُكْمُ الْحَاكِمِ يَرْفَعُ الْخِلَافَ لَكِنْ لَا يُزِيلُ الشَّيْءَ عَنْ صِفَتِهِ بَاطِنًا فَمَتَى حُكِمَ لَهُ بِبَيِّنَةِ زُورٍ بِزَوْجِيَّةِ امْرَأَةٍ وَوَطِئَ مَعَ الْعِلْمِ: فَكَالزِّنَا."]]},{"id":"da142_14","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٤","segs":[["matn","وَإِنْ بَاعَ حَنْبَلِيٌّ مَتْرُوكَ التَّسْمِيَةِ فَحَكَمَ بِصِحَّتِهِ شَافِعِيٌّ: نَفَذَ. وَمَنْ قَلَّدَ فِي صِحَّةِ نِكَاحٍ صَحَّ وَلَمْ يُفَارِقْ بِتَغَيُّرِ اجْتِهَادِهِ كَالْحُكْمِ بِذَلِكَ."]]},{"id":"da142_15","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٥","segs":[["matn","فَصْلٌ: وَتَصِحُّ الدَّعْوَى بِحُقُوقِ الْآدَمِيِّينَ عَلَى الْمَيِّتِ وَعَلَى غَيْرِ الْمُكَلَّفِ وَعَلَى الْغَائِبِ مَسَافَةَ قَصْرٍ وَكَذَا دُونَهَا إِذَا كَانَ مُسْتَتِرًا بِشَرْطِ الْبَيِّنَةِ فِي الْكُلِّ."]]},{"id":"da142_16","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٦","segs":[["matn","وَيَصِحُّ أَنْ يَكْتُبَ الْقَاضِي الَّذِي ثَبَتَ عِنْدَهُ الْحَقُّ إِلَى قَاضٍ آخَرَ مُعَيَّنٍ أَوْ غَيْرِ مُعَيَّنٍ بِصُورَةِ الدَّعْوَى الْوَاقِعَةِ عَلَى الْغَائِبِ بِشَرْطِ أَنْ يَقْرَأَ ذَلِكَ عَلَى عَدْلَيْنِ ثُمَّ يَدْفَعَهُ لَهُمَا وَيَقُولَ فِيهِ:"]]},{"id":"da142_17","label":"بَابُ طَرِيقِ الْحُكْمِ وَصِفَتِهِ · ١٧","segs":[["matn","وَإِنَّ ذَلِكَ قَدْ ثَبَتَ عِنْدِي وَإِنَّكَ تَأْخُذُ الْحَقَّ لِلْمُسْتَحِقِّ فَيَلْزَمُ الْقَاضِيَ الْوَاصِلَ إِلَيْهِ ذَلِكَ: الْعَمَلُ بِهِ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"da143","title":"بَابُ الْقِسْمَةِ","units":[{"id":"da143_1","label":"بَابُ الْقِسْمَةِ · ١","segs":[["matn","وَهِيَ نَوْعَانِ: قِسْمَةُ تَرَاضٍ وَقِسْمَةُ إِجْبَارٍ. فَلَا قِسْمَةَ فِي مُشْتَرَكٍ إِلَّا بِرِضَا الشُّرَكَاءِ كُلِّهِمْ حَيْثُ كَانَ فِي الْقِسْمَةِ ضَرَرٌ يَنْقُصُ الْقِيمَةَ كَحَمَّامٍ وَدُورٍ صِغَارٍ وَشَجَرٍ مُفْرَدٍ وَحَيَوَانٍ."]]},{"id":"da143_2","label":"بَابُ الْقِسْمَةِ · ٢","segs":[["matn","وَحَيْثُ تَرَاضَيَا صَحَّتْ وَكَانَتْ بَيْعًا يَثْبُتُ فِيهَا مَا يَثْبُتُ فِيهِ مِنَ الْأَحْكَامِ."]]},{"id":"da143_3","label":"بَابُ الْقِسْمَةِ · ٣","segs":[["matn","وَإِنْ لَمْ يَتَرَاضَيَا فَدَعَا أَحَدُهُمَا شَرِيكَهُ إِلَى الْبَيْعِ فِي ذَلِكَ أَوْ إِلَى بَيْعِ عَبْدٍ أَوْ بَهِيمَةٍ أَوْ سَيْفٍ وَنَحْوِهِ مِمَّا هُوَ شَرِكَةٌ بَيْنَهُمَا: أُجْبِرَ إِنِ امْتَنَعَ فَإِنْ أَبَى: بِيعَ عَلَيْهِمَا وَقُسِمَ الثَّمَنُ."]]},{"id":"da143_4","label":"بَابُ الْقِسْمَةِ · ٤","segs":[["matn","وَلَا إِجْبَارَ فِي قِسْمَةِ الْمَنَافِعِ فَإِنِ اقْتَسَمَاهَا بِالزَّمَنِ: كَهَذَا شَهْرًا وَالْآخَرُ مِثْلَهُ أَوْ بِالْمَكَانِ: كَهَذَا فِي بَيْتٍ وَالْآخَرُ فِي بَيْتٍ: صَحَّ جَائِزًا وَلِكُلٍّ الرُّجُوعُ."]]},{"id":"da143_5","label":"بَابُ الْقِسْمَةِ · ٥","segs":[["matn","فَصْلٌ: النَّوْعُ الثَّانِي: قِسْمَةُ إِجْبَارٍ وَهِيَ: مَا لَا ضَرَرَ فِيهَا وَلَا رَدُّ عِوَضٍ وَتَتَأَتَّى فِي كُلِّ مَكِيلٍ وَمَوْزُونٍ وَفِي دَارٍ كَبِيرَةٍ وَأَرْضٍ وَاسِعَةٍ وَيَدْخُلُ الشَّجَرُ تَبَعًا وَهَذَا النَّوْعُ لَيْسَ بَيْعًا فَيَجْبُرُ الْحَاكِمُ أَحَدَ الشَّرِيكَيْنِ إِذَا امْتَنَعَ."]]},{"id":"da143_6","label":"بَابُ الْقِسْمَةِ · ٦","segs":[["matn","وَيَصِحُّ أَنْ يَتَقَاسَمَا بِأَنْفُسِهِمَا وَأَنْ يَنْصِبَا قَاسِمًا بَيْنَهُمَا. وَيُشْتَرَطُ إِسْلَامُهُ وَعَدَالَتُهُ وَتَكْلِيفُهُ وَمَعْرِفَتُهُ بِالْقِسْمَةِ. وَأُجْرَتُهُ بَيْنَهُمَا عَلَى قَدْرِ أَمْلَاكِهِمَا."]]},{"id":"da143_7","label":"بَابُ الْقِسْمَةِ · ٧","segs":[["matn","وَإِنْ تَقَاسَمَا بِالْقُرْعَةِ جَازَ وَلَزِمَتِ الْقِسْمَةُ بِمُجَرَّدِ خُرُوجِ الْقُرْعَةِ وَلَوْ فِيمَا فِيهِ رَدٌّ أَوْ ضَرَرٌ. وَإِنْ خَيَّرَ أَحَدُهُمَا الْآخَرَ بِلَا قُرْعَةٍ وَتَرَاضَيَا: لَزِمَتْ بِالتَّفَرُّقِ."]]},{"id":"da143_8","label":"بَابُ الْقِسْمَةِ · ٨","segs":[["matn","وَإِنْ خَرَجَ فِي نَصِيبِ أَحَدِهِمَا عَيْبٌ جَهِلَهُ: خُيِّرَ بَيْنَ فَسْخٍ أَوْ إِمْسَاكٍ وَيَأْخُذَ الْأَرْشَ. وَإِنْ غُبِنَ غَبْنًا فَاحِشًا بَطَلَتْ. وَإِنِ ادَّعَى كُلٌّ أَنَّ هَذَا مِنْ سَهْمِهِ تَحَالَفَا وَنُقِضَتْ."]]},{"id":"da143_9","label":"بَابُ الْقِسْمَةِ · ٩","segs":[["matn","وَإِنْ حَصَلَتِ الطَّرِيقُ فِي حِصَّةِ أَحَدِهِمَا وَلَا مَنْفَذَ لِلْآخَرِ: بَطَلَتْ."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"da144","title":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ","units":[{"id":"da144_1","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ١","segs":[["matn","لَا تَصِحُّ الدَّعْوَى إِلَّا مِنْ جَائِزِ التَّصَرُّفِ. وَإِذَا تَدَاعَيَا عَيْنًا لَمْ تَخْلُ مِنْ أَرْبَعَةِ أَحْوَالٍ: أَحَدُهَا: أَنْ لَا تَكُونَ بِيَدِ أَحَدٍ وَلَا ثَمَّ ظَاهِرٌ وَلَا بَيِّنَةٌ فَيَتَحَالَفَانِ وَيَتَنَاصَفَانِهَا وَإِنْ وُجِدَ ظَاهِرٌ لِأَحَدِهِمَا عُمِلَ بِهِ."]]},{"id":"da144_2","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٢","segs":[["matn","الثَّانِي: أَنْ تَكُونَ بِيَدِ أَحَدِهِمَا فَهِيَ لَهُ بِيَمِينِهِ فَإِنْ لَمْ يَحْلِفْ قُضِيَ عَلَيْهِ بِالنُّكُولِ وَلَوْ أَقَامَ بَيِّنَةً. الثَّالِثُ: أَنْ تَكُونَ بِيَدَيْهِمَا كَشَيْءٍ: كُلٌّ مُمْسِكٌ لِبَعْضِهِ فَيَتَحَالَفَانِ وَيَتَنَاصَفَانِهِ."]]},{"id":"da144_3","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٣","segs":[["matn","فَإِنْ قَوِيَتْ يَدُ أَحَدِهِمَا كَحَيَوَانٍ: وَاحِدٌ سَائِقُهُ وَالْآخَرُ رَاكِبُهُ أَوْ قَمِيصٍ: وَاحِدٌ آخِذٌ بِكُمِّهِ وَالْآخَرُ لَابِسُهُ: فَلِلثَّانِي بِيَمِينِهِ. وَإِنْ تَنَازَعَ صَانِعَانِ فِي آلَةِ دُكَّانِهِمَا: فَآلَةُ كُلِّ صَنْعَةٍ لِصَانِعِهَا."]]},{"id":"da144_4","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٤","segs":[["matn","وَمَتَى كَانَ لِأَحَدِهِمَا بَيِّنَةٌ فَالْعَيْنُ لَهُ فَإِنْ كَانَ لِكُلٍّ مِنْهُمَا بَيِّنَةٌ بِهِ وَتَسَاوَتَا مِنْ كُلِّ وَجْهٍ تَعَارَضَتَا وَتَسَاقَطَتَا فَيَتَحَالَفَانِ وَيَتَنَاصَفَانِ مَا بِأَيْدِيهِمَا وَيَقْتَرِعَانِ فِيمَا عَدَاهُ فَمَنْ خَرَجَتْ لَهُ الْقُرْعَةُ فَهُوَ لَهُ بِيَمِينِهِ."]]},{"id":"da144_5","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٥","segs":[["matn","وَإِنْ كَانَتِ الْعَيْنُ بِيَدِ أَحَدِهِمَا: فَهُوَ دَاخِلٌ وَالْآخَرُ خَارِجٌ وَبَيِّنَةُ الْخَارِجِ مُقَدَّمَةٌ عَلَى بَيِّنَةِ الدَّاخِلِ لَكِنْ لَوْ أَقَامَ الْخَارِجُ بَيِّنَةً أَنَّهَا مِلْكُهُ وَالدَّاخِلُ بَيِّنَةً أَنَّهُ اشْتَرَاهَا مِنْهُ:"]]},{"id":"da144_6","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٦","segs":[["matn","قُدِّمَتْ بَيِّنَتُهُ هُنَا لِمَا مَعَهَا مِنْ زِيَادَةِ الْعِلْمِ أَوْ أَقَامَ أَحَدُهُمَا بَيِّنَةً أَنَّهُ اشْتَرَاهَا مِنْ فُلَانٍ وَأَقَامَ الْآخَرُ بَيِّنَةً كَذَلِكَ عُمِلَ بِأَسْبَقِهِمَا تَارِيخًا."]]},{"id":"da144_7","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٧","segs":[["matn","الرَّابِعُ: أَنْ تَكُونَ بِيَدِ ثَالِثٍ فَإِنِ ادَّعَاهَا لِنَفْسِهِ حَلَفَ لِكُلِّ وَاحِدٍ يَمِينًا فَإِنْ نَكَلَ أَخَذَاهَا مِنْهُ مَعَ بَدَلِهَا وَاقْتَرَعَا عَلَيْهِمَا وَإِنْ أَقَرَّ بِهَا لَهُمَا اقْتَسَمَاهَا وَحَلَفَ لِكُلِّ وَاحِدٍ يَمِينًا وَحَلَفَ كُلُّ وَاحِدٍ لِصَاحِبِهِ عَلَى النِّصْفِ الْمَحْكُومِ لَهُ بِهِ."]]},{"id":"da144_8","label":"بَابُ الدَّعَاوَى وَالْبَيِّنَاتِ · ٨","segs":[["matn","وَإِنْ قَالَ: هِيَ لِأَحَدِهِمَا وَأَجْهَلُهُ فَصَدَّقَاهُ لَمْ يَحْلِفْ وَإِلَّا حَلَفَ يَمِينًا وَاحِدَةً وَيُقْرَعُ بَيْنَهُمَا فَمَنْ قَرَعَ حَلَفَ وَأَخَذَهَا."]]}],"group":"كِتَابُ الْقَضَاءِ"},{"id":"da145","title":"كِتَابُ الشَّهَادَاتِ","units":[{"id":"da145_1","label":"كِتَابُ الشَّهَادَاتِ · ١","segs":[["matn","تَحَمُّلُ الشَّهَادَةِ فِي حُقُوقِ الْآدَمِيِّينَ فَرْضُ كِفَايَةٍ وَأَدَاؤُهَا فَرْضُ عَيْنٍ وَمَتَى تَحَمَّلَهَا وَجَبَتْ كِتَابَتُهَا."]]},{"id":"da145_2","label":"كِتَابُ الشَّهَادَاتِ · ٢","segs":[["matn","وَيَحْرُمُ أَخْذُ أُجْرَةٍ وَجُعْلٍ عَلَيْهَا لَكِنْ إِنْ عَجَزَ عَنِ الْمَشْيِ أَوْ تَأَذَّى بِهِ: فَلَهُ أَخْذُ أُجْرَةِ مَرْكُوبٍ. وَيَحْرُمُ كَتْمُ الشَّهَادَةِ وَلَا ضَمَانَ."]]},{"id":"da145_3","label":"كِتَابُ الشَّهَادَاتِ · ٣","segs":[["matn","وَيَجِبُ الْإِشْهَادُ: فِي عَقْدِ النِّكَاحِ خَاصَّةً وَيُسَنُّ: فِي كُلِّ عَقْدٍ سِوَاهُ. وَيَحْرُمُ أَنْ يَشْهَدَ إِلَّا بِمَا يَعْلَمُهُ وَالْعِلْمُ إِمَّا بِرُؤْيَةٍ أَوْ سَمَاعٍ."]]},{"id":"da145_4","label":"كِتَابُ الشَّهَادَاتِ · ٤","segs":[["matn","وَمَنْ رَأَى شَيْئًا بِيَدِ إِنْسَانٍ يَتَصَرَّفُ فِيهِ مُدَّةً طَوِيلَةً: كَتَصَرُّفِ الْمُلَّاكِ مِنْ نَقْضٍ وَبِنَاءٍ وَإِجَارَةٍ وَإِعَارَةٍ: فَلَهُ أَنْ يَشْهَدَ لَهُ بِالْمِلْكِ وَالْوَرَعُ أَنْ يَشْهَدَ بِالْيَدِ وَالتَّصَرُّفِ."]]},{"id":"da145_5","label":"كِتَابُ الشَّهَادَاتِ · ٥","segs":[["matn","فَصْلٌ: وَإِنْ شَهِدَا أَنَّهُ طَلَّقَ وَاحِدَةً وَنَسِيَا عَيْنَهَا لَمْ تُقْبَلْ."]]},{"id":"da145_6","label":"كِتَابُ الشَّهَادَاتِ · ٦","segs":[["matn","وَلَوْ شَهِدَ أَحَدُهُمَا أَنَّهُ أَقَرَّ لَهُ بِأَلْفٍ وَالْآخَرُ أَنَّهُ أَقَرَّ لَهُ بِأَلْفَيْنِ، كَمَلَتْ بِأَلْفٍ وَلَهُ أَنْ يَحْلِفَ عَلَى الْأَلْفِ الْآخَرِ مَعَ شَاهِدِهِ وَيَسْتَحِقُّهُ وَإِنْ شَهِدَا أَنَّ عَلَيْهِ أَلْفًا وَقَالَ أَحَدُهُمَا: قَضَاهُ بَعْضَهُ بَطَلَتْ شَهَادَتُهُ."]]},{"id":"da145_7","label":"كِتَابُ الشَّهَادَاتِ · ٧","segs":[["matn","وَإِنْ شَهِدَا أَنَّهُ أَقْرَضَهُ أَلْفًا ثُمَّ قَالَ أَحَدُهُمَا: قَضَاهُ نِصْفَهُ: صَحَّتْ شَهَادَتُهُمَا. وَلَا يَحِلُّ: لِمَنْ أَخْبَرَهُ عَدْلٌ بِاقْتِضَاءِ الْحَقِّ أَنْ يَشْهَدَ بِهِ."]]},{"id":"da145_8","label":"كِتَابُ الشَّهَادَاتِ · ٨","segs":[["matn","وَلَوْ شَهِدَ اثْنَانِ فِي جَمْعٍ مِنَ النَّاسِ عَلَى وَاحِدٍ مِنْهُمْ أَنَّهُ طَلَّقَ أَوْ أَعْتَقَ أَوْ شَهِدَا عَلَى خَطِيبٍ أَنَّهُ قَالَ أَوْ فَعَلَ عَلَى الْمِنْبَرِ فِي الْخُطْبَةِ شَيْئًا وَلَمْ يَشْهَدْ بِهِ أَحَدٌ غَيْرُهُمَا: قُبِلَتْ شَهَادَتُهُمَا."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"da146","title":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ","units":[{"id":"da146_1","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ١","segs":[["matn","وَهِيَ سِتَّةٌ: أَحَدُهَا: الْبُلُوغُ فَلَا شَهَادَةَ لِصَغِيرٍ وَلَوِ اتَّصَفَ بِالْعَدَالَةِ. الثَّانِي: الْعَقْلُ فَلَا شَهَادَةَ لِمَعْتُوهٍ وَمَجْنُونٍ. الثَّالِثُ: النُّطْقُ: فَلَا شَهَادَةَ لِأَخْرَسَ إِلَّا إِذَا أَدَّاهَا بِخَطِّهِ."]]},{"id":"da146_2","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٢","segs":[["matn","الرَّابِعُ: الْحِفْظُ: فَلَا شَهَادَةَ لِمُغَفَّلٍ وَمَعْرُوفٍ بِكَثْرَةِ غَلَطٍ وَسَهْوٍ. الْخَامِسُ: الْإِسْلَامُ: فَلَا شَهَادَةَ لِكَافِرٍ وَلَوْ عَلَى مِثْلِهِ."]]},{"id":"da146_3","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٣","segs":[["matn","السَّادِسُ: الْعَدَالَةُ وَيُعْتَبَرُ لَهَا شَيْئَانِ: الصَّلَاحُ فِي الدِّينِ وَهُوَ: أَدَاءُ الْفَرَائِضِ بِرَوَاتِبِهَا وَاجْتِنَابُ الْمُحَرَّمِ: بِأَنْ لَا يَأْتِيَ كَبِيرَةً وَلَا يُدْمِنَ عَلَى صَغِيرَةٍ."]]},{"id":"da146_4","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٤","segs":[["matn","الثَّانِي: اسْتِعْمَالُ الْمُرُوءَةِ بِفِعْلِ مَا يُجَمِّلُهُ وَيُزَيِّنُهُ وَتَرْكِ مَا يُدَنِّسُهُ وَيَشِينُهُ. فَلَا شَهَادَةَ لِمُتَمَسْخِرٍ وَرَقَّاصٍ وَمُشَعْبِذٍ وَلَاعِبٍ بِشِطْرَنْجٍ وَنَحْوِهِ."]]},{"id":"da146_5","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٥","segs":[["matn","وَلَا لِمَنْ يَمُدُّ رِجْلَيْهِ بِحَضْرَةِ النَّاسِ أَوْ يَكْشِفُ مِنْ بَدَنِهِ مَا جَرَتِ الْعَادَةُ بِتَغْطِيَتِهِ. وَلَا لِمَنْ يَحْكِي الْمُضْحِكَاتِ وَلَا لِمَنْ يَأْكُلُ بِالسُّوقِ وَيُغْتَفَرُ الْيَسِيرُ كَاللُّقْمَةِ وَالتُّفَّاحَةِ."]]},{"id":"da146_6","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٦","segs":[["matn","فَصْلٌ: وَمَتَى وُجِدَ الشَّرْطُ بِأَنْ بَلَغَ الصَّغِيرُ وَعَقَلَ الْمَجْنُونُ وَأَسْلَمَ الْكَافِرُ وَتَابَ الْفَاسِقُ: قُبِلَتِ الشَّهَادَةُ بِمُجَرَّدِ ذَلِكَ."]]},{"id":"da146_7","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٧","segs":[["matn","وَلَا تُشْتَرَطُ الْحُرِّيَّةُ فَتُقْبَلُ شَهَادَةُ الْعَبْدِ وَالْأَمَةِ فِي كُلِّ مَا تُقْبَلُ فِيهِ شَهَادَةُ الْحُرِّ وَالْحُرَّةِ."]]},{"id":"da146_8","label":"بَابُ شُرُوطِ بُلُوغِ مَنْ تُقْبَلُ شَهَادَتُهُ · ٨","segs":[["matn","وَلَا يُشْتَرَطُ كَوْنُ الصِّنَاعَةِ غَيْرَ دَنِيئَةٍ وَلَا كَوْنُهُ بَصِيرًا؛ فَتُقْبَلُ شَهَادَةُ الْأَعْمَى بِمَا سَمِعَهُ حَيْثُ تَيَقَّنَ الصَّوْتَ وَبِمَا رَآهُ قَبْلَ عَمَاهُ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"da147","title":"بَابُ مَوَانِعِ الشَّهَادَةِ","units":[{"id":"da147_1","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ١","segs":[["matn","وَهِيَ سِتَّةٌ: أَحَدُهَا: كَوْنُ الشَّاهِدِ أَوْ بَعْضِهِ مِلْكًا لِمَنْ شَهِدَ لَهُ وَكَذَا لَوْ كَانَ زَوْجًا لَهُ وَلَوْ فِي الْمَاضِي أَوْ كَانَ مِنْ فُرُوعِهِ وَإِنْ سَفَلُوا مِنْ وَلَدِ الْبَنِينَ وَالْبَنَاتِ أَوْ مِنْ أُصُولِهِ وَإِنْ عَلَوْا وَتُقْبَلُ لِبَاقِي أَقَارِبِهِ:"]]},{"id":"da147_2","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٢","segs":[["matn","كَأَخِيهِ وَكُلُّ مَنْ لَا تُقْبَلُ لَهُ فَإِنَّهَا تُقْبَلُ عَلَيْهِ."]]},{"id":"da147_3","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٣","segs":[["matn","الثَّانِي: كَوْنُهُ يَجُرُّ بِهَا نَفْعًا لِنَفْسِهِ فَلَا تُقْبَلُ شَهَادَتُهُ لِرَقِيقِهِ وَمُكَاتَبِهِ وَلَا لِمُوَرِّثِهِ بِجُرْحٍ قَبْلَ انْدِمَالِهِ وَلَا لِشَرِيكِهِ فِيمَا هُوَ شَرِيكٌ فِيهِ وَلَا لِمُسْتَأْجِرِهِ فِيمَا اسْتَأْجَرَهُ فِيهِ."]]},{"id":"da147_4","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٤","segs":[["matn","الثَّالِثُ: أَنْ يَدْفَعَ بِهَا ضَرَرًا عَنْ نَفْسِهِ: فَلَا تُقْبَلُ شَهَادَةُ الْعَاقِلَةِ بِجَرْحِ شُهُودِ قَتْلِ الْخَطَأِ وَلَا شَهَادَةُ الْغُرَمَاءِ بِجَرْحِ شُهُودِ دَيْنٍ عَلَى مُفْلِسٍ"]]},{"id":"da147_5","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٥","segs":[["matn","وَلَا شَهَادَةُ الضَّامِنِ لِمَنْ ضَمِنَهُ بِقَضَاءِ الْحَقِّ أَوِ الْإِبْرَاءِ مِنْهُ وَكُلُّ مَنْ لَا تُقْبَلُ شَهَادَتُهُ لَهُ لَا تُقْبَلُ شَهَادَتُهُ بِجَرْحِ شَاهِدٍ عَلَيْهِ."]]},{"id":"da147_6","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٦","segs":[["matn","الرَّابِعُ: الْعَدَاوَةُ لِغَيْرِ اللَّهِ تَعَالَى: كَفَرَحِهِ بِمَسَاءَتِهِ أَوْ غَمِّهِ لِفَرَحِهِ وَطَلَبِهِ لَهُ الشَّرَّ فَلَا تُقْبَلُ شَهَادَتُهُ عَلَى عَدُوِّهِ إِلَّا فِي عَقْدِ النِّكَاحِ."]]},{"id":"da147_7","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٧","segs":[["matn","الْخَامِسُ: الْعَصَبِيَّةُ: فَلَا شَهَادَةَ لِمَنْ عُرِفَ بِهَا كَتَعَصُّبِ جَمَاعَةٍ عَلَى جَمَاعَةٍ وَإِنْ لَمْ تَبْلُغْ رُتْبَةَ الْعَدَاوَةِ."]]},{"id":"da147_8","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٨","segs":[["matn","السَّادِسُ: أَنْ تُرَدَّ شَهَادَتُهُ لِفِسْقِهِ ثُمَّ يَتُوبُ وَيُعِيدُهَا أَوْ يَشْهَدَ لِمُوَرِّثِهِ بِجُرْحٍ قَبْلَ بُرْئِهِ ثُمَّ يَبْرَأُ وَيُعِيدُهَا أَوْ تُرَدَّ لِدَفْعِ ضَرَرٍ أَوْ جَلْبِ نَفْعٍ أَوْ عَدَاوَةٍ أَوْ مِلْكٍ أَوْ زَوْجِيَّةٍ"]]},{"id":"da147_9","label":"بَابُ مَوَانِعِ الشَّهَادَةِ · ٩","segs":[["matn","ثُمَّ يَزُولُ ذَلِكَ وَتُعَادُ فَلَا تُقْبَلُ فِي الْجَمِيعِ بِخِلَافِ مَا لَوْ شَهِدَ وَهُوَ كَافِرٌ أَوْ غَيْرُ مُكَلَّفٍ أَوْ أَخْرَسُ ثُمَّ زَالَ ذَلِكَ وَأَعَادُوهَا."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"da148","title":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ","units":[{"id":"da148_1","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ١","segs":[["matn","وَهُوَ سِتَّةٌ: أَحَدُهَا: الزِّنَا: فَلَا بُدَّ مِنْ أَرْبَعَةِ رِجَالٍ يَشْهَدُونَ بِهِ وَأَنَّهُمْ رَأَوْا ذَكَرَهُ فِي فَرْجِهَا أَوْ يَشْهَدُونَ أَنَّهُ أَقَرَّ أَرْبَعًا."]]},{"id":"da148_2","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٢","segs":[["matn","الثَّانِي: إِذَا ادَّعَى مَنْ عُرِفَ بِغِنًى أَنَّهُ فَقِيرٌ لِيَأْخُذَ مِنَ الزَّكَاةِ: فَلَا بُدَّ مِنْ ثَلَاثَةِ رِجَالٍ."]]},{"id":"da148_3","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٣","segs":[["matn","الثَّالِثُ: الْقَوَدُ وَالْإِعْسَارُ وَمَا يُوجِبُ الْحَدَّ وَالتَّعْزِيرَ: فَلَا بُدَّ مِنْ رَجُلَيْنِ وَمِثْلُهُ: النِّكَاحُ وَالرَّجْعَةُ وَالْخُلْعُ وَالطَّلَاقُ وَالنَّسَبُ وَالْوَلَاءُ وَالتَّوْكِيلُ فِي غَيْرِ الْمَالِ."]]},{"id":"da148_4","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٤","segs":[["matn","الرَّابِعُ: الْمَالُ وَمَا يُقْصَدُ بِهِ الْمَالُ: كَالْقَرْضِ وَالرَّهْنِ وَالْوَصِيَّةِ وَالْعِتْقِ وَالتَّدْبِيرِ وَالْوَقْفِ وَالْبَيْعِ وَجِنَايَةِ الْخَطَأِ فَيَكْفِي فِيهِ رَجُلَانِ أَوْ رَجُلٌ وَامْرَأَتَانِ أَوْ رَجُلٌ وَيَمِينٌ لَا امْرَأَتَانِ وَيَمِينٌ وَلَوْ كَانَ لِجَمَاعَةٍ حَقٌّ بِشَاهِدٍ فَأَقَامُوهُ:"]]},{"id":"da148_5","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٥","segs":[["matn","فَمَنْ حَلَفَ أَخَذَ نَصِيبَهُ وَلَا يُشَارِكُهُ مَنْ لَمْ يَحْلِفْ. الْخَامِسُ: دَاءُ دَابَّةٍ وَمُوضِحَةٌ وَنَحْوُهُمَا: فَيُقْبَلُ قَوْلُ طَبِيبٍ وَبَيْطَارٍ وَاحِدٍ لِعَدَمِ غَيْرِهِ فِي مَعْرِفَتِهِ وَإِنِ اخْتَلَفَ اثْنَانِ قُدِّمَ قَوْلُ الْمُثْبِتِ."]]},{"id":"da148_6","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٦","segs":[["matn","السَّادِسُ: مَا لَا يَطَّلِعُ عَلَيْهِ الرِّجَالُ غَالِبًا كَعُيُوبِ النِّسَاءِ تَحْتَ الثِّيَابِ وَالرَّضَاعِ وَالْبَكَارَةِ وَالثُّيُوبَةِ وَالْحَيْضِ وَكَذَا جِرَاحَةٌ وَغَيْرُهَا فِي حَمَّامٍ وَعُرْسٍ وَنَحْوِهِمَا مِمَّا لَا يَحْضُرُهُ الرِّجَالُ فَيَكْفِي فِيهِ امْرَأَةٌ عَدْلٌ وَالْأَحْوَطُ: اثْنَتَانِ."]]},{"id":"da148_7","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٧","segs":[["matn","فَصْلٌ: فَلَوْ شَهِدَ بِقَتْلِ الْعَمْدِ رَجُلٌ وَامْرَأَتَانِ لَمْ يَثْبُتْ شَيْءٌ وَإِنْ شَهِدُوا بِسَرِقَةٍ: ثَبَتَ الْمَالُ دُونَ الْقَطْعِ."]]},{"id":"da148_8","label":"بَابُ أَقْسَامِ الْمَشْهُودِ بِهِ · ٨","segs":[["matn","وَمَنْ حَلَفَ بِالطَّلَاقِ أَنَّهُ مَا سَرَقَ أَوْ مَا غَصَبَ وَنَحْوَهُ فَثَبَتَ فِعْلُهُ بِرَجُلٍ وَامْرَأَتَيْنِ أَوْ رَجُلٍ وَيَمِينٍ: ثَبَتَ الْمَالُ وَلَمْ تَطْلُقْ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"da149","title":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا","units":[{"id":"da149_1","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ١","segs":[["matn","الشَّهَادَةُ عَلَى الشَّهَادَةِ أَنْ يَقُولَ: اشْهَدْ يَا فُلَانُ عَلَى شَهَادَتِي: أَنِّي أَشْهَدُ أَنَّ فُلَانَ بْنَ فُلَانٍ أَشْهَدَنِي عَلَى نَفْسِهِ أَوْ شَهِدْتُ عَلَيْهِ أَوْ أَقَرَّ عِنْدِي بِكَذَا."]]},{"id":"da149_2","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٢","segs":[["matn","وَيَصِحُّ: أَنْ يَشْهَدَ عَلَى شَهَادَةِ الرَّجُلَيْنِ رَجُلٌ وَامْرَأَتَانِ وَرَجُلٌ وَامْرَأَتَانِ عَلَى مِثْلِهِمْ وَامْرَأَةٌ عَلَى امْرَأَةٍ فِيمَا تُقْبَلُ فِيهِ الْمَرْأَةُ. وَشُرُوطُهَا أَرْبَعَةٌ: أَحَدُهَا: أَنْ تَكُونَ فِي حُقُوقِ الْآدَمِيِّينَ."]]},{"id":"da149_3","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٣","segs":[["matn","الثَّانِي: تَعَذُّرُ شُهُودِ الْأَصْلِ بِمَوْتٍ أَوْ مَرَضٍ أَوْ غَيْبَةٍ مَسَافَةَ قَصْرٍ وَيَدُومَ تَعَذُّرُهُمْ إِلَى صُدُورِ الْحُكْمِ فَمَتَى أَمْكَنَتْ شَهَادَةُ الْأَصْلِ وُقِفَ الْحُكْمُ عَلَى سَمَاعِهَا."]]},{"id":"da149_4","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٤","segs":[["matn","الثَّالِثُ: دَوَامُ عَدَالَةِ الْأَصْلِ وَالْفَرْعِ إِلَى صُدُورِ الْحُكْمِ فَمَتَى حَدَثَ مِنْ أَحَدِهِمْ قَبْلَهُ مَا يَمْنَعُهُ وُقِفَ."]]},{"id":"da149_5","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٥","segs":[["matn","الرَّابِعُ: ثُبُوتُ عَدَالَةِ الْجَمِيعِ وَيَصِحُّ: مِنَ الْفَرْعِ أَنْ يُعَدِّلَ الْأَصْلَ لَا تَعْدِيلُ شَاهِدٍ لِرَفِيقِهِ وَإِنْ قَالَ شُهُودُ الْأَصْلِ بَعْدَ الْحُكْمِ بِشَهَادَةِ الْفَرْعِ: مَا أَشْهَدْنَاهُمْ بِشَيْءٍ لَمْ يَضْمَنِ الْفَرِيقَانِ شَيْئًا."]]},{"id":"da149_6","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٦","segs":[["matn","فَصْلٌ: وَلَا تُقْبَلُ الشَّهَادَةُ إِلَّا بِأَشْهَدُ أَوْ شَهِدْتُ فَلَا يَكْفِي أَنَا شَاهِدٌ وَلَا أَعْلَمُ أَوْ أُحِقُّ أَوْ أَشْهَدُ بِمَا وَضَعْتُ بِهِ خَطِّي لَكِنْ لَوْ قَالَ مَنْ تَقَدَّمَهُ غَيْرُهُ بِالشَّهَادَةِ: بِذَلِكَ أَشْهَدُ أَوْ كَذَلِكَ صَحَّ."]]},{"id":"da149_7","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٧","segs":[["matn","وَإِذَا رَجَعَ شُهُودُ الْمَالِ أَوِ الْعِتْقِ بَعْدَ حُكْمِ الْحَاكِمِ: لَمْ يُنْقَضْ وَيَضْمَنُونَ."]]},{"id":"da149_8","label":"بَابُ الشَّهَادَةِ عَلَى الشَّهَادَةِ وَصِفَةِ أَدَائِهَا · ٨","segs":[["matn","وَإِذَا عَلِمَ الْحَاكِمُ بِشَاهِدِ زُورٍ بِإِقْرَارِهِ أَوْ تَبَيُّنِ كَذِبِهِ يَقِينًا: عَزَّرَهُ وَلَوْ تَابَ بِمَا يَرَاهُ مَا لَمْ يُخَالِفْ نَصًّا وَطِيفَ بِهِ فِي الْمَوَاضِعِ الَّتِي يَشْتَهِرُ فِيهَا فَيُقَالُ: إِنَّا وَجَدْنَاهُ شَاهِدَ زُورٍ فَاجْتَنِبُوهُ."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"da150","title":"بَابُ الْيَمِينِ فِي الدَّعَاوَى","units":[{"id":"da150_1","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ١","segs":[["matn","الْبَيِّنَةُ عَلَى الْمُدَّعِي وَالْيَمِينُ عَلَى مَنْ أَنْكَرَ. وَلَا يَمِينَ عَلَى مُنْكِرٍ ادُّعِيَ عَلَيْهِ بِحَقِّ اللَّهِ تَعَالَى كَالْحَدِّ وَلَوْ قَذْفًا، وَالتَّعْزِيرِ وَالْعِبَادَةِ وَإِخْرَاجِ الصَّدَقَةِ وَالْكَفَّارَةِ وَالنَّذْرِ وَلَا عَلَى شَاهِدٍ أَنْكَرَ شَهَادَتَهُ وَحَاكِمٍ أَنْكَرَ حُكْمَهُ."]]},{"id":"da150_2","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٢","segs":[["matn","وَيَحْلِفُ الْمُنْكِرُ فِي كُلِّ حَقِّ آدَمِيٍّ يُقْصَدُ مِنْهُ الْمَالُ: كَالدُّيُونِ وَالْجِنَايَاتِ وَالْإِتْلَافَاتِ. فَإِنْ نَكَلَ عَنِ الْيَمِينِ قُضِيَ عَلَيْهِ بِالْحَقِّ."]]},{"id":"da150_3","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٣","segs":[["matn","وَإِذَا حَلَفَ عَلَى نَفْيِ فِعْلِ نَفْسِهِ أَوْ نَفْيِ دَيْنٍ عَلَيْهِ: حَلَفَ عَلَى الْبَتِّ وَإِنْ حَلَفَ عَلَى نَفْيِ دَعْوَى عَلَى غَيْرِهِ: كَمُوَرِّثِهِ وَرَقِيقِهِ وَمُوَلِّيهِ حَلَفَ عَلَى نَفْيِ الْعِلْمِ وَمَنْ أَقَامَ شَاهِدًا بِمَا ادَّعَاهُ: حَلَفَ مَعَهُ عَلَى الْبَتِّ."]]},{"id":"da150_4","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٤","segs":[["matn","وَمَنْ تَوَجَّهَ عَلَيْهِ حَلِفٌ لِجَمَاعَةٍ: حَلَفَ لِكُلِّ وَاحِدٍ يَمِينًا مَا لَمْ يَرْضَوْا بِوَاحِدَةٍ."]]},{"id":"da150_5","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٥","segs":[["matn","فَصْلٌ: وَلِلْحَاكِمِ تَغْلِيظُ الْيَمِينِ فِيمَا لَهُ خَطَرٌ كَجِنَايَةٍ لَا تُوجِبُ قَوَدًا وَعِتْقٍ وَمَالٍ كَثِيرٍ قَدْرَ نِصَابِ الزَّكَاةِ."]]},{"id":"da150_6","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٦","segs":[["matn","فَتَغْلِيظُ يَمِينِ الْمُسْلِمِ أَنْ يَقُولَ: وَاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ عَالِمِ الْغَيْبِ وَالشَّهَادَةِ الرَّحْمَنِ الرَّحِيمِ الطَّالِبِ الْغَالِبِ الضَّارِّ النَّافِعِ الَّذِي يَعْلَمُ خَائِنَةَ الْأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ."]]},{"id":"da150_7","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٧","segs":[["matn","وَيَقُولُ الْيَهُودِيُّ: وَاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى وَفَلَقَ لَهُ الْبَحْرَ وَأَنْجَاهُ مِنْ فِرْعَوْنَ وَمَلَئِهِ وَيَقُولُ النَّصْرَانِيُّ: وَاللَّهِ الَّذِي أَنْزَلَ الْإِنْجِيلَ عَلَى عِيسَى وَجَعَلَهُ يُحْيِي الْمَوْتَى وَيُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ وَمَنْ أَبَى التَّغْلِيظَ لَمْ يَكُنْ نَاكِلًا."]]},{"id":"da150_8","label":"بَابُ الْيَمِينِ فِي الدَّعَاوَى · ٨","segs":[["matn","وَإِنْ رَأَى الْحَاكِمُ تَرْكَ التَّغْلِيظِ فَتَرَكَهُ كَانَ مُصِيبًا."]]}],"group":"كِتَابُ الشَّهَادَاتِ"},{"id":"da151","title":"كِتَابُ الْإِقْرَارِ","units":[{"id":"da151_1","label":"كِتَابُ الْإِقْرَارِ · ١","segs":[["matn","لَا يَصِحُّ الْإِقْرَارُ إِلَّا مِنْ مُكَلَّفٍ مُخْتَارٍ وَلَوْ هَازِلًا بِلَفْظٍ أَوْ كِتَابَةٍ لَا بِإِشَارَةٍ إِلَّا مِنْ أَخْرَسَ."]]},{"id":"da151_2","label":"كِتَابُ الْإِقْرَارِ · ٢","segs":[["matn","لَكِنْ لَوْ أَقَرَّ صَغِيرٌ أَوْ قِنٌّ أُذِنَ لَهُمَا فِي تِجَارَةٍ فِي قَدْرِ مَا أُذِنَ لَهُمَا فِيهِ: صَحَّ. وَمَنْ أُكْرِهَ لِيُقِرَّ بِدِرْهَمٍ فَأَقَرَّ بِدِينَارٍ أَوْ لِيُقِرَّ لِزَيْدٍ فَأَقَرَّ لِعَمْرٍو: صَحَّ وَلَزِمَهُ."]]},{"id":"da151_3","label":"كِتَابُ الْإِقْرَارِ · ٣","segs":[["matn","وَلَيْسَ الْإِقْرَارُ بِإِنْشَاءِ تَمْلِيكٍ فَيَصِحُّ حَتَّى مَعَ إِضَافَةِ الْمِلْكِ لِنَفْسِهِ كَقَوْلِهِ: كِتَابِي هَذَا لِزَيْدٍ."]]},{"id":"da151_4","label":"كِتَابُ الْإِقْرَارِ · ٤","segs":[["matn","وَيَصِحُّ إِقْرَارُ الْمَرِيضِ بِمَالٍ لِغَيْرِ وَارِثٍ وَيَكُونُ مِنْ رَأْسِ الْمَالِ وَبِأَخْذِ دَيْنٍ مِنْ غَيْرِ وَارِثٍ لَا إِنْ أَقَرَّ لِوَارِثٍ إِلَّا بِبَيِّنَةٍ."]]},{"id":"da151_5","label":"كِتَابُ الْإِقْرَارِ · ٥","segs":[["matn","وَالِاعْتِبَارُ بِكَوْنِ مَنْ أَقَرَّ لَهُ وَارِثًا أَوْ لَا حَالَةَ الْإِقْرَارِ لَا الْمَوْتِ عَكْسَ الْوَصِيَّةِ. وَإِنْ كَذَّبَ الْمُقَرُّ لَهُ الْمُقِرَّ بَطَلَ الْإِقْرَارُ وَكَانَ لِلْمُقِرِّ أَنْ يَتَصَرَّفَ فِيمَا أَقَرَّ بِهِ بِمَا شَاءَ."]]},{"id":"da151_6","label":"كِتَابُ الْإِقْرَارِ · ٦","segs":[["matn","فَصْلٌ: وَالْإِقْرَارُ لِقِنِّ غَيْرِهِ إِقْرَارٌ لِسَيِّدِهِ وَلِمَسْجِدٍ أَوْ مَقْبَرَةٍ أَوْ طَرِيقٍ وَنَحْوِهِ يَصِحُّ وَلَوْ أَطْلَقَ."]]},{"id":"da151_7","label":"كِتَابُ الْإِقْرَارِ · ٧","segs":[["matn","وَلِدَارٍ أَوْ بَهِيمَةٍ: لَا إِلَّا إِنْ عَيَّنَ السَّبَبَ وَلِحَمْلٍ فَإِنْ وُلِدَ مَيِّتًا أَوْ لَمْ يَكُنْ حَمْلٌ: بَطَلَ وَحَيًّا فَأَكْثَرَ: فَلَهُ بِالسَّوِيَّةِ."]]},{"id":"da151_8","label":"كِتَابُ الْإِقْرَارِ · ٨","segs":[["matn","وَإِنْ أَقَرَّ رَجُلٌ أَوِ امْرَأَةٌ بِزَوْجِيَّةِ الْآخَرِ فَسَكَتَ أَوْ جَحَدَ ثُمَّ صَدَّقَهُ: صَحَّ وَوَرِثَهُ لَا إِنْ بَقِيَ عَلَى تَكْذِيبِهِ حَتَّى مَاتَ."]]}],"group":"كِتَابُ الْإِقْرَارِ"},{"id":"da152","title":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ","units":[{"id":"da152_1","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ١","segs":[["matn","مَنِ ادُّعِيَ عَلَيْهِ بِأَلْفٍ فَقَالَ: نَعَمْ أَوْ صَدَقْتَ أَوْ: أَنَا مُقِرٌّ أَوْ: خُذْهَا أَوْ: اتَّزِنْهَا أَوِ اقْبِضْهَا: فَقَدْ أَقَرَّ لَا إِنْ قَالَ: أَنَا أُقِرُّ أَوْ: لَا أُنْكِرُ أَوْ: خُذْ أَوْ: اتَّزِنْ أَوْ: افْتَحْ كُمَّكَ."]]},{"id":"da152_2","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٢","segs":[["matn","وَبَلَى فِي جَوَابِ أَلَيْسَ لِي عَلَيْكَ كَذَا إِقْرَارٌ لَا: نَعَمْ إِلَّا مِنْ عَامِّيٍّ. وَإِنْ قَالَ: اقْضِ دَيْنِي عَلَيْكَ أَلْفًا أَوْ: هَلْ لِي: أَوْ لِي عَلَيْكَ أَلْفٌ؟"]]},{"id":"da152_3","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٣","segs":[["matn","فَقَالَ: نَعَمْ أَوْ قَالَ: أَمْهِلْنِي يَوْمًا أَوْ حَتَّى أَفْتَحَ الصُّنْدُوقَ أَوْ قَالَ: لَهُ عَلَيَّ أَلْفٌ إِنْ شَاءَ اللَّهُ أَوْ: إِلَّا أَنْ يَشَاءَ اللَّهُ أَوْ زَيْدٌ: فَقَدْ أَقَرَّ."]]},{"id":"da152_4","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٤","segs":[["matn","وَإِنْ عَلَّقَ بِشَرْطٍ لَمْ يَصِحَّ سَوَاءٌ قَدَّمَ الشَّرْطَ كَإِنْ شَاءَ زَيْدٌ فَلَهُ عَلَيَّ دِينَارٌ أَوْ أَخَّرَهُ كَلَهُ عَلَيَّ دِينَارٌ إِنْ شَاءَ زَيْدٌ أَوْ:"]]},{"id":"da152_5","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٥","segs":[["matn","قَدِمَ الْحَاجُّ إِلَّا إِذَا قَالَ: عَلَيَّ كَذَا إِذَا جَاءَ وَقْتُ كَذَا فَلَهُ عَلَيَّ دِينَارٌ: فَيَلْزَمُهُ فِي الْحَالِ فَإِنْ فَسَّرَهُ بِأَجَلٍ أَوْ وَصِيَّةٍ: قُبِلَ بِيَمِينِهِ."]]},{"id":"da152_6","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٦","segs":[["matn","وَمَنِ ادُّعِيَ عَلَيْهِ بِدِينَارٍ فَقَالَ: إِنْ شَهِدَ بِهِ زَيْدٌ فَهُوَ صَادِقٌ: لَمْ يَكُنْ مُقِرًّا."]]},{"id":"da152_7","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٧","segs":[["matn","فَصْلٌ فِيمَا إِذَا وَصَلَ بِالْإِقْرَارِ مَا يُغَيِّرُهُ: إِذَا قَالَ: لَهُ عَلَيَّ مِنْ ثَمَنِ خَمْرٍ أَلْفٌ لَمْ يَلْزَمْهُ شَيْءٌ وَإِنْ قَالَ: أَلْفٌ مِنْ ثَمَنِ خَمْرٍ لَزِمَهُ."]]},{"id":"da152_8","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٨","segs":[["matn","وَيَصِحُّ اسْتِثْنَاءُ النِّصْفِ فَأَقَلَّ فَيَلْزَمُهُ عَشَرَةٌ فِي: لَهُ عَلَيَّ عَشَرَةٌ إِلَّا سِتَّةً وَخَمْسَةٌ فِي:"]]},{"id":"da152_9","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ٩","segs":[["matn","لَيْسَ لَكَ عَلَيَّ عَشَرَةٌ إِلَّا خَمْسَةً بِشَرْطِ أَنْ لَا يَسْكُتَ مَا يُمْكِنُهُ الْكَلَامُ فِيهِ وَأَنْ يَكُونَ مِنَ الْجِنْسِ وَالنَّوْعِ فَلَهُ عَلَيَّ هَؤُلَاءِ الْعَبِيدُ الْعَشَرَةُ إِلَّا وَاحِدًا صَحِيحٌ وَيَلْزَمُهُ تِسْعَةٌ وَلَهُ عَلَيَّ مِائَةُ دِرْهَمٍ إِلَّا دِينَارًا:"]]},{"id":"da152_10","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ١٠","segs":[["matn","تَلْزَمُهُ الْمِائَةُ وَلَهُ هَذِهِ الدَّارُ إِلَّا هَذَا الْبَيْتَ قُبِلَ وَلَوْ كَانَ أَكْثَرَهَا لَا إِنْ قَالَ: إِلَّا ثُلُثَيْهَا وَنَحْوَهُ وَلَهُ الدَّارُ ثُلُثَاهَا أَوْ عَارِيَّةً أَوْ هِبَةً عُمِلَ بِالثَّانِي."]]},{"id":"da152_11","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ١١","segs":[["matn","فَصْلٌ: وَمَنْ بَاعَ أَوْ وَهَبَ أَوْ أَعْتَقَ عَبْدًا ثُمَّ أَقَرَّ بِهِ لِغَيْرِهِ لَمْ يُقْبَلْ وَيَغْرَمُهُ لِلْمُقَرِّ لَهُ."]]},{"id":"da152_12","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ١٢","segs":[["matn","وَإِنْ قَالَ: غَصَبْتُ هَذَا الْعَبْدَ مِنْ زَيْدٍ لَا بَلْ مِنْ عَمْرٍو أَوْ: مِلْكُهُ لِعَمْرٍو وَغَصَبْتُهُ مِنْ زَيْدٍ: فَهُوَ لِزَيْدٍ وَيَغْرَمُ قِيمَتَهُ لِعَمْرٍو وَ:غَصَبْتُهُ مِنْ زَيْدٍ وَمِلْكُهُ لِعَمْرٍو: فَهُوَ لِزَيْدٍ وَلَا يَغْرَمُ لِعَمْرٍو شَيْئًا."]]},{"id":"da152_13","label":"بَابُ مَا يَحْصُلُ بِهِ الْإِقْرَارُ وَمَا يُغَيِّرُهُ · ١٣","segs":[["matn","وَمَنْ خَلَّفَ ابْنَيْنِ وَمِائَتَيْنِ فَادَّعَى شَخْصٌ مِائَةَ دِينَارٍ عَلَى الْمَيِّتِ فَصَدَّقَهُ أَحَدُهُمَا وَأَنْكَرَ الْآخَرُ: لَزِمَ الْمُقِرَّ نِصْفُهَا إِلَّا أَنْ يَكُونَ عَدْلًا وَيَشْهَدَ وَيَحْلِفَ مَعَهُ الْمُدَّعِي فَيَأْخُذُهَا وَتَكُونُ الْبَاقِيَةُ بَيْنَ الِابْنَيْنِ."]]}],"group":"كِتَابُ الْإِقْرَارِ"},{"id":"da153","title":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ","units":[{"id":"da153_1","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ١","segs":[["matn","إِذَا قَالَ: لَهُ عَلَيَّ شَيْءٌ وَشَيْءٌ أَوْ كَذَا وَكَذَا قِيلَ لَهُ: فَسِّرْهُ فَإِنْ أَبَى حُبِسَ حَتَّى يُفَسِّرَ وَيُقْبَلُ تَفْسِيرُهُ بِأَقَلِّ مُتَمَوَّلٍ فَإِنْ مَاتَ قَبْلَ التَّفْسِيرِ: لَمْ يُؤَاخَذْ وَارِثُهُ بِشَيْءٍ."]]},{"id":"da153_2","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٢","segs":[["matn","وَ: لَهُ عَلَيَّ مَالٌ عَظِيمٌ أَوْ خَطِيرٌ أَوْ كَثِيرٌ أَوْ جَلِيلٌ أَوْ نَفِيسٌ قُبِلَ تَفْسِيرُهُ بِأَقَلِّ مُتَمَوَّلٍ. وَ: لَهُ دَرَاهِمُ كَثِيرَةٌ قُبِلَ بِثَلَاثَةٍ."]]},{"id":"da153_3","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٣","segs":[["matn","وَ: لَهُ عَلَيَّ كَذَا كَذَا دِرْهَمْ بِالرَّفْعِ أَوْ بِالنَّصْبِ لَزِمَهُ دِرْهَمٌ وَإِنْ قَالَ: بِالْجَرِّ أَوْ: وَقَفَ عَلَيْهِ: لَزِمَهُ بَعْضُ دِرْهَمٍ وَيُفَسِّرُهُ."]]},{"id":"da153_4","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٤","segs":[["matn","وَلَهُ عَلَيَّ أَلْفٌ وَدِرْهَمٌ، أَوْ أَلْفٌ وَدِينَارٌ، أَوْ أَلْفٌ وَثَوْبٌ أَوْ: أَلْفٌ إِلَّا دِينَارًا، كَانَ الْمُبْهَمُ مِنْ جِنْسِ الْمُعَيَّنِ"]]},{"id":"da153_5","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٥","segs":[["matn","فَصْلٌ: إِذَا قَالَ: لَهُ عَلَيَّ مَا بَيْنَ دِرْهَمٍ وَعَشَرَةٍ لَزِمَهُ ثَمَانِيَةٌ وَ: مِنْ دِرْهَمٍ إِلَى عَشَرَةٍ أَوْ مَا: بَيْنَ دِرْهَمٍ إِلَى عَشَرَةٍ لَزِمَهُ: تِسْعَةٌ."]]},{"id":"da153_6","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٦","segs":[["matn","وَ: لَهُ دِرْهَمٌ قَبْلَهُ دِرْهَمٌ وَبَعْدَهُ دِرْهَمٌ أَوْ: دِرْهَمٌ وَدِرْهَمٌ، وَدِرْهَمٌ لَزِمَهُ ثَلَاثَةٌ وَكَذَا: دِرْهَمٌ، دِرْهَمٌ، دِرْهَمٌ فَإِنْ أَرَادَ التَّأْكِيدَ: فَعَلَى مَا أَرَادَ. وَ: لَهُ دِرْهَمٌ بَلْ دِينَارٌ لَزِمَاهُ."]]},{"id":"da153_7","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٧","segs":[["matn","وَ: لَهُ دِرْهَمٌ فِي دِينَارٍ لَزِمَهُ: دِرْهَمٌ فَإِنْ قَالَ: أَرَدْتُ الْعَطْفَ أَوْ مَعْنَى مَعَ لَزِمَاهُ."]]},{"id":"da153_8","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٨","segs":[["matn","وَ: لَهُ دِرْهَمٌ فِي عَشَرَةٍ لَزِمَهُ: دِرْهَمٌ مَا لَمْ يُخَالِفْهُ عُرْفٌ فَيَلْزَمُهُ: مُقْتَضَاهُ أَوْ يُرِدِ الْحِسَابَ وَلَوْ جَاهِلًا بِهِ: فَيَلْزَمُهُ عَشَرَةٌ أَوْ يُرِدِ الْجَمِيعَ: فَيَلْزَمُهُ أَحَدَ عَشَرَ."]]},{"id":"da153_9","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ٩","segs":[["matn","وَ: لَهُ تَمْرٌ فِي جِرَابٍ أَوْ سَيْفٌ فِي قِرَابٍ أَوْ ثَوْبٌ فِي مِنْدِيلٍ لَيْسَ إِقْرَارًا بِالثَّانِي وَلَهُ خَاتَمٌ فِيهِ فَصٌّ أَوْ سَيْفٌ بِقِرَابٍ إِقْرَارٌ بِهِمَا."]]},{"id":"da153_10","label":"بَابُ الْإِقْرَارِ بِالْمُجْمَلِ · ١٠","segs":[["matn","وَإِقْرَارُهُ بِشَجَرَةٍ لَيْسَ إِقْرَارًا بِأَرْضِهَا فَلَا يَمْلِكُ غَرْسَ مَكَانِهَا لَوْ ذَهَبَتْ وَلَا أُجْرَةَ مَا بَقِيَتْ. وَ: لَهُ عَلَيَّ دِرْهَمٌ أَوْ: دِينَارٌ يَلْزَمُهُ: أَحَدُهُمَا وَيُعَيِّنُهُ."]]}],"group":"كِتَابُ الْإِقْرَارِ"},{"id":"da154","title":"خَاتِمَةٌ","units":[{"id":"da154_1","label":"خَاتِمَةٌ · ١","segs":[["matn","إِذَا اتَّفَقَا عَلَى عَقْدٍ وَادَّعَى أَحَدُهُمَا فَسَادَهُ وَالْآخَرُ صِحَّتَهُ فَقَوْلُ مُدَّعِي الصِّحَّةِ بِيَمِينِهِ. وَإِنِ ادَّعَيَا شَيْئًا بِيَدِ غَيْرِهِمَا شَرِكَةً بَيْنَهُمَا بِالسَّوِيَّةِ فَأَقَرَّ لِأَحَدِهِمَا بِنِصْفِهِ: فَالْمُقَرُّ بِهِ بَيْنَهُمَا."]]},{"id":"da154_2","label":"خَاتِمَةٌ · ٢","segs":[["matn","وَمَنْ قَالَ بِمَرَضِ مَوْتِهِ: هَذَا الْأَلْفُ لُقَطَةٌ فَتَصَدَّقُوا بِهِ وَلَا مَالَ لَهُ غَيْرُهُ: لَزِمَ الْوَرَثَةَ الصَّدَقَةُ بِجَمِيعِهِ وَلَوْ كَذَّبُوهُ."]]},{"id":"da154_3","label":"خَاتِمَةٌ · ٣","segs":[["matn","وَيُحْكَمُ بِإِسْلَامِ مَنْ أَقَرَّ وَلَوْ مُمَيِّزًا أَوْ قُبَيْلَ مَوْتِهِ بِشَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ."]]},{"id":"da154_4","label":"خَاتِمَةٌ · ٤","segs":[["matn","اللَّهُمَّ اجْعَلْنِي مِمَّنْ أَقَرَّ بِهَا مُخْلِصًا فِي حَيَاتِهِ وَعِنْدَ مَمَاتِهِ وَبَعْدَ وَفَاتِهِ وَاجْعَلِ اللَّهُمَّ هَذَا خَالِصًا لِوَجْهِكَ الْكَرِيمِ وَسَبَبًا لِلْفَوْزِ لَدَيْكَ بِجَنَّاتِ النَّعِيمِ."]]},{"id":"da154_5","label":"خَاتِمَةٌ · ٥","segs":[["matn","وَصَلَّى اللَّهُ وَسَلَّمَ عَلَى أَشْرَفِ الْعَالَمِ وَسَيِّدِ بَنِي آدَمَ وَعَلَى سَائِرِ إِخْوَانِهِ مِنَ النَّبِيِّينَ وَالْمُرْسَلِينَ وَعَلَى آلِ كُلٍّ وَصَحْبِهِ أَجْمَعِينَ وَعَلَى أَهْلِ طَاعَتِكَ مِنْ أَهْلِ السَّمَاوَاتِ وَالْأَرَضِينَ."]]},{"id":"da154_6","label":"خَاتِمَةٌ · ٦","segs":[["matn","الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ. فَلَهُ الْحَمْدُ حَتَّى يَرْضَى وَلَهُ الْحَمْدُ عَلَى كُلِّ حَالٍ وَالْحَمْدُ لِلَّهِ وَحْدَهُ."]]}],"group":"كِتَابُ الْإِقْرَارِ"}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
